  at timestamp with time zone DEFAULT now() NOT NULL,
  direction text NOT NULL,
  body text,
  media_url text,
  media_kind text,
  transcript text,
  transcript_source text,
  intent_key text,
  answered_by text,
  fact_pack jsonb,
