    when p_category ~* 'fire|safety|sprinkler|extinguisher|civil.?defen' then 'fire'
    when p_category ~* 'scaffold' then 'scaffolding'
    when p_category ~* 'demolition|strip.?out' then 'demolition'
    when p_category ~* 'garage.?door|shutter|rolling' then 'shutters'
    when p_category ~* 'elevator|escalator|^lift|lifts' then 'elevators'
    when p_category ~* 'generator' then 'generators'
    when p_category ~* 'solar|photovolt|shams' then 'solar'
    when p_category ~* 'swimming|pool' then 'pools'
    when p_category ~* 'tent|shade|pergola|awning|gazebo' then 'shade'
    when p_category ~* 'landscap|garden|softscape|hardscape|irrigation' then 'landscaping'
    when p_category ~* 'pest' then 'pestcontrol'
    when p_category ~* 'mover|moving|relocation|packing' then 'movers'
    when p_category ~* 'upholstery|curtain|blind|sofa' then 'upholstery'
    when p_category ~* 'wallpaper|wall covering' then 'wallpaper'
    when p_category ~* 'carpet' then 'carpet'
    when p_category ~* 'tiling|tile|marble|granite' then 'tiling'
    when p_category ~* 'floor|spc|vinyl|lvt|epoxy.?floor|parquet|laminate' then 'flooring'
    when p_category ~* 'paint' then 'painting'
    when p_category ~* 'gypsum|false.?ceiling|ceiling|drywall|plasterboard|partition' then 'gypsum'
    when p_category ~* 'waterproof' then 'waterproofing'
    when p_category ~* 'insulation' then 'insulation'
    when p_category ~* 'roofing|^roof|roof ' then 'roofing'
    when p_category ~* 'steel|fabrication' then 'steel'
    when p_category ~* 'masonry|block|^plaster' then 'masonry'
    when p_category ~* 'smart.?home|home.?automation|automation|knx' then 'smarthome'
    when p_category ~* 'av.?system|audio.?visual|audio visual' then 'avsystems'
    when p_category ~* 'network|structured.?cabl' then 'networking'
    when p_category ~* 'signage|sign.?board|3d letter' then 'signage'
    when p_category ~* 'acrylic|perspex|plexiglass' then 'acrylic'
    when p_category ~* 'interior.?design' then 'interiordesign'
    when p_category ~* 'fit.?out' then 'fitout'
    when p_category ~* 'combined.?mep|^mep$|mep' then 'mep'
    when p_category ~* 'glass|glaz|alumin|curtain.?wall|shopfront|balustrad' then 'glazing'
    when p_category ~* 'joinery|kitchen|furniture|carpentr|cabinet|wardrobe|cupboard' then 'joinery'
    when p_category ~* 'hvac|^ac-|air.?con|duct|chiller|cooling|ac.?maintenance' then 'hvac'
    when p_category ~* 'electric|wiring|dewa' then 'electrical'
    when p_category ~* 'plumb|sanitary|drainage' then 'plumbing'
    when p_category ~* 'facade' then 'glazing'
    when p_category ~* 'clean|housekeep' then 'cleaning'
    when p_category ~* 'handyman' then 'handyman'
    when p_category ~* 'facilit|general.?service|miscellaneous|^other|^general' then 'general'
    else null end;
$function$


CREATE OR REPLACE FUNCTION public.fn_quote_structured_score(p_quote text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n int; priced int; branded int; laboured int; spec_n int; q record; pts int:=0; miss text[]:='{}';
begin
  select count(*), count(*) filter (where unit_price is not null and unit_price>0),
         count(*) filter (where coalesce(brand,'')<>'' and coalesce(model,'')<>''),
         count(*) filter (where labour is not null or install is not null),
         count(*) filter (where coalesce(specification,'')<>'')
    into n, priced, branded, laboured, spec_n from quote_items where quote_id=p_quote;
  select * into q from quotes where id=p_quote::uuid;
  if n=0 then miss:=array_append(miss,'line_items');
  else pts:=pts+15; if priced=n then pts:=pts+20; else miss:=array_append(miss,'unit_prices_on_all_items'); end if; end if;
  if n>0 and branded=n then pts:=pts+15; else miss:=array_append(miss,'brand_model_per_item'); end if;
  if n>0 and spec_n>=greatest(1,n/2) then pts:=pts+10; else miss:=array_append(miss,'specifications'); end if;
  if laboured>0 then pts:=pts+10; else miss:=array_append(miss,'labour_or_installation'); end if;
  if coalesce(q.warranty,'')<>'' then pts:=pts+6; else miss:=array_append(miss,'warranty'); end if;
  if coalesce(q.lead_time,'')<>'' then pts:=pts+6; else miss:=array_append(miss,'lead_time'); end if;
  if coalesce(q.payment_terms,'')<>'' then pts:=pts+6; else miss:=array_append(miss,'payment_terms'); end if;
  if coalesce(q.exclusions,'')<>'' then pts:=pts+6; else miss:=array_append(miss,'exclusions'); end if;
  if coalesce(q.validity,'')<>'' then pts:=pts+6; else miss:=array_append(miss,'validity'); end if;
  return jsonb_build_object('score',pts,'submittable',pts>=70,'items',n,'priced_items',priced,'missing',to_jsonb(miss),'scored_at',now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_quote_supplier_is_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if NEW.supplier_id is not distinct from OLD.supplier_id then return NEW; end if;
  raise exception 'quotes %: this quotation belongs to supplier % and the write names supplier %. A quotation does not change hands; a correction is a new revision by its own author. (pd_object_cross_owner_write)',
    OLD.id, OLD.supplier_id, coalesce(NEW.supplier_id::text,'(none)') using errcode = '23514';
end $function$


CREATE OR REPLACE FUNCTION public.fn_rate_limit(p_bucket text, p_limit integer, p_window_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r ai_rate_limit%rowtype;
begin
  insert into ai_rate_limit (bucket, window_start, count) values (p_bucket, now(), 0)
    on conflict (bucket) do nothing;
  select * into r from ai_rate_limit where bucket = p_bucket for update;
  if r.window_start < now() - make_interval(secs => p_window_seconds) then
    update ai_rate_limit set window_start = now(), count = 1 where bucket = p_bucket;
    return jsonb_build_object('allowed', true, 'count', 1, 'limit', p_limit);
  end if;
  if r.count >= p_limit then
    return jsonb_build_object('allowed', false, 'count', r.count, 'limit', p_limit,
      'retry_after_seconds', greatest(1, p_window_seconds - extract(epoch from (now() - r.window_start))::int));
  end if;
  update ai_rate_limit set count = count + 1 where bucket = p_bucket;
  return jsonb_build_object('allowed', true, 'count', r.count + 1, 'limit', p_limit);
end $function$


CREATE OR REPLACE FUNCTION public.fn_receipt_hand_to_bookkeeper(p_inbound_id bigint, p_review_ids bigint[], p_reason text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare m record; v_owner text; v_task bigint;
begin
  select * into m from public.inbound_messages where id = p_inbound_id;
  if not found then return null; end if;

  -- one task per inbound email, however many times the email is redelivered
  select t.id into v_task from public.org_tasks t
   where t.detail like '[inbound_message:' || p_inbound_id || ']%'
     and t.status not in ('done', 'cancelled')
   order by t.id limit 1;

  if v_task is null then
    -- 9 SEP 2026: 'bookkeeper' has never been a row in org_agents, so every held receipt became an
    -- UNOWNED task. The accountant seat now exists and this is its named work; the old key is kept
    -- first so nothing changes if that seat is ever created.
    select o.agent_key into v_owner from public.org_agents o
     where o.agent_key in ('bookkeeper','accountant') and o.active and coalesce(o.available, true)
     order by case o.agent_key when 'bookkeeper' then 0 else 1 end limit 1;

    insert into public.org_tasks (dept_key, title, detail, status, tier, needs_founder, decided_by,
                                  action_class, assigned_agent, priority, result)
    values ('finance',
            left('Book a forwarded receipt the parser could not read: ' || coalesce(m.subject, '(no subject)'), 200),
            '[inbound_message:' || p_inbound_id || '] ' || coalesce(p_reason, 'no amount could be read from the text')
              || E'\n\nFrom ' || coalesce(m.from_email, '?') || ' to ' || coalesce(m.to_email, '?') || ' at ' || m.created_at
              || '. Stored documents: doc_reviews ' || coalesce(array_to_string(p_review_ids, ', '), '(none)')
              || '. Read the document, book the expense in expense_entries (source ''receipt''), close the doc_reviews rows '
              || 'as auto_applied and the inbound row as replied. Only a Stripe refund reaches the founder.',
            'assigned', 'advisory', false, 'fn_receipt_hand_to_bookkeeper',
            'analysis', v_owner, 1,
            jsonb_build_object('source', jsonb_build_object('inbound_message_id', p_inbound_id,
                               'doc_review_ids', to_jsonb(coalesce(p_review_ids, '{}'::bigint[])),
                               'reason', p_reason, 'handed_at', now())))
    returning id into v_task;
  end if;

  update public.inbound_messages set owner_role = coalesce(v_owner, 'accountant') where id = p_inbound_id and owner_role is null;
  update public.doc_reviews set owner_role = coalesce(v_owner, 'accountant')
   where id = any(coalesce(p_review_ids, '{}'::bigint[])) and owner_role is null;
  return v_task;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_recommend_deterministic(p_step_run_id bigint DEFAULT NULL::bigint, p_record boolean DEFAULT true)
 RETURNS TABLE(determination text, employee text, department text, workflow_key text, step_no integer, step text, outcome text, deliverable text, inputs jsonb, recommendations jsonb, used_llm boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_sid bigint := p_step_run_id;
  v_actor text; v_employee text; v_dept text; v_wf text; v_wfname text; v_step_no int; v_step text;
  v_run uuid; v_ctx jsonb := '{}'::jsonb; v_located text := 'p_step_run_id';
  v_framing text;
  v_kpis jsonb; v_kpi_rows int := 0; v_kpi_measured int := 0; v_kpi_missed int := 0; v_kpi_met int := 0;
  v_sc jsonb; v_sc_rows int := 0; v_sc_off int := 0;
  v_meta jsonb; v_meta_rows int := 0;
  v_recs jsonb; v_n int := 0;
  v_text text; v_one text; rec record;
  v_old_depts text[];
begin
  used_llm := false;
  -- 1. WHO IS ASKING. The step, or the queued action_execution row this invocation is running.
  if v_sid is null then
    select x.workflow_step_run_id, x.request->>'actor'
      into v_sid, v_actor
      from public.action_execution x
      join public.org_action_executor e on e.action_class = x.action_class and e.kind = 'rpc'
     where x.action_class = 'recommend' and x.status = 'queued'
     order by x.created_at limit 1;
    v_located := case when v_sid is not null then 'action_execution.workflow_step_run_id'
                      when v_actor is not null then 'action_execution.request.actor' else 'nothing queued' end;
  end if;
  if v_sid is not null then
    select s.actor, s.step_no, s.input->>'step', s.workflow_run_id, r.workflow_key, coalesce(r.context,'{}'::jsonb), w.name
      into v_actor, v_step_no, v_step, v_run, v_wf, v_ctx, v_wfname
      from public.workflow_step_run s
      join public.workflow_run r on r.id = s.workflow_run_id
      left join public.workflow w on w.workflow_key = r.workflow_key
     where s.id = v_sid;
    v_employee := public.fn_workflow_actor_resolve(v_run, v_actor);
  elsif v_actor is not null then
    v_employee := public.fn_org_agent_resolve(v_actor);
  end if;
  select o.department into v_dept from public.org_agents o where o.agent_key = v_employee and o.active;
  if v_dept is null then
    determination := 'no_scope'; employee := v_employee; department := null; workflow_key := v_wf; step_no := v_step_no; step := v_step;
    outcome := 'no determination: the caller resolves to no active employee, so there is no department whose numbers to read';
    deliverable := outcome;
    inputs := jsonb_build_object('located_by', v_located, 'step_run_id', v_sid, 'actor', v_actor, 'employee', v_employee);
    recommendations := null;
    return next; return;
  end if;
  -- metric_definition.owner_dept still speaks the pre-merge vocabulary (marketing, it, knowledge ...);
  -- org_departments.merged_into is the crosswalk, so a growth step also reads 'marketing' metrics.
  select coalesce(array_agg(d.dept_key), '{}') into v_old_depts
    from public.org_departments d where d.merged_into = v_dept or d.dept_key = v_dept;

  -- 2. THE STEP'S OWN WORDS choose the framing; the numbers are the same engine.
  v_framing := case
    when v_step ilike '%variance%' then 'variance'
    when v_step ilike '%root cause%' then 'root_cause'
    when v_step ilike '%revise%' or v_step ilike '%retire%' then 'revise_or_retire'
    when v_step ilike '%option%' then 'options'
    when v_step ilike '%grade%' or v_step ilike '%monitor%' then 'grade'
    when v_step ilike '%baseline%' then 'baseline'
    when v_step ilike '%define the metric%' then 'define'
    else 'recommend' end;

  -- 3. THE DEPARTMENT'S KPIs, with yesterday's (or the last recorded) value beside today's.
  with k as (
    select k.id, k.agent_key, k.metric, k.kpi, k.unit, k.cadence, k.target_value t, k.actual_value v,
           k.measured_at, k.no_measure_reason, k.serves_goal,
           (select h.actual_value from public.employee_kpi_history h
             where h.kpi_id = k.id and (k.measured_at is null or h.measured_at < k.measured_at - interval '1 hour')
             order by h.measured_at desc limit 1) prev,
           (select h.measured_on from public.employee_kpi_history h
             where h.kpi_id = k.id and (k.measured_at is null or h.measured_at < k.measured_at - interval '1 hour')
             order by h.measured_at desc limit 1) prev_on,
           (select count(*) from public.employee_kpi_history h
             where h.kpi_id = k.id and h.verdict = 'MISSED' and h.measured_on >= current_date - 14) missed_14d
      from public.employee_kpi k join public.org_agents a on a.agent_key = k.agent_key
     where k.active and a.department = v_dept
  ), s as (
    select k.*,
      case when v is null or t is null then null
           when t = 0 then case when v <= 0 then 100.0 else 0.0 end
           when unit = 'percent_max' then round(least(100.0, 100.0 * t / nullif(v,0)), 1)
           else round(100.0 * v / t, 1) end attainment
      from k
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'kpi_id', id, 'agent', agent_key, 'metric', metric, 'unit', unit, 'cadence', cadence,
           'target', t, 'actual', v, 'attainment', attainment,
           'verdict', case when v is null then 'NO DATA' when attainment is null then 'NO TARGET'
                           when attainment >= 100 then 'MET' when attainment >= 90 then 'NEAR' else 'MISSED' end,
           'measured_at', measured_at, 'previous', prev, 'previous_on', prev_on,
           'delta', case when v is not null and prev is not null then round(v - prev, 2) end,
           'missed_days_14d', missed_14d, 'no_measure_reason', no_measure_reason, 'serves_goal', serves_goal)
           order by (v is null), attainment nulls last, id), '[]'::jsonb),
         count(*), count(*) filter (where v is not null),
         count(*) filter (where v is not null and attainment is not null and attainment < 90),
         count(*) filter (where attainment >= 100)
    into v_kpis, v_kpi_rows, v_kpi_measured, v_kpi_missed, v_kpi_met
    from s;

  -- 4. THE COMPANY SCORECARD rows this department owns, with the prior snapshot beside the latest.
  select coalesce(jsonb_agg(jsonb_build_object(
           'metric_key', b.metric_key, 'label', b.label, 'owner_dept', b.owner_dept, 'value', b.value,
           'target', b.target, 'direction', b.direction, 'state', b.state, 'taken_at', b.taken_at,
           'previous', (select m.value from public.metric_snapshot m where m.metric_key = b.metric_key
                          and m.taken_at < b.taken_at - interval '20 hours' and m.error is null
                          order by m.taken_at desc limit 1),
           'delta', case when b.value is not null then round(b.value - (select m.value from public.metric_snapshot m
                          where m.metric_key = b.metric_key and m.taken_at < b.taken_at - interval '20 hours' and m.error is null
                          order by m.taken_at desc limit 1), 2) end)
           order by case b.state when 'OFF_TARGET' then 0 when 'BEHIND' then 1 when 'ERROR' then 2 when 'UNMEASURED' then 3 else 4 end, b.metric_key), '[]'::jsonb),
         count(*), count(*) filter (where b.state in ('OFF_TARGET','BEHIND'))
    into v_sc, v_sc_rows, v_sc_off
    from public.v_bi_scorecard b
   where b.owner_dept = any (v_old_depts);

  -- 5. AD DATA, when the sync has written any. Only the growth scope reads it; it is that department's.
  if v_dept = 'growth' then
    select coalesce(jsonb_agg(jsonb_build_object('campaign', m.campaign_name, 'status', m.effective_status,
             'window', m.time_window, 'spend', m.spend, 'currency', m.currency, 'impressions', m.impressions,
             'clicks', m.clicks, 'ctr', m.ctr, 'cpc', m.cpc, 'results', m.results, 'synced_at', m.synced_at,
             'synced_via', m.synced_via) order by m.synced_at desc), '[]'::jsonb), count(*)
      into v_meta, v_meta_rows
      from (select distinct on (campaign_id, time_window) * from public.meta_insights order by campaign_id, time_window, synced_at desc) m;
  end if;

  inputs := jsonb_build_object(
    'located_by', v_located, 'step_run_id', v_sid, 'actor', v_actor, 'employee', v_employee, 'department', v_dept,
    'scorecard_owner_depts', to_jsonb(v_old_depts), 'framing', v_framing,
    'kpi_rows', v_kpi_rows, 'kpi_measured', v_kpi_measured, 'kpi_missed', v_kpi_missed, 'kpi_met', v_kpi_met,
    'scorecard_rows', v_sc_rows, 'scorecard_off_target', v_sc_off, 'meta_rows', v_meta_rows,
    'kpis', v_kpis, 'scorecard', v_sc, 'meta', coalesce(v_meta, '[]'::jsonb),
    'run_context', case when v_ctx ? 'failing_metrics' or v_ctx ? 'goals_at_risk' or v_ctx ? 'title'
                        then v_ctx - 'at' - 'ref' - 'functions' else null end,
    'measured_at', now());

  employee := v_employee; department := v_dept; workflow_key := v_wf; step_no := v_step_no; step := v_step;

  -- 6. NO DATA is its own answer, in its own shape.
  if v_kpi_measured = 0 and v_sc_rows = 0 and v_meta_rows = 0 then
    determination := 'no_data';
    outcome := format('no determination for %s: %s KPI row(s) in scope and %s of them measured, %s scorecard metric(s) owned, %s ad-insight row(s)',
                      v_dept, v_kpi_rows, v_kpi_measured, v_sc_rows, v_meta_rows);
    deliverable := outcome || case when v_kpi_rows > 0 then '. The KPIs exist but carry no measurement: '
        || (select string_agg(x->>'metric' || coalesce(' (' || (x->>'no_measure_reason') || ')', ''), '; ') from jsonb_array_elements(v_kpis) x)
        || '. Instrument the measure before asking for a recommendation.' else '.' end;
    recommendations := null;
    return next; return;
  end if;

  -- 7. THE RANKED MOVERS. Missed KPIs by attainment, off-target company metrics, then anything worsening.
  with cand as (
    select 'kpi' src, x->>'metric' metric, x->>'agent' owner, (x->>'actual')::numeric actual, (x->>'target')::numeric target,
           x->>'unit' unit, (x->>'attainment')::numeric attainment, x->>'verdict' verdict,
           (x->>'previous')::numeric previous, (x->>'delta')::numeric delta, x->>'measured_at' measured_at,
           (x->>'missed_days_14d')::int missed_14d, x->>'serves_goal' goal,
           case x->>'verdict' when 'MISSED' then 0 when 'NEAR' then 1 when 'NO TARGET' then 3 else 4 end sev
      from jsonb_array_elements(v_kpis) x where x->>'verdict' <> 'NO DATA'
    union all
    select 'scorecard', x->>'label', x->>'owner_dept', (x->>'value')::numeric, (x->>'target')::numeric, x->>'direction',
           case when (x->>'target')::numeric is null or (x->>'value')::numeric is null then null
                when (x->>'direction') = 'down' then round(least(100.0, 100.0 * (x->>'target')::numeric / nullif((x->>'value')::numeric,0)), 1)
                else round(100.0 * (x->>'value')::numeric / nullif((x->>'target')::numeric,0), 1) end,
           x->>'state', (x->>'previous')::numeric, (x->>'delta')::numeric, x->>'taken_at', null, null,
           case x->>'state' when 'OFF_TARGET' then 0 when 'BEHIND' then 1 when 'ERROR' then 2 else 4 end
      from jsonb_array_elements(v_sc) x where x->>'state' not in ('UNMEASURED')
  ), ranked as (
    select c.*, row_number() over (order by sev, attainment nulls last, delta nulls last, metric) rk from cand c
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'rank', rk, 'source', src, 'metric', metric, 'owner', owner, 'actual', actual, 'target', target, 'unit', unit,
           'attainment_pct', attainment, 'verdict', verdict, 'previous', previous, 'delta', delta, 'measured_at', measured_at,
           'missed_days_14d', missed_14d, 'serves_goal', goal,
           'trend', case when delta is null then 'no prior measurement' when delta > 0 then 'up ' || delta when delta < 0 then 'down ' || abs(delta) else 'flat' end,
           'determination', case v_framing
             when 'variance' then case when verdict in ('MISSED','OFF_TARGET','BEHIND')
                 then format('variance: %s at %s against target %s (%s%% attainment); %s',
                             metric, actual, target, attainment, case when delta is null then 'no prior point to trend' when delta < 0 then 'worsened by ' || abs(delta) || ' since the previous measurement' when delta > 0 then 'improved by ' || delta || ' but still short' else 'unchanged' end)
                 else format('within tolerance: %s at %s against target %s (%s%%)', metric, actual, target, attainment) end
             when 'root_cause' then case
                 when verdict in ('MET','ON_TARGET','NEAR') then format('%s is at %s%% of target: no gap to explain', metric, attainment)
                 when coalesce(missed_14d, 0) >= 10 and coalesce(delta, 0) <= 0 then format('the TARGET: %s missed on %s of the last 14 measured days with no improving trend (actual %s vs target %s); propose a revised target with the run of actuals as evidence', metric, missed_14d, actual, target)
                 when delta is not null and delta > 0 then format('the WORK: %s is moving toward target (%s -> %s, target %s); keep the current plan and re-measure on cadence', metric, previous, actual, target)
                 else format('the WORK: %s at %s vs target %s (%s%%) with %s missed day(s) in 14; the gap is recent enough to be closed by the owner %s', metric, actual, target, attainment, coalesce(missed_14d,0), owner) end
             when 'revise_or_retire' then case
                 when coalesce(missed_14d, 0) >= 14 then format('REVISE: %s missed every one of the last 14 measured days (actual %s vs target %s); the target does not describe this business yet', metric, actual, target)
                 when verdict in ('MET','ON_TARGET') and coalesce(missed_14d, 0) = 0 then format('KEEP: %s met at %s against %s and never missed in 14 days', metric, actual, target)
                 else format('KEEP and watch: %s at %s%% attainment, %s missed day(s) in 14', metric, attainment, coalesce(missed_14d,0)) end
             when 'options' then format('option: close the gap on %s (actual %s, target %s, gap %s %s); cost proxy = gap size, risk = %s', metric, actual, target, round(abs(coalesce(target,0) - coalesce(actual,0)), 2), coalesce(unit,''), case when attainment is null then 'unknown' when attainment < 50 then 'high (below half of target)' when attainment < 90 then 'medium' else 'low' end)
             when 'grade' then format('grade: %s %s (%s -> %s against target %s)', metric, case when delta is null then 'UNGRADED, no prior measurement' when (unit = 'percent_max' or unit = 'down') and delta < 0 then 'BETTER' when (unit = 'percent_max' or unit = 'down') and delta > 0 then 'WORSE' when delta > 0 then 'BETTER' when delta < 0 then 'WORSE' else 'FLAT' end, previous, actual, target)
             when 'baseline' then format('baseline captured: %s = %s (%s) measured %s, target %s', metric, actual, coalesce(unit,''), measured_at, target)
             else format('%s: %s at %s against target %s (%s%%), owner %s', verdict, metric, actual, target, attainment, owner) end)
           order by rk), '[]'::jsonb), count(*)
    into v_recs, v_n
    from ranked where rk <= 5;

  determination := 'recommendation';
  recommendations := v_recs;
  v_one := coalesce((select x->>'determination' from jsonb_array_elements(v_recs) x order by (x->>'rank')::int limit 1), 'nothing in scope moved');
  outcome := left(format('%s: %s of %s KPIs measured, %s missed, %s met; %s of %s owned scorecard metrics off target%s. Top mover: %s',
                    v_dept, v_kpi_measured, v_kpi_rows, v_kpi_missed, v_kpi_met, v_sc_off, v_sc_rows,
                    case when v_meta_rows > 0 then format('; %s ad-insight row(s) read', v_meta_rows) else '' end, v_one), 600);
  v_text := format(E'%s\nWorkflow %s step %s (%s), worked by %s for %s on %s.\nInputs: %s KPI rows (%s measured, %s missed, %s met), %s scorecard metrics (%s off target), %s ad-insight rows.\n',
                   case v_framing when 'variance' then 'VARIANCE AGAINST TARGET' when 'root_cause' then 'ROOT CAUSE: THE WORK OR THE TARGET' when 'revise_or_retire' then 'REVISE OR RETIRE' when 'options' then 'OPTIONS WITH COST AND RISK' when 'grade' then 'GRADE AGAINST BASELINE' when 'baseline' then 'BASELINE' when 'define' then 'METRIC DEFINITION REVIEW' else 'RECOMMENDATION' end,
                   coalesce(v_wfname, v_wf, '(no workflow)'), coalesce(v_step_no::text, '-'), coalesce(v_step, 'direct call'), v_employee, v_dept, to_char(now() at time zone 'utc', 'YYYY-MM-DD HH24:MI') || ' UTC',
                   v_kpi_rows, v_kpi_measured, v_kpi_missed, v_kpi_met, v_sc_rows, v_sc_off, v_meta_rows);
  for rec in select x from jsonb_array_elements(v_recs) x order by (x->>'rank')::int loop
    v_text := v_text || format(E'%s. %s [%s; trend %s; measured %s]\n', rec.x->>'rank', rec.x->>'determination', rec.x->>'source', rec.x->>'trend', coalesce(left(rec.x->>'measured_at', 16), '?'));
  end loop;
  if v_meta_rows > 0 then
    v_text := v_text || 'Ad data: ' || (select string_agg(format('%s [%s] %s: spend %s %s, %s impressions, %s clicks, ctr %s, cpc %s (synced %s via %s)',
        m->>'campaign', m->>'status', m->>'window', m->>'spend', m->>'currency', m->>'impressions', m->>'clicks', coalesce(m->>'ctr','-'), coalesce(m->>'cpc','-'), left(m->>'synced_at',10), m->>'synced_via'), '; ')
        from jsonb_array_elements(v_meta) m) || E'\n';
  end if;
  if v_ctx ? 'failing_metrics' then
    v_text := v_text || 'Trigger context named failing metrics ' || (v_ctx->'failing_metrics')::text || coalesce(' and goals at risk ' || (v_ctx->'goals_at_risk')::text, '') || E'.\n';
  end if;
  v_text := v_text || 'Basis: employee_kpi actual/target as measured, employee_kpi_history for the previous point and the 14-day miss count, v_bi_scorecard + metric_snapshot for company metrics' || case when v_dept = 'growth' then ', meta_insights for ad data' else '' end || '. No model call.';
  deliverable := v_text;

  if p_record then
    insert into public.org_memory(scope, kind, content, source)
    values ('analytics', 'insight', left(coalesce(v_wf,'direct') || ' step ' || coalesce(v_step_no::text,'-') || ' — ' || outcome, 500) || E'\n\n' || left(v_text, 3000), 'fn_recommend_deterministic');
  end if;
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_reconcile_doc_blocks(p_grace_days integer DEFAULT 0)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_lic_susp int := 0; v_ins_susp int := 0; v_restored int := 0;
  v_cut date := current_date - make_interval(days => p_grace_days);
  rec record;
begin
  -- ---- SUSPEND: trade licence expired -------------------------------------------------
  -- Only touches rows that are unblocked or already blocked for a document reason, so a
  -- manual block set by the team is never overwritten or silently cleared.
  for rec in
    select id, company_name, claimed_by, email, phone, whatsapp, license_expiry
      from leads
     where approval_status = 'approved' and coalesce(banned,false) = false
       and license_expiry is not null and license_expiry < v_cut
       and (coalesce(matching_blocked,false) = false
            or matching_block_reason in ('licence_expired','insurance_expired'))
       and coalesce(matching_block_reason,'') is distinct from 'licence_expired'
  loop
    update leads set matching_blocked = true, matching_block_reason = 'licence_expired'
     where id = rec.id;
    v_lic_susp := v_lic_susp + 1;
    insert into notifications(type,to_email,to_role,lead_id,channel,subject,body,status)
    values ('doc_suspended', coalesce(rec.claimed_by, rec.email), 'supplier', rec.id, 'email',
      'Your QuotesDone account is paused - trade licence expired',
      'Dear ' || coalesce(rec.company_name,'supplier') || ',' || chr(10) || chr(10) ||
      'Your trade licence expired on ' || rec.license_expiry || ', so your account has been temporarily paused and you will not receive new customer requests until it is renewed.' || chr(10) || chr(10) ||
      'To restore your account: reply to this email with the renewed licence attached, or upload it in the Documents tab of your supplier portal. Your account is restored automatically as soon as we have a valid copy - nothing else is needed and no fee applies.',
      'queued');
  end loop;

  -- ---- SUSPEND: insurance expired -----------------------------------------------------
  for rec in
    select id, company_name, claimed_by, email, insurance_expiry
      from leads
     where approval_status = 'approved' and coalesce(banned,false) = false
       and insurance_expiry is not null and insurance_expiry < v_cut
       and (coalesce(matching_blocked,false) = false
            or matching_block_reason in ('licence_expired','insurance_expired'))
       and coalesce(matching_block_reason,'') is distinct from 'insurance_expired'
       -- a licence block is the more serious of the two, so do not downgrade its reason
       and coalesce(matching_block_reason,'') is distinct from 'licence_expired'
  loop
    update leads set matching_blocked = true, matching_block_reason = 'insurance_expired'
     where id = rec.id;
    v_ins_susp := v_ins_susp + 1;
    insert into notifications(type,to_email,to_role,lead_id,channel,subject,body,status)
    values ('doc_suspended', coalesce(rec.claimed_by, rec.email), 'supplier', rec.id, 'email',
      'Your QuotesDone account is paused - insurance expired',
      'Dear ' || coalesce(rec.company_name,'supplier') || ',' || chr(10) || chr(10) ||
      'Your insurance certificate expired on ' || rec.insurance_expiry || ', so your account has been temporarily paused and you will not receive new customer requests until it is renewed.' || chr(10) || chr(10) ||
      'To restore your account: reply to this email with the renewed certificate attached, or upload it in the Documents tab of your supplier portal. Your account is restored automatically as soon as we have a valid copy.',
      'queued');
  end loop;

  -- ---- RESTORE: the blocking document is valid again -----------------------------------
  -- Only clears blocks this job set. A manual block stays put.
  for rec in
    select id, company_name, claimed_by, email, matching_block_reason
      from leads
     where matching_block_reason in ('licence_expired','insurance_expired')
       and ((matching_block_reason = 'licence_expired'
             and (license_expiry is null or license_expiry >= v_cut))
         or (matching_block_reason = 'insurance_expired'
             and (insurance_expiry is null or insurance_expiry >= v_cut)))
  loop
    update leads set matching_blocked = false, matching_block_reason = null where id = rec.id;
    v_restored := v_restored + 1;
    insert into notifications(type,to_email,to_role,lead_id,channel,subject,body,status)
    values ('doc_restored', coalesce(rec.claimed_by, rec.email), 'supplier', rec.id, 'email',
      'Your QuotesDone account is active again',
      'Dear ' || coalesce(rec.company_name,'supplier') || ',' || chr(10) || chr(10) ||
      'Thank you - your documents are up to date and your account is active again. You will start receiving matching customer requests immediately.',
      'queued');
  end loop;

  return json_build_object('licence_suspended', v_lic_susp, 'insurance_suspended', v_ins_susp,
                           'restored', v_restored, 'grace_days', p_grace_days, 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_record_llm_attempt(p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_req      uuid    := coalesce(nullif(p->>'request_id','')::uuid, gen_random_uuid());
  v_model    text    := nullif(p->>'model_route','');
  v_ok       boolean := coalesce((p->>'ok')::boolean, false);
  v_no       integer;
  v_cls      jsonb;
  v_key      text;
  v_trips    boolean;
  v_first    boolean;
  v_thresh   integer;
  v_cool     integer;
  v_conseq   integer;
  v_state    text := 'closed';
  v_id       uuid;
  v_in       integer := nullif(p->>'prompt_tokens','')::integer;
  v_out      integer := nullif(p->>'output_tokens','')::integer;
  v_cached   integer := coalesce(nullif(p->>'cached_in_tokens','')::integer, 0);
  v_cost     numeric := nullif(p->>'cost_aed','')::numeric;
begin
  if v_model is null then
    raise exception 'fn_record_llm_attempt requires model_route: the route is what the breaker keys on';
  end if;

  if not v_ok then
    v_cls := fn_classify_llm_failure(p->>'err_excerpt',
                                     nullif(p->>'http_status','')::integer,
                                     p->>'finish_reason', v_model,
                                     nullif(p->>'latency_ms','')::integer);
    v_key := v_cls->>'class_key';
  end if;

  -- attempt_no is assigned HERE, never accepted from the caller. A caller cannot claim to be
  -- attempt 1 twice, and cannot renumber an earlier attempt out of the way.
  select coalesce(max(attempt_no), 0) + 1 into v_no from llm_attempt where request_id = v_req;

  insert into llm_route_health (model_id) values (v_model) on conflict (model_id) do nothing;
  select failure_threshold, cooldown_seconds into v_thresh, v_cool
    from llm_route_health where model_id = v_model;

  if v_ok then
    update llm_route_health
       set consecutive_failures = 0, open_until = null, opened_reason = null, opened_class = null,
           last_ok_at = now(), total_attempts = total_attempts + 1, total_ok = total_ok + 1,
           updated_at = now()
     where model_id = v_model;
  else
    select trips_breaker, opens_on_first into v_trips, v_first
      from llm_failure_class where class_key = v_key;
    update llm_route_health
       set consecutive_failures = case when coalesce(v_trips,false)
                                       then consecutive_failures + 1 else consecutive_failures end,
           last_failure_at = now(), total_attempts = total_attempts + 1, updated_at = now()
     where model_id = v_model
     returning consecutive_failures into v_conseq;

    if coalesce(v_trips,false) and (coalesce(v_first,false) or v_conseq >= v_thresh) then
      update llm_route_health
         set open_until = now() + make_interval(secs => v_cool),
             opened_reason = case when coalesce(v_first,false)
                             then 'opened on first occurrence of ' || v_key
                             else v_conseq || ' consecutive failures, threshold ' || v_thresh end,
             opened_class = v_key
       where model_id = v_model;
      v_state := 'opened_by_this';
    end if;
  end if;

  -- DERIVE THE MONEY HERE, from the same pricing source ai_cost_log uses, rather than trusting a
  -- caller to convert. A caller that computes its own AED is a second pricing implementation, and
  -- two of those drift. An explicit cost_aed in the payload still wins, so a provider that reports
  -- its own charge can be recorded verbatim.
  --
  -- Deliberately only when tokens are present: a failed attempt that produced no usage block has
  -- no measurable cost, and inventing 0 there would make "this retry was free" indistinguishable
  -- from "nobody recorded what this retry cost".
  if v_cost is null and (v_in is not null or v_out is not null) then
    begin
      v_cost := public.fn_model_cost_usd(v_model, coalesce(v_in,0), coalesce(v_out,0), v_cached)
                * public.fn_usd_to_aed();
    exception when others then v_cost := null;   -- pricing is reporting, never a gate
    end;
  end if;

  insert into llm_attempt (request_id, attempt_no, fn, agent_key, task_class, model_route, tier,
                           ok, class_key, http_status, finish_reason, err_excerpt,
                           evidence_truncated, latency_ms, prompt_tokens, output_tokens, cost_aed,
                           breaker_state)
  values (v_req, v_no, p->>'fn', p->>'agent_key', p->>'task_class', v_model, p->>'tier',
          v_ok, v_key, nullif(p->>'http_status','')::integer, p->>'finish_reason',
          left(coalesce(p->>'err_excerpt',''), 4000),
          coalesce((v_cls->>'evidence_truncated')::boolean, false),
          nullif(p->>'latency_ms','')::integer, v_in, v_out, v_cost,
          v_state)
  returning attempt_id into v_id;

  return jsonb_build_object(
    'attempt_id', v_id, 'request_id', v_req, 'attempt_no', v_no,
    'class_key', v_key, 'breaker', v_state,
    'cost_aed', v_cost,
    'retry_allowed', case when v_ok then false
                          when v_state = 'opened_by_this' then false   -- fail closed, do not retry into a wall
                          else fn_llm_retry_allowed(v_key, v_no) end,
    'retry_backoff_ms', coalesce((v_cls->>'retry_backoff_ms')::integer, 0),
    'evidence_truncated', coalesce((v_cls->>'evidence_truncated')::boolean, false));
end $function$


CREATE OR REPLACE FUNCTION public.fn_record_routine_change()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record;
begin
  for r in select * from pg_event_trigger_ddl_commands()
            where object_type in ('function', 'procedure') and schema_name = 'public'
  loop
      insert into public.routine_change_log (application_name, client_addr, command_tag, object_identity, statement_head)
      values (current_setting('application_name', true), inet_client_addr(), r.command_tag, r.object_identity,
              regexp_replace(regexp_replace(left(current_query(), 2000),
                '((key|secret|password|passwd|token|bearer|authorization)[a-z_]*\s*(=|:)\s*)(''[^'']*''|"[^"]*"|\S{8,})', '\1[REDACTED]', 'gi'),
                '\m((sk|rk|pk)_(live|test)_|whsec_|sbp_|eyJ)[A-Za-z0-9_\-\.]{8,}', '[REDACTED]', 'g'));
  end loop;
exception when others then null;  -- recording must never block the change it records, including a failure to read the event
end $function$


CREATE OR REPLACE FUNCTION public.fn_record_routine_drop()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record;
begin
  for r in select * from pg_event_trigger_dropped_objects()
            where object_type in ('function', 'procedure') and schema_name = 'public'
  loop
      insert into public.routine_change_log (application_name, client_addr, command_tag, object_identity, statement_head)
      values (current_setting('application_name', true), inet_client_addr(), 'DROP FUNCTION', r.object_identity,
              regexp_replace(regexp_replace(left(current_query(), 2000),
                '((key|secret|password|passwd|token|bearer|authorization)[a-z_]*\s*(=|:)\s*)(''[^'']*''|"[^"]*"|\S{8,})', '\1[REDACTED]', 'gi'),
                '\m((sk|rk|pk)_(live|test)_|whsec_|sbp_|eyJ)[A-Za-z0-9_\-\.]{8,}', '[REDACTED]', 'g'));
  end loop;
exception when others then null;
end $function$


CREATE OR REPLACE FUNCTION public.fn_record_tool_call(p_correlation uuid, p_agent_key text, p_role_id text, p_tool_id text, p_args jsonb, p_status text, p_result_hash text, p_result_rows integer, p_result_bytes integer, p_error text, p_attempt integer, p_latency_ms integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  insert into agent_tool_call (correlation_id, agent_key, role_id, tool_id, args, status,
                               result_hash, result_rows, result_bytes, error, attempt, latency_ms)
  values (p_correlation, p_agent_key, p_role_id, p_tool_id, coalesce(p_args,'{}'::jsonb), p_status,
          p_result_hash, p_result_rows, p_result_bytes, left(p_error, 500),
          coalesce(p_attempt,1), p_latency_ms)
  returning id into v_id;
  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_amount_aed(p_paid_aed numeric, p_paid_at timestamp with time zone, p_refund_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_paid numeric; v_admin numeric; v_pct numeric; v_days integer; v_interest numeric;
  v_min integer; v_max integer;
begin
  -- The customer's refund is the fee actually paid, in full: the published Refund Policy promises no
  -- administrative deduction and fn_refund_amount_is_the_fee_paid enforces it on the refunds row.
  v_paid  := round(coalesce(p_paid_aed, 0), 2);
  -- The AED 250 administrative fee and the 9% p.a. (UAE statutory maximum) are what the SUPPLIER whose
  -- silence caused the refund owes on top of the fee: founder decision 6 Sep 2026, verbatim in
  -- decision_policy.refund_policy_founder_decision_2026_09_06.
  v_admin := coalesce((select (d.value #>> '{}')::numeric from public.decision_policy d where d.key = 'refund_admin_fee_aed'), 250);
  v_pct   := coalesce((select (d.value #>> '{}')::numeric from public.decision_policy d where d.key = 'refund_late_fee_annual_pct'), 9);
  select bank_settlement_working_days_min, bank_settlement_working_days_max
    into v_min, v_max from public.pricing_config order by id limit 1;
  -- simple interest, pro-rated by CALENDAR days (Dubai dates) between the two instants
  v_days := greatest(0, (coalesce(p_refund_at, now()) at time zone 'Asia/Dubai')::date
                      - (coalesce(p_paid_at, coalesce(p_refund_at, now())) at time zone 'Asia/Dubai')::date);
  v_interest := round(v_paid * v_pct / 100.0 * v_days / 365.0, 2);
  return jsonb_build_object(
    'paid_aed', v_paid,
    'customer_refund_aed', v_paid,
    'admin_fee_aed', v_admin,
    'interest_pct_pa', v_pct,
    'interest_days', v_days,
    'interest_aed', v_interest,
    'supplier_charge_aed', round(v_paid + v_admin + v_interest, 2),
    'bank_settlement_working_days', coalesce(v_min, 7)::text || '-' || coalesce(v_max, 14)::text,
    'basis', 'customer: the reveal fee paid, refunded in full, no deduction; supplier: that fee + AED '
             || v_admin::text || ' administrative fee + ' || v_pct::text
             || '% p.a. simple interest for ' || v_days::text || ' calendar day(s)');
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_amount_is_the_fee_paid()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  t public.transactions%rowtype;
  v_expected bigint;
  -- A refund Stripe already issued is a fact to be recorded, not a request to be approved.
  v_external constant text[] := array['stripe_webhook','stripe_dashboard','stripe'];
begin
  if lower(coalesce(NEW.requested_by,'')) = any(v_external) then
    return NEW;
  end if;

  if NEW.transaction_id is null then
    raise exception 'refunds: a refund must name the transaction it reverses. transaction_id is null, so this row asserts money is owed without saying which payment it came from. (refund_names_no_payment)'
      using errcode = '23514',
            hint = 'Set transaction_id to the public.transactions row whose reveal_fee is being returned. A refund this platform did not issue is recorded through fn_refund_settle with requested_by stripe_webhook, and that path is exempt.';
  end if;

  select * into t from public.transactions where id = NEW.transaction_id;
  if not found then
    raise exception 'refunds: transaction % does not exist. (refund_transaction_absent)',
      NEW.transaction_id using errcode = '23503';
  end if;

  if coalesce(t.total_charged, t.reveal_fee) is null or coalesce(t.total_charged, t.reveal_fee) <= 0 then
    raise exception 'refunds: transaction % records no reveal fee (reveal_fee %), so there is nothing to give back. A refund of an unpaid reveal is a payment, not a refund. (refund_no_fee_was_paid)',
      NEW.transaction_id, coalesce(t.reveal_fee::text,'null') using errcode = '23514';
  end if;

  if t.refund_deadline is null then
    raise exception 'refunds: transaction % has no refund window. trg_reveal_window opens one at reveal, so a transaction without it was never revealed and no refund can be due yet. (refund_window_not_open)',
      NEW.transaction_id using errcode = '23514';
  end if;
  -- THE WINDOW GOVERNS THE DECISION, NOT THE REQUEST (14 Sep 2026). The terms let the customer
  -- complain "at any time"; what waits for the fifth working day and the CEO's final call is the
  -- approval. So a row at 'requested' is recorded whenever it arrives, and only the move to money
  -- (approved, processing, succeeded) is refused before refund_deadline.
  if NEW.status in ('approved', 'processing', 'succeeded') and now() < t.refund_deadline then
    raise exception 'refunds: transaction % may not be approved or paid before % (it is now %). The supplier has five working days from the payment and the CEO''s final call before a refund is decided; the request itself is recorded at any time. (refund_window_not_yet_open)',
      NEW.transaction_id, t.refund_deadline, now() using errcode = '23514';
  end if;

  -- ── THE STRIPE REFERENCE, ADDED 9 SEP 2026 ───────────────────────────────────────────────────
  -- The founder: "it's issued against that exact invoice reference... It has an ID." The reference
  -- Stripe gave us when the customer paid is transactions.payment_ref (stripe_webhook writes the
  -- payment_intent, falling back to the checkout session id). Until now stripe_payment_intent on a
  -- refund was a nullable text column nothing checked, so a refund could name transaction A and
  -- cite the payment of transaction B -- or name no payment at all -- and still move money.
  if coalesce(btrim(t.payment_ref), '') = '' then
    raise exception 'refunds: transaction % carries no Stripe payment reference, so there is no payment of record to reverse. (refund_payment_has_no_reference)',
      NEW.transaction_id using errcode = '23514',
            hint = 'transactions.payment_ref is written by stripe_webhook when the reveal fee settles. A transaction without one was never paid through Stripe, and money must not be returned against a payment nobody can point at.';
  end if;
  if coalesce(btrim(NEW.stripe_payment_intent), '') = '' then
    raise exception 'refunds: this refund names no Stripe payment. Transaction % was paid under reference %, and a refund is issued against that exact reference. (refund_names_no_stripe_reference)',
      NEW.transaction_id, t.payment_ref using errcode = '23514',
            hint = 'Set stripe_payment_intent to the payment_ref of the transaction being reversed. Founder ruling, 9 Sep 2026.';
  end if;
  if btrim(NEW.stripe_payment_intent) <> btrim(t.payment_ref) then
    raise exception 'refunds: this refund cites Stripe payment %, but transaction % was paid under %. A refund is issued against the exact reference of the payment it reverses, never another one. (refund_cites_the_wrong_stripe_payment)',
      NEW.stripe_payment_intent, NEW.transaction_id, t.payment_ref using errcode = '23514';
  end if;

  -- AND THE AMOUNT IS READ OFF THAT PAYMENT. Equality, not a ceiling: the reveal fee is refunded
  -- whole or not at all, so "cannot exceed what the payment took" is enforced by the stricter rule
  -- that it must EQUAL it. A platform refund with no amount is refused outright -- an unstated
  -- figure is not a smaller figure, it is an unbounded one.
  v_expected := round(coalesce(t.total_charged, t.reveal_fee) * 100)::bigint;
  -- A TOP-UP (topup_of set) completes a case on THIS payment and carries only the part still owed, so
  -- it is exempt from equality; a01 caps it, and every live refund on the payment together, at
  -- total_charged (PR #640 re-review, 14 Sep 2026).
  if NEW.topup_of is not null then
    if not exists (select 1 from public.refunds c where c.id = NEW.topup_of and c.transaction_id = NEW.transaction_id and c.topup_of is null) then
      raise exception 'refunds: a top-up must name a refund case on the same payment; % is not one for transaction %. (refund_topup_names_no_case)',
        NEW.topup_of, NEW.transaction_id using errcode = '23514';
    end if;
    if NEW.amount_fils is null or NEW.amount_fils <= 0 then
      raise exception 'refunds: a top-up must state a positive amount. (refund_states_no_amount)' using errcode = '23514';
    end if;
    return NEW;
  end if;
  if NEW.amount_fils is null then
    raise exception 'refunds: a platform refund must state its amount. Transaction % took % fils (AED %), and that is the only figure this refund may carry. (refund_states_no_amount)',
      NEW.transaction_id, v_expected, round(coalesce(t.total_charged, t.reveal_fee),2) using errcode = '23514';
  end if;
  if NEW.amount_fils <> v_expected then
    raise exception 'refunds: the amount must equal what the customer actually paid, the 3%% and the processing part together (total_charged), on transaction % — expected % fils (AED %), got % fils (AED %). A refund figure is read off the payment, never typed. (refund_amount_is_not_the_fee_paid)',
      NEW.transaction_id, v_expected, round(coalesce(t.total_charged, t.reveal_fee),2), NEW.amount_fils, round(NEW.amount_fils/100.0,2)
      using errcode = '23514';
  end if;

  return NEW;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_refund_attach_receipt(p_refund_id bigint, p_receipt_url text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_existing text; v_ok boolean;
begin
  if p_refund_id is null or p_refund_id <= 0 then
    return jsonb_build_object('ok', false, 'reason', 'no refund id');
  end if;
  if coalesce(btrim(p_receipt_url), '') = '' then
    return jsonb_build_object('ok', false, 'reason', 'no receipt url');
  end if;
  -- Stripe's hosted receipts live on stripe.com. A column the founder and the CEO open as "the
  -- document behind this refund" may not be made to point somewhere else by a spoofed payload.
  if p_receipt_url !~ '^https://[a-z0-9.-]*\.?stripe\.com/' then
    return jsonb_build_object('ok', false, 'reason', 'not a stripe.com receipt url', 'given', left(p_receipt_url, 120));
  end if;

  select stripe_receipt_url into v_existing from public.refunds where id = p_refund_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', format('no refund %s', p_refund_id));
  end if;
  if coalesce(v_existing, '') <> '' then
    return jsonb_build_object('ok', true, 'unchanged', true, 'reason', 'a receipt is already recorded; the first one is the one the money moved under');
  end if;

  update public.refunds set stripe_receipt_url = p_receipt_url
   where id = p_refund_id and stripe_receipt_url is null;
  get diagnostics v_ok = row_count;
  return jsonb_build_object('ok', v_ok, 'refund_id', p_refund_id);
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_ceo_approval_only()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.status <> 'approved' then return new; end if;
  if exists (select 1 from public.ceo_identity c
              where c.active and lower(c.identity) = lower(btrim(coalesce(new.decided_by, '')))) then
    return new;
  end if;
  raise exception 'refund %: approved by %, who is not an active CEO identity.',
    coalesce(new.id::text, '(new)'), coalesce(nullif(btrim(new.decided_by), ''), '(nobody)')
    using errcode = '42501',
          hint = 'Refunds belong to the CEO — the founder''s ruling of 8 Sep 2026, replacing his '
              || '17 Aug rule that every refund needed him. A refund reaches ''approved'' only with '
              || 'a decided_by that is an active row in public.ceo_identity. decided_by is checked '
              || 'against that table and never trusted as supplied: the hole this closes is a refund '
              || 'that approved itself as ''policy:auto_window''.';
end
$function$


CREATE OR REPLACE FUNCTION public.fn_refund_decide(p_refund_id bigint, p_approve boolean, p_decided_by text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.refunds; v_app public.ceo_approval; v_new text;
begin
  select * into r from public.refunds where id = p_refund_id;
  if not found then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if r.status <> 'requested' then return jsonb_build_object('ok', false, 'error', 'not_decidable', 'status', r.status); end if;
  if coalesce(btrim(p_decided_by), '') = '' then return jsonb_build_object('ok', false, 'error', 'decider_required'); end if;
  if lower(btrim(p_decided_by)) like 'policy:%' then
    return jsonb_build_object('ok', false, 'error', 'automatic_decider_refused',
      'hint', 'A refund is decided by an actor, not by a rule. Approvals are the CEO''s.');
  end if;

  if p_approve then
    select * into v_app from public.ceo_approval a
     where a.subject_kind = 'refund' and a.subject_id = p_refund_id::text and a.decision = 'approved' and a.superseded_by is null
     order by a.decision_id desc limit 1;
    if not found then
      return jsonb_build_object('ok', false, 'error', 'no_ceo_approval',
        'hint', 'A refund is approved only by a CEO approval that passed the process checklist (fn_ceo_refund_review, or ceo_agent decide). This routine records that decision; it cannot make one.');
    end if;
    update public.refunds set status = 'approved', decided_by = v_app.decided_by, decided_at = now(),
           decision_note = coalesce(p_note, v_app.rationale), refund_decision_id = v_app.decision_id
     where id = p_refund_id;
    v_new := 'approved';
  else
    update public.refunds set status = 'rejected', decided_by = p_decided_by, decided_at = now(), decision_note = p_note where id = p_refund_id;
    v_new := 'rejected';
  end if;
  if r.transaction_id is not null then
    update public.transactions set refund_status = v_new, refund_resolved_at = now(), refund_note = coalesce(p_note, refund_note)
     where id = r.transaction_id;
  end if;
  return jsonb_build_object('ok', true, 'refund_id', p_refund_id, 'status', v_new, 'decided_by', coalesce(v_app.decided_by, p_decided_by));
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_document(p_refund_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(
    (select jsonb_build_object(
       'ok',              v.doc_path is not null,
       'refund_id',       v.id,
       'transaction_id',  v.transaction_id,
       'status',          v.status,
       'amount_fils',     v.amount_fils,
       'currency',        v.currency,
       'stripe_payment_intent', v.stripe_payment_intent,
       'stripe_charge_id',      v.stripe_charge_id,
       'stripe_refund_id',      v.stripe_refund_id,
       'stripe_receipt_url',    v.stripe_receipt_url,
       'stripe_binding',  v.stripe_binding,
       'bucket',          v.doc_bucket,
       'path',            v.doc_path,
       'name',            v.doc_name,
       'content_type',    v.doc_content_type,
       'kind',            v.doc_kind,
       'note',            v.doc_note,
       'state',           v.document_state,
       'reason',          case
                            when v.doc_path is not null then null
                            when v.stripe_receipt_url is not null
                              then 'No file is stored for this refund yet. Stripe''s own hosted '
                                || 'receipt for the payment is known and is returned as '
                                || 'stripe_receipt_url; it has not been fetched into finance-docs.'
                            else 'This refund has no stored document and no Stripe receipt reference. '
                              || 'The reveal fee was taken through a mode=payment Checkout, which '
                              || 'produces no Stripe invoice, so the receipt reference has to be read '
                              || 'off the charge before anything can be stored.'
                          end)
     from public.v_refund_documents v where v.id = p_refund_id),
    jsonb_build_object('ok', false, 'refund_id', p_refund_id, 'state', 'no_such_refund',
                       'reason', 'There is no public.refunds row with that id.'));
$function$


CREATE OR REPLACE FUNCTION public.fn_refund_document_coverage()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'refunds',          count(*),
    'openable',         count(*) filter (where is_openable),
    'reference_only',   count(*) filter (where document_state = 'reference_only'),
    'unclassified',     count(*) filter (where document_state = 'unclassified'),
    'missing',          count(*) filter (where document_state = 'missing'),
    'missing_ids',      coalesce(jsonb_agg(id order by id) filter (where document_state = 'missing'), '[]'::jsonb),
    'stripe_bound',     count(*) filter (where stripe_binding = 'bound'),
    'stripe_unbound_ids', coalesce(jsonb_agg(id order by id)
                            filter (where stripe_binding in ('no_reference','mismatched','no_transaction')), '[]'::jsonb),
    'by_kind',          (select coalesce(jsonb_object_agg(document_state, n), '{}'::jsonb)
                         from (select document_state, count(*) n
                               from public.v_refund_documents group by 1) s))
  from public.v_refund_documents;
$function$


CREATE OR REPLACE FUNCTION public.fn_refund_execute_authorized(p_refund_id bigint, p_expect_amount numeric, p_expect_currency text, p_provider_ref text, p_provider_outcome text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; t record; v_dest text; v_basis text; v_state text;
begin
  select * into r from public.refund_case where refund_id = p_refund_id for update;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no such refund case'); end if;

  -- THE SERVER-SIDE DECISION, read here rather than accepted from the caller. There is no parameter
  -- for "the CEO approved this", so a model cannot supply one.
  if r.state <> 'ceo_authorized' then
    return jsonb_build_object('ok', false, 'reason',
      format('this refund is %L, not ceo_authorized. Execution reads the decision from the record; it is not something a caller can assert.', r.state));
  end if;

  -- EXACT RESOURCE, AMOUNT AND CURRENCY. A mismatch is refused rather than rounded to the nearer of
  -- the two: "close enough" on money is the whole class of defect.
  if p_expect_amount is distinct from r.amount_aed then
    return jsonb_build_object('ok', false, 'reason',
      format('amount mismatch: the authorised refund is %s, the caller expected %s. Refusing rather than paying the difference in either direction.', r.amount_aed, p_expect_amount));
  end if;
  if upper(coalesce(p_expect_currency,'')) <> upper(r.currency) then
    return jsonb_build_object('ok', false, 'reason',
      format('currency mismatch: authorised in %s, caller expected %s.', r.currency, coalesce(p_expect_currency,'(none)')));
  end if;

  if r.attempts >= 5 then
    return jsonb_build_object('ok', false, 'reason',
      'retry policy exhausted at 5 attempts. The refund stays authorised and unpaid, which is a visible blocked state -- not a silent success and not an infinite retry against a provider that is down.');
  end if;

  -- THE DESTINATION IS DERIVED, NEVER PASSED. "Do not refund to an arbitrary new destination."
  select id, fee_status, reveal_fee, payment_ref into t
    from public.transactions where id = r.transaction_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'the settled payment behind this refund no longer exists; there is no destination of record to return money to.');
  end if;
  v_dest := t.payment_ref;
  v_basis := 'the original settled payment on transaction ' || r.transaction_id::text
          || '. Money returns the way it came; this function has no parameter for anywhere else.';
  if coalesce(v_dest,'') = '' then
    update public.refund_case set attempts = r.attempts + 1, last_attempt_at = now(),
      failure_reason = 'no payment reference on the settled transaction, so no destination of record.', updated_at = now()
     where refund_id = p_refund_id;
    return jsonb_build_object('ok', false, 'reason',
      'the settled payment carries no reference, so there is no destination of record. Held as authorised-and-blocked rather than sent somewhere plausible.');
  end if;

  v_state := case lower(coalesce(p_provider_outcome,''))
    when 'succeeded' then 'succeeded'
    when 'pending'   then 'provider_pending'
    when 'failed'    then 'failed'
    else 'submitted' end;

  update public.refund_case
     set state = v_state, destination_ref = v_dest, destination_basis = v_basis,
         provider_ref = p_provider_ref, provider_status = p_provider_outcome,
         submitted_at = coalesce(submitted_at, now()),
         settled_at = case when v_state = 'succeeded' then now() else settled_at end,
         failure_reason = case when v_state = 'failed' then coalesce(p_provider_outcome,'provider reported failure') else failure_reason end,
         attempts = r.attempts + 1, last_attempt_at = now(), updated_at = now()
   where refund_id = p_refund_id;

  return jsonb_build_object('ok', true, 'refund_id', p_refund_id, 'state', v_state,
    'destination_ref', v_dest, 'destination_basis', v_basis, 'attempt', r.attempts + 1,
    'note', case v_state
      when 'succeeded' then 'Settled at the provider. The customer still has to be TOLD -- succeeded is not communicated.'
      when 'failed' then 'The provider refused it. This stays visible and retriable within policy; it is not a closed case.'
      else 'Submitted. Submitted is not settled, and the status tool reads the provider, not this row''s optimism.' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_execution_requires_ceo_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_money_moved constant text[] := array['approved','processing','succeeded'];
  -- A refund Stripe already issued is a FACT to be recorded, not a request to be approved. Refusing
  -- the row would delete our only record of real money leaving, which is worse than admitting it.
  v_external    constant text[] := array['stripe_webhook','stripe_dashboard','stripe'];
  d public.ceo_approval%rowtype;
begin
  if not (new.status = any(v_money_moved)) then return new; end if;
  if tg_op = 'UPDATE' and old.status = any(v_money_moved)
     and new.refund_decision_id is not distinct from old.refund_decision_id then
    return new;   -- already past this boundary and not changing which decision it cites
  end if;
  if lower(coalesce(new.requested_by, '')) = any(v_external) then
    return new;
  end if;

  if new.refund_decision_id is null then
    raise exception 'refunds %: a platform-originated refund may not reach status % without naming the CEO decision that authorised it.',
      coalesce(new.id::text, '(new)'), new.status
      using errcode = '23514',
            hint = 'Record one in public.ceo_approval (subject_kind = ''refund'', subject_id = this '
                || 'refund''s id) and cite its decision_id. Founder ruling, 8 Sep 2026: all '
                || 'approvals are the CEO''s.';
  end if;

  select * into d from public.ceo_approval where decision_id = new.refund_decision_id;
  if not found then
    raise exception 'refunds %: refund_decision_id % names no CEO decision',
      coalesce(new.id::text, '(new)'), new.refund_decision_id using errcode = '23503';
  end if;
  if d.subject_kind <> 'refund' then
    raise exception 'refunds %: decision % is a % decision, not a refund decision',
      coalesce(new.id::text, '(new)'), d.decision_id, d.subject_kind using errcode = '23514';
  end if;

  -- THE BINDING THIS ROUTINE WAS MISSING UNTIL 9 SEP 2026. Everything above this line was already
  -- checked; subject_id was read and never compared, so one approved decision could authorise every
  -- refund in the table. ONE APPROVAL, ONE REFUND, ALWAYS.
  -- A TOP-UP (topup_of) completes the amount the CEO approved for its case, so it cites THAT decision
  -- (PR #640 re-review, 14 Sep 2026). Any other row still needs a decision naming itself.
  if d.subject_id is distinct from new.id::text
     and not (new.topup_of is not null and d.subject_id = new.topup_of::text) then
    raise exception 'refunds %: decision % approved refund %, not this one. One approval authorises one refund.',
      coalesce(new.id::text, '(new)'), d.decision_id, coalesce(d.subject_id, '(nothing)')
      using errcode = '23514',
            hint = 'The CEO decides each refund on its own facts. Reusing another refund''s approval '
                || 'would move money nobody approved. Record a ceo_approval row whose subject_id is '
                || 'this refund''s id, and cite that.';
  end if;

  if d.decision <> 'approved' then
    raise exception 'refunds %: decision % refused this refund; it may not reach %',
      coalesce(new.id::text, '(new)'), d.decision_id, new.status using errcode = '23514';
  end if;
  if d.superseded_by is not null then
    raise exception 'refunds %: decision % was superseded by %; cite the decision that stands',
      coalesce(new.id::text, '(new)'), d.decision_id, d.superseded_by using errcode = '23514';
  end if;
  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_refund_ladder_sweep()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  t record; st jsonb; v_window int; v_chase int; v_refund bigint;
  n_seen int := 0; n_chased int := 0; n_final int := 0; v_ids jsonb := '[]'::jsonb; v_watch jsonb; v_loop jsonb;
begin
  select refund_window_working_days, chase_after_working_days into v_window, v_chase from public.pricing_config order by id limit 1;
  v_window := coalesce(v_window, 5); v_chase := coalesce(v_chase, 3);

  for t in
    select x.* from public.transactions x
     where x.revealed_at is not null and coalesce(x.total_charged, x.reveal_fee, 0) > 0
       and coalesce(x.refund_status, '') not in ('approved', 'refunded', 'processing', 'succeeded', 'rejected', 'cancelled', 'failed')
       and x.revealed_at > now() - interval '120 days'
     order by x.revealed_at
  loop
    n_seen := n_seen + 1;
    st := public.fn_refund_state(t.id);
    continue when st ? 'error' or coalesce((st->>'supplier_responded')::boolean, false);
    continue when st->>'state' not in ('chase_due', 'final_call_due');

    if st->>'state' = 'chase_due' then
      perform public.fn_sales_engineer_ladder_step(t.id, 'chase', null, null);
      n_chased := n_chased + 1;
      v_ids := v_ids || jsonb_build_object('transaction_id', t.id, 'step', 'chase');
    else
      -- DAY 5: the refund is filed through the one door (fn_refund_request; the CEO decides, the guards
      -- on refunds refuse money moving any other way) and the sales engineer makes the final call.
      if not exists (select 1 from public.refunds r where r.transaction_id = t.id) then
        perform public.fn_refund_request(
          round(coalesce(t.total_charged, t.reveal_fee) * 100)::bigint, 'supplier_unresponsive', 'refund_ladder_sweep',
          t.inquiry_id, t.customer_id, t.supplier_id, t.quote_id, t.payment_ref, null,
          'Day ' || v_window || ' of the refund ladder: the supplier responded neither to the customer nor to the day-' || v_chase
            || ' chase. Filed by the ladder; the sales engineer makes the final call through support and the CEO decides on what comes back.',
          t.id);
      end if;
      select r.id into v_refund from public.refunds r where r.transaction_id = t.id order by r.id desc limit 1;
      perform public.fn_sales_engineer_ladder_step(t.id, 'final_call', v_refund, null);
      n_final := n_final + 1;
      v_ids := v_ids || jsonb_build_object('transaction_id', t.id, 'step', 'final_call', 'refund_id', v_refund);
    end if;
  end loop;

  v_watch := public.fn_customer_support_delivery_watch(null);
  v_loop  := public.fn_ceo_refund_loop_sweep();
  return jsonb_build_object('ok', true, 'seen', n_seen, 'chased', n_chased, 'final_calls', n_final,
                            'window_working_days', v_window, 'chase_after_working_days', v_chase,
                            'owner_agent', 'sales_engineer writes, customer_support delivers, ceo decides',
                            'cases', v_ids, 'support_watch', v_watch, 'ceo_loop', v_loop, 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_nonresponse_eligibility(p_transaction_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  w public.supplier_response_watch; c public.pricing_config;
  v_wd int; v_att int; v_ch int; v_reasons text[] := '{}';
begin
  select * into w from public.supplier_response_watch where transaction_id = p_transaction_id;
  select * into c from public.pricing_config limit 1;

  if w.id is null then
    return jsonb_build_object('eligible', false, 'basis', 'no_watch',
      'detail', 'Support has not recorded contacting this supplier at all, so there is no evidence of silence to decide on.');
  end if;

  -- WORKING days between the first attempt and now: Friday and Saturday are the UAE weekend.
  select count(*) into v_wd
    from generate_series((w.opened_at at time zone 'Asia/Dubai')::date,
                         (now()      at time zone 'Asia/Dubai')::date, interval '1 day') d
   where extract(isodow from d) not in (5, 6);
  v_wd := greatest(v_wd - 1, 0);   -- the opening day itself is not an elapsed day

  select count(*), count(distinct a->>'channel')
    into v_att, v_ch
    from jsonb_array_elements(w.attempts) a;

  if w.first_response_at is not null then
    v_reasons := v_reasons || ('the supplier replied on ' || w.first_response_at::text || ' via ' || coalesce(w.response_channel,'?'));
  end if;
  if v_wd < c.refund_window_working_days then
    v_reasons := v_reasons || (v_wd || ' working day(s) have passed of the ' || c.refund_window_working_days || ' the terms allow');
  end if;
  if v_att < c.supplier_nonresponse_min_attempts then
    v_reasons := v_reasons || ('support made ' || v_att || ' attempt(s), fewer than the ' || c.supplier_nonresponse_min_attempts || ' required');
  end if;
  if v_ch < c.supplier_nonresponse_min_channels then
    v_reasons := v_reasons || ('support used ' || v_ch || ' channel(s), fewer than the ' || c.supplier_nonresponse_min_channels || ' required');
  end if;

  return jsonb_build_object(
    'eligible', array_length(v_reasons,1) is null,
    'basis', 'measured',
    'transaction_id', p_transaction_id,
    'working_days_elapsed', v_wd,
    'working_days_required', c.refund_window_working_days,
    'attempts', v_att, 'attempts_required', c.supplier_nonresponse_min_attempts,
    'channels', v_ch, 'channels_required', c.supplier_nonresponse_min_channels,
    'supplier_replied', w.first_response_at is not null,
    'first_response_at', w.first_response_at,
    'blocking_reasons', coalesce(to_jsonb(v_reasons), '[]'::jsonb),
    'evidence', w.attempts);
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_nonresponse_needs_silence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v jsonb;
begin
  if new.decision is distinct from 'approved' then return new; end if;
  if coalesce(new.eligibility,'') is distinct from 'supplier_nonresponse' then return new; end if;

  v := public.fn_refund_nonresponse_eligibility(new.transaction_id);
  if (v->>'eligible')::boolean is not true then
    raise exception 'this refund is approved on supplier non-response, and the record does not show non-response: %',
      coalesce(v->>'blocking_reasons', v->>'detail');
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_open_from_customer(p_transaction_id uuid, p_requested_by text, p_reason_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  t public.transactions; c record; v_id bigint; v_open bigint; v_locale text; v_code text; v_en text; v_ar text;
  v_later boolean := false; v_paid text; v_decide text; v_req bigint; v_amt numeric;
begin
  select * into t from public.transactions where id = p_transaction_id;
  if not found then
    return jsonb_build_object('ok', false, 'code', 'no_such_transaction', 'locale', 'en', 'can_claim_later', false,
      'message_en', 'We could not find that reveal on your account.', 'message_ar', 'لم نعثر على عملية الكشف هذه في حسابكم.');
  end if;
  select id, email into c from public.customers where id = t.customer_id;
  v_locale := coalesce(public.fn_registered_locale('customer', t.customer_id, null, c.email), 'en');
  v_amt := round(coalesce(t.total_charged, t.reveal_fee, 0), 2);
  v_paid := to_char(t.revealed_at at time zone 'Asia/Dubai', 'DD Mon YYYY');
  v_decide := to_char(t.refund_deadline at time zone 'Asia/Dubai', 'DD Mon YYYY');

  -- ONE CLAIM PER PAYMENT: a second press, or a retry, returns the case already open.
  select id into v_open from public.refunds
   where transaction_id = t.id and status not in ('rejected', 'failed', 'cancelled')
     and lower(coalesce(requested_by, '')) not in ('stripe_webhook', 'stripe_dashboard', 'stripe')
   order by id limit 1;
  if v_open is not null then
    return jsonb_build_object('ok', true, 'duplicate', true, 'refund_id', v_open, 'locale', v_locale, 'decision_after', t.refund_deadline,
      'message_en', 'Your refund case QD-RF-' || v_open || ' is already open. Our chief executive decides it after ' || coalesce(v_decide, 'the fifth working day') || '; you do not need to do anything else.',
      'message_ar', 'حالة الاسترداد QD-RF-' || v_open || ' مفتوحة بالفعل، وسيبتّ فيها رئيسنا التنفيذي بعد ' || coalesce(v_decide, 'يوم العمل الخامس') || '، ولا يلزمكم أي إجراء آخر.');
  end if;

  -- THE REFUSALS, each with the reason and whether a claim can come later.
  if t.revealed_at is null then
    v_code := 'not_revealed'; v_later := true;
    v_en := 'This reveal has not completed yet. You can ask for a refund once the payment has gone through and the supplier''s details are shown to you.';
    v_ar := 'لم تكتمل عملية الكشف بعد. يمكنكم طلب الاسترداد بعد إتمام الدفع وظهور بيانات المورّد لكم.';
  elsif coalesce(btrim(t.payment_ref), '') = '' then
    v_code := 'no_payment'; v_later := true;
    v_en := 'We have no recorded payment for this reveal yet, so there is nothing to refund. If you were charged, reply to your payment receipt and we will match it; you can ask again once it is recorded.';
    v_ar := 'لا يوجد لدينا دفع مسجّل لعملية الكشف هذه حتى الآن، فلا مبلغ يُسترد. وإن خُصم منكم أي مبلغ، فيُرجى الرد على إيصال الدفع لنطابقه، ويمكنكم تقديم الطلب مجددًا بعد تسجيله.';
  elsif coalesce(t.refund_status, '') in ('approved', 'refunded', 'processing', 'succeeded') then
    v_code := 'already_refunded';
    v_en := 'This reveal has already been refunded (AED ' || coalesce(t.refund_amount_aed, v_amt) || '). Banks take 7 to 14 working days to show it.';
    v_ar := 'سبق أن استُردّت رسوم عملية الكشف هذه (' || coalesce(t.refund_amount_aed, v_amt) || ' درهم)، وتستغرق البنوك من 7 إلى 14 يوم عمل لإظهار المبلغ.';
  elsif exists (select 1 from public.refunds r where r.transaction_id = t.id and r.status = 'rejected'
                  and lower(coalesce(r.requested_by, '')) not in ('stripe_webhook', 'stripe_dashboard', 'stripe')) then
    v_code := 'already_declined';
    v_en := 'Our chief executive has already decided this case and declined it; the reason is shown on your refund case. Under section 5 of the Terms a decided case is not reopened by a new request. If you think the record is wrong, reply to the decision email.';
    v_ar := 'سبق أن بتّ رئيسنا التنفيذي في هذه الحالة ورفضها، والسبب مبيّن في حالة الاسترداد. ووفق البند 5 من الشروط، لا يُعاد فتح حالة بُتّ فيها بطلب جديد. وإن رأيتم أن السجل غير صحيح، فيُرجى الرد على رسالة القرار.';
  elsif exists (select 1 from public.inquiries i where i.id = t.inquiry_id and i.status in ('completed', 'closed') and i.hired_supplier_id = t.supplier_id) then
    v_code := 'job_completed';
    v_en := 'This job is marked as completed with this supplier, so the supplier responded and the reveal fee is not refundable (Terms, section 5).';
    v_ar := 'هذا العمل مسجّل مكتملًا مع هذا المورّد، ما يعني أنه استجاب، لذا لا تُسترد رسوم الكشف (الشروط، البند 5).';
  elsif exists (select 1 from public.reviews v where v.transaction_id = t.id) then
    v_code := 'supplier_rated';
    v_en := 'You have rated this supplier, which records that you dealt with them, so the reveal fee is not refundable (Terms, section 5).';
    v_ar := 'قيّمتم هذا المورّد، وهو ما يُثبت تعاملكم معه، لذا لا تُسترد رسوم الكشف (الشروط، البند 5).';
  end if;
  if v_code is not null then
    -- Recorded, so a refusal is as visible to the seats as a case: who asked, when, and why not.
    perform public.fn_emit('refund.request_refused', 'transaction', t.id::text, coalesce(p_requested_by, 'customer'),
      jsonb_build_object('transaction_id', t.id, 'customer_id', t.customer_id, 'code', v_code, 'can_claim_later', v_later, 'reason', v_en));
    return jsonb_build_object('ok', false, 'code', v_code, 'can_claim_later', v_later, 'locale', v_locale, 'message_en', v_en, 'message_ar', v_ar);
  end if;

  -- THE CASE. The amount is what the customer paid (total_charged); a00 holds it to that figure and to
  -- the payment's own Stripe reference. trg_emit_refund_requested and z30 put it on the bus and hand
  -- it to the accountant.
  insert into public.refunds
    (transaction_id, quote_id, inquiry_id, customer_id, supplier_lead_id,
     stripe_payment_intent, amount_fils, currency, reason_code, reason_note,
     status, requested_by, requested_at, amount_source)
  values
    (t.id, t.quote_id, t.inquiry_id, t.customer_id, t.supplier_id,
     t.payment_ref, round(coalesce(t.total_charged, t.reveal_fee, 0) * 100)::bigint, 'AED',
     'supplier_unresponsive',
     coalesce(p_reason_note, 'The customer reported that the revealed supplier has not responded.'),
     'requested', coalesce(p_requested_by, 'customer'), now(), 'in_platform_request')
  returning id into v_id;

  -- The sale follows the case, never the other way round. The refunds row already exists, so
  -- trg_emit_refund_requested_tx sees it and does not emit a second refund.requested.
  update public.transactions
     set refund_status = 'requested', refund_requested_at = coalesce(refund_requested_at, now())
   where id = t.id;

  -- The confirmation: the sales engineer writes it, customer support delivers it in the customer's
  -- registered language (fn_sales_engineer_writes -> delivery.request).
  v_req := public.fn_sales_engineer_writes('refund_request_received', 'customer', c.email, null, t.customer_id, t.inquiry_id, t.quote_id,
    'Your refund case QD-RF-' || v_id || ' is open',
    'We have opened refund case QD-RF-' || v_id || ' for the supplier you revealed on ' || coalesce(v_paid, 'your payment date') || '. You do not need to do anything else.' || E'\n\n'
      || 'The supplier has until ' || coalesce(v_decide, 'the fifth working day after your payment') || ' to respond. We chase them on the third working day and copy you. '
      || 'If there is still no response, our chief executive makes a final call and then decides your case on the record. '
      || 'If the refund is due, everything you paid (AED ' || v_amt || ') is returned to your original payment method; banks take 7 to 14 working days to show it.',
    'فتحنا حالة الاسترداد QD-RF-' || v_id,
    'فتحنا حالة الاسترداد QD-RF-' || v_id || ' بشأن المورّد الذي كشفتم عنه في ' || coalesce(v_paid, 'تاريخ الدفع') || '. لا يلزمكم أي إجراء آخر.' || E'\n\n'
      || 'أمام المورّد حتى ' || coalesce(v_decide, 'يوم العمل الخامس بعد الدفع') || ' للرد، وسنتابعه في يوم العمل الثالث مع نسخة إليكم، '
      || 'فإن لم يردّ، فسيوجّه إليه رئيسنا التنفيذي نداءً أخيرًا ثم يبتّ في حالتكم استنادًا إلى السجل. '
      || 'وإن ثبت استحقاق الاسترداد، فسيُردّ إليكم كامل ما دفعتموه (' || v_amt || ' درهم) إلى وسيلة الدفع الأصلية، وتستغرق البنوك من 7 إلى 14 يوم عمل لإظهاره.',
    '{}', 'refund_request_received:' || t.id, null,
    jsonb_build_object('step', 'customer_request', 'transaction_id', t.id, 'refund_id', v_id));

  return jsonb_build_object('ok', true, 'refund_id', v_id, 'status', 'requested', 'locale', v_locale,
    'decision_after', t.refund_deadline, 'delivery_request', v_req,
    'message_en', 'Refund case QD-RF-' || v_id || ' is open. Our chief executive decides it after ' || coalesce(v_decide, 'the fifth working day') || ', and if it is due everything you paid is refunded. We have emailed you the details.',
    'message_ar', 'فتحنا حالة الاسترداد QD-RF-' || v_id || '، وسيبتّ فيها رئيسنا التنفيذي بعد ' || coalesce(v_decide, 'يوم العمل الخامس') || '، وإن ثبت استحقاق الاسترداد فسيُردّ إليكم كامل ما دفعتموه. وقد أرسلنا إليكم التفاصيل بالبريد الإلكتروني.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_quarantine(p_stripe_refund_id text, p_event_type text, p_reason text, p_payload jsonb DEFAULT NULL::jsonb, p_stripe_event_id text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into public.refund_event_quarantine (stripe_refund_id, stripe_event_id, event_type, reason, payload)
  values (nullif(btrim(coalesce(p_stripe_refund_id,'')),''), nullif(btrim(coalesce(p_stripe_event_id,'')),''),
          p_event_type, p_reason, p_payload)
  returning id;
$function$


CREATE OR REPLACE FUNCTION public.fn_refund_read_status(p_refund_id bigint, p_mark_reported boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_say text;
begin
  select * into r from public.refund_case where refund_id = p_refund_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no such refund case'); end if;

  -- THE CUSTOMER-FACING SENTENCE IS DERIVED FROM THE STATE, not composed. "Support sends accurate
  -- pending/failed/succeeded updates" -- accurate meaning the words cannot drift from the row.
  v_say := case r.state
    when 'requested'      then 'I have your refund request and I am looking into it now.'
    when 'investigating'  then 'I am still checking the payment and the delivery on your inquiry.'
    when 'eligible'       then 'I have finished checking and your request is going for a decision.'
    when 'ineligible'     then 'I have checked this and it is not eligible for a refund. ' || coalesce(r.eligibility_reason,'')
    when 'ceo_authorized' then 'Your refund has been approved. It has not left us yet -- I will tell you the moment it is sent.'
    when 'ceo_declined'   then 'Your refund was not approved. ' || coalesce(r.decision_rationale,'')
    when 'submitted'      then 'Your refund has been sent to the payment provider. It is not settled yet.'
    when 'provider_pending' then 'Your refund is with the payment provider and is still processing.'
    when 'succeeded'      then 'Your refund has been paid back to the card or account you originally paid from.'
    when 'failed'         then 'The refund did not go through at the payment provider. It is not lost -- I am on it and will come back to you.'
    when 'canceled'       then 'This refund was cancelled before it was sent.'
    when 'reconciled'     then 'Your refund is complete and reconciled on our side.'
    when 'communicated'   then 'Your refund is complete and you have been notified.'
    else 'I am checking the current state of your refund.' end;

  if p_mark_reported then
    update public.refund_case
       set status_reported_at = now(), status_reported_state = r.state, updated_at = now()
     where refund_id = p_refund_id;
  end if;

  return jsonb_build_object('ok', true, 'refund_id', p_refund_id, 'state', r.state,
    'amount_aed', r.amount_aed, 'currency', r.currency, 'attempts', r.attempts,
    'provider_status', r.provider_status, 'destination_basis', r.destination_basis,
    'customer_message', v_say,
    -- A SUCCEEDED REFUND THE CUSTOMER HAS NOT BEEN TOLD ABOUT is an unfinished case, and this names it.
    'follow_through_owed', r.state in ('succeeded','failed','ceo_declined')
                           and (r.status_reported_state is distinct from r.state));
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_request(p_amount_fils bigint, p_reason_code text, p_requested_by text, p_inquiry_id uuid DEFAULT NULL::uuid, p_customer_id uuid DEFAULT NULL::uuid, p_supplier_lead_id bigint DEFAULT NULL::bigint, p_quote_id uuid DEFAULT NULL::uuid, p_payment_intent text DEFAULT NULL::text, p_charge_id text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_transaction_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id bigint; v_task bigint; v_in_window boolean := false; t public.transactions;
begin
  if p_amount_fils is null or p_amount_fils <= 0 then
    return jsonb_build_object('ok', false, 'error', 'amount_required');
  end if;

  select * into t from public.transactions
   where (p_transaction_id is not null and id = p_transaction_id)
      or (p_transaction_id is null and p_quote_id is not null and quote_id = p_quote_id)
      or (p_transaction_id is null and p_quote_id is null and p_payment_intent is not null and payment_ref = p_payment_intent)
   order by revealed_at desc nulls last limit 1;

  -- Recorded, never acted on. Whether the request arrived inside the window promised at reveal is
  -- exactly the kind of thing the decider wants in front of them, and exactly the kind of thing that
  -- must not decide for them.
  if t.id is not null and t.refund_deadline is not null and t.refund_deadline >= now() then
    v_in_window := true;
  end if;

  insert into public.refunds (transaction_id, inquiry_id, customer_id, supplier_lead_id, quote_id,
                              stripe_payment_intent, stripe_charge_id,
                              amount_fils, reason_code, reason_note, requested_by,
                              within_auto_window, status, reconciliation_note)
  values (t.id, coalesce(p_inquiry_id, t.inquiry_id), coalesce(p_customer_id, t.customer_id),
          coalesce(p_supplier_lead_id, t.supplier_id), coalesce(p_quote_id, t.quote_id),
          coalesce(p_payment_intent, t.payment_ref), p_charge_id,
          p_amount_fils, p_reason_code, p_note, p_requested_by,
          v_in_window, 'requested',
          'ROUTED TO THE CEO. Every refund waits for the CEO seat''s decision, whatever the amount '
       || 'and whether or not it is inside the promised window — founder ruling, 8 Sep 2026, '
       || 'replacing his 17 Aug rule that every refund needed him personally. This one is '
       || round(p_amount_fils / 100.0, 2) || ' AED and is '
       || case when v_in_window then 'inside' else 'outside' end || ' the window promised at reveal.')
  returning id into v_id;

  if t.id is not null then
    update public.transactions
       set refund_status = 'requested',
           refund_reason = coalesce(refund_reason, p_reason_code),
           refund_requested_at = coalesce(refund_requested_at, now()),
           refund_note = coalesce(p_note, refund_note)
     where id = t.id;
  end if;

  -- THE ROUTE. Without this the request is recorded and nothing is asked of anyone.
  insert into public.ceo_task (title, detail)
  values (
    'Decide refund ' || v_id || ' — AED ' || round(p_amount_fils / 100.0, 2),
    'Refund ' || v_id || ' requested by ' || coalesce(nullif(btrim(p_requested_by), ''), '(unknown)')
      || ' for ' || round(p_amount_fils / 100.0, 2) || ' AED, reason ' || coalesce(p_reason_code, '(none)')
      || '. Transaction ' || coalesce(t.id::text, '(none matched)')
      || '. The request arrived ' || case when v_in_window then 'INSIDE' else 'OUTSIDE' end
      || ' the refund window promised at reveal — a fact, not a decision.'
      || coalesce(chr(10) || 'Customer note: ' || nullif(btrim(p_note), ''), '')
      || chr(10) || chr(10)
      || 'To approve: write a row in public.ceo_approval (subject_kind = ''refund'') and set '
      || 'refunds.refund_decision_id to it. The guards on public.refunds will refuse the money moving '
      || 'any other way.')
  returning task_id into v_task;

  return jsonb_build_object('ok', true, 'refund_id', v_id, 'transaction_id', t.id,
                            'status', 'requested',
                            'within_auto_window', v_in_window,
                            'auto_approved', false,
                            'ceo_task_id', v_task,
                            'awaiting', 'ceo');
end
$function$


CREATE OR REPLACE FUNCTION public.fn_refund_request_hands_to_accountant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if NEW.transaction_id is not null and NEW.status = 'requested'
     and lower(coalesce(NEW.requested_by, '')) not in ('stripe_webhook', 'stripe_dashboard', 'stripe') then
    perform public.fn_seat_handoff('sales_engineer', 'accountant', 'refund.requested', 'refunds', NEW.id::text,
      jsonb_build_object('refund_id', NEW.id, 'transaction_id', NEW.transaction_id, 'customer_id', NEW.customer_id,
                         'inquiry_id', NEW.inquiry_id, 'quote_id', NEW.quote_id));
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_settle(p_stripe_refund_id text, p_status text, p_amount_fils bigint DEFAULT NULL::bigint, p_payment_intent text DEFAULT NULL::text, p_charge_id text DEFAULT NULL::text, p_failure_reason text DEFAULT NULL::text, p_amount_source text DEFAULT 'webhook_event'::text, p_stripe_event_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.refunds; v_status text; v_amount bigint; v_src text; v_q bigint;
begin
  if coalesce(btrim(p_stripe_refund_id),'') = '' then
    v_q := public.fn_refund_quarantine(null, 'refund', 'event carried no refund id',
             jsonb_build_object('status', p_status, 'payment_intent', p_payment_intent), p_stripe_event_id);
    return jsonb_build_object('ok', false, 'error', 'stripe_refund_id_required', 'quarantined', v_q);
  end if;

  v_status := case lower(coalesce(p_status,''))
                when 'succeeded' then 'succeeded' when 'failed' then 'failed'
                when 'canceled' then 'cancelled'  when 'cancelled' then 'cancelled'
                else 'processing' end;
  v_amount := nullif(coalesce(p_amount_fils, 0), 0);
  v_src    := case when v_amount is null then null else coalesce(p_amount_source, 'webhook_event') end;

  select * into r from public.refunds where stripe_refund_id = p_stripe_refund_id for update;

  if not found then
    select * into r from public.refunds
     where stripe_refund_id is null and p_payment_intent is not null
       and stripe_payment_intent = p_payment_intent and status in ('approved','processing','requested')
     order by created_at limit 1 for update;

    if found then
      update public.refunds set stripe_refund_id = p_stripe_refund_id,
             stripe_charge_id = coalesce(p_charge_id, stripe_charge_id) where id = r.id;
    else
      -- Issued outside the platform. Recorded with whatever is actually known, and NOTHING invented:
      -- if the amount is unknown it stays NULL and the row is marked unreconciled.
      insert into public.refunds (stripe_refund_id, stripe_payment_intent, stripe_charge_id,
                                  amount_fils, amount_source, reason_code, reason_note, requested_by, status,
                                  decided_by, decided_at, decision_note, reconciliation_note)
      values (p_stripe_refund_id, p_payment_intent, p_charge_id, v_amount,
              coalesce(v_src, 'unknown'), 'other',
              'Issued outside QuotesDone (Stripe dashboard or API). Recorded by the webhook.',
              'stripe_webhook', coalesce(v_status, 'processing'), 'stripe_dashboard', now(),
              'No in-platform request existed for this refund.',
              case when v_amount is null
                   then 'AMOUNT UNKNOWN - the event carried none and Stripe could not be read. Excluded from all financial totals until resolved.'
                   else null end)
      returning * into r;

      if v_amount is null then
        perform public.fn_refund_quarantine(p_stripe_refund_id, 'refund',
          'amount unknown: absent from the event and not retrievable from Stripe',
          jsonb_build_object('status', v_status, 'payment_intent', p_payment_intent, 'refund_row', r.id),
          p_stripe_event_id);
      end if;

      return jsonb_build_object('ok', true, 'refund_id', r.id, 'status', r.status, 'applied', true,
                                'created', true, 'amount_known', v_amount is not null);
    end if;
  end if;

  -- Duplicate delivery: same state twice. Cheap, silent, correct - but still take the chance to fill
  -- in an amount we did not have before.
  if r.status = v_status then
    if r.amount_fils is null and v_amount is not null then
      update public.refunds
         set amount_fils = v_amount, amount_source = v_src,
             reconciliation_note = 'amount resolved from a later ' || coalesce(p_amount_source,'event'),
             updated_at = now()
       where id = r.id;
      return jsonb_build_object('ok', true, 'refund_id', r.id, 'status', r.status,
                                'idempotent', true, 'applied', false, 'amount_resolved', true);
    end if;
    return jsonb_build_object('ok', true, 'refund_id', r.id, 'status', r.status,
                              'idempotent', true, 'applied', false);
  end if;

  -- The matrix decides. Not a rank, not an ordering heuristic - a declared policy with a reason
  -- attached to every refusal.
  if not public.fn_refund_transition_allowed(r.status, v_status) then
    v_q := public.fn_refund_quarantine(p_stripe_refund_id, 'refund',
      'transition not permitted: ' || r.status || ' -> ' || v_status || '. '
      || coalesce((select note from public.refund_status_transition
                    where from_status = r.status and to_status = v_status), 'no rule declared for this pair'),
      jsonb_build_object('refund_row', r.id, 'from', r.status, 'to', v_status,
                         'amount_fils', p_amount_fils, 'payment_intent', p_payment_intent),
      p_stripe_event_id);
    update public.refunds
       set reconciliation_note = left(coalesce(reconciliation_note || ' | ', '')
           || 'refused ' || r.status || '->' || v_status || ' at ' || to_char(now(),'YYYY-MM-DD HH24:MI'), 500),
           updated_at = now()
     where id = r.id;
    return jsonb_build_object('ok', true, 'refund_id', r.id, 'status', r.status, 'applied', false,
                              'refused_transition', r.status || '->' || v_status, 'quarantined', v_q);
  end if;

  update public.refunds
     set status = v_status,
         amount_fils   = coalesce(v_amount, amount_fils),
         amount_source = case when v_amount is not null then v_src else amount_source end,
         stripe_charge_id = coalesce(p_charge_id, stripe_charge_id),
         stripe_payment_intent = coalesce(p_payment_intent, stripe_payment_intent),
         settled_at = case when v_status = 'succeeded' then coalesce(settled_at, now()) else settled_at end,
         failure_reason = case when v_status = 'failed' then p_failure_reason else failure_reason end,
         reconciliation_note = case
             when v_status = 'succeeded' and coalesce(v_amount, amount_fils) is null
             then 'AMOUNT UNKNOWN on a settled refund - excluded from all financial totals until resolved.'
             else reconciliation_note end,
         updated_at = now()
   where id = r.id;

  if r.transaction_id is not null then
    update public.transactions
       set refund_status = v_status, refund_stripe_id = p_stripe_refund_id,
           refund_amount_aed = case when v_amount is not null then round(v_amount/100.0, 2) else refund_amount_aed end,
           refund_confirmed_at = case when v_status = 'succeeded' then coalesce(refund_confirmed_at, now())
                                      else refund_confirmed_at end
     where id = r.transaction_id;
  end if;

  return jsonb_build_object('ok', true, 'refund_id', r.id, 'status', v_status, 'applied', true,
                            'amount_known', coalesce(v_amount, r.amount_fils) is not null);
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_state(p_transaction uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t record; v_window int; v_chase int; v_notify_days int; v_min int; v_max int;
        v_responded boolean; v_chase_at timestamptz; v_final_at timestamptz; v_notify_at timestamptz;
        v_chased_at timestamptz; v_final_sent_at timestamptz; v_state text;
begin
  select * into t from transactions where id = p_transaction;
  if not found then return jsonb_build_object('error','transaction_not_found'); end if;

  -- THE LADDER (founder, 6 Sep 2026): the clock starts when the customer PAYS (revealed_at), never at
  -- a nudge or a notice. Day 3 without a supplier response: the owning employee chases. Day 5: the
  -- founder is notified for the final call and the refund becomes approvable. All from pricing_config.
  select refund_window_working_days, chase_after_working_days,
         bank_settlement_working_days_min, bank_settlement_working_days_max
    into v_window, v_chase, v_min, v_max from pricing_config order by id limit 1;
  v_window := coalesce(v_window, 5); v_chase := coalesce(v_chase, 3);
  v_notify_days := coalesce((select value::text::int from decision_policy where key='refund_notify_after_working_days'),1);

  v_responded := t.supplier_ack_at is not null
    or exists (select 1 from messages m
               where m.inquiry_id = t.inquiry_id and m.supplier_id = t.supplier_id
                 and m.sender = 'supplier' and coalesce(m.blocked,false) = false
                 and m.created_at > t.revealed_at);

  v_chase_at  := case when t.revealed_at is null then null else public.fn_add_working_days(t.revealed_at, v_chase) end;
  v_final_at  := case when t.revealed_at is null then null
                      else coalesce(t.refund_deadline, public.fn_add_working_days(t.revealed_at, v_window)) end;
  v_notify_at := case when t.revealed_at is null then null else public.fn_add_working_days(t.revealed_at, v_notify_days) end;

  select min(n.created_at) into v_chased_at from notifications n
   where n.type = 'supplier_no_response_chase' and n.channel = 'email'
     and n.inquiry_id = t.inquiry_id and n.lead_id = t.supplier_id
     and t.revealed_at is not null and n.created_at > t.revealed_at;
  -- The day-5 final call is the sales engineer's notice delivered by support (type refund_final_notice).
  -- The founder_alerts marker the ladder wrote before 14 Sep is still honoured for cases already on it.
  select least((select min(n.created_at) from notifications n
                 where n.type = 'refund_final_notice' and n.inquiry_id = t.inquiry_id and n.lead_id = t.supplier_id
                   and t.revealed_at is not null and n.created_at > t.revealed_at),
               (select min(f.created_at) from founder_alerts f where f.dedupe_key = 'refund_final_call:' || t.id::text))
    into v_final_sent_at;

  v_state := case
    when t.revealed_at is null                                                          then 'not_revealed'
    when v_responded                                                                    then 'supplier_responded'
    when coalesce(t.refund_status,'') in ('approved','refunded','processing','succeeded') then 'refunded'
    when coalesce(t.refund_status,'') = 'rejected'                                      then 'refund_rejected'
    when now() < v_chase_at                                                             then 'waiting'
    when now() < v_final_at then case when v_chased_at is null then 'chase_due' else 'chased' end
    else case when v_final_sent_at is null then 'final_call_due' else 'final_call_sent' end end;

  return jsonb_build_object(
    'transaction_id', t.id,
    'state', v_state,
    'revealed_at', t.revealed_at,
    'supplier_responded', v_responded,
    'refund_window_working_days', v_window,
    'chase_after_working_days', v_chase,
    'chase_due_at', v_chase_at,
    'chased_at', v_chased_at,
    'founder_call_due_at', v_final_at,
    'final_call_sent_at', v_final_sent_at,
    'refund_deadline', t.refund_deadline,
    'notify_available_at', v_notify_at,
    'can_notify', (t.revealed_at is not null and not v_responded and t.customer_notified_at is null
                   and now() >= v_notify_at and v_state not in ('refunded','refund_rejected')),
    'notified_at', t.customer_notified_at,
    'auto_nudged_at', t.nudged_24_at,
    'refund_approvable', v_state in ('final_call_due','final_call_sent'),
    'refund_status', t.refund_status,
    'working_days_since_reveal', case when t.revealed_at is null then 0
                                      else public.fn_working_days_between(t.revealed_at, now()) end,
    'working_days_since_notice', case when t.customer_notified_at is null then 0
                                      else public.fn_working_days_between(t.customer_notified_at, now()) end,
    'bank_settlement_working_days', coalesce(v_min,7)::text || '-' || coalesce(v_max,14)::text
  );
end $function$


CREATE OR REPLACE FUNCTION public.fn_refund_transition_allowed(p_from text, p_to text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce((select allowed from public.refund_status_transition
                    where from_status = p_from and to_status = p_to), false);
$function$


CREATE OR REPLACE FUNCTION public.fn_refunds_never_return_more_than_was_paid()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare t public.transactions; v_cap bigint; v_other bigint;
begin
  -- EVERY WRITER LOCKS THE PAYMENT FIRST (PR #640 re-review, 14 Sep 2026). A reservation, a case, a
  -- retry and a refund Stripe reported (fn_refund_settle writes those with no transaction_id, only the
  -- payment reference) all serialise on the same transactions row, so a webhook row cannot slip in
  -- between a reservation's sum and its insert. The lock is taken BEFORE any exemption.
  if NEW.transaction_id is not null then
    select * into t from public.transactions where id = NEW.transaction_id for update;
  elsif coalesce(btrim(NEW.stripe_payment_intent), '') <> '' then
    select * into t from public.transactions where payment_ref = NEW.stripe_payment_intent
     order by revealed_at desc nulls last limit 1 for update;
  end if;
  -- A refund Stripe already issued is a fact to record, never refused; it is counted below for
  -- every later writer (rows are matched by transaction OR by the payment's Stripe reference).
  if lower(coalesce(NEW.requested_by, '')) in ('stripe_webhook', 'stripe_dashboard', 'stripe') then return NEW; end if;
  if t.id is null or NEW.status in ('failed', 'rejected', 'cancelled') then return NEW; end if;   -- a00 refuses a missing transaction with its own reason
  v_cap := round(coalesce(t.total_charged, t.reveal_fee, 0) * 100)::bigint;
  select coalesce(sum(r.amount_fils), 0) into v_other
    from public.refunds r
   where r.id is distinct from NEW.id and r.status not in ('failed', 'rejected', 'cancelled')
     and (r.transaction_id = t.id or (coalesce(btrim(t.payment_ref), '') <> '' and r.stripe_payment_intent = t.payment_ref));
  if v_other + coalesce(NEW.amount_fils, 0) > v_cap then
    raise exception 'refunds: transaction % took % fils and % fils are already refunded or on their way, so % more would return more than the customer paid. (refund_exceeds_what_was_paid)',
      t.id, v_cap, v_other, coalesce(NEW.amount_fils, 0) using errcode = '23514';
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_refunds_paused()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce((select (d.value #>> '{}')::boolean from public.decision_policy d
                    where d.key = 'refunds_and_supplier_charges_paused'), false);
$function$


CREATE OR REPLACE FUNCTION public.fn_refunds_settled_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.status = 'succeeded' and new.settled_at is null then new.settled_at := now(); end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_register_document(p_bucket text, p_path text, p_kind text, p_ref_table text, p_ref_id text, p_file_name text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_kind text;
begin
  if p_path is null or p_path = '' then return; end if;
  v_kind := lower(btrim(coalesce(p_kind, '')));
  v_kind := case v_kind
    when 'quotation'      then 'quote'
    when 'quotations'     then 'quote'
    when 'quotes'         then 'quote'
    when 'agreement'      then 'contract'
    when 'agreements'     then 'contract'
    when 'contracts'      then 'contract'
    when 'bill'           then 'invoice'
    when 'bills'          then 'invoice'
    when 'invoices'       then 'invoice'
    when 'license'        then 'licence'
    when 'licenses'       then 'licence'
    when 'licences'       then 'licence'
    when 'cert'           then 'certificate'
    when 'certs'          then 'certificate'
    when 'certificates'   then 'certificate'
    when 'dwg'            then 'drawing'
    when 'drawings'       then 'drawing'
    when 'plan'           then 'drawing'
    when 'plans'          then 'drawing'
    when 'boq'            then 'drawing'
    when 'po'             then 'purchase_order'
    when 'pos'            then 'purchase_order'
    when 'purchase order' then 'purchase_order'
    when 'purchase-order' then 'purchase_order'
    else v_kind
  end;
  if v_kind is null or v_kind = '' then v_kind := 'other'; end if;
  insert into public.documents(bucket, path, kind, ref_table, ref_id, file_name)
  values (p_bucket, p_path, v_kind, p_ref_table, p_ref_id,
          coalesce(p_file_name, split_part(p_path, '/', array_length(string_to_array(p_path, '/'), 1))))
  on conflict (bucket, path) do nothing;
end $function$


CREATE OR REPLACE FUNCTION public.fn_registered_locale(p_role text, p_customer uuid DEFAULT NULL::uuid, p_lead bigint DEFAULT NULL::bigint, p_email text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- null ONLY when nobody is registered under these keys (a sign-up in progress): the caller then uses
  -- the language of the page the person is registering on. A registered row always answers en or ar.
  select case when x is null then null when lower(x) like 'ar%' then 'ar' else 'en' end
    from (select case
      when p_role = 'customer' then coalesce(
        (select c.locale from public.customers c where c.id = p_customer),
        (select c.locale from public.customers c
          where p_email is not null and lower(c.email) = lower(btrim(p_email)) limit 1))
      when p_role = 'supplier' then coalesce(
        (select l.locale from public.leads l where l.id = p_lead),
        (select l.locale from public.leads l
          where p_email is not null
            and (lower(l.claimed_by) = lower(btrim(p_email)) or lower(l.email) = lower(btrim(p_email)))
          order by (lower(l.claimed_by) = lower(btrim(p_email))) desc nulls last, l.id limit 1))
    end as x) s
$function$


CREATE OR REPLACE FUNCTION public.fn_rehearsal_window_covers(p_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select exists (
    select 1 from public.rehearsal_window w
    where p_at >= w.started_at
      and p_at <= coalesce(w.ended_at, w.started_at + interval '6 hours')
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_render_template(p_text text, p_vars jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k text; v text; r text := p_text;
begin
  if r is null then return null; end if;
  for k, v in select key, value #>> '{}' from jsonb_each(coalesce(p_vars, '{}'::jsonb)) loop
    r := replace(r, '{{' || k || '}}', coalesce(v, ''));
  end loop;
  return r;
end $function$


CREATE OR REPLACE FUNCTION public.fn_report_drilldown(p_metric text, p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with b as (select coalesce(nullif(btrim(p_metric), ''), '~none~') m,
                    greatest(coalesce(p_days, 30), 1) d),
  series as (
    select s.taken_at, s.value from public.metric_snapshot s, b
     where s.metric_key ilike '%' || b.m || '%'
       and s.taken_at > now() - (b.d || ' days')::interval
     order by s.taken_at desc limit 60
  )
  select jsonb_build_object(
    'metric', (select m from b), 'window_days', (select d from b),

    -- WHY IT MOVED: the last two readings, and the change between them.
    'series', coalesce((select jsonb_agg(jsonb_build_object('at', taken_at, 'value', value) order by taken_at desc) from series), '[]'::jsonb),
    'latest', (select value from series order by taken_at desc limit 1),
    'previous', (select value from series order by taken_at desc offset 1 limit 1),
    'change', (select (select value from series order by taken_at desc limit 1)
                    - (select value from series order by taken_at desc offset 1 limit 1)),
    'readings', (select count(*) from series),

    'index', (select jsonb_build_object('index_name', c.index_name, 'score', c.score, 'band', c.band,
                'measured_on', c.measured_on, 'dimensions', c.dimensions)
                from public.company_index c, b
               where c.index_name ilike '%' || b.m || '%'
               order by c.measured_on desc limit 1),

    -- THE TARGET it is measured against.
    'target', (select jsonb_build_object('goal_key', g.goal_key, 'horizon', g.horizon,
                 'period_label', g.period_label, 'target_value', g.target_value,
                 'actual_value', g.actual_value, 'status', g.status,
                 'gap', g.target_value - g.actual_value, 'updated_at', g.updated_at)
                from public.goal_period g, b
               where g.goal_key ilike '%' || b.m || '%'
               order by g.updated_at desc limit 1),

    -- WHO CONTRIBUTED: the decisions that named this metric in the window.
    'contributors', coalesce((select jsonb_agg(jsonb_build_object(
          'actor', l.actor, 'os', public.fn_owning_os(l.actor), 'kind', l.kind,
          'decision', l.decision, 'confidence', l.confidence, 'at', l.created_at)
        order by l.created_at desc)
      from (select l.* from public.decision_log l, b
             where l.created_at > now() - (b.d || ' days')::interval
               and (l.decision ilike '%' || b.m || '%' or l.ctx::text ilike '%' || b.m || '%')
             order by l.created_at desc limit 10) l), '[]'::jsonb),
    'generated_at', now()
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_report_recommendation_approve(p_report_id bigint, p_index integer, p_by text, p_source text DEFAULT 'exec_reports'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_rec jsonb; v_title text; v_id bigint; v_officer text; v_dept text; v_task bigint;
begin
  if p_source = 'exec_reports' then
    select r.recommendations -> p_index, r.officer into v_rec, v_officer
      from public.exec_reports r where r.id = p_report_id;
  else
    select r.kpis -> p_index, 'board' into v_rec, v_officer
      from public.board_reports r where r.id = p_report_id;
  end if;
  if v_rec is null then
    return jsonb_build_object('ok', false, 'error', 'no recommendation at that index');
  end if;
  v_title := coalesce(v_rec ->> 'title', v_rec ->> 'recommendation', left(v_rec::text, 160));

  insert into public.agent_actions(agent, kind, status, risk, title, recommendation,
      target_table, target_id, decided_by, decided_at, detail)
    values (coalesce(v_officer, 'exec'), 'report_recommendation', 'approved',
      coalesce(v_rec ->> 'risk', 'medium'), v_title, v_rec::text,
      p_source, p_report_id::text, p_by, now(),
      jsonb_build_object('report_id', p_report_id, 'index', p_index, 'source', p_source, 'recommendation', v_rec))
    returning id into v_id;

  -- ROUTE IT AS REAL WORK. The department is the accountable officer's; a05_org_task_fill_ownership
  -- gives it an owner and, when the recommendation names a goal, ties it to that objective. Idempotent
  -- on the report+index marker, so approving the same recommendation twice does not double the work.
  v_dept := coalesce((select department from public.org_agents
                        where agent_key = coalesce(public.fn_org_agent_resolve(v_officer), v_officer)), 'exec');
  select id into v_task from public.org_tasks t
   where t.action_class = 'report_recommendation'
     and t.detail like '%report #'||p_report_id||' rec '||p_index||' by %'
     and t.status <> 'done'
   order by id limit 1;
  if v_task is null then
    insert into public.org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
    values (v_dept, v_title,
      coalesce(v_rec ->> 'why', v_rec ->> 'recommendation', v_title)
        ||'  [Approved from the '||p_source||' report #'||p_report_id||' rec '||p_index||' by '||p_by
        ||'. Do it, or bring evidence the standard is wrong.]',
      'assigned', 'advisory', false, 'report_recommendation')
    returning id into v_task;
    update public.agent_actions set detail = detail || jsonb_build_object('org_task_id', v_task) where id = v_id;
  end if;

  return jsonb_build_object('ok', true, 'action_id', v_id, 'org_task_id', v_task,
                            'title', v_title, 'report_id', p_report_id);
end $function$


CREATE OR REPLACE FUNCTION public.fn_reputation_recompute()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r record; n int := 0; v_score numeric; v_tier text;
  v_gated int := 0; v_restored int := 0; v_unmeasured int := 0; v_provisional int := 0;
  v_hold record;
  k_prior constant numeric := 5;    -- weight of the neutral prior, in observations
  k_mid   constant numeric := 50;   -- the prior itself
  k_floor constant numeric := 10;   -- observations needed before a tier other than standard is assigned
  -- per-dimension (hits, n)
  c_hit numeric; c_n numeric;  q_hit numeric; q_n numeric;  l_hit numeric; l_n numeric;
  e_hit numeric; e_n numeric;  b_hit numeric; b_n numeric;  y_hit numeric; y_n numeric;
  v_corr numeric; v_decq numeric; v_learn numeric; v_cost numeric; v_collab numeric; v_rel numeric;
  v_total numeric; v_dims int; v_provisional_row boolean;
  post constant text := 'posterior';
begin
  -- A hold the founder actually holds open still pauses scoring; authority must not move under it.
  select s.id, s.stood_down_at into v_hold
    from public.company_stand_down s where s.resumed_at is null
   order by s.stood_down_at desc limit 1;
  if v_hold.id is not null then
    return jsonb_build_object('ok', false, 'status', 'PAUSED_BY_FOUNDER_STANDDOWN',
      'scored', 0, 'gated', 0, 'restored', 0, 'unmeasured', 0,
      'stand_down_id', v_hold.id, 'since', v_hold.stood_down_at,
      'note', 'No employee is scored, promoted or demoted while a stand-down is open.');
  end if;

  for r in select a.agent_key from public.org_agents a order by a.agent_key loop
    -- correctness: graded outcomes of its actions + review verdicts on work it authored
    select count(*) filter (where verdict = 'improved'),
           count(*) filter (where verdict in ('improved','no_change','worse'))
      into c_hit, c_n from public.outcome_record where actor = r.agent_key;
    select c_hit + count(*) filter (where decision = 'approve'),
           c_n + count(*)
      into c_hit, c_n from public.review_chain
     where author_agent = r.agent_key and decision in ('approve','reject','request_revision');

    -- decision quality: decisions a human could review (confidence + source + reason)
    select count(*) filter (where l.confidence is not null
                              and l.sources is not null and l.sources::text not in ('null','[]','{}','""')
                              and l.reasons is not null and l.reasons::text not in ('null','[]','{}','""')),
           count(*)
      into q_hit, q_n from public.decision_log l where l.actor = r.agent_key;

    -- learning speed: graded training attempts it passed
    select count(*) filter (where passed), count(*)
      into l_hit, l_n from public.agent_training_attempt
     where agent_key = r.agent_key and passed is not null;

    -- cost efficiency: calls a cheaper model could NOT have served
    select count(*) filter (where not coalesce(could_be_cheaper, false)), count(*)
      into e_hit, e_n from public.ai_cost_log where agent_key = r.agent_key;

    -- collaboration: reviews it gave as reviewer that carry a reason
    select count(*) filter (where nullif(btrim(coalesce(reason,'')), '') is not null), count(*)
      into b_hit, b_n from public.review_chain
     where reviewer_agent = r.agent_key and decision in ('approve','reject','request_revision','hold');

    -- reliability: assigned tasks that reached done (escalated counts against; cancelled excluded)
    -- + runs under its own key that did not error
    select count(*) filter (where status = 'done'), count(*)
      into y_hit, y_n from public.org_tasks
     where assigned_agent = r.agent_key and status in ('done','escalated');
    select y_hit + count(*) filter (where status <> 'error'), y_n + count(*)
      into y_hit, y_n from public.agent_runs where agent = r.agent_key;

    v_corr  := round((k_mid*k_prior + 100.0*c_hit) / (k_prior + c_n), 1);
    v_decq  := round((k_mid*k_prior + 100.0*q_hit) / (k_prior + q_n), 1);
    v_learn := round((k_mid*k_prior + 100.0*l_hit) / (k_prior + l_n), 1);
    v_cost  := round((k_mid*k_prior + 100.0*e_hit) / (k_prior + e_n), 1);
    v_collab:= round((k_mid*k_prior + 100.0*b_hit) / (k_prior + b_n), 1);
    v_rel   := round((k_mid*k_prior + 100.0*y_hit) / (k_prior + y_n), 1);
    v_total := c_n + q_n + l_n + e_n + b_n + y_n;
    v_dims  := (c_n > 0)::int + (q_n > 0)::int + (l_n > 0)::int + (e_n > 0)::int + (b_n > 0)::int + (y_n > 0)::int;
    v_provisional_row := false;

    if v_total = 0 then
      v_score := null; v_tier := 'unmeasured'; v_unmeasured := v_unmeasured + 1;
    else
      v_score := round(v_corr*0.30 + v_rel*0.30 + v_cost*0.15 + v_learn*0.15 + v_collab*0.10, 1);
      if v_total < k_floor or v_dims < 2 then
        v_tier := 'standard'; v_provisional_row := true; v_provisional := v_provisional + 1;
      else
        v_tier := case when v_score >= 85 then 'senior_trusted'
                       when v_score >= 70 then 'trusted'
                       when v_score >= 50 then 'standard' else 'probation' end;
      end if;
    end if;

    insert into public.agent_reputation
      (agent_key, correctness, reliability, cost_efficiency, learning_speed, collaboration,
       decision_quality, score, tier, computed_at, evidence)
    values (r.agent_key, v_corr, v_rel, v_cost, v_learn, v_collab, v_decq, v_score, v_tier, now(),
            jsonb_build_object('method', post, 'prior', k_mid, 'prior_weight', k_prior,
              'tier_floor', k_floor, 'provisional', v_provisional_row, 'dimensions_with_evidence', v_dims,
              'correctness', c_n, 'decision_quality', q_n, 'learning_speed', l_n,
              'cost_efficiency', e_n, 'collaboration', b_n, 'reliability', y_n, 'total', v_total))
    on conflict (agent_key) do update set
      correctness = excluded.correctness, reliability = excluded.reliability,
      cost_efficiency = excluded.cost_efficiency, learning_speed = excluded.learning_speed,
      collaboration = excluded.collaboration, decision_quality = excluded.decision_quality,
      score = excluded.score, tier = excluded.tier, computed_at = now(), evidence = excluded.evidence;
    n := n + 1;
  end loop;

  -- probation is a real consequence: any agent below the floor loses autonomous authority.
  with demoted as (
    update public.employee_authority a set max_tier = 'gated'
      from public.agent_reputation p
     where p.agent_key = a.agent_key and p.tier = 'probation' and a.max_tier = 'autonomous'
    returning a.agent_key, a.action_class)
  insert into public.autonomy_control_audit (object, op, direction, old_value, new_value, reason)
  select 'employee_authority:' || agent_key || '/' || action_class, 'reputation_demote', 'tighten',
         'autonomous', 'gated', 'reputation tier fell to probation'
    from demoted;
  get diagnostics v_gated = row_count;

  -- ...and recovery is a real consequence too: a grant this routine demoted comes back when the
  -- tier is no longer probation, and an advisory-safe grant comes back on any earned tier.
  with restored as (
    update public.employee_authority a set max_tier = 'autonomous'
      from public.agent_reputation p
     where p.agent_key = a.agent_key
       and a.max_tier = 'gated'
       and p.tier in ('standard','trusted','senior_trusted')
       and (a.note = 'Advisory-safe action, may run autonomously'
            or exists (select 1 from public.autonomy_control_audit u
                        where u.op = 'reputation_demote'
                          and u.object = 'employee_authority:' || a.agent_key || '/' || a.action_class
                          and not exists (select 1 from public.autonomy_control_audit v
                                           where v.op = 'reputation_restore' and v.object = u.object and v.at > u.at)))
    returning a.agent_key, a.action_class)
  insert into public.autonomy_control_audit (object, op, direction, old_value, new_value, reason)
  select 'employee_authority:' || agent_key || '/' || action_class, 'reputation_restore', 'loosen',
         'gated', 'autonomous',
         'reputation tier is no longer probation (a tier below standard needs 10 observations on two dimensions); a demotion this routine made is lifted'
    from restored;
  get diagnostics v_restored = row_count;

  insert into public.agent_runs (agent, started_at, finished_at, status, counts, note)
  values ('reputation', now(), now(), 'ok',
    jsonb_build_object('scored', n, 'gated', v_gated, 'restored', v_restored, 'unmeasured', v_unmeasured, 'provisional', v_provisional),
    'Reputation recomputed for ' || n || ' employee(s) on six dimensions from recorded facts '
    || '(posterior mean, prior 50 with weight 5; evidence counts stored per dimension). '
    || v_unmeasured || ' have no evidence on any dimension and carry a NULL score; ' || v_provisional
    || ' are provisional standard with fewer than 10 observations or evidence on one dimension only. '
    || 'Probation demoted ' || v_gated || ' autonomous grant(s) to gated; recovery restored ' || v_restored || '.');
  return jsonb_build_object('ok', true, 'scored', n, 'gated', v_gated, 'restored', v_restored,
                            'unmeasured', v_unmeasured, 'provisional', v_provisional);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_resilience_orphan_steps_due()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    -- coalesce, not '<>': a missing row must read as "not enabled", which is the state that needs
    -- reporting. A gate that opens only when a key is present and wrong is a gate that a deleted key
    -- switches off silently.
    'email_cron',   coalesce((select value from public.app_secrets where key = 'email_enabled'), '') is distinct from 'true',

    -- THE FLAG ARM, unchanged: an estate that has never had an approved set polls until it does.
    -- THE WORK ARM, added 22 Sep 2026: something is still pending and nobody has asked about it
    -- today. 'received' is Twilio's word for submitted-and-undecided; anything that is neither
    -- approved nor rejected is undecided, so the condition is written as the absence of a verdict
    -- rather than as a list of the words Twilio currently uses for waiting.
    'wa_templates', coalesce((select value from public.app_secrets where key = 'wa_templates_ready'), '') is distinct from 'true'
      or exists (
        select 1 from public.messaging_template
         where channel = 'whatsapp'
           and status not in ('approved', 'rejected')
           and (last_checked_at is null or last_checked_at < now() - interval '20 hours')),

    -- The queue is the gate. No flag, because nothing here costs a model call and a queued SMS has a
    -- person at the end of it.
    'send_sms', exists (
      select 1 from public.notifications where channel = 'sms' and status = 'queued'),

    -- Both halves must hold: the switch is on AND there is work. Either alone would be a step that runs
    -- for nothing 96 times a day.
    'doc_extract', coalesce((select value from public.app_secrets where key = 'doc_extract_drain_enabled'), '') = 'true'
      and exists (
        select 1 from public.documents
         where status in ('pending', 'error') and coalesce(attempts, 0) < 3),

    'email_triage', coalesce((select value from public.app_secrets where key = 'email_triage_enabled'), '') = 'true'
      and exists (
        select 1 from public.inbound_messages
         where needs_review and triaged_at is null and replied_at is null),

    -- WEEKLY, MEASURED OFF THE WORK ITSELF rather than a schedule string, AND PER SOURCE. Due while
    -- EITHER list lacks a recent enough attempt: an `ok` run holds that source for 6 days (the founder
    -- asked for a weekly check, and 6 not 7 so a slow week never skips one), a failed or unparseable one
    -- for 6 hours — a transient UN or UAE outage is retried a few times a day, never every 15 minutes.
    --
    -- PER SOURCE IS NOT A DETAIL (found in independent review before this was applied). Written as one
    -- ungrouped NOT EXISTS over the whole table, a healthy UN fetch would hold the gate shut for six days
    -- and the UAE list — failing every time — would be retried once a week instead of every six hours,
    -- with the documented back-off silently never applying to the source that actually needed it. That is
    -- the estate's "guarded by a condition that cannot occur" shape: the failure branch exists and can
    -- never be reached. The cost of the correct version is that a broken source re-opens the gate every
    -- 6 hours and the healthy list is downloaded again with it, ~4 times a day instead of once a week.
    -- That is the right way round: bandwidth is cheap and an unscreened sanctions source is not.
    --
    -- Every attempt writes a screening_run row whatever happened, which is what makes this a measurement
    -- and not a hope; a zero-run history reads as due, which is correct, because it has never run.
    'sanctions', coalesce((select value from public.app_secrets where key = 'sanctions_screen_enabled'), '') = 'true'
      and exists (
        select 1 from (values ('un_consolidated'), ('uae_local_terrorist_list')) as s(source)
         where not exists (
           select 1 from public.screening_run r
            where r.source = s.source
              and r.fetched_at > now() - case when r.status = 'ok' then interval '6 days' else interval '6 hours' end))
  )
$function$


CREATE OR REPLACE FUNCTION public.fn_resilience_step_board()
 RETURNS TABLE(step text, every interval, overdue_ratio numeric, last_started_at timestamp with time zone, last_ok_at timestamp with time zone, ewma_ms integer, deferrals integer, deferred_since timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select s.step, s.every,
         round((extract(epoch from (now() - coalesce(s.last_started_at, now() - s.every - interval '365 days')))
                / greatest(extract(epoch from s.every), 1))::numeric, 2),
         s.last_started_at, s.last_ok_at, s.ewma_ms, s.deferrals, s.deferred_since
    from public.resilience_step s
   order by 3 desc, s.step;
$function$


CREATE OR REPLACE FUNCTION public.fn_resilience_step_record(p_rows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_seen integer := 0;
begin
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    return jsonb_build_object('ok', false, 'error', 'p_rows must be a jsonb array');
  end if;

  -- EVERY FIELD IS READ DEFENSIVELY, AND THE ARRAY IS DE-DUPLICATED (independent review,
  -- ecc:database-reviewer, 18 Sep 2026). Two findings, both about one bad element taking the whole call
  -- down or silently winning:
  --   * a malformed `ms` or `ok` ("12.5", 2) would raise a cast error, and because this is ONE
  --     `update … from` that aborts the whole batch — so no step gets its attempt stamped, every
  --     staleness ratio keeps rising, and the next plan is computed from a lie. A bad field now degrades
  --     to its default instead of taking the tick's whole record with it.
  --   * `update … from` with the same step twice picks an arbitrary source row, with no error and a
  --     row_count that still looks complete. `distinct on` makes the winner a decision: a step that RAN
  --     beats the same step reported deferred, because a stamped attempt is the truthful one.
  with parsed as (
    select e->>'step'                                                           as step,
           coalesce(e->>'deferred' = 'true', false)                             as deferred,
           coalesce(e->>'ok' = 'true', false)                                   as ok,
           case when e->>'ms' ~ '^[0-9]{1,9}$' then (e->>'ms')::integer end      as ms
      from jsonb_array_elements(p_rows) e
     where jsonb_typeof(e) = 'object' and e->>'step' is not null
  ), rows as (
    select distinct on (step) * from parsed order by step, deferred asc, ok desc, ms desc nulls last
  )
  update public.resilience_step s
     set last_started_at = case when r.deferred then s.last_started_at else now() end,
         last_ok_at      = case when not r.deferred and r.ok then now() else s.last_ok_at end,
         last_ms         = case when r.deferred then s.last_ms else coalesce(r.ms, s.last_ms) end,
         -- 0.7 old + 0.3 new: a single slow pass moves the estimate without owning it.
         ewma_ms         = case
                             when r.deferred or r.ms is null then s.ewma_ms
                             when s.ewma_ms is null then r.ms
                             else round(0.7 * s.ewma_ms + 0.3 * r.ms)::integer
                           end,
         deferrals       = case when r.deferred then s.deferrals + 1 else 0 end,
         deferred_since  = case when r.deferred then coalesce(s.deferred_since, now()) else null end
    from rows r
   where r.step = s.step;
  get diagnostics v_seen = row_count;

  return jsonb_build_object('ok', true, 'updated', v_seen);
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_resilience_tick_plan(p_budget_ms integer DEFAULT 70000)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with due as (
    select step, coalesce(ewma_ms, budget_ms) as cost, deferrals,
           extract(epoch from (now() - coalesce(last_started_at, now() - every - interval '365 days')))
             / greatest(extract(epoch from every), 1) as ratio
      from public.resilience_step
     where place = 'plan'
       -- A TICK IS NEVER EXACTLY ON THE BEAT, SO THE DUE TEST HAS TWO MINUTES OF TOLERANCE
       -- (22 Sep 2026, it_engineer, SEATS-04). `now() - last_started_at >= every` asks for the full
       -- interval to have elapsed at the moment the tick looks. Ticks jitter by seconds, so a 30-minute
       -- step whose last attempt was 29 min 58 s ago is not due on this tick and waits for the next one:
       -- its real cadence becomes one tick longer, and measured across the estate the scheduled steps
       -- were running about 1.5x their declared interval.
       -- SAID PRECISELY, because the loose version of this sentence was wrong: the effective floor is
       -- `every - 2 min`, so a 15-minute step can now run as often as every 13 minutes and TWICE inside
       -- some 15-minute windows. That is the intended trade — two runs 13 minutes apart cost one extra
       -- pass of a step that already gates itself, where a missed beat costs a whole interval — and it is
       -- not a lock: nothing here reserves a step. `last_started_at` is stamped by
       -- fn_resilience_step_record when the tick REPORTS, i.e. at the end, so two ticks overlapping in
       -- time can both plan the same step. That was already true before this change; the tolerance does
       -- not create it and does not fix it. Each step's own `fn_*_due` gate and claim-style queries are
       -- what make a double run harmless.
       and (last_started_at is null or now() - last_started_at >= every - interval '2 minutes')
  ), ranked as (
    select *, row_number() over (order by ratio desc, step) as rn from due
  ), filled as (
    -- ponytail: prefix cut, not a knapsack. A large step near the front can leave budget unused; the
    -- staleness order still admits it next tick, so the cost is a beat, never a starved step. Swap in a
    -- fitting pass only if the measured deferral rate says the waste matters.
    select *, sum(cost) over (order by rn rows between unbounded preceding and current row) as cum
      from ranked
  ), decided as (
    select *, (rn = 1 or cum <= p_budget_ms) as admitted from filled
  )
  select jsonb_build_object(
    'budget_ms',  p_budget_ms,
    'planned_ms', coalesce((select sum(cost) from decided where admitted), 0),
    'run',        coalesce((select jsonb_agg(step order by rn) from decided where admitted), '[]'::jsonb)
                  || coalesce((select jsonb_agg(step order by rank, step) from public.resilience_step where place = 'last'), '[]'::jsonb),
    'deferred',   coalesce((select jsonb_agg(step order by rn) from decided where not admitted), '[]'::jsonb),
    -- A step that has been passed over four ticks running (an hour) is no longer "a beat late". It is
    -- returned so the tick raises it as an IT engineer finding, which is the alarm on the guarantee
    -- above: if the bound is ever not holding, this says so instead of the silence that cost the
    -- sanctions screen its run.
    'starved',    coalesce((select jsonb_agg(step order by deferrals desc, step)
                              from decided where not admitted and deferrals >= 4), '[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_resolve_cat_agent(cat text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare k text; c text := lower(trim(coalesce(cat,'')));
begin
  if c = '' then return null; end if;

  -- Hop 1 and 2, unchanged: the caller already holds a catalogue slug.
  if exists(select 1 from category_agents where slug=c and coalesce(active,true)) then return 'cat:'||c; end if;
  if exists(select 1 from agent_knowledge where agent_key='cat:'||c limit 1) then return 'cat:'||c; end if;

  -- Hop 3, NEW: the declared trade -> catalogue bridge, the same one fn_category_knowledge walks.
  -- Before the name LIKE, because a mapping somebody decided beats a substring that happens to hit.
  select 'cat:'||m.catalog_slug into k
    from lead_trade_map m
   where m.trade_key = c
     and exists (select 1 from agent_knowledge a where a.agent_key = 'cat:'||m.catalog_slug)
   limit 1;
  if k is not null then return k; end if;

  -- Hop 4, unchanged: the display-name fallback, now only reached when nothing declared a mapping.
  select 'cat:'||slug into k from category_agents
    where coalesce(active,true) and (lower(name) like '%'||c||'%' or c like '%'||slug||'%' or lower(name)=c)
    order by length(slug) desc limit 1;
  return k;
end $function$


CREATE OR REPLACE FUNCTION public.fn_reveal_outcome_check_tick(p_include_fixtures boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_days numeric := public.fn_seat_clock_policy('reveal_outcome_check_days', 7);
  v_rating int; d record; v jsonb; v_asked int := 0; v_skipped jsonb := '[]'::jsonb;
begin
  select nullif(regexp_replace(coalesce(value, ''), '[^0-9]', '', 'g'), '')::int into v_rating
    from public.app_secrets where key = 'rating_request_days_after_reveal';
  v_rating := coalesce(v_rating, 21);

  for d in
    select t.id as tx_id, t.quote_id, t.inquiry_id, t.supplier_id, c.email as cemail, c.locale as clocale,
           c.full_name as cname, public.fn_seat_clock_customer_is_fixture(c) as fixture,
           l.company_name, i.category
      from public.transactions t
      join public.customers c on c.id = t.customer_id
      left join public.leads l on l.id = t.supplier_id
      left join public.inquiries i on i.id = t.inquiry_id
     where t.revealed_at is not null and t.quote_id is not null
       and t.revealed_at <= now() - make_interval(days => v_days::int)
       -- the rating ask owns day 21 onwards; the outcome check never lands on or after it
       and t.revealed_at >  now() - make_interval(days => v_rating)
       -- the same allowlist as fn_support_request_ratings_due: never a refunded or disputed reveal
       and coalesce(t.refund_status, 'none') in ('none', 'window_open', 'declined')
       and coalesce(i.outcome, '') = '' and coalesce(i.status, '') <> 'completed'
       and (p_include_fixtures or not public.fn_seat_clock_customer_is_fixture(c))
       and not public.fn_seat_clock_asked('reveal_outcome_check:' || t.quote_id)
     order by t.revealed_at
  loop
    v := public.fn_seat_clock_deliver('customer_support', 'reveal_outcome_check', 'customer', d.cemail, d.fixture, d.clocale,
           'reveal_outcome_check',
           jsonb_build_object('name', d.cname, 'supplier', d.company_name, 'category', d.category),
           'reveal_outcome_check:' || d.quote_id, d.inquiry_id, d.quote_id, d.supplier_id);
    if coalesce((v->>'ok')::boolean, false) then v_asked := v_asked + 1;
    else v_skipped := v_skipped || jsonb_build_array(jsonb_build_object('transaction_id', d.tx_id, 'reason', v->>'reason'));
    end if;
  end loop;
  return jsonb_build_object('ok', true, 'asked', v_asked, 'not_written', v_skipped, 'days_after_reveal', v_days,
                            'rating_ask_day', v_rating);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_revenue_document(p_transaction_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(
    (select jsonb_build_object(
       'ok',              v.doc_path is not null,
       'transaction_id',  v.id,
       'quote_id',        v.quote_id,
       'revealed_at',     v.revealed_at,
       'reveal_fee',      v.reveal_fee,
       'payment_ref',     v.payment_ref,
       'invoice_id',      v.stripe_invoice_id,
       'invoice_number',  v.stripe_invoice_number,
       'invoice_status',  v.stripe_invoice_status,
       'invoice_total_fils', v.stripe_invoice_total_fils,
       'invoice_currency',   v.stripe_invoice_currency,
       'invoice_pdf_url',    v.stripe_invoice_pdf_url,
       'invoice_hosted_url', v.stripe_invoice_hosted_url,
       'invoice_agrees_with_fee', v.invoice_agrees_with_fee,
       'bucket',          v.doc_bucket,
       'path',            v.doc_path,
       'name',            v.doc_name,
       'content_type',    v.doc_content_type,
       'kind',            v.doc_kind,
       'note',            v.doc_note,
       'state',           v.document_state,
       'reason',          case
                            when v.doc_path is not null then null
                            when v.stripe_invoice_id is not null
                              then 'Stripe issued invoice ' || coalesce(v.stripe_invoice_number, v.stripe_invoice_id)
                                || ' for this sale, but its PDF has not been fetched into finance-docs yet.'
                            else 'This sale has no Stripe invoice on record. Reveal fees paid before '
                              || 'invoice_creation was enabled on 9 Sep 2026 produced no Invoice '
                              || 'object at all, so there is nothing to fetch for those.'
                          end)
     from public.v_revenue_documents v where v.id = p_transaction_id),
    jsonb_build_object('ok', false, 'transaction_id', p_transaction_id, 'state', 'no_such_transaction',
                       'reason', 'There is no public.transactions row with that id.'));
$function$


CREATE OR REPLACE FUNCTION public.fn_revenue_document_coverage()
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'sales',              count(*),
    'fees_taken',         count(*) filter (where fee_was_taken),
    'invoiced',           count(*) filter (where fee_was_taken and stripe_invoice_id is not null),
    'openable',           count(*) filter (where fee_was_taken and is_openable),
    'reference_only',     count(*) filter (where fee_was_taken and document_state = 'reference_only'),
    'unclassified',       count(*) filter (where fee_was_taken and document_state = 'unclassified'),
    'missing',            count(*) filter (where fee_was_taken and document_state = 'missing'),
    'missing_ids',        coalesce(jsonb_agg(id order by revealed_at)
                            filter (where fee_was_taken and document_state = 'missing'), '[]'::jsonb),
    'reference_only_ids', coalesce(jsonb_agg(id order by revealed_at)
                            filter (where fee_was_taken and document_state = 'reference_only'), '[]'::jsonb),
    'total_disagrees_ids', coalesce(jsonb_agg(id order by revealed_at)
                            filter (where fee_was_taken and invoice_agrees_with_fee = 'disagrees'), '[]'::jsonb),
    'by_state',           (select coalesce(jsonb_object_agg(document_state, n), '{}'::jsonb)
                           from (select document_state, count(*) n
                                 from public.v_revenue_documents
                                 where fee_was_taken group by 1) s))
  from public.v_revenue_documents;
$function$


CREATE OR REPLACE FUNCTION public.fn_review_decide(p_kind text, p_ref_id bigint, p_decision text, p_comment text DEFAULT NULL::text, p_by text DEFAULT 'founder'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare dec text := lower(coalesce(p_decision,'')); ok boolean := false;
begin
  if dec not in ('approve','changes','reject') then return jsonb_build_object('error','decision must be approve|changes|reject'); end if;

  if p_kind = 'marketing_post' then
    update content_drafts set
      review_status = case dec when 'approve' then 'approved' when 'changes' then 'changes_requested' else 'rejected' end,
      founder_comment = coalesce(p_comment, founder_comment), reviewed_at = now()
    where id = p_ref_id and status='draft';
    ok := found;
    -- On approve, social_stage will publish it live (gated by marketing_golive). On changes, the marketing loop revises it.

  elsif p_kind = 'refund' then
    update transactions set
      refund_status = case dec when 'approve' then 'approved' when 'reject' then 'declined' else 'requested' end,
      refund_note = coalesce(p_comment, refund_note),
      refund_resolved_at = case when dec in ('approve','reject') then now() else refund_resolved_at end
    where id = p_ref_id and refund_status='requested';
    ok := found;

  elsif p_kind = 'boost_budget' then
    update review_queue set
      status = case dec when 'approve' then 'approved' when 'changes' then 'changes_requested' else 'rejected' end,
      founder_comment = coalesce(p_comment, founder_comment), decided_at = now(), decided_by = p_by
    where id = p_ref_id and status='pending';
    ok := found;
  else
    return jsonb_build_object('error','unknown kind '||p_kind);
  end if;

  return jsonb_build_object('ok', ok, 'kind', p_kind, 'ref_id', p_ref_id, 'decision', dec);
end $function$


CREATE OR REPLACE FUNCTION public.fn_review_hold_record(p_task_class text, p_fn text, p_agent_key text, p_counterpart_model text, p_why text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id bigint;
begin
  insert into public.review_hold (task_class, fn, agent_key, counterpart_model, why)
  values (coalesce(p_task_class, '(unresolved)'), p_fn, p_agent_key, coalesce(nullif(btrim(p_counterpart_model), ''), '(none)'),
          left(coalesce(p_why, 'no independent reviewer'), 2000))
  on conflict (task_class, coalesce(fn, ''), counterpart_model) where closed_at is null
  do update set last_held_at = now(), times_held = review_hold.times_held + 1, why = excluded.why
  returning id into v_id;
  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_review_pending()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'marketing_posts', coalesce((select jsonb_agg(jsonb_build_object(
        'kind','marketing_post','ref_id',c.id,'title',c.title,'channel',c.channel,'body',c.body,'image_url',c.image_url,
        'media_missing', case when c.image_url is null then 'no media designed yet' end,
        'created_at',c.created_at)
        order by c.created_at desc)
      from content_drafts c where c.status='draft' and coalesce(c.review_status,'pending')='pending'), '[]'::jsonb),
    'refunds', coalesce((select jsonb_agg(jsonb_build_object(
        'kind','refund','ref_id',t.id,'customer_id',t.customer_id,'reason',t.refund_reason,'requested_at',t.refund_requested_at)
        order by t.refund_requested_at desc)
      from transactions t where t.refund_status='requested'), '[]'::jsonb),
    'boost_budgets', coalesce((select jsonb_agg(jsonb_build_object(
        'kind','boost_budget','ref_id',r.id,'title',r.title,'summary',r.summary,'payload',r.payload,'created_at',r.created_at)
        order by r.created_at desc)
      from review_queue r where r.kind='boost_budget' and r.status='pending'), '[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_review_submit(p_subject_type text, p_subject_id text, p_dept_key text, p_author text, p_content text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_crit        jsonb;
  v_rule        jsonb;
  v_violations  jsonb := '[]'::jsonb;
  v_unenforced  jsonb := '[]'::jsonb;
  v_critical    int := 0;
  v_major       int := 0;
  v_pick        jsonb;
  v_head        text;
  v_deleg_from  text;
  v_deleg_basis text;
  v_cos         text := 'brief';
  v_decision    text;
  v_reason      text;
  v_conf        numeric;
  v_first_rule  text;
  v_res         jsonb;
begin
  -- CANONICAL AUTHOR, OR THE LEDGER CANNOT SEE ITS OWN SELF-REVIEWS.
  -- review_chain.author_agent was written with whatever string the caller passed while
  -- reviewer_agent was always resolved. A head authoring under an alias therefore produced a row
  -- whose author and reviewer were the SAME employee under two names - and every self-review
  -- count in this system is "author_agent = reviewer_agent", which such a row passes.
  -- So the reported zero was a property of the spelling, not of the behaviour.
  p_author := coalesce(public.fn_org_agent_resolve(p_author), p_author);

  -- Who is actually able to approve for this department right now, GIVEN WHO WROTE IT.
  v_pick        := fn_pick_reviewer(p_dept_key, p_author);
  v_head        := v_pick->>'reviewer';
  v_deleg_from  := v_pick->>'delegated_from';
  v_deleg_basis := v_pick->>'basis';

  -- The Chief of Staff cannot counter-sign its own draft either: that review climbs to the CEO.
  if p_author = coalesce(public.fn_org_agent_resolve(v_cos), v_cos) then v_cos := 'ceo'; end if;

  insert into review_chain (subject_type, subject_id, dept_key, author_agent, stage, decision, reason, confidence)
  values (p_subject_type, p_subject_id, p_dept_key, p_author, 'drafted', null,
          'Draft submitted for department review', null);

  if v_head is null then
    insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent, stage,
                              decision, reason, confidence, delegated_from, delegation_basis)
    values (p_subject_type, p_subject_id, p_dept_key, p_author, null, 'dept_review',
            'escalate', 'No available approver in ' || p_dept_key || ': ' || coalesce(v_deleg_basis,''), 1.0,
            v_deleg_from, v_deleg_basis);
    return jsonb_build_object('subject_id', p_subject_id, 'outcome', 'escalate',
                              'stopped_at', 'dept_review', 'violations', v_violations,
                              'reason', coalesce(v_deleg_basis,''));
  end if;

  select criteria into v_crit from quality_standard where work_type = p_subject_type;

  if v_crit is not null then
    for v_rule in select * from jsonb_array_elements(v_crit) loop

      if (v_rule ? 'check_fn') then
        begin
          execute format('select %I($1,$2)', v_rule->>'check_fn')
            into v_res using p_subject_id, p_content;
        exception when others then
          v_res := jsonb_build_object('passed', false, 'detail', 'check ' || (v_rule->>'check_fn') || ' errored: ' || sqlerrm);
        end;
        if not coalesce((v_res->>'passed')::boolean, false) then
          v_violations := v_violations || jsonb_build_object(
            'rule', v_rule->>'rule', 'severity', v_rule->>'severity',
            'why', v_rule->>'why', 'detail', v_res->>'detail');
          if (v_rule->>'severity') = 'critical' then v_critical := v_critical + 1;
          elsif (v_rule->>'severity') = 'major' then v_major := v_major + 1; end if;
          if v_first_rule is null then v_first_rule := v_rule->>'rule'; end if;
        end if;

      elsif (v_rule ? 'pattern') and (v_rule ? 'fails_when') then
        if (v_rule->>'fails_when') = 'match' and p_content ~ (v_rule->>'pattern') then
          v_violations := v_violations || jsonb_build_object(
            'rule', v_rule->>'rule', 'severity', v_rule->>'severity', 'why', v_rule->>'why');
          if (v_rule->>'severity') = 'critical' then v_critical := v_critical + 1;
          elsif (v_rule->>'severity') = 'major' then v_major := v_major + 1; end if;
          if v_first_rule is null then v_first_rule := v_rule->>'rule'; end if;
        elsif (v_rule->>'fails_when') = 'no_match' and p_content !~ (v_rule->>'pattern') then
          v_violations := v_violations || jsonb_build_object(
            'rule', v_rule->>'rule', 'severity', v_rule->>'severity', 'why', v_rule->>'why');
          if (v_rule->>'severity') = 'critical' then v_critical := v_critical + 1;
          elsif (v_rule->>'severity') = 'major' then v_major := v_major + 1; end if;
          if v_first_rule is null then v_first_rule := v_rule->>'rule'; end if;
        end if;

      else
        v_unenforced := v_unenforced || jsonb_build_object(
          'rule', v_rule->>'rule', 'severity', v_rule->>'severity', 'why', v_rule->>'why');
      end if;

    end loop;
  end if;

  if v_critical > 0 then
    v_decision := 'reject';
    v_reason   := 'Rejected by department head: ' || v_critical || ' critical rule breach(es) - ' || (v_violations::text);
    v_conf     := 1.0;
  elsif v_major > 0 then
    v_decision := 'request_revision';
    v_reason   := 'Returned for revision: ' || v_major || ' major issue(s) - ' || (v_violations::text);
    v_conf     := 0.9;
  elsif jsonb_array_length(v_unenforced) > 0
        and exists (select 1 from jsonb_array_elements(v_unenforced) u where u->>'severity' = 'critical') then
    v_decision := 'hold_for_human';
    v_reason   := 'Held for human review: no executable check exists for critical criteria - ' || (v_unenforced::text);
    v_conf     := 1.0;
    v_first_rule := (select u->>'rule' from jsonb_array_elements(v_unenforced) u where u->>'severity'='critical' limit 1);
  elsif v_crit is null then
    v_decision := 'hold_for_human';
    v_reason   := 'Held for human review: no quality standard is defined for work type "' || p_subject_type || '"';
    v_conf     := 1.0;
  else
    v_decision := 'approve';
    v_reason   := 'Meets the quality standard for ' || p_subject_type || '; every criterion was checked and passed';
    v_conf     := 0.95;
  end if;

  insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent, stage,
                            decision, reason, violated_rule, confidence, delegated_from, delegation_basis)
  values (p_subject_type, p_subject_id, p_dept_key, p_author, v_head, 'dept_review',
          v_decision, v_reason, v_first_rule, v_conf, v_deleg_from,
          case when v_deleg_from is not null then v_deleg_basis else null end);

  if v_decision <> 'approve' then
    return jsonb_build_object('subject_id', p_subject_id, 'outcome', v_decision,
                              'stopped_at', 'dept_review', 'violations', v_violations,
                              'unenforceable', v_unenforced,
                              'reviewer', v_head, 'delegated_from', v_deleg_from);
  end if;

  insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent, stage,
                            decision, reason, confidence)
  values (p_subject_type, p_subject_id, p_dept_key, p_author, v_cos, 'cos_review',
          'approve', 'Approved by Chief of Staff: brand-compliant and serves a company goal', 0.9);

  insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent, stage,
                            decision, reason, confidence)
  values (p_subject_type, p_subject_id, p_dept_key, p_author, v_cos, 'published',
          'approve', 'Published after full approval chain', 1.0);

  -- 4 Sep 2026: the content.published emit that stood here is retired. It fired on every approved
  -- review of any subject (org_tasks, posts, documents) — 360 events, 1,003 deliveries, 163 tasks
  -- minted and 87 still open for two subscribers who wanted campaign.published. The 'published'
  -- review_chain row above is the log; the real publish path emits campaign.published from
  -- content_drafts.status = 'posted' (fn_emit_campaign_published_from_content).

  return jsonb_build_object('subject_id', p_subject_id, 'outcome', 'published',
                            'stopped_at', 'published', 'violations', v_violations,
                            'unenforceable', v_unenforced,
                            'reviewer', v_head, 'delegated_from', v_deleg_from);
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_rfq_board(p_search text DEFAULT ''::text, p_limit integer DEFAULT 80, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare out jsonb;
begin
  with base as (
    select i.id, coalesce(nullif(trim(i.category),''),'general') as category,
      coalesce(nullif(trim(i.emirate),''),'—') as emirate,
      left(coalesce(nullif(trim(i.summary),''), i.raw_input, ''),140) as summary,
      i.expected_value as value, nullif(btrim(i.budget),'') as budget, i.urgency, i.status, i.outcome, i.created_at,
      case lower(coalesce(i.pipeline_stage, i.status, ''))
        when 'won' then 'won' when 'revealed' then 'revealed' when 'quoted' then 'quoted' when 'matched' then 'matched'
        else (case when i.outcome='won' then 'won' else 'new' end) end as stage
    from inquiries i
    where coalesce(p_search,'')='' or i.category ilike '%'||p_search||'%' or i.summary ilike '%'||p_search||'%' or i.emirate ilike '%'||p_search||'%'
  ), ranked as (select *, row_number() over (partition by stage order by created_at desc, id desc) rn from base),
  sc as (select stage, count(*) c from base group by stage)
  select jsonb_build_object(
    'total',(select count(*) from base),
    'stages',(select jsonb_agg(jsonb_build_object('key',s.key,'label',s.label,'count',coalesce((select c from sc where sc.stage=s.key),0),
      'cards',coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'category',r.category,'emirate',r.emirate,'summary',r.summary,'value',r.value,'budget',r.budget,'urgency',r.urgency,'status',r.status) order by r.rn) from ranked r where r.stage=s.key and r.rn<=12),'[]'::jsonb))
      order by s.ord)
      from (values ('new','New',1),('matched','Matched',2),('quoted','Quoted',3),('revealed','Revealed',4),('won','Won',5)) s(key,label,ord)),
    'rows',(select coalesce(jsonb_agg(jsonb_build_object('id',b.id,'category',b.category,'emirate',b.emirate,'summary',b.summary,'value',b.value,'budget',b.budget,'urgency',b.urgency,'status',b.status,'stage',b.stage,'created_at',b.created_at) order by b.created_at desc, b.id desc),'[]'::jsonb)
             from (select * from base order by created_at desc, id desc limit greatest(1,least(p_limit,200)) offset greatest(0,p_offset)) b)
  ) into out; return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_rfq_required_check(i inquiries)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  spec_fields jsonb; f jsonb; bag jsonb := '{}'::jsonb; blob text;
  k text; v text; bk text; opt text; tok text; toks text[];
  reqn int := 0; have text[] := '{}';
  miss jsonb := '[]'::jsonb; advisory jsonb := '[]'::jsonb; found boolean;
begin
  select cs.fields into spec_fields
    from public.category_specs cs
   where lower(cs.category) = lower(coalesce(i.category,''))
   limit 1;

  if spec_fields is null or jsonb_typeof(spec_fields) <> 'array' then
    return jsonb_build_object('applicable', false, 'reason', 'no category_specs row',
      'category', i.category, 'required_ok', true, 'required_total', 0,
      'present','[]'::jsonb, 'missing','[]'::jsonb, 'advisory_missing','[]'::jsonb, 'checked_at', now());
  end if;

  if i.spec is not null and jsonb_typeof(i.spec) = 'object' then
    for k, v in
      select e.key, case when jsonb_typeof(e.value) in ('object','array')
                         then e.value::text else coalesce(e.value #>> '{}','') end
        from jsonb_each(i.spec) e
    loop
      bag := bag || jsonb_build_object(lower(k), v);
    end loop;

    for k, v in
      select e2.key, case when jsonb_typeof(e2.value) in ('object','array')
                          then e2.value::text else coalesce(e2.value #>> '{}','') end
        from jsonb_each(i.spec) e1
        join lateral jsonb_each(case when jsonb_typeof(e1.value)='object'
                                     then e1.value else '{}'::jsonb end) e2 on true
    loop
      if not public._rfq_answered(bag->>lower(k)) then
        bag := bag || jsonb_build_object(lower(k), v);
      end if;
    end loop;
  end if;

  bag := bag
    || case when coalesce(i.emirate,'') <> '' then
            jsonb_build_object('emirate', i.emirate,
              'location', coalesce(nullif(bag->>'location',''), i.emirate)) else '{}'::jsonb end
    || case when coalesce(i.scope_type,'') <> '' then
            jsonb_build_object('scope', coalesce(nullif(bag->>'scope',''), i.scope_type)) else '{}'::jsonb end
    || case when coalesce(i.budget,'') <> '' then jsonb_build_object('budget', i.budget) else '{}'::jsonb end
    || case when coalesce(array_length(i.trades,1),0) > 0 then
            jsonb_build_object('trades', array_to_string(i.trades,', ')) else '{}'::jsonb end
    || case when coalesce(i.drawing_file_path,'') <> '' or i.boq is not null then
            jsonb_build_object('drawing','provided') else '{}'::jsonb end;

  blob := lower(concat_ws(' ', i.summary, i.raw_input, i.spec::text));
  foreach tok in array coalesce(regexp_split_to_array(lower(coalesce(i.category,'')), '[^a-z0-9]+'), '{}'::text[]) loop
    if length(coalesce(tok,'')) >= 4 then blob := replace(blob, tok, ' '); end if;
  end loop;

  for f in select value from jsonb_array_elements(spec_fields)
            where coalesce((value->>'required')::boolean, false)
  loop
    k := nullif(btrim(lower(coalesce(f->>'key',''))), '');

    -- Keyless required field: unaddressable, so ADVISORY ONLY (never blocks dispatch).
    if k is null then
      advisory := advisory || jsonb_build_object(
        'question', f->>'question', 'reason', 'category_specs field has no key - cannot be gated');
      continue;
    end if;

    reqn := reqn + 1; found := false;

    if public._rfq_answered(bag->>k) then found := true; end if;

    if not found then
      for bk in select key from jsonb_each_text(bag) loop
        if public._rfq_answered(bag->>bk) then
          if public._rfq_concept(k) is not null
             and public._rfq_concept(k) = public._rfq_concept(bk) then
            found := true;
          else
            foreach tok in array coalesce(string_to_array(k,'_'), '{}'::text[]) loop
              if length(coalesce(tok,'')) >= 4
                 and (bk = tok or bk like '%'||tok||'%' or tok like '%'||bk||'%') then
                found := true;
              end if;
            end loop;
          end if;
        end if;
        exit when found;
      end loop;
    end if;

    if not found and jsonb_typeof(f->'options') = 'array' then
      for opt in select lower(o) from jsonb_array_elements_text(f->'options') o loop
        toks := coalesce(regexp_split_to_array(regexp_replace(coalesce(opt,''),'[^a-z0-9 ]',' ','g'), '\s+'), '{}'::text[]);
        foreach tok in array toks loop
          if length(coalesce(tok,'')) >= 4 and blob like '%'||tok||'%' then found := true; end if;
        end loop;
        exit when found;
      end loop;
    end if;

    if found then
      have := array_append(have, k);
    else
      miss := miss || jsonb_build_object('key', k, 'question', f->>'question', 'type', f->>'type');
    end if;
  end loop;

  return jsonb_build_object(
    'applicable', true, 'category', i.category,
    'required_total', reqn,
    'required_ok', (jsonb_array_length(miss) = 0),
    'present', to_jsonb(have),
    'missing', miss,
    'advisory_missing', advisory,
    'checked_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_rfq_score(i inquiries)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare pts int:=0; miss text[]:='{}'; have text[]:='{}'; spectxt text;
        catchk jsonb; catmiss text[]:='{}'; m jsonb; gready boolean; catok boolean;
begin
  spectxt := coalesce(i.spec::text,'');
  if coalesce(i.category,'')<>'' then pts:=pts+20; have:=array_append(have,'category'); else miss:=array_append(miss,'category'); end if;
  if coalesce(i.emirate,'')<>'' then pts:=pts+10; have:=array_append(have,'emirate'); else miss:=array_append(miss,'emirate'); end if;
  if length(regexp_replace(spectxt,'[^a-zA-Z0-9]','','g')) > 20 then pts:=pts+25; have:=array_append(have,'scope_detail'); else miss:=array_append(miss,'scope_detail'); end if;
  if coalesce(i.scope_type,'')<>'' then pts:=pts+15; have:=array_append(have,'scope_type'); else miss:=array_append(miss,'scope_type'); end if;
  if i.budget is not null then pts:=pts+15; have:=array_append(have,'budget'); else miss:=array_append(miss,'budget'); end if;
  if coalesce(array_length(i.trades,1),0)>0 or coalesce(i.drawing_file_path,'')<>'' or i.boq is not null then
     pts:=pts+15; have:=array_append(have,'supporting_detail'); else miss:=array_append(miss,'supporting_detail'); end if;

  gready := pts >= 70;

  catchk := public.fn_rfq_required_check(i);
  catok  := coalesce((catchk->>'required_ok')::boolean, true);

  if coalesce((catchk->>'applicable')::boolean,false) then
    for m in select value from jsonb_array_elements(coalesce(catchk->'missing','[]'::jsonb)) loop
      catmiss := array_append(catmiss, coalesce(nullif(m->>'question',''), m->>'key'));
    end loop;
  end if;

  return jsonb_build_object(
    'score', pts,
    'generic_ready', gready,
    'category_required_ok', catok,
    'ready', (gready and catok),
    'have', to_jsonb(have),
    'missing', to_jsonb(miss || catmiss),
    'category_missing', coalesce(catchk->'missing','[]'::jsonb),
    'category_check', catchk,
    'scored_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_rfq_short_of_quotes_tick(p_include_fixtures boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  -- the top-3 rule: the comparison report is the top 3 (founder rule). A constant, not a setting.
  c_target constant int := 3;
  v_window numeric; v_lead numeric := public.fn_seat_clock_policy('rfq_short_sweep_hours_before_deadline', 8);
  v_fanout int := coalesce(public.fn_seat_clock_policy('match_max_fanout', 5), 5)::int;
  r record; s record; l public.leads; v jsonb; v_codes text[]; v_need text; v_value numeric; v_new int;
  v_swept int := 0; v_invited int := 0; v_reminded int := 0; v_told int := 0; v_skipped jsonb := '[]'::jsonb;
begin
  select nullif(regexp_replace(coalesce(value, ''), '[^0-9.]', '', 'g'), '')::numeric into v_window
    from public.app_secrets where key = 'sla_quote_hours';
  v_window := coalesce(v_window, 24);

  for r in
    with open_rfq as (
      select i.*, c.email as cemail, c.locale as clocale, c.full_name as cname,
             public.fn_seat_clock_customer_is_fixture(c) as fixture,
             (select min(m.sent_at) from public.inquiry_matches m where m.inquiry_id = i.id) as first_sent,
             (select count(*) from public.quotes q where q.inquiry_id = i.id
                and coalesce(q.status, '') not in ('draft', 'withdrawn', 'rejected', 'expired', 'held', 'cancelled')
                and q.stale_at is null)::int as live_quotes
        from public.inquiries i
        join public.customers c on c.id = i.customer_id
       where i.status in ('sent', 'quoted')
    )
    select o.*, o.first_sent + make_interval(secs => (v_window * 3600)::double precision) as deadline
      from open_rfq o
     where o.first_sent is not null
       and o.live_quotes < c_target
       and now() >= o.first_sent + make_interval(secs => ((v_window - v_lead) * 3600)::double precision)
       and now() <  o.first_sent + interval '14 days'
       and (p_include_fixtures or not o.fixture)
     order by o.first_sent
  loop
    v_swept := v_swept + 1;

    -- (a) widen ONCE, from the same matcher, same-kind suppliers only.
    if not coalesce(r.routing ? 'short_sweep', false) then
      v_new := 0;
      v_codes := public.fn_taxonomy_trades_for(case when coalesce(cardinality(r.trades), 0) > 0 then r.trades
                                                    else array[coalesce(r.category, '')] end);
      if coalesce(cardinality(v_codes), 0) > 0 then
        v_need := case when coalesce(r.scope_type, '') ilike '%turnkey%' then 'whole_scope'
                       when coalesce(r.scope_type, '') || ' ' || coalesce(r.role_needed, '') ~* 'supply|material|product' then 'supplies'
                       else 'executes' end;
        v_value := coalesce(r.expected_value, nullif(regexp_replace(coalesce(r.budget, ''), '[^0-9.]', '', 'g'), '')::numeric);
        if v_value is not null and v_value <= 0 then v_value := null; end if;
        for s in select m.supplier_id, m.score, m.why
                   from public.fn_match_capability(v_codes, v_need, '{}'::text[], '{}'::text[], r.scope_type, v_value, r.emirate, 60) m
                   join public.leads ld on ld.id = m.supplier_id
                  where not exists (select 1 from public.inquiry_matches x where x.inquiry_id = r.id and x.supplier_id = m.supplier_id)
                    and public.fn_seat_clock_lead_is_fixture(ld) = r.fixture
                  order by m.score desc
                  limit v_fanout loop
          insert into public.inquiry_matches (inquiry_id, supplier_id, similarity, match_reason)
          values (r.id, s.supplier_id, least(1, greatest(0, round(s.score / 100, 3))),
                  left('short-of-quotes sweep (fn_rfq_short_of_quotes_tick): ' || coalesce(s.why, ''), 400))
          on conflict (inquiry_id, supplier_id) do nothing;
          if found then
            v_new := v_new + 1;
            select * into l from public.leads where id = s.supplier_id;
            v := public.fn_seat_clock_deliver('sales_engineer', 'supplier_rfq_widened_invite', 'supplier',
                   lower(btrim(coalesce(nullif(btrim(l.claimed_by), ''), l.email))), r.fixture, l.locale, 'rfq_invite',
                   jsonb_build_object('name', l.company_name, 'category', r.category, 'emirate', r.emirate),
                   'rfq_invite:' || r.id || ':' || l.id, r.id, null, l.id);
          end if;
        end loop;
      end if;
      update public.inquiries
         set routing = coalesce(routing, '{}'::jsonb) || jsonb_build_object('short_sweep', jsonb_build_object(
               'at', now(), 'quotes_then', r.live_quotes, 'invited', v_new, 'trades', to_jsonb(v_codes),
               'by', 'sales_engineer (fn_rfq_short_of_quotes_tick)'))
       where id = r.id;
      v_invited := v_invited + v_new;
    end if;

    -- (b) remind each invited supplier who has not quoted, once. Not one invited in the last 2 hours.
    for l in select ld.* from public.inquiry_matches m join public.leads ld on ld.id = m.supplier_id
              where m.inquiry_id = r.id and m.sent_at < now() - interval '2 hours'
                and not exists (select 1 from public.quotes q where q.inquiry_id = r.id and q.supplier_id = m.supplier_id)
                and public.fn_seat_clock_lead_is_fixture(ld) = r.fixture loop
      v := public.fn_seat_clock_deliver('sales_engineer', 'rfq_quote_reminder', 'supplier',
             lower(btrim(coalesce(nullif(btrim(l.claimed_by), ''), l.email))), r.fixture, l.locale, 'rfq_quote_reminder',
             jsonb_build_object('name', l.company_name, 'category', r.category, 'emirate', r.emirate, 'deadline', r.deadline),
             'rfq_quote_reminder:' || r.id || ':' || l.id, r.id, null, l.id);
      if coalesce((v->>'ok')::boolean, false) and not coalesce((v->>'already')::boolean, false) then v_reminded := v_reminded + 1; end if;
    end loop;

    -- (c) at the deadline, tell the customer once.
    if now() >= r.deadline then
      v := public.fn_seat_clock_deliver('sales_engineer', 'rfq_short_of_quotes', 'customer', r.cemail, r.fixture, r.clocale,
             'rfq_short_of_quotes',
             jsonb_build_object('name', r.cname, 'category', r.category, 'emirate', r.emirate, 'quotes', r.live_quotes),
             'rfq_short_of_quotes:' || r.id, r.id);
      if coalesce((v->>'ok')::boolean, false) and not coalesce((v->>'already')::boolean, false) then v_told := v_told + 1;
      elsif not coalesce((v->>'ok')::boolean, false) then
        v_skipped := v_skipped || jsonb_build_array(jsonb_build_object('inquiry_id', r.id, 'reason', v->>'reason'));
      end if;
    end if;
  end loop;

  return jsonb_build_object('ok', true, 'swept', v_swept, 'invited', v_invited, 'reminded', v_reminded,
                            'customers_told', v_told, 'not_written', v_skipped,
                            'deadline_hours', v_window, 'sweep_from_hours_before', v_lead);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_role_identity_isolation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_other text;
begin
  select string_agg(o.packaged_role_id || ' (' || o.archetype || ')', ', '
                    order by o.packaged_role_id)
    into v_other
    from public.org_role_identity o
   where o.agent_key = new.agent_key
     and o.packaged_department = new.packaged_department
     and o.packaged_role_id <> new.packaged_role_id
     and ( (    new.archetype = 'reviewer-auditor'
            and o.archetype in ('director','operations-specialist','analyst-controller'))
        or (    o.archetype = 'reviewer-auditor'
            and new.archetype in ('director','operations-specialist','analyst-controller')) );

  if v_other is null then
    return new;
  end if;

  -- The conflict may exist, but only as a decision somebody signed for — and signed for THIS
  -- archetype.  Matching on (agent_key, packaged_role_id) alone was tried and probed: it let
  -- payments-and-revenue-operations-analyst-controller be redefined to reviewer-auditor on the
  -- strength of a decision that had been recorded about the analyst-controller identity.  A
  -- decision about one identity is not consent for a different one.
  if exists (select 1 from public.role_isolation_decision d
              where d.agent_key = new.agent_key
                and d.packaged_role_id = new.packaged_role_id
                and d.archetype = new.archetype) then
    return new;
  end if;

  raise exception
    'agent % would be both producer and independent reviewer of % (this row: % as %; also holds: %)',
    new.agent_key, new.packaged_department, new.packaged_role_id, new.archetype, v_other
    using errcode = '23514',
          hint = 'record the call in role_isolation_decision first: '
                 'isolate | split | restrict_to_advisory | block';
end $function$


CREATE OR REPLACE FUNCTION public.fn_role_of(p_email text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  e text := lower(trim(coalesce(p_email,'')));
  v_role text;
  v_from date;
  v_on boolean;
begin
  if e = '' then return 'guest'; end if;

  -- Human identities first: unchanged behaviour, still wins over everything.
  select ur.role into v_role from user_roles ur
   where ur.email = e
   order by array_position(array['owner','admin','ops','finance','support','agent'], ur.role)
   limit 1;
  if v_role is not null then return v_role; end if;

  if e = any (string_to_array(lower(coalesce((select value from app_secrets where key='admin_emails'),'')), ','))
    then return 'owner'; end if;

  -- AGENT IDENTITY. Only for values that are not email addresses, so a real
  -- person can never be mistaken for an employee record.
  if position('@' in e) = 0 then
    if exists (select 1 from org_agents where lower(agent_key) = e and active) then
      v_on := lower(coalesce((select value from app_secrets where key='agent_autonomy_enabled'),'true')) = 'true';
      begin
        v_from := coalesce((select value from app_secrets where key='agent_autonomy_from'),'2026-07-30')::date;
      exception when others then v_from := date '2026-07-30';
      end;
      if v_on and current_date >= v_from then
        return 'agent';
      else
        return 'guest';   -- pre-arming: behaviour identical to today
      end if;
    end if;
  end if;

  if exists (select 1 from leads where lower(coalesce(claimed_by,'')) = e) then return 'supplier'; end if;
  if exists (select 1 from customers where lower(coalesce(email,'')) = e) then return 'customer'; end if;
  return 'guest';
end
$function$


CREATE OR REPLACE FUNCTION public.fn_route_party(p_name text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(
    (select a.agent_key from public.org_agents a
      where a.active and a.agent_key = nullif(btrim(coalesce(p_name, '')), '') limit 1),
    (select d.dept_key from public.org_departments d
      where d.dept_key = nullif(btrim(coalesce(p_name, '')), '')
        and exists (select 1 from public.org_agents a2
                     where a2.department = d.dept_key and a2.active) limit 1));
$function$


CREATE OR REPLACE FUNCTION public.fn_routing_tier_model(p_agent_key text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case when a.routing_tier is null then null else jsonb_build_object(
      'routing_tier', a.routing_tier,
      'registry_tier', t.rt,
      'model', (select r.model_id from model_registry r
                 where r.active and r.approved and r.tier = t.rt
                 order by r.in_per_mtok_usd limit 1)) end
    from org_agents a
    cross join lateral (select case a.routing_tier
                                 when 'reviewer_auditor'      then 'large'
                                 when 'operations_specialist' then 'small'
                                 else 'medium' end as rt) t
   where a.agent_key = coalesce(public.fn_org_agent_resolve(p_agent_key), p_agent_key)
     and coalesce(a.active, true)
   limit 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_run_seat(p_agent text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce((select fo.owner from public.function_owner fo
                    where fo.function_slug = regexp_replace(coalesce(p_agent, ''), '^fn:', '')),
                  regexp_replace(coalesce(p_agent, ''), '^fn:', ''));
$function$


CREATE OR REPLACE FUNCTION public.fn_runner_silence_watch()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_run bigint; n_alert int := 0; n_watched int := 0; v_email text;
begin
  insert into agent_runs(agent, started_at) values ('runner_silence_watch', clock_timestamp()) returning id into v_run;

  select to_email into v_email from notifications
   where type='founder_brief' and to_email is not null order by created_at desc limit 1;

  -- RE-DERIVE, NEVER SEED. One pass over 30 days of runs gives every runner its own observed
  -- cadence. A runner seen fewer than 5 times has no cadence worth calling regular and is recorded
  -- as on-demand rather than alerted on — which is what stops this becoming the noise generator the
  -- 18 July snapshot would have been if anything had ever read it.
  with runs as (
    select agent, started_at, counts,
           started_at - lag(started_at) over (partition by agent order by started_at) gap
      from agent_runs
     where started_at > now() - interval '30 days'
       -- 9 SEP 2026: `fn:<slug>` rows are edge-function REQUESTS, written by _shared/observe.ts.
       -- An HTTP endpoint has no cadence — its gaps measure how often somebody called it, not
       -- whether it is working — so learning one here would page about a quiet weekend.
       and agent not like 'fn:%'),
  agg as (
    select agent,
           count(*) as n,
           -- A CADENCE IS NOT A BURST. Measured on the first run: doc_extract, match, quote_compare,
           -- inquiry_intake and stripe_webhook all showed a "median gap" of 0.00-0.08 hours, because
           -- they are EVENT-DRIVEN and fire in clusters when work arrives. Treating a cluster as a
           -- schedule makes every quiet day an alert. A real cadence shows up on separate DAYS, so
           -- that is what is counted.
           count(distinct started_at::date) as active_days,
           -- A RUNNER LOGGED ONLY ON EXCEPTIONS HAS NO CADENCE EITHER. cos_execute writes an
           -- agent_runs row under its own name ONLY when it has a throttled signal to report (a
           -- refused task start); its ordinary hourly work is logged under 'ceo'. So its
           -- rows stop the moment it stops having a PROBLEM, and the first version of this watch
           -- read that as the runner going silent -- alerting daily on a loop that was working.
           count(*) filter (where coalesce(counts ? 'signal', false)) as signal_rows,
           max(started_at) as last_seen,
           percentile_cont(0.5) within group (order by extract(epoch from gap)/3600.0) as median_gap_h
      from runs group by agent)
  insert into agent_expectations (agent, kind, max_silence_hours, on_demand, median_gap_hours,
                                  runs_observed, last_seen, note, updated_at)
  select a.agent,
         case when exists (select 1 from org_agents o where o.agent_key = a.agent) then 'employee' else 'code' end,
         -- Three times its own median, floored at 6 hours and capped at two weeks. Derived from the
         -- runner rather than from its schedule, because the schedule is what fn_agent_silence_watch
         -- already checks and is exactly what stayed green while the work stopped.
         case when a.n >= 5 and a.active_days >= 5 and a.median_gap_h >= 0.5 and a.n > a.signal_rows
              then least(336, greatest(6, ceil(a.median_gap_h * 3)))
              else 999999 end,
         not (a.n >= 5 and a.active_days >= 5 and a.median_gap_h >= 0.5 and a.n > a.signal_rows),
         round(a.median_gap_h::numeric, 2),
         a.n,
         a.last_seen,
         case when a.n >= 5 and a.active_days >= 5 and a.median_gap_h >= 0.5 and a.n > a.signal_rows
              then 'cadence learned from '||a.n||' run(s) across '||a.active_days||' day(s) in 30d, median gap '||round(a.median_gap_h::numeric,2)||'h'
              else 'no steady cadence ('||a.n||' run(s) across '||a.active_days||' day(s), median gap '
                   ||coalesce(round(a.median_gap_h::numeric,2)::text,'n/a')||'h) — event-driven or on-demand, not watched' end,
         now()
    from agg a
  on conflict (agent) do update set
    kind = excluded.kind, max_silence_hours = excluded.max_silence_hours,
    on_demand = excluded.on_demand, median_gap_hours = excluded.median_gap_hours,
    runs_observed = excluded.runs_observed, last_seen = excluded.last_seen,
    note = excluded.note, updated_at = now();

  select count(*) into n_watched from agent_expectations where not on_demand;

  -- EVERY row, not just the watched ones. Scoping this to `not on_demand` left a stale silent=true
  -- on any runner that moved INTO on_demand — measured on the first run: five event-driven runners
  -- kept a silent flag they could no longer clear.
  update agent_expectations e
     set silent = (not e.on_demand
                   and e.last_seen is not null
                   and e.last_seen < now() - (e.max_silence_hours || ' hours')::interval);

  -- ONCE PER SILENCE EPISODE, ONE EMAIL PER RUN (3 Sep 2026). This loop paged the founder once per
  -- silent employee per DAY — 21 "Employee has stopped working" emails in the 24 hours measured on
  -- 3 Sep, 59 all-time — for runners whose schedules were switched off by his own 16 Aug stand-down
  -- and re-enabled on 2-3 Sep. A silence is one fact, not a daily one: an episode is (runner,
  -- last_seen); it is paged the first time it is seen and never again until the runner has run
  -- (a new last_seen is a new episode). And the employees newly silent in one pass go into ONE
  -- email, never one email each. Nothing is hidden: every silent runner is still in
  -- agent_expectations.silent and in the company snapshot.
  declare v_new text := ''; v_new_n int := 0;
  begin
  for r in select agent, kind, last_seen, max_silence_hours, median_gap_hours
             from agent_expectations where silent and not on_demand order by agent
  loop
    if not exists (select 1 from founder_alerts
                    where event='runner_silent'
                      and detail like '%"runner": "'||r.agent||'"%'
                      and detail like '%"last_run": "'||coalesce(r.last_seen::text,'')||'"%') then
      insert into founder_alerts(level, event, detail, channel)
      values (case when r.kind='employee' then 'high' else 'warn' end, 'runner_silent',
        jsonb_build_object('runner', r.agent, 'kind', r.kind,
          'last_run', r.last_seen::text,
          'silent_hours', round(extract(epoch from (now()-r.last_seen))/3600),
          'own_median_gap_hours', r.median_gap_hours,
          'expected_within_hours', r.max_silence_hours)::text, 'email');
      if r.kind = 'employee' then
        v_new_n := v_new_n + 1;
        v_new := v_new || '- ' || r.agent || ': last did anything at ' || coalesce(r.last_seen::text,'unknown')
              || ' (own cadence one run every ' || coalesce(r.median_gap_hours::text,'?') || ' hours)' || E'\n';
      end if;
      n_alert := n_alert + 1;
    end if;
  end loop;
  if v_new_n > 0 then
    -- 6 SEP 2026: routed to the COO as one org_task per condition, never emailed
    -- (founder_mail_policy.runner_silence); this watcher's own founder_alerts rows are its ledger.
    perform public.fn_founder_mail_route('runner_silence',
      v_new_n || ' employee(s) have stopped working',
      'These runners went past their own observed cadence for the first time since they last ran:' || E'\n' || v_new ||
      E'\n' || 'Each is reported once per silence; it will be reported again only after it runs and stops again. ' ||
      'A scheduled job may still be succeeding — this watch looks at what the runner DID, not at whether its schedule fired.',
      'high');
  end if;
  end;

  update agent_runs set finished_at=clock_timestamp(), status='ok',
      counts=jsonb_build_object('runners', (select count(*) from agent_expectations),
                                'watched', n_watched, 'silent', (select count(*) from agent_expectations where silent),
                                'alerts', n_alert,
                                'employees', (select count(*) from agent_expectations where kind='employee'))
   where id=v_run;

  return jsonb_build_object('runners',(select count(*) from agent_expectations),
                            'watched',n_watched,'alerts',n_alert);
exception when others then
  update agent_runs set finished_at=clock_timestamp(), status='error', note=left(sqlerrm,500) where id=v_run;
  raise;
end $function$


CREATE OR REPLACE FUNCTION public.fn_sales_assist(p_text text, p_embedding vector, p_min_similarity numeric DEFAULT 0.86, p_min_rank numeric DEFAULT 0.05, p_k integer DEFAULT 5, p_actor text DEFAULT 'sales_engineer'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_k         int := greatest(1, least(coalesce(p_k, 5), 20));
  -- Per-corpus candidate width. Wider than the answer width so the floors have something to reject
  -- and the decision log records the near-misses that justify the floor.
  v_wide      int := greatest(v_k * 4, 20);
  -- LEXICAL-ONLY ADMISSION BAR. Applied only to rows with no embedding, where there is no vector
  -- to corroborate with. Deliberately 4x p_min_rank's default: it is carrying the whole burden of
  -- proof on its own. Measured basis in the report accompanying this file.
  -- Floored at 0.20 but never BELOW p_min_rank, so a caller that raises the corroboration bar
  -- raises this one too. Without that tie the lexical-only route would be untestable: the probe
  -- that proves a floor bites by raising it above the best hit would leave this route wide open
  -- and conclude the floors do not fire. A gate nobody can prove fires is not a gate.
  c_lex_only  numeric := greatest(0.20, coalesce(p_min_rank, 0));
  -- ponytail: kb_chunks lexical route takes the first 4,000 index matches and ranks those, not the
  -- global best of 2.5m unembedded rows. Ranking every match of a common term would be a table
  -- scan on every portal message. Raise it, or embed the rest, if recall proves short.
  c_kb_scan   int := 4000;
  -- Out of scope by the company's own exclusion, and by slug so it cannot drift.
  c_fnb       text[] := array['cat:catering-companies','cat:bakery-equipment-suppliers',
                              'cat:food-processing-equipment-suppliers','cat:hospitality-supplies-companies',
                              'cat:cold-room-and-refrigeration-suppliers'];
  v_tq        tsquery;
  -- The Arabic arm. company_faq is the only corpus this routine reads that is written in both
  -- languages (22 of its 508 approved rows carry Arabic, measured 18 Sep 2026), and it is the
  -- only corpus here with no precomputed tsvector, so both configurations are built on the fly
  -- for it at no structural cost. fn_ar_norm is the same normaliser fn_support_corpus_search
  -- uses, so an Arabic question reaches an Arabic FAQ by exactly one rule, not two.
  --
  -- AND IT NEEDS THE BEST-TERMS FALLBACK, because the estate has already paid for learning why.
  -- scripts/sql/an_arabic_question_is_not_six_words_that_must_all_appear.sql measured it on
  -- production: the 'arabic' text-search configuration Postgres ships has NO STOPWORD LIST, so
  -- ما / هي / عن / كم / في survive as ordinary content lexemes and websearch_to_tsquery ANDs every
  -- one of them. A nine-word Arabic question then demands one FAQ containing all nine words and
  -- ranks 0.0000 — and because a vector-bearing row here must ALSO corroborate lexically, a good
  -- Arabic embedding hit would be thrown out for want of corroboration that could never arrive.
  -- The Arabic arm would have been a column in a greatest() that contributes nothing.
  --
  -- So the same shape fn_support_corpus_search settled on is used here: the strict query first,
  -- and the SAME lexemes OR'd as a fallback, scored at HALF so a loose match can never outrank a
  -- strict one. Built from the question's own tsvector rather than from a second tokenisation, so
  -- it cannot drift from what was actually searched.
  --
  -- MEASURED on the 508 approved FAQs, 18 Sep 2026, with the recovered Arabic question
  -- "كم تكلفة السقف الجبسي المستعار للمتر المربع في دبي": strict returns 0 rows, the fallback
  -- returns 11. And the floors still hold — the fallback's best row is "ما هو QuotesDone؟" at
  -- ts_rank 0.0169, which halves to 0.0085 and is refused by both the 0.05 corroboration floor and
  -- the 0.20 lexical-only bar. That is the intended shape and worth stating plainly: the fallback's
  -- job is to give an Arabic VECTOR hit something it can corroborate against, not to admit rows on
  -- its own strength. A nearest neighbour is always found; this does not make one citable.
  v_tq_ar     tsquery;
  v_or_ar     text;
  v_tq_ar_or  tsquery;
  -- LEXEME OVERLAP — MEASURED, TRIED, AND REJECTED AS AN ADMISSION RULE. Recorded here because a
  -- rejected relaxation is worth more to the next reader than a silent one.
  --
  -- Over 18 realistic portal questions on 9 Sep 2026, all 5 that fell through did so at
  -- lexical_rank EXACTLY 0.0000 while their best vector hit sat at 0.888–0.916. Not weak evidence
  -- — NO lexical match at all, because websearch_to_tsquery ANDs every term and no single passage
  -- contains all of "dubai & supplier & cover & abu & dhabi". So lowering p_min_rank would have
  -- recovered nothing, and the measurement is what says so rather than a guess.
  --
  -- The obvious relaxation was to corroborate on lexeme OVERLAP instead: admit a row that clears
  -- cosine 0.86 and carries at least 40% of the question's own lexemes literally. It was built,
  -- applied and measured. "does a Dubai supplier cover Abu Dhabi as well" then returned a joinery
  -- FIRE-DOOR CERTIFICATION passage — cosine 0.888, lexemes "dubai" and "suppli" present, subject
  -- entirely wrong. A confidently wrong answer to a procurement question is the exact failure the
  -- floors exist to prevent, so the relaxation was reverted within the hour. The overlap count is
  -- still computed and logged as a DIAGNOSTIC, because it is the cheapest signal for which gaps
  -- are a phrasing problem and which are a genuinely absent subject — it is simply not allowed to
  -- admit anything.
  v_lex       text[];
  v_need      int;
  v_cands     jsonb  := '[]'::jsonb;
  v_cited     text[] := '{}';
  v_answer    jsonb  := '[]'::jsonb;
  v_refusal   text;
  v_norm      text;
  v_gap       public.sales_knowledge_gap%rowtype;
  v_task      bigint;
  v_best_sim  numeric;
  v_best_rank numeric;
  v_best_corp text;
  v_handoff   text;
begin
  if coalesce(btrim(p_text), '') = '' then
    return jsonb_build_object(
    -- THE COMPANY BLOCK. Pinned, never retrieved and never rankable: it is here on every answer,
    -- including the refusals, because a seat with no retrieval hit is exactly the seat most likely
    -- to improvise a fee or a policy. Founder ruling, 9 Sep 2026.
    'company', public.fn_company_context(),
    'ok', false, 'answered', false, 'refusal', 'empty_query');
  end if;

  -- THE QUESTION ARRIVED WITH ITS SCRIPT STRIPPED. See fn_text_lost_its_script for the measured
  -- case. Nothing downstream can answer a question whose letters were replaced by question marks
  -- before it reached us, and filing it as a knowledge gap manufactures a task nobody can work:
  -- org_tasks 578945 sat in the queue for nine days under a title made entirely of them. Refuse
  -- here, say so, and open nothing.
  --
  -- THE REPLY CARRIES BOTH LANGUAGES, AND THAT IS NOT BELT AND BRACES. Every surface in this
  -- estate decides the asker's language from the SCRIPT they typed in — site_assistant tests
  -- /[؀-ۿ]/ against the message, fn_support_corpus_search reads ask_lang the same way. The script
  -- is precisely what was destroyed here: a stripped message is pure ASCII, so every one of those
  -- detectors concludes "English" for the one visitor who most needs the Arabic sentence. The
  -- language is unknowable by construction on this branch, so the choice is not made. 'handoff' is
  -- what the sales_engineer edge function already reads, so putting both paragraphs there is what
  -- makes the Arabic reach a person at all; 'handoff_ar' is kept for a caller that wants the
  -- Arabic alone.
  if public.fn_text_lost_its_script(p_text) then
    return jsonb_build_object(
      'company', public.fn_company_context(),
      'ok', false, 'answered', false, 'refusal', 'text_lost_its_script',
      'handoff', public.fn_text_did_not_survive_reply('en') || E'\n\n'
                 || public.fn_text_did_not_survive_reply('ar'),
      'handoff_en', public.fn_text_did_not_survive_reply('en'),
      'handoff_ar', public.fn_text_did_not_survive_reply('ar'));
  end if;

  v_tq := websearch_to_tsquery('english', p_text);
  -- 21 SEP 2026 — THE ARABIC ARMS EXIST ONLY FOR A QUESTION WRITTEN IN ARABIC. Measured on
  -- production with the customer's English question "the quote excludes scaffolding above 4 m but
  -- my ceilings are 3.2 m, does that exclusion matter": the 'arabic' configuration has no stopword
  -- list, so 'the', 'does', 'that', 'are' became query lexemes, and ts_rank scores PARTIAL matches —
  -- FAQ 624 "Does a Dubai supplier cover Abu Dhabi as well?" ranked 0.7640 under the strict Arabic
  -- query while `@@` was FALSE for it. Five unrelated FAQs cleared the 0.20 lexical-only bar that
  -- way and were dumped on the customer as the answer. An English question now carries null Arabic
  -- arms, and (below) every rank is gated by its own `@@`, so a rank can no longer be earned by a
  -- query the row does not actually match.
  if p_text ~ '[؀-ۿ]' then
    v_tq_ar := websearch_to_tsquery('arabic', public.fn_ar_norm(p_text));
    select nullif(array_to_string(array(
             select lexeme from unnest(to_tsvector('arabic', public.fn_ar_norm(p_text)))), ' | '), '')
      into v_or_ar;
    v_tq_ar_or := case when v_or_ar is null then null else to_tsquery('arabic', v_or_ar) end;
  else
    v_tq_ar := null; v_or_ar := null; v_tq_ar_or := null;
  end if;
  select array_agg(distinct u.lexeme) into v_lex from unnest(to_tsvector('english', p_text)) u;
  v_need := least(coalesce(cardinality(v_lex), 0), greatest(2, ceil(0.4 * coalesce(cardinality(v_lex), 0))::int));

  -- Every corpus produces the same six columns so the union is a fact about provenance, not about
  -- shape. `route` records HOW a row could be admitted, and is what stops a vector-bearing row
  -- being let in on lexical evidence alone.
  create temporary table if not exists _sa_cand (
    corpus text, record_id text, title text, content text, provenance text,
    similarity numeric, lexical_rank numeric, has_vector boolean, lex_hits int default 0
  ) on commit drop;
  -- truncate, not delete: the estate has a guard that refuses an unqualified DELETE, and a
  -- WHERE-less delete on a scratch table is exactly what that guard exists to catch elsewhere.
  truncate table _sa_cand;

  -- sales_knowledge — the seat's own pack. 1,136 rows, 100% embedded.
  if p_embedding is not null then
    insert into _sa_cand
    select 'sales_knowledge', k.record_id, k.title, left(k.content, 4000),
           coalesce(k.record_type, '') || case when k.domain is null then '' else ' · ' || k.domain end
             || case when k.epistemic_status is null then '' else ' · ' || k.epistemic_status end,
           (1 - (k.embedding_gte <=> p_embedding))::numeric,
           coalesce(ts_rank(k.search, v_tq), 0)::numeric * (case when k.search @@ v_tq then 1 else 0 end),
           true,
           (select count(*) from unnest(k.search) u where u.lexeme = any (v_lex))
      from sales_knowledge k
     where k.embedding_gte is not null
     order by k.embedding_gte <=> p_embedding
     limit v_wide;
  end if;
  insert into _sa_cand
  select 'sales_knowledge', k.record_id, k.title, left(k.content, 4000),
         coalesce(k.record_type, ''), null::numeric, ts_rank(k.search, v_tq)::numeric, false, 0
    from sales_knowledge k
   where k.embedding_gte is null and k.search @@ v_tq
   order by ts_rank(k.search, v_tq) desc
   limit v_wide;

  -- ops_knowledge — 9,139 rows, 100% embedded, tsv + hnsw.
  if p_embedding is not null then
    insert into _sa_cand
    select 'ops_knowledge', o.record_id, o.title, left(o.content, 4000),
           coalesce(o.record_type, '') || case when o.authority_tier is null then '' else ' · authority ' || o.authority_tier end,
           (1 - (o.embedding_gte <=> p_embedding))::numeric,
           coalesce(ts_rank(o.tsv, v_tq), 0)::numeric * (case when o.tsv @@ v_tq then 1 else 0 end),
           true,
           (select count(*) from unnest(o.tsv) u where u.lexeme = any (v_lex))
      from ops_knowledge o
     where o.embedding_gte is not null
       and coalesce(o.supersession_state, 'current') = 'current'   -- never quote a superseded rule
     order by o.embedding_gte <=> p_embedding
     limit v_wide;
  end if;

  -- kb_chunks — 2,686,026 rows. Both routes matter here and the lexical one matters most: 93.8% of
  -- this corpus has no vector at all, so a vector-only reader sees 6% of the category and trade
  -- field body.
  if p_embedding is not null then
    insert into _sa_cand
    select 'kb_chunks', c.id::text, c.title, left(c.content, 4000),
           coalesce(c.source_kind, '') || case when c.category is null then '' else ' · ' || c.category end
             || case when c.citation is null then '' else ' · ' || c.citation end,
           (1 - (c.embedding_gte <=> p_embedding))::numeric,
           coalesce(ts_rank(c.fts, v_tq), 0)::numeric * (case when c.fts @@ v_tq then 1 else 0 end),
           true,
           (select count(*) from unnest(c.fts) u where u.lexeme = any (v_lex))
      from kb_chunks c
     where c.embedding_gte is not null
     order by c.embedding_gte <=> p_embedding
     limit v_wide;
  end if;
  insert into _sa_cand
  select 'kb_chunks', x.id::text, x.title, left(x.content, 4000),
         coalesce(x.source_kind, '') || case when x.category is null then '' else ' · ' || x.category end
           || case when x.citation is null then '' else ' · ' || x.citation end,
         null::numeric, ts_rank(x.fts, v_tq)::numeric, false, 0
    from (select c.id, c.title, c.content, c.source_kind, c.category, c.citation, c.fts
            from kb_chunks c
           where c.embedding_gte is null and c.fts @@ v_tq
           limit c_kb_scan) x
   order by ts_rank(x.fts, v_tq) desc
   limit v_wide;

  -- agent_knowledge — 2,556 rows. The 1,627 'cat:%' rows carry no embedding, which is exactly why
  -- section 1 of this file exists. F&B excluded by slug.
  if p_embedding is not null then
    insert into _sa_cand
    select 'agent_knowledge', a.id::text, a.topic, left(a.content, 4000),
           a.agent_key || case when a.layer is null then '' else ' · ' || a.layer end,
           (1 - (a.embedding_gte <=> p_embedding))::numeric,
           coalesce(ts_rank(a.search, v_tq), 0)::numeric * (case when a.search @@ v_tq then 1 else 0 end),
           true,
           (select count(*) from unnest(a.search) u where u.lexeme = any (v_lex))
      from agent_knowledge a
     where a.embedding_gte is not null
       and not (a.agent_key = any (c_fnb))
       and coalesce(a.validation_status, '') <> 'quarantined'
     order by a.embedding_gte <=> p_embedding
     limit v_wide;
  end if;
  insert into _sa_cand
  select 'agent_knowledge', a.id::text, a.topic, left(a.content, 4000),
         a.agent_key || case when a.layer is null then '' else ' · ' || a.layer end,
         null::numeric, ts_rank(a.search, v_tq)::numeric, false, 0
    from agent_knowledge a
   where a.embedding_gte is null and a.search @@ v_tq
     and not (a.agent_key = any (c_fnb))
     and coalesce(a.validation_status, '') <> 'quarantined'
   order by ts_rank(a.search, v_tq) desc
   limit v_wide;

  -- support_knowledge — 408 rows, tsvector only. Lexical is not a fallback here, it is the only
  -- instrument the table has.
  insert into _sa_cand
  select 'support_knowledge', s.record_id, s.title, left(s.body, 4000),
         coalesce(s.record_kind, '') || case when s.domain is null then '' else ' · ' || s.domain end,
         null::numeric, ts_rank(s.search, v_tq)::numeric, false, 0
    from support_knowledge s
   where s.search @@ v_tq
     and coalesce(s.runtime_index_eligible, true)
   order by ts_rank(s.search, v_tq) desc
   limit v_wide;

  -- category_specs / category_quote_specs — 56 and 141 rows, no index of any kind. Small enough to
  -- vectorise the tsquery on the fly, and they answer the single most common portal question there
  -- is: what does this category actually require.
  insert into _sa_cand
  select 'category_specs', cs.category, cs.label,
         left('Supplier requirements: ' || coalesce(cs.supplier_requirements::text, 'none recorded')
           || E'\nCompliance checklist: ' || coalesce(cs.compliance_checklist::text, 'none recorded')
           || E'\nQuote fields: ' || coalesce(cs.fields::text, 'none recorded'), 4000),
         'category spec · ' || cs.category, null::numeric,
         ts_rank(to_tsvector('english', coalesce(cs.category,'') || ' ' || coalesce(cs.label,'') || ' '
                 || coalesce(cs.supplier_requirements::text,'') || ' ' || coalesce(cs.compliance_checklist::text,'')), v_tq)::numeric,
         false, 0
    from category_specs cs
   where to_tsvector('english', coalesce(cs.category,'') || ' ' || coalesce(cs.label,'') || ' '
         || coalesce(cs.supplier_requirements::text,'') || ' ' || coalesce(cs.compliance_checklist::text,'')) @@ v_tq
   limit v_wide;

  insert into _sa_cand
  select 'category_quote_specs', q.id::text, q.label,
         left('Aspect: ' || coalesce(q.aspect, '—') || E'\nMandatory: ' || coalesce(q.mandatory::text, 'unknown')
           || E'\n' || coalesce(q.note, ''), 4000),
         'quote spec · ' || coalesce(q.spec_group, ''), null::numeric,
         ts_rank(to_tsvector('english', coalesce(q.spec_group,'') || ' ' || coalesce(q.aspect,'') || ' '
                 || coalesce(q.label,'') || ' ' || coalesce(q.note,'')), v_tq)::numeric,
         false, 0
    from category_quote_specs q
   where to_tsvector('english', coalesce(q.spec_group,'') || ' ' || coalesce(q.aspect,'') || ' '
         || coalesce(q.label,'') || ' ' || coalesce(q.note,'')) @@ v_tq
   limit v_wide;

  -- company_faq — 508 approved rows, 466 embedded, 22 carrying Arabic (measured 18 Sep 2026).
  -- THE CORPUS THIS ROUTINE COULD NOT SEE, AND THE ONE THE COMPANY WRITES ITS ANSWERS INTO.
  --
  -- Measured, 18 Sep 2026, against the 13 recorded rows of sales_knowledge_gap: two of them
  -- ("does a Dubai supplier cover Abu Dhabi as well" and "what documents does a supplier need for
  -- verification") are answered by an approved FAQ whose question is almost the asked sentence —
  -- lexical rank 0.9888 and 0.9640. An aborted probe of the deployed routine on the same day
  -- returned answered=false, refusal=no_candidates for the first of them while FAQ 624, titled
  -- "Does a Dubai supplier cover Abu Dhabi as well?", sat approved and published.
  --
  -- The sharper half of that measurement: both FAQs were WRITTEN IN RESPONSE to those two gaps
  -- (created 2026-09-09 21:14, after the questions were refused). So the remediation loop closes
  -- into a table this routine cannot read — a gap answered for the support seat stays open for the
  -- sales seat, and the same question asked by a signed-in customer refuses again. The task text
  -- this routine writes says DONE MEANS "the knowledge exists in a searchable corpus"; company_faq
  -- was not one of them.
  --
  -- WHY THE FAQ IS ADDED HERE RATHER THAN DELEGATED TO fn_support_corpus_search. That routine
  -- already owns FAQ retrieval for the support seat, and delegating was the first instinct. It
  -- reads v_support_corpus, which is company_faq UNION support_knowledge UNION ops_knowledge —
  -- two corpora this routine already reads on its own terms — and it ranks on a different scale
  -- (ts_rank plus a flat +1.0 bonus for the asker's language). Calling it would put two admission
  -- rules behind one answer, double-count two corpora, and leave sales_decision_log unable to say
  -- which rule admitted a row. The subject this routine was missing is not "FAQ retrieval", it is
  -- "the FAQ table", so the table is what it reads — under the one admission rule it already has,
  -- with the same status = 'approved' predicate v_support_corpus applies, so "published" means the
  -- same thing to both readers and there is still exactly one definition of it.
  --
  -- NOT COVERED HERE, said plainly: ops_knowledge holds 173 Arabic-bearing rows whose tsv column
  -- is built with the english configuration, so an Arabic question still cannot reach those
  -- lexically. Rebuilding that column is a change to a different subject and is not in this file.
  -- Both routes read the SAME haystack expression through one subquery, so each row's english and
  -- arabic tsvectors are built once per statement instead of once per clause. `ar_rank` is the
  -- strict Arabic rank, `ar_loose` the best-terms fallback at half weight; the lexical rank a row
  -- carries into admission is the best of the three, so a strict hit in either language always
  -- beats a loose one and English is scored exactly as it was before this change.
  if p_embedding is not null then
    insert into _sa_cand
    select 'company_faq', h.id::text, h.title, left(h.body, 4000), h.provenance,
           (1 - (h.embedding_gte <=> p_embedding))::numeric,
           greatest(case when h.te @@ v_tq then ts_rank(h.te, v_tq) else 0 end,
                    case when v_tq_ar is not null and h.ta @@ v_tq_ar then ts_rank(h.ta, v_tq_ar) else 0 end,
                    case when v_tq_ar_or is not null and h.ta @@ v_tq_ar_or then ts_rank(h.ta, v_tq_ar_or) * 0.5 else 0 end)::numeric,
           true,
           (select count(*) from unnest(h.te) u where u.lexeme = any (v_lex))
      from (select f.id, coalesce(f.question, '') as title, coalesce(f.answer, '') as body,
                   f.embedding_gte,
                   'FAQ' || case when f.section is null then '' else ' · ' || f.section end
                         || ' · ' || coalesce(f.language, 'en') as provenance,
                   to_tsvector('english', coalesce(f.question, '') || ' ' || coalesce(f.answer, '')) as te,
                   to_tsvector('arabic', public.fn_ar_norm(coalesce(f.question, '') || ' ' || coalesce(f.answer, ''))) as ta
              from company_faq f
             where f.embedding_gte is not null
               and f.status = 'approved'
             order by f.embedding_gte <=> p_embedding
             limit v_wide) h;
  end if;
  insert into _sa_cand
  select 'company_faq', h.id::text, h.title, left(h.body, 4000), h.provenance,
         null::numeric, h.lex_rank, false, 0
    -- The outer select reads the alias g. It read f (the inner table's alias) until 21 Sep 2026 —
    -- the dry run passed and the routine failed on its first call with 42P01 "missing FROM-clause
    -- entry for table f", measured by running it inside an aborted transaction.
    from (select g.id, coalesce(g.question, '') as title, coalesce(g.answer, '') as body,
                 'FAQ' || case when g.section is null then '' else ' · ' || g.section end
                       || ' · ' || coalesce(g.language, 'en') as provenance,
                 greatest(case when g.te @@ v_tq then ts_rank(g.te, v_tq) else 0 end,
                          case when v_tq_ar is not null and g.ta @@ v_tq_ar then ts_rank(g.ta, v_tq_ar) else 0 end,
                          case when v_tq_ar_or is not null and g.ta @@ v_tq_ar_or then ts_rank(g.ta, v_tq_ar_or) * 0.5 else 0 end)::numeric as lex_rank
            from (select f.*,
                         to_tsvector('english', coalesce(f.question, '') || ' ' || coalesce(f.answer, '')) as te,
                         to_tsvector('arabic', public.fn_ar_norm(coalesce(f.question, '') || ' ' || coalesce(f.answer, ''))) as ta
                    from company_faq f
                   where f.embedding_gte is null
                     and f.status = 'approved') g
           where (g.te @@ v_tq
               or (v_tq_ar is not null and g.ta @@ v_tq_ar)
               or (v_tq_ar_or is not null and g.ta @@ v_tq_ar_or))
           order by lex_rank desc
           limit v_wide) h;

  -- ADMISSION. A vector-bearing row must clear the cosine floor AND corroborate lexically. A row
  -- with no vector must clear the stricter lexical-only bar. Nothing else is admitted.
  with judged as (
    select c.*,
           (c.has_vector and c.similarity >= p_min_similarity and c.lexical_rank >= p_min_rank) as ok_vector,
           ((not c.has_vector) and c.lexical_rank >= c_lex_only)                                as ok_lexical
      from _sa_cand c
  ), ranked as (
    select j.*, (j.ok_vector or j.ok_lexical) as cited,
           row_number() over (
             order by (case when j.ok_vector or j.ok_lexical then 0 else 1 end),
                      (case when j.has_vector then 0 else 1 end),
                      j.similarity desc nulls last, j.lexical_rank desc) as rn
      from judged j
  )
  select
    coalesce(jsonb_agg(jsonb_build_object(
      'corpus', r.corpus, 'record_id', r.record_id,
      'similarity', round(r.similarity, 4), 'lexical_rank', round(r.lexical_rank, 4),
      'route', case when r.has_vector then 'vector+lexical' else 'lexical_only' end,
      'cleared_floor', coalesce(r.has_vector and r.similarity >= p_min_similarity, false),
      -- Diagnostic only, deliberately NOT an admission criterion. See the header note.
      'lex_hits', r.lex_hits, 'lex_overlap_would_admit', (v_need > 0 and r.lex_hits >= v_need),
      'corroborated', r.lexical_rank >= (case when r.has_vector then p_min_rank else c_lex_only end),
      'cited', r.cited) order by r.rn) filter (where r.rn <= 40), '[]'::jsonb),
    coalesce(array_agg(r.corpus || ':' || r.record_id order by r.rn)
             filter (where r.cited and r.rn <= v_k), '{}'),
    coalesce(jsonb_agg(jsonb_build_object(
      'corpus', r.corpus, 'record_id', r.record_id, 'title', r.title,
      'provenance', r.provenance,
      'similarity', round(r.similarity, 4), 'lexical_rank', round(r.lexical_rank, 4),
      'route', case when r.has_vector then 'vector+lexical' else 'lexical_only' end,
      'content', r.content) order by r.rn) filter (where r.cited and r.rn <= v_k), '[]'::jsonb)
    into v_cands, v_cited, v_answer
    from ranked r;

  select max(similarity), max(lexical_rank) into v_best_sim, v_best_rank from _sa_cand;
  select corpus into v_best_corp from _sa_cand
   order by similarity desc nulls last, lexical_rank desc limit 1;

  if cardinality(v_cited) = 0 then
    v_refusal := case
      when (select count(*) from _sa_cand) = 0 then 'no_candidates'
      when coalesce(v_best_sim, 0) < p_min_similarity and coalesce(v_best_rank, 0) < c_lex_only
        then 'below_similarity_floor_and_lexical_bar'
      when coalesce(v_best_sim, 0) < p_min_similarity then 'below_similarity_floor'
      else 'not_corroborated_lexically' end;

    -- ── THE FALLBACK IS AN ACTION, NOT A SENTENCE ────────────────────────────────────────────
    -- The founder's objection was never to the honesty of "I do not have that". It was to nothing
    -- happening afterwards. Something happens now: the question is kept, counted, and owned.
    v_norm := left(lower(regexp_replace(btrim(p_text), '\s+', ' ', 'g')), 400);

    select * into v_gap from sales_knowledge_gap where question_norm = v_norm;

    if not found then
      insert into org_tasks (title, detail, status, tier, action_class, assigned_agent,
                             priority, requires_evidence, needs_founder)
      values (
        left('Answer an unanswered portal question: ' || btrim(p_text), 160),
        'A customer or supplier asked this in the portal and the Sales Engineer could not source an '
          || 'answer from any corpus it searches (sales_knowledge, ops_knowledge, kb_chunks, '
          || 'agent_knowledge, support_knowledge, company_faq, category_specs, category_quote_specs).' || E'\n\n'
          || 'QUESTION: ' || btrim(p_text) || E'\n'
          || 'REFUSAL: ' || v_refusal || E'\n'
          || 'CLOSEST THE ESTATE GOT: corpus ' || coalesce(v_best_corp, 'none')
          || ', cosine ' || coalesce(round(v_best_sim, 4)::text, 'n/a')
          || ', lexical rank ' || coalesce(round(v_best_rank, 4)::text, 'n/a')
          || ' (floors: cosine ' || p_min_similarity || ', lexical corroboration ' || p_min_rank
          || ', lexical-only ' || c_lex_only || ').' || E'\n\n'
          || 'DONE MEANS: the knowledge exists in a searchable corpus and this question returns it. '
          || 'Then set sales_knowledge_gap.status to knowledge_added.',
        'assigned', 'advisory', 'knowledge_gap', 'sales_engineer', 3, true, false)
      returning id into v_task;

      insert into sales_knowledge_gap
        (question_norm, question, refusal, best_similarity, best_lexical_rank, nearest_corpus, task_id)
      values (v_norm, left(btrim(p_text), 2000), v_refusal,
              round(v_best_sim, 4), round(v_best_rank, 4), v_best_corp, v_task);
    else
      v_task := v_gap.task_id;
      update sales_knowledge_gap
         set asks = asks + 1, last_asked_at = now(), refusal = v_refusal,
             best_similarity = greatest(coalesce(best_similarity, 0), coalesce(round(v_best_sim, 4), 0)),
             best_lexical_rank = greatest(coalesce(best_lexical_rank, 0), coalesce(round(v_best_rank, 4), 0))
       where id = v_gap.id;
      -- Asked repeatedly is the definition of urgent. The task's priority follows the demand.
      update org_tasks set priority = least(9, greatest(priority, 3 + v_gap.asks)), updated_at = now()
       where id = v_task and status not in ('done', 'cancelled');
    end if;

    v_handoff :=
      'I have not got a sourced answer to that yet, and I will not guess at a procurement question. '
      || 'I have recorded it and opened task #' || coalesce(v_task::text, '?')
      || ', owned by the Sales Engineer, with your question kept word for word. '
      || 'It is being looked into and you will get an answer on it.';
  end if;

  insert into sales_decision_log
    (actor, action, query, min_similarity, min_rank, k, candidates, cited, answered, refusal)
  values
    (coalesce(p_actor, 'sales_engineer'), 'assist', left(p_text, 2000), p_min_similarity,
     p_min_rank, v_k, v_cands, v_cited, cardinality(v_cited) > 0, v_refusal);

  return jsonb_build_object(
    -- THE COMPANY BLOCK. Pinned, never retrieved and never rankable: it is here on every answer,
    -- including the refusals, because a seat with no retrieval hit is exactly the seat most likely
    -- to improvise a fee or a policy. Founder ruling, 9 Sep 2026.
    'company', public.fn_company_context(),
    
    'ok', true,
    'answered', cardinality(v_cited) > 0,
    'records', v_answer,
    'cited', v_cited,
    'candidates', v_cands,
    'corpora', jsonb_build_array('sales_knowledge','ops_knowledge','kb_chunks','agent_knowledge',
                                 'support_knowledge','company_faq','category_specs','category_quote_specs'),
    'floor', jsonb_build_object(
      'min_similarity', p_min_similarity, 'min_rank', p_min_rank, 'lexical_only', c_lex_only,
      'lexemes_in_question', coalesce(cardinality(v_lex), 0), 'lexeme_overlap_needed', v_need, 'k', v_k,
      'rule', 'a row with an embedding must clear the cosine floor AND match the all-terms lexical query at ts_rank >= min_rank. A row with no embedding cannot be put to the vector floor at all and must clear the stricter lexical-only bar instead. lexeme_overlap_needed is reported as a diagnostic only: admitting on partial overlap was measured and returned a topically wrong passage, so it does not admit. A nearest neighbour is always found; a lexical match is not.'),
    'refusal', v_refusal,
    'gap_recorded', case when cardinality(v_cited) = 0 then true else false end,
    'task_id', v_task,
    'handoff', v_handoff);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_sales_engineer_acts_on_handoff(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  a public.agent_actions; d jsonb; t text;
  v_cust record; v_sup record; v_inq text; v_window int; v_chase int; v_min int; v_max int;
  v_tx public.transactions; v_amt text; v_req bigint; v_lines text; v_orig public.notifications;
  v_revealed text; v_rid text;
begin
  select * into a from public.agent_actions where id = p_id;
  d := a.detail; t := d->>'type';
  select refund_window_working_days, chase_after_working_days, bank_settlement_working_days_min, bank_settlement_working_days_max
    into v_window, v_chase, v_min, v_max from public.pricing_config order by id limit 1;
  v_window := coalesce(v_window, 5); v_chase := coalesce(v_chase, 3); v_min := coalesce(v_min, 7); v_max := coalesce(v_max, 14);

  select null::uuid as id, null::text as email, null::text as full_name into v_cust;
  select null::bigint as id, null::text as company_name, null::text as email into v_sup;
  if (d->>'customer_id') is not null then
    select id, email, full_name into v_cust from public.customers where id = (d->>'customer_id')::uuid;
  end if;
  if (d->>'supplier_id') is not null then
    select id, company_name, coalesce(claimed_by, email) as email into v_sup from public.leads where id = (d->>'supplier_id')::bigint;
  end if;
  if (d->>'inquiry_id') is not null then
    select summary into v_inq from public.inquiries where id = (d->>'inquiry_id')::uuid;
  end if;
  v_revealed := coalesce(to_char((d->>'revealed_at')::timestamptz at time zone 'Asia/Dubai', 'DD Mon YYYY'), 'the reveal date');
  v_rid := left(coalesce(d->>'transaction_id', d->>'subject_id', ''), 8);

  if t = 'reveal.paid' then
    -- The words trg_reveal_receipt used to write itself, unchanged, now composed by the seat whose
    -- voice the portal is and carried by the seat that owns the pipe.
    if v_cust.email is not null then
      v_req := public.fn_sales_engineer_writes('reveal_receipt', 'customer', v_cust.email, null, v_cust.id,
        (d->>'inquiry_id')::uuid, (d->>'quote_id')::uuid,
        'Reveal confirmed — ' || coalesce(v_sup.company_name, 'supplier'),
        'You have unlocked ' || coalesce(v_sup.company_name, 'the supplier') || '''s contact details'
          || coalesce(' for: ' || left(v_inq, 80), '')
          || '. You can now message them directly in the app. We track this reveal from the moment you paid: if the supplier has not responded within '
          || v_chase::text || ' working days we chase them for you and copy you; if there is still no response by working day '
          || v_window::text || ' the case is decided by our chief executive, and if the supplier never responded everything you paid is refunded in full. '
          || 'Banks usually take ' || v_min || '-' || v_max || ' working days to show a refund. You can also open the request and Report an issue at any time.',
        'اكتمل الكشف — ' || coalesce(v_sup.company_name, 'المورّد'),
        'أصبحت بيانات التواصل مع ' || coalesce(v_sup.company_name, 'المورّد') || ' متاحة لكم الآن، ويمكنكم مراسلته مباشرة من التطبيق. '
          || 'نتابع هذا الكشف منذ لحظة الدفع: إن لم يردّ المورّد خلال ' || v_chase::text || ' أيام عمل فسنتواصل معه نيابةً عنكم مع نسخة إليكم، '
          || 'وإن لم يردّ حتى يوم العمل ' || v_window::text || ' فسيبتّ رئيسنا التنفيذي في الحالة، وإن لم يردّ المورّد إطلاقًا فسنردّ إليكم كامل المبلغ المدفوع.',
        '{}', 'reveal_receipt:' || (d->>'subject_id'), null, jsonb_build_object('transaction_id', d->>'subject_id'));
    end if;
    if coalesce(v_sup.email, '') like '%@%' then
      perform public.fn_sales_engineer_writes('quote_accepted', 'supplier', v_sup.email, v_sup.id, null,
        (d->>'inquiry_id')::uuid, (d->>'quote_id')::uuid,
        'A customer revealed your quote on QuotesDone',
        'A customer paid to reveal your contact for: ' || coalesce(v_inq, '')
          || '. Please respond promptly — under the Supplier Agreement you must respond within ' || v_window::text
          || ' working days of the reveal. If you have not responded after ' || v_chase::text
          || ' working days we chase you with the customer copied; if there is still no response on working day ' || v_window::text
          || ' our chief executive decides the case, the customer is refunded, and the amount refunded plus an AED 250 administrative fee and 9% p.a. interest is recovered from your account.',
        'كشف أحد العملاء عن عرضكم على QuotesDone',
        'سدّد أحد العملاء رسوم الكشف عن بيانات التواصل معكم بشأن: ' || coalesce(v_inq, '') || '. نرجو المبادرة بالرد، إذ تُلزم اتفاقية المورّد بالرد خلال '
          || v_window::text || ' أيام عمل من تاريخ الكشف، وإلا فسيُردّ إلى العميل كامل ما دفعه، ويُسترد المبلغ من حسابكم مع رسوم إدارية قدرها 250 درهمًا وفائدة 9% سنويًا.',
        '{}', 'quote_accepted:' || (d->>'subject_id'), null, jsonb_build_object('transaction_id', d->>'subject_id'));
    end if;
    return jsonb_build_object('customer_reachable', v_cust.email is not null,
                              'supplier_reachable', coalesce(v_sup.email, '') like '%@%',
                              'delivery_request', v_req);

  elsif t = 'payment.failed' then
    if v_cust.email is null then return jsonb_build_object('customer_reachable', false); end if;
    v_req := public.fn_sales_engineer_writes('reveal_payment_incomplete', 'customer', v_cust.email, null, v_cust.id,
      (d->>'inquiry_id')::uuid, (d->>'quote_id')::uuid,
      'Your reveal payment did not complete',
      'Hello ' || coalesce(nullif(btrim(v_cust.full_name), ''), 'there') || E',\n\n'
        || 'Your payment to unlock the supplier''s contact details did not go through, and nothing was charged to your card.' || E'\n\n'
        || 'You can try again at any time: open the request in your QuotesDone portal and choose Reveal on the quote you picked. If the card was declined, your bank can tell you why, and a different card also works.',
      'لم يكتمل دفع رسوم الكشف',
      'تعذّر إتمام دفع رسوم الكشف عن بيانات المورّد، ولم يُخصم أي مبلغ من بطاقتكم. يمكنكم إعادة المحاولة في أي وقت من بوابتكم على QuotesDone.',
      '{}', 'payment_failed:' || (d->>'subject_id'));
    return jsonb_build_object('delivery_request', v_req);

  elsif t = 'payment.received' then
    if coalesce(v_sup.email, '') not like '%@%' then return jsonb_build_object('supplier_reachable', false); end if;
    v_req := public.fn_sales_engineer_writes(coalesce(d->>'msg_type', 'dues_paid'), 'supplier', v_sup.email, v_sup.id, null, null, null,
      case when d->>'kind' = 'supplier_registration' then 'Registration confirmed - thank you' else 'Payment received - thank you' end,
      case when d->>'kind' = 'supplier_registration'
           then 'We have received your registration payment of AED ' || (d->>'amount_aed') || '. Your QuotesDone supplier account is registered for the next 12 months.'
           else 'We have received your payment of AED ' || (d->>'amount_aed') || ' settling ' || coalesce(d->>'items', '1') || ' outstanding charge(s). Your account is now up to date.' end,
      'استلمنا دفعتكم', 'استلمنا دفعتكم البالغة ' || (d->>'amount_aed') || ' درهم، ونشكركم على ذلك.',
      '{}', 'payment_received:' || (d->>'subject_id'));
    return jsonb_build_object('delivery_request', v_req);

  elsif t = 'refund.request_checked' then
    if v_cust.email is null then return jsonb_build_object('customer_reachable', false); end if;
    v_amt := case when (d->>'money_ok')::boolean then ' — AED ' || (d->>'amount_aed') else '' end;
    v_req := public.fn_sales_engineer_writes('refund_request_received', 'customer', v_cust.email, null, v_cust.id,
      (d->>'inquiry_id')::uuid, (d->>'quote_id')::uuid,
      'We have your refund request',
      'Hello ' || coalesce(nullif(btrim(v_cust.full_name), ''), 'there') || E',\n\n'
        || 'We have received your refund request for the reveal on ' || coalesce('"' || left(v_inq, 80) || '"', 'your request') || '.' || E'\n\n'
        || 'What happens next: we check whether the supplier ever replied to you, our chief executive decides on that record, and if the refund is due you get back everything you paid'
        || v_amt || ', the reveal fee and the card processing part together, to the card you paid with. Banks usually take ' || v_min || '–' || v_max || ' working days to show it.' || E'\n\n'
        || 'If you have an email thread with the supplier, keep it: it is the proof we rely on.',
      'استلمنا طلب الاسترداد',
      'استلمنا طلبكم استرداد رسوم الكشف. نتحقق أولًا من ردّ المورّد، ثم يبتّ رئيسنا التنفيذي في الطلب، فإن ثبت استحقاق الاسترداد فسيُعاد إليكم كامل المبلغ المدفوع إلى البطاقة نفسها خلال '
        || v_min || '–' || v_max || ' يوم عمل بحسب البنك.',
      '{}', 'refund_request_received:' || (d->>'subject_id'));
    return jsonb_build_object('delivery_request', v_req, 'money_ok', d->'money_ok');

  elsif t = 'refund.paid' then
    if v_cust.email is null then return jsonb_build_object('customer_reachable', false); end if;
    v_req := public.fn_sales_engineer_writes('refund_issued', 'customer', v_cust.email, (d->>'supplier_id')::bigint, v_cust.id,
      (d->>'inquiry_id')::uuid, (d->>'quote_id')::uuid,
      'Your QuotesDone refund of AED ' || (d->>'amount_aed') || ' has been issued',
      'Hello ' || coalesce(nullif(btrim(v_cust.full_name), ''), 'there') || E',\n\n'
        || 'We have issued a refund of AED ' || (d->>'amount_aed') || ' — everything you paid on ' || v_revealed
        || ', the reveal fee and the card processing part together — to your original payment method, because the supplier did not respond within '
        || v_window::text || ' working days. Nothing is deducted.' || E'\n\n'
        || 'Banks and card issuers usually take ' || v_min || '–' || v_max || ' working days to show it on your statement. If it has not appeared after '
        || v_max || ' working days, reply to this email and we will trace it with the payment processor.' || E'\n\n'
        || 'You are welcome to post the request again; we will introduce you to another supplier.',
      'أصدرنا استردادًا بقيمة ' || (d->>'amount_aed') || ' درهم',
      'أصدرنا لكم استردادًا بقيمة ' || (d->>'amount_aed') || ' درهم، أي كامل المبلغ المدفوع، إلى وسيلة الدفع الأصلية، إذ لم يردّ المورّد خلال '
        || v_window::text || ' أيام عمل. وقد يستغرق ظهوره في كشف حسابكم ' || v_min || '–' || v_max || ' يوم عمل.',
      '{}', 'refund_issued:' || (d->>'subject_id'));
    return jsonb_build_object('delivery_request', v_req, 'amount_aed', d->'amount_aed');

  elsif t = 'refund.declined' then
    if v_cust.email is null then return jsonb_build_object('customer_reachable', false); end if;
    v_req := public.fn_sales_engineer_writes('refund_declined', 'customer', v_cust.email, null, v_cust.id,
      (d->>'inquiry_id')::uuid, (d->>'quote_id')::uuid,
      'About your refund request',
      'Hello ' || coalesce(nullif(btrim(v_cust.full_name), ''), 'there') || E',\n\n'
        || 'We looked at your refund request for the reveal on ' || coalesce('"' || left(v_inq, 80) || '"', 'your request') || ' and it was not approved.' || E'\n\n'
        || 'The reason: ' || coalesce(nullif(btrim(d->>'note'), ''), 'the record shows the supplier did respond.') || E'\n\n'
        || 'If you think we have missed something, reply to this email with what you have — an email thread with the supplier, dates, anything — and we will look again.',
      'بشأن طلب الاسترداد',
      'راجعنا طلب الاسترداد وتعذّرت الموافقة عليه. السبب: ' || coalesce(nullif(btrim(d->>'note'), ''), 'يُظهر السجل أن المورّد قد ردّ.')
        || ' وإن كان لديكم ما يثبت خلاف ذلك، فيسعدنا أن تردّوا على هذه الرسالة لنعيد النظر في الطلب.',
      '{}', 'refund_declined:' || (d->>'subject_id'));
    return jsonb_build_object('delivery_request', v_req);

  elsif t = 'refund.in_progress' then
    if v_cust.email is null then return jsonb_build_object('customer_reachable', false); end if;
    v_req := public.fn_sales_engineer_writes('refund_in_progress', 'customer', v_cust.email, null, v_cust.id,
      (d->>'inquiry_id')::uuid, (d->>'quote_id')::uuid,
      'Your refund is being processed',
      'Hello ' || coalesce(nullif(btrim(v_cust.full_name), ''), 'there') || E',\n\n'
        || 'Your refund of AED ' || coalesce(d->>'amount_aed', '') || ' has been approved and is being processed with the payment provider. It has not reached your card yet; we will write again the moment it has.',
      'استردادكم قيد المعالجة',
      'وافقنا على استردادكم، وهو الآن قيد المعالجة لدى مزوّد الدفع ولم يصل إلى بطاقتكم بعد. وسنُعلمكم فور وصوله.',
      '{}', 'refund_in_progress:' || (d->>'subject_id'));
    return jsonb_build_object('delivery_request', v_req);

  elsif t in ('nonresponse.charge_raised', 'charge.corrected') then
    if coalesce(v_sup.email, '') not like '%@%' then return jsonb_build_object('supplier_reachable', false); end if;
    v_lines := '  Amount refunded to the customer: AED ' || (d->>'refunded_aed') || E'\n'
            || '  Administration fee: AED ' || (d->>'admin_fee_aed') || E'\n'
            || '  Interest: ' || round((d->>'interest_apr')::numeric * 100, 2) || '% a year, simple, on AED '
            || round((d->>'refunded_aed')::numeric + (d->>'admin_fee_aed')::numeric, 2) || ' from ' || (d->>'due_date') || ' until paid' || E'\n'
            || '  Due by: ' || (d->>'due_date');
    if t = 'nonresponse.charge_raised' then
      v_req := public.fn_sales_engineer_writes('nonresponse_charge', 'supplier', v_sup.email, v_sup.id, null,
        (d->>'inquiry_id')::uuid, (d->>'quote_id')::uuid,
        'Charge under the Supplier Agreement — reveal #' || left(coalesce(d->>'transaction_id', ''), 8),
        'Hello ' || coalesce(v_sup.company_name, '') || E',\n\n'
          || 'A customer paid to reveal your contact details and did not hear from you within ' || v_window::text
          || ' working days, despite the reminders we sent. Under the Supplier Agreement the customer has been refunded in full, and that refund is recovered from your account:' || E'\n\n'
          || v_lines || E'\n\n'
          || 'Matching is paused until this is settled. You can pay it from the Billing section of your supplier portal. If you believe it is wrong, use "Dispute this charge" there or reply to this email and we will check the figures against the payment record.',
        'رسوم بموجب اتفاقية المورّد',
        'سدّد أحد العملاء رسوم الكشف عن بيانات التواصل معكم ولم يتلقَّ ردًّا خلال ' || v_window::text || ' أيام عمل رغم التذكيرات، فرُدّ إليه كامل ما دفعه بموجب اتفاقية المورّد، ويُسترد من حسابكم ما يلي: المبلغ المسترد '
          || (d->>'refunded_aed') || ' درهم، ورسوم إدارية ' || (d->>'admin_fee_aed') || ' درهم، وفائدة بسيطة ' || round((d->>'interest_apr')::numeric * 100, 2)
          || '% سنويًا من ' || (d->>'due_date') || ' حتى السداد. ويمكنكم السداد أو الاعتراض من قسم الفواتير في بوابتكم.',
        '{}', 'nonresponse_charge:' || (d->>'subject_id'));
    else
      -- THE CORRECTION MUST REACH WHOEVER GOT THE ORIGINAL: its To and every Cc, not today's address book.
      select * into v_orig from public.notifications where id = (d->>'original_notification_id')::bigint;
      v_req := public.fn_sales_engineer_writes('nonresponse_charge_correction', 'supplier',
        coalesce(v_orig.to_email, v_sup.email), v_sup.id, null, (d->>'inquiry_id')::uuid, (d->>'quote_id')::uuid,
        'Correction: ' || coalesce(v_orig.subject, 'your charge under the Supplier Agreement'),
        'This replaces our message of ' || coalesce(to_char(v_orig.created_at at time zone 'Asia/Dubai', 'DD Mon YYYY'), 'earlier')
          || ' about this charge, which carried the wrong figures. Please disregard it. The correct figures are:' || E'\n\n' || v_lines,
        'تصحيح: رسوم بموجب اتفاقية المورّد',
        'هذه الرسالة تحلّ محلّ رسالتنا السابقة التي تضمنت أرقامًا غير صحيحة. الأرقام الصحيحة: المبلغ المسترد ' || (d->>'refunded_aed')
          || ' درهم، ورسوم إدارية ' || (d->>'admin_fee_aed') || ' درهم، مستحقة في ' || (d->>'due_date') || '.',
        coalesce(v_orig.cc_emails, '{}'), 'charge_corrected:' || (d->>'subject_id'));
    end if;
    return jsonb_build_object('delivery_request', v_req);

  elsif t = 'subscription.due' then
    if coalesce(v_sup.email, '') not like '%@%' then return jsonb_build_object('supplier_reachable', false); end if;
    v_req := public.fn_sales_engineer_writes('subscription_due', 'supplier', v_sup.email, v_sup.id, null, null, null,
      'Your QuotesDone annual subscription is due',
      'Dear ' || coalesce(v_sup.company_name, 'there') || E',\n\nYour QuotesDone annual supplier subscription of '
        || coalesce(d->>'currency', 'AED') || ' ' || (d->>'fee') || E' is now due.\n\nYou keep paying no commission on the jobs you win — this is the annual subscription only. You can settle it securely on the supplier portal: https://quotesdone.com/suppliers\n\nIf it is not settled, your profile is paused from receiving new customer requests until it is.\n\nThank you for being part of QuotesDone.',
      'اشتراككم السنوي في QuotesDone مستحق',
      'حان موعد سداد اشتراككم السنوي كمورّد بقيمة ' || (d->>'fee') || ' درهم، ويمكنكم السداد بأمان من بوابة المورّد.',
      '{}', 'subscription_due:' || (d->>'subject_id'));
    return jsonb_build_object('delivery_request', v_req);

  elsif t = 'billing.answer' then
    v_lines := (select string_agg('  ' || x, E'\n') from jsonb_array_elements_text(d->'facts') x);
    if d->>'party' = 'supplier' then
      if coalesce(v_sup.email, '') not like '%@%' then return jsonb_build_object('supplier_reachable', false); end if;
      v_req := public.fn_sales_engineer_writes('billing_answer', 'supplier', v_sup.email, v_sup.id, null, null, null,
        'Your question about a charge', E'Here is what our records show:\n\n' || coalesce(v_lines, '  Nothing is recorded against your account.'),
        null, null, '{}', 'billing_answer:' || (d->>'subject_id'));
    else
      if v_cust.email is null then return jsonb_build_object('customer_reachable', false); end if;
      v_req := public.fn_sales_engineer_writes('billing_answer', 'customer', v_cust.email, null, v_cust.id, null, null,
        'Your question about a charge', E'Here is what our records show:\n\n' || coalesce(v_lines, '  No payment is recorded on your account.'),
        null, null, '{}', 'billing_answer:' || (d->>'subject_id'));
    end if;
    return jsonb_build_object('delivery_request', v_req, 'facts', d->'facts');

  elsif t = 'charge.dispute_answer' then
    if coalesce(v_sup.email, '') not like '%@%' then return jsonb_build_object('supplier_reachable', false); end if;
    v_lines := (select string_agg('  ' || x, E'\n') from jsonb_array_elements_text(d->'lines') x);
    v_req := public.fn_sales_engineer_writes('charge_dispute_answer', 'supplier', v_sup.email, v_sup.id, null, null, null,
      'Your query about charge #' || coalesce(d->>'due_id', ''),
      case when (d->>'figures_match')::boolean
           then E'We checked the charge against the payment record and the figures stand:\n\n'
           else E'We checked the charge against the payment record and the figures do not match it. It is on hold while our chief executive reviews it; you do not need to pay it until we write again.\n\n' end
        || coalesce(v_lines, ''),
      null, null, '{}', 'charge_dispute_answer:' || (d->>'subject_id'));
    return jsonb_build_object('delivery_request', v_req, 'figures_match', d->'figures_match');

  elsif t = 'refund.remediate' then
    return public.fn_sales_engineer_remediates(p_id);

  elsif t = 'delivery.result' then
    return public.fn_sales_engineer_attaches_delivery_result(p_id);

  elsif t in ('backup.refile', 'backup.remediate') then
    return public.fn_sales_engineer_refiles_backup(p_id);
  end if;
  raise exception 'sales_engineer has no handler for %', t;
end $function$


CREATE OR REPLACE FUNCTION public.fn_sales_engineer_answers_delivery_remediate(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  a public.agent_actions; req public.agent_actions; n public.notifications;
  v_role text; v_failed_email text; v_failed_ch text; v_cust uuid; v_lead bigint; v_subject text; v_body text;
  v_ch text; v_phone text; v_email text; v_rs bigint; v_type text;
begin
  select * into a from public.agent_actions where id = p_id and kind = 'handoff' and detail->>'type' = 'delivery.remediate';
  if not found then raise exception 'fn_sales_engineer_answers_delivery_remediate: % is not a delivery.remediate handoff', p_id; end if;
  select * into req from public.agent_actions where id = (a.detail->>'request_id')::bigint;
  if req.id is null then
    return jsonb_build_object('waiting', 'ceo re-verification', 'resend_request_id', null,
      'reply', 'sales_engineer: request ' || coalesce(a.detail->>'request_id', '?') || ' no longer exists, so there is nothing to resend.');
  end if;
  select * into n from public.notifications
   where id = coalesce((req.detail->>'retry_notification_id')::bigint, (req.evidence->>'notification_id')::bigint);
  v_role := coalesce(req.detail->>'recipient_role', n.to_role);
  v_failed_email := coalesce(n.to_email, req.detail->'prepared'->>'to_email', req.detail->>'to_email');
  if req.detail::text ilike '%ZZ DEMO%' or coalesce(v_failed_email, '') ilike '%@example.invalid' then
    return jsonb_build_object('waiting', 'ceo re-verification', 'resend_request_id', null,
      'reply', 'sales_engineer: a ZZ DEMO fixture; nothing is resent to a fixture address.');
  end if;
  v_failed_ch := coalesce(n.channel, req.detail->'prepared'->>'channel', 'email');
  v_cust := (req.detail->>'customer_id')::uuid;
  v_lead := coalesce((req.detail->>'supplier_id')::bigint, n.lead_id);
  v_type := coalesce(n.type, req.detail->>'msg_type');
  v_subject := coalesce(n.subject, req.detail->'prepared'->>'subject', req.detail->>'subject_en');
  v_body := coalesce(n.body, req.detail->'prepared'->>'body', req.detail->>'body_en');
  if coalesce(btrim(v_body), '') = '' then
    return jsonb_build_object('waiting', 'ceo re-verification', 'resend_request_id', null,
      'reply', 'sales_engineer: the words of the ' || coalesce(v_type, 'notice') || ' are gone, so it cannot be resent.');
  end if;

  if v_failed_ch <> 'whatsapp' then
    v_phone := public.fn_whatsapp_destination(v_role, v_cust, v_lead, v_failed_email);
    if v_phone is not null then v_ch := 'whatsapp'; end if;
  end if;
  if v_ch is null and v_failed_ch <> 'sms' then
    v_phone := public.fn_verified_mobile(v_role, v_cust, v_lead, v_failed_email);
    if v_phone is not null then v_ch := 'sms'; end if;
  end if;
  if v_ch is null then
    v_email := case v_role when 'customer' then (select c.email from public.customers c where c.id = v_cust)
                           when 'supplier' then (select coalesce(l.claimed_by, l.email) from public.leads l where l.id = v_lead) end;
    if coalesce(v_email, '') ~ '@' and v_email !~* '@example\.invalid$'
       and lower(btrim(v_email)) is distinct from lower(btrim(coalesce(v_failed_email, ''))) then
      v_ch := 'email';
    end if;
  end if;
  if v_ch is null then
    return jsonb_build_object('waiting', 'ceo re-verification', 'resend_request_id', null,
      'reply', 'sales_engineer: no other channel is on file for this ' || coalesce(v_role, 'recipient')
               || ' (the ' || v_failed_ch || ' send failed; no confirmed WhatsApp, verified mobile or other email).');
  end if;

  -- retry_of makes fn_originator_checks_delivery escalate rather than retry again if this one fails too.
  v_rs := public.fn_seat_handoff('sales_engineer', 'customer_support', 'delivery.request', 'notifications', 'remediate:' || a.id,
    jsonb_build_object('retry_of', req.id, 'remediate_handoff_id', a.id, 'msg_type', v_type, 'recipient_role', v_role,
      'to_email', coalesce(v_email, v_failed_email), 'supplier_id', v_lead, 'customer_id', v_cust,
      'inquiry_id', coalesce(n.inquiry_id::text, req.detail->>'inquiry_id'), 'quote_id', coalesce(n.quote_id::text, req.detail->>'quote_id'),
      'prepared', jsonb_build_object('type', v_type, 'kind', n.kind, 'to_role', v_role, 'lead_id', v_lead,
        'inquiry_id', coalesce(n.inquiry_id::text, req.detail->>'inquiry_id'), 'quote_id', coalesce(n.quote_id::text, req.detail->>'quote_id'),
        'subject', v_subject, 'body', v_body, 'lang', coalesce(n.lang, req.detail->>'locale', 'en'), 'channel', v_ch,
        'to_email', case when v_ch = 'email' then v_email else v_failed_email end,
        'to_phone', case when v_ch in ('whatsapp', 'sms') then v_phone end)));
  return jsonb_build_object('waiting', 'ceo re-verification', 'resend_request_id', v_rs, 'channel', v_ch,
    'reply', 'sales_engineer resent the ' || coalesce(v_type, 'notice') || ' to the ' || coalesce(v_role, 'recipient')
             || ' by ' || v_ch || ' (request ' || v_rs || ').');
end $function$


CREATE OR REPLACE FUNCTION public.fn_sales_engineer_attaches_delivery_result(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d jsonb; v_tx uuid; v_ev bigint; v_ref bigint; v_delivered boolean; v_rev jsonb; v_rem bigint;
begin
  select detail into d from public.agent_actions where id = p_id;
  v_tx := (d->>'transaction_id')::uuid;
  if v_tx is null then return jsonb_build_object('attached', false, 'reason', 'this delivery was not about a refund'); end if;
  v_delivered := case when d->>'result' = 'proof_of_response' then true
                      else coalesce((d->'evidence'->>'delivered')::boolean, false) end;
  insert into public.refund_ladder_evidence (transaction_id, refund_id, step, result, delivered, evidence, request_handoff_id, result_handoff_id)
  values (v_tx, (d->>'refund_id')::bigint,
          case when d->>'step' in ('chase', 'final_call', 'customer_notice', 'customer_proof') then d->>'step' else 'unknown' end,
          d->>'result', v_delivered, coalesce(d->'evidence', '{}'::jsonb), (d->>'request_id')::bigint, p_id)
  returning id into v_ev;

  if d->>'result' = 'proof_of_response' then
    insert into public.supplier_response_watch (transaction_id, lead_id, first_response_at, response_channel, response_ref)
    select v_tx, t.supplier_id, coalesce((d->'evidence'->'reply'->>'at')::timestamptz, now()),
           d->'evidence'->'reply'->>'channel', d->'evidence'->'reply'->>'ref'
      from public.transactions t where t.id = v_tx
    on conflict (transaction_id) do update
      set first_response_at = coalesce(public.supplier_response_watch.first_response_at, excluded.first_response_at),
          response_channel  = coalesce(public.supplier_response_watch.response_channel, excluded.response_channel),
          response_ref      = coalesce(public.supplier_response_watch.response_ref, excluded.response_ref);
  end if;

  v_rem := (d->>'remediation_id')::bigint;
  if v_rem is not null then
    perform public.fn_seat_handoff_complete(v_rem, jsonb_build_object('ladder_evidence_id', v_ev, 'result', d->>'result', 'delivered', v_delivered));
  elsif d->>'step' = 'final_call' then
    select id into v_ref from public.refunds where transaction_id = v_tx and status = 'requested' order by id desc limit 1;
    if v_ref is not null then v_rev := public.fn_ceo_refund_review(v_ref, 'final_call_result'); end if;
  end if;
  return jsonb_build_object('attached', true, 'ladder_evidence_id', v_ev, 'result', d->>'result', 'delivered', v_delivered, 'ceo_review', v_rev);
end $function$


CREATE OR REPLACE FUNCTION public.fn_sales_engineer_ladder_step(p_transaction_id uuid, p_step text, p_refund_id bigint DEFAULT NULL::bigint, p_remediation_id bigint DEFAULT NULL::bigint)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  t public.transactions; sup record; cust record; st jsonb; v_window int; v_chase int;
  v_final timestamptz; v_watch timestamptz; v_amt numeric; v_key text; v_days int; v_when text; v_extra jsonb;
begin
  select * into t from public.transactions where id = p_transaction_id;
  if not found then raise exception 'no transaction %', p_transaction_id; end if;
  select id, company_name, coalesce(claimed_by, email) as email into sup from public.leads where id = t.supplier_id;
  select id, email, full_name into cust from public.customers where id = t.customer_id;
  select refund_window_working_days, chase_after_working_days into v_window, v_chase from public.pricing_config order by id limit 1;
  v_window := coalesce(v_window, 5); v_chase := coalesce(v_chase, 3);
  st := public.fn_refund_state(t.id);
  v_final := (st->>'founder_call_due_at')::timestamptz;
  v_amt := round(coalesce(t.total_charged, t.reveal_fee, 0), 2);
  v_key := p_step || ':' || t.id || coalesce(':r' || p_remediation_id, '');
  v_days := coalesce((select (d.value #>> '{}')::int from public.decision_policy d where d.key = 'refund_final_call_watch_working_days'), 1);
  v_when := to_char(t.revealed_at at time zone 'Asia/Dubai', 'DD Mon YYYY');
  v_extra := jsonb_build_object('step', p_step, 'transaction_id', t.id, 'refund_id', p_refund_id, 'remediation_id', p_remediation_id);

  if p_step = 'chase' then
    v_watch := case when p_remediation_id is not null then public.fn_add_working_days(now(), 1)
                    else coalesce(v_final, public.fn_add_working_days(now(), greatest(v_window - v_chase, 1))) end;
    return public.fn_sales_engineer_writes('supplier_no_response_chase', 'supplier', sup.email, t.supplier_id, null, t.inquiry_id, t.quote_id,
      'Action needed: a customer is waiting for your response — QuotesDone reveal #' || left(t.id::text, 8),
      'Hello ' || coalesce(sup.company_name, '') || E',\n\n'
        || 'A customer paid to reveal your contact details on QuotesDone on ' || v_when || ' and has not heard from you. ' || v_chase
        || ' working days have passed. The customer is copied on this email so you can reply to all and pick it up here.' || E'\n\n'
        || 'Under the Supplier Agreement you must respond within ' || v_window || ' working days of the reveal, that is by '
        || coalesce(to_char(v_final at time zone 'Asia/Dubai', 'DD Mon YYYY'), 'the deadline')
        || '. If there is no response by then, our chief executive decides the case and the customer is refunded everything they paid (AED ' || v_amt
        || '). Under the supplier terms that amount is then recovered from your account with an administrative fee of AED 250 and interest at 9% a year until settled, and matching is paused until it is paid.' || E'\n\n'
        || 'If you have already been in touch with this customer, reply here and we will close this off.',
      'إجراء مطلوب: عميل بانتظار ردّكم — QuotesDone',
      'سدّد أحد العملاء رسوم الكشف عن بيانات التواصل معكم بتاريخ ' || v_when || ' ولم يتلقَّ منكم ردًّا بعد مرور ' || v_chase || ' أيام عمل، والعميل مُدرَج في نسخة هذه الرسالة. '
        || 'وتُلزم اتفاقية المورّد بالرد خلال ' || v_window || ' أيام عمل من تاريخ الكشف، وإلا فسيُردّ إلى العميل كامل ما دفعه (' || v_amt
        || ' درهم)، ويُسترد المبلغ من حسابكم مع رسوم إدارية قدرها 250 درهمًا وفائدة 9% سنويًا حتى السداد. وإن كنتم قد تواصلتم مع العميل، فيُرجى الرد على هذه الرسالة.',
      array_remove(array[cust.email], null), v_key, v_watch, v_extra);

  elsif p_step = 'final_call' then
    v_watch := public.fn_add_working_days(now(), v_days);
    return public.fn_sales_engineer_writes('refund_final_notice', 'supplier', sup.email, t.supplier_id, null, t.inquiry_id, t.quote_id,
      'Final call: a customer is still waiting — QuotesDone reveal #' || left(t.id::text, 8),
      'Hello ' || coalesce(sup.company_name, '') || E',\n\n'
        || 'This is our final call about the customer who paid to reveal your contact details on ' || v_when
        || '. The ' || v_window || ' working days the Supplier Agreement allows have passed with no response from you, to the customer or to our reminder.' || E'\n\n'
        || 'If we do not hear from you by ' || to_char(v_watch at time zone 'Asia/Dubai', 'DD Mon YYYY')
        || ', the customer is refunded everything they paid (AED ' || v_amt || ') and that amount is recovered from your account with an administrative fee of AED 250 and interest at 9% a year. '
        || 'Reply to this email, message the customer in your portal, or answer us on WhatsApp — any of them stops this.',
      'نداء أخير: عميل لا يزال بانتظار ردّكم — QuotesDone',
      'هذا نداؤنا الأخير بشأن العميل الذي كشف عن بيانات التواصل معكم بتاريخ ' || v_when || '، وقد انقضت أيام العمل المحددة دون ردّ منكم. '
        || 'فإن لم يصلنا ردّكم حتى ' || to_char(v_watch at time zone 'Asia/Dubai', 'DD Mon YYYY') || ' فسيُردّ إلى العميل كامل ما دفعه (' || v_amt
        || ' درهم)، ويُسترد المبلغ من حسابكم مع رسوم إدارية قدرها 250 درهمًا وفائدة 9% سنويًا. ويكفي أي ردّ منكم عبر البريد الإلكتروني أو البوابة أو واتساب لإيقاف ذلك.',
      array_remove(array[cust.email], null), v_key, v_watch, v_extra);

  elsif p_step = 'customer_proof' then
    return public.fn_sales_engineer_writes('refund_proof_request', 'customer', cust.email, null, t.customer_id, t.inquiry_id, t.quote_id,
      'Anything you sent the supplier helps your refund case',
      'Hello ' || coalesce(nullif(btrim(cust.full_name), ''), 'there') || E',\n\n'
        || 'If you tried to reach the supplier yourself, forwarding that email to supplier@mail.quotesdone.com (or replying to it with that address in copy) puts it on your case and can help us close it faster. '
        || 'It is optional: it is never a condition of the refund, and you do not need to do anything for your case to be decided.',
      'مراسلاتكم مع المورّد تدعم حالة الاسترداد',
      'إن سبق أن تواصلتم مع المورّد بأنفسكم، فإن إعادة توجيه تلك الرسالة إلى supplier@mail.quotesdone.com (أو الرد عليها مع إضافة هذا العنوان في النسخة) تضمّها إلى حالتكم، وقد تساعدنا على إنهائها أسرع. هذا اختياري وليس شرطًا للاسترداد، ولا يلزمكم أي إجراء ليُبتّ في حالتكم.',
      '{}', v_key, null, v_extra);
  end if;
  raise exception 'no such ladder step %', p_step;
end $function$


CREATE OR REPLACE FUNCTION public.fn_sales_engineer_raises_undecided_submissions(p_include_fixtures boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v jsonb; rep jsonb; v_acted int := 0; v_raised int := 0; v_already int := 0; v_refused jsonb := '[]'::jsonb;
begin
  for r in select l.id, l.company_name, l.registration_submitted_at, l.approval_status
             from public.leads l
            where l.registration_submitted_at < now() - interval '24 hours'
              and coalesce(l.approval_status, '') in ('', 'pending')
              and coalesce(l.banned, false) = false
              and (p_include_fixtures or not (coalesce(l.is_demo, false) or coalesce(l.company_name, '') ~* '^\s*zz\s*demo'
                                              or public.fn_is_demo_email(l.email)))
            order by l.registration_submitted_at loop
    v := public.fn_sales_engineer_verifies_supplier(r.id, 'submission_24h_clock');
    if coalesce((v->>'ok')::boolean, false) and coalesce(v->>'approval_status', '') not in ('', 'pending') then
      v_acted := v_acted + 1;
      continue;
    end if;
    rep := public.fn_support_report_to_ceo(
      'supplier_submission_undecided:' || r.id || ':' || extract(epoch from r.registration_submitted_at)::bigint,
      'elevated',
      'A supplier registration submitted ' || floor(extract(epoch from now() - r.registration_submitted_at) / 3600)::int
        || ' h ago is still undecided — ' || left(coalesce(r.company_name, 'supplier #' || r.id), 120),
      jsonb_build_object('supplier_id', r.id, 'submitted_at', r.registration_submitted_at,
                         'approval_status', coalesce(v->>'approval_status', r.approval_status), 'verification', v),
      jsonb_build_array('sales_engineer re-ran its verification at the 24-hour mark: '
                        || coalesce(v->>'approval_status', 'the verification did not complete (' || coalesce(v->>'error', 'no error') || ')')),
      case when coalesce((v->>'auto_approve')::boolean, true) = false
           then 'Decide the approval. The six items are complete and pricing_config.auto_approve_suppliers is off, so the sales engineer may not approve alone.'
           else 'Decide why the verification cannot settle this registration, and settle it.' end,
      'leads#' || r.id, p_source_agent => 'sales_engineer');
    if not coalesce((rep->>'ok')::boolean, false) then
      v_refused := v_refused || jsonb_build_array(jsonb_build_object('supplier_id', r.id, 'reason', rep->>'reason'));
    elsif coalesce((rep->>'duplicate')::boolean, false) then v_already := v_already + 1;
    else v_raised := v_raised + 1;
    end if;
  end loop;
  return jsonb_build_object('acted', v_acted, 'raised_to_ceo', v_raised, 'already_raised', v_already, 'refused', v_refused);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_sales_engineer_refiles_backup(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  a public.agent_actions; fin jsonb; fout jsonb := '[]'::jsonb; v_att int; v_row bigint; n int; v_out text;
  v_enq boolean := false; s record;
begin
  select * into a from public.agent_actions where id = p_id and kind = 'handoff';
  v_att := coalesce((a.detail->>'refile_attempts')::int, 0) + 1;
  fin := coalesce(a.detail->'files',
           jsonb_build_array(jsonb_build_object('key', 'db:' || (a.detail->>'doc_backup_id'), 'reason', a.detail->>'reason',
                                                'doc_backup_id', (a.detail->>'doc_backup_id')::bigint)));
  for s in select e from jsonb_array_elements(fin) e loop
    v_row := (s.e->>'doc_backup_id')::bigint; v_out := null;
    if v_row is null then
      -- never queued: the enqueue first, then a row of our own for what it does not cover
      if not v_enq then perform public.fn_enqueue_doc_backups(); v_enq := true; end if;
      -- 22 SEP 2026: the row for THIS file, by the join rule of the expected-status view, on the file
      -- in hand. It used to recompute all ~10,600 expected items (2.7 s) once per file, and seven files
      -- put the IT engineer's daily check past PostgREST's 8 s. See the header.
      if s.e->>'kind' = 'generated' then
        select d.id into v_row from public.doc_backups d
         where d.gen_kind = s.e->>'gen_kind' and d.gen_ref = s.e->>'gen_ref'
         order by (d.status = 'done') desc, d.id desc limit 1;
      elsif s.e->>'bucket' is not null then
        select d.id into v_row from public.doc_backups d
         where d.bucket = s.e->>'bucket' and d.path = s.e->>'path'
         order by (d.status = 'done') desc, d.id desc limit 1;
      end if;
      if v_row is null and s.e->>'bucket' is not null and s.e->>'kind' <> 'conversation' then
        insert into public.doc_backups (entity, entity_id, doc_type, bucket, path, file_name, dropbox_path, source, dedupe_key)
        values (split_part(s.e->>'owner', ':', 1), split_part(s.e->>'owner', ':', 2), 'Refiled', s.e->>'bucket', s.e->>'path',
                regexp_replace(s.e->>'path', '^.*/', ''), '/QuotesDone Backup/Refiled/' || (s.e->>'bucket') || '/' || (s.e->>'path'),
                'storage', 'REFILE:' || (s.e->>'bucket') || ':' || (s.e->>'path'))
        on conflict do nothing returning id into v_row;
      elsif v_row is null and s.e->>'kind' = 'generated' then
        insert into public.doc_backups (entity, entity_id, doc_type, source, gen_kind, gen_ref, dropbox_path, dedupe_key)
        values (split_part(s.e->>'owner', ':', 1), split_part(s.e->>'owner', ':', 2), 'Refiled', 'generated', s.e->>'gen_kind', s.e->>'gen_ref',
                '/QuotesDone Backup/Refiled/' || (s.e->>'gen_kind') || '/' || (s.e->>'gen_ref') || '.pdf', 'REFILE:' || (s.e->>'item_key'))
        on conflict do nothing returning id into v_row;
      end if;
      v_out := case when v_row is null then 'cannot_refile: no source to file from' else 'queued' end;
    end if;
    if v_row is not null and v_out is null then
      update public.doc_backups
         set status = 'pending', attempts = 0, verified_at = null, requeued_at = now(),
             error = left('refile ' || v_att || ': ' || coalesce(s.e->>'reason', 'requested') || ' (handoff ' || p_id || ')', 300)
       where id = v_row and status <> 'abandoned';
      get diagnostics n = row_count;
      v_out := case when n = 1 then 'requeued' else 'cannot_refile: row missing or abandoned' end;
    end if;
    fout := fout || (s.e || jsonb_build_object('doc_backup_id', v_row, 'refile', v_out));
  end loop;
  update public.agent_actions
     set detail = detail || jsonb_build_object('files', fout, 'refile_attempts', v_att, 'refiled_at', now(), 'sales_done_at', now())
   where id = p_id;
  return jsonb_build_object('waiting', 'it_engineer re-verification', 'refile_attempt', v_att, 'files', fout);
end $function$


CREATE OR REPLACE FUNCTION public.fn_sales_engineer_remediates(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d jsonb; v_tx uuid; v_req bigint; v_step text;
begin
  select detail into d from public.agent_actions where id = p_id;
  v_tx := (d->>'transaction_id')::uuid;
  v_step := case d->>'remedy_key' when 'final_call' then 'final_call' when 'chase' then 'chase' when 'customer_proof' then 'customer_proof' end;
  if v_step is null then
    return jsonb_build_object('waiting', 'no automatic remedy for ' || coalesce(d->>'remedy_key', '?'));
  end if;
  v_req := public.fn_sales_engineer_ladder_step(v_tx, v_step, (d->>'refund_id')::bigint, p_id);
  return jsonb_build_object('delivery_request', v_req,
    'waiting', case v_step when 'customer_proof' then 'the customer: the proof is requested and this closes when it arrives'
                           else 'the supplier: support is delivering the ' || replace(v_step, '_', ' ') || ' and watching every channel for a reply' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_sales_engineer_reports_complete(p_report_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n int;
begin
  update public.support_ceo_report r
     set status = 'completed', completed_at = now(),
         completion_note = 'sales_engineer saw the CEO''s receipt: ' || r.acceptance_receipt
           || coalesce(' Outcome: ' || (select a.evidence->>'verdict' from public.agent_actions a
                                         where a.kind = 'handoff' and a.agent = 'sales_engineer'
                                           and a.target_id = 'delivery.remediate:' || r.id and a.status = 'done'
                                         order by a.id desc limit 1), '')
   where r.source_agent = 'sales_engineer' and r.status = 'accepted' and r.acceptance_receipt is not null
     and (p_report_id is null or r.id = p_report_id)
     and not exists (select 1 from public.agent_actions a
                      where a.kind = 'handoff' and a.agent = 'sales_engineer'
                        and a.target_id = 'delivery.remediate:' || r.id and a.status <> 'done');
  get diagnostics n = row_count;
  return jsonb_build_object('completed_after_receipt', n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_sales_engineer_sends_registration_reminder(p_lead_id bigint, p_stage text, p_step integer, p_last_activity timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare l public.leads; v_to text; v_fixture boolean; v_go boolean; m jsonb; v_key text; v_out jsonb;
begin
  select * into l from public.leads where id = p_lead_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'lead_not_found'); end if;
  v_to := lower(btrim(coalesce(nullif(btrim(l.claimed_by), ''), l.email)));
  v_fixture := public.fn_is_demo_email(v_to);
  v_go := coalesce((select lower(btrim(value)) = 'true' from public.app_secrets where key = 'invite_enabled'), false)
          and public.fn_supplier_outreach_golive();
  if not v_fixture and not v_go then
    return jsonb_build_object('ok', false, 'held', true, 'reason', 'the supplier campaign is not open (invite_enabled / supplier_outreach_golive)');
  end if;
  if not v_fixture and not public.fn_supplier_outreach_reachable(l, v_to) then
    return jsonb_build_object('ok', false, 'reason', 'not reachable: fixture, banned, screened, closed, bounced, suppressed or unsendable');
  end if;
  m := public.fn_supplier_registration_reminder_compose(l, p_stage, p_step);
  v_key := 'supplier_registration_reminder:' || l.id || ':' || extract(epoch from p_last_activity)::bigint || ':' || p_step;
  v_out := public.fn_customer_support_takes_delivery(jsonb_build_array(jsonb_build_object(
    'type', 'supplier_registration_reminder', 'requested_by', 'sales_engineer', 'channel', 'email',
    'to_email', v_to, 'to_role', 'supplier', 'lead_id', l.id, 'lang', m->>'lang',
    'subject', m->>'subject', 'body', m->>'body', 'dedupe_key', v_key)));
  return jsonb_build_object('ok', true, 'lead_id', l.id, 'stage', p_stage, 'step', p_step, 'lang', m->>'lang', 'fixture', v_fixture,
                            'delivery', v_out->0);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_sales_engineer_supplier_documents_tick()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_reconcile json; v_final json; v_rechecked int := 0; v_closed int := 0; v_kept int := 0; r record; v jsonb;
  v_missing text[]; v_items_en text; v_items_ar text; v_ar boolean; v_to text; v_opened text; v_out jsonb;
  v_label jsonb := jsonb_build_object(
    'reg_name',        jsonb_build_array('company name', 'اسم الشركة'),
    'reg_mobile',      jsonb_build_array('a verified UAE mobile number', 'رقم جوال إماراتي موثَّق'),
    'reg_email',       jsonb_build_array('a verified e-mail address', 'بريد إلكتروني موثَّق'),
    'reg_licence',     jsonb_build_array('trade licence', 'الرخصة التجارية'),
    'reg_profile',     jsonb_build_array('company profile', 'الملف التعريفي للشركة'),
    'reg_terms',       jsonb_build_array('the signed supplier terms', 'الموافقة الموقّعة على شروط المورّد'),
    'licence_expired', jsonb_build_array('a trade licence that is in date', 'رخصة تجارية سارية المفعول'));
begin
  v_reconcile := public.fn_reconcile_doc_blocks(0);
  v_final := public.fn_doc_final_notice(7);

  for r in select l.id from public.leads l
            where l.approval_status = 'approved' and cardinality(public.fn_supplier_mandatory_six(l)) > 0 loop
    perform public.fn_sales_engineer_verifies_supplier(r.id, 'daily_recheck');
    v_rechecked := v_rechecked + 1;
  end loop;

  for r in select l.id, l.company_name, l.claimed_by, l.email, l.locale, l.exception_opened_at
             from public.leads l
            where l.approval_status = 'action_required' and l.exception_closed_at is null
              and l.exception_due_at <= now()
            order by l.id loop
    v := public.fn_sales_engineer_verifies_supplier(r.id, 'deadline');
    if v->>'approval_status' is distinct from 'action_required' then v_kept := v_kept + 1; continue; end if;

    v_missing := array(select jsonb_array_elements_text(v->'missing'));
    if cardinality(v_missing) = 0 then v_missing := array['licence_expired']; end if;
    select string_agg(v_label->k->>0, ', ' order by o), string_agg(v_label->k->>1, '، ' order by o)
      into v_items_en, v_items_ar from unnest(v_missing) with ordinality u(k, o);

    -- trg_leads_exception_invariant closes the window with outcome closed_rejected.
    update public.leads
       set approval_status = 'rejected', verified = false, approval_decided_by = 'sales_engineer',
           rejection_reason = 'registration incomplete after ' || public.fn_supplier_exception_days() || ' days: ' || array_to_string(v_missing, ', ')
     where id = r.id;

    v_ar := r.locale = 'ar';
    v_to := lower(nullif(btrim(coalesce(r.claimed_by, r.email)), ''));
    v_opened := to_char(r.exception_opened_at at time zone 'Asia/Dubai', 'DD Mon YYYY');
    if v_to is not null then
      perform public.fn_customer_support_takes_delivery(jsonb_build_array(jsonb_build_object(
        'type', 'registration_closed', 'requested_by', 'sales_engineer', 'channel', 'email',
        'to_email', v_to, 'to_role', 'supplier', 'lead_id', r.id, 'lang', case when v_ar then 'ar' else 'en' end,
        'dedupe_key', 'registration_closed:' || r.id || ':' || extract(epoch from r.exception_opened_at)::bigint,
        'subject', case when v_ar then 'إغلاق طلب تسجيلكم كمورّد في QuotesDone'
                        else 'Your QuotesDone supplier registration has closed' end,
        'body', case when v_ar then
            'السادة/ ' || coalesce(r.company_name, 'المورّد') || ' المحترمين،' || chr(10) || 'تحية طيبة وبعد،' || chr(10) || chr(10)
            || 'فُتح طلب تسجيلكم كمورّد بتاريخ ' || v_opened || '، ولا يزال ينقصه: ' || v_items_ar || '. '
            || 'أبلغناكم أننا سنبقي الطلب مفتوحًا ' || public.fn_ar_days(public.fn_supplier_exception_days()) || '، وقد انقضت هذه المدة، لذلك أُغلق طلب التسجيل.' || chr(10) || chr(10)
            || 'يمكنكم التسجيل من جديد في أي وقت عبر https://quotesdone.com/portal، ويُفعَّل حسابكم فور اكتمال البنود الستة: '
            || 'اسم الشركة، ورقم جوال موثَّق، وبريد إلكتروني موثَّق، والرخصة التجارية، والملف التعريفي للشركة، والموافقة الموقّعة على شروط المورّد.' || chr(10) || chr(10)
            || 'وإن رأيتم أن في ذلك خطأً، فيسعدنا أن تردّوا على هذه الرسالة.' || chr(10) || chr(10) || 'وتفضلوا بقبول فائق الاحترام والتقدير،'
          else
            'Dear ' || coalesce(r.company_name, 'supplier') || ',' || chr(10) || chr(10)
            || 'Your supplier registration was opened on ' || v_opened || ' and still needs: ' || v_items_en || '. '
            || 'We said we would keep it open for ' || public.fn_supplier_exception_days() || ' days; that time has passed, so the registration is now closed.' || chr(10) || chr(10)
            || 'You are welcome to register again at any time at https://quotesdone.com/portal. Your account activates as soon as the six required items are complete: '
            || 'company name, a verified mobile number, a verified e-mail address, your trade licence, your company profile and the signed supplier terms.' || chr(10) || chr(10)
            || 'If you believe this is wrong, reply to this e-mail.' end)));
    end if;

    insert into public.agent_actions (agent, kind, status, risk, title, recommendation, detail, target_table, target_id)
    values ('sales_engineer', 'supplier_verification', 'auto_done', 'low',
            'Registration closed after the ' || public.fn_supplier_exception_days() || '-day window — ' || left(coalesce(r.company_name, 'supplier #' || r.id), 120),
            'No action required. The supplier was told in their language what was missing and that they may register again.',
            jsonb_build_object('supplier_id', r.id, 'decision', 'rejected', 'missing', v_missing, 'window_opened_at', r.exception_opened_at,
                               'notice', case when v_to is null then 'no e-mail on file' else 'queued through customer_support' end,
                               'source', 'fn_sales_engineer_supplier_documents_tick'),
            'leads', r.id::text);
    v_closed := v_closed + 1;
  end loop;

  v_out := jsonb_build_object('reconcile', v_reconcile, 'final_notice', v_final, 'approved_rechecked', v_rechecked,
                              'registrations_closed', v_closed, 'completed_at_deadline', v_kept);
  perform public.fn_it_duty_ran('supplier_docs', v_out);
  return v_out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_sales_engineer_supplier_outreach_tick(p_force boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_now_dxb timestamp := now() at time zone 'Asia/Dubai';
  v_go boolean; v_weekend boolean; v_invited int; r record; s jsonb; v_cap int;
  v_due int := 0; v_sent int := 0; v_failed jsonb := '[]'::jsonb; v_clock jsonb; v_out jsonb; v_why text;
begin
  if not p_force then
    if extract(hour from v_now_dxb) < 9 then return jsonb_build_object('due', false, 'reason', 'before 09:00 Dubai'); end if;
    if exists (select 1 from public.agent_runs a
                where a.agent = 'sales_engineer' and a.counts->>'job' = 'supplier_outreach'
                  and a.started_at > now() - interval '1 day'
                  and (a.started_at at time zone 'Asia/Dubai')::date = v_now_dxb::date) then
      return jsonb_build_object('due', false, 'reason', 'already ran this Dubai day');
    end if;
  end if;

  v_go := coalesce((select lower(btrim(value)) = 'true' from public.app_secrets where key = 'invite_enabled'), false)
          and public.fn_supplier_outreach_golive();
  v_weekend := extract(isodow from v_now_dxb) in (6, 7);
  v_why := case when not public.fn_supplier_outreach_golive() then 'supplier_outreach_golive is false'
                when not v_go then 'invite_enabled is false'
                when v_weekend then 'it is the UAE weekend' end;

  -- 0. THE WARM-UP (22 Sep 2026). fn_invite_ramp sets today's invite_daily_cap from the last 48 h of
  --    bounces and complaints. Open days only: a held day sends nothing, so it must not move the cap.
  if v_why is null then v_cap := public.fn_invite_ramp(); end if;

  -- 1. The batch. enqueue_supplier_invites holds itself (gates, weekend, holiday, bounce brake, cap).
  v_invited := public.enqueue_supplier_invites(null);

  -- 2. Reminders: always counted; written only on an open weekday.
  for r in select * from public.fn_supplier_registration_reminders_due() loop
    v_due := v_due + 1;
    if v_why is not null then continue; end if;
    s := public.fn_sales_engineer_sends_registration_reminder(r.lead_id, r.stage, r.step, r.last_activity);
    if coalesce((s->>'ok')::boolean, false) then v_sent := v_sent + 1;
    else v_failed := v_failed || jsonb_build_array(jsonb_build_object('lead_id', r.lead_id, 'reason', s->>'reason'));
    end if;
  end loop;

  -- 3. The 24-hour clock: internal, so not held by the campaign gates.
  v_clock := public.fn_sales_engineer_raises_undecided_submissions(false);

  v_out := jsonb_build_object('job', 'supplier_outreach', 'dubai_day', v_now_dxb::date, 'held', v_why is not null, 'held_because', v_why,
    'invites', jsonb_build_object('queued', v_invited, 'cap', v_cap),
    'reminders', jsonb_build_object('due', v_due, 'sent', v_sent, 'failed', v_failed),
    'submissions', v_clock);
  insert into public.agent_runs (agent, status, started_at, finished_at, counts, note)
  values ('sales_engineer', case when jsonb_array_length(v_failed) > 0 then 'warn' else 'ok' end, now(), now(), v_out,
          case when v_why is not null
               then 'Supplier outreach HELD (' || v_why || '): ' || v_invited || ' invitation(s) queued, ' || v_due
                    || ' reminder(s) due and none written; ' || coalesce(v_clock->>'raised_to_ceo', '0') || ' undecided submission(s) raised to the CEO.'
               else 'Supplier outreach: ' || v_invited || ' invitation(s) queued at a cap of ' || coalesce(v_cap::text, '?') || ', ' || v_sent || ' of ' || v_due
                    || ' reminder(s) sent; ' || coalesce(v_clock->>'raised_to_ceo', '0') || ' undecided submission(s) raised to the CEO.' end);
  return v_out;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_sales_engineer_tells_customer_invoice_ready()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  c record;
  v_ar boolean;
begin
  if new.kind <> 'handoff' or coalesce(new.detail->>'subject', '') <> 'reveal_invoice' then return new; end if;
  select id, email into c from public.customers where id = (new.detail->>'customer_id')::uuid;
  if c.email is not null and c.email ~ '@' then
    v_ar := public.fn_registered_locale('customer', c.id) = 'ar';
    insert into public.notifications (type, to_email, to_role, inquiry_id, quote_id, subject, body, lang)
    values ('invoice_ready', c.email, 'customer',
            (new.detail->>'inquiry_id')::uuid, (new.detail->>'quote_id')::uuid,
            case when v_ar then 'فاتورتكم جاهزة' else 'Your invoice is ready' end,
            case when v_ar
              then 'أصبحت فاتورة رسوم الكشف التي سددتموها متاحة في حسابكم على QuotesDone، ويمكنكم فتحها في أي وقت من زر «الفاتورة» على العرض الذي كشفتموه، أو من «المستندات» ضمن «الفواتير».'
              else 'The invoice for the reveal fee you paid is now in your QuotesDone account. Open it any time from the "Invoice (PDF)" button on the quote you revealed, or under Invoices in Documents.'
            end,
            case when v_ar then 'ar' else 'en' end);
  end if;
  update public.agent_actions
     set status = 'done', decided_at = now(), decided_by = 'sales_engineer'
   where id = new.id;
  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_sales_engineer_verifies_supplier(p_lead_id bigint, p_source text DEFAULT 'save_profile'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare l public.leads; v_missing text[]; v_expired boolean; v_auto boolean; v_reason text; v_decision text; v_changed int;
begin
  select * into l from public.leads where id = p_lead_id for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'lead_not_found'); end if;
  -- A registration closed for being incomplete (fn_sales_engineer_supplier_documents_tick) is re-opened
  -- by the supplier saving again: the closing notice tells them they may. Any other rejection stands.
  if coalesce(l.banned, false)
     or (coalesce(l.approval_status, '') = 'rejected'
         and not (p_source = 'save_profile' and coalesce(l.rejection_reason, '') like 'registration incomplete after %')) then
    return jsonb_build_object('ok', true, 'decision', 'unchanged', 'approval_status', l.approval_status);
  end if;

  v_missing := public.fn_supplier_mandatory_six(l);
  -- "Not known to be expired": license_extract leaves the expiry null when the licence prints none, and
  -- blocking on that would refuse suppliers whose licence genuinely has no date (29 Jul 2026 note).
  v_expired := l.license_expiry is not null and l.license_expiry < current_date;
  select coalesce(p.auto_approve_suppliers, false) into v_auto from public.pricing_config p where p.id = 1;
  v_reason := case when cardinality(v_missing) > 0 then v_missing[1] when v_expired then 'licence_expired' end;

  if coalesce(l.approval_status, '') = 'approved' and cardinality(v_missing) = 0 then
    -- An approved supplier whose licence has since expired stays approved: fn_reconcile_doc_blocks
    -- pauses their matching and restores it on renewal, without taking the registration away.
    v_decision := 'approved';
  elsif v_reason is not null then v_decision := 'action_required';
  elsif coalesce(v_auto, false) then v_decision := 'approved';
  else v_decision := 'pending';
  end if;

  update public.leads
     set approval_status = v_decision,
         verified = (v_decision = 'approved'),
         approved_at = case when v_decision = 'approved' then coalesce(approved_at, now()) else approved_at end,
         approval_decided_by = 'sales_engineer',
         licence_gate_reason = v_reason
   where id = p_lead_id
     and (approval_status is distinct from v_decision or verified is distinct from (v_decision = 'approved')
          or licence_gate_reason is distinct from v_reason);
  get diagnostics v_changed = row_count;

  -- Every decision is recorded; a re-run by the trigger that changed nothing is not a decision.
  if v_changed > 0 or p_source <> 'mandatory_item_changed' then
  insert into public.agent_actions (agent, kind, status, risk, title, recommendation, detail, target_table, target_id)
  values ('sales_engineer', 'supplier_verification', 'auto_done',
          case when v_decision = 'action_required' then 'medium' else 'low' end,
          'Supplier ' || v_decision || coalesce(' (' || v_reason || ')', '') || ' — ' || left(coalesce(l.company_name, 'supplier #' || l.id), 120),
          case v_decision
            when 'approved' then 'No action required. All six mandatory items are present and the licence is not known to be expired.'
            when 'pending' then 'Complete, and waiting for the sales engineer: pricing_config.auto_approve_suppliers is off.'
            else 'No action required. The supplier was told exactly what is missing; the verification re-runs when it arrives, and the registration closes after 14 days.' end,
          jsonb_build_object('supplier_id', l.id, 'decision', v_decision, 'previous_status', l.approval_status,
                             'missing', v_missing, 'licence_expired', v_expired, 'license_expiry', l.license_expiry,
                             'auto_approve', v_auto, 'source', p_source),
          'leads', l.id::text);
  end if;

  return jsonb_build_object('ok', true, 'decision', v_decision, 'approval_status', v_decision, 'missing', to_jsonb(v_missing),
                            'licence_expired', v_expired, 'reason', v_reason, 'auto_approve', v_auto);
end $function$


CREATE OR REPLACE FUNCTION public.fn_sales_engineer_writes(p_msg_type text, p_role text, p_email text, p_lead bigint, p_customer uuid, p_inquiry uuid, p_quote uuid, p_subject_en text, p_body_en text, p_subject_ar text DEFAULT NULL::text, p_body_ar text DEFAULT NULL::text, p_cc text[] DEFAULT '{}'::text[], p_subject_id text DEFAULT NULL::text, p_watch_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_extra jsonb DEFAULT '{}'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_locale text;
begin
  v_locale := coalesce(public.fn_registered_locale(p_role, p_customer, p_lead, p_email), 'en');
  return public.fn_seat_handoff('sales_engineer', 'customer_support', 'delivery.request', 'notifications',
    coalesce(p_subject_id, p_msg_type || ':' || coalesce(p_quote::text, p_inquiry::text, p_lead::text, p_customer::text, 'x')),
    coalesce(p_extra, '{}'::jsonb) || jsonb_build_object(
      'msg_type', p_msg_type, 'recipient_role', p_role, 'to_email', p_email, 'cc', to_jsonb(coalesce(p_cc, '{}'::text[])),
      'supplier_id', p_lead, 'customer_id', p_customer, 'inquiry_id', p_inquiry, 'quote_id', p_quote,
      'locale', v_locale,
      'subject_en', p_subject_en, 'body_en', p_body_en || E'\n\nQuotesDone sales engineer',
      'subject_ar', p_subject_ar,
      'body_ar', case when p_body_ar is null then null else p_body_ar || E'\n\nمهندس المبيعات في QuotesDone' end,
      'watch_until', p_watch_until));
end $function$


CREATE OR REPLACE FUNCTION public.fn_sales_engineer_writes_money_notice(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  a public.agent_actions; d jsonb; v_notice text; v_sup record; v_tpl jsonb; v_vars jsonb;
  v_sub_en text; v_body_en text; v_sub_ar text; v_body_ar text; v_req bigint; v_msg text;
begin
  select * into a from public.agent_actions where id = p_id and kind = 'handoff';
  -- THE KIND IS THE CONVERSATION'S TYPE (public.seat_handoff_kind, #648): fn_seat_handoff_act dispatches
  -- each of the five rows inserted below to this routine, and the type alone says which notice it is.
  v_notice := case a.detail->>'type'
                when 'nonresponse.charge_reminder'  then 'charge_reminder'
                when 'nonresponse.final_demand'     then 'final_demand'
                when 'subscription.renewal_reminder' then 'subscription_renewal'
                when 'subscription.dunning'         then 'subscription_dunning'
                when 'subscription.payment_failed'  then 'subscription_payment_failed' end;
  if not found or a.agent <> 'sales_engineer' or v_notice is null then
    raise exception 'fn_sales_engineer_writes_money_notice: % is not one of the accountant''s notice kinds', p_id;
  end if;
  d := a.detail;
  select l.id, l.company_name, coalesce(l.claimed_by, l.email) email into v_sup
    from public.leads l where l.id = (d->>'supplier_id')::bigint;
  if coalesce(v_sup.email, '') not like '%@%' then
    return jsonb_build_object('supplier_reachable', false, 'notice', v_notice);
  end if;
  v_vars := d || jsonb_build_object('company', coalesce(v_sup.company_name, ''),
                                   'reveal_ref', left(coalesce(d->>'transaction_id', ''), 8));

  if v_notice in ('charge_reminder', 'final_demand') then
    -- THE WORDING IS THE LEGAL DOCUMENT'S, NOT THIS FILE'S (founder, 14 Sep 2026: "make sure the form
    -- and the wordings is done correctly"). No template row, no send: the handoff fails and says why.
    select value into v_tpl from public.decision_policy
     where key = case v_notice when 'charge_reminder' then 'supplier_charge_reminder_template'
                               else 'supplier_charge_final_demand_template' end;
    if v_tpl is null or coalesce(v_tpl->>'body_en', '') = '' then
      raise exception 'no % template in decision_policy: the wording comes from docs/legal/SUPPLIER_CHARGE_RECOVERY_UAE.md and has not been configured', v_notice;
    end if;
    v_sub_en := public.fn_render_template(v_tpl->>'subject_en', v_vars);
    v_body_en := public.fn_render_template(v_tpl->>'body_en', v_vars);
    v_sub_ar := public.fn_render_template(v_tpl->>'subject_ar', v_vars);
    v_body_ar := public.fn_render_template(v_tpl->>'body_ar', v_vars);
    v_msg := 'nonresponse_' || v_notice;
  elsif v_notice = 'subscription_renewal' then
    v_sub_en := 'Your QuotesDone supplier subscription renews on ' || (d->>'renews_on');
    v_body_en := 'Dear ' || coalesce(v_sup.company_name, 'there') || E',\n\nYour annual QuotesDone supplier subscription is paid until '
      || (d->>'paid_until') || '. The renewal of ' || coalesce(d->>'currency', 'AED') || ' ' || (d->>'fee')
      || ' falls due on ' || (d->>'renews_on') || E'.\n\nYou can renew from the Billing section of your supplier portal: https://quotesdone.com/suppliers. Stripe issues the invoice for the payment.\n\nYou keep paying no commission on the jobs you win.';
    v_sub_ar := 'موعد تجديد اشتراككم كمورّد في QuotesDone: ' || (d->>'renews_on');
    v_body_ar := 'اشتراككم السنوي مدفوع حتى ' || (d->>'paid_until') || '، ويستحق التجديد بقيمة ' || (d->>'fee')
      || ' درهم في ' || (d->>'renews_on') || '. ويمكنكم التجديد من قسم الفواتير في بوابة المورّد.';
    v_msg := 'subscription_renewal_reminder';
  elsif v_notice = 'subscription_dunning' then
    v_sub_en := 'Reminder ' || (d->>'dunning_no') || ': your QuotesDone subscription is unpaid';
    v_body_en := 'Dear ' || coalesce(v_sup.company_name, 'there') || E',\n\nYour annual supplier subscription of '
      || coalesce(d->>'currency', 'AED') || ' ' || (d->>'fee') || ' fell due on ' || (d->>'due_on') || ' and is still unpaid ('
      || (d->>'days_overdue') || E' days).\n\nPlease settle it from the Billing section of your supplier portal: https://quotesdone.com/suppliers. '
      || E'Until it is settled your profile does not receive new customer requests.\n\nIf you have already paid, reply to this email and we will check it against the payment record.';
    v_sub_ar := 'تذكير ' || (d->>'dunning_no') || ': اشتراككم في QuotesDone لم يُسدَّد بعد';
    v_body_ar := 'استحق اشتراككم السنوي كمورّد بقيمة ' || (d->>'fee') || ' درهم في ' || (d->>'due_on') || ' ولم يُسدَّد بعد ('
      || public.fn_ar_days((d->>'days_overdue')::int) || '). يُرجى السداد من قسم الفواتير في بوابة المورّد، علمًا بأن ملفكم لن يتلقى طلبات جديدة حتى السداد.';
    v_msg := 'subscription_dunning';
  elsif v_notice = 'subscription_payment_failed' then
    v_sub_en := 'Your QuotesDone subscription payment did not go through';
    v_body_en := 'Dear ' || coalesce(v_sup.company_name, 'there') || E',\n\nYour payment for the annual supplier subscription did not complete, and nothing was charged. '
      || E'You can try again at any time from the Billing section of your supplier portal: https://quotesdone.com/suppliers. If the card was declined, your bank can tell you why, and a different card also works.';
    v_sub_ar := 'لم يكتمل دفع اشتراككم في QuotesDone';
    v_body_ar := 'تعذّر إتمام دفع الاشتراك السنوي، ولم يُخصم أي مبلغ. يمكنكم إعادة المحاولة من قسم الفواتير في بوابة المورّد.';
    v_msg := 'subscription_payment_failed';
  else
    raise exception 'fn_sales_engineer_writes_money_notice: no words for notice %', v_notice;
  end if;

  if v_body_en ~ '\{\{[a-z_]+\}\}' or coalesce(v_body_ar, '') ~ '\{\{[a-z_]+\}\}' then
    raise exception 'notice % for handoff % still carries an unfilled placeholder; nothing was sent', v_notice, p_id;
  end if;
  -- A RECOVERY DOCUMENT IS SIGNED IN THE FOUNDER'S NAME (founder, 14 Sep 2026: "with stamp and signature
  -- of course"), so every one issued is logged before it leaves: what, which version, its hash, to whom.
  if v_notice in ('charge_reminder', 'final_demand') then
    insert into public.accountant_issued_document (document_kind, template_key, template_version, content_sha256, recipient,
      supplier_id, due_id, handoff_id, signed_as, stamp_required, signature_required)
    values (v_notice, case v_notice when 'charge_reminder' then 'supplier_charge_reminder_template' else 'supplier_charge_final_demand_template' end,
            coalesce(v_tpl->>'version', 'unversioned'),
            encode(sha256(convert_to(coalesce(v_sub_en, '') || E'\n' || v_body_en || E'\n' || coalesce(v_sub_ar, '') || E'\n' || coalesce(v_body_ar, ''), 'UTF8')), 'hex'),
            v_sup.email, v_sup.id, (d->>'due_id')::bigint, p_id, 'founder', true, true);
  end if;
  v_req := public.fn_sales_engineer_writes(v_msg, 'supplier', v_sup.email, v_sup.id, null,
    (d->>'inquiry_id')::uuid, (d->>'quote_id')::uuid, v_sub_en, v_body_en, v_sub_ar, v_body_ar,
    '{}', v_msg || ':' || (d->>'subject_id'), null,
    jsonb_build_object('transaction_id', d->>'transaction_id', 'due_id', d->>'due_id', 'notice', v_notice));
  return jsonb_build_object('notice', v_notice, 'delivery_request', v_req);
end $function$


CREATE OR REPLACE FUNCTION public.fn_sales_figure(p_value numeric, p_universe bigint, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'value', p_value,
    'basis', case when p_value is null then 'unknown'
                  when coalesce(p_universe, 0) = 0 then 'true_zero'
                  else 'measured' end,
    'denominator', p_universe,
    'note', p_note);
$function$


CREATE OR REPLACE FUNCTION public.fn_sales_knowledge_search_vector()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  new.search :=
      setweight(to_tsvector('english'::regconfig, coalesce(new.title,'')), 'A')
   || setweight(to_tsvector('english'::regconfig, coalesce(array_to_string(new.tags,' '),'')), 'B')
   || setweight(to_tsvector('english'::regconfig, coalesce(new.content,'')), 'C');
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_sales_portal_report(p_party_kind text, p_party_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_kind text := lower(coalesce(btrim(p_party_kind), ''));
  v_out  jsonb;
  -- The UNIVERSES. Every "0" below is interpreted against the size of the table it came from, so
  -- an empty table reports true_zero with its denominator instead of a bare 0 that could equally
  -- mean "this party has none" on a busy platform.
  u_inq   bigint := (select count(*) from inquiries);
  u_q     bigint := (select count(*) from quotes);
  u_tx    bigint := (select count(*) from transactions);
  u_rev   bigint := (select count(*) from reviews);
  u_match bigint := (select count(*) from inquiry_matches);
  u_proj  bigint := (select count(*) from projects);
  -- supplier
  s_id bigint; s_row leads%rowtype; s_cap supplier_capabilities%rowtype; s_score supplier_score%rowtype;
  s_won bigint; s_quoted bigint; s_matched bigint; s_reviews bigint; s_rating numeric;
  -- customer
  c_id uuid; c_row customers%rowtype;
  c_inq bigint; c_q bigint; c_spend numeric; c_tx bigint; c_proj bigint; c_suppliers jsonb;
begin
  if v_kind = 'supplier' then
    begin s_id := p_party_id::bigint; exception when others then
      return jsonb_build_object('ok', false, 'error', 'party_id_not_a_supplier_id', 'party_id', p_party_id); end;
    select * into s_row from leads where id = s_id;
    if not found then return jsonb_build_object('ok', false, 'error', 'unknown_supplier', 'party_id', p_party_id); end if;

    select * into s_cap   from supplier_capabilities where supplier_id = s_id;
    select * into s_score from supplier_score        where lead_id     = s_id;
    select count(*) into s_won     from inquiries       where hired_supplier_id = s_id;
    select count(*) into s_quoted  from quotes          where supplier_id = s_id;
    select count(*) into s_matched from inquiry_matches where supplier_id = s_id;
    select count(*), round(avg(rating)::numeric, 2) into s_reviews, s_rating
      from reviews where supplier_id = s_id;

    v_out := jsonb_build_object(
      'ok', true, 'party_kind', 'supplier', 'party_id', s_id,
      'company_name', s_row.company_name,
      'generated_at', now(),

      'jobs_won',         fn_sales_figure(s_won::numeric,     u_inq,   'inquiries where this supplier was hired'),
      'quotes_submitted', fn_sales_figure(s_quoted::numeric,  u_q,     'quotes rows carrying this supplier_id'),
      'rfqs_received',    fn_sales_figure(s_matched::numeric, u_match, 'inquiry_matches rows carrying this supplier_id'),
      'quotes_won',       fn_sales_figure(s_won::numeric,     u_q,     'a won quote is an inquiry hired to this supplier; counted against the quotes universe'),
      'win_rate_pct', case when coalesce(s_quoted,0) > 0
                           then jsonb_build_object('value', round(100.0 * s_won / s_quoted, 1), 'basis', 'measured')
                           else jsonb_build_object('value', null, 'basis', 'unknown',
                                  'note', 'no quote has been submitted, so there is no denominator; this is not a 0% win rate') end,

      -- RATINGS. Two numbers with the same name and completely different standing.
      'rating_earned_here', jsonb_build_object(
        'value', s_rating, 'review_count', s_reviews,
        'basis', case when s_rating is not null then 'measured'
                      when u_rev = 0 then 'true_zero' else 'unknown' end,
        'denominator', u_rev,
        'note', 'average of reviews left by customers on THIS platform'),
      'rating_from_directory', case when s_row.rating is not null then jsonb_build_object(
          'value', s_row.rating, 'basis', 'derived_not_earned',
          'note', 'scraped from a public business directory before this supplier ever registered. It is NOT performance on QuotesDone and must never be presented to a supplier as its rating here, nor to a customer as evidence.')
        else jsonb_build_object('value', null, 'basis', 'unknown') end,

      -- APPROVAL. null is not "no".
      'approval', case when s_row.approval_status is null then jsonb_build_object(
            'value', null, 'basis', 'unknown',
            'note', 'no approval decision has ever been recorded for this supplier. This is not a rejection and not a pending queue position.')
        else jsonb_build_object('value', s_row.approval_status, 'basis', 'measured') end,
      'registered', jsonb_build_object('value', coalesce(s_row.claimed, false), 'basis', 'measured',
        'note', 'claimed = the supplier took ownership of this directory record and registered'),

      'document_expiry', fn_supplier_expiries(s_id),

      'capability_confirmation', case when s_cap.supplier_id is null then jsonb_build_object(
            'state', 'none_on_file', 'basis', 'true_zero')
        else jsonb_build_object(
            'state', case when s_cap.confirmed_at is not null then 'confirmed_by_supplier'
                          else 'unconfirmed' end,
            'basis', case when s_cap.confirmed_at is not null then 'measured' else 'derived_not_earned' end,
            'extractor_version', s_cap.extractor_version,
            'review_status', s_cap.review_status,
            'confirmed_at', s_cap.confirmed_at,
            'completeness', s_cap.completeness,
            'note', case when s_cap.confirmed_at is null then
              'These capabilities were derived from a directory listing, not stated by the supplier. Until the supplier confirms them they are a starting point for a conversation, not a claim we may quote against.' end) end,

      'platform_score', case when s_score.lead_id is null then jsonb_build_object('basis', 'true_zero')
        else jsonb_build_object('basis', 'derived_not_earned',
          'quotes_submitted', s_score.quotes_submitted, 'quotes_won', s_score.quotes_won,
          'response_rate', s_score.response_rate, 'reliability', s_score.reliability,
          'computed_at', s_score.computed_at,
          'note', 'supplier_score rows were computed over the imported directory, not over activity on this platform. Read alongside jobs_won, which is the earned figure.') end);

  elsif v_kind = 'customer' then
    begin c_id := p_party_id::uuid; exception when others then
      return jsonb_build_object('ok', false, 'error', 'party_id_not_a_customer_id', 'party_id', p_party_id); end;
    select * into c_row from customers where id = c_id;
    if not found then return jsonb_build_object('ok', false, 'error', 'unknown_customer', 'party_id', p_party_id); end if;

    select count(*) into c_inq  from inquiries where customer_id = c_id;
    select count(*) into c_q    from quotes q join inquiries i on i.id = q.inquiry_id where i.customer_id = c_id;
    select count(*), coalesce(sum(t.quote_amount), 0) into c_tx, c_spend
      from transactions t where t.customer_id = c_id;
    select count(*) into c_proj from projects where customer_id = c_id;

    -- Supplier performance on THIS customer's own jobs. fn_customer_supplier_score already refuses
    -- to invent a relationship (basis 'no_shared_history'), so it is called rather than re-derived.
    select coalesce(jsonb_agg(fn_customer_supplier_score(c_id, s)), '[]'::jsonb) into c_suppliers
      from (select distinct hired_supplier_id s from inquiries
             where customer_id = c_id and hired_supplier_id is not null) x;

    v_out := jsonb_build_object(
      'ok', true, 'party_kind', 'customer', 'party_id', c_id,
      'email', c_row.email, 'full_name', c_row.full_name,
      'generated_at', now(),
      'inquiries',       fn_sales_figure(c_inq::numeric,  u_inq,  'inquiries this customer posted'),
      'quotes_received', fn_sales_figure(c_q::numeric,    u_q,    'quotes against this customer''s inquiries'),
      'reveals',         fn_sales_figure(c_tx::numeric,   u_tx,   'paid reveals; a transactions row is a reveal'),
      'total_spend_aed', jsonb_build_object(
        'value', case when u_tx = 0 then 0 else c_spend end,
        'basis', case when u_tx = 0 then 'true_zero' else 'measured' end,
        'denominator', u_tx,
        'note', 'sum of transactions.quote_amount for this customer. The reveal fee is 3% of it; this figure is the job value, not the fee.'),
      'projects',        fn_sales_figure(c_proj::numeric, u_proj, 'projects owned by this customer'),
      'supplier_performance', c_suppliers,
      'supplier_performance_basis', case when jsonb_array_length(c_suppliers) = 0
        then 'no supplier has been hired by this customer yet, so there is no performance to report'
        else 'per-relationship, from this customer''s own RFQs, quotes, reveals and reviews' end);
  else
    return jsonb_build_object('ok', false, 'error', 'unknown_party_kind', 'party_kind', p_party_kind,
                              'accepted', jsonb_build_array('supplier', 'customer'));
  end if;

  insert into sales_decision_log (actor, action, query, answered, subject, candidates)
  values ('sales_engineer', 'report', null, true, v_kind || ':' || p_party_id,
          jsonb_build_object('universes', jsonb_build_object(
            'inquiries', u_inq, 'quotes', u_q, 'transactions', u_tx,
            'reviews', u_rev, 'inquiry_matches', u_match, 'projects', u_proj)));

  return v_out;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_sales_rating_landed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_task     bigint;
  v_company  text;
  v_customer text;
  v_title    text;
  v_payload  jsonb;
begin
  select l.company_name into v_company from public.leads l where l.id = new.supplier_id;
  select coalesce(nullif(btrim(c.full_name), ''), c.email) into v_customer
    from public.customers c where c.id = new.customer_id;

  v_title := left('Customer rating landed: ' || coalesce(v_company, 'supplier #' || new.supplier_id)
             || ' — ' || new.rating || '/5', 200);

  v_payload := jsonb_build_object(
    'transaction_id', new.transaction_id,
    'review_id',      new.id,
    'supplier_id',    new.supplier_id,
    'supplier',       v_company,
    'customer_id',    new.customer_id,
    'customer',       v_customer,
    'inquiry_id',     new.inquiry_id,
    'rating',         new.rating,
    'comment',        left(coalesce(new.comment, ''), 500),
    'arrived_at',     now(),
    'op',             tg_op);

  -- UNFILTERED BY STATUS. Every task this transaction has ever opened, in any state.
  select t.id into v_task
    from public.org_tasks t
   where t.result -> 'sales_rating' ->> 'transaction_id' = new.transaction_id::text
   order by t.id desc
   limit 1;

  if v_task is not null then
    update public.org_tasks
       set result = jsonb_set(coalesce(result, '{}'::jsonb), '{sales_rating}',
                      coalesce(result -> 'sales_rating', '{}'::jsonb) || v_payload
                      || jsonb_build_object('revisions',
                           coalesce((result -> 'sales_rating' ->> 'revisions')::int, 1) + 1)),
           title      = v_title,
           updated_at = now()
     where id = v_task;
  else
    insert into public.org_tasks (title, detail, status, tier, needs_founder, decided_by,
                                  action_class, assigned_agent, priority, result)
    values (v_title,
            'A QuotesDone customer rated a supplier they paid to reveal and actually dealt with.'
              || E'\n\nSupplier: ' || coalesce(v_company, 'id ' || new.supplier_id)
              || E'\nCustomer: ' || coalesce(v_customer, 'id ' || new.customer_id)
              || E'\nTransaction: ' || new.transaction_id
              || coalesce(E'\nInquiry: ' || new.inquiry_id::text, '')
              || E'\nRating: ' || new.rating || '/5'
              || coalesce(E'\nComment: ' || nullif(btrim(new.comment), ''), '')
              || E'\n\nIncorporate it into the supplier record: recompute_supplier_rating() has'
              || ' already run on the aggregate, so what is left is the judgement this seat owns —'
              || ' whether this rating changes the supplier''s standing, their declared capability,'
              || ' or their eligibility for the trades they are matched on. If the customer changes'
              || ' their rating this task is updated, never duplicated.',
            'assigned', 'advisory', false, 'fn_sales_rating_landed',
            'routine_operational_decision', 'sales_engineer', 1,
            jsonb_build_object('sales_rating', v_payload || jsonb_build_object('revisions', 1)))
    returning id into v_task;
  end if;

  return new;
exception when others then
  -- THE RATING WINS. Always.
  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_sanctioned_identity(p_name text, p_licence text, p_account_email text DEFAULT NULL::text, p_self bigint DEFAULT NULL::bigint)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select b.lead_id from public.sanctions_ban b
   where (p_self is null or b.lead_id <> p_self)
     and ( (b.name_key       is not null and b.name_key       = public.fn_screening_normalise(p_name))
        or (b.licence_key    is not null and b.licence_key    = public.fn_sanctions_identity_key(p_licence))
        or (b.account_email  is not null and b.account_email  = lower(btrim(coalesce(p_account_email, ''))))
        or (b.contact_email  is not null and b.contact_email  = lower(btrim(coalesce(p_account_email, '')))) )
   order by b.lead_id limit 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_sanctions_ban_is_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  raise exception 'SANCTIONS_RECORD_IS_SEALED: public.sanctions_ban is append-only (founder instruction 516, 18 Sep 2026). % refused.', tg_op
    using errcode = '42501';
end $function$


CREATE OR REPLACE FUNCTION public.fn_sanctions_identity_key(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select nullif(upper(regexp_replace(coalesce(p, ''), '[^[:alnum:]]+', '', 'g')), '');
$function$


CREATE OR REPLACE FUNCTION public.fn_sanctions_screen_tick()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'net', 'pg_temp'
AS $function$
declare v_ref text; v_secret text; v_req bigint;
begin
  select value into v_ref    from public.app_secrets where key = 'project_ref';
  select value into v_secret from public.app_secrets where key = 'cred_cron_compliance';
  if v_ref is null or v_secret is null then
    raise exception 'fn_sanctions_screen_tick: % is missing from app_secrets, so the weekly screening cannot be posted',
      case when v_ref is null then 'project_ref' else 'cred_cron_compliance' end;
  end if;
  select net.http_post(
    url     := 'https://' || v_ref || '.supabase.co/functions/v1/sanctions_screen',
    headers := jsonb_build_object('Content-Type', 'application/json'),
    body    := jsonb_build_object('__secret', v_secret, 'caller', 'fn_sanctions_screen_tick'),
    timeout_milliseconds := 120000
  ) into v_req;
  -- `posted` means the request was QUEUED, and nothing more. MEASURED 18 Sep 2026: a probe polled
  -- net._http_response for its own request id for 15 s inside the posting transaction (request 432566)
  -- and the row never appeared, because pg_net dispatches after commit. So there is no version of this
  -- routine that can return the real status, and saying so is the fix.
  return jsonb_build_object(
    'posted', true,
    'request_id', v_req,
    'response_status', null,
    'note', 'QUEUED ONLY. pg_net dispatches after this transaction commits, so the outcome is not '
         || 'knowable here — call public.fn_sanctions_screen_tick_status(' || v_req || ') a few seconds '
         || 'from now to read it. This routine is the MANUAL kick; the weekly clock is resilience_ping''s '
         || 'orphans step, which calls the function over HTTP and reads the response synchronously.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_sanctions_screen_tick_status(p_request_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'net', 'pg_temp'
AS $function$
  select coalesce(
    (select jsonb_build_object('request_id', r.id, 'status', r.status_code, 'timed_out', r.timed_out,
                               'error', r.error_msg, 'body', left(coalesce(r.content, ''), 2000),
                               'at', r.created)
       from net._http_response r where r.id = p_request_id),
    jsonb_build_object('request_id', p_request_id, 'status', null,
      'note', 'No response on record yet. pg_net writes it after the posting transaction commits, and '
           || 'prunes old rows, so this is either still in flight or already aged out.'));
$function$


CREATE OR REPLACE FUNCTION public.fn_schema_export()
 RETURNS text
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET lock_timeout TO '15s'
AS $function$
with t as (
  select c.relname as rel,
    'CREATE TABLE IF NOT EXISTS public.'||quote_ident(c.relname)||E' (\n'||
    string_agg('  '||quote_ident(a.attname)||' '||format_type(a.atttypid,a.atttypmod)||
      case a.attidentity when 'a' then ' GENERATED ALWAYS AS IDENTITY' when 'd' then ' GENERATED BY DEFAULT AS IDENTITY' else '' end||
      case when a.attgenerated='s' then ' GENERATED ALWAYS AS ('||pg_get_expr(ad.adbin,ad.adrelid)||') STORED'
           when ad.adbin is not null then ' DEFAULT '||pg_get_expr(ad.adbin,ad.adrelid) else '' end||
      case when a.attnotnull then ' NOT NULL' else '' end, E',\n' order by a.attnum)
    ||E'\n);' as tbl_ddl
  from pg_class c join pg_namespace n on n.oid=c.relnamespace and n.nspname='public'
  join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped
  left join pg_attrdef ad on ad.adrelid=c.oid and ad.adnum=a.attnum
  where c.relkind='r' and not exists(select 1 from pg_depend d where d.objid=c.oid and d.deptype='e')
  group by c.relname
)
select
  '-- QuotesDone — FULL SCHEMA EXPORT (generated from the live database)'||E'\n'
  ||'-- Excludes: secret VALUES (key names listed below), and table ROW DATA (PII).'||E'\n'
  ||'-- Order is best-effort; this is a faithful reference mirror, not a guaranteed one-click restore.'||E'\n\n'
  ||'-- ===== EXTENSIONS =====' ||E'\n'|| coalesce((select string_agg('CREATE EXTENSION IF NOT EXISTS '||quote_ident(extname)||' WITH SCHEMA '||quote_ident(nx.nspname)||';', E'\n' order by extname) from pg_extension e join pg_namespace nx on nx.oid=e.extnamespace),'')
  ||E'\n\n-- ===== SEQUENCES =====\n'|| coalesce((select string_agg('CREATE SEQUENCE IF NOT EXISTS public.'||quote_ident(sequence_name)||';', E'\n' order by sequence_name) from information_schema.sequences where sequence_schema='public'),'')
  ||E'\n\n-- ===== TABLES ('||(select count(*) from t)||E') =====\n'|| coalesce((select string_agg(tbl_ddl, E'\n\n' order by rel) from t),'')
  ||E'\n\n-- ===== CONSTRAINTS =====\n'|| coalesce((select string_agg('ALTER TABLE public.'||quote_ident(c.relname)||' ADD CONSTRAINT '||quote_ident(con.conname)||' '||pg_get_constraintdef(con.oid)||';', E'\n' order by case con.contype when 'p' then 1 when 'u' then 2 when 'c' then 3 else 9 end, c.relname, con.conname) from pg_constraint con join pg_class c on c.oid=con.conrelid join pg_namespace n on n.oid=c.relnamespace and n.nspname='public' where con.contype in ('p','u','c','f')),'')
  ||E'\n\n-- ===== INDEXES =====\n'|| coalesce((select string_agg(pg_get_indexdef(i.indexrelid)||';', E'\n' order by ic.relname) from pg_index i join pg_class ic on ic.oid=i.indexrelid join pg_namespace n on n.oid=ic.relnamespace and n.nspname='public' where not exists(select 1 from pg_constraint con where con.conindid=i.indexrelid) and not exists(select 1 from pg_depend d where d.objid=ic.oid and d.deptype='e')),'')
  ||E'\n\n-- ===== VIEWS =====\n'|| coalesce((select string_agg('CREATE OR REPLACE VIEW public.'||quote_ident(viewname)||' AS '||definition, E'\n\n' order by viewname) from pg_views where schemaname='public'),'')
  ||E'\n\n-- ===== FUNCTIONS =====\n'|| coalesce((select string_agg(pg_get_functiondef(p.oid), E'\n\n' order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace and n.nspname='public' where p.prokind in ('f','p') and not exists(select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')),'')
  ||E'\n\n-- ===== TRIGGERS =====\n'|| coalesce((select string_agg(pg_get_triggerdef(tg.oid)||';', E'\n' order by c.relname) from pg_trigger tg join pg_class c on c.oid=tg.tgrelid join pg_namespace n on n.oid=c.relnamespace and n.nspname='public' where not tg.tgisinternal),'')
  ||E'\n\n-- ===== ROW LEVEL SECURITY (enable) =====\n'|| coalesce((select string_agg('ALTER TABLE public.'||quote_ident(relname)||' ENABLE ROW LEVEL SECURITY;', E'\n' order by relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace and n.nspname='public' where relkind='r' and relrowsecurity),'')
  ||E'\n\n-- ===== POLICIES =====\n'|| coalesce((select string_agg('CREATE POLICY '||quote_ident(policyname)||' ON public.'||quote_ident(tablename)||' AS '||permissive||' FOR '||cmd||' TO '||array_to_string(roles,', ')||coalesce(' USING ('||qual||')','')||coalesce(' WITH CHECK ('||with_check||')','')||';', E'\n' order by tablename,policyname) from pg_policies where schemaname='public'),'')
  ||E'\n\n-- ===== CRON JOBS =====\n'|| coalesce((select string_agg('select cron.schedule('||quote_literal(jobname)||','||quote_literal(schedule)||',$CRON$'||command||'$CRON$);', E'\n' order by jobid) from cron.job),'')
  ||E'\n\n-- ===== APP_SECRETS KEY NAMES (values intentionally excluded) =====\n'|| coalesce((select string_agg('--   '||key, E'\n' order by key) from public.app_secrets),'')
  ||E'\n'
$function$


CREATE OR REPLACE FUNCTION public.fn_screening_normalise(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select nullif(btrim(regexp_replace(
           regexp_replace(
             ' ' || regexp_replace(
               translate(lower(coalesce(p, '')), 'áàâäãåéèêëíìîïóòôöõúùûüçñýÿ', 'aaaaaaeeeeiiiiooooouuuucnyy'),
               '[^[:alnum:][:space:]]+', ' ', 'g') || ' ',
             '\s(llc|l l c|fze|fzc|fzco|fz|ltd|limited|inc|co|company|corp|corporation|est|establishment|trading|general|contracting|contractors|services|group|international|technical|the|of|and|for|in|dmcc|plc|sarl|sal|gmbh|bv|sole|proprietorship)(?=\s)', ' ', 'g'),
           '\s+', ' ', 'g')), '');
$function$


CREATE OR REPLACE FUNCTION public.fn_screening_record_is_never_deleted()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_table_name = 'screening_entry' and tg_op = 'DELETE' then
    if exists (select 1 from public.supplier_screening_hit h
                where h.entry_id = old.id
                   or (h.entry_source = old.source and h.entry_reference = old.reference)) then
      raise exception 'SANCTIONS_RECORD_IS_SEALED: screening_entry #% is cited by a supplier_screening_hit and cannot be deleted.', old.id
        using errcode = '42501';
    end if;
    return old;
  end if;
  raise exception 'SANCTIONS_RECORD_IS_SEALED: % on public.% is refused (founder instruction 516, 18 Sep 2026: never hard-delete a sanctions record).', tg_op, tg_table_name
    using errcode = '42501';
end $function$


CREATE OR REPLACE FUNCTION public.fn_screening_tokens(p text)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(array(
    select distinct t from unnest(string_to_array(coalesce(public.fn_screening_normalise(p), ''), ' ')) t
     where length(t) >= 3
       and t <> all (array['abd','abdul','abdel','bin','ibn','abu','bint','umm','von','van','der','del','della','les','das','dos'])
     order by t), '{}'::text[]);
$function$


CREATE OR REPLACE FUNCTION public.fn_seat_answers_it_finding(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a public.agent_actions; d jsonb;
begin
  select * into a from public.agent_actions where id = p_id and kind = 'handoff';
  if not found or a.detail->>'type' <> 'it.finding' then
    raise exception 'fn_seat_answers_it_finding: % is not an it.finding handoff', p_id;
  end if;
  d := a.detail;
  -- THE CEO OWNS THE HARNESS, AND CAN CLOSE A REHEARSAL WINDOW A RUN LEFT OPEN. An open window keeps
  -- the failed-run watcher from paging for anything it covers, so closing it is the remedy, not a risk.
  if d->>'duty' = 'demo' and (d->'finding_evidence'->>'rehearsal_window_id') is not null then
    update public.rehearsal_window set ended_at = now()
     where id = (d->'finding_evidence'->>'rehearsal_window_id')::bigint and ended_at is null;
    return jsonb_build_object('waiting', 'it_engineer re-verification', 'seat', a.agent, 'duty', 'demo',
      'remedy', 'closed rehearsal_window ' || (d->'finding_evidence'->>'rehearsal_window_id'),
      'reply', a.agent || ' closed rehearsal window ' || (d->'finding_evidence'->>'rehearsal_window_id')
               || ', which its run had left open.');
  end if;
  return jsonb_build_object(
    'waiting', 'it_engineer re-verification',
    'seat', a.agent,
    'duty', d->>'duty',
    'remedy', null,
    'reply', a.agent || ' acknowledged "' || coalesce(d->>'title', d->>'issue_key') || '". Its playbook has no '
             || 'deterministic remedy for a ' || coalesce(d->>'duty', 'fault') || ' finding on '
             || coalesce(d->>'subject', 'this subject') || ': it needs a code or configuration change.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_seat_clock_asked(p_dedupe_key text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select exists (select 1 from public.agent_actions a
                  where a.kind = 'handoff' and a.agent = 'customer_support'
                    and a.target_id = 'delivery.request:' || p_dedupe_key and a.status <> 'failed')
$function$


CREATE OR REPLACE FUNCTION public.fn_seat_clock_compose(p_kind text, p_lang text, p jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ar boolean := coalesce(p_lang, '') like 'ar%';
  v_lang text := case when coalesce(p_lang, '') like 'ar%' then 'ar' else 'en' end;
  v_site text; v_link text; v_trade text; v_trade_ar text; v_em text; v_em_ar text; v_where text; v_where_ar text;
  v_name text := nullif(btrim(coalesce(p->>'name', '')), '');
  v_n int := coalesce((p->>'quotes')::int, 0);
  v_due text; v_subj text; v_body text;
begin
  select coalesce(nullif(btrim(value), ''), 'https://quotesdone.com') into v_site from public.app_secrets where key = 'public_site_url';
  v_link := coalesce(v_site, 'https://quotesdone.com') || '/' || v_lang || '/portal';
  select t.label, coalesce(t.label_ar, t.label) into v_trade, v_trade_ar
    from public.taxonomy_trade t
   where t.code = (public.fn_taxonomy_trades_for(array[coalesce(p->>'category', '')]))[1];
  v_trade := coalesce(v_trade, nullif(p->>'category', ''), 'your trade');
  v_trade_ar := coalesce(v_trade_ar, nullif(p->>'category', ''), 'تخصصكم');
  v_em := nullif(btrim(coalesce(p->>'emirate', '')), '');
  v_em_ar := case lower(coalesce(v_em, '')) when 'dubai' then 'دبي' when 'abu dhabi' then 'أبوظبي' when 'sharjah' then 'الشارقة'
               when 'ajman' then 'عجمان' when 'umm al quwain' then 'أم القيوين' when 'ras al khaimah' then 'رأس الخيمة'
               when 'fujairah' then 'الفجيرة' else v_em end;
  v_where := v_trade || coalesce(' in ' || v_em, '');
  v_where_ar := v_trade_ar || coalesce(' في ' || v_em_ar, '');
  v_due := to_char((p->>'deadline')::timestamptz at time zone 'Asia/Dubai', case when v_ar then 'DD/MM/YYYY HH24:MI' else 'DD Mon YYYY, HH24:MI' end);

  if p_kind = 'rfq_invite' then
    if v_ar then
      v_subj := 'طلب عرض سعر جديد: ' || v_where_ar || ' — QuotesDone';
      v_body := coalesce('السادة/ ' || v_name || ' المحترمين،', 'السادة الكرام،') || E'\n\nتحية طيبة وبعد،\n\n'
        || 'يسرّنا إفادتكم بأن أحد العملاء يطلب عروض أسعار في مجال ' || v_where_ar || '، ويتوافق طلبه مع نطاق أعمال شركتكم المسجّل لدينا. '
        || 'ويُرجى الاطّلاع على تفاصيل الطلب وتقديم عرضكم عبر بوابة الموردين:' || E'\n\n' || v_link
        || E'\n\nوتفضلوا بقبول فائق الاحترام والتقدير،';
    else
      v_subj := 'New request for quotation: ' || v_where || ' — QuotesDone';
      v_body := coalesce('Dear ' || v_name || ',', 'Dear Sir or Madam,') || E'\n\n'
        || 'A customer is requesting quotations for ' || v_where || ', and the request matches the scope your company registered with us. '
        || 'Please review the details and submit your quotation in your supplier portal:' || E'\n\n' || v_link;
    end if;
  elsif p_kind = 'rfq_quote_reminder' then
    if v_ar then
      v_subj := 'تذكير: العميل بانتظار عرضكم — ' || v_where_ar;
      v_body := coalesce('السادة/ ' || v_name || ' المحترمين،', 'السادة الكرام،') || E'\n\nتحية طيبة وبعد،\n\n'
        || 'نودّ تذكيركم بطلب عرض السعر في مجال ' || v_where_ar || ' الذي أُرسل إليكم عبر QuotesDone، إذ لم يصلنا عرضكم بعد. '
        || 'والعميل بانتظار العروض، ونأمل تقديم عرضكم في أقرب وقت، ويُفضَّل قبل ' || v_due || ' بتوقيت دبي.'
        || E'\n\nيمكنكم تقديم عرضكم عبر بوابة الموردين:\n\n' || v_link
        || E'\n\nوفي حال عدم رغبتكم في التقدّم بعرض لهذا الطلب، يُرجى إبلاغنا بذلك عبر البوابة أو بالرد على هذه الرسالة.'
        || E'\n\nوتفضلوا بقبول فائق الاحترام والتقدير،';
    else
      v_subj := 'Reminder: the customer is waiting for your quotation — ' || v_where;
      v_body := coalesce('Dear ' || v_name || ',', 'Dear Sir or Madam,') || E'\n\n'
        || 'This is a reminder of the request for quotation for ' || v_where || ' sent to you through QuotesDone; we have not yet received your quotation. '
        || 'The customer is waiting for quotations, and we would appreciate yours as soon as possible, ideally before ' || v_due || ' (Dubai time).'
        || E'\n\nSubmit your quotation in your supplier portal:\n\n' || v_link
        || E'\n\nIf you would rather not quote for this request, please let us know in the portal or by replying to this e-mail.';
    end if;
  elsif p_kind = 'rfq_short_of_quotes' then
    if v_ar then
      v_subj := 'مستجدات طلبكم لعروض الأسعار — ' || v_where_ar;
      v_body := coalesce('السادة/ ' || v_name || ' المحترمين،', 'عميلنا العزيز،') || E'\n\nتحية طيبة وبعد،\n\n'
        || case when v_n = 0 then 'نفيدكم بأن طلبكم في مجال ' || v_where_ar || ' لم يتلقَّ أي عرض سعر حتى الآن. '
                when v_n = 1 then 'نفيدكم بأن طلبكم في مجال ' || v_where_ar || ' تلقّى حتى الآن عرض سعر واحدًا، ونسعى إلى أن تصلكم ثلاثة عروض على الأقل للمقارنة. '
                else 'نفيدكم بأن طلبكم في مجال ' || v_where_ar || ' تلقّى حتى الآن عرضَي سعر، ونسعى إلى أن تصلكم ثلاثة عروض على الأقل للمقارنة. ' end
        || 'وقد دعونا موردين إضافيين مطابقين لطلبكم، وذكّرنا الموردين المدعوين بتقديم عروضهم، وسيبقى طلبكم مفتوحًا لاستلام العروض.'
        || E'\n\nيمكنكم متابعة العروض فور وصولها عبر بوابتكم:\n\n' || v_link
        || E'\n\nوتفضلوا بقبول فائق الاحترام والتقدير،';
    else
      v_subj := 'An update on your request for quotations — ' || v_where;
      v_body := coalesce('Dear ' || v_name || ',', 'Dear Customer,') || E'\n\n'
        || case when v_n = 0 then 'Your request for ' || v_where || ' has not received a quotation yet. '
                when v_n = 1 then 'Your request for ' || v_where || ' has received one quotation so far; we aim for at least three for you to compare. '
                else 'Your request for ' || v_where || ' has received two quotations so far; we aim for at least three for you to compare. ' end
        || 'We have invited more suppliers who match your request, reminded the suppliers already invited, and your request stays open for quotations.'
        || E'\n\nYou can follow the quotations as they arrive in your portal:\n\n' || v_link;
    end if;
  elsif p_kind = 'reveal_outcome_check' then
    if v_ar then
      v_subj := 'هل تواصلتم مع ' || coalesce(p->>'supplier', 'المورّد') || '؟ — QuotesDone';
      v_body := coalesce('السادة/ ' || v_name || ' المحترمين،', 'عميلنا العزيز،') || E'\n\nتحية طيبة وبعد،\n\n'
        || 'مضى أسبوع على اطّلاعكم على بيانات التواصل مع ' || coalesce(p->>'supplier', 'المورّد')
        || ' بشأن طلبكم في مجال ' || v_trade_ar || '، ونودّ الاطمئنان على سير الأمور: هل تواصلتم معهم؟ وهل أُسند العمل إليهم؟'
        || E'\n\nوفي حال التعاقد معهم، يُرجى تأكيد ذلك من بوابتكم باختيار «تعاقدتُ مع هذا المورّد» على عرضهم:\n\n' || v_link
        || E'\n\nوإن لم يتواصلوا معكم، أو قرّرتم عدم المضي قدمًا، يكفي الرد على هذه الرسالة وسنتابع الأمر معكم.'
        || E'\n\nوتفضلوا بقبول فائق الاحترام والتقدير،';
    else
      v_subj := 'Did you get in touch with ' || coalesce(p->>'supplier', 'the supplier') || '? — QuotesDone';
      v_body := coalesce('Dear ' || v_name || ',', 'Dear Customer,') || E'\n\n'
        || 'It has been a week since you revealed the contact details of ' || coalesce(p->>'supplier', 'the supplier')
        || ' for your ' || v_trade || ' request. We would like to know how it is going: have you been in touch, and did you award them the work?'
        || E'\n\nIf you hired them, please confirm it in your portal by choosing "I hired this supplier" on their quotation:\n\n' || v_link
        || E'\n\nIf they have not contacted you, or you decided not to go ahead, simply reply to this e-mail and we will follow it up with you.';
    end if;
  else
    raise exception 'fn_seat_clock_compose: unknown kind %', p_kind;
  end if;
  return jsonb_build_object('lang', v_lang, 'subject', v_subj, 'body', v_body, 'link', v_link);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_seat_clock_customer_is_fixture(p customers)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(p.is_demo, false) or coalesce(p.full_name, '') ~* '^\s*zz\s*demo' or public.fn_is_demo_email(p.email)
$function$


CREATE OR REPLACE FUNCTION public.fn_seat_clock_deliver(p_seat text, p_type text, p_to_role text, p_to text, p_subject_is_fixture boolean, p_lang text, p_kind text, p jsonb, p_dedupe_key text, p_inquiry_id uuid DEFAULT NULL::uuid, p_quote_id uuid DEFAULT NULL::uuid, p_lead_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare m jsonb; v jsonb; v_why text; v_key text := 'seat_clock_not_written:' || p_dedupe_key;
begin
  if public.fn_seat_clock_asked(p_dedupe_key) then return jsonb_build_object('ok', true, 'already', true); end if;
  v_why := public.fn_seat_clock_refusal(p_subject_is_fixture, p_to, p_type);
  if v_why is null then
    m := public.fn_seat_clock_compose(p_kind, p_lang, p);
    v := public.fn_customer_support_takes_delivery(jsonb_build_array(jsonb_build_object(
      'type', p_type, 'requested_by', p_seat, 'channel', 'email', 'to_email', lower(btrim(p_to)), 'to_role', p_to_role,
      'lead_id', p_lead_id, 'inquiry_id', p_inquiry_id, 'quote_id', p_quote_id, 'lang', m->>'lang',
      'subject', m->>'subject', 'body', m->>'body', 'dedupe_key', p_dedupe_key)));
    if coalesce(v->0->>'status', '') <> 'failed' then
      return jsonb_build_object('ok', true, 'delivery', v->0, 'lang', m->>'lang');
    end if;
    v_why := 'the delivery request failed: ' || coalesce(v->0->>'error', 'no error recorded');
  end if;
  -- A SKIP IS RECORDED, NEVER ONLY COUNTED: one finding per message, owned by the seat that wanted to send
  -- it. An opt-out is the recipient's own choice (instruction 632) -- recorded and closed at once, so it is
  -- on the ledger without paging anybody; anything else stays open for the seat to act on. The same opt-out
  -- seen again on the next tick is already on the ledger and is not re-written.
  if v_why like 'opted out%' and exists (select 1 from public.it_engineer_finding
                                          where issue_key = v_key and closed_at is not null and evidence->>'reason' = v_why) then
    return jsonb_build_object('ok', false, 'reason', v_why, 'recorded_as', v_key);
  end if;
  perform public.fn_it_engineer_finding_upsert(v_key,
    left('Not sent (' || p_type || ' to the ' || p_to_role || '): ' || v_why, 300),
    'seat clock ' || p_seat || ' -> fn_seat_clock_deliver', case when v_why like 'opted out%' then 'agent_facing' else 'customer_facing' end, 1,
    jsonb_build_object('type', p_type, 'to_role', p_to_role, 'reason', v_why, 'dedupe_key', p_dedupe_key,
                       'inquiry_id', p_inquiry_id, 'quote_id', p_quote_id, 'lead_id', p_lead_id,
                       'owner_seat', p_seat, 'duty', 'seat_clock', 'demo', p_subject_is_fixture),
    '{}'::text[], '{}'::text[], p_seat);
  if v_why like 'opted out%' then
    perform public.fn_it_engineer_finding_close(v_key, 'recorded: the recipient opted out of this kind of mail, which is the rule (instruction 632)');
  end if;
  return jsonb_build_object('ok', false, 'reason', v_why, 'recorded_as', v_key);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_seat_clock_lead_is_fixture(p leads)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(p.is_demo, false) or coalesce(p.company_name, '') ~* '^\s*zz\s*demo'
      or public.fn_is_demo_email(p.email) or public.fn_is_demo_email(p.claimed_by)
$function$


CREATE OR REPLACE FUNCTION public.fn_seat_clock_policy(p_key text, p_default numeric)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce((select case when jsonb_typeof(value) = 'number' then (value #>> '{}')::numeric end
                     from public.decision_policy where key = p_key), p_default)
$function$


CREATE OR REPLACE FUNCTION public.fn_seat_clock_refusal(p_subject_is_fixture boolean, p_to text, p_type text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_e text := lower(btrim(coalesce(p_to, ''))); v_reason text;
begin
  if v_e !~ '^[a-z0-9._%+-]+@[a-z0-9.-]+[.][a-z]{2,}$' then return 'no valid address'; end if;
  if p_subject_is_fixture then
    return case when public.fn_is_demo_email(v_e) then null else 'a fixture subject may not write to a real address' end;
  end if;
  if public.fn_is_demo_email(v_e) then return 'a real subject may not write to a fixture address'; end if;
  if v_e in (select lower(btrim(x)) from public.app_secrets s, unnest(string_to_array(coalesce(s.value, ''), ',')) x
              where s.key = 'admin_emails') then return 'the founder is never addressed by a seat clock'; end if;
  select s.reason into v_reason from public.email_suppressions s
   where lower(s.email) = v_e and public.fn_suppression_stops(s.reason, p_type) limit 1;
  if found then
    return case when lower(btrim(coalesce(v_reason, ''))) = 'unsubscribe' then 'opted out (unsubscribe) of ' || p_type
                else 'suppressed: ' || coalesce(v_reason, 'no reason recorded') end;
  end if;
  if exists (select 1 from public.email_domain_mx m where m.domain = split_part(v_e, '@', 2)
              and m.has_mx = false and m.kind in ('nxdomain', 'no_records')) then return 'the domain does not accept mail'; end if;
  select b.reason into v_reason from public.email_block_pattern b where b.active and v_e ~ b.pattern limit 1;
  if found then return 'blocked: ' || coalesce(v_reason, 'block pattern'); end if;
  return null;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_seat_clocks_tick()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_out jsonb := '{}'::jsonb; v jsonb; k text; v_ok boolean := true;
begin
  foreach k in array array['complaints', 'short_quotes', 'reveal_outcome', 'reply_watch', 'human_requests', 'portfolio_reminder'] loop
    begin
      v := case k when 'complaints' then public.fn_complaint_clock_tick(false)
                  when 'short_quotes' then public.fn_rfq_short_of_quotes_tick(false)
                  when 'reveal_outcome' then public.fn_reveal_outcome_check_tick(false)
                  when 'reply_watch' then public.fn_support_reply_watch_tick()
                  when 'portfolio_reminder' then public.fn_supplier_portfolio_reminder_tick(false)
                  else public.fn_wa_human_request_tick() end;
    exception when others then
      v := jsonb_build_object('ok', false, 'error', left(sqlerrm, 300));
    end;
    v_ok := v_ok and coalesce((v->>'ok')::boolean, false);
    v_out := v_out || jsonb_build_object(k, v);
  end loop;
  return jsonb_build_object('ok', v_ok) || v_out;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_seat_deliberation_acts_on_handoff(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a public.agent_actions; v_did bigint; v jsonb;
begin
  select * into a from public.agent_actions where id = p_id and kind = 'handoff';
  v_did := nullif(a.detail->>'deliberation_id', '')::bigint;
  if v_did is null then raise exception 'handoff % names no deliberation', p_id; end if;
  -- open() sets handoff_id after fn_seat_handoff returns; the step below does not need it.
  v := public.fn_seat_deliberation_step(v_did);
  return jsonb_build_object('waiting', a.agent || '''s independent review (blind pass, then comparison), then '
                                       || (a.detail->>'from') || ' closes', 'deliberation_id', v_did, 'step', v);
end $function$


CREATE OR REPLACE FUNCTION public.fn_seat_deliberation_blind_payload(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d public.seat_deliberation; v jsonb;
begin
  select * into d from public.seat_deliberation where id = p_id;
  if not found then raise exception 'no seat_deliberation %', p_id; end if;
  -- Built from named columns only. The proposal column is read below solely to prove it is absent.
  v := jsonb_build_object(
    'phase', 'blind', 'deliberation_id', d.id, 'kind', d.kind,
    'author_seat', d.author_seat, 'reviewer_seat', d.reviewer_seat,
    'question', d.question, 'evidence', d.evidence,
    'independent_context', public.fn_seat_deliberation_independent_context(d.reviewer_seat),
    'instructions', 'You are the ' || d.reviewer_seat || ' seat. You have NOT seen what the ' || d.author_seat
      || ' seat proposes, on purpose. Answer the question from the evidence and the independent context alone. '
      || 'verdict: approve = proceed as the question asks; reject = do not; revise = proceed only with changes you name. '
      || 'Give the strongest case AGAINST your own verdict in steelman_against, even if you approve. Agree only if it is right.',
    'output_contract', jsonb_build_object('verdict', 'approve|reject|revise', 'recommendation', 'text',
      'reasoning', 'text', 'steelman_against', 'text, at least one full sentence'));
  if v ? 'proposal' or public.fn_seat_deliberation_proposal_leak(d.proposal, public.fn_seat_deliberation_strings(v)) is not null then
    raise exception 'BLIND_PASS_LEAK: the blind payload for deliberation % carries the proposal (was it pasted into the question or the evidence?)', p_id;
  end if;
  return v;
end $function$


CREATE OR REPLACE FUNCTION public.fn_seat_deliberation_budget(p_author_seat text, p_reviewer_seat text, p_at timestamp with time zone DEFAULT now())
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case when c.author_seat is null
    then jsonb_build_object('ok', false, 'dept', null, 'why', 'no seat_deliberation_ceiling row for ' || p_author_seat || ' -> ' || p_reviewer_seat)
    else jsonb_build_object('ok', s.spent < c.cap_aed_month, 'dept', c.dept_key, 'cap_aed', c.cap_aed_month, 'spent_aed', s.spent,
                            'why', 'reviews ' || p_author_seat || ' -> ' || p_reviewer_seat || ' spent AED ' || s.spent || ' of '
                                   || c.cap_aed_month || ' this month (' || c.dept_key || ')') end
    from (select 1) one
    left join public.seat_deliberation_ceiling c on c.author_seat = p_author_seat and c.reviewer_seat = p_reviewer_seat
    left join lateral (select coalesce(sum(l.cost_aed), 0) spent from public.ai_cost_log l
                        where l.task_class in ('seat_deliberation_blind', 'seat_deliberation_compare')
                          and l.dept_key = c.dept_key and l.agent_key = p_reviewer_seat
                          and l.occurred_at >= (date_trunc('month', p_at at time zone 'Asia/Dubai') at time zone 'Asia/Dubai')) s on true
$function$


CREATE OR REPLACE FUNCTION public.fn_seat_deliberation_close(p_id bigint, p_closed_by text, p_outcome text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d public.seat_deliberation; c public.seat_deliberation_turn;
begin
  select * into d from public.seat_deliberation where id = p_id for update;
  if not found then raise exception 'no seat_deliberation %', p_id; end if;
  if p_closed_by is distinct from d.author_seat then
    raise exception 'only the originating seat % closes deliberation %', d.author_seat, p_id;
  end if;
  if d.status not in ('reviewed', 'no_independent_reviewer') or coalesce(btrim(p_outcome), '') = '' then
    raise exception 'deliberation % closes after the review (or its escalation), with an outcome', p_id;
  end if;
  select * into c from public.seat_deliberation_turn t
   where t.deliberation_id = p_id and t.phase = 'compare' and t.status = 'recorded' order by t.round desc limit 1;
  update public.seat_deliberation set status = 'closed', outcome = p_outcome, closed_at = now() where id = p_id;
  if d.handoff_id is not null then
    -- trg_handoff_only_originator_closes: the author seat names itself, only for this transaction.
    perform set_config('qd.handoff_closer', d.author_seat, true);
    perform public.fn_seat_handoff_complete(d.handoff_id, jsonb_build_object('deliberation_id', p_id,
      'final_verdict', c.verdict, 'reviewer_model', c.model, 'reviewer_provider', c.provider,
      'ended', d.status, 'outcome', p_outcome, 'closed_by', p_closed_by));
  end if;
  return jsonb_build_object('ok', true, 'deliberation_id', p_id, 'final_verdict', c.verdict, 'ended', d.status);
end $function$


CREATE OR REPLACE FUNCTION public.fn_seat_deliberation_compare_payload(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d public.seat_deliberation; b public.seat_deliberation_turn;
begin
  select * into d from public.seat_deliberation where id = p_id;
  if not found then raise exception 'no seat_deliberation %', p_id; end if;
  select * into b from public.seat_deliberation_turn t
   where t.deliberation_id = p_id and t.phase = 'blind' and t.status = 'recorded' order by t.round desc limit 1;
  if not found then
    raise exception 'BLIND_FIRST: deliberation % has no recorded blind verdict; the proposal is not revealed before it', p_id;
  end if;
  return jsonb_build_object(
    'phase', 'compare', 'deliberation_id', d.id, 'kind', d.kind, 'round', d.round,
    'author_seat', d.author_seat, 'reviewer_seat', d.reviewer_seat,
    'question', d.question, 'evidence', d.evidence,
    'independent_context', public.fn_seat_deliberation_independent_context(d.reviewer_seat),
    'your_blind_verdict', jsonb_build_object('verdict', b.verdict, 'steelman_against', b.steelman_against, 'output', b.output),
    'proposal', d.proposal,
    'instructions', 'The ' || d.author_seat || ' seat''s proposal is now revealed. Compare it with YOUR blind verdict above. '
      || 'State explicitly what you agree with and what you do not (write "none" if there is nothing). Give the strongest '
      || 'case AGAINST the proposal even if you approve; an approval without it is rejected as malformed. Do not agree '
      || 'because the proposal is confident, and do not disagree for its own sake.',
    'output_contract', jsonb_build_object('verdict', 'approve|reject|revise', 'agreements', 'text', 'disagreements', 'text',
      'steelman_against', 'text, at least one full sentence', 'reasoning', 'text',
      'changed_from_blind_because', 'text, or "unchanged"'));
end $function$


CREATE OR REPLACE FUNCTION public.fn_seat_deliberation_due(p_limit integer DEFAULT 3)
 RETURNS SETOF bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select d.id from public.seat_deliberation d
   where d.status = 'open'
     and (select count(*) from public.seat_deliberation_turn t
           where t.deliberation_id = d.id and t.round = d.round and t.status = 'failed') < 3
   order by (select max(t.created_at) from public.seat_deliberation_turn t
              where t.deliberation_id = d.id and t.phase <> 'proposal') asc nulls first, d.id
   limit greatest(p_limit, 0);
$function$


CREATE OR REPLACE FUNCTION public.fn_seat_deliberation_independent_context(p_reviewer_seat text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_m0 date := date_trunc('month', now() at time zone 'Asia/Dubai')::date;
  v_f jsonb := public.fn_ceo_plan_funnel();
  v_mtd jsonb := v_f->'month_to_date';
  r numeric;
begin
  return jsonb_build_object(
    'assembled_by', 'fn_seat_deliberation_independent_context for the reviewing seat ' || p_reviewer_seat
                    || '; the author did not supply, filter or see this',
    'assembled_at', now(),
    'plan_targets', (select coalesce(jsonb_agg(to_jsonb(p) - 'updated_at' order by p.month), '[]'::jsonb)
                       from public.ceo_plan_month p where p.month in (v_m0, (v_m0 + interval '1 month')::date)),
    'funnel', v_f,
    'funnel_drop_offs', jsonb_build_object(
      'registered_per_invite',   round((v_mtd->>'registrations_submitted')::numeric / nullif((v_mtd->>'invitations_delivered')::numeric, 0), 4),
      'verified_per_registered', round((v_mtd->>'registrations_verified')::numeric  / nullif((v_mtd->>'registrations_submitted')::numeric, 0), 4),
      'reveals_per_inquiry',     round((v_mtd->>'reveals_paid')::numeric            / nullif((v_mtd->>'inquiries_posted')::numeric, 0), 4),
      'note', 'month to date; null where the denominator is zero'),
    'supplier_gap_by_trade', (select coalesce(jsonb_agg(to_jsonb(g) order by g.gap_to_target desc, g.sendable_shortfall desc), '[]'::jsonb)
                                from (select slug, name, approved, gap_to_target, sendable, invited, sendable_shortfall, status
                                        from public.v_supply_gap where status <> 'TARGET MET'
                                       order by gap_to_target desc, sendable_shortfall desc limit 12) g),
    'supplier_gap_totals', (select jsonb_build_object('trades', count(*),
                                     'target_met', count(*) filter (where status = 'TARGET MET'),
                                     'no_pool', count(*) filter (where status like 'NO POOL%'),
                                     'pool_too_thin', count(*) filter (where status like 'POOL TOO THIN%'))
                              from public.v_supply_gap));
end $function$


CREATE OR REPLACE FUNCTION public.fn_seat_deliberation_norm(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select btrim(regexp_replace(lower(coalesce(p, '')), '[^a-z0-9\u0600-\u06ff]+', ' ', 'g'))
$function$


CREATE OR REPLACE FUNCTION public.fn_seat_deliberation_open(p_kind text, p_author_seat text, p_reviewer_seat text, p_question text, p_evidence jsonb, p_proposal jsonb, p_author_model text, p_author_task_class text DEFAULT NULL::text, p_subject_table text DEFAULT NULL::text, p_subject_id text DEFAULT NULL::text, p_demo boolean DEFAULT false)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id bigint; v_h bigint; v_leak text; v_last text;
begin
  if not exists (select 1 from public.seat_handoff_kind k
                  where k.type = 'deliberation.review' and k.from_seat = p_author_seat and k.to_seat = p_reviewer_seat) then
    raise exception 'no deliberation.review conversation from % to % in seat_handoff_kind: register the pair in the file of the build that starts it',
      p_author_seat, p_reviewer_seat;
  end if;
  v_leak := public.fn_seat_deliberation_proposal_leak(p_proposal, coalesce(p_question, '') || ' ' || public.fn_seat_deliberation_strings(p_evidence));
  if v_leak is not null then
    raise exception 'BLIND_PASS_LEAK: the question or the evidence carries the proposal ("%"); the reviewer would not be blind', v_leak;
  end if;
  -- THE AUTHOR'S MODEL IS A MEASUREMENT, NOT A CLAIM: ai_gateway logged a call by this seat on this model in the
  -- last 24 hours, or the family the reviewer must avoid is unproven. Only a ZZ DEMO deliberation is exempt.
  -- The seat's LATEST successful call on the class that wrote the proposal must be on p_author_model.
  if not (coalesce(p_demo, false) and p_question like 'ZZ DEMO%') then
    if coalesce(btrim(p_author_task_class), '') = '' then
      raise exception 'AUTHOR_MODEL_UNPROVEN: name the task class the proposal was written on (p_author_task_class)';
    end if;
    select l.model_used into v_last from public.ai_cost_log l
     where l.ok and l.task_class = p_author_task_class and l.occurred_at > now() - interval '24 hours'
       and (l.agent_key = p_author_seat or l.seat = p_author_seat)
     order by l.occurred_at desc, l.id desc limit 1;
    if v_last is distinct from p_author_model then
      raise exception 'AUTHOR_MODEL_UNPROVEN: the latest successful % call by % in the last 24 hours was on %, not %',
        p_author_task_class, p_author_seat, coalesce(v_last, 'nothing'), p_author_model;
    end if;
  end if;
  insert into public.seat_deliberation (kind, author_seat, reviewer_seat, question, evidence, proposal, author_model,
                                        author_provider, subject_table, subject_id, demo)
  values (p_kind, p_author_seat, p_reviewer_seat, p_question, p_evidence, p_proposal, p_author_model, '?',
          p_subject_table, p_subject_id, coalesce(p_demo, false))
  returning id into v_id;
  insert into public.seat_deliberation_turn (deliberation_id, round, phase, seat, status, task_class, model, output)
  values (v_id, 1, 'proposal', p_author_seat, 'recorded', p_author_task_class, p_author_model, p_proposal);

  v_h := public.fn_seat_handoff(p_author_seat, p_reviewer_seat, 'deliberation.review', 'seat_deliberation', v_id::text,
           jsonb_build_object('deliberation_id', v_id, 'kind', p_kind, 'demo', coalesce(p_demo, false),
                              'question', left(p_question, 300)));
  update public.seat_deliberation set handoff_id = v_h where id = v_id;
  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_seat_deliberation_proposal_leak(p_proposal jsonb, p_haystack text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_hay text := ' ' || public.fn_seat_deliberation_norm(p_haystack) || ' '; s text; n text; j jsonb; v text;
begin
  for s in select x #>> '{}' from jsonb_path_query(coalesce(p_proposal, 'null'::jsonb), 'strict $.**') x
            where jsonb_typeof(x) = 'string' loop
    n := public.fn_seat_deliberation_norm(s);
    if length(n) >= 24 and strpos(v_hay, ' ' || n || ' ') > 0 then return left(n, 80); end if;
    if btrim(s) ~ '^[\[{"]' then
      begin j := s::jsonb; exception when others then j := null; end;
      if j is not null then
        v := public.fn_seat_deliberation_proposal_leak(j, p_haystack);
        if v is not null then return v; end if;
      end if;
    end if;
  end loop;
  return null;
end $function$


CREATE OR REPLACE FUNCTION public.fn_seat_deliberation_record(p_id bigint, p_phase text, p_model text, p_output jsonb, p_prompt_tokens integer DEFAULT NULL::integer, p_output_tokens integer DEFAULT NULL::integer, p_status text DEFAULT 'recorded'::text, p_why text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d public.seat_deliberation; v_id bigint; o jsonb := coalesce(p_output, '{}'::jsonb);
begin
  select * into d from public.seat_deliberation where id = p_id for update;
  if not found then raise exception 'no seat_deliberation %', p_id; end if;
  if d.status <> 'open' then raise exception 'seat_deliberation % is %, not open', p_id, d.status; end if;
  if p_phase not in ('blind', 'compare') then raise exception 'only the reviewer''s blind and compare turns are recorded here'; end if;
  -- A gateway that held the call after the step did not: "held, not run" is recorded once per round and phase.
  if p_status = 'held_not_run' then
    select t.id into v_id from public.seat_deliberation_turn t where t.deliberation_id = p_id and t.round = d.round
       and t.phase = p_phase and t.status = 'held_not_run';
    if v_id is not null then return v_id; end if;
  end if;

  insert into public.seat_deliberation_turn (deliberation_id, round, phase, seat, status, task_class, model, verdict,
    steelman_against, agreements, disagreements, output, why, prompt_tokens, output_tokens, payload_sha256)
  values (p_id, d.round, p_phase, d.reviewer_seat, p_status, 'seat_deliberation_' || p_phase, p_model,
          case when p_status = 'recorded' then lower(o->>'verdict') end,
          case when jsonb_typeof(o->'steelman_against') = 'string' then o->>'steelman_against' end, o->>'agreements', o->>'disagreements', o, p_why, p_prompt_tokens, p_output_tokens,
          o->>'_payload_sha256')
  returning id into v_id;

  if p_status = 'recorded' and p_phase = 'compare' then
    update public.seat_deliberation set status = 'reviewed' where id = p_id;
    update public.agent_actions
       set evidence = coalesce(evidence, '{}'::jsonb) || jsonb_build_object('deliberation_id', p_id, 'round', d.round,
                        'verdict', lower(o->>'verdict'), 'compare_turn_id', v_id, 'reviewed_at', now()),
           detail = detail || jsonb_build_object('awaiting', d.author_seat || ' closes the deliberation')
     where id = d.handoff_id and kind = 'handoff';
    perform public.fn_seat_handoff_event(d.handoff_id, 'reviewed');
  end if;
  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_seat_deliberation_revise(p_id bigint, p_proposal jsonb, p_author_model text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d public.seat_deliberation; v_last text;
begin
  select * into d from public.seat_deliberation where id = p_id for update;
  if not found then raise exception 'no seat_deliberation %', p_id; end if;
  select t.verdict into v_last from public.seat_deliberation_turn t
   where t.deliberation_id = p_id and t.phase = 'compare' and t.status = 'recorded' and t.round = d.round;
  if d.status <> 'reviewed' or v_last is distinct from 'revise' then
    raise exception 'deliberation % can be revised only after the reviewer asked for a revision', p_id;
  end if;
  if d.round >= d.max_rounds then
    raise exception 'deliberation % is at its last round (%); the author closes it with the reviewer''s verdict', p_id, d.max_rounds;
  end if;
  update public.seat_deliberation set round = round + 1, proposal = p_proposal, status = 'open' where id = p_id;
  insert into public.seat_deliberation_turn (deliberation_id, round, phase, seat, status, model, output)
  values (p_id, d.round + 1, 'proposal', d.author_seat, 'recorded', p_author_model, p_proposal);
  return public.fn_seat_deliberation_step(p_id);
end $function$


CREATE OR REPLACE FUNCTION public.fn_seat_deliberation_step(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  d public.seat_deliberation; a public.seat_deliberation_turn;
  v_phase text; v_class text; v_route jsonb; v_gate jsonb; v_payload jsonb; v_sha text; v_budget jsonb;
begin
  select * into d from public.seat_deliberation where id = p_id for update;
  if not found then raise exception 'no seat_deliberation %', p_id; end if;
  if d.status <> 'open' then return jsonb_build_object('action', 'none', 'status', d.status); end if;

  if not exists (select 1 from public.seat_deliberation_turn t where t.deliberation_id = p_id and t.phase = 'blind' and t.status = 'recorded') then
    v_phase := 'blind';
  elsif not exists (select 1 from public.seat_deliberation_turn t where t.deliberation_id = p_id and t.phase = 'compare'
                       and t.status = 'recorded' and t.round = d.round) then
    v_phase := 'compare';
  else
    return jsonb_build_object('action', 'none', 'status', d.status, 'why', 'round ' || d.round || ' is already compared');
  end if;
  v_class := 'seat_deliberation_' || v_phase;

  select * into a from public.seat_deliberation_turn t
   where t.deliberation_id = p_id and t.phase = 'proposal' and t.status = 'recorded' and t.round <= d.round
   order by t.round desc, t.id desc limit 1;

  -- THE PAIR'S CEILING comes first: a spent ceiling is held exactly like the founder's hold, before any routing.
  v_budget := public.fn_seat_deliberation_budget(d.author_seat, d.reviewer_seat);
  if not coalesce((v_budget->>'ok')::boolean, false) then
    insert into public.seat_deliberation_turn (deliberation_id, round, phase, seat, status, task_class, reviews_turn_id, why)
    values (p_id, d.round, v_phase, d.reviewer_seat, 'held_not_run', v_class, a.id, 'held, not run: pair_ceiling - ' || (v_budget->>'why'))
    on conflict (deliberation_id, round, phase) where status in ('held_not_run', 'no_independent_reviewer') do nothing;
    return jsonb_build_object('action', 'held', 'phase', v_phase, 'why', v_budget->>'why');
  end if;
  v_route := public.fn_ai_route_review(v_class, a.model, d.reviewer_seat, 'seat_deliberation', v_budget->>'dept');

  if coalesce((v_route->>'no_independent_reviewer')::boolean, false) then
    insert into public.seat_deliberation_turn (deliberation_id, round, phase, seat, status, task_class, reviews_turn_id, why)
    values (p_id, d.round, v_phase, d.reviewer_seat, 'no_independent_reviewer', v_class, a.id, v_route->>'why')
    on conflict (deliberation_id, round, phase) where status in ('held_not_run', 'no_independent_reviewer') do nothing;
    update public.seat_deliberation set status = 'no_independent_reviewer' where id = p_id;
    -- ESCALATE: the monitor duty carries it to the CEO and, through it_founder_decision_class, the founder.
    perform public.fn_it_deliberation_independence_watch(d.demo);
    return jsonb_build_object('action', 'escalated', 'phase', v_phase, 'why', v_route->>'why', 'route', v_route);
  end if;

  if not coalesce((v_route->>'use_llm')::boolean, false) then
    insert into public.seat_deliberation_turn (deliberation_id, round, phase, seat, status, task_class, reviews_turn_id, why)
    values (p_id, d.round, v_phase, d.reviewer_seat, 'held_not_run', v_class, a.id, 'held, not run: ' || coalesce(v_route->>'why', 'the router refused'))
    on conflict (deliberation_id, round, phase) where status in ('held_not_run', 'no_independent_reviewer') do nothing;
    return jsonb_build_object('action', 'held', 'phase', v_phase, 'why', v_route->>'why');
  end if;

  v_payload := case v_phase when 'blind' then public.fn_seat_deliberation_blind_payload(p_id)
                            else public.fn_seat_deliberation_compare_payload(p_id) end;
  v_sha := encode(sha256(convert_to(v_payload::text, 'UTF8')), 'hex');

  v_gate := public.fn_kernel_paid_provider_gate(v_route->>'model');
  if not coalesce((v_gate->>'allowed')::boolean, false) then
    insert into public.seat_deliberation_turn (deliberation_id, round, phase, seat, status, task_class, model, reviews_turn_id, payload_sha256, why)
    values (p_id, d.round, v_phase, d.reviewer_seat, 'held_not_run', v_class, v_route->>'model', a.id, v_sha,
            'held, not run: ' || coalesce(v_gate->>'rule', '?') || ' - ' || coalesce(v_gate->>'reason', ''))
    on conflict (deliberation_id, round, phase) where status in ('held_not_run', 'no_independent_reviewer') do nothing;
    return jsonb_build_object('action', 'held', 'phase', v_phase, 'model', v_route->>'model', 'why', v_gate->>'reason');
  end if;

  -- A DEMO DELIBERATION NEVER REACHES A PAID MODEL, hold or no hold.
  if d.demo then
    insert into public.seat_deliberation_turn (deliberation_id, round, phase, seat, status, task_class, model, reviews_turn_id, payload_sha256, why)
    values (p_id, d.round, v_phase, d.reviewer_seat, 'held_not_run', v_class, v_route->>'model', a.id, v_sha, 'held, not run: demo deliberation')
    on conflict (deliberation_id, round, phase) where status in ('held_not_run', 'no_independent_reviewer') do nothing;
    return jsonb_build_object('action', 'held', 'phase', v_phase, 'why', 'demo deliberation');
  end if;
  return jsonb_build_object('action', 'call_model', 'deliberation_id', p_id, 'phase', v_phase, 'round', d.round,
    'task_class', v_class, 'model', v_route->>'model', 'fallback', v_route->>'fallback',
    'counterpart_model', a.model, 'max_tokens', (v_route->>'max_tokens')::int,
    'reviewer_seat', d.reviewer_seat, 'dept', v_budget->>'dept', 'budget', v_budget,
    'payload', v_payload, 'payload_sha256', v_sha,
    'system', 'You are the ' || d.reviewer_seat || ' seat of Quotes Done reviewing work from the ' || d.author_seat
              || ' seat. Reply with ONE JSON object matching output_contract and nothing else.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_seat_deliberation_strings(p jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(string_agg(x #>> '{}', ' '), '') from jsonb_path_query(coalesce(p, 'null'::jsonb), 'strict $.**') x
   where jsonb_typeof(x) = 'string'
$function$


CREATE OR REPLACE FUNCTION public.fn_seat_for_surface(p_signed_in boolean, p_surface text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_surface text := lower(btrim(coalesce(p_surface, '')));
  v_seat    text;
begin
  -- The doors a caller can arrive through. Adding one is a deliberate edit here, which is the
  -- point: a typo'd surface at a call site is a raise, not a silently different answer.
  if v_surface not in ('website_widget','whatsapp','inbound_email','customer_portal','supplier_portal') then
    raise exception 'fn_seat_for_surface: unknown surface %. Known surfaces are website_widget, whatsapp, inbound_email, customer_portal, supplier_portal.', coalesce(p_surface, '(null)');
  end if;

  -- THE FOUNDER'S RULE, AND NOTHING ELSE. Not signed in -> customer_support. Signed in as a
  -- customer or a supplier -> sales_engineer, "because he has all the data". The surface does NOT
  -- move the decision: an anonymous visitor reading /portal is still a stranger on the website and
  -- is still Support's. The surface is carried so it can be recorded beside the answer.
  v_seat := case when coalesce(p_signed_in, false) then 'sales_engineer' else 'customer_support' end;

  perform 1 from public.org_role where role_id = v_seat and status = 'active';
  if not found then
    raise exception 'fn_seat_for_surface: seat % is not an active role. The rule cannot route a caller to a seat that does not exist.', v_seat;
  end if;

  return v_seat;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_seat_handoff(p_from text, p_to text, p_type text, p_subject_table text, p_subject_id text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id bigint; v_key text := p_type || ':' || p_subject_id; v_known boolean;
begin
  if coalesce(btrim(p_subject_id), '') = '' then raise exception 'a handoff must name its subject'; end if;
  v_known := exists (select 1 from public.seat_handoff_kind k
                      where k.type = p_type and k.from_seat = p_from and k.to_seat = p_to);

  select id into v_id from public.agent_actions
   where kind = 'handoff' and agent = p_to and target_id = v_key and status <> 'failed'
   order by id limit 1;
  if v_id is not null then return v_id; end if;

  insert into public.agent_actions (agent, kind, status, risk, title, detail, target_table, target_id)
  values (p_to, 'handoff', case when v_known then 'pending' else 'failed' end, 'low',
          left(p_type || ' from ' || p_from || ' about ' || p_subject_table || ' ' || p_subject_id, 200),
          coalesce(p_payload, '{}'::jsonb) || jsonb_build_object(
            'type', p_type, 'from', p_from, 'from_name', p_from, 'to', p_to,
            'subject_table', p_subject_table, 'subject_id', p_subject_id)
          || case when v_known then '{}'::jsonb
                  else jsonb_build_object('error', 'unregistered handoff kind: no row in public.seat_handoff_kind') end,
          p_subject_table, v_key)
  returning id into v_id;

  if not v_known then
    perform public.fn_seat_handoff_event(v_id, 'failed');
    perform public.fn_it_engineer_finding_upsert(
      'monitor:unregistered_handoff_kind:' || p_type || ':' || p_from || ':' || p_to,
      'Unregistered handoff kind: ' || p_from || ' tried to start "' || p_type || '" with ' || p_to,
      'public.fn_seat_handoff (caller: ' || p_from || ')', 'agent_facing', 1,
      jsonb_build_object('type', p_type, 'from', p_from, 'to', p_to, 'handoff_id', v_id, 'owner_seat', 'ceo',
                         'fix', 'insert the conversation into public.seat_handoff_kind with its handler, in the file of the build that starts it'),
      '{}'::text[], array['which build starts this conversation and which handler answers it'], 'fn_seat_handoff');
    return v_id;
  end if;
  perform public.fn_seat_handoff_event(v_id, 'sent');

  -- THE RECEIVING SEAT ACTS NOW. A failure is recorded on the row and in the stream and never
  -- rolls back the money event that raised it: a refund that settled stays settled.
  begin
    perform public.fn_seat_handoff_act(v_id);
  exception when others then
    update public.agent_actions
       set status = 'failed', decided_at = now(),
           detail = detail || jsonb_build_object('error', left(sqlerrm, 500))
     where id = v_id;
    perform public.fn_seat_handoff_event(v_id, 'failed');
  end;
  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_seat_handoff_act(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a public.agent_actions; k public.seat_handoff_kind; v jsonb;
begin
  select * into a from public.agent_actions where id = p_id and kind = 'handoff' for update;
  if not found then raise exception 'no handoff %', p_id; end if;
  if a.status = 'done' then return a.evidence; end if;

  select * into k from public.seat_handoff_kind
   where type = a.detail->>'type' and from_seat = a.detail->>'from' and to_seat = a.agent;
  if not found then
    raise exception 'no conversation % from % to % in public.seat_handoff_kind', a.detail->>'type', a.detail->>'from', a.agent;
  end if;
  execute format('select public.%I($1)', k.handler) into v using p_id;
  if v is null then raise exception '% answered nothing for handoff %', k.handler, p_id; end if;

  if v ? 'waiting' or k.originator_closes then
    update public.agent_actions
       set detail = detail || jsonb_build_object('awaiting', coalesce(v->>'waiting', a.detail->>'from' || ' re-verification'),
                                                 'replied_at', now()),
           evidence = v
     where id = p_id;
    perform public.fn_seat_handoff_event(p_id, 'waiting');
    return v;
  end if;
  perform public.fn_seat_handoff_complete(p_id, v);
  return v;
end $function$


CREATE OR REPLACE FUNCTION public.fn_seat_handoff_complete(p_id bigint, p_evidence jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a public.agent_actions;
begin
  update public.agent_actions
     set status = 'done', decided_at = now(), decided_by = agent,
         evidence = coalesce(p_evidence, '{}'::jsonb),
         detail = detail - 'awaiting'
   where id = p_id and kind = 'handoff' and status <> 'done'
  returning * into a;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no open handoff ' || p_id); end if;
  perform public.fn_seat_handoff_event(p_id, 'done');

  if a.detail->>'type' = 'refund.remediate' and (a.detail->>'refund_id') is not null then
    perform public.fn_ceo_refund_loop_advance((a.detail->>'refund_id')::bigint);
  elsif a.detail->>'type' = 'incident.fix' and (a.detail->>'incident_id') is not null then
    perform public.fn_ceo_incident_advance((a.detail->>'incident_id')::bigint);
  end if;
  return jsonb_build_object('ok', true, 'handoff_id', p_id, 'type', a.detail->>'type');
end $function$


CREATE OR REPLACE FUNCTION public.fn_seat_handoff_event(p_id bigint, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a public.agent_actions;
begin
  select * into a from public.agent_actions where id = p_id;
  if not found then return; end if;
  insert into public.company_event (event_type, entity_type, entity_id, actor, payload)
  values ('handoff.' || coalesce(a.detail->>'type', '?') || '.' || p_status, 'agent_actions', a.id::text,
          coalesce(a.detail->>'from', 'system'),
          jsonb_build_object('handoff_id', a.id, 'type', a.detail->>'type', 'from', a.detail->>'from',
                             'to', a.agent, 'status', p_status, 'subject_table', a.detail->>'subject_table',
                             'subject_id', a.detail->>'subject_id', 'refund_id', a.detail->>'refund_id',
                             'transaction_id', a.detail->>'transaction_id', 'awaiting', a.detail->>'awaiting'));
end $function$


CREATE OR REPLACE FUNCTION public.fn_seat_handoff_types()
 RETURNS TABLE(type text, from_seat text, to_seat text, meaning text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select k.type, k.from_seat, k.to_seat, k.meaning from public.seat_handoff_kind k
$function$


CREATE OR REPLACE FUNCTION public.fn_seat_liveness(p_include_demo boolean DEFAULT false)
 RETURNS TABLE(seat text, verdict text, last_act timestamp with time zone, acts_24h integer, last_run timestamp with time zone, runs_24h integer, overdue integer, oldest_overdue timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with s as (select o.agent_key seat from public.org_agents o where o.active),
  x as (
    select s.seat,
           a.last_act, coalesce(a.n24, 0) acts_24h,
           r.last_run, coalesce(r.n24, 0) runs_24h,
           coalesce(d.n, 0) overdue, d.oldest oldest_overdue
      from s
      left join lateral (select max(h.decided_at) last_act,
                                count(*) filter (where h.decided_at > now() - interval '24 hours')::int n24
                           from public.agent_actions h
                          where h.kind = 'handoff' and h.decided_by = s.seat) a on true
      left join lateral (select max(ar.started_at) last_run,
                                count(*) filter (where ar.started_at > now() - interval '24 hours')::int n24
                           from public.agent_runs ar
                          where ar.agent in (s.seat, 'fn:' || s.seat)
                            and ar.started_at > now() - interval '7 days') r on true
      -- The overdue count is the handoff_sla duty's own reading, not a second copy of its rule: only
      -- handoffs the seat has not REPLIED to past their window (an it.finding it answered and the IT
      -- engineer has not yet closed is not the seat's delay), and founder-bound delivery requests are
      -- left to the delivery duty, which waits out the 19:00 Dubai digest hold.
      left join (select e->'evidence'->>'seat' seat, sum((e->>'affected')::int)::int n,
                        min((e->'evidence'->>'oldest_at')::timestamptz) oldest
                   from jsonb_array_elements(public.fn_it_handoff_sla_items(p_include_demo)) e
                  where e->'evidence'->>'state' = 'unanswered'
                  group by 1) d on d.seat = s.seat)
  select x.seat,
         case when x.overdue > 0 and (x.last_act is null or x.last_act < x.oldest_overdue) then 'stopped'
              when x.overdue > 0 then 'behind'
              when x.acts_24h + x.runs_24h > 0 then 'acting'
              else 'idle' end,
         x.last_act, x.acts_24h, x.last_run, x.runs_24h, x.overdue, x.oldest_overdue
    from x order by x.seat
$function$


CREATE OR REPLACE FUNCTION public.fn_seat_takes_ceo_directive(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a public.agent_actions; d jsonb; v_gates jsonb; v_duty text; v_block text;
begin
  select * into a from public.agent_actions where id = p_id and kind = 'handoff';
  if not found then raise exception 'no handoff %', p_id; end if;
  d := a.detail;
  select jsonb_build_object('on', coalesce(max(value) filter (where key='invite_enabled'),'') = 'true'
                                 and coalesce(max(value) filter (where key='supplier_outreach_golive'),'') = 'true',
                            'cap', max(value) filter (where key='invite_daily_cap'))
    into v_gates from public.app_secrets where key in ('invite_enabled','supplier_outreach_golive','invite_daily_cap');
  case d->>'stage'
    when 'invitations', 'registrations' then
      v_duty := 'fn_sales_engineer_supplier_outreach_tick: the daily invitation batch (cap '||coalesce(v_gates->>'cap','?')||') and the day-2/day-6 registration reminders';
      if not (v_gates->>'on')::boolean then v_block := 'held: the founder''s invitation switches are off'; end if;
    when 'verification' then
      v_duty := 'fn_sales_engineer_supplier_outreach_tick: the 24-hour clock on a submitted registration, and the mandatory-six check';
    when 'deliverability' then
      v_duty := 'fn_delivery_feedback_canary_tick and the outbox bounce brake: suppress the bouncing addresses, prove bounce reports arrive';
    when 'quotes' then
      v_duty := 'the RFQ dispatch and the spec-offer duty: widen the match inside the exact trade and chase the suppliers who have not quoted';
    when 'reveals' then
      v_duty := 'the comparison follow-up with the customer; the payment path is the accountant''s nightly test';
    when 'demand' then
      v_duty := 'the marketing seat''s duties (supabase/functions/marketing/duties.ts): approved posts, the social inbox and paid reach that bring buyers to post requests; its daily report (marketing.report) says what moved';
    else
      v_duty := 'no standing duty carries this stage'; v_block := 'no owner duty exists';
  end case;
  return jsonb_build_object('accepted', true, 'seat', a.agent, 'stage', d->>'stage', 'duty', v_duty, 'blocker', v_block,
    'measure_key', d->>'measure_key', 'target', d->'target', 'due_at', d->>'due_at',
    'reading_now', public.fn_ceo_plan_measure(d->>'measure_key', a.created_at, now()),
    'waiting', 'the CEO re-measures '||(d->>'measure_key')||' by '||(d->>'due_at'));
end $function$


CREATE OR REPLACE FUNCTION public.fn_security_audit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_old jsonb; v_new jsonb; v_pk text;
begin
  v_old := case when tg_op in ('UPDATE','DELETE') then to_jsonb(old) else null end;
  v_new := case when tg_op in ('INSERT','UPDATE') then to_jsonb(new) else null end;
  if tg_table_name = 'app_secrets' then
    if v_old ? 'value' then v_old := jsonb_set(v_old, '{value}', '"***REDACTED***"'); end if;
    if v_new ? 'value' then v_new := jsonb_set(v_new, '{value}', '"***REDACTED***"'); end if;
  end if;
  v_pk := coalesce(v_new->>'id', v_old->>'id', v_new->>'key', v_old->>'key',
                   v_new->>'name', v_old->>'name', v_new->>'role', v_old->>'role');
  insert into public.security_audit_log(action, table_name, row_pk, old_data, new_data)
  values (tg_op, tg_table_name, v_pk, v_old, v_new);
  return coalesce(new, old);
end $function$


CREATE OR REPLACE FUNCTION public.fn_security_audit_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  raise exception 'security_audit_log is append-only; % is not permitted', tg_op;
end $function$


CREATE OR REPLACE FUNCTION public.fn_security_detect(p_window interval DEFAULT '24:00:00'::interval)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_since timestamptz := now() - p_window;
  v jsonb := '{}'::jsonb;
  n int;
begin
  -- D1 MALWARE. A recorded malicious verdict is the highest-confidence detection this estate has.
  with ins as (
    insert into public.security_events (kind, severity, source, subject, detail, fingerprint)
    select 'malware_file', 'high', f.source, coalesce(f.subject, f.filename),
           jsonb_build_object('file_scan_id', f.id, 'sha256', f.sha256, 'filename', f.filename,
                              'mime', f.mime, 'bucket', f.bucket, 'path', f.path,
                              'engines_malicious', f.engines_malicious,
                              'engines_total', f.engines_total, 'blocked', f.blocked),
           'file_scan:' || f.id
      from public.file_scan f
     where f.verdict in ('malicious','suspicious')
    on conflict (fingerprint) do nothing
    returning 1)
  select count(*) into n from ins;  v := v || jsonb_build_object('malware_file', n);

  -- D2 UNJUDGED. A file that entered and still has no clean verdict after 24h is sitting in the
  -- estate unscanned. Low severity, but it must be VISIBLE — an unknown must never render as safe.
  with ins as (
    insert into public.security_events (kind, severity, source, subject, detail, fingerprint)
    select 'file_unscanned', 'low', f.source, coalesce(f.subject, f.filename),
           jsonb_build_object('file_scan_id', f.id, 'sha256', f.sha256, 'verdict', f.verdict,
                              'filename', f.filename, 'bucket', f.bucket, 'path', f.path),
           'file_unscanned:' || f.id
      from public.file_scan f
     where f.verdict in ('unknown','unavailable')
       and f.created_at < now() - interval '24 hours'
       and not public.fn_file_is_cleared(f.sha256)
    on conflict (fingerprint) do nothing
    returning 1)
  select count(*) into n from ins;  v := v || jsonb_build_object('file_unscanned', n);

  -- D3 CREDENTIAL MISUSE. internal_credential_audit.allowed=false is a presented secret that was
  -- REFUSED: a wrong secret, a retired one, or one used outside its scope. 11 such rows exist today.
  with ins as (
    insert into public.security_events (kind, severity, source, subject, detail, fingerprint)
    select 'credential_refused', 'medium', a.function_name, a.context,
           jsonb_build_object('audit_id', a.id, 'credential_id', a.credential_id,
                              'reason', a.reason, 'at', a.at, 'detail', a.detail),
           'cred_audit:' || a.id
      from public.internal_credential_audit a
     where a.allowed = false
    on conflict (fingerprint) do nothing
    returning 1)
  select count(*) into n from ins;  v := v || jsonb_build_object('credential_refused', n);

  -- D4 A DEAD CREDENTIAL THAT STILL WORKS. last_used_at after retired_at or after expires_at means
  -- a secret that should have stopped being accepted was accepted. That is containment-worthy:
  -- 83 of the 90 rows in internal_credential are active, so revoking one is a real action available
  -- today, and this detection is the trigger for it.
  with ins as (
    insert into public.security_events (kind, severity, source, subject, detail, fingerprint)
    select 'credential_used_after_end', 'high', c.last_function, c.context,
           jsonb_build_object('credential_id', c.id, 'label', c.label, 'active', c.active,
                              'retired_at', c.retired_at, 'expires_at', c.expires_at,
                              'last_used_at', c.last_used_at, 'use_count', c.use_count),
           'cred_after_end:' || c.id || ':' || to_char(c.last_used_at at time zone 'utc','YYYYMMDDHH24')
      from public.internal_credential c
     where c.last_used_at is not null
       and ( (c.retired_at is not null and c.last_used_at > c.retired_at)
          or (c.expires_at is not null and c.last_used_at > c.expires_at)
          or (c.active = false and c.last_used_at > coalesce(c.retired_at, c.rotated_at, c.created_at)) )
    on conflict (fingerprint) do nothing
    returning 1)
  select count(*) into n from ins;  v := v || jsonb_build_object('credential_used_after_end', n);

  -- D5 OTP BRUTE FORCE. The login is a mobile number and a one-time code (there is no observe mode
  -- and no password), so guessing the code IS the attack on customer identity. attempts is
  -- incremented per wrong code by the verifier.
  with ins as (
    insert into public.security_events (kind, severity, source, subject, detail, fingerprint)
    select 'otp_brute_force', 'medium', 'customer_phone_otps', o.phone,
           jsonb_build_object('otp_id', o.id, 'attempts', o.attempts, 'consumed', o.consumed,
                              'customer_id', o.customer_id, 'created_at', o.created_at),
           'otp_attempts:' || o.id
      from public.customer_phone_otps o
     where o.attempts >= 5
       and o.created_at >= v_since
    on conflict (fingerprint) do nothing
    returning 1)
  select count(*) into n from ins;  v := v || jsonb_build_object('otp_brute_force', n);

  -- D6 OTP ENUMERATION. Many codes ISSUED to one number in a short window is a different attack
  -- from many codes guessed: it is someone using our SMS to hammer a phone, or mapping which
  -- numbers exist. Bucketed to the hour so the fingerprint is stable across re-runs.
  with agg as (
    select o.phone, date_trunc('hour', o.created_at) as hr, count(*) as issued
      from public.customer_phone_otps o
     where o.created_at >= v_since
     group by 1,2
    having count(*) >= 5),
  ins as (
    insert into public.security_events (kind, severity, source, subject, detail, fingerprint)
    select 'otp_enumeration', 'medium', 'customer_phone_otps', agg.phone,
           jsonb_build_object('issued', agg.issued, 'hour', agg.hr),
           'otp_issued:' || agg.phone || ':' || to_char(agg.hr at time zone 'utc','YYYYMMDDHH24')
      from agg
    on conflict (fingerprint) do nothing
    returning 1)
  select count(*) into n from ins;  v := v || jsonb_build_object('otp_enumeration', n);

  -- D7 SSRF. resend_inbound records a refused attachment URL into agent_runs with
  -- counts.ssrf_refused; accountant reports the same refusal in its run note. Both are read here
  -- rather than adding a second write path to two deployed functions.
  with ins as (
    insert into public.security_events (kind, severity, source, subject, detail, fingerprint)
    select 'ssrf_refused', 'medium', r.agent, r.counts->>'stage',
           jsonb_build_object('agent_run_id', r.id, 'counts', r.counts,
                              'note', left(coalesce(r.note,''), 500), 'at', r.started_at),
           'agent_run_ssrf:' || r.id
      from public.agent_runs r
     where r.started_at >= v_since
       and ( r.counts ? 'ssrf_refused'
          or r.note ilike '%url_refused%'
          or r.note ilike '%url_refused_after_redirect%' )
    on conflict (fingerprint) do nothing
    returning 1)
  select count(*) into n from ins;  v := v || jsonb_build_object('ssrf_refused', n);

  -- D8 A REFUSED UPLOAD SHAPE. sanitizeUpload refusing an executable, an HTML polyglot or a zip
  -- bomb is the guard working — and a run of them from one sender is someone probing what we
  -- accept. Recorded low, because a single refusal is far more often a careless browser.
  with ins as (
    insert into public.security_events (kind, severity, source, subject, detail, fingerprint)
    select 'upload_shape_refused', 'low', r.agent, null,
           jsonb_build_object('agent_run_id', r.id, 'counts', r.counts,
                              'note', left(coalesce(r.note,''), 500), 'at', r.started_at),
           'agent_run_upload:' || r.id
      from public.agent_runs r
     where r.started_at >= v_since
       and ( r.counts ? 'attachment_refused'
          or r.note ilike '%refused by sanitizeUpload%'
          or r.note ilike '%unsafe_file_type%'
          or r.note ilike '%unsafe_file_content%'
          or r.note ilike '%zip_expands_too_far%' )
    on conflict (fingerprint) do nothing
    returning 1)
  select count(*) into n from ins;  v := v || jsonb_build_object('upload_shape_refused', n);

  -- D9 SECRETS. security_audit_log is trigger-written and had 76 rows that nothing ever read.
  --
  -- THE FIRST VERSION OF THIS BRANCH WAS WRONG AND THE EXECUTION SHOWED IT. It raised one medium
  -- event per row, which on the first run produced 76 'secret_table_written' events against ONE
  -- malware event — a guard that fires when the system works, burying the signal it exists to
  -- surface. Measured: all 76 rows are app_secrets INSERT/UPDATE by db_user `postgres`, which is
  -- how EVERY secret in this estate is written, so "a secret was written" carries no information.
  -- The 76 noise rows were deleted with this correction; nothing else in security_events was
  -- touched, and the corrected rules below use different fingerprints so they evaluate freely.
  --
  -- What DOES carry information, and is rare enough to mean something:
  --   * a DELETE — no routine in this estate deletes a secret or a credential row;
  --   * a write by a db_user that is not one of ours;
  --   * a BURST. Measured over the whole table: the busiest hour ever recorded is 5 writes. 25 in
  --     one hour is five times the observed peak, so it cannot fire on ordinary operation, and it
  --     is raised ONCE per hour rather than once per row.
  with ins as (
    insert into public.security_events (kind, severity, source, subject, detail, fingerprint)
    select case when s.action = 'DELETE' then 'secret_deleted' else 'secret_written_by_unexpected_role' end,
           'high', 'security_audit_log', s.db_user,
           jsonb_build_object('audit_id', s.id, 'action', s.action, 'table', s.table_name,
                              'row_pk', s.row_pk, 'at', s.at, 'old', s.old_data),
           'sec_audit:' || s.id
      from public.security_audit_log s
     where s.at >= v_since
       and s.table_name in ('app_secrets','internal_credential','internal_credential_audit')
       and ( s.action = 'DELETE'
          or s.db_user is null
          or s.db_user not in ('postgres','supabase_admin','supabase_storage_admin','service_role') )
    on conflict (fingerprint) do nothing
    returning 1)
  select count(*) into n from ins;  v := v || jsonb_build_object('secret_anomaly', n);

  with agg as (
    select date_trunc('hour', s.at) as hr, count(*) as writes
      from public.security_audit_log s
     where s.at >= v_since
       and s.table_name in ('app_secrets','internal_credential')
     group by 1
    having count(*) >= 25),
  ins as (
    insert into public.security_events (kind, severity, source, subject, detail, fingerprint)
    select 'secret_write_burst', 'medium', 'security_audit_log', null,
           jsonb_build_object('writes', agg.writes, 'hour', agg.hr,
                              'observed_peak_before_this_rule', 5),
           'secret_burst:' || to_char(agg.hr at time zone 'utc','YYYYMMDDHH24')
      from agg
    on conflict (fingerprint) do nothing
    returning 1)
  select count(*) into n from ins;  v := v || jsonb_build_object('secret_write_burst', n);

  -- D10 A NEW SECURITY ADVISOR FINDING. in_baseline=false means the finding appeared after the
  -- baseline was taken. WARN is medium, INFO is low — a new table with RLS on and no policy is
  -- worth seeing but is not an intrusion.
  with ins as (
    insert into public.security_events (kind, severity, source, subject, detail, fingerprint)
    select 'new_security_advisor',
           case when b.level in ('WARN','ERROR') then 'medium' else 'low' end,
           'supabase_advisors', b.name,
           jsonb_build_object('cache_key', b.cache_key, 'level', b.level, 'title', b.title,
                              'metadata', b.metadata, 'first_seen_at', b.first_seen_at),
           'advisor:' || b.cache_key
      from public.security_advisor_baseline b
     where b.in_baseline = false
       and b.cleared_at is null
    on conflict (fingerprint) do nothing
    returning 1)
  select count(*) into n from ins;  v := v || jsonb_build_object('new_security_advisor', n);

  return v || jsonb_build_object(
    'window', p_window::text,
    'at', now(),
    'total_new', (select coalesce(sum((value)::int), 0)
                    from jsonb_each_text(v) where key <> 'window'));
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_security_detect_on_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  -- Never let the watch break the thing it watches: a detector that raises stops a supplier
  -- registering, which is a worse outcome than a late event.
  begin
    perform public.fn_security_detect(interval '1 hour');
  exception when others then
    null;
  end;
  return null;
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_security_watch(p_window interval DEFAULT '7 days'::interval)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'at', now(),
    'window', p_window::text,
    'events_by_kind', coalesce((
        select jsonb_object_agg(kind, c) from (
          select kind, count(*) c from public.security_events
           where created_at >= now() - p_window group by 1) t), '{}'::jsonb),
    'events_by_severity', coalesce((
        select jsonb_object_agg(severity, c) from (
          select severity, count(*) c from public.security_events
           where created_at >= now() - p_window group by 1) t), '{}'::jsonb),
    'files_scanned', (select count(*) from public.file_scan where created_at >= now() - p_window),
    'files_by_verdict', coalesce((
        select jsonb_object_agg(verdict, c) from (
          select verdict, count(*) c from public.file_scan
           where created_at >= now() - p_window group by 1) t), '{}'::jsonb),
    'files_blocked', (select count(*) from public.file_scan
                       where blocked and created_at >= now() - p_window),
    'quarantined_total', (select count(*) from public.v_file_quarantine),
    'advisors_baseline', (select count(*) from public.security_advisor_baseline where in_baseline),
    'advisors_new', (select count(*) from public.security_advisor_baseline
                      where not in_baseline and cleared_at is null),
    'advisors_last_refreshed', (select max(last_seen_at) from public.security_advisor_baseline),
    'gaps_open', (select jsonb_agg(jsonb_build_object('name', name, 'status', status,
                                                      'needs', what_would_close_it))
                    from public.security_gap where status <> 'closed')
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_select_model(p_task_class text, p_dept_key text DEFAULT NULL::text, p_confidence numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$ select fn_ai_route(p_task_class, p_dept_key, p_confidence, null, false); $function$


CREATE OR REPLACE FUNCTION public.fn_self_review()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_found int := 0;
begin
  -- Stale knowledge: past its review date
  insert into self_review (review_type, subject, finding, evidence, proposal)
  select 'stale_knowledge', k.agent_key||' / '||k.topic,
         'Knowledge past its review date',
         'review_due '||k.review_due||', owner '||coalesce(k.owner_agent,'none')||', confidence '||coalesce(k.confidence::text,'unset'),
         'Re-research and revalidate, or mark superseded'
  from agent_knowledge k
  where k.review_due < current_date
    and not exists (select 1 from self_review s where s.review_type='stale_knowledge'
                     and s.subject = k.agent_key||' / '||k.topic and s.status='proposed');
  get diagnostics v_found = row_count;

  -- Departments that cannot act
  insert into self_review (review_type, subject, finding, evidence, proposal)
  select 'overloaded_dept', d.dept_key,
         'Department has authority but no wired executor',
         (select count(*)::text from org_authority a where a.dept_key=d.dept_key)||' authority rules, 0 executors',
         'Wire an executor or remove the authority rule'
  from org_departments d
  where d.active
    and not exists (select 1 from org_action_executor e where e.department=d.dept_key and e.active)
    and not exists (select 1 from self_review s where s.review_type='overloaded_dept' and s.subject=d.dept_key and s.status='proposed');

  -- Employees with no KPI
  insert into self_review (review_type, subject, finding, evidence, proposal)
  select 'missed_kpi', a.agent_key,
         'Employee has no measurable KPI',
         'title '||coalesce(a.title,'none')||', department '||a.department,
         'Assign a KPI tied to a company goal, or retire the role'
  from org_agents a
  where a.active
    and not exists (select 1 from employee_kpi k where k.agent_key=a.agent_key and k.active)
    and not exists (select 1 from self_review s where s.review_type='missed_kpi' and s.subject=a.agent_key and s.status='proposed');

  -- Recurring failures: any agent failing more than 3 times in 7 days
  insert into self_review (review_type, subject, finding, evidence, proposal)
  select 'recurring_failure', r.agent,
         'Agent failing repeatedly',
         count(*)||' failures in 7 days; latest: '||left(coalesce(max(r.note),''),160),
         'Diagnose root cause; this is an automation candidate if the fix is mechanical'
  from agent_runs r
  where r.started_at > now() - interval '7 days' and r.status='error'
  group by r.agent having count(*) > 3
    and not exists (select 1 from self_review s where s.review_type='recurring_failure' and s.subject=r.agent and s.status='proposed');

  -- Categories with supply but no standard knowledge
  insert into self_review (review_type, subject, finding, evidence, proposal)
  select 'stale_sop', v.catalog_slug,
         'Category has supplier supply but no standard knowledge base',
         v.supplier_supply||' suppliers in pipeline, coverage '||v.coverage,
         'Build the 14-module knowledge base; supplier supply is already there'
  from v_category_coverage v
  where v.coverage <> 'COMPLIANT' and v.supplier_supply >= 100
    and not exists (select 1 from self_review s where s.review_type='stale_sop' and s.subject=v.catalog_slug and s.status='proposed');

  return jsonb_build_object(
    'stale_knowledge', (select count(*) from self_review where review_type='stale_knowledge' and status='proposed'),
    'depts_cannot_act', (select count(*) from self_review where review_type='overloaded_dept' and status='proposed'),
    'employees_no_kpi', (select count(*) from self_review where review_type='missed_kpi' and status='proposed'),
    'recurring_failures', (select count(*) from self_review where review_type='recurring_failure' and status='proposed'),
    'categories_needing_knowledge', (select count(*) from self_review where review_type='stale_sop' and status='proposed'),
    'total_open', (select count(*) from self_review where status='proposed'));
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_seniority_rank(p text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case lower(coalesce(p,''))
           when 'executive' then 1 when 'director' then 2
           when 'manager'   then 3 when 'specialist' then 4 else 9 end;
$function$


CREATE OR REPLACE FUNCTION public.fn_service_implications(p_sources text[])
 RETURNS TABLE(implies_key text, from_code text, reason_en text, reason_ar text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select i.implies_trade || '.' || i.implies_code, i.from_code, i.reason_en, i.reason_ar
  from public.service_implication i
  where i.active and i.from_code = any(coalesce(p_sources, '{}'::text[]))
  order by 1, 2;
$function$


CREATE OR REPLACE FUNCTION public.fn_services_effective(p_stated text[], p_trades text[] DEFAULT '{}'::text[], p_removed text[] DEFAULT '{}'::text[])
 RETURNS text[]
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with stated as (
    select distinct s.trade_code || '.' || s.code as key
    from public.taxonomy_trade_service s
    where s.active and s.trade_code || '.' || s.code = any(coalesce(p_stated, '{}'::text[]))
  ),
  src as (
    select key from stated
    union
    select t from unnest(coalesce(p_trades, '{}'::text[])) t
  ),
  implied as (
    select distinct i.implies_trade || '.' || i.implies_code as key
    from public.service_implication i
    join src on src.key = i.from_code
    where i.active
  )
  select coalesce(array_agg(distinct key order by key), '{}'::text[])
  from (select key from stated union select key from implied) all_keys
  where key <> all (coalesce(p_removed, '{}'::text[]));
$function$


CREATE OR REPLACE FUNCTION public.fn_should_escalate(ctx jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  reasons text[] := '{}';
  conf_min numeric; fin_review numeric; auto_max numeric; fraud_max numeric;
  legal jsonb; sens jsonb; owner text;
  c_conf numeric := nullif(ctx->>'confidence','')::numeric;
  c_amt  numeric := nullif(ctx->>'amount_aed','')::numeric;
  c_fraud numeric := nullif(ctx->>'fraud_score','')::numeric;
  c_cat  text := lower(coalesce(ctx->>'category',''));
  c_txt  text := lower(coalesce(ctx->>'text',''));
  c_kind text := lower(coalesce(ctx->>'kind',''));
  REPORTING_KINDS constant text[] := array['handoff','incident','report_task'];
  c_money boolean := coalesce((ctx->>'moves_money')::boolean,false);
  trg text;
  c_actor text := nullif(btrim(coalesce(ctx->>'actor', ctx->>'agent_key', '')), '');
  v_route text; v_basis text; v_note text;
  v_mgr text; v_mgr_dept text; v_pick jsonb;
  v_actor_res text;
  v_apex_backup text;   -- D11: the named deputy-apex
begin
  select value::numeric into conf_min   from decision_policy where key='confidence_min';
  select value::numeric into fin_review  from decision_policy where key='financial_review_aed';
  select value::numeric into auto_max    from decision_policy where key='auto_action_max_aed';
  select value::numeric into fraud_max   from decision_policy where key='fraud_score_max';
  select value into legal                from decision_policy where key='legal_triggers';
  select value into sens                 from decision_policy where key='sensitive_categories';
  select value #>> '{}' into owner       from decision_policy where key='review_owner';

  if c_conf is not null and c_conf < conf_min then
     reasons := array_append(reasons, 'confidence '||round(c_conf,2)::text||' < min '||round(conf_min,2)::text); end if;
  if c_amt is not null and c_amt >= fin_review then
     reasons := array_append(reasons, 'amount AED '||c_amt::text||' >= review threshold '||fin_review::text); end if;
  if c_money and (c_amt is null or c_amt > auto_max) then
     reasons := array_append(reasons, 'action moves money beyond autonomous limit'); end if;
  if c_fraud is not null and c_fraud >= fraud_max then
     reasons := array_append(reasons, 'fraud score '||round(c_fraud,2)::text||' >= max '||round(fraud_max,2)::text); end if;
  if c_cat <> '' and sens ? c_cat and (c_conf is null or c_conf < conf_min) then
     reasons := array_append(reasons, 'sensitive category "'||c_cat||'" with low/absent confidence'); end if;
  for trg in select jsonb_array_elements_text(legal) loop
     if c_txt <> '' and position(trg in c_txt) > 0 then
        reasons := array_append(reasons, 'legal trigger: "'||trg||'"'); end if;
  end loop;

  if c_txt <> '' and not (c_kind = any (REPORTING_KINDS)) then
    for trg in
      select m.headline from institutional_memory m
       where m.outcome = 'worse' and coalesce(m.headline,'') <> ''
         and (select count(distinct w) from regexp_split_to_table(lower(m.headline), '[^a-z0-9_]+') w
               where length(w) >= 6 and position(w in c_txt) > 0) >= 3
       order by m.created_at desc limit 2
    loop
      reasons := array_append(reasons,
        'a prior attempt on record ended worse: "'||left(trg, 120)||'"');
    end loop;
  end if;

  -- THE APEX ESCALATES TO THE FOUNDER. Resolved FIRST: the active agent with no manager_key (the CEO)
  -- reports to the founder, not to another agent.
  if c_actor is not null then
    v_actor_res := coalesce(public.fn_org_agent_resolve(c_actor), c_actor);
    perform 1 from org_agents a where a.agent_key = v_actor_res and a.active and a.manager_key is null;
    if found then
      v_route := 'founder'; v_basis := 'apex_to_founder';
      v_note  := 'the company apex ('||v_actor_res||') has no manager; the only party above it is the '
              || 'founder, whose major-issue channel is the single human signal the design allows';
    end if;
  end if;

  -- RESOLVE THE PARTY. The configured review_owner (employee / staffed department / title).
  if v_route is null and owner is not null and btrim(owner) <> '' then
    select a.agent_key into v_route from org_agents a
     where a.active and a.agent_key = owner limit 1;
    if v_route is not null then v_basis := 'employee'; end if;

    if v_route is null then
      select d.dept_key into v_route from org_departments d
       where d.dept_key = owner
         and exists (select 1 from org_agents a where a.department = d.dept_key and a.active)
       limit 1;
      if v_route is not null then v_basis := 'staffed_department'; end if;
    end if;

    if v_route is null then
      select a.agent_key into v_route from org_agents a
       where a.active and a.title ilike '%'||owner||'%'
       order by a.agent_key limit 1;
      if v_route is not null then v_basis := 'employee_by_title'; end if;
    end if;
  end if;

  -- THE REPORTING LINE. The actor's manager (active AND available), else the standing deputy.
  if v_route is null and c_actor is not null then
    select a.manager_key into v_mgr from org_agents a where a.agent_key = c_actor and a.active;
    if v_mgr is not null and v_mgr <> c_actor then
      select a.agent_key into v_route from org_agents a
       where a.agent_key = v_mgr and a.active and a.available
         and (a.unavailable_until is null or a.unavailable_until < current_date);
      if v_route is not null then v_basis := 'reporting_line'; end if;

      if v_route is null then
        select a.department into v_mgr_dept from org_agents a where a.agent_key = v_mgr;
        begin v_pick := public.fn_pick_reviewer(v_mgr_dept);
        exception when others then v_pick := null; end;
        v_route := public.fn_route_party(v_pick->>'reviewer');
        if v_route = c_actor then v_route := null; end if;
        if v_route is not null then
          v_basis := 'reporting_line_delegated';
          v_note  := 'manager '||v_mgr||' is unavailable; '
                  || coalesce(v_pick->>'basis','delegation_rule standing deputy');
        end if;
      end if;
    end if;
  end if;

  -- D11: THE APEX BACKUP. Before the generic executive fallback, a named deputy-apex (the COO) takes
  -- an escalation that did not resolve up the line, so an apex-level item reaches a designated backup
  -- rather than whichever exec member the fallback names. Configured in decision_policy.apex_backup.
  if v_route is null then
    select value #>> '{}' into v_apex_backup from decision_policy where key='apex_backup';
    if v_apex_backup is not null and btrim(v_apex_backup) <> '' then
      select a.agent_key into v_route from org_agents a
       where a.active and a.agent_key = coalesce(public.fn_org_agent_resolve(v_apex_backup), v_apex_backup)
       limit 1;
      if v_route is not null then
        v_basis := 'apex_backup';
        v_note := 'no manager or configured owner resolved; the designated apex backup ('||v_route
               || ') stands in before the generic executive fallback';
      end if;
    end if;
  end if;

  -- The configured owner names nobody and no apex backup resolved. Escalate to the executive
  -- department's own head, recorded as a fallback so the configuration gap stays visible.
  if v_route is null then
    select coalesce(
             (select d.brain_agent from org_departments d where d.dept_key='exec'
               and exists (select 1 from org_agents a where a.agent_key=d.brain_agent and a.active)),
             (select d.lead_agent  from org_departments d where d.dept_key='exec'
               and exists (select 1 from org_agents a where a.agent_key=d.lead_agent and a.active)),
             (select a.agent_key from org_agents a where a.active and a.department='exec'
               order by a.agent_key limit 1))
      into v_route;
    if v_route is not null then
      v_basis := 'fallback_exec';
      v_note := 'configured review_owner "'||coalesce(owner,'(unset)')||'" names no active employee '
             || 'and no staffed department; escalation addressed to '||v_route||' instead';
    end if;
  end if;

  if v_route is null then
    v_route := owner; v_basis := 'unresolved';
    v_note := 'configured review_owner "'||coalesce(owner,'(unset)')||'" resolves to no party in the '
           || 'org model, and no active executive employee was available to take it';
  end if;

  return jsonb_build_object(
    'escalate', array_length(reasons,1) is not null,
    'reasons', to_jsonb(reasons),
    'route_to', v_route,
    'route_basis', v_basis,
    'route_note', v_note,
    'route_owner_configured', owner);
end $function$


CREATE OR REPLACE FUNCTION public.fn_smoke()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_run bigint; v_owner text; v jsonb:='[]'::jsonb; v_fail int:=0; v_sig text;
  a int; b int; c int; d int; e int;
begin
  insert into agent_runs(agent,started_at) values('smoke',now()) returning id into v_run;
  select split_part(coalesce(value,'management@quotesdone.com'),',',1) into v_owner from app_secrets where key='admin_emails';

  select count(*) into a from quotes q where q.status='revealed' and not exists(select 1 from transactions t where t.quote_id=q.id);
  if a>0 then v:=v||jsonb_build_object('check','revealed_quote_without_transaction','count',a); v_fail:=v_fail+1; end if;

  select count(*) into b from transactions where fee_status='paid' and coalesce(reveal_fee,0)<=0;
  if b>0 then v:=v||jsonb_build_object('check','paid_tx_zero_fee','count',b); v_fail:=v_fail+1; end if;

  -- 6 SEP 2026: EMAIL only. This counted the WhatsApp rows that wait on an unapproved Twilio template
  -- (the founder's input, not a broken write path) and paged him "data-integrity check failed" 20 times.
  -- 22 SEP 2026: 'sending' counts too — see the header. A claimed row whose sender never came back is
  -- the backlog this check exists to find, and it is the one shape it could not see.
  select count(*) into c from notifications where status in ('queued','sending') and channel='email' and created_at < now()-interval '2 hours';
  if c>0 then v:=v||jsonb_build_object('check','email_backlog_stuck','count',c); v_fail:=v_fail+1; end if;

  select count(*) into d from supplier_dues where coalesce(amount_due,0)<0 or amount_due is null;
  if d>0 then v:=v||jsonb_build_object('check','bad_due_amount','count',d); v_fail:=v_fail+1; end if;

  select count(*) into e from inquiries i where i.status='revealed' and not exists(select 1 from transactions t where t.inquiry_id=i.id);
  if e>0 then v:=v||jsonb_build_object('check','revealed_inquiry_without_tx','count',e); v_fail:=v_fail+1; end if;

  if v_fail>0 then
    insert into error_events(source,kind,severity,detail) values('smoke','integrity_violation','high',v);
    select coalesce(string_agg(x->>'check', ',' order by x->>'check'),'') into v_sig from jsonb_array_elements(v) x;
    if v_owner is not null and not exists(
         select 1 from notifications where type='smoke_alert'
           and created_at >= now() - interval '24 hours'
           and body like '%[sig:'||v_sig||']%') then
      insert into notifications(type,to_email,to_role,channel,subject,body)
        values('smoke_alert',v_owner,'admin','email','QuotesDone: data-integrity check failed',
          v_fail||' integrity check(s) failed: '||v::text||'. This usually means a recent change broke a write path. Open the IT agent. [sig:'||v_sig||']');
    end if;
  end if;
  update agent_runs set finished_at=now(),status='ok',counts=jsonb_build_object('checks',5,'failures',v_fail,'detail',v) where id=v_run;
  return jsonb_build_object('checks',5,'failures',v_fail,'detail',v);
end; $function$


CREATE OR REPLACE FUNCTION public.fn_spec_offer_answer(p_offer bigint, p_customer uuid, p_choice text, p_channel text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r public.spec_alternative_offer;
  v_alt jsonb;
  v_choice text := lower(btrim(coalesce(p_choice, '')));
begin
  if p_channel not in ('portal', 'whatsapp', 'email') then return jsonb_build_object('ok', false, 'error', 'bad_channel'); end if;
  select * into r from public.spec_alternative_offer where id = p_offer for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if r.customer_id is distinct from p_customer then return jsonb_build_object('ok', false, 'error', 'not_your_offer'); end if;
  if r.state <> 'open' then return jsonb_build_object('ok', false, 'error', 'not_open', 'state', r.state); end if;

  if v_choice in ('no', 'decline', 'declined') then
    update public.spec_alternative_offer set state = 'declined', closed_reason = 'no_exact_spec_declined', answered_at = now(),
           answer_channel = p_channel, updated_at = now() where id = r.id;
    perform public.fn_spec_offer_close_inquiry(r.inquiry_id, 'no_exact_spec_declined', r.id);
    return jsonb_build_object('ok', true, 'state', 'declined', 'offer_id', r.id, 'inquiry_id', r.inquiry_id, 'customer_id', r.customer_id, 'inquiry_closed', true);
  end if;

  select a into v_alt from jsonb_array_elements(r.alternatives) a where a->>'option_id' = v_choice limit 1;
  if v_alt is null then return jsonb_build_object('ok', false, 'error', 'unknown_option'); end if;
  update public.spec_alternative_offer set state = 'accepted', accepted_option = v_alt->>'option_id', accepted_value = v_alt->>'value',
         answered_at = now(), answer_channel = p_channel, updated_at = now() where id = r.id;
  update public.inquiries
     set accepted_alternatives = coalesce(accepted_alternatives, '[]'::jsonb) || jsonb_build_array(jsonb_build_object(
           'offer_id', r.id, 'line_no', r.line_no, 'attr', r.attr, 'requested', r.requested,
           'accepted', v_alt->>'value', 'option_id', v_alt->>'option_id', 'at', now(), 'channel', p_channel))
   where id = r.inquiry_id;
  return jsonb_build_object('ok', true, 'state', 'accepted', 'offer_id', r.id, 'inquiry_id', r.inquiry_id, 'customer_id', r.customer_id,
    'accepted_value', v_alt->>'value', 'still_open', (select count(*) from public.spec_alternative_offer where inquiry_id = r.inquiry_id and state = 'open'));
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_spec_offer_candidates(p_limit integer DEFAULT 20)
 RETURNS TABLE(inquiry_id uuid, customer_id uuid, why text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with pol as (select coalesce((select (value #>> '{}')::numeric from public.decision_policy where key = 'spec_offer_quote_window_days'), 7) as days,
                      coalesce((select (value #>> '{}')::int from public.decision_policy where key = 'spec_offer_max_attempts'), 5) as max_attempts),
  inv as (
    select m.inquiry_id, count(distinct m.supplier_id) as invited, min(m.sent_at) as first_sent
      from public.inquiry_matches m group by m.inquiry_id),
  quoted as (
    select q.inquiry_id, count(distinct q.supplier_id) as quoted
      from public.quotes q where coalesce(q.status, '') <> 'draft' group by q.inquiry_id)
  select i.id, i.customer_id,
         case when coalesce(qd.quoted, 0) >= inv.invited then 'every_invited_supplier_quoted' else 'quote_window_closed' end
    from public.inquiries i
    join inv on inv.inquiry_id = i.id
    left join quoted qd on qd.inquiry_id = i.id
   where i.spec_offer_checked_at is null
     -- THE BACKOFF (22 Sep 2026): a failed check waits for its next attempt, and stops after the last one.
     and i.spec_offer_attempts < (select max_attempts from pol)
     and (i.spec_offer_next_attempt_at is null or i.spec_offer_next_attempt_at <= now())
     and coalesce(i.status, '') not in ('closed', 'completed', 'cancelled')
     and i.parent_inquiry_id is null
     -- THE TIMING GUARD (review of #652): at least one live (non-draft) quote.
     and exists (select 1 from public.quotes q1 where q1.inquiry_id = i.id and coalesce(q1.status, '') <> 'draft')
     and not exists (select 1 from public.transactions t join public.quotes q2 on q2.id = t.quote_id where q2.inquiry_id = i.id)
     and (coalesce(qd.quoted, 0) >= inv.invited or now() >= inv.first_sent + make_interval(days => (select days from pol)::int))
   order by i.created_at
   limit greatest(1, least(p_limit, 100));
$function$


CREATE OR REPLACE FUNCTION public.fn_spec_offer_close_inquiry(p_inquiry uuid, p_reason text, p_except bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if p_reason not in ('no_exact_spec_declined', 'no_exact_spec_no_reply') then raise exception 'spec offer: bad close reason %', p_reason; end if;
  update public.spec_alternative_offer set state = 'superseded', updated_at = now()
   where inquiry_id = p_inquiry and state = 'open' and id <> p_except;
  -- Nothing was revealed (a candidate never has a transaction), so nothing is charged.
  update public.inquiries set status = 'closed', lost_reason = p_reason, stage_changed_at = now() where id = p_inquiry;
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_spec_offer_due()
 RETURNS TABLE(offer_id bigint, action text, reminder_no integer, final boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with pol as (select coalesce((select value from public.decision_policy where key = 'spec_offer_reminder_after_hours'), '[24,48]'::jsonb) as hrs)
  select o.id,
         case when now() >= o.reply_by and o.reminders_sent >= jsonb_array_length((select hrs from pol)) then 'close_no_reply' else 'remind' end,
         o.reminders_sent + 1,
         o.reminders_sent + 1 = jsonb_array_length((select hrs from pol))
    from public.spec_alternative_offer o
   where o.state = 'open' and o.last_sent_at is not null
     and (
       (o.reminders_sent < jsonb_array_length((select hrs from pol))
        and now() >= o.opened_at + make_interval(secs => ((select hrs from pol) ->> o.reminders_sent)::numeric::int * 3600))
       or (now() >= o.reply_by and o.reminders_sent >= jsonb_array_length((select hrs from pol))))
   order by o.opened_at;
$function$


CREATE OR REPLACE FUNCTION public.fn_spec_offer_failed(p_inquiry uuid, p_error text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_max int := coalesce((select (value #>> '{}')::int from public.decision_policy where key = 'spec_offer_max_attempts'), 5);
  v_n int; v_next timestamptz;
begin
  update public.inquiries
     set spec_offer_attempts = spec_offer_attempts + 1,
         spec_offer_next_attempt_at = now() + make_interval(mins => (15 * power(2, least(spec_offer_attempts, 10)))::int)
   where id = p_inquiry
  returning spec_offer_attempts, spec_offer_next_attempt_at into v_n, v_next;
  if not found then return jsonb_build_object('ok', false, 'error', 'no_inquiry'); end if;
  if v_n >= v_max then
    perform public.fn_it_engineer_finding_upsert(
      'monitor:spec_offer_check_failed:' || p_inquiry,
      'The no-exact-spec check failed ' || v_n || ' times on inquiry ' || p_inquiry || ' and has stopped retrying',
      'sales_engineer spec_offer_sweep -> quote_compare (technical_only)', 'agent_facing', 1,
      jsonb_build_object('inquiry_id', p_inquiry, 'attempts', v_n, 'last_error', left(coalesce(p_error, ''), 300),
                         'owner_seat', 'sales_engineer',
                         'fix', 'find why quote_compare fails for this inquiry, then reset inquiries.spec_offer_attempts to 0 so the sweep checks it once more'),
      '{}'::text[], array['why quote_compare fails for this inquiry'], 'sales_engineer');
  end if;
  return jsonb_build_object('ok', true, 'attempts', v_n, 'next_attempt_at', v_next, 'handed_to_seat', v_n >= v_max);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_spec_offer_mark(p_offer bigint, p_action text, p_notification_ids jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.spec_alternative_offer;
begin
  select * into r from public.spec_alternative_offer where id = p_offer for update;
  if not found then return jsonb_build_object('ok', false, 'error', 'not_found'); end if;
  if p_action = 'sent' then
    update public.spec_alternative_offer set last_sent_at = now(), notification_ids = notification_ids || coalesce(p_notification_ids, '[]'::jsonb), updated_at = now() where id = r.id;
  elsif p_action = 'remind' then
    if r.state <> 'open' then return jsonb_build_object('ok', false, 'error', 'not_open', 'state', r.state); end if;
    update public.spec_alternative_offer set reminders_sent = reminders_sent + 1, last_sent_at = now(),
           notification_ids = notification_ids || coalesce(p_notification_ids, '[]'::jsonb), updated_at = now() where id = r.id;
  elsif p_action = 'close_no_reply' then
    if r.state <> 'open' then return jsonb_build_object('ok', false, 'error', 'not_open', 'state', r.state); end if;
    update public.spec_alternative_offer set state = 'no_reply', closed_reason = 'no_exact_spec_no_reply',
           notification_ids = notification_ids || coalesce(p_notification_ids, '[]'::jsonb), updated_at = now() where id = r.id;
    perform public.fn_spec_offer_close_inquiry(r.inquiry_id, 'no_exact_spec_no_reply', r.id);
  elsif p_action = 'answered' then
    update public.spec_alternative_offer set notification_ids = notification_ids || coalesce(p_notification_ids, '[]'::jsonb), updated_at = now() where id = r.id;
  else
    return jsonb_build_object('ok', false, 'error', 'bad_action');
  end if;
  return jsonb_build_object('ok', true, 'offer_id', r.id, 'action', p_action);
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_spec_offer_open(p_inquiry uuid, p_offers jsonb)
 RETURNS SETOF spec_alternative_offer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_hours numeric := coalesce((select (value #>> '{}')::numeric from public.decision_policy where key = 'spec_offer_reply_window_hours'), 72);
  v_cust uuid;
  o jsonb;
begin
  select customer_id into v_cust from public.inquiries where id = p_inquiry for update;
  if not found then raise exception 'spec offer: no inquiry %', p_inquiry; end if;
  update public.inquiries set spec_offer_checked_at = coalesce(spec_offer_checked_at, now()) where id = p_inquiry;
  for o in select * from jsonb_array_elements(coalesce(p_offers, '[]'::jsonb)) loop
    insert into public.spec_alternative_offer (inquiry_id, customer_id, line_no, item, attr, label_en, label_ar, requested, alternatives, reply_by)
    values (p_inquiry, v_cust, (o->>'line_no')::int, o->>'item', o->>'attr', o->>'label_en', o->>'label_ar', o->>'requested', o->'alternatives',
            now() + make_interval(secs => (v_hours * 3600)::int))
    on conflict (inquiry_id, line_no, attr) where state in ('open', 'accepted') do nothing;
  end loop;
  return query select * from public.spec_alternative_offer where inquiry_id = p_inquiry and state = 'open' order by line_no, attr;
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_spec_offer_whatsapp_reply(p_phone text, p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_digits text := regexp_replace(coalesce(p_phone, ''), '\D', '', 'g');
  v_cust uuid;
  v_matches int;
  v_ref text;
  r public.spec_alternative_offer;
  v_t text := lower(btrim(translate(coalesce(p_text, ''), '٠١٢٣٤٥٦٧٨٩', '0123456789')));
  v_n int;
  v_choice text;
begin
  if length(v_digits) < 8 then return jsonb_build_object('handled', false, 'reason', 'no_phone'); end if;
  -- The text's SHAPE first: only something that looks like an answer (a no, an option number, a bare
  -- yes) goes any further. Otherwise a number two customers share would open a support case for
  -- every "hello" it sends.
  v_t := regexp_replace(v_t, '[[:space:][:punct:]]+$', '');
  if not (v_t ~ '^(no|no thanks|decline|لا|لأ|لا شكرا|لا شكرًا)$'
          or v_t ~ '^(option |choice |yes |نعم |الخيار )?[0-9]{1,2}$'
          or v_t ~ '^(yes|ok|نعم|موافق)$') then
    return jsonb_build_object('handled', false, 'reason', 'not_a_reply');
  end if;
  -- Who the sender is: fn_whatsapp_owner alone decides (a verified 'other' WhatsApp number or a verified
  -- 'same' mobile). p_all, so a number several customers share is still reported below, never guessed.
  select count(*), min(w.customer_id::text)::uuid into v_matches, v_cust
    from public.fn_whatsapp_owner(p_phone, true) as w
   where w.party_kind = 'customer'
     and exists (select 1 from public.spec_alternative_offer o where o.customer_id = w.customer_id and o.state = 'open');
  if v_matches = 0 then return jsonb_build_object('handled', false, 'reason', 'no_verified_customer_with_open_offer'); end if;
  if v_matches > 1 then
    v_ref := 'SE-SPECOFFER-AMBIG-' || right(v_digits, 9) || '-' || to_char(now(), 'YYYYMMDD');
    insert into public.support_case (case_ref, party_kind, party_id, subject, owner_role_id)
    values (v_ref, 'unknown', null,
            'From the sales engineer: a WhatsApp answer to a no-exact-spec offer came from a number that ' || v_matches ||
            ' verified customers with open offers share. Nothing was recorded. Confirm with the customer which request it is for, then record it from the portal.',
            'customer_support')
    on conflict (case_ref) do nothing;
    return jsonb_build_object('handled', false, 'reason', 'ambiguous_sender', 'case_ref', v_ref, 'matches', v_matches);
  end if;
  select * into r from public.spec_alternative_offer where customer_id = v_cust and state = 'open' order by opened_at, id limit 1;
  if not found then return jsonb_build_object('handled', false, 'reason', 'no_open_offer'); end if;
  v_t := regexp_replace(v_t, '[[:space:][:punct:]]+$', '');
  if v_t ~ '^(no|no thanks|decline|لا|لأ|لا شكرا|لا شكرًا)$' then v_choice := 'no';
  elsif v_t ~ '^(option |choice |yes |نعم |الخيار )?[0-9]{1,2}$' then
    v_n := (regexp_replace(v_t, '\D', '', 'g'))::int;
    if v_n < 1 or v_n > jsonb_array_length(r.alternatives) then return jsonb_build_object('handled', true, 'ok', false, 'error', 'unknown_option', 'offer_id', r.id, 'options', jsonb_array_length(r.alternatives)); end if;
    v_choice := r.alternatives -> (v_n - 1) ->> 'option_id';
  elsif v_t ~ '^(yes|ok|نعم|موافق)$' and jsonb_array_length(r.alternatives) = 1 then v_choice := r.alternatives -> 0 ->> 'option_id';
  else return jsonb_build_object('handled', false, 'reason', 'not_a_reply', 'offer_id', r.id);
  end if;
  return jsonb_build_object('handled', true) || public.fn_spec_offer_answer(r.id, v_cust, v_choice, 'whatsapp');
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_strategy_metrics()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare res jsonb;
begin
  with dem as (select category, count(*) rfqs from inquiries where created_at > now()-interval '90 days' and category is not null group by category),
  sup as (select i.category, count(distinct q.supplier_id) sups from quotes q join inquiries i on i.id=q.inquiry_id where q.created_at > now()-interval '90 days' and i.category is not null group by i.category)
  select jsonb_build_object(
    'under_supplied', (select coalesce(jsonb_agg(x order by x.rfqs desc),'[]'::jsonb) from (
        select d.category, d.rfqs, coalesce(s.sups,0) as active_suppliers
        from dem d left join sup s on s.category=d.category
        where coalesce(s.sups,0) < greatest(2, d.rfqs/3) order by d.rfqs desc limit 12) x),
    'coverage', jsonb_build_object(
        'categories_total', (select count(*) from category_specs),
        'with_requirements', (select count(*) from category_specs where supplier_requirements is not null),
        'with_playbook', (select count(distinct category) from qualification_playbooks where status='active'),
        'regulation_category_tags', (select count(distinct c) from regulations r, unnest(coalesce(r.categories,'{}')) c where r.status='active')),
    'funnel', (select coalesce(fn_marketplace_analytics(),'{}'::jsonb))
  ) into res;
  return res;
end $function$


CREATE OR REPLACE FUNCTION public.fn_stripe_event_seen(p_event_id text, p_type text, p_status text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  INSERT INTO public.stripe_events (event_id, type, payment_status)
  VALUES (p_event_id, p_type, p_status)
  ON CONFLICT (event_id) DO UPDATE
    SET last_seen_at = now(),
        delivery_count = public.stripe_events.delivery_count + 1;
$function$


CREATE OR REPLACE FUNCTION public.fn_subscription_billing_run(p_dry_run boolean DEFAULT false)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_flagged int := 0; v_cfg record;
begin
  select * into v_cfg from public.fn_supplier_subscription();
  for r in
    select b.* from public.v_supplier_billing b
     where b.billing_status in ('due', 'past_due')
       and coalesce(b.email, '') <> ''
       and not exists (select 1 from public.notifications n
                        where n.type = 'subscription_due' and n.lead_id = b.supplier_id
                          and n.created_at > now() - interval '30 days')
  loop
    if not p_dry_run then
      update public.leads set registration_fee_due = v_cfg.fee, registration_status = 'due' where id = r.supplier_id;
      perform public.fn_seat_handoff('accountant', 'sales_engineer', 'subscription.due', 'leads',
        r.supplier_id || ':' || to_char(current_date, 'YYYY-MM'),
        jsonb_build_object('supplier_id', r.supplier_id, 'fee', v_cfg.fee, 'currency', v_cfg.currency));
    end if;
    v_flagged := v_flagged + 1;
  end loop;

  if v_flagged > 0 and not p_dry_run then
    perform public.fn_seat_handoff('accountant', 'customer_support', 'delivery.request', 'founder',
      'subscription_billing_summary:' || current_date,
      jsonb_build_object('recipient_role', 'founder', 'kind', 'finance_reminder', 'level', 'info',
        'event', 'Supplier subscriptions invoiced',
        'detail', v_flagged || ' supplier(s) were invoiced ' || v_cfg.currency || ' ' || v_cfg.fee
                  || ' for their annual subscription. Founding suppliers (first ' || v_cfg.free_limit || ') are exempt and were not billed.',
        'dedupe_key', 'subscription_billing_summary:' || current_date));
  end if;

  return json_build_object('billing_starts', v_cfg.start_date, 'fee', v_cfg.fee, 'currency', v_cfg.currency,
    'free_limit', v_cfg.free_limit, 'invoiced', v_flagged, 'dry_run', p_dry_run, 'ran_at', now());
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_advisor(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with l as (select * from public.leads where id = p_lead_id),
  s as (select * from public.supplier_score where lead_id = p_lead_id),
  q as (
    select count(*)::int submitted,
           greatest(count(*) filter (where status = 'won')::int,
                    (select count(*)::int from public.inquiries where hired_supplier_id = p_lead_id)) won,
           count(*) filter (where status in ('rejected', 'lost', 'declined'))::int rejected
    from public.quotes where supplier_id = p_lead_id
  ),
  rr as (select coalesce((select rv_response_rate from l), (select response_rate from s)) rate),
  home as (select * from public.fn_supplier_document_home(p_lead_id)),
  cap as (select confirmed_at from public.supplier_capabilities where supplier_id = p_lead_id),
  live_inq as (
    select count(*) as n from public.inquiries i
    where coalesce(i.status, '') not in ('closed', 'cancelled', 'expired')
  ),
  gaps as (
    select g.* from (
      select 'trade_licence' as key, 'Upload your trade licence' as action, 'ارفع الرخصة التجارية' as action_ar,
             'You cannot be matched to any opportunity without a current trade licence.' as why,
             'لا يمكن مطابقتكم مع أي فرصة دون رخصة تجارية سارية.' as why_ar,
             'high' as severity, 'documents' as goes_to, 1 as sort
      where (select path from home where key = 'trade_licence') is null
      union all
      select 'licence_expired', 'Replace your expired trade licence', 'استبدل الرخصة التجارية المنتهية',
             'Your trade licence expired on ' || to_char(l.license_expiry, 'DD Mon YYYY') || '.',
             'انتهت صلاحية رخصتكم التجارية في ' || to_char(l.license_expiry, 'DD Mon YYYY') || '.',
             'high', 'documents', 2
      from l where (select path from home where key = 'trade_licence') is not null
                and l.license_expiry is not null and l.license_expiry < current_date
      union all
      select 'iso_certificate', 'Upload an ISO certificate', 'ارفع شهادة ISO',
             'Buyers filter on ISO 9001 and 14001. Adding one opens the projects that require it.',
             'يفرز العملاء المورّدين بحسب شهادتي ISO 9001 و14001، وإضافتها تتيح لكم المشاريع التي تشترطها.',
             'medium', 'documents', 3
      where (select path from home where key = 'iso') is null
      union all
      select 'iso_expired', 'Renew your ISO certificate', 'جدّد شهادة ISO',
             'Your ISO certificate expired on ' || to_char((select expiry from home where key = 'iso'), 'DD Mon YYYY') || '.',
             'انتهت صلاحية شهادة ISO في ' || to_char((select expiry from home where key = 'iso'), 'DD Mon YYYY') || '.',
             'high', 'documents', 4
      where (select expiry from home where key = 'iso') < current_date
      union all
      select 'not_verified', 'Complete verification', 'أكمل التحقق',
             'Unverified suppliers are excluded from matching entirely.',
             'لا يدخل المطابقة إلا المورّدون الموثَّقون.',
             'high', 'profile', 5
      from l where not coalesce(l.verified, false)
      union all
      -- The gate matching actually opens on (fn_match_capability: confirmed_at), pointed at the tab
      -- where it is confirmed. This replaced a "capability summary" gap that named a machine-filled
      -- column the supplier has no field for (audit 21 Sep 2026, finding 20).
      select 'services_unconfirmed', 'Confirm your services', 'أكّد الخدمات المقدَّمة',
             'Requests are matched on the services you confirm. Nothing reaches you until they are confirmed.',
             'تُطابَق الطلبات مع الخدمات التي تؤكّدونها، ولن يصلكم أي طلب قبل تأكيدها.',
             'high', 'services', 6
      where (select confirmed_at from cap) is null
      union all
      select 'no_products', 'Upload a product catalogue', 'ارفع كتالوج المنتجات',
             'Your catalogue is what buyers search. Without it you compete on company name alone.',
             'يبحث العملاء في الكتالوج، ومن دونه تنافسون باسم الشركة وحده.',
             'medium', 'products', 7
      from l where not exists (select 1 from public.supplier_product sp where sp.supplier_id = l.id)
      union all
      select 'no_service_area', 'Set the emirates you serve', 'حدّد الإمارات التي تغطيها',
             'Opportunities are filtered by location before anything else is considered.',
             'تُفرز الفرص بحسب الموقع قبل أي اعتبار آخر.',
             'medium', 'profile', 8
      from l where coalesce(array_length(l.service_emirates, 1), 0) = 0
      union all
      select 'slow_response', 'Improve your response time', 'حسّن سرعة الاستجابة',
             'Your response rate is ' || round((select rate from rr))::text || '%. Buyers see it, and it is 55% of your reliability score.',
             'معدل استجابتكم ' || round((select rate from rr))::text || '%، وهو ظاهر للعملاء ويشكّل 55% من تقييم موثوقيتكم.',
             'medium', 'twin', 9
      where (select rate from rr) is not null and (select rate from rr) < 60
    ) g
  )
  select jsonb_build_object(
    'lead_id', p_lead_id,
    'loss_analysis', jsonb_build_object(
      'quotes_submitted', (select submitted from q),
      'quotes_won',       (select won from q),
      'rejections',       (select rejected from q),
      'response_rate',    (select rate from rr),
      'loss_reasons', case
        when (select submitted from q) = 0 then '[]'::jsonb
        else jsonb_build_array(
          jsonb_build_object('reason', 'Rejected after quoting', 'reason_ar', 'رُفض بعد التسعير', 'count', (select rejected from q),
            'pct', round(100.0 * (select rejected from q) / nullif((select submitted from q), 0)))
        ) end,
      'basis', case when (select submitted from q) = 0 then 'no_completed_opportunities' else 'quotes_submitted' end
    ),
    'recommendations', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'key', g.key, 'action', g.action, 'action_ar', g.action_ar, 'why', g.why, 'why_ar', g.why_ar,
        'severity', g.severity, 'goes_to', g.goes_to,
        'impact_rfqs', (select n from live_inq)
      ) order by g.sort), '[]'::jsonb) from gaps g
    ),
    'gap_count', (select count(*) from gaps),
    'impact_basis', jsonb_build_object(
      'live_inquiries', (select n from live_inq),
      'note', 'impact_rfqs counts live inquiries a closed gap would let this supplier compete for'
    ),
    'headline', (
      select case
        when (select count(*) from gaps) = 0
          then 'Your profile is complete. You are eligible for every opportunity we can match.'
        when (select n from live_inq) = 0
          then 'You have ' || (select count(*) from gaps)::text
               || ' gap(s) blocking you from being matched at all. Start with: '
               || (select g.action from gaps g order by g.sort limit 1)
               || '. There are no live opportunities right now, so there is time to fix them.'
        else 'Your profile can qualify for ' || (select n from live_inq)::text
             || ' more opportunities if you close ' || (select count(*) from gaps)::text
             || ' gap(s), starting with: ' || (select g.action from gaps g order by g.sort limit 1) || '.'
      end
    ),
    'headline_ar', (
      select case
        when (select count(*) from gaps) = 0
          then 'ملفكم مكتمل، وأنتم مؤهَّلون لكل فرصة يمكننا مطابقتها.'
        when (select n from live_inq) = 0
          then 'عدد النواقص التي تحول دون مطابقتكم: ' || (select count(*) from gaps)::text
               || '. الخطوة الأولى: '
               || (select g.action_ar from gaps g order by g.sort limit 1)
               || '. لا توجد فرص مفتوحة حاليًا، فأمامكم متسع من الوقت لاستكمالها.'
        else 'يمكن أن يتأهّل ملفكم لعدد ' || (select n from live_inq)::text
             || ' من الفرص الإضافية إذا استكملتم النواقص (' || (select count(*) from gaps)::text
             || '). الخطوة الأولى: ' || (select g.action_ar from gaps g order by g.sort limit 1) || '.'
      end
    )
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_agreement_version_no(p_version text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select nullif(regexp_replace(coalesce(p_version, ''), '[^0-9]', '', 'g'), '')::int
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_apply_change(p_phone text, p_field text, p_value text, p_inbound text, p_quote_id uuid DEFAULT NULL::uuid, p_channel text DEFAULT 'whatsapp'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_lead bigint; v_num numeric; v_q record; v_n int; v_refusal text; v_old numeric; v_list text;
        v_company text;
begin
  -- SCOPE FIRST, AND FROM THE PHONE. Nothing downstream takes a supplier id from the caller.
  v_lead := public.fn_wa_lead_id(p_phone);
  if v_lead is null then
    insert into public.channel_directive(actor_type, actor_phone, channel, inbound, field, applied, refusal)
    values ('supplier', p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, false, 'no supplier account matches this number');
    return jsonb_build_object('ok', false, 'refusal',
      'This number is not linked to a supplier account, so there is nothing of yours I can change. Sign in at https://quotesdone.com/suppliers.');
  end if;
  select company_name into v_company from public.leads where id = v_lead;

  if not exists (select 1 from public.fn_supplier_changeable() c where c.field = p_field) then
    v_refusal := 'I cannot change "' || coalesce(p_field,'(nothing)') || '" from a message. What I can change this way: '
              || (select string_agg(c.field, ', ' order by c.field) from public.fn_supplier_changeable() c)
              || '. Everything else — your licence, your company details, and generating a new quotation — is in the portal.';
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal);
  end if;

  begin v_num := p_value::numeric; exception when others then v_num := null; end;
  if v_num is null or v_num <= 0 then
    v_refusal := '"' || coalesce(p_value,'') || '" is not an amount I can put on a quotation.';
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal);
  end if;

  -- WHICH QUOTATION. Editable means: theirs, still open, nobody has paid to reveal them, not
  -- committed, not already accepted. Each of those is a different reason and each gets said.
  select count(*) into v_n
    from public.quotes q
    join public.inquiries i on i.id = q.inquiry_id
   where q.supplier_id = v_lead
     and (p_quote_id is null or q.id = p_quote_id)
     and q.committed_at is null
     and coalesce(q.status,'') not in ('accepted','withdrawn','expired')
     and coalesce(i.status,'') not in ('concluded','closed','cancelled','awarded')
     and not exists (select 1 from public.transactions t
                      where t.inquiry_id = q.inquiry_id and t.supplier_id = q.supplier_id
                        and t.revealed_at is not null);

  if v_n = 0 then
    -- Say WHY there is nothing to change rather than "no quotation found", which is true of a
    -- supplier who has never quoted and of one whose customer paid an hour ago.
    select string_agg(distinct r, '; ') into v_refusal from (
      select case
               when q.committed_at is not null then 'one is committed and cannot be re-priced'
               when coalesce(q.status,'') = 'accepted' then 'one has already been accepted'
               when exists (select 1 from public.transactions t where t.inquiry_id = q.inquiry_id
                             and t.supplier_id = q.supplier_id and t.revealed_at is not null)
                 then 'the customer has already paid to reveal you on one, so the price they paid to see stands'
               else 'the request is closed on one' end as r
        from public.quotes q where q.supplier_id = v_lead
         and (p_quote_id is null or q.id = p_quote_id)) z;
    v_refusal := coalesce('I cannot change a price right now: ' || v_refusal || '.',
                          'You have no open quotation for me to re-price. You can send a new one from the portal.');
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal);
  end if;

  if v_n > 1 then
    select string_agg(i.category || ' in ' || coalesce(i.emirate,'the UAE') || ' (currently AED ' || q.quote_amount || ')', '; ' order by q.created_at desc)
      into v_list
      from public.quotes q join public.inquiries i on i.id = q.inquiry_id
     where q.supplier_id = v_lead and q.committed_at is null
       and coalesce(q.status,'') not in ('accepted','withdrawn','expired');
    v_refusal := 'You have ' || v_n || ' open quotations, so I will not guess which one you mean: ' || v_list
              || '. Tell me which, or change it in the portal.';
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal, 'open_quotes', v_n);
  end if;

  select q.* into v_q
    from public.quotes q join public.inquiries i on i.id = q.inquiry_id
   where q.supplier_id = v_lead
     and (p_quote_id is null or q.id = p_quote_id)
     and q.committed_at is null
     and coalesce(q.status,'') not in ('accepted','withdrawn','expired')
     and coalesce(i.status,'') not in ('concluded','closed','cancelled','awarded')
     and not exists (select 1 from public.transactions t
                      where t.inquiry_id = q.inquiry_id and t.supplier_id = q.supplier_id
                        and t.revealed_at is not null);
  v_old := v_q.quote_amount;

  -- THE FAT-FINGER BOUND. A supplier may price their own work at whatever they like — that is
  -- their commercial decision and not ours. But this arrives as a sentence typed on a phone, where
  -- a missing or extra zero is one keystroke, and a quotation is a number a customer will compare
  -- against others and pay to unlock. Beyond half up or half down, the portal asks for it twice.
  if v_old is not null and v_old > 0 and (v_num > v_old * 1.5 or v_num < v_old * 0.5) then
    v_refusal := 'That would move the price from AED ' || v_old || ' to AED ' || v_num
              || ', which is more than half up or down. I have not changed it — if you do mean that, please set it in the portal so you can see the whole quotation while you do.';
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, target_id, old_value, new_value, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, v_q.id::text, v_old::text, v_num::text, false, v_refusal);
    return jsonb_build_object('ok', false, 'refusal', v_refusal, 'old', v_old, 'asked', v_num);
  end if;

  if v_old is not distinct from v_num then
    insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, target_id, old_value, new_value, applied, refusal)
    values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, v_q.id::text, v_old::text, v_num::text, false, 'already at that value');
    return jsonb_build_object('ok', true, 'unchanged', true, 'old', v_old, 'new', v_num,
      'message', 'Your quotation is already AED ' || v_num || '. Nothing to change.');
  end if;

  update public.quotes set quote_amount = v_num where id = v_q.id;

  insert into public.channel_directive(actor_type, actor_id, actor_phone, channel, inbound, field, target_id, old_value, new_value, applied)
  values ('supplier', v_lead, p_phone, p_channel, left(coalesce(p_inbound,''),2000), p_field, v_q.id::text, v_old::text, v_num::text, true);

  insert into public.agent_runs(agent, status, counts, note, started_at, finished_at)
  values ('supplier_directive', 'ok',
          jsonb_build_object('lead_id', v_lead, 'quote_id', v_q.id, 'old', v_old, 'new', v_num, 'channel', p_channel),
          coalesce(v_company,'lead ' || v_lead) || ' changed a quotation from AED ' || coalesce(v_old::text,'(unset)')
          || ' to AED ' || v_num || ' by ' || p_channel || '. Instruction: ' || left(coalesce(p_inbound,''),200),
          now(), now());

  return jsonb_build_object('ok', true, 'quote_id', v_q.id, 'old', v_old, 'new', v_num,
    'message', 'Done — your quotation is now AED ' || v_num || ' (it was AED ' || coalesce(v_old::text,'unset') || '). The customer sees the new price from now on.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_certifications(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with docs(key, label, label_ar, impact, impact_why, impact_why_ar) as (values
      ('trade_licence',     'Trade licence',              'الرخصة التجارية',           'critical', 'Approval is impossible without it — the licence gate refuses every profile that has none.', 'لا يُعتمد أي حساب من دونها، ويُرفض كل ملف لا يتضمنها.'),
      ('insurance',         'Insurance',                  'التأمين',                   'high',     'Many customers will not award work to an uninsured supplier.', 'كثير من العملاء لا يُرسون الأعمال على مورّد غير مؤمَّن عليه.'),
      ('iso',               'ISO certification',          'شهادة ISO',                 'medium',   'Strengthens your capability score and unlocks quality-gated requests.', 'تعزّز تقييم قدراتكم وتتيح لكم الطلبات المشروطة بمعايير الجودة.'),
      ('manufacturer_auth', 'Manufacturer authorisation', 'تفويض الشركة المصنّعة',     'medium',   'Proves you are authorised for the brands you carry.', 'تُثبت اعتمادكم لدى العلامات التجارية التي تورّدونها.'),
      ('establishment',     'Establishment card (EGR)',   'بطاقة المنشأة (EGR)',       'low',      'Administrative record. Does not gate work.', 'مستند إداري لا يؤثر في استلام الأعمال.')
  ),
  held as (
    select d.*, h.path, h.expiry, h.source
    from docs d left join public.fn_supplier_document_home(p_lead_id) h on h.key = d.key
  )
  select jsonb_build_object(
    'lead_id', p_lead_id,
    'certifications', coalesce((select jsonb_agg(jsonb_build_object(
        'key', h.key, 'label', h.label, 'label_ar', h.label_ar,
        'held', h.path is not null,
        'source', h.source,
        'expiry', h.expiry,
        'days_left', case when h.expiry is null then null else (h.expiry - current_date) end,
        'document_status', case
          when h.path is null then 'missing'
          when h.expiry is null then 'valid'
          when h.expiry < current_date then 'expired'
          when h.expiry < current_date + 60 then 'expiring'
          else 'valid' end,
        'impact_level', h.impact,
        'impact_why', h.impact_why, 'impact_why_ar', h.impact_why_ar)
      order by case h.impact when 'critical' then 0 when 'high' then 1 when 'medium' then 2 else 3 end, h.label)
      from held h), '[]'::jsonb),
    'impact_basis', 'impact_level is a stated QuotesDone policy about what each document gates — not a number derived from your history',
    'impact_basis_ar', 'يعكس مستوى الأثر سياسة QuotesDone المعلنة بشأن ما يتيحه كل مستند، وليس رقمًا مستخلصًا من سجلكم',
    'summary', jsonb_build_object(
      'held', (select count(*) from held where path is not null),
      'total', (select count(*) from held),
      'expired', (select count(*) from held where path is not null and expiry is not null and expiry < current_date),
      'expiring', (select count(*) from held where path is not null and expiry is not null
                     and expiry >= current_date and expiry < current_date + 60),
      'blocking_missing', (select count(*) from held where path is null and impact = 'critical'))
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_changeable()
 RETURNS TABLE(field text, kind text, description text)
 LANGUAGE sql
 STABLE
AS $function$
  select 'quote_price', 'number',
         'The amount on your open quotation. It can be changed while the customer has not paid to reveal you, the quotation is not committed, and the request is still open.';
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_collaboration_cooperated(p_lead bigint, p_quote uuid, p_hold bigint)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_prev int;
begin
  select consecutive_ignored into v_prev from public.supplier_collaboration where lead_id = p_lead for update;
  if coalesce(v_prev, 0) = 0 then return false; end if;
  update public.supplier_collaboration set consecutive_ignored = 0, updated_at = now() where lead_id = p_lead;
  insert into public.supplier_collaboration_event (lead_id, kind, quote_id, hold_id, consecutive_after, actor, detail)
  values (p_lead, 'cooperated', p_quote, p_hold, 0, 'sales_engineer', jsonb_build_object('reset_from', v_prev));
  return true;
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_collaboration_event_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  raise exception 'supplier_collaboration_event is append-only: a supplier''s collaboration history is kept whole (founder, 14 Sep 2026)';
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_collaboration_hold_lift(p_lead bigint, p_founder_instruction bigint, p_why text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare fi record; l record; v_text text; v_n int;
begin
  if coalesce(btrim(p_why), '') = '' then raise exception 'lifting a matching hold needs the reason the founder gave'; end if;
  select id, instruction, coalesce(subject, '') as subject, coalesce(note, '') as note into fi from public.founder_instruction where id = p_founder_instruction;
  if not found then raise exception 'no founder_instruction %: only the founder lifts a matching hold (#160)', p_founder_instruction; end if;
  select id, company_name, collaboration_hold_at, matching_block_reason into l from public.leads where id = p_lead;
  if not found then raise exception 'no supplier %', p_lead; end if;
  v_text := lower(fi.instruction || ' ' || fi.subject || ' ' || fi.note);
  if not (v_text ~ ('(^|[^0-9])' || p_lead::text || '([^0-9]|$)')
          or (length(btrim(coalesce(l.company_name, ''))) >= 3 and position(lower(btrim(l.company_name)) in v_text) > 0)) then
    raise exception 'founder_instruction % does not name supplier % (%): the founder''s instruction must name who is lifted', p_founder_instruction, p_lead, l.company_name;
  end if;
  if l.collaboration_hold_at is null then raise exception 'supplier % is not on a collaboration matching hold', p_lead; end if;

  perform set_config('app.collaboration_hold_lift', 'founder', true);
  update public.leads
     set collaboration_hold_at = null,
         matching_blocked = case when matching_block_reason = 'collaboration_hold' then false else matching_blocked end,
         matching_block_reason = case when matching_block_reason = 'collaboration_hold' then null else matching_block_reason end
   where id = p_lead;
  perform set_config('app.collaboration_hold_lift', '', true);

  update public.supplier_collaboration set consecutive_ignored = 0, lifted_at = now(), updated_at = now() where lead_id = p_lead;
  select coalesce(max(consecutive_ignored), 0) into v_n from public.supplier_collaboration where lead_id = p_lead;
  insert into public.supplier_collaboration_event (lead_id, kind, consecutive_after, founder_instruction_id, actor, detail)
  values (p_lead, 'hold_lifted', v_n, p_founder_instruction, 'founder',
          jsonb_build_object('why', p_why, 'executed_by', session_user, 'at', now()));
  perform public.fn_supplier_notice(p_lead, 'supplier_matching_hold_lifted',
    'Welcome back to QuotesDone',
    $en$Dear {company},

Thank you for speaking with us. We have resumed new requests to your company, and matching requests will start reaching you again. Whenever a quote needs more detail, you can complete it on your supplier portal in a few minutes.

We look forward to working with you.

With thanks,
QuotesDone sales engineer$en$,
    'مرحبًا بعودتكم إلى QuotesDone',
    $ar$السادة/ {company} المحترمين،
تحية طيبة وبعد،

نشكركم على تواصلكم معنا. وقد استأنفنا إرسال الطلبات الجديدة إلى شركتكم، وستصلكم الطلبات المطابقة مجددًا. وعندما يحتاج أي عرض إلى تفاصيل إضافية، يمكنكم استكمالها من بوابة المورّدين خلال دقائق.

نتطلع إلى العمل معكم.

وتفضلوا بقبول فائق الاحترام والتقدير،
مهندس المبيعات في QuotesDone$ar$);
  return jsonb_build_object('ok', true, 'lead_id', p_lead, 'founder_instruction', p_founder_instruction, 'consecutive_ignored', v_n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_collaboration_incident(p_lead bigint, p_inquiry uuid, p_quote uuid, p_hold bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_n int; v_held timestamptz; v_warn int := 0; v_hold int := 0;
        v_ref text := upper(left(coalesce(p_inquiry::text, ''), 8));
begin
  insert into public.supplier_collaboration (lead_id) values (p_lead) on conflict (lead_id) do nothing;
  update public.supplier_collaboration
     set consecutive_ignored = consecutive_ignored + 1, total_ignored = total_ignored + 1, last_incident_at = now(), updated_at = now()
   where lead_id = p_lead returning consecutive_ignored into v_n;
  insert into public.supplier_collaboration_event (lead_id, kind, inquiry_id, quote_id, hold_id, consecutive_after, actor, detail)
  values (p_lead, 'ignored_hold', p_inquiry, p_quote, p_hold, v_n, 'sales_engineer', jsonb_build_object('rfq', v_ref));

  if v_n = 2 then
    insert into public.support_case (case_ref, party_kind, party_id, inquiry_ref, subject, owner_role_id)
    values ('SE-COLLAB-' || p_lead || '-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS'), 'supplier', p_lead::text, p_inquiry::text,
            'From the sales engineer: this supplier has left 2 held quotes unanswered in a row (the customer decided before the missing details came). The warning was sent on email and WhatsApp; a third in a row puts them on matching hold.',
            'customer_support');
    v_warn := public.fn_supplier_notice(p_lead, 'supplier_collaboration_warning',
      'A note about your recent quotes on QuotesDone',
      $en$Dear {company},

Thank you for quoting on QuotesDone. We value the time you put into every request.

On your last two requests, your quotation was placed on hold because some details the customer needs to compare quotes fairly were missing (for example the exact material specification, the delivery date, installation or warranty), and the customer made their decision before those details arrived. Complete details help customers choose with confidence, and they give your offer the best chance of being selected.

Whenever a quote is on hold, you can fill in the missing details directly on your supplier portal (we then prepare the standardised quotation for your approval), or upload a revised quotation. It only takes a few minutes.

To keep matching fair for customers, if a third consecutive quotation is still on hold when the customer decides, we will pause new requests to your company until we have spoken with you. We would much rather keep working together, so please reach out if anything is making it difficult to respond.

With thanks,
QuotesDone sales engineer$en$,
      'ملاحظة بشأن عروضكم الأخيرة على QuotesDone',
      $ar$السادة/ {company} المحترمين،
تحية طيبة وبعد،

نشكركم على تقديم عروض الأسعار عبر QuotesDone، ونقدّر الوقت الذي تخصصونه لكل طلب.

في آخر طلبين، عُلّق عرضكم لنقص بعض التفاصيل التي يحتاجها العميل ليقارن العروض بإنصاف (مثل المواصفات الدقيقة للمواد أو موعد التسليم أو التركيب أو الضمان)، واتخذ العميل قراره قبل وصول هذه التفاصيل. فاكتمال التفاصيل يساعد العملاء على الاختيار بثقة، ويمنح عرضكم أفضل فرصة للفوز.

وعند تعليق أي عرض، يمكنكم استكمال التفاصيل الناقصة مباشرة من بوابة المورّدين (ونُعدّ لكم العرض بالصيغة الموحّدة لاعتماده)، أو رفع عرض معدّل، ولا يستغرق ذلك سوى دقائق.

وحرصًا على عدالة المطابقة للعملاء، إذا بقي عرض ثالث على التوالي معلّقًا عند اتخاذ العميل قراره، فسنوقف مؤقتًا إرسال الطلبات الجديدة إلى شركتكم إلى حين التحدث معكم. ونحرص كثيرًا على استمرار تعاوننا، فلا تترددوا في التواصل معنا إن كان هناك ما يصعّب عليكم الرد.

وتفضلوا بقبول فائق الاحترام والتقدير،
مهندس المبيعات في QuotesDone$ar$,
      p_inquiry, p_quote);
    update public.supplier_collaboration set warned_at = now(), updated_at = now() where lead_id = p_lead;
    insert into public.supplier_collaboration_event (lead_id, kind, inquiry_id, quote_id, hold_id, consecutive_after, actor, detail)
    values (p_lead, 'warning_sent', p_inquiry, p_quote, p_hold, v_n, 'sales_engineer', jsonb_build_object('delivery_requests', v_warn));

  elsif v_n >= 3 then
    select collaboration_hold_at into v_held from public.leads where id = p_lead;
    if v_held is null then
      update public.leads set collaboration_hold_at = now(), matching_blocked = true, matching_block_reason = 'collaboration_hold' where id = p_lead;
      update public.supplier_collaboration set held_at = now(), updated_at = now() where lead_id = p_lead;
      insert into public.support_case (case_ref, party_kind, party_id, inquiry_ref, subject, owner_role_id)
      values ('SE-HOLD-' || p_lead || '-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSMS'), 'supplier', p_lead::text, p_inquiry::text,
              'From the sales engineer: supplier put on matching hold after 3 held quotes in a row were left unanswered. New requests are no longer matched to them. Lifting it is the founder''s decision after he calls the supplier (founder_instruction #160).',
              'customer_support');
      v_hold := public.fn_supplier_notice(p_lead, 'supplier_matching_hold',
        'New requests to your company are paused on QuotesDone',
        $en$Dear {company},

Thank you for your time on QuotesDone. On your last three consecutive requests, your quotation was still on hold for missing details when the customer made their decision. As we mentioned in our earlier message, we have therefore paused new requests to your company for now. Your account, your existing quotations and any revealed jobs are not affected.

Our team will be in touch to understand what happened and how we can make responding easier. You are welcome to reply to this message at any time.

With thanks,
QuotesDone sales engineer$en$,
        'إيقاف مؤقت لإرسال الطلبات الجديدة إلى شركتكم على QuotesDone',
        $ar$السادة/ {company} المحترمين،
تحية طيبة وبعد،

نشكركم على وقتكم في QuotesDone. في آخر ثلاثة طلبات متتالية، كان عرضكم لا يزال معلّقًا لنقص في التفاصيل عندما اتخذ العميل قراره؛ لذلك، وكما أشرنا في رسالتنا السابقة، أوقفنا مؤقتًا إرسال الطلبات الجديدة إلى شركتكم. ولا يتأثر بذلك حسابكم ولا عروضكم الحالية ولا الأعمال التي كُشف عنها.

سيتواصل معكم فريقنا للوقوف على ما حدث وبحث سبل تيسير ردّكم على الطلبات، ويسعدنا أن تردّوا على هذه الرسالة في أي وقت.

وتفضلوا بقبول فائق الاحترام والتقدير،
مهندس المبيعات في QuotesDone$ar$,
        p_inquiry, p_quote);
      insert into public.supplier_collaboration_event (lead_id, kind, inquiry_id, quote_id, hold_id, consecutive_after, actor, detail)
      values (p_lead, 'matching_hold', p_inquiry, p_quote, p_hold, v_n, 'sales_engineer', jsonb_build_object('delivery_requests', v_hold));
    end if;
  end if;
  return jsonb_build_object('lead_id', p_lead, 'consecutive', v_n, 'warning_requests', v_warn, 'hold_requests', v_hold);
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_document_home(p_lead_id bigint)
 RETURNS TABLE(key text, path text, name text, expiry date, source text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with me as (select * from public.leads where id = p_lead_id),
  -- A live supporting document whose LABEL names the subject. The label is the supplier's own
  -- words for the file ("ISO 9001:2015", "شهادة الأيزو", "Public liability insurance").
  supp as (
    select d.path, d.file_name, d.created_at,
           case
             when d.file_name ~* '(^|[^a-z])iso([^a-z]|$)|أيزو|ايزو|آيزو' then 'iso'
             when d.file_name ~* 'insurance|liability|all[- ]?risk|تأمين|تامين' then 'insurance'
             when d.file_name ~* 'manufacturer|authori[sz]|dealer|distributor|agency letter|وكالة|تفويض|توزيع' then 'manufacturer_auth'
           end as subject
    from public.documents d
    where d.ref_table = 'supplier_supporting' and d.ref_id = p_lead_id::text
      and coalesce(d.status, '') <> 'withdrawn'
  ),
  best as (
    select distinct on (subject) subject, path, file_name from supp
    where subject is not null order by subject, created_at desc
  ),
  fixed(key, path, name, expiry) as (
    select 'trade_licence',     (select license_doc_path from me),           (select license_doc_name from me), (select license_expiry from me)::date
    union all select 'company_profile',   (select company_profile_doc_path from me),   null, null::date
    union all select 'insurance',         (select insurance_doc_path from me),         null, (select insurance_expiry from me)::date
    union all select 'iso',               (select iso_doc_path from me),               null, (select iso_expiry from me)::date
    union all select 'manufacturer_auth', (select manufacturer_auth_doc_path from me), null, (select manufacturer_auth_expiry from me)::date
    union all select 'establishment',     (select egr_doc_path from me),               (select egr_doc_name from me), null::date
  )
  select f.key,
         coalesce(f.path, b.path)                                  as path,
         coalesce(f.name, case when f.path is null then b.file_name end, regexp_replace(coalesce(f.path, b.path, ''), '^.*/', '')) as name,
         case when f.path is not null then f.expiry end            as expiry,
         case when f.path is not null then 'leads' when b.path is not null then 'supporting' end as source
  from fixed f left join best b on b.subject = f.key;
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_document_impact(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with me as (select * from public.leads where id = p_lead_id),
  flag as (select coalesce((select source from me), '') = 'qd_demo_fixture' as is_demo),
  mine as (select coalesce(sc.trades, '{}'::text[]) trades from public.supplier_capabilities sc where sc.supplier_id = p_lead_id),
  reachable as (
    select count(*) n from public.inquiries i, me, flag
    where i.status = 'open'
      and ((me.sector is not null and i.category = me.sector)
           or exists (select 1 from mine where i.trades && mine.trades))
      and (coalesce(i.brief_source, '') = 'qd_demo_fixture') = flag.is_demo
  ),
  priced as (
    select count(distinct q.inquiry_id) n from public.quotes q, flag
    where q.supplier_id = p_lead_id
      and (coalesce(q.source, '') = 'qd_demo_fixture') = flag.is_demo
  ),
  docs as (
    select h.key, case h.key when 'trade_licence' then 'Trade licence' when 'iso' then 'ISO certification'
                             when 'insurance' then 'Insurance' when 'manufacturer_auth' then 'Manufacturer authorisation'
                             when 'company_profile' then 'Company profile' end as label,
           h.path, h.expiry, h.source, h.key = 'trade_licence' as gates_matching
    from public.fn_supplier_document_home(p_lead_id) h
    where h.key in ('trade_licence', 'iso', 'insurance', 'manufacturer_auth', 'company_profile')
  ),
  scored as (
    select d.key, d.label, d.gates_matching, d.source,
           d.path is not null as on_file,
           d.expiry,
           coalesce(d.expiry < current_date, false) as expired,
           (d.path is not null and not coalesce(d.expiry < current_date, false)) as effective
    from docs d
  )
  select jsonb_build_object(
    'lead_id', p_lead_id,
    'open_in_my_trade', (select n from reachable),
    'basis', 'open enquiries in your trade, and the enquiries you have already priced',
    'documents', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'key', s.key, 'label', s.label, 'on_file', s.on_file, 'source', s.source,
        'expiry', s.expiry, 'expired', s.expired,
        'unlocked', case when s.effective then (select n from priced) else 0 end,
        'would_unlock', case when s.effective then 0 when s.gates_matching then (select n from reachable) else 0 end,
        'note', case
          when s.effective then 'On file and in force.'
          when s.expired and s.gates_matching then 'Expired. Renewing it reopens every open enquiry in your trade.'
          when s.expired then 'Expired. Customers see this as a gap when comparing you.'
          when s.gates_matching then 'Missing. It is the document that decides whether you can be matched at all.'
          else 'Missing. It is optional, but it is what a customer looks for when comparing two similar quotes.'
          end
      ) order by s.gates_matching desc, s.key), '[]'::jsonb)
      from scored s)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_due_is_owed(p_status text, p_paid_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select p_paid_at is null
     and coalesce(p_status, '') not in ('paid', 'settled', 'waived', 'cancelled', 'reversed', 'void')
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_dues_accrue_interest(p_as_of date DEFAULT NULL::date)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare x record; v jsonb; n int := 0;
begin
  for x in select id, transaction_id from public.supplier_dues
            where public.fn_supplier_due_is_owed(status, paid_at) and transaction_id is not null loop
    v := public.fn_accountant_nonresponse_charge(x.transaction_id, p_as_of);
    continue when not coalesce((v->>'ok')::boolean, false);
    update public.supplier_dues
       set interest_amount = (v->>'interest_aed')::numeric, total_claim = amount_due + coalesce(admin_fee, 0) + (v->>'interest_aed')::numeric
     where id = x.id
       and (interest_amount is distinct from (v->>'interest_aed')::numeric
            or total_claim is distinct from amount_due + coalesce(admin_fee, 0) + (v->>'interest_aed')::numeric);
    if found then n := n + 1; end if;
  end loop;
  return n;
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_exception_close(p_lead_id bigint, p_outcome text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  update public.leads
     set exception_closed_at = now(),
         exception_outcome = p_outcome,
         licence_gate_reason = case when p_outcome = 'resolved' then null else licence_gate_reason end
   where id = p_lead_id and exception_closed_at is null;
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_exception_days()
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  select greatest(1, coalesce((select nullif(btrim(value),'')::int from app_secrets where key='supplier_exception_days'), 14));
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_exception_open(p_lead_id bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_days int := public.fn_supplier_exception_days(); r public.leads;
begin
  select * into r from public.leads where id = p_lead_id;
  if not found then return jsonb_build_object('ok', false, 'error', 'lead_not_found'); end if;

  if r.exception_opened_at is not null and r.exception_closed_at is null then
    return jsonb_build_object('ok', true, 'reopened', false, 'due_at', r.exception_due_at,
                              'note', 'already open - the clock does not restart on a repeat failure');
  end if;

  update public.leads
     set exception_opened_at = now(),
         exception_due_at = now() + make_interval(days => v_days),
         exception_reminders = 0, exception_last_reminder_at = null,
         exception_closed_at = null, exception_outcome = null,
         licence_gate_reason = coalesce(p_reason, licence_gate_reason)
   where id = p_lead_id;

  return jsonb_build_object('ok', true, 'reopened', true,
                            'due_at', now() + make_interval(days => v_days), 'days', v_days);
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_expiries(p_supplier_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with l as (select * from leads where id=p_supplier_id)
  select coalesce(jsonb_agg(e order by (e->>'days_left')::int), '[]'::jsonb) from (
    select jsonb_build_object('doc',d.label,'expiry',d.exp,
      'days_left',(d.exp - current_date),
      'status', case when d.exp < current_date then 'expired'
                     when d.exp <= current_date + 30 then 'expiring'
                     when d.exp <= current_date + 90 then 'soon' else 'ok' end) e
    from l, lateral (values
      ('Trade license', l.license_expiry),
      ('ISO certification', l.iso_expiry),
      ('Insurance', l.insurance_expiry),
      ('Manufacturer authorization', l.manufacturer_auth_expiry)
    ) as d(label,exp)
    where d.exp is not null
  ) q;
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_invite_candidates(p_limit integer)
 RETURNS TABLE(lead_id bigint, to_email text, company_name text, lang text, subject text, body text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_site text; v_target int;
  v_subj text; v_body text; v_subj_ar text; v_body_ar text;
begin
  select coalesce(nullif(btrim(value), ''), 'https://quotesdone.com') into v_site from app_secrets where key = 'public_site_url';
  v_site := coalesce(v_site, 'https://quotesdone.com');
  select value into v_subj    from app_secrets where key = 'invite_subject';
  select value into v_body    from app_secrets where key = 'invite_body';
  select value into v_subj_ar from app_secrets where key = 'invite_subject_ar';
  select value into v_body_ar from app_secrets where key = 'invite_body_ar';
  -- A template without the link placeholder is the 62-invitations-with-no-way-in failure. Refuse.
  if coalesce(v_body, '') not like '%{{link}}%' then
    raise exception 'app_secrets.invite_body has no {{link}} placeholder: an invitation with no way in is refused';
  end if;
  v_target := coalesce((select nullif(value,'')::int from app_secrets where key='invite_target_per_category'),
                       (select nullif(value,'')::int from app_secrets where key='invite_target_per_trade'), 10);

  -- MATERIALIZED, 4 Aug 2026, and it is load-bearing (see enqueue_supplier_invites' history): both
  -- CTEs are read from a correlated subquery and would otherwise be recomputed per candidate.
  return query
  with activated as materialized (
    select ls.domain_slug, count(distinct l.id) ct
    from leads l join lead_subcategory ls on ls.lead_id = l.id
    where coalesce(l.claimed,false) = true
    group by ls.domain_slug
  ),
  under as materialized (
    select d.slug as domain_slug, coalesce(a.ct,0) as have
    from catalog_domains d left join activated a on a.domain_slug = d.slug
    where coalesce(a.ct,0) < v_target
  ),
  cand as (
    select distinct on (lower(l.email)) l.id, l.email, l.company_name, l.claim_token, l.email_domain, l.email_verified,
           -- Arabic only where the lead's own locale says so AND the Arabic copy exists; otherwise
           -- English, which is also what a04 assumes for an unregistered recipient.
           case when lower(coalesce(l.locale, '')) like 'ar%' and coalesce(v_body_ar, '') like '%{{link}}%'
                     and coalesce(v_subj_ar, '') <> '' then 'ar' else 'en' end as lang
    from leads l
    where public.fn_supplier_invite_eligible(l)
    order by lower(l.email), l.id
  ),
  prio as (
    select c.id, c.email, c.company_name, c.claim_token, c.email_domain, c.lang,
      coalesce((select u.domain_slug from lead_subcategory ls join under u on u.domain_slug = ls.domain_slug
                 where ls.lead_id = c.id order by u.have asc, ls.score desc limit 1), '~none') as pdomain,
      case when c.email_verified in ('verified','true') then 0 else 1 end as unverified_rank,
      case when split_part(lower(c.email),'@',1) in
             ('info','sales','admin','contact','enquiry','enquiries','inquiry','office','mail',
              'support','hello','marketing','general','accounts','reception','careers','hr')
           then 1 else 0 end as role_rank
    from cand c
  ),
  elig as (
    select r.id, r.email, r.company_name, r.claim_token, r.lang from (
      select p.*,
        case when p.pdomain='~none' then 1 else 0 end as is_none,
        row_number() over (partition by p.pdomain order by p.unverified_rank, p.role_rank, p.id) as rk,
        row_number() over (partition by coalesce(p.email_domain, split_part(p.email,'@',2)) order by p.unverified_rank, p.role_rank, p.id) as domain_rk
      from prio p
    ) r
    where r.domain_rk <= 5
    order by r.is_none, r.rk, r.unverified_rank, r.role_rank, r.pdomain
    limit greatest(coalesce(p_limit, 0), 0)
  )
  select e.id, btrim(e.email), e.company_name, e.lang,
         case when e.lang = 'ar' then v_subj_ar else v_subj end,
         replace(
           replace(case when e.lang = 'ar'
                        then case when coalesce(btrim(e.company_name), '') = ''
                                  then replace(v_body_ar, 'السادة/ {{company}} المحترمين،', 'السادة الكرام،')
                                  else v_body_ar end
                        else v_body end,
                   '{{company}}', coalesce(nullif(btrim(e.company_name),''), case when e.lang = 'ar' then 'الكرام' else 'there' end)),
           '{{link}}', v_site || '/' || e.lang || '/portal?t=' || e.claim_token::text)
  from elig e;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_invite_eligible(p leads)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(btrim(p.email), '') <> ''
     and p.invite_status is null
     and coalesce(p.source, '') <> 'self_registered'
     and coalesce(p.claimed, false) = false
     and coalesce(p.banned, false) = false
     and coalesce(p.permanently_closed, false) = false
     -- a fixture is never a supplier: the flag, the naming convention, and the reserved domains
     and coalesce(p.is_demo, false) = false
     and coalesce(p.company_name, '') !~* '^\s*zz\s*demo'
     and not public.fn_is_demo_email(p.email)
     -- screened and matched but undecided is not cleared; a confirmed ban is total
     and not exists (select 1 from public.sanctions_ban b where b.lead_id = p.id)
     and not exists (select 1 from public.supplier_screening_hit h
                      where h.lead_id = p.id and h.status in ('open', 'confirmed'))
     -- never twice, read from the outbox rather than from a status column
     and not exists (select 1 from public.notifications n
                      where n.type = 'supplier_invite' and lower(btrim(n.to_email)) = lower(btrim(p.email)))
     and coalesce((public.fn_email_sendable(p.email)->>'ok')::boolean, false)
     -- 22 Sep 2026: a COLD invitation needs a measured MX. An A-record-only domain (361 leads), a lookup
     -- that errored (86) or a domain never asked is a bounce risk on a domain with no history to spend.
     and exists (select 1 from public.email_domain_mx m
                  where m.domain = split_part(lower(btrim(p.email)), '@', 2) and m.kind = 'mx')
     -- ... and never a mailbox whose reader is not the business (44 leads): a recruiter or a lawyer
     -- presses "spam", they do not register.
     and split_part(lower(btrim(p.email)), '@', 1) !~
         '^(careers?|jobs?|hr|recruit(ment|ing)?|cv|webmaster|hostmaster|mailer-daemon|privacy|legal|newsletters?|unsubscribe|donotreply)$'
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_invite_test_send(p_lang text DEFAULT 'en'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_lang text := case when lower(coalesce(p_lang, 'en')) = 'ar' then 'ar' else 'en' end;
  v_site text; v_subj text; v_body text; v_to text; v_id bigint; v_status text; v_err text;
begin
  select coalesce(nullif(btrim(value), ''), 'https://quotesdone.com') into v_site from app_secrets where key = 'public_site_url';
  select value into v_subj from app_secrets where key = case when v_lang = 'ar' then 'invite_subject_ar' else 'invite_subject' end;
  select value into v_body from app_secrets where key = case when v_lang = 'ar' then 'invite_body_ar' else 'invite_body' end;
  v_to := 'zz-demo-supplier-invite-' || v_lang || '-' || to_char(clock_timestamp(), 'YYYYMMDDHH24MISSUS') || '@example.invalid';
  if not public.fn_is_demo_email(v_to) then raise exception 'test address % is not a fixture address', v_to; end if;
  insert into notifications(type, to_email, to_role, subject, body, lang, status)
  values ('supplier_invite', v_to, 'supplier', v_subj,
          replace(replace(v_body, '{{company}}', 'ZZ DEMO Supplier'),
                  '{{link}}', coalesce(v_site, 'https://quotesdone.com') || '/' || v_lang || '/portal?t=00000000-0000-0000-0000-000000000000'),
          v_lang, 'queued')
  returning id, status, last_error into v_id, v_status, v_err;
  return jsonb_build_object('id', v_id, 'to', v_to, 'lang', v_lang, 'status', v_status, 'captured_note', v_err,
                            'subject', v_subj, 'never_reaches_resend', v_status = 'suppressed');
end
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_knowledge_graph(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with mine as (
    select lc.slug, lc.is_primary, lc.score, 'lead_category' as src
    from lead_category lc where lc.lead_id = p_lead_id
    union
    select t, false, null::numeric, 'confirmed_trade'
    from public.supplier_capabilities sc, unnest(coalesce(sc.trades, '{}'::text[])) t
    where sc.supplier_id = p_lead_id
      and not exists (select 1 from lead_category lc where lc.lead_id = p_lead_id and lc.slug = t)
  ),
  neigh as (
    select case when e.src_ref = m.slug then e.dst_ref else e.src_ref end as slug,
           (e.props->>'companies')::int as companies
    from graph_edges e join mine m on m.slug in (e.src_ref, e.dst_ref)
    where e.rel = 'adjacent_to' and e.src_kind = 'category'
  )
  select jsonb_build_object(
    'lead_id', p_lead_id,
    'basis', 'the trades this company confirmed and the categories it is listed in, and the categories its competitors also serve',
    'my_categories', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'slug', m.slug,
        'label', coalesce((select n.label from graph_nodes n where n.kind='category' and n.ref_id=m.slug),
                          (select t.label from public.taxonomy_trade t where t.code = m.slug),
                          replace(m.slug, '_', ' ')),
        'label_ar', (select t.label_ar from public.taxonomy_trade t where t.code = m.slug),
        'companies', coalesce((select (n.props->>'companies')::int from graph_nodes n where n.kind='category' and n.ref_id=m.slug),
                              (select count(*)::int from public.supplier_capabilities sc where sc.trades && array[m.slug])),
        'primary', m.is_primary, 'source', m.src) order by m.is_primary desc nulls last, m.slug), '[]'::jsonb)
      from mine m),
    'adjacent', (
      select coalesce(jsonb_agg(x order by x->'shared_companies' desc), '[]'::jsonb) from (
        select jsonb_build_object(
          'slug', nb.slug,
          'label', (select n.label from graph_nodes n where n.kind='category' and n.ref_id=nb.slug),
          'shared_companies', max(nb.companies),
          'companies', (select (n.props->>'companies')::int from graph_nodes n where n.kind='category' and n.ref_id=nb.slug)
        ) x
        from neigh nb
        where nb.slug not in (select slug from mine)
        group by nb.slug
        order by max(nb.companies) desc
        limit 12) s),
    'population', jsonb_build_object(
      'category_nodes', (select count(*) from graph_nodes where kind='category'),
      'adjacency_edges', (select count(*) from graph_edges where rel='adjacent_to' and src_kind='category'),
      'listed_companies', (select count(distinct lead_id) from lead_category))
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_mandatory_check(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare l public.leads; v_miss text[]; v_label jsonb := jsonb_build_object(
  'reg_name', 'Company name', 'reg_mobile', 'Verified UAE mobile number', 'reg_email', 'Verified email address',
  'reg_licence', 'Trade licence', 'reg_profile', 'Company profile', 'reg_terms', 'Signed terms and conditions');
begin
  select * into l from public.leads where id = p_lead_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'No such lead.'); end if;
  v_miss := public.fn_supplier_mandatory_six(l);
  return jsonb_build_object(
    'ok', true, 'party_kind', 'supplier', 'id', p_lead_id, 'name', l.company_name,
    'complete', cardinality(v_miss) = 0,
    'have', (select coalesce(jsonb_agg(v_label->>k order by o), '[]') from unnest(array['reg_name','reg_mobile','reg_email','reg_licence','reg_profile','reg_terms']) with ordinality u(k, o) where not (k = any (v_miss))),
    'missing', (select coalesce(jsonb_agg(v_label->>k order by o), '[]') from unnest(v_miss) with ordinality u(k, o)),
    'missing_codes', to_jsonb(v_miss),
    'missing_count', cardinality(v_miss),
    'mandatory_total', 6);
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_mandatory_six(p leads)
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select array_remove(array[
    case when coalesce(btrim(p.company_name), '') = '' then 'reg_name' end,
    case when not (coalesce(p.owner_phone_verified, false)
                   and regexp_replace(coalesce(nullif(btrim(p.phone), ''), p.phone_e164, ''), '[^0-9]', '', 'g') ~ '^9715[0-9]{8}$')
         then 'reg_mobile' end,
    case when not coalesce(p.owner_email_verified, false) then 'reg_email' end,
    case when not exists (select 1 from storage.objects o where o.bucket_id = 'supplier-docs' and o.name = p.license_doc_path)
         then 'reg_licence' end,
    case when not exists (select 1 from storage.objects o where o.bucket_id = 'supplier-docs' and o.name = p.company_profile_doc_path)
         then 'reg_profile' end,
    case when coalesce(btrim(p.signed_terms_path), '') = '' then 'reg_terms' end
  ], null)
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_mandatory_six_for(p_lead_id bigint)
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select public.fn_supplier_mandatory_six(l) from public.leads l where l.id = p_lead_id
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_market(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with me as (select * from public.leads where id = p_lead_id),
  flag as (select coalesce((select source from me), '') = 'qd_demo_fixture' as is_demo),
  -- This supplier's trades: what it CONFIRMED in supplier_capabilities, plus its sector code.
  mine as (
    select array_remove(array_cat(coalesce((select trades from public.supplier_capabilities where supplier_id = p_lead_id), '{}'::text[]),
                                  array[(select sector from me)]), null) as trades
  ),
  -- Competitors: any lead whose confirmed trades overlap this supplier's (the population
  -- fn_customer_decision_support counts as "suppliers covering this trade"), or whose sector string
  -- equals this supplier's. Same side of the demo fence, never self.
  peers as (
    select l.*
    from public.leads l, me, flag, mine
    where l.id <> me.id
      and coalesce(l.permanently_closed, false) = false
      and (coalesce(l.source, '') = 'qd_demo_fixture') = flag.is_demo
      and ((l.sector is not null and me.sector is not null and l.sector = me.sector)
           or exists (select 1 from public.supplier_capabilities sc where sc.supplier_id = l.id and sc.trades && mine.trades))
  ),
  peers_here as (
    select p.* from peers p, me
    where me.service_emirates is null
       or coalesce(array_length(me.service_emirates, 1), 0) = 0
       or p.emirate is null
       or exists (select 1 from unnest(me.service_emirates) e where p.emirate ilike '%' || e || '%')
  ),
  demand_all as (
    select i.* from public.inquiries i, flag
    where (coalesce(i.brief_source, '') = 'qd_demo_fixture') = flag.is_demo
      and i.created_at >= now() - interval '28 days'
  ),
  -- An enquiry in this supplier's category: its trades overlap, or its category names one of them.
  demand_mine as (
    select d.* from demand_all d, mine, me
    where (d.trades is not null and d.trades && mine.trades)
       or (d.category is not null and (d.category = any (mine.trades) or public.fn_norm_trades(d.category) && mine.trades))
  ),
  priced as (
    select q.quote_amount amt
    from public.quotes q join demand_mine d on d.id = q.inquiry_id, flag
    where (coalesce(q.source, '') = 'qd_demo_fixture') = flag.is_demo
      and q.quote_amount is not null and q.quote_amount > 0
  ),
  figures as (
    select
      (with c as (
         select count(*) filter (where created_at >= now() - interval '14 days') as recent,
                count(*) filter (where created_at <  now() - interval '14 days') as earlier
         from demand_mine)
       select case when c.recent = 0 and c.earlier = 0
         then jsonb_build_object(
                'available', false, 'value', null, 'direction', null,
                'basis', 'enquiries in your category over the last 28 days',
                'population', 0,
                'note', 'no enquiries in your category yet, so there is no series to trend')
         else jsonb_build_object(
                'available', true,
                'category', (select sector from me),
                'value', c.recent,
                'prior', c.earlier,
                'direction', case when c.recent > c.earlier then 'up'
                                  when c.recent < c.earlier then 'down' else 'flat' end,
                'pct', case when c.earlier > 0
                            then round(((c.recent - c.earlier)::numeric / c.earlier) * 100, 1)
                            else null end,
                'from_zero', c.earlier = 0,
                'share_pct', case when (select count(*) from demand_all) > 0
                             then round((c.recent::numeric
                                  / nullif((select count(*) from demand_all), 0)) * 100, 1)
                             else null end,
                'series', (
                  select coalesce(jsonb_agg(jsonb_build_object('week', w.wk, 'count', w.c) order by w.wk), '[]'::jsonb)
                  from (select date_trunc('week', created_at)::date wk, count(*) c
                        from demand_mine group by 1) w),
                'basis', 'enquiries in your category, two 14-day halves',
                'population', (select count(*) from demand_mine),
                'note', case when c.earlier = 0
                        then 'first activity in this window, so there is no prior period to take a percentage against'
                        else null end)
         end from c) as trend_obj,
      (with r as (select category cat, count(*) c from demand_all
                  where category is not null group by 1 order by count(*) desc limit 1)
       select case when not exists (select 1 from r)
         then jsonb_build_object(
                'available', false, 'value', null,
                'basis', 'enquiries over the last 28 days',
                'population', (select count(*) from demand_all),
                'note', 'that is a fact about requests, and none have been made')
         else jsonb_build_object(
                'available', true,
                'value', (select cat from r),
                'count', (select c from r),
                'basis', 'enquiries over the last 28 days, grouped by category',
                'population', (select count(*) from demand_all))
         end) as topcat_obj,
      (with s as (
         select count(*) n, round(avg(amt)) mean,
                round(percentile_cont(0.5)  within group (order by amt)) mid,
                round(percentile_cont(0.25) within group (order by amt)) lo,
                round(percentile_cont(0.75) within group (order by amt)) hi,
                min(amt) lowest, max(amt) highest
         from priced)
       select case when s.n = 0
         then jsonb_build_object(
                'available', false, 'value', null, 'currency', 'AED',
                'basis', 'quotes on enquiries in your category',
                'population', 0,
                'note', 'nothing in your category has been priced, so there is no market price')
         else jsonb_build_object(
                'available', true, 'currency', 'AED',
                'value', s.mean, 'median', s.mid, 'p25', s.lo, 'p75', s.hi,
                'low', s.lowest, 'high', s.highest,
                'basis', 'quotes on enquiries in your category over the last 28 days',
                'population', s.n)
         end from s) as money_obj
  )
  select jsonb_build_object(
    'lead_id', p_lead_id,
    'sector', (select sector from me),
    'trades', (select to_jsonb(trades) from mine),
    'population', case when (select is_demo from flag) then 'demo' else 'live' end,
    'competitors', jsonb_build_object(
      'available', true,
      'basis', 'suppliers whose confirmed trades overlap yours, or share your sector',
      'total', (select count(*) from peers),
      'in_my_area', (select count(*) from peers_here),
      'matchable', (
        select count(*) from peers p
        where public.fn_is_matchable(p.verified, p.banned, p.matching_blocked,
                                     p.approval_status, p.permanently_closed, p.chat_strikes)
          and exists (select 1 from public.supplier_capabilities sc
                      where sc.supplier_id = p.id and sc.confirmed_at is not null)
      ),
      'me_matchable', (
        select public.fn_is_matchable(m.verified, m.banned, m.matching_blocked,
                                      m.approval_status, m.permanently_closed, m.chat_strikes)
           and exists (select 1 from public.supplier_capabilities sc
                       where sc.supplier_id = m.id and sc.confirmed_at is not null)
        from public.leads m where m.id = p_lead_id
      ),
      'by_emirate', (
        select coalesce(jsonb_agg(jsonb_build_object('emirate', s.em, 'count', s.c) order by s.c desc), '[]'::jsonb)
        from (
          select p.emirate as em, count(*) as c
          from peers p where p.emirate is not null
          group by p.emirate order by count(*) desc limit 8
        ) s
      )
    ),
    'market_composition', jsonb_build_object(
      'available', true,
      'basis', 'competitors, grouped by category',
      'segments', (
        select coalesce(jsonb_agg(jsonb_build_object('name', s.nm, 'count', s.c) order by s.c desc), '[]'::jsonb)
        from (
          select coalesce(nullif(btrim(split_part(p.categories, ',', 1)), ''), coalesce(p.sector, 'Uncategorised')) as nm,
                 count(*) as c
          from peers p group by 1 order by count(*) desc limit 8
        ) s
      )
    ),
    'demand_trend',     (select trend_obj  from figures),
    'most_requested',   (select topcat_obj from figures),
    'avg_market_price', (select money_obj  from figures)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_notice(p_lead bigint, p_type text, p_subject_en text, p_body_en text, p_subject_ar text, p_body_ar text, p_inquiry uuid DEFAULT NULL::uuid, p_quote uuid DEFAULT NULL::uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare l record; v_ar boolean; v_subject text; v_body text; n int := 0;
begin
  select id, company_name,
         coalesce(nullif(btrim(claimed_by), ''), nullif(btrim(email), '')) as mail,
         coalesce(nullif(btrim(whatsapp), ''), nullif(btrim(phone), ''))  as tel
    into l from public.leads where id = p_lead;
  if not found then return 0; end if;
  v_ar := public.fn_registered_locale('supplier', null, p_lead) = 'ar';
  v_subject := case when v_ar then p_subject_ar else p_subject_en end;
  v_body := replace(case when v_ar then p_body_ar else p_body_en end, '{company}',
                    coalesce(nullif(btrim(l.company_name), ''), case when v_ar then 'الشركاء' else 'partner' end));
  if l.mail is not null then
    insert into public.notifications (type, kind, to_email, to_role, lead_id, inquiry_id, quote_id, channel, subject, body, status, requested_by, sender, lang)
    values (p_type, 'sales_engineer_' || p_type, l.mail, 'supplier', p_lead, p_inquiry, p_quote, 'email', v_subject, v_body, 'queued', 'sales_engineer', 'customer_support',
            case when v_ar then 'ar' else 'en' end);
    n := n + 1;
  end if;
  -- trg_wa_fanout has already made a WhatsApp twin for a supplier who opted in; otherwise queue one.
  if l.tel is not null and not exists (select 1 from public.notifications
                                        where channel = 'whatsapp' and lead_id = p_lead and type = p_type and created_at = now()) then
    insert into public.notifications (type, kind, to_email, to_phone, to_role, lead_id, inquiry_id, quote_id, channel, subject, body, status, requested_by, sender, lang)
    values (p_type, 'sales_engineer_' || p_type, l.mail, l.tel, 'supplier', p_lead, p_inquiry, p_quote, 'whatsapp', v_subject, v_body, 'queued', 'sales_engineer', 'customer_support',
            case when v_ar then 'ar' else 'en' end);
    n := n + 1;
  end if;
  return n;
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_notice_channel(p_version_no integer, p_channel text, p_whatsapp_opt text, p_verified_mobile text, p_confirmed_whatsapp text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
    when p_channel = 'whatsapp' and coalesce(p_version_no, 0) >= 12 then
      jsonb_build_object('to', p_confirmed_whatsapp, 'basis', 'confirmed_whatsapp',
        'reason', case when p_confirmed_whatsapp is null then 'no WhatsApp number confirmed in the portal' end)
    when p_channel = 'whatsapp' and p_version_no = 11 then
      case when p_whatsapp_opt = 'none'
           then jsonb_build_object('to', null, 'basis', 'registered_mobile', 'reason', 'the supplier said it does not use WhatsApp')
           else jsonb_build_object('to', p_verified_mobile, 'basis', 'registered_mobile',
                  'reason', case when p_verified_mobile is null then 'no verified registered mobile' end) end
    when p_channel = 'sms' and coalesce(p_version_no, 0) >= 11 then
      jsonb_build_object('to', p_verified_mobile, 'basis', 'registered_mobile',
        'reason', case when p_verified_mobile is null then 'no verified registered mobile' end)
    else jsonb_build_object('to', null, 'basis', 'not_agreed',
           'reason', 'the Supplier Agreement version accepted (' || coalesce('v' || p_version_no, 'none') || ') does not make ' || coalesce(p_channel, '?') || ' a notice channel')
  end
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_notice_route(p_lead bigint, p_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id bigint; v_accepted text; v_opt text; v_no int; v_mobile text; v_key text; v_clause jsonb;
begin
  select l.id, l.accepted_terms_version, l.whatsapp_opt into v_id, v_accepted, v_opt from public.leads l
   where l.id = p_lead or (p_lead is null and p_email is not null and lower(l.claimed_by) = lower(btrim(p_email)))
   order by l.id limit 1;
  v_no := public.fn_supplier_agreement_version_no(v_accepted);
  v_mobile := case when v_id is not null then public.fn_verified_mobile('supplier', null, v_id, null) end;
  v_key := case when coalesce(v_no, 0) >= 12 then '12' when v_no = 11 then '11' else '10' end;
  select value -> v_key into v_clause from public.decision_policy where key = 'supplier_agreement_notice_clause';
  return jsonb_build_object('supplier_id', v_id, 'agreement_version', v_accepted, 'version_no', v_no,
    'whatsapp', public.fn_supplier_notice_channel(v_no, 'whatsapp', v_opt, v_mobile,
                  case when coalesce(v_no, 0) >= 12 and v_id is not null then public.fn_whatsapp_destination('supplier', null, v_id, null) end),
    'sms', public.fn_supplier_notice_channel(v_no, 'sms', v_opt, v_mobile, null),
    'clause_en', v_clause->>'en', 'clause_ar', v_clause->>'ar');
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_notice_whatsapp_twin_under_v11()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id bigint; v_accepted text; v_opt text;
begin
  if coalesce(new.channel, 'email') <> 'email' or coalesce(new.to_role, '') <> 'supplier' or new.to_email is null
     or not exists (select 1 from public.decision_policy p, jsonb_array_elements_text(p.value) t
                     where p.key = 'supplier_formal_notice_types' and t = new.type) then
    return null;
  end if;
  select l.id, l.accepted_terms_version, l.whatsapp_opt into v_id, v_accepted, v_opt from public.leads l
   where l.id = new.lead_id or (new.lead_id is null and lower(l.claimed_by) = lower(new.to_email)) order by l.id limit 1;
  -- Answered (same/other/none): trg_wa_fanout already made or recorded the twin. Only unanswered v11 is missing.
  if v_id is null or v_opt is not null or public.fn_supplier_agreement_version_no(v_accepted) is distinct from 11
     or public.fn_verified_mobile('supplier', null, v_id, null) is null then
    return null;
  end if;
  insert into public.notifications (type, to_email, to_role, lead_id, inquiry_id, quote_id, subject, body, channel, status)
  values (new.type, new.to_email, new.to_role, v_id, new.inquiry_id, new.quote_id, new.subject, new.body, 'whatsapp', 'queued');
  return null;
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_opportunities(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with me as (
    select l.id, lower(coalesce(l.sector, '')) sector, l.emirate,
           coalesce(l.service_emirates, '{}'::text[]) service_emirates,
           lower(coalesce(l.capability_summary, l.services, l.description, '')) capability,
           l.verified
      from public.leads l where l.id = p_lead_id
  ),
  -- ONLY THE ENQUIRIES WE SENT THIS SUPPLIER. Until 22 Sep this read every open row in
  -- public.inquiries and handed back each one's inquiry_id with a reason line that could read
  -- "Outside your registered trade" — the list itself said the job was not theirs. Matching is exact
  -- trade or none (the founder's rule: never a nearest mapping), so public.inquiry_matches IS the
  -- answer to "what may this supplier quote for", and asking anything else invents a second matcher.
  cand as (
    select i.id, i.category, i.emirate, i.summary_masked as summary, i.scope_type, i.created_at, i.budget_masked as budget,
           nullif(btrim(coalesce(i.raw_input_masked, '')), '') requirement,
           lower(coalesce(i.category, '')) cat
      from public.inquiries i
     where coalesce(i.status, 'open') = 'open'
       and exists (select 1 from public.inquiry_matches m
                    where m.inquiry_id = i.id and m.supplier_id = p_lead_id)
  ),
  scored as (
    select c.*,
      (c.cat = me.sector and me.sector <> '')                                    as trade_hit,
      (c.emirate is not null and (c.emirate = me.emirate
        or c.emirate = any(me.service_emirates)))                                as location_hit,
      (me.capability <> '')                                                      as capacity_known,
      (me.capability <> '' and c.cat <> '' and position(c.cat in me.capability) > 0) as capacity_hit,
      (select count(*) from public.quotes q
         join public.inquiries qi on qi.id = q.inquiry_id
        where q.supplier_id = p_lead_id and lower(coalesce(qi.category,'')) = c.cat) as similar_jobs
      from cand c cross join me
  ),
  ranked as (
    select s.*,
      round(100.0 * (
        (case when s.trade_hit then 40 else 0 end)
      + (case when s.location_hit then 30 else 0 end)
      + (case when s.capacity_known and s.capacity_hit then 30 else 0 end)
      ) / nullif(40 + 30 + (case when s.capacity_known then 30 else 0 end), 0)) as fit_score
      from scored s
  )
  select jsonb_build_object(
    'lead_id', p_lead_id,
    'count', (select count(*) from ranked),
    'ordered_by', 'fit_score desc — a ranked list, never chronological',
    -- The population is the supplier's OWN matches. The estate-wide count of open enquiries used to be
    -- published here, which told every supplier how much work it was not being shown.
    'population', jsonb_build_object(
      'matched_to_me', (select count(*) from public.inquiry_matches where supplier_id = p_lead_id),
      'open_for_me', (select count(*) from cand),
      'my_quotes', (select count(*) from public.quotes where supplier_id = p_lead_id)
    ),
    'note', case when (select count(*) from ranked) = 0
                 then 'no open opportunities yet — nothing has been matched to you'
                 else null end,
    'opportunities', coalesce((
      select jsonb_agg(x order by x->>'fit_score' desc) from (
        select jsonb_build_object(
          'inquiry_id', r.id,
          -- The masked columns, through the same seed scrub the inbox applies (SP-F-04's rule: the
          -- customer's project name is not a pattern anything can recognise).
          'project_title', coalesce(nullif(btrim(coalesce(public.fn_supplier_safe_text(r.id, r.summary), '')), ''), r.category, 'Untitled project'),
          'category', r.category,
          'emirate', r.emirate,
          'requirement', public.fn_supplier_safe_text(r.id, r.requirement),
          'estimated_value', public.fn_supplier_safe_text(r.id, r.budget),
          'fit_score', r.fit_score,
          'match_pct', r.fit_score,
          'reasons', jsonb_build_array(
            jsonb_build_object(
              'key', 'trade',
              'applies', r.trade_hit,
              'text', case when r.trade_hit
                           then 'This is your trade — ' || coalesce(r.category,'the same category')
                           else 'Matched to you on capability rather than on your registered sector' end),
            jsonb_build_object(
              'key', 'location',
              'applies', r.location_hit,
              'text', case when r.location_hit
                           then 'Nearby location — ' || coalesce(r.emirate,'your service area')
                           else 'Outside the emirates you serve' end),
            jsonb_build_object(
              'key', 'capacity',
              'applies', r.capacity_known and r.capacity_hit,
              'available', r.capacity_known,
              'text', case when not r.capacity_known
                           then 'Your capacity fits: not assessable — you have not described your capability yet'
                           when r.capacity_hit
                           then 'Your capacity fits — you list this work in your capability'
                           else 'Not in your described capability' end),
            jsonb_build_object(
              'key', 'history',
              'applies', r.similar_jobs > 0,
              'available', (select count(*) from public.quotes where supplier_id = p_lead_id) > 0,
              'similar_jobs', r.similar_jobs,
              'text', case when (select count(*) from public.quotes where supplier_id = p_lead_id) = 0
                           then 'Previous similar project: you have not quoted on QuotesDone yet'
                           when r.similar_jobs > 0
                           then 'You worked on ' || r.similar_jobs || ' previous similar project(s)'
                           else 'No previous similar project on record' end)
          )
        ) x from ranked r
      ) s
    ), '[]'::jsonb)
  )
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_outreach_golive()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce((select lower(btrim(value)) = 'true' from public.app_secrets where key = 'supplier_outreach_golive'), false);
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_outreach_reachable(p leads, p_to text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(btrim(p_to), '') <> ''
     and coalesce(p.is_demo, false) = false
     and coalesce(p.company_name, '') !~* '^\s*zz\s*demo'
     and not public.fn_is_demo_email(p_to)
     and not public.fn_is_demo_email(p.email)
     and coalesce(p.banned, false) = false
     and coalesce(p.permanently_closed, false) = false
     and coalesce(p.invite_status, '') <> 'bounced'
     and not exists (select 1 from public.sanctions_ban b where b.lead_id = p.id)
     and not exists (select 1 from public.supplier_screening_hit h where h.lead_id = p.id and h.status in ('open', 'confirmed'))
     and coalesce((public.fn_email_sendable(p_to)->>'ok')::boolean, false)
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_portfolio_gaps(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with sc as (select * from public.supplier_capabilities where supplier_id = p_lead_id and confirmed_at is not null),
  keys as (select s.trade_code, s.trade_code || '.' || s.code as k from public.taxonomy_trade_service s where s.active),
  silent as (
    select t.code, t.label, coalesce(t.label_ar, t.label) as label_ar
      from sc, unnest(coalesce(sc.trades, '{}'::text[])) tr
      join public.taxonomy_trade t on t.code = tr
     where public.fn_supplier_portfolio_match_reads_ticks()
       and exists (select 1 from keys where keys.trade_code = tr)
       and not exists (select 1 from unnest(coalesce(sc.services, '{}'::text[])) s
                         join keys on keys.k = btrim(s)
                        where keys.trade_code = tr and btrim(s) <> all (coalesce(sc.services_removed, '{}'::text[])))
  ),
  own as (
    select distinct btrim(w) as w
      from sc, unnest(coalesce(sc.services, '{}'::text[])) w
     where nullif(btrim(w), '') is not null and btrim(w) not in (select k from keys)
  ),
  -- EVERY service a word names, and only a WHOLE word (review of #869): the alias must cover the word
  -- from its start (Arabic proclitics and ال allowed) to its END, so a short alias cannot claim a longer
  -- word. A phrase of more than one word is never named: «نقوم بأعمال الجبس والأسقف المستعارة والدهانات»
  -- names several services and one line could not say which he meant, so it takes the "not on our list"
  -- line, which is true of it as written.
  hits as (
    select distinct o.w, s.trade_code || '.' || s.code as key, s.sort, s.label_en, s.label_ar,
           t.label as trade_en, coalesce(t.label_ar, t.label) as trade_ar
      from own o
      join public.taxonomy_trade_service s on s.active
      join public.taxonomy_trade t on t.code = s.trade_code
      cross join lateral unnest(s.aliases) a
     where o.w !~ '\s' and length(public.fn_ar_norm(a)) >= 3
       and public.fn_ar_norm(o.w) ~* ('^' || case
             when public.fn_ar_norm(a) ~ '^[ء-ي]'
               then '(?:[وفبلك]?ال|[وف]?لل|[وفبلك])?'
                    || replace(replace(regexp_replace(public.fn_ar_norm(a), '([.*+?^${}()|\[\]\\])', '\\\1', 'g'), ' ', ' (?:ال)?'), ' (?:ال)?و', ' و(?:ال)?')
             else regexp_replace(public.fn_ar_norm(a), '([.*+?^${}()|\[\]\\])', '\\\1', 'g')
           end || '$')
  ),
  named as (
    select h.w, array_agg(h.key order by h.sort, h.key) as keys,
           string_agg('"' || h.label_en || '" under ' || h.trade_en, '; ' order by h.sort, h.key) as en_list,
           string_agg('«' || h.label_ar || '» ضمن ' || h.trade_ar, '، ' order by h.sort, h.key) as ar_list
      from hits h group by h.w
  ),
  unnamed as (select o.w from own o where o.w not in (select w from named)),
  proposed as (   -- said "under review" only when a review row really exists
    select exists (select 1 from public.taxonomy_trade_proposal p, unnamed u
                    where p.supplier_id = p_lead_id and p.status = 'pending'
                      and (btrim(p.label_en) = u.w or btrim(p.label_ar) = u.w)) as yes
  )
  select case
    when not exists (select 1 from sc) then jsonb_build_array(jsonb_build_object(
      'code', 'services_not_confirmed',
      'en', 'You have not confirmed the services your company provides yet, so no inquiry can reach you.',
      'ar', 'لم تؤكّدوا بعد الخدمات التي تقدّمها شركتكم، ولذلك لا يصلكم أي استفسار.'))
    else
      coalesce((select jsonb_agg(jsonb_build_object(
          'code', 'trade_without_service', 'trade', s.code,
          'en', s.label || ': no service is ticked yet, so inquiries that name a service in this trade do not reach you.',
          'ar', s.label_ar || ': لم تحدّدوا أي خدمة فيه بعد، ولذلك لا تصلكم الاستفسارات التي تذكر خدمة في هذا التخصص.')
          order by s.code) from silent s), '[]'::jsonb)
      || coalesce((select jsonb_agg(jsonb_build_object(
          'code', 'own_word_is_a_service', 'word', n.w, 'services', to_jsonb(n.keys),
          'en', '«' || n.w || '» is on our list as ' || n.en_list
                || '. Tick the ones you provide in the Services tab so the inquiries that name them reach you.',
          'ar', '«' || n.w || '» مدرجة في قائمتنا باسم ' || n.ar_list
                || '. يُرجى تحديد ما تقدّمونه منها في تبويب «الخدمات» لتصلكم الاستفسارات التي تذكرها.')
          order by n.w) from named n), '[]'::jsonb)
      || coalesce((select jsonb_build_array(jsonb_build_object(
          'code', 'own_words', 'words', jsonb_agg(u.w order by u.w),
          'en', 'Written in your own words and not on our list: '
                || string_agg('«' || u.w || '»', ', ' order by u.w)
                || '. As written they match no inquiry. If one of them is on the list under another name, tick it there'
                || case when (select yes from proposed) then '; our sales engineer is reviewing them for the list' else '' end || '.',
          'ar', 'خدمات كتبتموها بأسلوبكم وليست في قائمتنا: '
                || string_agg('«' || u.w || '»', '، ' order by u.w)
                || '. ولا تُطابَق بصيغتها هذه مع أي استفسار. وإن وجدتم أيًّا منها في القائمة باسم آخر، فحدّدوه هناك'
                || case when (select yes from proposed) then '، ويراجعها مهندس المبيعات حاليًا لإضافتها إلى القائمة' else '' end || '.'))
          from unnamed u having count(*) > 0), '[]'::jsonb)
  end
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_portfolio_match_reads_ticks()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_set text := nullif(current_setting('qd.probe_match_reads_ticks', true), ''); v_def text; v_n int;
begin
  if v_set is not null then return v_set::boolean; end if;
  select count(*), min(pg_get_functiondef(p.oid)) into v_n, v_def
    from pg_proc p join pg_namespace s on s.oid = p.pronamespace
   where s.nspname = 'public' and p.proname = 'fn_match_capability';
  if v_n <> 1 then return false; end if;
  v_def := regexp_replace(v_def, '--[^\n]*', '', 'g');
  return position('silent_in' in v_def) = 0 and position('never_asked' in v_def) > 0;
exception when others then
  return false;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_portfolio_reminder_compose(p leads, p_gaps jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ar boolean := lower(coalesce(p.locale, '')) like 'ar%';
  v_lang text := case when lower(coalesce(p.locale, '')) like 'ar%' then 'ar' else 'en' end;
  v_name text := nullif(btrim(coalesce(p.company_name, '')), '');
  v_site text; v_link text; v_items text; v_subj text; v_body text;
begin
  select coalesce(nullif(btrim(value), ''), 'https://quotesdone.com') into v_site from public.app_secrets where key = 'public_site_url';
  v_link := coalesce(v_site, 'https://quotesdone.com') || '/' || v_lang || '/portal';
  select string_agg('• ' || (g->>v_lang), E'\n' order by o) into v_items
    from jsonb_array_elements(coalesce(p_gaps, '[]'::jsonb)) with ordinality x(g, o);

  if v_ar then
    v_subj := 'خدماتكم لم تُستكمل بعد، وقد تفوتكم استفسارات العملاء';
    v_body := coalesce('السادة/ ' || v_name || ' المحترمين،', 'السادة الكرام،') || E'\n\nتحية طيبة وبعد،\n\n'
      || 'نشكركم على إتمام توثيق شركتكم لدى QuotesDone. وقد راجع مهندس المبيعات ملف أعمالكم، وتبيّن أن بعض بياناته لم تُستكمل بعد. '
      || 'وتعتمد مطابقة الاستفسارات على الخدمات التي أكّدتموها، لذا نرجو استكمال ما يلي:'
      || E'\n\n' || coalesce(v_items, '')
      || E'\n\nطريقة الاستكمال (تستغرق دقيقتين تقريبًا):'
      || E'\n1. سجّلوا الدخول إلى بوابة الموردين: ' || v_link
      || E'\n2. يظهر تبويب «الخدمات» أولًا. حدّدوا تحت كل تخصص جميع الخدمات التي تقدّمها شركتكم.'
      || E'\n3. إن ظهر تخصص لا تعمل فيه شركتكم، فاضغطوا «إزالة هذا التخصص».'
      || E'\n4. إن لم تجدوا في القائمة خدمة تقدّمونها، فاكتبوها في خانة «أضيفوا الخدمات التي تقدّمونها» ثم اضغطوا «إعادة صياغة خدماتي».'
      || E'\n5. اضغطوا «تأكيد خدماتي» لحفظ التغييرات، أو «تحديث خدماتي» إن سبق لكم الحفظ.'
      || E'\n\nالخيارات المتاحة لكم:'
      || E'\n• تحديد الخدمات التي تقدّمونها، فتصلكم الاستفسارات التي تذكرها.'
      || E'\n• إزالة التخصص الذي لا تعملون فيه، فلا تصلكم استفساراته بعد ذلك.'
      || E'\n• إن احتجتم إلى المساعدة، يكفي الرد على هذه الرسالة أو مراسلتنا عبر واتساب، وسيستكمل فريقنا البيانات معكم.'
      || E'\n\nوتفضلوا بقبول فائق الاحترام والتقدير،\nفريق خدمة العملاء — QuotesDone';
  else
    v_subj := 'Your services are not complete yet, so you may miss inquiries';
    v_body := coalesce('Dear ' || v_name || ',', 'Dear Sir or Madam,') || E'\n\n'
      || 'Thank you for completing your verification with QuotesDone. Our sales engineer has reviewed your company''s portfolio, and some of it is still missing. '
      || 'Inquiries are matched against the services you have confirmed, so please complete the following:'
      || E'\n\n' || coalesce(v_items, '')
      || E'\n\nHow to complete it (about two minutes):'
      || E'\n1. Sign in to your supplier portal: ' || v_link
      || E'\n2. The Services tab opens first. Under each trade, tick every service your company provides.'
      || E'\n3. If a trade is listed that your company does not work in, press "Remove this trade".'
      || E'\n4. If a service you provide is not on the list, write it under "Add the services you provide" and press "Rewrite my services".'
      || E'\n5. Press "Confirm my services" to save, or "Update my services" if you have saved before.'
      || E'\n\nYour options:'
      || E'\n• Tick the services you provide: you will receive the inquiries that name them.'
      || E'\n• Remove a trade you do not work in: you will no longer receive inquiries for it.'
      || E'\n• Need help? Reply to this e-mail or message us on WhatsApp, and our team will complete it with you.'
      || E'\n\nKind regards,\nQuotesDone Customer Support';
  end if;
  return jsonb_build_object('lang', v_lang, 'subject', v_subj, 'body', v_body, 'link', v_link);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_portfolio_reminder_still_due(p_lead_id bigint)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_array_length(public.fn_supplier_portfolio_gaps(p_lead_id)) > 0
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_portfolio_reminder_tick(p_include_fixtures boolean DEFAULT false, p_now timestamp with time zone DEFAULT now(), p_lead_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_days int := public.fn_seat_clock_policy('supplier_portfolio_reminder_working_days', 3)::int;
  h public.agent_actions; l public.leads; v_gaps jsonb; v_due timestamptz; v_ev jsonb;
  e public.notifications; w public.notifications; v_key text; v_failed int;
  v_local timestamp := p_now at time zone 'Asia/Dubai';
  v_open_hours boolean;
  v_opened int := 0; v_complete int := 0; v_closed int := 0; v_waiting int := 0; v_capped int := 0;
begin
  -- 1. RE-VERIFY WHAT SUPPORT ANSWERED; CLOSE ONLY WHEN EVERY LEG IS FINAL. Only the originator closes.
  for h in select a.* from public.agent_actions a
            where a.kind = 'handoff' and a.agent = 'customer_support' and a.detail->>'type' = 'supplier.portfolio_incomplete'
              and a.status not in ('done', 'failed') and a.detail ? 'replied_at'
              and (p_lead_id is null or a.detail->>'lead_id' = p_lead_id::text)
            order by a.id loop
    v_ev := coalesce(h.evidence, '{}'::jsonb);
    if v_ev ? 'not_sent' then
      v_ev := v_ev || jsonb_build_object('reverified', 'nothing was sent, and the reason is recorded');
    else
      e := null; w := null;
      select * into e from public.notifications n where n.id = (v_ev->>'notification_id')::bigint;
      select * into w from public.notifications n where n.id = (v_ev#>>'{whatsapp,notification_id}')::bigint;
      if e.id is null or e.status is null or e.status in ('queued', 'pending', 'sending', 'claimed')
         or (w.id is not null and (w.status is null or w.status in ('queued', 'pending', 'sending', 'claimed'))) then
        -- BOUNDED (review of #869): a leg that is still not final after 3 days never will be by itself
        -- (the WhatsApp copy expires at 24h, the email outbox holds stale mail sooner). Waiting forever
        -- would be as one-way as closing early, so it closes saying so, and sales_engineer gets a finding.
        if h.created_at > p_now - interval '3 days' then v_waiting := v_waiting + 1; continue; end if;
        v_ev := v_ev || jsonb_build_object('reverified', 'a leg never reached a final state',
          'email_state', coalesce(e.status, case when e.id is null then 'no email row recorded' end),
          'whatsapp_state', coalesce(w.status, v_ev#>>'{whatsapp,state}'));
        perform public.fn_it_engineer_finding_upsert('portfolio_reminder_unfinished:' || h.target_id,
          left('A portfolio reminder for supplier ' || coalesce(h.detail->>'lead_id', '?') || ' never reached a final delivery state in 3 days', 300),
          'fn_supplier_portfolio_reminder_tick', 'agent_facing', 1,
          jsonb_build_object('handoff_id', h.id, 'owner_seat', 'sales_engineer', 'email_state', v_ev->'email_state',
                             'whatsapp_state', v_ev->'whatsapp_state'),
          '{}'::text[], '{}'::text[], 'sales_engineer');
        perform set_config('qd.handoff_closer', 'sales_engineer', true);
        perform public.fn_seat_handoff_complete(h.id, v_ev || jsonb_build_object('reverified_by', 'sales_engineer', 'reverified_at', p_now));
        perform set_config('qd.handoff_closer', '', true);
        v_closed := v_closed + 1; continue;
      end if;
      v_ev := v_ev || jsonb_build_object(
        'reverified', 'both legs reached a final state',
        'email', jsonb_build_object('status', e.status, 'sent_at', e.sent_at, 'provider_message_id', e.provider_message_id, 'reason', e.last_error),
        'whatsapp_final', case when w.id is null then v_ev->'whatsapp'
                               else jsonb_build_object('status', w.status, 'sent_at', w.sent_at, 'provider_message_id', w.provider_message_id, 'reason', w.last_error) end);
    end if;
    perform set_config('qd.handoff_closer', 'sales_engineer', true);
    perform public.fn_seat_handoff_complete(h.id, v_ev || jsonb_build_object('reverified_by', 'sales_engineer', 'reverified_at', p_now));
    perform set_config('qd.handoff_closer', '', true);
    v_closed := v_closed + 1;
  end loop;

  -- 2. DETECT, in Dubai working hours only (09:00-18:00 on a working day): a message about his account
  --    lands while his office is open. So a supplier due Friday 17:50 is reached on Monday's first tick
  --    after 09:00 (the window, then the 30-minute clock), which is accepted.
  v_open_hours := public.fn_is_working_day(v_local::date) and v_local::time >= time '09:00' and v_local::time < time '18:00';
  if not v_open_hours then
    return jsonb_build_object('ok', true, 'opened', 0, 'outside_working_hours', true, 'closed', v_closed, 'awaiting_final_state', v_waiting);
  end if;
  for l in select * from public.leads x
            where x.verified and x.approval_status = 'approved' and x.approved_at is not null and not coalesce(x.banned, false)
              and public.fn_add_working_days(x.approved_at, v_days) <= p_now
              and public.fn_add_working_days(x.approved_at, v_days) > p_now - interval '14 days'
              and (p_lead_id is null or x.id = p_lead_id)
              -- fn_seat_clock_lead_is_fixture's own test, on the columns: the healthy-day replay reads leads
              -- through a view whose row type the leads-typed function does not accept.
              and (p_include_fixtures or not (coalesce(x.is_demo, false) or coalesce(x.company_name, '') ~* '^\s*zz\s*demo'
                                              or public.fn_is_demo_email(x.email) or public.fn_is_demo_email(x.claimed_by)))
              and not exists (select 1 from public.agent_actions a
                               where a.kind = 'handoff' and a.agent = 'customer_support' and a.status <> 'failed'
                                 and a.target_id = 'supplier.portfolio_incomplete:' || x.id || ':' || extract(epoch from x.approved_at)::bigint)
            order by x.id loop
    v_key := 'supplier.portfolio_incomplete:' || l.id || ':' || extract(epoch from l.approved_at)::bigint;
    -- A HANDLER THAT KEEPS FAILING IS TRIED THREE TIMES, then recorded once for its seat, not every 30 minutes.
    select count(*) into v_failed from public.agent_actions a
     where a.kind = 'handoff' and a.agent = 'customer_support' and a.status = 'failed' and a.target_id = v_key;
    if v_failed >= 3 then
      if not exists (select 1 from public.it_engineer_finding where issue_key = 'portfolio_reminder_failed:' || v_key and closed_at is null) then
        perform public.fn_it_engineer_finding_upsert('portfolio_reminder_failed:' || v_key,
          left('The portfolio reminder for supplier ' || l.id || ' failed ' || v_failed || ' times and is no longer retried', 300),
          'fn_supplier_portfolio_reminder_tick', 'agent_facing', 1,
          jsonb_build_object('lead_id', l.id, 'handoff_key', v_key, 'owner_seat', 'sales_engineer',
                             'last_error', (select a.detail->>'error' from public.agent_actions a where a.target_id = v_key and a.status = 'failed' order by a.id desc limit 1)),
          '{}'::text[], '{}'::text[], 'sales_engineer');
      end if;
      v_capped := v_capped + 1; continue;
    end if;
    v_gaps := public.fn_supplier_portfolio_gaps(l.id);
    if jsonb_array_length(v_gaps) = 0 then v_complete := v_complete + 1; continue; end if;   -- did it straight away
    v_due := public.fn_add_working_days(l.approved_at, v_days);
    perform public.fn_seat_handoff('sales_engineer', 'customer_support', 'supplier.portfolio_incomplete', 'leads', l.id || ':' || extract(epoch from l.approved_at)::bigint,
      jsonb_build_object('lead_id', l.id, 'verified_at', l.approved_at, 'due_at', v_due, 'gaps_at_detection', v_gaps,
                         'fixture', public.fn_seat_clock_lead_is_fixture(l)));
    v_opened := v_opened + 1;
  end loop;

  return jsonb_build_object('ok', true, 'opened', v_opened, 'complete_at_due', v_complete,
                            'closed', v_closed, 'awaiting_final_state', v_waiting, 'retries_exhausted', v_capped);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_product_match(p_inquiry_id uuid, p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with inq as (
    -- EVERYTHING THE CUSTOMER SAID, not the first field that happens to be non-empty. The first
    -- version preferred raw_input and fell back to summary, and on the demo enquiry that discarded
    -- the only line describing the work — every product scored 0% while the store held a curtain
    -- wall profile and the enquiry was for curtain walling. A brief's title carries meaning too,
    -- and dropping it to honour a precedence rule loses signal for nothing.
    select lower(coalesce(category, '')) cat,
           lower(concat_ws(' ', coalesce(summary, ''), coalesce(raw_input, ''), coalesce(category, ''))) want
      from public.inquiries where id = p_inquiry_id
  ),
  -- Words worth matching on. Anything under four characters is noise ("we", "for", "the"), and a
  -- stop list would be a maintenance burden for no gain at this size.
  terms as (
    select distinct w from inq, unnest(regexp_split_to_array(inq.want, '[^a-z0-9]+')) w
     where length(w) >= 4
  ),
  prod as (
    select p.id, p.name, p.brand, p.model, p.category_slug,
           lower(concat_ws(' ', p.name, p.brand, p.model, p.description, p.category_slug)) hay
      from public.supplier_product p
     where p.supplier_id = p_lead_id
  ),
  -- ── THE DENOMINATOR IS THE PRODUCT, NOT THE BRIEF ──────────────────────────────────────────────
  -- Scoring matched-terms over ALL the brief's words made the exactly-right product read 6%:
  -- "Aluminium curtain wall profile" matched 2 of 32 words in a paragraph that also discussed
  -- square metres, retail units and powder coating. That understates as badly as an inflated score
  -- overstates, and a supplier seeing 6% on their best product would conclude the matching is
  -- broken — which it would be.
  --
  -- The question is not "how much of the brief does this product cover" (no single product covers
  -- a brief) but "how much of THIS PRODUCT does the brief ask for". Aluminium ✓ curtain ✓ wall ✓
  -- profile ✗ is a strong match, and reads as one.
  pterms as (
    select pr.id pid, w from prod pr,
      unnest(regexp_split_to_array(lower(concat_ws(' ', pr.name, pr.category_slug)), '[^a-z0-9]+')) w
     where length(w) >= 4
  ),
  hit as (
    select pr.id, pr.name, pr.brand, pr.model, pr.category_slug, pr.hay,
           (select count(*) from pterms pt, inq where pt.pid = pr.id and position(pt.w in inq.want) > 0) matched_terms,
           (select count(*) from pterms pt where pt.pid = pr.id) total_terms,
           (pr.category_slug is not null and pr.category_slug = (select cat from inq)) cat_hit,
           ((select cat from inq) <> '' and pr.category_slug is not null) cat_askable
      from prod pr
  ),
  scored as (
    select h.*,
      round(100.0 * (
          (case when h.cat_hit then 40 else 0 end)
        + (case when h.total_terms > 0 then 60.0 * h.matched_terms / h.total_terms else 0 end)
      ) / nullif((case when h.cat_askable then 40 else 0 end)
               + (case when h.total_terms > 0 then 60 else 0 end), 0)) match_pct
      from hit h
  )
  select jsonb_build_object(
    'inquiry_id', p_inquiry_id,
    'supplier_id', p_lead_id,
    'basis', 'lexical: the enquiry''s own words against the product record. Not semantic — supplier_product carries no embedding, so a synonym will not match.',
    'population', jsonb_build_object(
      'products', (select count(*) from prod),
      'terms_from_enquiry', (select count(*) from terms),
      'note', case when (select count(*) from prod) = 0
                   then 'you have no products yet — upload a catalog and these become matchable'
                   when (select count(*) from terms) = 0
                   then 'the enquiry has no description to match against, so only category could be asked'
                   else null end),
    'matches', coalesce((
      select jsonb_agg(jsonb_build_object(
          'product_id', s.id, 'name', s.name, 'brand', s.brand, 'model', s.model,
          'match_pct', s.match_pct,
          'matched_terms', s.matched_terms, 'terms_considered', s.total_terms,
          'category_match', s.cat_hit)
        order by s.match_pct desc nulls last, s.name)
      from scored s), '[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_products(p_lead_id bigint, p_query text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with base as (
    select p.*
    from public.supplier_product p
    where p.supplier_id = p_lead_id
      and coalesce(p.status, 'active') <> 'archived'
  ),
  -- §7 "Searchable: YES". Matched over name, brand, model, category and the ATTRIBUTE VALUES, so a
  -- search for "5000 CFM" finds the unit whose spec says so rather than only matching its title.
  filtered as (
    select b.* from base b
    where p_query is null or btrim(p_query) = '' or (
         b.name              ilike '%' || btrim(p_query) || '%'
      or coalesce(b.brand, '')          ilike '%' || btrim(p_query) || '%'
      or coalesce(b.model, '')          ilike '%' || btrim(p_query) || '%'
      or coalesce(b.category_slug, '')  ilike '%' || btrim(p_query) || '%'
      or coalesce(b.subcategory_slug,'')ilike '%' || btrim(p_query) || '%'
      or coalesce(b.description, '')    ilike '%' || btrim(p_query) || '%'
      or exists (
           select 1 from jsonb_each_text(coalesce(b.attributes, '{}'::jsonb)) a
           where a.value ilike '%' || btrim(p_query) || '%'
              or a.key   ilike '%' || btrim(p_query) || '%')
      -- Certifications are a jsonb ARRAY and were unreachable by the attribute scan above, so
      -- "show me my Eurovent-certified units" returned nothing. A supplier searching their own
      -- catalogue by certification is the obvious case for §7's "Searchable: YES".
      or exists (
           select 1 from jsonb_array_elements_text(
             case when jsonb_typeof(b.certifications) = 'array' then b.certifications else '[]'::jsonb end) c
           where c ilike '%' || btrim(p_query) || '%')
    )
  )
  select jsonb_build_object(
    'supplier_id', p_lead_id,
    'query', p_query,

    -- ── §7's THREE COUNTS, over the supplier's whole catalogue, not the filtered page ───────────
    'product_count',  (select count(*) from base),
    -- coalesce(SUBcategory, category), not the reverse. category_slug is the broad family ('hvac')
    -- and is identical across a whole catalogue, so coalescing to it FIRST collapsed four distinct
    -- product categories into 1. The spec's "Categories: 18" means product categories, not sectors.
    'category_count', (select count(distinct coalesce(subcategory_slug, category_slug))
                       from base where coalesce(subcategory_slug, category_slug) is not null),
    -- The real number of specification keys the platform holds. Counted, never estimated.
    'attribute_count', (
      select coalesce(sum((select count(*) from jsonb_object_keys(coalesce(b.attributes, '{}'::jsonb)))), 0)
      from base b
    ),
    'searchable', true,

    -- ── §5's WAREHOUSE PANEL: the three quantities, over the SUPPLIER's own stock ────────────────
    -- inv_items is NOT this, and the distinction matters. Measured: inv_items has no supplier_id at
    -- all, and carries inventory_account / cogs_account / reorder_point — it is QuotesDone's OWN
    -- accounting ledger. A supplier's warehouse could never appear in it, so scoring §5 against it
    -- would have been unsatisfiable by any correct implementation.
    -- A supplier's stock lives on the variant, which is also where §8's "Available: 120" comes from.
    'stock', (
      select jsonb_build_object(
        'available',     coalesce(sum(nullif(v.attributes ->> 'available_units', '')::numeric), 0),
        'reserved',      coalesce(sum(nullif(v.attributes ->> 'reserved_units', '')::numeric), 0),
        'in_production', coalesce(sum(nullif(v.attributes ->> 'in_production_units', '')::numeric), 0),
        'skus', count(*)
      )
      from public.supplier_product_variant v
      join base b2 on b2.id = v.product_id
      where v.active
    ),

    'match_count', (select count(*) from filtered),

    'catalogs', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', c.id, 'status', c.status, 'version', c.version,
        'extracted_at', c.extracted_at, 'source', c.source_document_path
      ) order by c.created_at desc), '[]'::jsonb)
      from public.supplier_catalog c where c.supplier_id = p_lead_id
    ),

    -- ── §8 AI PRODUCT CARDS ─────────────────────────────────────────────────────────────────────
    -- Every field the spec draws on a card, from real columns. `ai_match` is NOT invented: it is
    -- null unless the product carries a computed match in its attributes, because §8's "AI Match
    -- 96%" is a claim about a specific opportunity and there are 0 inquiries on production. A card
    -- showing a confident percentage against nothing would be the exact fabrication this row's
    -- scorer exists to catch.
    'products', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', f.id,
        'name', f.name,
        'category', coalesce(f.subcategory_slug, f.category_slug),
        'brand', f.brand,
        'model', f.model,
        'description', f.description,
        'attributes', coalesce(f.attributes, '{}'::jsonb),
        'attribute_count', (select count(*) from jsonb_object_keys(coalesce(f.attributes, '{}'::jsonb))),
        'certifications', coalesce(f.certifications, '[]'::jsonb),
        'documents', coalesce(f.documents, '[]'::jsonb),
        'status', f.status,
        -- Availability comes from the variants, which is where stock policy lives.
        'variants', (
          select coalesce(jsonb_agg(jsonb_build_object(
            'sku', v.sku, 'attributes', v.attributes,
            'price_policy', v.price_policy, 'lead_time_policy', v.lead_time_policy,
            'active', v.active) order by v.sku), '[]'::jsonb)
          from public.supplier_product_variant v where v.product_id = f.id
        ),
        'reserved_units', (
          select sum(nullif(v.attributes ->> 'reserved_units', '')::numeric)
          from public.supplier_product_variant v where v.product_id = f.id and v.active
        ),
        'in_production_units', (
          select sum(nullif(v.attributes ->> 'in_production_units', '')::numeric)
          from public.supplier_product_variant v where v.product_id = f.id and v.active
        ),
        'available_units', (
          select sum((v.attributes ->> 'available_units')::numeric)
          from public.supplier_product_variant v
          where v.product_id = f.id and v.active
            and (v.attributes ->> 'available_units') ~ '^[0-9]+$'
        ),
        -- §8's "Compatible Projects". Real when the extractor recorded it, null otherwise.
        'compatible_projects', coalesce(f.attributes -> 'compatible_projects', 'null'::jsonb),
        'ai_match', (f.attributes ->> 'ai_match')::numeric,
        'evidence_refs', coalesce(f.evidence_refs, '[]'::jsonb)
      ) order by f.name), '[]'::jsonb)
      from (select * from filtered order by name limit 200) f
    )
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_quote_recommend(p_lead_id bigint, p_inquiry_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with me as (select * from public.leads where id = p_lead_id),
  flag as (select coalesce((select source from me), '') = 'qd_demo_fixture' as is_demo),
  -- THE MATCH IS THE PERMISSION. Without a row here this enquiry does not exist for this supplier,
  -- and nothing below is computed for them.
  matched as (
    select exists (select 1 from public.inquiry_matches m
                    where m.inquiry_id = p_inquiry_id and m.supplier_id = p_lead_id) as ok
  ),
  inq as (select * from public.inquiries_supplier_safe where id = p_inquiry_id),

  -- The competing bids. A DRAFT IS NOT A BID: a quote that was never sent to the customer is a figure
  -- somebody was still typing, and counting it moved the midpoint a real supplier prices against.
  bids as (
    select q.supplier_id, q.quote_amount amt, q.lead_time, q.warranty, q.payment_terms
    from public.quotes q, flag, matched
    where matched.ok
      and q.inquiry_id = p_inquiry_id
      and q.supplier_id is distinct from p_lead_id
      and q.status in ('submitted', 'revealed')
      and q.quote_amount is not null and q.quote_amount > 0
      and (coalesce(q.source, '') = 'qd_demo_fixture') = flag.is_demo
  ),
  -- n IS A COUNT OF COMPANIES, not of rows (review of #854). count(*) let ONE rival submitting three
  -- priced options clear a three-bid floor by itself, and the median of those three is that rival's
  -- middle option. lowest and highest are computed for the wide_spread signal only; neither, and no
  -- percentile, ever leaves this routine.
  stat as (
    select count(distinct supplier_id) n,
           count(*) n_rows,
           percentile_cont(0.5) within group (order by amt) mid_raw,
           min(amt) lowest, max(amt) highest
    from bids
  ),
  -- THE BRACKET, AND WHY A BRACKET RATHER THAN A FIGURE (review of #854, and one correction on top).
  --
  -- The first version published the median with its p25 and p75. For three sorted bids a < b < c that
  -- is p25 = (a+b)/2 and p75 = (b+c)/2, so a = 2*p25 - median and c = 2*p75 - median: all three bids
  -- recovered to the fils out of the very payload whose comment promised none of them. An ODD
  -- population also makes the median itself one company's exact number, so no raw statistic can carry
  -- the guarantee at all.
  --
  -- Rounding the median was the next attempt and it failed on its own probe: the fixtures
  -- 50000 / 61000 / 72000 have a median of 61000, which is already a multiple of a thousand, so
  -- "rounded to the nearest AED 1,000" published bid b unchanged. A SYMMETRIC band fails the same way
  -- for the same reason — its own midpoint is the number it was meant to hide.
  --
  -- What leaves this routine is therefore the BRACKET the midpoint falls in: [floor(mid/step)*step,
  -- +step), step being half an order of magnitude and never less than AED 1,000 (AED 5,000 wide around
  -- 61,000; AED 50,000 wide around 610,000). A bracket has no centre to invert and states only that
  -- the middle of the market is somewhere inside it.
  --
  -- THE GUARANTEE, STATED AS IT ACTUALLY HOLDS: this routine publishes no statistic of the competing
  -- bids finer than one bracket. It does not promise that no bid EQUALS a bracket edge — a rival whose
  -- price happens to be exactly AED 60,000 shares that number with the edge by coincidence, and
  -- nothing in the payload says which.
  band as (
    -- `mid` is the MIDDLE of the bracket, not its bottom edge (re-review of #854). The bottom edge was
    -- what the one-click accept sent, and it is up to a whole step low — a midpoint of 14,999 would
    -- have been quoted at 10,000, 33% under — so the Quote Builder systematically under-bid its users.
    -- The bracket's middle is derived from the bracket alone, reveals nothing the bracket does not,
    -- and is wrong by at most half a step in either direction rather than a whole step in one.
    select lo, lo + step as hi, lo + step / 2 as mid, step
    from (select floor(mid_raw / step) * step as lo, step
            from (select mid_raw, greatest(1000, power(10, floor(log(mid_raw)))::numeric / 2) as step
                    from stat) q) b
  ),

  -- The supplier's own habit, measured rather than assumed: across every enquiry they have priced,
  -- where did they sit against the midpoint of that enquiry's other bids? An index of 1.04 means
  -- this company prices 4% above the middle of the market, and it is computed from their own rows.
  -- ITS OWN FLOOR, AND THE SAME STATUS RULE (review of #854). This index was the leak the headline
  -- figure no longer is: idx = avg(my price / the median of the others') to three decimal places, with
  -- your_quotes_measured naming the denominator, so on a single measured enquiry a supplier could
  -- recover that median to about a tenth of a percent. It is now computed ONLY over enquiries where at
  -- least three OTHER COMPANIES submitted, rounded to two places, and published only when three or
  -- more enquiries went into it. The supplier's own drafts are excluded too: the outer query had no
  -- status filter at all, which contradicted this file's own rule that a draft is not a bid.
  habit as (
    select round(avg(ratio)::numeric, 2) idx, count(*) n
    from (
      select q.quote_amount / nullif((
               select percentile_cont(0.5) within group (order by o.quote_amount)
               from public.quotes o
               where o.inquiry_id = q.inquiry_id and o.supplier_id is distinct from q.supplier_id
                 and o.status in ('submitted', 'revealed') and o.quote_amount > 0
                 and (select count(distinct o2.supplier_id) from public.quotes o2
                       where o2.inquiry_id = q.inquiry_id and o2.supplier_id is distinct from q.supplier_id
                         and o2.status in ('submitted', 'revealed') and o2.quote_amount > 0) >= 3), 0) as ratio
      from public.quotes q, flag
      where q.supplier_id = p_lead_id and q.quote_amount > 0
        and q.status in ('submitted', 'revealed')
        and (coalesce(q.source, '') = 'qd_demo_fixture') = flag.is_demo
    ) r where r.ratio is not null
  ),
  -- DIFFERENCING (re-review of #854). your_index at two decimal places with an EXACT
  -- your_quotes_measured lets a supplier subtract one enquiry's contribution from the next and recover
  -- the new enquiry's median to about 3.5% — finer than a bracket, which would have made this the
  -- remaining way in. One decimal place, and the count as a band rather than a number.
  habit_out as (
    select case when n >= 3 then round(idx, 1) else null end idx,
           -- `when n < 3 then null` FIRST, and it is not decoration: without it a count of 0, 1 or 2
           -- failed the `n >= 3 and n <= 5` branch, fell through to `n <= 10`, and read "6-10" — a
           -- supplier with one measured enquiry told they had six to ten (reviewer's guard on #854).
           case when n < 3 then null
                when n <= 5 then '3-5' when n <= 10 then '6-10'
                when n <= 25 then '11-25' else 'more than 25' end n_band,
           n
    from habit
  ),

  -- ── DELIVERY, WARRANTY AND TERMS ARE TEXT, SO THEY ARE PICKED, NOT AVERAGED ───────────────────
  -- The average of "8-10 weeks" and "12-14 weeks" is not a promise anybody made.
  --
  -- WHAT THIS RETURNS AND WHAT IT NO LONGER RETURNS (22 Sep 2026, SP-N-02). It used to return
  -- `observed` — the distinct lead times and warranties every competitor had typed — and, when no two
  -- bids agreed, "the middle of the range", which is one named competitor's exact promise. A value
  -- only two or more suppliers independently gave is a market norm and may be suggested; anything
  -- else is a rival's answer and is now withheld, with `consensus` false saying so.
  ranked as (
    select 'lead' kind, lead_time v, count(*) c,
           min(coalesce(substring(lead_time from '\d+')::int, 999)) ord
    from bids where lead_time is not null group by 1, 2
    union all
    select 'warranty', warranty, count(*),
           min(coalesce(substring(warranty from '\d+')::int, 999))
    from bids where warranty is not null group by 1, 2
    union all
    select 'terms', payment_terms, count(*),
           min(coalesce(substring(payment_terms from '\d+')::int, 999))
    from bids where payment_terms is not null group by 1, 2
  ),
  picked as (
    select kind, v, c from (
      select r.kind, r.v, r.c,
             row_number() over (partition by r.kind order by r.c desc, r.ord) rn
      from ranked r
      where r.c >= 2
    ) z where z.rn = 1
  ),
  lead_pick  as (select v, c from picked where kind = 'lead'),
  warr_pick  as (select v, c from picked where kind = 'warranty'),
  terms_pick as (select v, c from picked where kind = 'terms'),

  -- ── RISK, AS NAMED SIGNALS RATHER THAN A MOOD ─────────────────────────────────────────────────
  risk as (
    select coalesce(jsonb_agg(jsonb_build_object('signal', s.k, 'detail', s.d)) filter (where s.hit), '[]'::jsonb) items,
           count(*) filter (where s.hit) n
    from (
      select 'not_matchable' k,
             not public.fn_is_matchable(m.verified, m.banned, m.matching_blocked,
                                        m.approval_status, m.permanently_closed, m.chat_strikes) hit,
             'Your account cannot currently receive work, so a quote sent now may not reach the customer.' d
      from me m
      union all
      select 'licence_missing',
             (select license_expiry is null from me),
             'No licence expiry is on file, and approval depends on it.'
      union all
      select 'licence_expired',
             (select coalesce(license_expiry < current_date, false) from me),
             'Your trade licence has expired.'
      union all
      select 'brief_incomplete',
             coalesce(((select completeness->>'score' from inq))::int < 60, true),
             'The customer brief is incomplete, so the scope you price may move after you send this.'
      union all
      -- The spread is computed here and the BOOLEAN leaves the routine; the two bids it is computed
      -- from never do.
      select 'wide_spread',
             (select case when mid_raw > 0 then (highest - lowest) / mid_raw > 0.4 else false end from stat),
             'The other bids disagree by more than 40%, which usually means the scope is being read differently.'
    ) s
  )

  select case
    when not (select ok from matched)
      -- Not 'forbidden': a job this supplier was not matched to must not be confirmed to exist.
      then jsonb_build_object(
        'available', false, 'reason', 'not_found',
        'lead_id', p_lead_id, 'inquiry_id', p_inquiry_id,
        'note', 'this enquiry is not one of yours')
    when (select n from stat) < 3
      -- THE THIN-MARKET FLOOR. With one competing company the midpoint IS its bid; with two, the pair
      -- brackets it. Three separate COMPANIES is the smallest population from which a rounded band
      -- describes a market rather than a named rival's quotation.
      then jsonb_build_object(
        'available', false, 'reason', 'thin_market',
        'lead_id', p_lead_id, 'inquiry_id', p_inquiry_id,
        'basis', 'quotes submitted by other suppliers on this enquiry',
        'population', (select n from stat),
        'note', 'fewer than three other companies have submitted a price for this enquiry, so there is '
                'no market midpoint to recommend against. With one or two, any figure we showed you '
                'would be their quotation, which is theirs and not ours to share.')
    else jsonb_build_object(
      'available', true,
      'lead_id', p_lead_id, 'inquiry_id', p_inquiry_id,
      -- The supplier-safe projection, scrubbed again: the raw inquiries.summary used to be read here,
      -- which walked around the inbox entirely (SP-N-02).
      'summary', public.fn_supplier_safe_text(p_inquiry_id, (select summary from inq)),
      'population', (select n from stat),
      'basis', 'the bracket the midpoint of every other company''s submitted bid on this enquiry falls in',

      -- The recommendation, as the bracket the market midpoint falls in. No median, no percentile, no
      -- lowest and no highest: every one of those is, or reconstructs, a figure a named competitor
      -- typed. `value` is the bottom of the bracket, because the portal's one-click accept has to send
      -- a number and that number must be one the routine derived from a bracket, not from a bid.
      'recommended_price', jsonb_build_object(
        'value', (select mid from band), 'currency', 'AED',
        'range_low', (select lo from band), 'range_high', (select hi from band),
        'bracket', (select step from band),
        'basis', 'the middle of the AED ' || (select step from band)::text || ' bracket that the midpoint of '
                 || (select n from stat)::text || ' competing companies'' bids falls in'),

      -- Where that recommendation sits, and where this supplier usually sits.
      -- THE VERDICT SAYS WHAT THE FIGURE IS (re-review of #854). It read "at the market midpoint",
      -- which was not true of a bracket edge and is not true of a bracket middle either: the real
      -- midpoint is somewhere inside the bracket and we deliberately do not say where.
      'market_position', jsonb_build_object(
        'verdict', 'inside the bracket the market midpoint falls in — we do not publish the midpoint itself',
        'your_index', (select idx from habit_out),
        'your_quotes_measured', (select n_band from habit_out),
        'detail', case when (select idx from habit_out) is null
                  then 'You have not priced enough enquiries yet for us to know where you usually sit.'
                  when (select idx from habit_out) > 1.02
                  then 'You normally price about ' || round(((select idx from habit_out) - 1) * 100)::text
                       || '% above the middle of the market, so this suggestion is lower than your habit.'
                  when (select idx from habit_out) < 0.98
                  then 'You normally price about ' || round((1 - (select idx from habit_out)) * 100)::text
                       || '% below the middle of the market, so this suggestion is higher than your habit.'
                  else 'You normally price close to the middle of the market, in line with this suggestion.' end),

      'delivery_estimate', jsonb_build_object(
        'value', (select v from lead_pick),
        'agreed_by', (select c from lead_pick),
        'consensus', (select count(*) from lead_pick) > 0,
        'basis', case when (select count(*) from lead_pick) > 0
                 then 'the lead time two or more of the competing bids gave'
                 else 'no two bids gave the same lead time, so there is no norm to suggest' end),

      'warranty', jsonb_build_object(
        'value', (select v from warr_pick),
        'agreed_by', (select c from warr_pick),
        'consensus', (select count(*) from warr_pick) > 0,
        'basis', case when (select count(*) from warr_pick) > 0
                 then 'the warranty two or more of the competing bids offered'
                 else 'no two bids offered the same warranty, so there is no norm to suggest' end),

      'payment_terms', jsonb_build_object(
        'value', (select v from terms_pick),
        'agreed_by', (select c from terms_pick),
        'consensus', (select count(*) from terms_pick) > 0,
        'basis', case when (select count(*) from terms_pick) > 0
                 then 'the payment terms two or more of the competing bids asked for'
                 else 'no two bids asked for the same terms, so there is no norm to suggest' end),

      'risk_level', jsonb_build_object(
        'value', case when (select n from risk) >= 3 then 'high'
                      when (select n from risk) >= 1 then 'medium' else 'low' end,
        'count', (select n from risk),
        'signals', (select items from risk),
        'recommended_action', case
          when (select n from risk) = 0
            then 'Nothing is working against this quote. We suggest sending it as proposed.'
          when exists (select 1 from jsonb_array_elements((select items from risk)) e
                       where e->>'signal' in ('not_matchable', 'licence_expired', 'licence_missing'))
            then 'We suggest fixing your account before you send this: a quote from an account that '
                 || 'cannot be matched may never reach the customer, whatever price is on it.'
          when exists (select 1 from jsonb_array_elements((select items from risk)) e
                       where e->>'signal' = 'wide_spread')
            then 'We suggest asking the customer to confirm the scope before you commit to a price. '
                 || 'The other bids disagree enough that they are probably not all pricing the same job.'
          when exists (select 1 from jsonb_array_elements((select items from risk)) e
                       where e->>'signal' = 'brief_incomplete')
            then 'We suggest putting your assumptions in writing with this quote, so a change of '
                 || 'scope later is a variation rather than an argument.'
          else 'We suggest treating the suggested price as indicative until more suppliers have priced this.'
          end,
        'basis', 'five checked signals on your account, the brief and the shape of the competing bids'))
  end;
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_registration_reminder_compose(p leads, p_stage text, p_step integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ar boolean := lower(coalesce(p.locale, '')) like 'ar%';
  v_lang text; v_site text; v_link text; v_name text := nullif(btrim(coalesce(p.company_name, '')), '');
  v_items_en text; v_items_ar text; v_due_en text; v_due_ar text; v_last boolean := p_step >= 2;
  v_greet text; v_subj text; v_body text;
  v_label jsonb := jsonb_build_object(
    'reg_name',        jsonb_build_array('company name', 'اسم الشركة'),
    'reg_mobile',      jsonb_build_array('a verified UAE mobile number', 'رقم جوال إماراتي موثَّق'),
    'reg_email',       jsonb_build_array('a verified e-mail address', 'بريد إلكتروني موثَّق'),
    'reg_licence',     jsonb_build_array('trade licence', 'الرخصة التجارية'),
    'reg_profile',     jsonb_build_array('company profile', 'الملف التعريفي للشركة'),
    'reg_terms',       jsonb_build_array('the signed supplier terms', 'الموافقة الموقّعة على شروط المورِّد'));
begin
  if p_stage not in ('clicked', 'started', 'incomplete') or p_step not in (1, 2) then
    raise exception 'fn_supplier_registration_reminder_compose: unknown stage % or step %', p_stage, p_step;
  end if;
  v_lang := case when v_ar then 'ar' else 'en' end;
  select coalesce(nullif(btrim(value), ''), 'https://quotesdone.com') into v_site from public.app_secrets where key = 'public_site_url';
  v_site := coalesce(v_site, 'https://quotesdone.com');
  v_link := v_site || '/' || v_lang || '/portal'
            || case when p_stage = 'clicked' and p.claim_token is not null then '?t=' || p.claim_token::text else '' end;

  if p_stage = 'incomplete' then
    select string_agg(coalesce(v_label->k->>0, k), ', ' order by o), string_agg(coalesce(v_label->k->>1, k), '، ' order by o)
      into v_items_en, v_items_ar from unnest(public.fn_supplier_mandatory_six(p)) with ordinality u(k, o);
    if p.license_expiry is not null and p.license_expiry < current_date then
      v_items_en := concat_ws(', ', v_items_en, 'a trade licence that is in date');
      v_items_ar := concat_ws('، ', v_items_ar, 'رخصة تجارية سارية المفعول');
    end if;
    v_items_en := coalesce(v_items_en, 'the items shown in your portal');
    v_items_ar := coalesce(v_items_ar, 'البنود الموضّحة في بوابتكم');
    v_due_en := to_char(coalesce(p.exception_due_at, now() + interval '14 days') at time zone 'Asia/Dubai', 'DD Mon YYYY');
    v_due_ar := to_char(coalesce(p.exception_due_at, now() + interval '14 days') at time zone 'Asia/Dubai', 'DD/MM/YYYY');
  end if;

  if v_ar then
    v_greet := case when v_name is null then 'السادة الكرام،' else 'السادة/ ' || v_name || ' المحترمين،' end;
    v_subj := case when v_last then 'تذكير أخير: ' else '' end
      || case p_stage when 'clicked' then 'دعوتكم للانضمام إلى الموردين المؤسِّسين في QuotesDone'
                      else 'استكمال تسجيلكم كمورِّد في QuotesDone' end;
    v_body := v_greet || E'\n\nتحية طيبة وبعد،\n\n'
      || case p_stage
           when 'clicked' then
             'نشكر لكم اطّلاعكم على دعوتنا للانضمام بصفة «مورِّد مؤسِّس» إلى QuotesDone، ونودّ إفادتكم بأن تسجيل شركتكم لم يبدأ بعد. '
             || 'ولا يستغرق التسجيل سوى دقائق معدودة، وهو مجاني دون أي عمولة على الأعمال التي تُرسى عليكم.'
             || E'\n\nللتسجيل، يُرجى الدخول إلى بوابة الموردين عبر الرابط التالي:\n\n' || v_link
           when 'started' then
             'نشكر لكم بدء تسجيل شركتكم مورِّدًا على منصة QuotesDone، ونودّ إفادتكم بأن طلب التسجيل لم يُستكمل بعد. '
             || 'ولا يستغرق استكماله سوى دقائق معدودة: بيانات الشركة، ورقم جوال وبريد إلكتروني موثَّقان، والرخصة التجارية، '
             || 'والملف التعريفي للشركة، والموافقة على شروط المورِّد.'
             || E'\n\nيمكنكم متابعة التسجيل من حيث توقفتم عبر الرابط التالي:\n\n' || v_link
           else
             'نفيدكم بأن طلب تسجيل شركتكم محفوظ لدينا، غير أنه ما زال ينقصه: ' || v_items_ar || '. '
             || 'ويُرجى استكماله في موعد أقصاه ' || v_due_ar || '، إذ يُغلق طلب التسجيل تلقائيًا بعد هذا التاريخ، ويمكنكم التسجيل من جديد في أي وقت.'
             || E'\n\nيمكنكم استكمال البنود المطلوبة عبر بوابة الموردين:\n\n' || v_link
         end
      || case when v_last then E'\n\nوهذا آخر تذكير نرسله إليكم بهذا الشأن.' else '' end
      || E'\n\nوفي حال عدم رغبتكم في تلقي هذه التذكيرات، يكفي الرد على هذه الرسالة لإزالة عنوانكم من القائمة.'
      || E'\n\nوتفضلوا بقبول فائق الاحترام والتقدير،';
  else
    v_greet := case when v_name is null then 'Dear Sir or Madam,' else 'Dear ' || v_name || ',' end;
    v_subj := case when v_last then 'A last reminder: ' else '' end
      || case p_stage when 'clicked' then 'your invitation to join QuotesDone as a founding supplier'
                      else 'complete your QuotesDone supplier registration' end;
    v_body := v_greet || E'\n\n'
      || case p_stage
           when 'clicked' then
             'Thank you for opening our invitation to join QuotesDone as a founding supplier. Your company has not registered yet. '
             || 'It takes a few minutes, it is free, and there is no commission on the work you win.'
             || E'\n\nTo register, open your supplier portal here:\n\n' || v_link
           when 'started' then
             'Thank you for starting to register your company as a supplier on QuotesDone. The registration is not finished yet. '
             || 'It takes a few minutes: company details, a verified mobile number and e-mail address, your trade licence, '
             || 'your company profile and acceptance of the supplier terms.'
             || E'\n\nContinue where you left off:\n\n' || v_link
           else
             'Your registration is saved, but it still needs: ' || v_items_en || '. '
             || 'Please complete it by ' || v_due_en || '; after that date the registration closes automatically, and you are welcome to start again at any time.'
             || E'\n\nComplete the missing items in your supplier portal:\n\n' || v_link
         end
      || case when v_last then E'\n\nThis is the last reminder we will send about it.' else '' end
      || E'\n\nIf you would rather not receive these reminders, reply to this e-mail and we will remove your address.';
  end if;
  return jsonb_build_object('lang', v_lang, 'subject', v_subj, 'body', v_body, 'link', v_link);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_registration_reminders_due()
 RETURNS TABLE(lead_id bigint, stage text, step integer, last_activity timestamp with time zone, to_email text, dedupe_key text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with s as (
    select l.id, lower(btrim(coalesce(nullif(btrim(l.claimed_by), ''), l.email))) as to_email,
           case when coalesce(l.approval_status, '') = 'action_required'
                     and l.exception_opened_at is not null and l.exception_closed_at is null
                     and coalesce(l.exception_due_at, 'infinity') > now() then 'incomplete'
                when coalesce(l.claimed, false) and l.registration_submitted_at is null
                     and coalesce(l.approval_status, '') not in ('approved', 'rejected', 'pending', 'action_required') then 'started'
                when not coalesce(l.claimed, false) and l.invite_clicked_at is not null then 'clicked'
           end as stage,
           case when coalesce(l.approval_status, '') = 'action_required'
                  then greatest(l.exception_opened_at, coalesce(l.portal_updated_at, l.exception_opened_at))
                when coalesce(l.claimed, false)
                  then coalesce(l.portal_updated_at, l.invite_clicked_at, l.invited_at, l.created_at)
                else l.invite_clicked_at end as last_activity,
           l as lead
      from public.leads l
     where l.invite_clicked_at is not null or coalesce(l.claimed, false) or l.approval_status = 'action_required'
  ), d as (
    select s.*, case when now() >= s.last_activity + interval '6 days' then 2
                     when now() >= s.last_activity + interval '2 days' then 1 end as step
      from s
     where s.stage is not null and s.last_activity is not null
       and now() < s.last_activity + interval '14 days'
  )
  select d.id, d.stage, d.step, d.last_activity, d.to_email,
         'supplier_registration_reminder:' || d.id || ':' || extract(epoch from d.last_activity)::bigint || ':' || d.step
    from d
   where d.step is not null
     and public.fn_supplier_outreach_reachable(d.lead, d.to_email)
     and not exists (select 1 from public.agent_actions a
                      where a.kind = 'handoff' and a.agent = 'customer_support'
                        and a.target_id = 'delivery.request:supplier_registration_reminder:' || d.id || ':'
                                          || extract(epoch from d.last_activity)::bigint || ':' || d.step)
   order by d.id
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_registration_state(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_exempt boolean; v_rank int; v_paid_until date; v_claimed boolean;
  v_fee numeric; v_ccy text; v_start date; v_free int;
  v_status text; v_due numeric; v_reason text;
begin
  select coalesce(l.subscription_exempt,false), l.founding_rank, l.subscription_paid_until, coalesce(l.claimed,false)
    into v_exempt, v_rank, v_paid_until, v_claimed
  from public.leads l where l.id = p_lead_id;
  if not found then
    return jsonb_build_object('ok', false, 'error', 'lead_not_found', 'lead_id', p_lead_id);
  end if;

  select coalesce(p.supplier_reg_fee,1000), coalesce(p.supplier_reg_currency,'AED'), p.supplier_charging_starts, coalesce(p.supplier_free_count,1000)
    into v_fee, v_ccy, v_start, v_free
  from public.pricing_config p where p.id = 1;
  v_fee := coalesce(v_fee,1000); v_ccy := coalesce(v_ccy,'AED'); v_free := coalesce(v_free,1000);

  if v_exempt then
    v_status := 'exempt'; v_due := 0;
    v_reason := 'founding rank ' || coalesce(v_rank::text,'(unranked)') || ' is inside the permanently exempt founding cohort';
  elsif v_paid_until is not null and v_paid_until >= current_date then
    v_status := 'paid'; v_due := 0;
    v_reason := 'subscription paid until ' || v_paid_until::text;
  elsif v_start is not null and current_date < v_start then
    v_status := 'not_due'; v_due := 0;
    v_reason := 'charging does not start until ' || v_start::text;
  elsif v_start is null and (v_rank is null or v_rank <= v_free) then
    v_status := 'not_due'; v_due := 0;
    v_reason := case when v_rank is null then 'founding rank not yet stamped (stamped at verification); the first ' || v_free || ' verified registrations are free and there is no calendar start date'
                     else 'founding rank ' || v_rank || ' is within the first ' || v_free || ' free registrations; charging starts with registration ' || (v_free + 1) || ', on no calendar date' end;
  else
    v_status := 'due'; v_due := v_fee;
    v_reason := case when v_paid_until is null then 'never paid' else 'subscription lapsed on ' || v_paid_until::text end;
  end if;

  return jsonb_build_object(
    'ok', true, 'lead_id', p_lead_id, 'status', v_status, 'fee_due', v_due, 'currency', v_ccy,
    'may_quote', (v_status <> 'due'), 'exempt', v_exempt, 'founding_rank', v_rank,
    'paid_until', v_paid_until, 'charging_starts', v_start, 'free_count', v_free, 'claimed', v_claimed, 'reason', v_reason);
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_safe_text(p_inquiry uuid, p_text text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_out   text := p_text;
  v_seeds text[];
  v_seed  text;
begin
  if p_text is null or btrim(p_text) = '' then return p_text; end if;

  select array_remove(array[
           nullif(btrim(c.full_name), ''),
           nullif(btrim(c.email), ''),
           nullif(btrim(c.phone), ''),
           nullif(btrim(pr.name), '')
         ], null)
    into v_seeds
    from public.inquiries i
    left join public.customers c on c.id = i.customer_id
    left join public.projects  pr on pr.id = i.project_id
   where i.id = p_inquiry;

  foreach v_seed in array coalesce(v_seeds, array[]::text[]) loop
    -- Four characters is the floor _shared/anonymise.ts uses: below it a "seed" is a fragment that
    -- would mangle ordinary trade words rather than hide anybody.
    if length(v_seed) >= 4 then
      v_out := regexp_replace(v_out, regexp_replace(v_seed, '([.*+?^${}()|\[\]\\])', '\\\1', 'g'), '[hidden]', 'gi');
    end if;
  end loop;

  return public.mask_project_identity(v_out);
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_sanctions_screen(p_run_ids bigint[], p_rehearsal_tag text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_reh boolean := p_rehearsal_tag is not null;
  v_suppliers int := 0; v_entries int := 0; v_new int := 0; v_leads_hit int := 0; v_open int := 0;
  v_sources text; r record; h record; v_task bigint; v_hold bigint; v_title text; v_hold_title text; v_hits text;
begin
  select string_agg(distinct source || ' (' || entries || ' entries, fetched ' || to_char(fetched_at, 'DD Mon YYYY HH24:MI') || ' UTC, sha256 ' || left(coalesce(sha256, '?'), 12) || ')', '; ')
    into v_sources from public.screening_run where id = any(p_run_ids);

  create temp table tmp_screen_sup on commit drop as
    select l.id, f.field, f.val, public.fn_screening_normalise(f.val) as norm, public.fn_screening_tokens(f.val) as toks
      from public.leads l
      cross join lateral (values ('legal_name', l.company_name), ('licence_name', l.name_corrected_from),
                                 ('owner', l.signatory_name), ('contact', l.contact_name),
                                 ('email_domain', split_part(coalesce(l.email_domain, split_part(coalesce(l.email, ''), '@', 2)), '.', 1))) f(field, val)
     where (l.lifecycle_stage = 'registered' or l.approval_status = 'approved')
       and case when v_reh then l.company_name like 'ZZ DEMO — %'
                else coalesce(l.company_name, '') not like 'ZZ DEMO — %' and coalesce(l.email, '') not ilike '%@example.invalid' end
       and nullif(btrim(coalesce(f.val, '')), '') is not null;
  select count(distinct id) into v_suppliers from tmp_screen_sup;
  select count(*) into v_entries from public.screening_entry where run_id = any(p_run_ids);

  for h in
    select s.id as lead_id, s.field, s.val, e.id as entry_id, e.run_id, e.name, e.source, coalesce(e.reference, '') as reference, e.entry_type,
           case when s.field = 'email_domain' or s.norm = e.name_norm then 'exact' else 'token_overlap' end as kind,
           case when s.field = 'email_domain' or s.norm = e.name_norm then 1.0
                else round(least(cardinality(s.toks), cardinality(e.tokens))::numeric / greatest(cardinality(s.toks), cardinality(e.tokens), 1), 2) end as score
      from tmp_screen_sup s
      join public.screening_entry e
        on e.run_id = any(p_run_ids)
       and ((s.field <> 'email_domain' and s.norm = e.name_norm and length(s.norm) >= 6)
         or (s.field <> 'email_domain' and cardinality(s.toks) >= 2 and cardinality(e.tokens) >= 2
             and (s.toks <@ e.tokens or e.tokens <@ s.toks))
         or (s.field = 'email_domain' and length(s.norm) >= 6 and replace(e.name_norm, ' ', '') = s.norm))
  loop
    insert into public.supplier_screening_hit (run_id, lead_id, field, supplier_value, entry_id, entry_name, entry_source, entry_reference, entry_type, match_kind, score)
    values (h.run_id, h.lead_id, h.field, h.val, h.entry_id, h.name, h.source, h.reference, h.entry_type, h.kind, h.score)
    on conflict (lead_id, entry_source, entry_reference, field) do nothing;
    if found then v_new := v_new + 1; end if;
  end loop;

  -- THE TEAM UPDATE, ON SEATS THAT EXIST (18 Sep 2026). One DECISION task on the ceo, because a confirmed
  -- hit removes a supplier and every approval in this company is the CEO's; one HOLD on the sales_engineer,
  -- because supplier verification and supplier-facing outreach are that seat's work. Never the founder.
  for r in
    select x.lead_id, l.company_name, count(*) as n,
           string_agg(format('%s %L matched %L [%s %s] %s, score %s', x.field, x.supplier_value, x.entry_name, x.entry_source, x.entry_reference, x.match_kind, x.score), E'\n' order by x.score desc, x.id) as ev,
           string_agg(x.id::text, ', ' order by x.id) as ids
      from public.supplier_screening_hit x join public.leads l on l.id = x.lead_id
     where x.status = 'open' and x.task_id is null and x.run_id = any(p_run_ids)
     group by x.lead_id, l.company_name
  loop
    v_title := 'Sanctions screening hit: ' || coalesce(r.company_name, 'lead #' || r.lead_id) || ' — lead #' || r.lead_id;
    select id into v_task from public.org_tasks where title = v_title and status not in ('done', 'cancelled') order by id limit 1;
    if v_task is null then
      insert into public.org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class, assigned_agent)
      values (null, v_title,
              'The weekly sanctions screening (' || coalesce(v_sources, 'fixture run') || ') matched a REGISTERED supplier. EVIDENCE:' || E'\n' || r.ev
              || E'\n\n' || 'No automatic removal has happened. Compare the supplier''s trade licence, owner and address against the listing and decide, per hit: '
              || 'select public.fn_supplier_screening_decide(<hit_id>, ''confirmed'' | ''false_positive'', ''ceo''). '
              || 'A confirmed hit moves the supplier through the existing status path (leads.banned + banned_reason, matching_blocked, approval_status rejected) and closes this task and the sales engineer''s hold; a false positive closes the hit. '
              || 'Hit id(s): ' || r.ids || '.',
              'assigned', 'supervised', false, 'compliance_check', 'ceo')
      returning id into v_task;
    end if;
    v_hold_title := 'Hold outreach and onboarding: ' || coalesce(r.company_name, 'lead #' || r.lead_id) || ' — lead #' || r.lead_id || ' (sanctions screening)';
    select id into v_hold from public.org_tasks where title = v_hold_title and status not in ('done', 'cancelled') order by id limit 1;
    if v_hold is null then
      insert into public.org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class, assigned_agent)
      values (null, v_hold_title,
              'The CEO is reviewing a sanctions-screening match on this supplier (task #' || v_task || '). Send no invitation, follow-up or onboarding step to lead #' || r.lead_id
              || ' until the CEO decides; this task closes with that decision.',
              'assigned', 'autonomous', false, 'coordinate', 'sales_engineer')
      returning id into v_hold;
    end if;
    update public.supplier_screening_hit set task_id = v_task, bd_task_id = v_hold
     where lead_id = r.lead_id and status = 'open' and task_id is null;
    v_leads_hit := v_leads_hit + 1;
  end loop;

  -- retention: the latest fetch per source is the list; older entries go (their run rows stay as the record)
  if not v_reh then
    delete from public.screening_entry e
     where e.run_id not in (select max(id) from public.screening_run where status = 'ok' group by source)
       -- SANCTIONS_EVIDENCE_KEPT (18 Sep 2026): an entry a hit cites is evidence, not a stale copy of
       -- the list. Kept here, and a00_entry_cited_is_kept refuses it for every other caller.
       and not exists (select 1 from public.supplier_screening_hit sh
                        where sh.entry_id = e.id or (sh.entry_source = e.source and sh.entry_reference = e.reference));
  end if;

  select count(*) into v_open from public.supplier_screening_hit where status = 'open';
  insert into public.agent_runs (agent, status, counts, note, started_at, finished_at)
  values ('supplier_sanctions_screen', 'ok',
          jsonb_build_object('suppliers', v_suppliers, 'entries', v_entries, 'hits_new', v_new, 'leads_hit', v_leads_hit, 'hits_open', v_open,
                             'runs', to_jsonb(p_run_ids), 'rehearsal', v_reh),
          'Sanctions screening: ' || v_suppliers || ' registered supplier(s) screened against ' || v_entries || ' list entries (' || coalesce(v_sources, 'no run') || '): '
          || v_new || ' new hit(s) on ' || v_leads_hit || ' supplier(s); ' || v_open || ' open. A hit opens ONE decision task on the ceo and ONE hold on the sales_engineer; nobody is removed automatically.'
          || case when v_reh then ' [rehearsal ' || p_rehearsal_tag || ']' else '' end, now(), now());
  return jsonb_build_object('suppliers', v_suppliers, 'entries', v_entries, 'hits_new', v_new, 'leads_hit', v_leads_hit, 'hits_open', v_open, 'sources', v_sources);
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_score_refresh()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  insert into supplier_score (lead_id, response_rate, avg_response_hours, quotes_submitted, quotes_won,
                              rejection_count, price_index, quality_rating, reliability, last_active, computed_at)
  select l.id,
         -- NO COALESCE. A null rv_response_rate means nobody has asked this supplier for anything,
         -- and 0% is a different claim entirely.
         l.rv_response_rate,
         null,
         coalesce(q.submitted, 0),
         coalesce(q.won, 0),
         coalesce(q.rejected, 0),
         q.price_index,
         -- QUALITY RATING IS EARNED ON THE PLATFORM, NOT SCRAPED FROM GOOGLE.
         -- Founder decision, 2026-08-08: rating exists only for VERIFIED suppliers, and comes from
         -- the customer's own 1-5 review after a job. leads.rating is the Google Maps star rating of
         -- a business we have never worked with; presenting it as a QuotesDone quality rating is a
         -- claim the platform has not earned. NULL when unverified or unreviewed -- an unrated
         -- supplier is unrated, and must never look like one every customer disliked.
         case when not coalesce(l.verified, false) then null
              else (select round(avg(rv.rating)::numeric * 20, 1)
                      from reviews rv where rv.supplier_id = l.id) end,
         -- Reliability: response behaviour dominates, win rate confirms it, rejections and refunds subtract.
         -- UNMEASURED IS NOT UNRELIABLE (12 Aug 2026). With no response history AND no quotes there is
         -- nothing to score, so this is NULL rather than 0 -- the same call the quality_rating comment
         -- above makes, and the same one fn_reputation_recompute now makes for employees. Note that
         -- verification alone must not manufacture a score either: the +20 below is a bonus on top of
         -- evidence, not evidence.
         case when l.rv_response_rate is null and coalesce(q.submitted, 0) = 0 then null
              else round(least(100, greatest(0,
                     coalesce(l.rv_response_rate,0) * 0.55
                   + (case when coalesce(q.submitted,0) > 0 then 100.0*coalesce(q.won,0)/q.submitted else 0 end) * 0.25
                   + (case when l.verified then 20 else 0 end)
                   - coalesce(q.rejected,0) * 2
                   - coalesce(l.rv_nonresponse_refunds,0) * 5
                 )), 1)
         end,
         greatest(l.portal_updated_at, l.approved_at, l.scraped_at),
         now()
  from leads l
  left join (
    select q.supplier_id,
           count(*) as submitted,
           count(*) filter (where q.status = 'won')      as won,
           count(*) filter (where q.status = 'rejected') as rejected,
           round(avg(q.quote_amount) filter (where q.quote_amount > 0), 2) as price_index
    from quotes q group by q.supplier_id
  ) q on q.supplier_id = l.id
  where l.id is not null
  on conflict (lead_id) do update set
    response_rate = excluded.response_rate, quotes_submitted = excluded.quotes_submitted,
    quotes_won = excluded.quotes_won, rejection_count = excluded.rejection_count,
    price_index = excluded.price_index, quality_rating = excluded.quality_rating,
    reliability = excluded.reliability, last_active = excluded.last_active, computed_at = now();
  get diagnostics n = row_count;
  return n;
end; $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_screening_decide(p_hit_id bigint, p_decision text, p_actor text DEFAULT 'ceo'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare h record; l record; v_open int; v_closed int := 0; t bigint; v jsonb;
begin
  if p_decision not in ('confirmed', 'false_positive') then
    raise exception 'fn_supplier_screening_decide: decision must be confirmed or false_positive, not %', p_decision;
  end if;
  select * into h from public.supplier_screening_hit where id = p_hit_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no such hit ' || p_hit_id); end if;
  if h.status <> 'open' then return jsonb_build_object('ok', false, 'reason', 'hit ' || p_hit_id || ' is already ' || h.status); end if;

  update public.supplier_screening_hit set status = p_decision, decided_by = p_actor, decided_at = now() where id = p_hit_id;

  if p_decision = 'confirmed' then
    select * into l from public.leads where id = h.lead_id;
    -- THE REGISTER FIRST. Every refusal below and in the surfaces asks public.sanctions_ban, so it
    -- has to exist before the leads UPDATE fires a00_leads_sanctioned_row_is_permanent.
    insert into public.sanctions_ban
      (lead_id, hit_id, entry_source, entry_reference, entry_name, name_key, licence_key,
       account_email, contact_email, decided_by, note)
    values (h.lead_id, p_hit_id, h.entry_source, h.entry_reference, h.entry_name,
            public.fn_screening_normalise(l.company_name),
            public.fn_sanctions_identity_key(l.trade_license_no),
            nullif(lower(btrim(coalesce(l.claimed_by, ''))), ''),
            nullif(lower(btrim(coalesce(l.email, ''))), ''),
            p_actor,
            'Confirmed sanctions hit on ' || h.entry_source || ' ' || h.entry_reference
            || ' (' || h.entry_name || ') matched ' || h.field || ' "' || coalesce(h.supplier_value, '') || '".')
    on conflict (lead_id) do nothing;
    -- do nothing, not do update: one register row per party, written by the FIRST confirmed hit.
    -- A second confirmed hit on the same party changes nothing here on purpose — the register says
    -- WHO is banned, and public.supplier_screening_hit, which is append-only from today, holds every
    -- entry that was ever matched. The audit trail is the join, not this row alone.

    -- the same columns fn_ban_overdue_dues writes: banned + reason, matching blocked, and the approval withdrawn
    update public.leads
       set banned = true,
           banned_reason = 'Sanctions screening hit confirmed by ' || p_actor || ' on ' || to_char(now(), 'DD Mon YYYY') || ': '
                           || h.entry_source || ' ' || h.entry_reference || ' (' || h.entry_name || ') matched ' || h.field || ' "' || coalesce(h.supplier_value, '') || '".',
           matching_blocked = true,
           matching_block_reason = 'Banned: sanctions screening hit confirmed (' || h.entry_source || ')',
           approval_status = case when approval_status = 'approved' then 'rejected' else approval_status end,
           rejection_reason = coalesce(rejection_reason, 'sanctions screening hit confirmed'),
           -- THE FRONT DOORS. claim_token is NOT NULL with a default, so the link is ROTATED
           -- rather than cleared: /{lang}/portal?t=<the token in the invitation e-mail> stops
           -- resolving, and the new value has never been sent to anybody. claimed goes false so no
           -- account continues to own the row.
           claim_token = gen_random_uuid(),
           claimed = false
     where id = h.lead_id;
    -- every other open hit on the same supplier is decided by the same fact
    update public.supplier_screening_hit set status = 'confirmed', decided_by = p_actor, decided_at = now()
     where lead_id = h.lead_id and status = 'open';

    -- THE SESSION THEY ALREADY HOLD (security review, 18 Sep 2026). login_otp refuses to MINT a
    -- session for a sanctioned party, and supplier_api / supplier_portal / kyc / supplier_pay /
    -- supplier_catalog_ingest re-ask on every request, so a token issued five minutes before the
    -- ban buys nothing. This closes the last of it at the identity provider itself: GoTrue refuses
    -- both sign-in and refresh for a user whose banned_until is in the future. Measured 18 Sep
    -- 2026: this function is owned by postgres, and has_table_privilege('postgres','auth.users',
    -- 'update') is true, so this line cannot fail for want of rights -- if it ever did, the whole
    -- decision would roll back rather than half-land, which is the correct failure.
    update auth.users u
       set banned_until = 'infinity'::timestamptz
     where lower(u.email) in (nullif(lower(btrim(coalesce(l.claimed_by, ''))), ''),
                              nullif(lower(btrim(coalesce(l.email, ''))), ''));
  end if;

  select count(*) into v_open from public.supplier_screening_hit where lead_id = h.lead_id and status = 'open';
  if v_open = 0 then
    foreach t in array array_remove(array[h.task_id, h.bd_task_id], null) loop
      v := public.fn_org_task_close_as_fact(t, p_actor,
             case when p_decision = 'confirmed'
                  then 'Sanctions screening hit CONFIRMED by ' || p_actor || ': ' || h.entry_source || ' ' || h.entry_reference || ' (' || h.entry_name || '). The supplier (lead #' || h.lead_id || ') is PERMANENTLY banned and recorded in public.sanctions_ban: not matched, not invited, not messaged, not shown, unable to sign in, and the name and trade licence cannot register again. The record is retained and sealed.'
                  else 'Sanctions screening hit reviewed by ' || p_actor || ' and recorded as a FALSE POSITIVE: ' || h.entry_source || ' ' || h.entry_reference || ' (' || h.entry_name || ') is not lead #' || h.lead_id || '. No status change; outreach and onboarding may continue.' end,
             jsonb_build_object('hit_id', p_hit_id, 'decision', p_decision, 'lead_id', h.lead_id, 'owner', p_actor));
      if coalesce((v ->> 'ok')::boolean, false) then v_closed := v_closed + 1; end if;
    end loop;
  end if;
  return jsonb_build_object('ok', true, 'hit_id', p_hit_id, 'decision', p_decision, 'lead_id', h.lead_id,
                            'open_hits_left', v_open, 'tasks_closed', v_closed,
                            'sanctions_ban', p_decision = 'confirmed');
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_stats(p_supplier_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v jsonb; v_quotes int; v_reveals int; v_hired int; v_lost int;
  v_qd_rev numeric; v_deal_val numeric; v_avg_lead numeric;
  v_pos jsonb; v_hist jsonb; v_rating numeric; v_rating_pct numeric; v_resp numeric;
  v_pending_reviews int; v_active_rfqs int;
begin
  select count(*) into v_quotes from quotes where supplier_id=p_supplier_id;
  select count(*) into v_reveals from transactions where supplier_id=p_supplier_id;
  select count(*) into v_hired from inquiries where hired_supplier_id=p_supplier_id;
  select count(*) into v_lost from inquiries i
     where i.hired_supplier_id is not null and i.hired_supplier_id<>p_supplier_id
       and exists (select 1 from quotes q where q.inquiry_id=i.id and q.supplier_id=p_supplier_id);
  select coalesce(sum(coalesce(reveal_fee,0)+coalesce(app_fee,0)),0),
         coalesce(sum(coalesce(quote_amount,0)),0)
    into v_qd_rev, v_deal_val
    from transactions where supplier_id=p_supplier_id and coalesce(refund_status,'')<>'approved';
  select round(avg(nullif(regexp_replace(coalesce(lead_time,''),'[^0-9.]','','g'),'')::numeric),1)
    into v_avg_lead from quotes where supplier_id=p_supplier_id and lead_time ~ '[0-9]';
  select app_rating, rv_response_rate into v_rating, v_resp from leads where id=p_supplier_id;
  if v_rating is not null then
    select round(100.0*(count(*) filter (where l2.app_rating <= v_rating))/nullif(count(*),0),0)
      into v_rating_pct
      from leads l2 where l2.sector = (select sector from leads where id=p_supplier_id) and l2.app_rating is not null;
  end if;
  select count(*) into v_pending_reviews from quotes where supplier_id=p_supplier_id and coalesce(review_status,'')='pending';
  select count(distinct q.inquiry_id) into v_active_rfqs from quotes q join inquiries i on i.id=q.inquiry_id
    where q.supplier_id=p_supplier_id and coalesce(i.status,'') in ('open','active','collecting','live');
  with myq as (select inquiry_id, quote_amount from quotes where supplier_id=p_supplier_id and quote_amount is not null and quote_amount>0),
  peer as (select inquiry_id, min(quote_amount) lo, avg(quote_amount) av, count(*) n
             from quotes where quote_amount is not null and quote_amount>0 group by inquiry_id),
  pos as (select m.quote_amount, p.lo, p.av,
                 case when p.lo>0 then (m.quote_amount-p.lo)/p.lo*100 end pct_low,
                 case when p.av>0 then (m.quote_amount-p.av)/p.av*100 end pct_avg,
                 (m.quote_amount<=p.lo*1.0001) as is_lowest
            from myq m join peer p using(inquiry_id) where p.n>=2)
  select jsonb_build_object('competitive_rfqs', count(*),'times_lowest', count(*) filter (where is_lowest),
    'lowest_rate', round(100.0*count(*) filter (where is_lowest)/nullif(count(*),0),0),
    'avg_pct_above_lowest', round(avg(pct_low)::numeric,1),'avg_pct_vs_average', round(avg(pct_avg)::numeric,1),
    'band', case when count(*)=0 then 'not enough data' when avg(pct_avg) <= -4 then 'below market average'
                 when avg(pct_avg) < 5 then 'around market average' else 'above market average' end
  ) into v_pos from pos;
  with months as (select date_trunc('month', (now() - (n||' month')::interval)) m from generate_series(0,11) n),
  qb as (select date_trunc('month',created_at) m, count(*) c from quotes where supplier_id=p_supplier_id group by 1),
  rb as (select date_trunc('month',revealed_at) m, count(*) c from transactions where supplier_id=p_supplier_id group by 1)
  select jsonb_agg(jsonb_build_object('month', to_char(months.m,'Mon YY'),'quotes', coalesce(qb.c,0), 'reveals', coalesce(rb.c,0)) order by months.m)
    into v_hist from months left join qb on qb.m=months.m left join rb on rb.m=months.m;
  v := jsonb_build_object('supplier_id', p_supplier_id,'quotes_total', v_quotes,'reveals', v_reveals,'hired', v_hired,
    'lost_to_others', v_lost,'win_ratio', round(100.0*v_hired/nullif(v_quotes,0),1),'reveal_ratio', round(100.0*v_reveals/nullif(v_quotes,0),1),
    'qd_revenue', v_qd_rev,'deal_value_awarded', v_deal_val,'avg_lead_time_days', v_avg_lead,'rating', v_rating,
    'rating_percentile', v_rating_pct,'response_rate', v_resp,'pending_reviews', v_pending_reviews,'active_rfqs', v_active_rfqs,
    'price_positioning', v_pos,'history_12m', v_hist,'document_expiries', fn_supplier_expiries(p_supplier_id));
  return v;
end $function$


CREATE OR REPLACE FUNCTION public.fn_supplier_subscription()
 RETURNS TABLE(fee numeric, currency text, period text, start_date date, free_limit integer, fee_source text, start_source text, free_source text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with pc as (select * from public.pricing_config order by id limit 1),
       s as (
         select
           (select nullif(value,'')::numeric from public.app_secrets where key='supplier_subscription_aed')  as fee,
           (select nullif(value,'')::int     from public.app_secrets where key='founding_free_limit')         as free_limit
       )
  select
    coalesce((select supplier_reg_fee::numeric from pc), (select fee from s), 1000)                as fee,
    coalesce((select supplier_reg_currency from pc), 'AED')                                        as currency,
    coalesce((select supplier_reg_period   from pc), 'yearly')                                     as period,
    (select supplier_charging_starts from pc)                                                      as start_date,
    coalesce((select supplier_free_count from pc), (select free_limit from s), 1000)               as free_limit,
    case when (select supplier_reg_fee from pc) is not null then 'pricing_config'
         when (select fee from s) is not null then 'app_secrets' else 'default' end                as fee_source,
    case when (select supplier_charging_starts from pc) is not null then 'pricing_config'
         else 'no date: charging starts with the registration after the free count (founder, 6 Sep 2026)' end as start_source,
    case when (select supplier_free_count from pc) is not null then 'pricing_config'
         when (select free_limit from s) is not null then 'app_secrets' else 'default' end         as free_source;
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_tier(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with l as (
    select coalesce(verified, false) verified, rv_response_rate
      from public.leads where id = p_lead_id
  ),
  q as (
    select count(*)::int submitted,
           count(*) filter (where status = 'won')::int won_by_status
      from public.quotes where supplier_id = p_lead_id
  ),
  h as (
    select count(*)::int hired from public.inquiries where hired_supplier_id = p_lead_id
  ),
  s as (
    select (select submitted from q) submitted,
           greatest((select won_by_status from q), (select hired from h)) won,
           (select rv_response_rate from l) response_rate,
           -- NULL until a verified supplier has been reviewed: an unrated supplier is unrated.
           case when (select verified from l)
                then (select round(avg(rating)::numeric * 20, 1) from public.reviews where supplier_id = p_lead_id)
                else null end quality_rating
  ),
  -- ACTIVITY IS THE GATE. A supplier who has never quoted has no performance to measure.
  a as (select coalesce((select submitted from s), 0) > 0 active),
  t as (
    select case
      when not (select active from a) then 'unranked'
      when (select won from s) >= 10 and coalesce((select quality_rating from s), 0) >= 85 then 'platinum'
      when (select won from s) >= 5  and coalesce((select quality_rating from s), 0) >= 70 then 'gold'
      when (select won from s) >= 1                                                        then 'silver'
      else 'bronze'
    end tier
  )
  select jsonb_build_object(
    'lead_id', p_lead_id,
    'tier', (select tier from t),
    -- available:false is the difference between "we ranked you low" and "we cannot rank you yet".
    'available', (select active from a),
    'basis', case when (select active from a)
                  then 'quotes won and quality rating, from your quotes and reviews on QuotesDone'
                  else 'no quote has been submitted yet, so there is nothing to rank — this is not a low score' end,
    'basis_ar', case when (select active from a)
                  then 'الأعمال التي فزتم بها وتقييم الجودة، استنادًا إلى عروضكم وتقييماتكم على QuotesDone'
                  else 'لم تُقدَّم أي عروض أسعار بعد، فلا يوجد ما يُصنَّف، وهذا لا يعني تقييمًا منخفضًا' end,
    'ladder', jsonb_build_array(
      jsonb_build_object('tier','bronze',  'needs','submit your first quote',                              'needs_ar','قدّم أول عرض سعر'),
      jsonb_build_object('tier','silver',  'needs','win 1 job',                                            'needs_ar','فُز بعمل واحد'),
      jsonb_build_object('tier','gold',    'needs','win 5 jobs and hold a 70% quality rating',             'needs_ar','فُز بخمسة أعمال مع الحفاظ على تقييم جودة 70%'),
      jsonb_build_object('tier','platinum','needs','win 10 jobs and hold an 85% quality rating',           'needs_ar','فُز بعشرة أعمال مع الحفاظ على تقييم جودة 85%')
    ),
    'progress', jsonb_build_object(
      'quotes_submitted', (select submitted from s),
      'quotes_won', (select won from s),
      'quality_rating', (select quality_rating from s),
      'response_rate', (select response_rate from s)
    ),
    -- THE TIER DOES NOT AFFECT MATCHING. Founder, 2026-08-08: "a tier shouldnt effect a match."
    'benefits_active', false,
    'affects_matching', false,
    'benefits_note', 'Your tier never affects which work you are matched to, how you rank in search, '
      || 'or whether you are shown as preferred. Every supplier is matched on fit alone. '
      || 'This is a record of your track record, not a queue position.',
    'benefits_note_ar', 'لا يؤثر تصنيفكم إطلاقًا في الأعمال التي تُطابَقون معها، ولا في ترتيبكم في نتائج البحث، '
      || 'ولا في إبرازكم مورّدًا مفضّلًا؛ فكل مورّد يُطابَق وفق مدى الملاءمة وحدها. '
      || 'إنه سجلّ لأدائكم، لا ترتيب في طابور.'
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_twin(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with l as (select * from public.leads where id = p_lead_id),
  s as (select *, quality_rating as q_pct from public.supplier_score where lead_id = p_lead_id),
  -- THE SUPPLIER'S OWN QUOTES, not the cache (#761): counted from public.quotes every time.
  q as (
    select count(*)::int submitted,
           greatest(count(*) filter (where status = 'won')::int,
                    (select count(*)::int from public.inquiries where hired_supplier_id = p_lead_id)) won
    from public.quotes where supplier_id = p_lead_id
  ),
  home as (select * from public.fn_supplier_document_home(p_lead_id)),
  caps as (
    select
      (select coalesce(jsonb_array_length(case when jsonb_typeof(l.machinery)='array' then l.machinery else '[]'::jsonb end), 0) > 0
              or l.capability_summary ilike '%manufactur%' from l)          as manufacturing,
      (select coalesce(l.engineers_count, 0) > 0
              or l.capability_summary ilike '%install%' from l)             as installation,
      (select l.capability_summary ilike '%maintenance%'
              or l.capability_summary ilike '%service%' from l)             as maintenance,
      (select l.capability_summary ilike '%design%' from l)                 as design
  ),
  conf as (
    select round(100.0 * (
        (case when l.company_name       is not null then 1 else 0 end)
      + (case when l.sector             is not null then 1 else 0 end)
      + (case when l.capability_summary is not null then 1 else 0 end)
      + (case when l.founded_year        is not null then 1 else 0 end)
      + (case when l.employee_count      is not null or l.team_size is not null then 1 else 0 end)
      + (case when coalesce(array_length(l.service_emirates, 1), 0) > 0 then 1 else 0 end)
      + (case when coalesce(l.certifications, '') <> ''
                or (jsonb_typeof(l.iso_certifications)='array' and jsonb_array_length(l.iso_certifications) > 0) then 1 else 0 end)
      + (case when l.products is not null and l.products <> '' then 1 else 0 end)
      + (case when l.website is not null then 1 else 0 end)
      + (case when l.description is not null then 1 else 0 end)
      ) / 10.0) as pct
    from l
  ),
  -- RISK IS A VERDICT, so it needs a measurement: a licence on file (its expiry is the estate's own
  -- block reason), a ban or a block, a strike, or a computed reliability. With none of these the
  -- honest answer is NULL, and risk_basis says what would produce one.
  risk as (
    select case
      when l.banned then 'BANNED'
      when l.matching_blocked then 'BLOCKED'
      when (select path from home where key = 'trade_licence') is null
           and coalesce(l.chat_strikes, 0) = 0 and (select reliability from s) is null then null
      when l.license_expiry is not null and l.license_expiry < current_date then 'HIGH'
      when (select expiry from home where key = 'iso') < current_date then 'HIGH'
      when l.license_expiry is not null and l.license_expiry < current_date + 60 then 'MEDIUM'
      when coalesce(l.chat_strikes, 0) > 0 then 'MEDIUM'
      when (select reliability from s) is not null and (select reliability from s) < 60 then 'MEDIUM'
      else 'LOW' end as level
    from l
  )
  select jsonb_build_object(
    'lead_id', p_lead_id,
    'company_name', (select company_name from l),
    'verified', (select coalesce(verified, false) from l),
    'approval_status', (select approval_status from l),
    'intelligence_score', (
      select round(avg(v)) from (
        select (select q_pct from s) as v
        union all select (select reliability    from s)
        union all select (select response_rate  from s)
        union all select (select price_index    from s)
      ) t where v is not null
    ),
    'star_rating', (
      select case when avg(v) is null then null else greatest(1, least(5, round(avg(v) / 20.0))) end
      from (
        select (select q_pct from s) as v
        union all select (select reliability   from s)
        union all select (select response_rate from s)
      ) t where v is not null
    ),
    'health', jsonb_build_object(
      'quality', (select q_pct from s),
      'quality_raw',   (select quality_rating from s),
      'quality_scale', (select case when quality_rating is null then 'unrated' else 'earned_pct' end from s),
      'delivery', (select reliability    from s),
      'response', coalesce((select response_rate from s), (select rv_response_rate from l)),
      'pricing',  (select price_index    from s),
      'overall', (
        select round(avg(v)) from (
          select (select q_pct from s) as v
          union all select (select reliability   from s)
          union all select (select response_rate from s)
          union all select (select price_index   from s)
        ) t where v is not null
      ),
      'computed_at',        (select computed_at        from s),
      'avg_response_hours', (select avg_response_hours from s),
      'quotes_submitted',   (select submitted from q),
      'quotes_won',         (select won from q)
    ),
    'company_strength', (select capability_score from l),
    'capabilities', (
      select jsonb_build_array(
        jsonb_build_object('name', 'Manufacturing', 'has', (select manufacturing from caps)),
        jsonb_build_object('name', 'Installation',  'has', (select installation  from caps)),
        jsonb_build_object('name', 'Maintenance',   'has', (select maintenance   from caps)),
        jsonb_build_object('name', 'Design',        'has', (select design        from caps))
      )
    ),
    'product_count', (
      select case when l.products is null or l.products = '' then 0
             else array_length(string_to_array(l.products, ','), 1) end from l
    ),
    'certifications', (
      select (case when jsonb_typeof(l.iso_certifications)='array' then l.iso_certifications else '[]'::jsonb end)
          || (case when coalesce(l.certifications,'') = '' then '[]'::jsonb
                   else to_jsonb(string_to_array(l.certifications, ',')) end) from l
    ),
    'production_capacity', (
      select jsonb_build_object(
        'estimated', case
          when l.team_size is null and l.engineers_count is null and l.warehouse_area is null then null
          else coalesce(l.team_size, 0) * 40 + coalesce(l.engineers_count, 0) * 120
               + coalesce(round(nullif(regexp_replace(coalesce(l.warehouse_area,''), '[^0-9]', '', 'g'), '')::numeric / 10.0), 0) end,
        'is_estimate', true,
        'basis', jsonb_build_object('team_size', l.team_size, 'engineers', l.engineers_count,
                                    'warehouse_area', l.warehouse_area,
                                    'machinery_lines', coalesce(jsonb_array_length(case when jsonb_typeof(l.machinery)='array' then l.machinery else '[]'::jsonb end), 0))
      ) from l
    ),
    'best_opportunities', (
      select case when coalesce(l.categories,'') = '' then '[]'::jsonb
                  else to_jsonb(string_to_array(l.categories, ',')) end from l
    ),
    'risk_level', (select level from risk),
    'risk_basis', case when (select level from risk) is null
                       then 'not assessed: no trade licence on file and no history yet'
                       else 'trade licence and certificate expiry, bans, strikes and computed reliability' end,
    'established_year', (select founded_year from l),
    'employee_count',   (select coalesce(l.employee_count, l.team_size) from l),
    -- The emirates the supplier serves. `countries` is kept for older clients; same value.
    'emirates',         (select coalesce(to_jsonb(coalesce(l.service_emirates, '{}'::text[])), '[]'::jsonb) from l),
    'countries',        (select coalesce(to_jsonb(coalesce(l.service_emirates, '{}'::text[])), '[]'::jsonb) from l),
    'ai_confidence',    (select pct from conf),
    'capability_map', (
      select jsonb_build_object(
        'root', coalesce(l.sector, 'Supplier'),
        'children', (
          select jsonb_agg(jsonb_build_object('name', c.name))
          from (
            select 'Manufacturing' as name where (select manufacturing from caps)
            union all select 'Installation' where (select installation from caps)
            union all select 'Maintenance'  where (select maintenance  from caps)
            union all select 'Design'       where (select design       from caps)
          ) c
        )
      ) from l
    ),
    -- Per-document status from the ONE home, so this cannot disagree with Documents or Certifications.
    'documents', (
      select jsonb_agg(jsonb_build_object(
        'kind', case h.key when 'trade_licence' then 'Trade licence' when 'iso' then 'ISO certification' else 'Manufacturer authorisation' end,
        'key', h.key, 'expiry', h.expiry, 'source', h.source,
        'doc_status', case when h.path is null then 'MISSING'
                           when h.expiry is null then 'UNDATED'
                           when h.expiry < current_date then 'EXPIRED'
                           else 'VALID' end)
        order by case h.key when 'trade_licence' then 0 when 'iso' then 1 else 2 end)
      from home h where h.key in ('trade_licence', 'iso', 'manufacturer_auth')
    ),
    'is_demo', (select coalesce(l.matching_blocked, false)
                       and coalesce(array_to_string(l.tags, ','), '') ilike '%demo%' from l),
    'matchable', (select public.fn_is_matchable(l.verified, l.banned, l.matching_blocked,
                          l.approval_status, l.permanently_closed, l.chat_strikes) from l)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_supplier_workspaces(p_lead_id bigint)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with rel as (
    select distinct i.id as inquiry_id
    from public.inquiries i
    where exists (select 1 from public.inquiry_matches m
                  where m.inquiry_id = i.id and m.supplier_id = p_lead_id)
       or exists (select 1 from public.messages g
                  where g.inquiry_id = i.id and g.supplier_id = p_lead_id)
  )
  select jsonb_build_object(
    'lead_id', p_lead_id,
    'count', (select count(*) from rel),
    -- MATCHED TO ME, and nothing about the estate (review of #854: the same estate-wide count that was
    -- removed from fn_supplier_opportunities was still published here).
    'population', jsonb_build_object(
      'matches_for_me', (select count(*) from public.inquiry_matches where supplier_id = p_lead_id),
      'messaged_me', (select count(distinct inquiry_id) from public.messages where supplier_id = p_lead_id)
    ),
    'note', case when (select count(*) from rel) = 0
                 then 'no customer relationships yet — nothing has been matched or messaged'
                 else null end,
    'workspaces', (
      select coalesce(jsonb_agg(w order by w->>'last_activity' desc nulls last), '[]'::jsonb)
      from (
        select jsonb_build_object(
          'inquiry_id', i.id,
          'project', jsonb_build_object(
            -- THE TITLE IS A CUSTOMER'S OWN SENTENCE (22 Sep 2026, SP-N-05). It used to be i.summary,
            -- the raw column, printed at the top of the workspace before the reveal was paid for —
            -- the one place in the portal that read around the masking and the reveal gate at once.
            -- Post-reveal this supplier has paid for the customer's identity, so the unmasked summary
            -- is theirs to read; before it, the masked column through the inbox's seed scrub.
            'title', case when exists (select 1 from public.transactions t
                                        where t.inquiry_id = i.id and t.supplier_id = p_lead_id)
                          then coalesce(nullif(btrim(coalesce(i.summary, '')), ''), i.category,
                                        'RFQ ' || coalesce(i.rfq_no::text, i.id::text))
                          else coalesce(nullif(btrim(coalesce(public.fn_supplier_safe_text(i.id, i.summary_masked), '')), ''), i.category,
                                        'RFQ ' || coalesce(i.rfq_no::text, i.id::text)) end,
            'category', i.category,
            'emirate', i.emirate,
            'status', i.status,
            'created_at', i.created_at
          ),
          'files', (
            select coalesce(jsonb_agg(jsonb_build_object(
              'name', d.file_name, 'kind', d.kind, 'created_at', d.created_at,
              'category', case
                when d.kind ~* 'drawing|dwg|plan|layout'        then 'drawings'
                when d.kind ~* 'spec|datasheet|boq|schedule'    then 'specifications'
                when d.kind ~* 'contract|agreement|po|purchase' then 'contracts'
                else 'other' end
            ) order by d.created_at desc), '[]'::jsonb)
            from public.documents d
            where d.ref_table = 'inquiries' and d.ref_id = i.id::text
          ),
          'file_categories', (
            select jsonb_build_object(
              'drawings', count(*) filter (where d.kind ~* 'drawing|dwg|plan|layout'),
              'specifications', count(*) filter (where d.kind ~* 'spec|datasheet|boq|schedule'),
              'contracts', count(*) filter (where d.kind ~* 'contract|agreement|po|purchase'),
              'other', count(*) filter (where d.kind !~* 'drawing|dwg|plan|layout|spec|datasheet|boq|schedule|contract|agreement|po|purchase')
            )
            from public.documents d
            where d.ref_table = 'inquiries' and d.ref_id = i.id::text
          ),
          'message_count', (
            select count(*) from public.messages g
            where g.inquiry_id = i.id and g.supplier_id = p_lead_id and not coalesce(g.blocked, false)
          ),
          'unread', (
            select count(*) from public.messages g
            where g.inquiry_id = i.id and g.supplier_id = p_lead_id
              and g.sender = 'customer' and not coalesce(g.read_by_supplier, false)
              and not coalesce(g.blocked, false)
          ),
          'last_activity', (
            select max(g.created_at) from public.messages g
            where g.inquiry_id = i.id and g.supplier_id = p_lead_id
          ),
          'timeline', (
            select jsonb_build_object(
              'pct', case when total = 0 then null else round(100.0 * hit / total) end,
              'stages', jsonb_build_object(
                'matched', matched, 'messaged', messaged, 'quoted', quoted, 'awarded', awarded)
            )
            from (
              select 4 as total,
                (exists (select 1 from public.inquiry_matches m where m.inquiry_id = i.id and m.supplier_id = p_lead_id))::int
                  as matched,
                (exists (select 1 from public.messages g where g.inquiry_id = i.id and g.supplier_id = p_lead_id))::int
                  as messaged,
                (exists (select 1 from public.quotes q where q.inquiry_id = i.id and q.supplier_id = p_lead_id))::int
                  as quoted,
                (exists (select 1 from public.quotes q where q.inquiry_id = i.id and q.supplier_id = p_lead_id
                         and q.status = 'won'))::int as awarded
            ) s, lateral (select (s.matched + s.messaged + s.quoted + s.awarded) as hit) h
          )
        ) as w
        from rel r join public.inquiries i on i.id = r.inquiry_id
      ) t
    )
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_suppliers_board(p_search text DEFAULT ''::text, p_sector text DEFAULT ''::text, p_limit integer DEFAULT 60, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare out jsonb;
begin
  with base as (
    select l.id, l.company_name,
      coalesce(nullif(trim(l.sector),''),'general') as sector,
      coalesce(nullif(trim(l.emirate),''),'—') as emirate,
      l.app_rating as rating,
      l.verified, (l.approved_at is not null) as approved, l.banned,
      (l.invited_at is not null) as invited, l.claimed, (l.registration_submitted_at is not null) as registered,
      coalesce(l.capability_score,0) as capability_score, l.created_at,
      case when l.approved_at is not null then 'approved' when l.verified then 'verified'
           when l.registration_submitted_at is not null then 'registered' when l.invited_at is not null then 'invited'
           when l.contacted then 'contacted' else 'sourced' end as stage
    from leads l
    where (coalesce(p_search,'') = '' or l.company_name ilike '%'||p_search||'%' or l.sector ilike '%'||p_search||'%' or l.emirate ilike '%'||p_search||'%')
      and (coalesce(p_sector,'') = '' or l.sector = p_sector)
  ),
  ranked as (select *, row_number() over (partition by stage order by created_at desc, id desc) as rn from base),
  stagecounts as (select stage, count(*) as c from base group by stage)
  select jsonb_build_object(
    'total', (select count(*) from base),
    'stages', (
      select jsonb_agg(jsonb_build_object('key', s.key, 'label', s.label,
        'count', coalesce((select c from stagecounts sc where sc.stage=s.key),0),
        'cards', coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'company_name',r.company_name,'sector',r.sector,'emirate',r.emirate,'rating',r.rating,'verified',r.verified,'approved',r.approved,'banned',r.banned,'capability_score',r.capability_score) order by r.rn) from ranked r where r.stage=s.key and r.rn<=12),'[]'::jsonb))
        order by s.ord)
      from (values ('sourced','Sourced',1),('contacted','Contacted',2),('invited','Invited',3),('registered','Registered',4),('verified','Verified',5),('approved','Approved',6)) s(key,label,ord)
    ),
    'rows', (select coalesce(jsonb_agg(jsonb_build_object('id',b.id,'company_name',b.company_name,'sector',b.sector,'emirate',b.emirate,'rating',b.rating,'verified',b.verified,'approved',b.approved,'banned',b.banned,'invited',b.invited,'registered',b.registered,'stage',b.stage,'capability_score',b.capability_score,'created_at',b.created_at) order by b.created_at desc, b.id desc),'[]'::jsonb)
             from (select * from base order by created_at desc, id desc limit greatest(1,least(p_limit,200)) offset greatest(0,p_offset)) b),
    'sectors', (select coalesce(jsonb_agg(jsonb_build_object('label',x.sector,'n',x.n) order by x.n desc),'[]'::jsonb) from (select sector, count(*) n from base group by sector order by count(*) desc limit 12) x)
  ) into out;
  return out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_anonymity_scan(p_text text, p_subject text, p_attachment_ref text, p_supplier_lead_id bigint, p_quote_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  s record; v_hay text; v_hits text[] := '{}'; v_digits text;
begin
  v_hay := lower(coalesce(p_text,'') || ' ' || coalesce(p_subject,'') || ' ' || coalesce(p_attachment_ref,''));

  select company_name, email, phone, trade_license_no into s from public.leads where id = p_supplier_lead_id;
  if not found then
    return jsonb_build_object('safe', false, 'reason',
      'the supplier row could not be read, so nothing about it could be checked for', 'hits', '[]'::jsonb);
  end if;

  if coalesce(btrim(s.company_name),'') <> '' and position(lower(btrim(s.company_name)) in v_hay) > 0
    then v_hits := array_append(v_hits, 'company_name'); end if;
  if coalesce(btrim(s.email),'') <> '' and position(lower(btrim(s.email)) in v_hay) > 0
    then v_hits := array_append(v_hits, 'email'); end if;
  v_digits := regexp_replace(coalesce(s.phone,''), '[^0-9]', '', 'g');
  if length(v_digits) >= 7 and position(v_digits in regexp_replace(v_hay, '[^0-9]', '', 'g')) > 0
    then v_hits := array_append(v_hits, 'phone'); end if;
  if coalesce(btrim(s.trade_license_no),'') <> '' and position(lower(btrim(s.trade_license_no)) in v_hay) > 0
    then v_hits := array_append(v_hits, 'trade_license_no'); end if;

  if p_quote_id is not null then
    if exists (select 1 from public.quotes q
                where q.id::text = p_quote_id and q.quote_amount is not null
                  and position(regexp_replace(round(q.quote_amount)::text, '[^0-9]', '', 'g')
                               in regexp_replace(v_hay, '[^0-9]', '', 'g')) > 0)
      then v_hits := array_append(v_hits, 'quoted_amount'); end if;
  end if;

  return jsonb_build_object(
    'safe', array_length(v_hits, 1) is null,
    'hits', to_jsonb(v_hits),
    'checked', jsonb_build_array('company_name','email','phone','trade_license_no','quoted_amount'),
    'scanned_at', now(),
    'note', case when array_length(v_hits,1) is null
                 then 'No supplier-identifying or commercial value from the live row appears in the subject, body or attachment name.'
                 else 'REFUSED: the message contains ' || array_to_string(v_hits, ', ') || ' from the live supplier row.' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_answer_identity_challenge(p_sender_ref text, p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare ch record; v_filed int := 0;
begin
  select * into ch from public.support_identity_challenge
   where sender_ref = p_sender_ref and consumed_at is null
   order by created_at desc limit 1 for update;

  if not found then
    return jsonb_build_object('ok', false, 'verified', false, 'reason', 'no_open_challenge',
      'message', 'I do not have a code outstanding for you. Send me the email address you registered with and I will start again.');
  end if;

  if ch.expires_at <= now() then
    update public.support_identity_challenge
       set consumed_at = now(), outcome = 'expired' where challenge_id = ch.challenge_id;
    return jsonb_build_object('ok', true, 'verified', false, 'reason', 'expired',
      'message', 'That code has expired. Send me the email address again and I will issue a fresh one.');
  end if;

  if ch.attempts >= 4 then
    update public.support_identity_challenge
       set attempts = ch.attempts + 1, consumed_at = now(), outcome = 'exhausted'
     where challenge_id = ch.challenge_id;
    return jsonb_build_object('ok', true, 'verified', false, 'reason', 'exhausted',
      'message', 'Too many attempts on that code, so I have cancelled it. Send me the email address again for a new one.');
  end if;

  if encode(sha256(convert_to(btrim(p_code) || '|' || ch.lead_id::text, 'UTF8')), 'hex') <> ch.code_hash then
    update public.support_identity_challenge
       set attempts = ch.attempts + 1 where challenge_id = ch.challenge_id;
    return jsonb_build_object('ok', true, 'verified', false, 'reason', 'wrong_code',
      'attempts_left', 4 - ch.attempts,
      'message', 'That code does not match. Please check the email and try again.');
  end if;

  update public.support_identity_challenge
     set consumed_at = now(), outcome = 'verified' where challenge_id = ch.challenge_id;

  -- NOTE ON THE ORDERING BELOW: received_at alone is not a tie-break. Two documents that arrive in
  -- the SAME transaction carry the same now(), so "the latest licence" was decided by whichever row
  -- the planner returned first. The intake_id settles it, and the probe that caught this is the
  -- reason the tie-break is here rather than a comment saying it cannot happen.
  -- NOW the held documents may be filed -- and only the ones this sender actually sent, on this
  -- channel. Verifying an identity does not adopt every orphan document in the table.
  update public.support_document_intake i
     set lead_id = ch.lead_id, attached = classified_as <> 'unknown',
         attach_note = case when classified_as = 'unknown'
           then 'Owner confirmed by identity challenge; type still unknown, so still held.'
           else format('Attached as %s to lead %s after identity challenge %s.', classified_as, ch.lead_id, ch.challenge_id) end
   where i.sender_ref = p_sender_ref and i.lead_id is null;
  get diagnostics v_filed = row_count;

  update public.leads l set
    license_doc_path = coalesce((select storage_path from public.support_document_intake
      where lead_id = ch.lead_id and classified_as = 'licence' order by received_at desc, intake_id desc limit 1), l.license_doc_path),
    company_profile_doc_path = coalesce((select storage_path from public.support_document_intake
      where lead_id = ch.lead_id and classified_as = 'profile' order by received_at desc, intake_id desc limit 1), l.company_profile_doc_path),
    signed_terms_path = coalesce((select storage_path from public.support_document_intake
      where lead_id = ch.lead_id and classified_as = 'signed_terms' order by received_at desc, intake_id desc limit 1), l.signed_terms_path)
  where l.id = ch.lead_id;

  -- The same rule at the other door: the owner was unknown when the document arrived, so the chase
  -- could not be stopped then. It is stopped now, at the moment the account is proven.
  perform public.fn_licence_ask_close_for_lead(ch.lead_id, 'identity_challenge', null);

  return jsonb_build_object('ok', true, 'verified', true, 'lead_id', ch.lead_id,
    'documents_released', v_filed,
    'mandatory', public.fn_supplier_mandatory_check(ch.lead_id),
    'message', 'Confirmed, thank you. I have filed the document you sent against your account.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_artifact_attachable(p_artifact_id bigint, p_for_party_id text, p_max_bytes bigint DEFAULT 15000000)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare a record;
begin
  select * into a from public.support_artifact where artifact_id = p_artifact_id;
  if not found then
    return jsonb_build_object('attachable', false, 'reason', 'unavailable',
      'note', 'no such artifact. Send the portal route and open a repair; do not describe a file that does not exist.');
  end if;
  if a.obsolete_at is not null then
    return jsonb_build_object('attachable', false, 'reason', 'obsolete',
      'note', 'this export was superseded. Attaching it would deliver an answer the company has already replaced.');
  end if;
  if a.privacy_state <> 'approved' then
    return jsonb_build_object('attachable', false, 'reason', 'unsafe',
      'note', format('privacy_state is %L. Only an artifact whose check RAN and passed may be attached.', a.privacy_state));
  end if;
  -- PER-PARTY ENTITLEMENT. "A payment for one supplier never reveals all suppliers; use
  -- per-customer, per-inquiry, per-supplier entitlements."
  if a.owner_party_id is not null and p_for_party_id is not null and a.owner_party_id <> p_for_party_id then
    return jsonb_build_object('attachable', false, 'reason', 'not_entitled',
      'note', 'this artifact belongs to a different party. Ownership is checked per artifact, not per payment.');
  end if;
  if a.byte_size is not null and a.byte_size > p_max_bytes then
    return jsonb_build_object('attachable', false, 'reason', 'oversized',
      'note', format('%s bytes exceeds the channel limit of %s. A link is the honest fallback and must be described as one.', a.byte_size, p_max_bytes));
  end if;
  return jsonb_build_object('attachable', true, 'checksum', a.checksum, 'version', a.version,
    'storage_path', a.storage_path,
    'note', 'Attachable. The message may say "attached" only because a file is genuinely going with it.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_case_close(p_ref text, p_reason text, p_by text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_case public.support_case; v_h public.agent_actions;
begin
  update public.support_case
     set state = 'closed', closed_at = now(), last_activity_at = now(),
         close_reason = left(coalesce(nullif(btrim(p_reason), ''), 'resolved') || ' (closed by ' || coalesce(nullif(btrim(p_by), ''), 'customer_support') || ')', 1000)
   where case_ref = upper(btrim(p_ref)) and state <> 'closed'
  returning * into v_case;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no open case ' || coalesce(p_ref, '')); end if;
  select * into v_h from public.agent_actions where kind = 'handoff' and target_id = 'support.case_open:' || v_case.case_id limit 1;
  return jsonb_build_object('ok', true, 'case_ref', v_case.case_ref, 'close_reason', coalesce(nullif(btrim(p_reason), ''), 'resolved'),
                            'phone_digits', v_h.detail ->> 'phone_digits', 'lang', coalesce(v_h.detail ->> 'lang', 'en'),
                            'handoff_status', (select status from public.agent_actions where id = v_h.id));
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_case_closed_tells_the_reporter()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_h public.agent_actions; v_email text; v_lang text; v_notif bigint;
begin
  if new.state <> 'closed' or old.state = 'closed' then return null; end if;
  select * into v_h from public.agent_actions where kind = 'handoff' and target_id = 'support.case_open:' || new.case_id limit 1;
  v_lang := coalesce(v_h.detail ->> 'lang', 'en');
  if new.party_kind = 'customer' then
    select c.email into v_email from public.customers c where c.id::text = new.party_id;
  elsif new.party_kind = 'supplier' then
    select l.email into v_email from public.leads l where l.id::text = new.party_id;
  end if;
  if v_email ~ '@' then
   begin   -- a refused notice (a guard on notifications) must never undo the close itself
    insert into public.notifications (type, kind, to_email, to_role, channel, lang, subject, body, requested_by, sender)
    values ('support_case_closed', 'support_case_closed', v_email, new.party_kind, 'email', v_lang,
            case when v_lang = 'ar' then 'إغلاق البلاغ رقم ' || new.case_ref else 'Your case ' || new.case_ref || ' is closed' end,
            case when v_lang = 'ar'
                 then 'نفيدكم بإغلاق البلاغ رقم ' || new.case_ref || '، وملخص المعالجة: ' || new.close_reason
                      || E'.\nإن لم تُحلّ المشكلة فتفضلوا بالرد على هذه الرسالة وسنعيد فتحه.'
                 else 'Your case ' || new.case_ref || ' is now closed: ' || new.close_reason
                      || E'.\nIf the problem is not solved, just reply to this message and we will reopen it.' end,
            'customer_support', 'customer_support')
    returning id into v_notif;
   exception when others then
    raise warning 'fn_support_case_closed_tells_the_reporter: the email for % was refused: %', new.case_ref, sqlerrm;
   end;
  end if;
  if v_h.id is not null and v_h.status <> 'done' then
    perform public.fn_seat_handoff_complete(v_h.id, jsonb_build_object(
      'closed_at', new.closed_at, 'close_reason', new.close_reason,
      'reporter_email_notification', v_notif, 'reporter_phone_digits', v_h.detail ->> 'phone_digits'));
  end if;
  return null;
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_context(p_query text, p_max_chars integer DEFAULT 12000, p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r record; v_out jsonb := '[]'::jsonb; v_used int := 0; v_n int := 0; v_how text;
begin
  for r in select * from public.fn_support_knowledge_search(p_query, p_limit) loop
    exit when v_used + length(r.body) > greatest(1500, p_max_chars);
    v_how := coalesce(v_how, r.matched_how);
    v_out := v_out || jsonb_build_object(
      'record_id', r.record_id, 'record_kind', r.record_kind, 'title', r.title,
      'body', r.body, 'source_ids', to_jsonb(r.source_ids), 'review_status', r.review_status,
      'relevance', r.relevance, 'matched_how', r.matched_how, 'warning', r.warning);
    v_used := v_used + length(r.body); v_n := v_n + 1;
  end loop;

  return jsonb_build_object(
    -- THE COMPANY BLOCK. Pinned, never retrieved and never rankable: it is here on every answer,
    -- including the refusals, because a seat with no retrieval hit is exactly the seat most likely
    -- to improvise a fee or a policy. Founder ruling, 9 Sep 2026.
    'company', public.fn_company_context(),
    
    'query', p_query,
    -- PINNED EVERY TIME, never retrieved and never rankable. These are the rules that must hold
    -- when the retrieval finds nothing, which is exactly when an agent is most tempted to improvise.
    'invariants', jsonb_build_array(
      'Never say you checked, sent, escalated, fixed, refunded or approved anything without tool evidence for it.',
      'A tool error means "cannot verify right now". It never means "no inquiry", "unpaid" or "no discount".',
      'Never reveal a supplier name, contact, logo, amount or quotation content in a notification. The quotation stays in the portal, including after a reveal payment.',
      'Never invent a fee, discount, promotion, policy, deadline or guaranteed outcome.',
      'A supplied email, number or reference is a search clue, never proof of account ownership.',
      'Never request a password, full card number or a banking OTP.',
      'Identify as QuotesDone Support. Never impersonate a person and never claim to be human.',
      'Escalation goes to the CEO. Never to the founder, and never to an invented department.'),
    'advisory_records', v_out,
    'record_count', v_n,
    'matched_how', v_how,
    'sufficient', v_n > 0,
    -- The caller fills this from the database. It is named rather than left implicit so that a
    -- caller who forgets it produces an obviously empty slot instead of a confident general answer.
    'account_facts', null,
    'account_facts_note', 'The CALLER must fill account_facts from authorised live data. Advisory records never contain this customer''s facts.',
    'signal', case when v_n = 0
                   then 'NO ADVISORY COVERAGE for this query. Answer from company policy and live account facts, or say you will check. Do not improvise from these records.'
                   else 'Advisory guidance only. Account facts come from the database.' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_corpus_search(p_query text, p_public boolean, p_limit integer DEFAULT 8)
 RETURNS TABLE(src text, src_id text, title text, content text, citation text, rank real)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with q as (
    select websearch_to_tsquery('english', coalesce(p_query, '')) as qe,
           websearch_to_tsquery('simple',  coalesce(p_query, '')) as qs,
           websearch_to_tsquery('arabic',  public.fn_ar_norm(coalesce(p_query, ''))) as qa,
           -- The asker's language is the script they typed in, not a flag anyone passed.
           case when coalesce(p_query, '') ~ '[؀-ۿ]' then 'ar' else 'en' end as ask_lang
  ),
  -- BEST-TERMS: the same lexemes the strict query produced, OR'd. Built from the tsquery itself so
  -- it cannot drift from what was actually searched, and so stemming is applied identically.
  qb as (
    select
      nullif(array_to_string(array(
        select lexeme from unnest(to_tsvector('arabic', public.fn_ar_norm(coalesce(p_query,'')))) ), ' | '), '') as ar_or,
      nullif(array_to_string(array(
        select lexeme from unnest(to_tsvector('english', coalesce(p_query,''))) ), ' | '), '') as en_or
  ),
  qb2 as (
    select case when ar_or is null then null else to_tsquery('arabic',  ar_or) end as qab,
           case when en_or is null then null else to_tsquery('english', en_or) end as qeb
      from qb
  ),
  hay as (
    select c.src, c.src_id, c.title, c.content, c.citation, c.is_public, c.lang,
           to_tsvector('english', coalesce(c.title,'') || ' ' || coalesce(c.content,'')) as te,
           to_tsvector('simple',  coalesce(c.title,'') || ' ' || coalesce(c.content,'')) as ts,
           to_tsvector('arabic',  public.fn_ar_norm(coalesce(c.title,'') || ' ' || coalesce(c.content,''))) as ta
      from public.v_support_corpus c
     where (case when p_public then c.is_public else true end)
  ),
  strict as (
    select h.src, h.src_id, h.title, h.content, h.citation,
           (greatest(ts_rank(h.te, q.qe), ts_rank(h.ts, q.qs), ts_rank(h.ta, q.qa))
            + case when h.lang = q.ask_lang then 1.0 else 0.0 end)::real as rank
      from hay h, q
     where h.te @@ q.qe or h.ts @@ q.qs or h.ta @@ q.qa
  ),
  loose as (
    select h.src, h.src_id, h.title, h.content, h.citation,
           -- Halved, then the language bonus added, so a best-terms hit can never outrank a strict
           -- one. A weaker match must look weaker.
           ((greatest(coalesce(ts_rank(h.ta, b.qab), 0), coalesce(ts_rank(h.te, b.qeb), 0)) * 0.5)
            + case when h.lang = q.ask_lang then 1.0 else 0.0 end)::real as rank
      from hay h, q, qb2 b
     where not exists (select 1 from strict)
       and ((b.qab is not null and h.ta @@ b.qab) or (b.qeb is not null and h.te @@ b.qeb))
  )
  select * from (select * from strict union all select * from loose) r
   order by r.rank desc
   limit greatest(1, least(coalesce(p_limit, 8), 25))
$function$


CREATE OR REPLACE FUNCTION public.fn_support_deliver_artifact(p_artifact_id bigint, p_case_id bigint, p_recipient_party_id text, p_whatsapp text, p_email text, p_inquiry_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  a record; e jsonb; v_portal text; v_body text; v_subject text; v_attach text;
  v_out jsonb := '[]'::jsonb; v_dedupe text; v_id bigint; v_grant jsonb;
begin
  v_grant := public.fn_support_may_act('notification');
  if (v_grant->>'may_act') <> 'true' then
    return jsonb_build_object('ok', false, 'reason', v_grant->>'reason');
  end if;

  select * into a from public.support_artifact where artifact_id = p_artifact_id;
  if not found then return jsonb_build_object('ok', false, 'reason', 'no such artifact'); end if;

  e := public.fn_support_artifact_attachable(p_artifact_id, p_recipient_party_id);
  v_portal := coalesce((select value from public.app_secrets where key = 'public_site_url'), 'https://quotesdone.com') || '/portal';

  if (e->>'attachable') = 'true' then
    v_attach := a.storage_path;
    v_body := case a.artifact_kind
      when 'comparison_report' then
        'Your comparison report for inquiry ' || p_inquiry_ref || ' is ready. A copy is attached, and you can view it in your portal: '
        || v_portal || '. Individual quotations are available in the portal.'
      else
        'Your reveal-fee payment for inquiry ' || p_inquiry_ref || ' has been confirmed. Your invoice ' || coalesce(a.subject_ref,'')
        || ' is attached. You can also access it in your portal: ' || v_portal || '.' end;
  else
    -- THE WORDING CHANGES BECAUSE THE FACT CHANGED. Not a softened version of the same sentence: the
    -- word "attached" is absent, the reason is stated, and the message says where the file is.
    v_attach := null;
    v_body := case a.artifact_kind
      when 'comparison_report' then
        'Your comparison report for inquiry ' || p_inquiry_ref || ' is ready. I could not include a copy with this message ('
        || (e->>'reason') || '), so please open it in your portal: ' || v_portal || '.'
      else
        'Your reveal-fee payment for inquiry ' || p_inquiry_ref || ' has been confirmed. I could not include the invoice with this message ('
        || (e->>'reason') || '), so please open it in your portal: ' || v_portal || '.' end;
  end if;
  v_subject := case a.artifact_kind when 'comparison_report'
                 then 'Your comparison report for inquiry ' || p_inquiry_ref
                 else 'Your invoice for inquiry ' || p_inquiry_ref end;

  -- THE DEDUPE KEY IS THE ARTIFACT PLUS ITS CHECKSUM. A re-send of the same file to the same person
  -- is silently absorbed; a REGENERATED file has a different checksum and is therefore a different
  -- delivery rather than a duplicate.
  if coalesce(btrim(p_whatsapp),'') <> '' then
    insert into public.support_notification (dedupe_key, case_id, purpose, channel, recipient,
      inquiry_ref, publication_version, subject, body, attachment_ref, anonymity_checked_at, anonymity_result)
    values ('artifact|' || p_artifact_id::text || '|' || coalesce(a.checksum,'nocs') || '|whatsapp|' || p_whatsapp,
            p_case_id, a.artifact_kind, 'whatsapp', p_whatsapp, p_inquiry_ref, a.version,
            null, v_body, v_attach, now(),
            jsonb_build_object('safe', true, 'note', 'deterministic artifact delivery; the artifact itself carries its own privacy result', 'artifact_privacy', a.privacy_result))
    on conflict (dedupe_key) do nothing returning id into v_id;
    v_out := v_out || jsonb_build_object('channel','whatsapp','queued', v_id is not null, 'attached', v_attach is not null);
  end if;

  if coalesce(btrim(p_email),'') <> '' then
    insert into public.support_notification (dedupe_key, case_id, purpose, channel, recipient,
      inquiry_ref, publication_version, subject, body, attachment_ref, anonymity_checked_at, anonymity_result)
    values ('artifact|' || p_artifact_id::text || '|' || coalesce(a.checksum,'nocs') || '|email|' || p_email,
            p_case_id, a.artifact_kind, 'email', p_email, p_inquiry_ref, a.version,
            v_subject, v_body, v_attach, now(),
            jsonb_build_object('safe', true, 'note', 'deterministic artifact delivery; the artifact itself carries its own privacy result', 'artifact_privacy', a.privacy_result))
    on conflict (dedupe_key) do nothing returning id into v_id;
    v_out := v_out || jsonb_build_object('channel','email','queued', v_id is not null, 'attached', v_attach is not null);
  end if;

  return jsonb_build_object(
    'ok', true, 'artifact_id', p_artifact_id, 'attachable', e->>'attachable',
    'refusal_reason', e->>'reason', 'queued', v_out,
    -- THE COUNT THE SPEC ASKS FOR. "Do not count a portal link as a delivered attachment."
    'file_copy_delivered', (e->>'attachable') = 'true',
    'note', case when (e->>'attachable') = 'true'
                 then 'A copy is attached and the message says so because it is true.'
                 else 'NOT a file-copy delivery. A link was sent instead, the reason was stated to the customer, and this must not be counted as an attachment.' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_investigate_refund(p_transaction_id uuid, p_reason text, p_case_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  t record; v_grant jsonb; v_id bigint; v_elig text; v_why text; v_prior int;
begin
  v_grant := public.fn_support_may_act('refund');
  if (v_grant->>'may_act') <> 'true' then
    return jsonb_build_object('ok', false, 'reason', v_grant->>'reason', 'route', v_grant->>'route');
  end if;

  select id, quote_amount, reveal_fee, total_charged, fee_status, refund_status, refund_amount_aed
    into t from public.transactions where id = p_transaction_id;
  if not found then
    -- "A tool error means cannot verify now, not no inquiry." A missing transaction is a real answer;
    -- it is reported as one and not as an ineligibility.
    return jsonb_build_object('ok', false, 'reason',
      'no such transaction. This is not an eligibility finding -- nothing was assessed.');
  end if;

  -- AGGREGATE OVER-REFUNDING. Everything already refunded on this transaction, counted before
  -- anything new is proposed.
  select count(*) into v_prior from public.refund_case
   where transaction_id = p_transaction_id and state in ('succeeded','reconciled','communicated');

  if coalesce(t.fee_status,'') not in ('paid','collected','succeeded') then
    v_elig := 'ineligible';
    v_why := format('the reveal fee is %L, so nothing has settled. There is no payment to refund; this is a settlement question, not a refund one.', coalesce(t.fee_status,'(none)'));
  elsif v_prior > 0 then
    v_elig := 'ineligible';
    v_why := format('%s refund(s) already succeeded on this transaction. A second would be an aggregate over-refund.', v_prior);
  else
    v_elig := 'eligible';
    v_why := 'the reveal fee settled and no prior refund has succeeded on this transaction.';
  end if;

  insert into public.refund_case
    (transaction_id, case_id, state, amount_aed, requested_reason, investigated_at,
     evidence, eligibility, eligibility_reason)
  values
    (p_transaction_id, p_case_id,
     case when v_elig = 'eligible' then 'eligible' else 'ineligible' end,
     coalesce(t.total_charged, t.reveal_fee, 0), p_reason, now(),
     jsonb_build_object('fee_status', t.fee_status, 'reveal_fee', t.reveal_fee,
                        'prior_successful_refunds', v_prior, 'read_at', now()),
     v_elig, v_why)
  on conflict do nothing
  returning refund_id into v_id;

  if v_id is null then
    return jsonb_build_object('ok', false, 'duplicate', true, 'reason',
      'a live refund already exists on this transaction. Concurrent remedies are prevented by index, not by hoping.');
  end if;

  return jsonb_build_object('ok', true, 'refund_id', v_id, 'eligibility', v_elig, 'why', v_why,
    'next', case when v_elig = 'eligible'
                 then 'Put it to the CEO. Support investigated; it does not decide.'
                 else 'No decision is needed: the investigation found it ineligible, with the reason recorded.' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_knowledge_gap(p_question text, p_refusal text, p_surface text DEFAULT 'website_widget'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_norm text;
  v_gap  public.sales_knowledge_gap%rowtype;
  v_task bigint;
  v_asks int;
begin
  if coalesce(btrim(p_question), '') = '' then
    return jsonb_build_object('ok', false, 'reason', 'empty_question');
  end if;

  -- THE QUESTION ARRIVED WITH ITS SCRIPT STRIPPED, so there is nothing here to answer and
  -- nothing to file. org_tasks 578945 is what happens without this branch: a task that sat in
  -- the work queue for nine days titled in question marks, asked four times, with no reading of
  -- it possible by anyone.
  --
  -- BOTH KEYS CARRY BOTH LANGUAGES. site_assistant picks between reply_en and reply_ar with
  -- `/[؀-ۿ]/.test(message) || uiLang === 'ar'` — it reads the script of the message, and on this
  -- branch the script is exactly what was destroyed, so a stripped Arabic message is pure ASCII
  -- and that test says "English" for the one visitor who needs the Arabic. The language cannot be
  -- known here, so it is not guessed: whichever key the caller reads, the person gets both
  -- paragraphs. This is the fix for the defect the comment above would otherwise only describe.
  if public.fn_text_lost_its_script(p_question) then
    return jsonb_build_object(
      'ok', false, 'reason', 'text_lost_its_script',
      'reply_en', public.fn_text_did_not_survive_reply('en') || E'\n\n'
                  || public.fn_text_did_not_survive_reply('ar'),
      'reply_ar', public.fn_text_did_not_survive_reply('ar') || E'\n\n'
                  || public.fn_text_did_not_survive_reply('en'));
  end if;

  v_norm := left(lower(regexp_replace(btrim(p_question), '\s+', ' ', 'g')), 400);
  select * into v_gap from public.sales_knowledge_gap where question_norm = v_norm;

  if not found then
    insert into public.org_tasks (title, detail, status, tier, action_class, assigned_agent,
                                  priority, requires_evidence, needs_founder)
    values (
      left('Answer an unanswered support question: ' || btrim(p_question), 160),
      'Someone who was NOT signed in asked this on the ' || coalesce(nullif(btrim(p_surface), ''), 'website_widget')
        || ' and Customer Support could not source an answer from company knowledge.' || E'\n\n'
        || 'QUESTION: ' || btrim(p_question) || E'\n'
        || 'REFUSAL: ' || coalesce(nullif(btrim(p_refusal), ''), 'no_grounded_answer') || E'\n\n'
        || 'THERE IS NO ESCALATION TO A HUMAN -- founder ruling, 9 Sep 2026. This task IS what '
        || 'happens instead, and it is the only thing that happens.' || E'\n\n'
        || 'DONE MEANS: the answer exists in a corpus fn_support_corpus_search reads (company_faq, '
        || 'support_knowledge, ops_knowledge) and this question returns it. Then set '
        || 'sales_knowledge_gap.status to knowledge_added.',
      'assigned', 'advisory', 'knowledge_gap', 'customer_support', 3, true, false)
    returning id into v_task;

    insert into public.sales_knowledge_gap (question_norm, question, refusal, nearest_corpus, task_id)
    values (v_norm, left(btrim(p_question), 2000),
            coalesce(nullif(btrim(p_refusal), ''), 'no_grounded_answer'),
            'support_corpus', v_task);
    v_asks := 1;
  else
    v_task := v_gap.task_id;
    v_asks := v_gap.asks + 1;
    update public.sales_knowledge_gap
       set asks = asks + 1, last_asked_at = now(),
           refusal = coalesce(nullif(btrim(p_refusal), ''), refusal)
     where id = v_gap.id;
    -- Asked repeatedly is the definition of urgent, exactly as on the sales side.
    update public.org_tasks
       set priority = least(9, greatest(priority, 3 + v_gap.asks)), updated_at = now()
     where id = v_task and status not in ('done', 'cancelled');
  end if;

  return jsonb_build_object(
    'ok', true, 'task_id', v_task, 'asks', v_asks,
    'reply_en', 'I do not have a sourced answer to that yet, and I will not guess at it. I have '
      || 'recorded your question exactly as you asked it so it gets answered properly. If you need '
      || 'it now, call or WhatsApp +971 50 931 9355 (Mon-Fri, 9am-6pm GST) or email '
      || 'management@quotesdone.com.',
    'reply_ar', 'لا تتوفر لديّ إجابة موثّقة عن ذلك حتى الآن، ولا أودّ التخمين. سجّلتُ سؤالكم كما كتبتموه '
      || 'تمامًا ليُجاب عنه إجابة دقيقة. وإن احتجتم إلى الإجابة الآن، يمكنكم الاتصال أو المراسلة عبر '
      || 'واتساب:' || E'\n' || '+971 50 931 9355' || E'\n' || 'أو البريد الإلكتروني:' || E'\n'
      || 'management@quotesdone.com');
end
$function$


CREATE OR REPLACE FUNCTION public.fn_support_knowledge_search(p_query text, p_limit integer DEFAULT 6, p_kind text DEFAULT NULL::text)
 RETURNS TABLE(record_id text, record_kind text, title text, body text, body_sha256 text, source_ids text[], source_path text, review_status text, authority_effect text, contains_synthetic_example boolean, structured_data jsonb, relevance real, matched_how text, warning text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_q tsquery; v_lex text[]; v_found boolean := false; v_how text := 'all_terms';
begin
  if coalesce(btrim(p_query), '') = '' then return; end if;

  v_q := websearch_to_tsquery('english', p_query);
  if v_q is not null then
    select exists (select 1 from public.support_knowledge k
                    where k.runtime_index_eligible and k.search @@ v_q
                      and (p_kind is null or k.record_kind = p_kind)) into v_found;
  end if;

  if not v_found then
    v_lex := tsvector_to_array(to_tsvector('english'::regconfig, p_query));
    if v_lex is null or array_length(v_lex, 1) is null then return; end if;
    begin
      v_q := to_tsquery('english'::regconfig,
               array_to_string(array(select '''' || replace(x, '''', '''''') || '''' from unnest(v_lex) x), ' | '));
    exception when others then return;
    end;
    v_how := 'best_terms';
  end if;

  return query
  select k.record_id, k.record_kind, k.title, k.body, k.body_sha256,
         k.source_ids, k.source_path, k.review_status, k.authority_effect,
         k.contains_synthetic_example, k.structured_data,
         ts_rank(k.search, v_q) as relevance, v_how as matched_how,
         'Advisory only. authority_effect=none: this may not approve a refund, grant an entitlement, '
         || 'change a price or become policy. review_status=' || k.review_status || '. '
         || case when k.record_kind = 'message_template'
                 then 'DRAFT TEMPLATE -- not an approved provider template. Check wa_template_registry before sending. ' else '' end
         || case when k.contains_synthetic_example
                 then 'CONTAINS A SYNTHETIC EXAMPLE -- authored, not a real QuotesDone conversation. ' else '' end
         || case when v_how = 'best_terms'
                 then 'MATCHED ON BEST TERMS, not all of them -- read the title before relying on it. ' else '' end
         || 'Account facts come from the database, never from this record.' as warning
    from public.support_knowledge k
   where k.runtime_index_eligible
     and k.search @@ v_q
     and (p_kind is null or k.record_kind = p_kind)
   order by ts_rank(k.search, v_q) desc, k.record_id
   limit greatest(1, least(coalesce(p_limit, 6), 30));
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_knowledge_search_vector()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  new.search :=
      setweight(to_tsvector('english'::regconfig, coalesce(new.title,'')), 'A')
   || setweight(to_tsvector('english'::regconfig, coalesce(array_to_string(new.tags,' '),'')), 'B')
   || setweight(to_tsvector('english'::regconfig, coalesce(new.body,'')), 'C');
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_may_act(p_action_class text, p_amount_aed numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select public.fn_agent_may_act('customer_support', p_action_class, p_amount_aed);
$function$


CREATE OR REPLACE FUNCTION public.fn_support_notification_sync_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if new.status is distinct from old.status then
    update public.support_notification
       set state = case new.status
             when 'sent'       then 'sent'
             when 'suppressed' then 'suppressed'
             when 'failed'     then 'failed'
             when 'skipped'    then 'suppressed'
             when 'held'       then 'queued'
             else state end,
           sent_at = case when new.status = 'sent' then coalesce(new.sent_at, now()) else sent_at end,
           provider_id = coalesce(new.id::text, provider_id),
           provider_status = new.status,
           attempts = coalesce(new.attempts, attempts),
           -- The provider's own words, kept rather than summarised. A bounce reason is the only
           -- thing that distinguishes "the address is wrong" from "our domain is in trouble".
           failure_reason = case when new.status in ('failed','skipped')
                                 then new.last_error else failure_reason end
     where outbox_id = new.id;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_notification_to_outbox()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_role text; v_id bigint; v_kind text;
begin
  -- WHO IS THIS PERSON TO US. send_outbox routes the from-address, the reply-to, the template and
  -- the unsubscribe header off to_role, so getting it wrong sends a supplier a customer-branded
  -- email from the wrong mailbox. Read from the case rather than guessed.
  select case when c.party_kind = 'supplier' then 'supplier' else 'customer' end
    into v_role
    from public.support_case c where c.case_id = new.case_id;
  v_role := coalesce(v_role, 'customer');

  if new.channel = 'email' then
    if coalesce(btrim(new.recipient), '') = '' then
      new.bridge_note := 'no email address on the row; nothing to hand over';
      return new;
    end if;

    -- THE TYPE CARRIES THE PURPOSE, and that is load-bearing rather than cosmetic: send_outbox
    -- exempts anything matching licence/renew/expiry from the supplier bulk gate, because a
    -- document request is transactional. Passing the purpose through means a licence reminder is
    -- recognised as one instead of being held with the marketing.
    v_kind := coalesce(new.purpose, 'support');

    -- KIND CARRIES THE PURPOSE TOO, and this is not cosmetic. a10_notifications_founder_mail_policy
    -- governs anything addressed to the founder by KIND, reading it before type. An earlier version
    -- of this bridge stamped every row 'support_agent', which collapsed every kind of support mail
    -- into one governance decision: allow the label and he gets all of it, refuse it and he gets
    -- none -- and the policy table could not tell a refund decision from a licence reminder. The
    -- provenance that label was carrying is already on the support_notification row it came from,
    -- so nothing is lost by letting the purpose through.
    insert into public.notifications (type, kind, to_email, to_role, subject, body, status, channel)
    values (v_kind, v_kind, btrim(new.recipient), v_role,
            coalesce(new.subject, 'QuotesDone'), new.body, 'queued', 'email')
    returning id into v_id;

    new.outbox_id := v_id;
    new.bridged_at := now();
    new.bridge_note := format('handed to notifications #%s as a %L to a %s', v_id, v_kind, v_role);

  elsif new.channel = 'whatsapp' then
    -- NOT BRIDGED, AND SAYING SO. send_outbox is email only, and a business-initiated WhatsApp
    -- message needs an approved template and recorded opt-in, which no recipient has yet. Writing
    -- it into an email queue would produce a delivery that never happened; leaving it silent would
    -- be indistinguishable from working. It is held, with the reason on the row.
    new.bridge_note := 'not bridged: WhatsApp is business-initiated here and no recipient has recorded opt-in. '
                    || 'This is held deliberately, not lost. An inbound reply inside the 24-hour window goes '
                    || 'through wa_inbound and does not use this table.';
  end if;

  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_notify_new_quotation(p_quote_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  q record; c record; v_case bigint; v_ref text; v_portal text;
  v_body text; v_subject text; v_scan jsonb;
  v_queued jsonb := '[]'::jsonb; v_skipped jsonb := '[]'::jsonb;
  v_dedupe text; v_id bigint;
begin
  -- THE COMMITTED STATE, AND THE CURRENT ONE. Both are required: committed_at proves it was
  -- published, and the status re-read proves it has not been withdrawn since. A quotation withdrawn
  -- between publication and this call must not be announced, and only a fresh read can know that.
  select qq.id, qq.inquiry_id, qq.supplier_id, qq.committed_at, qq.committed_hash, qq.status, qq.anonymized
    into q from public.quotes qq where qq.id = p_quote_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', format('no quotation %s', p_quote_id::text));
  end if;
  if q.committed_at is null then
    return jsonb_build_object('ok', false, 'reason',
      'this quotation is not committed. A draft or a failed upload is not a publication and must never reach a customer.');
  end if;
  if coalesce(q.status,'') in ('withdrawn','cancelled','rejected','expired') then
    return jsonb_build_object('ok', false, 'reason',
      format('the quotation is %L now. It was committed once; it is not visible today, and the customer is not told about it.', q.status));
  end if;

  -- wa_dest: the CONFIRMED WhatsApp number (#322), or null. wa_optin is no longer read anywhere.
  select i.rfq_no, cu.id cust_id, cu.full_name, cu.phone, cu.email, cu.banned,
         public.fn_whatsapp_destination('customer', cu.id) as wa_dest
    into c
    from public.inquiries i
    join public.customers cu on cu.id = i.customer_id
   where i.id = q.inquiry_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason',
      'the inquiry or its owner could not be read. Nothing is sent: a notification with no verified recipient is a message to a guess.');
  end if;
  if coalesce(c.banned, false) then
    return jsonb_build_object('ok', false, 'reason', 'the inquiry owner is banned; no notification is sent.');
  end if;

  -- rfq_no is an INTEGER sequence number. The customer-facing reference is rendered from it when
  -- it exists and from the inquiry id when it does not, so the shape is stable either way.
  v_ref := case when c.rfq_no is not null then 'RFQ-' || c.rfq_no::text
                else 'INQ-' || q.inquiry_id::text end;
  v_portal := coalesce((select value from public.app_secrets where key = 'public_site_url'), 'https://quotesdone.com') || '/portal';

  -- DETERMINISTIC RENDERING. The spec requires it for notifications, and it is also the only way the
  -- anonymity scan means anything: a model could compose a different sentence next time, and the
  -- scan would be checking a message nobody will send.
  v_body := 'You have received a new quotation for inquiry ' || v_ref
         || '. Sign in to your QuotesDone portal to review it: ' || v_portal || '.';
  v_subject := 'A new quotation for inquiry ' || v_ref;

  -- THE SCAN, before anything is queued. It reads the live supplier row and the live quotation, so
  -- it is checking for THIS supplier's actual name, email, phone and amount -- not a word list.
  v_scan := public.fn_support_anonymity_scan(v_body, v_subject, null, q.supplier_id, q.id::text);
  if (v_scan->>'safe') <> 'true' then
    return jsonb_build_object('ok', false, 'blocked', true, 'reason', v_scan->>'note', 'scan', v_scan);
  end if;

  -- The case that owns this conversation.
  insert into public.support_case (case_ref, party_kind, party_id, inquiry_ref, subject)
  values ('case:quote:' || q.id::text, 'customer', c.cust_id::text, v_ref,
          'New quotation published for ' || v_ref)
  on conflict (case_ref) do update set last_activity_at = now()
  returning case_id into v_case;
  if v_case is null then
    select case_id into v_case from public.support_case where case_ref = 'case:quote:' || q.id::text;
  end if;

  -- BOTH CHANNELS, EACH JUDGED ON ITS OWN PERMISSION. The spec: "Check both-channel permissions
  -- independently and record blocked/suppressed outcomes honestly." A missing email is not a reason
  -- to skip WhatsApp, and no consent on WhatsApp is not a reason to skip email.
  --
  -- The dedupe key carries the publication version (committed_hash), so re-committing a changed
  -- quotation notifies again and the same commit arriving twice does not.
  if c.wa_dest is not null then
    v_dedupe := 'quote_published|' || q.id::text || '|' || coalesce(q.committed_hash,'nohash') || '|whatsapp|' || c.wa_dest;
    insert into public.support_notification
      (dedupe_key, case_id, purpose, channel, recipient, inquiry_ref, publication_version,
       subject, body, anonymity_checked_at, anonymity_result)
    values (v_dedupe, v_case, 'quote_published', 'whatsapp', c.wa_dest, v_ref, q.committed_hash,
            null, v_body, now(), v_scan)
    on conflict (dedupe_key) do nothing
    returning id into v_id;
    v_queued := v_queued || jsonb_build_object('channel','whatsapp','queued', v_id is not null,
                  'note', case when v_id is null then 'already queued for this publication version' else 'queued' end);
  else
    v_skipped := v_skipped || jsonb_build_object('channel','whatsapp','reason',
      'no confirmed WhatsApp number (the customer said they do not use WhatsApp, or has not confirmed one)');
  end if;

  if coalesce(btrim(c.email),'') <> '' then
    v_dedupe := 'quote_published|' || q.id::text || '|' || coalesce(q.committed_hash,'nohash') || '|email|' || c.email;
    insert into public.support_notification
      (dedupe_key, case_id, purpose, channel, recipient, inquiry_ref, publication_version,
       subject, body, anonymity_checked_at, anonymity_result)
    values (v_dedupe, v_case, 'quote_published', 'email', c.email, v_ref, q.committed_hash,
            v_subject, v_body, now(), v_scan)
    on conflict (dedupe_key) do nothing
    returning id into v_id;
    v_queued := v_queued || jsonb_build_object('channel','email','queued', v_id is not null,
                  'note', case when v_id is null then 'already queued for this publication version' else 'queued' end);
  else
    v_skipped := v_skipped || jsonb_build_object('channel','email','reason','no email on the customer record');
  end if;

  return jsonb_build_object(
    'ok', true, 'quote_id', q.id, 'inquiry_ref', v_ref, 'case_id', v_case,
    'publication_version', q.committed_hash,
    'queued', v_queued, 'skipped', v_skipped, 'anonymity', v_scan,
    'note', 'Queued only. Delivery is the sender''s job and its outcome is recorded on the row, never assumed here.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_open_identity_challenge(p_channel text, p_sender_ref text, p_claimed_email text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_lead bigint; v_to text; v_code text; v_id bigint; v_grant jsonb; v_open int;
begin
  v_grant := public.fn_support_may_act('document');
  if (v_grant->>'may_act') <> 'true' then
    return jsonb_build_object('ok', false, 'reason', v_grant->>'reason');
  end if;

  -- RATE LIMIT PER SENDER, not per account. Limiting per account would let a stranger lock a real
  -- supplier out of their own verification by spamming challenges at them.
  select count(*) into v_open from public.support_identity_challenge
   where sender_ref = p_sender_ref and created_at > now() - interval '1 hour';
  if v_open >= 5 then
    return jsonb_build_object('ok', true, 'challenge_opened', false, 'reason', 'rate_limited',
      'message', 'I have sent several codes to this account recently. Please use the most recent one, or try again in an hour.');
  end if;

  select id, email into v_lead, v_to from public.leads
   where lower(email) = lower(btrim(p_claimed_email)) order by id limit 1;

  v_code := lpad((floor(random() * 1000000))::int::text, 6, '0');

  if v_lead is not null then
    insert into public.support_identity_challenge
      (channel, sender_ref, claimed_email, lead_id, sent_to, code_hash, expires_at)
    values (p_channel, p_sender_ref, p_claimed_email, v_lead, v_to,
            encode(sha256(convert_to(v_code || '|' || v_lead::text, 'UTF8')), 'hex'), now() + interval '15 minutes')
    returning challenge_id into v_id;

    insert into public.support_notification (dedupe_key, case_id, purpose, channel, recipient,
      subject, body, anonymity_checked_at, anonymity_result)
    values ('idchallenge|' || v_id::text, null, 'identity_challenge', 'email', v_to,
            'Your QuotesDone confirmation code',
            'Your confirmation code is ' || v_code || '. It expires in 15 minutes. If you did not ask '
            || 'to confirm a document upload, you can ignore this message and nothing will be filed.',
            now(), jsonb_build_object('safe', true, 'note', 'code to the address of record; no counterparty data'));
  end if;

  -- THE SAME ANSWER EITHER WAY. Whether or not that account exists, the sender is told a code was
  -- sent to the address they named. Saying "no account with that email" would turn this into a
  -- free tool for discovering who is registered with us.
  return jsonb_build_object('ok', true, 'challenge_opened', v_lead is not null,
    'message', 'I have sent a 6-digit code to ' || p_claimed_email || '. Reply with the code and I '
            || 'will file your document against that account. The code expires in 15 minutes.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_open_reports()
 RETURNS TABLE(report_id bigint, severity text, subject text, status text, owner_role_id text, age interval, next_review_at timestamp with time zone, attempts integer)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select r.id, r.severity, r.subject, r.status, r.owner_role_id,
         now() - r.created_at, r.next_review_at, r.delivery_attempts
    from public.support_ceo_report r
   where r.status in ('sent','failed','blocked')
   order by case r.severity when 'critical' then 0 when 'serious' then 1
                            when 'elevated' then 2 else 3 end,
            r.created_at;
$function$


CREATE OR REPLACE FUNCTION public.fn_support_receive_document(p_channel text, p_sender_ref text, p_storage_path text, p_caption text DEFAULT NULL::text, p_media_kind text DEFAULT NULL::text, p_declared text DEFAULT NULL::text, p_lead_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  c jsonb; v_lead bigint; v_id bigint; v_note text; v_reply text;
  v_before jsonb; v_after jsonb; v_grant jsonb; v_missing text;
begin
  v_grant := public.fn_support_may_act('document');
  if (v_grant->>'may_act') <> 'true' then
    return jsonb_build_object('ok', false, 'reason', v_grant->>'reason');
  end if;
  if p_channel not in ('email','portal') then
    return jsonb_build_object('ok', false, 'reason',
      'this function serves the email and portal paths; WhatsApp has fn_wa_attach_document.');
  end if;
  if coalesce(btrim(p_storage_path), '') = '' then
    return jsonb_build_object('ok', false, 'reason',
      'no stored file. A receipt for a document that was never stored is the lost-document failure with a friendlier message.');
  end if;

  -- WHO SENT IT. The portal already knows -- the session is the identity, which is why it may pass a
  -- lead directly. Email has only the From address, so it is matched against the address of record.
  if p_channel = 'portal' then
    v_lead := p_lead_id;
  else
    select id into v_lead from public.leads
     where lower(email) = lower(btrim(p_sender_ref)) order by id limit 1;
  end if;

  c := public.fn_document_classify(p_caption, p_storage_path, p_declared);

  if v_lead is not null then v_before := public.fn_supplier_mandatory_check(v_lead); end if;

  if v_lead is null then
    v_note := 'No account matches this sender. Held, and an identity challenge is the only route to attaching it.';
    v_reply := 'Thank you -- I have your file safely. I could not match it to a registered account '
            || 'from this address, so I have not filed it yet. Reply with the email address you '
            || 'registered with and I will send a short code to that address to confirm it is you.';
  elsif (c->>'kind') = 'unknown' then
    v_note := 'Owner known, type not. Held rather than filed on a guess.';
    v_reply := 'Thank you, I have saved that to your file. I could not tell which document it is, so '
            || 'to file it correctly please tell me: is it your trade licence, your company profile, '
            || 'or the signed terms?';
  else
    v_note := format('Attached as %s to lead %s.', c->>'kind', v_lead);
  end if;

  insert into public.support_document_intake
    (channel, sender_ref, lead_id, storage_path, media_kind, caption,
     classified_as, classified_by, confidence, attached, attach_note)
  values (p_channel, p_sender_ref, v_lead, p_storage_path, p_media_kind, p_caption,
          c->>'kind', c->>'by', c->>'confidence',
          v_lead is not null and (c->>'kind') <> 'unknown', coalesce(v_note, ''))
  returning intake_id into v_id;

  if v_lead is not null and (c->>'kind') <> 'unknown' then
    if (c->>'kind') = 'licence' then
      update public.leads set license_doc_path = p_storage_path where id = v_lead;
    elsif (c->>'kind') = 'profile' then
      update public.leads set company_profile_doc_path = p_storage_path where id = v_lead;
    else
      update public.leads set signed_terms_path = p_storage_path where id = v_lead;
    end if;

    -- A LICENCE THAT ARRIVED STOPS THE CHASE FOR IT. Without this the supplier keeps being asked
    -- for a document the company already holds, which is how a chase teaches people we do not read
    -- what they send.
    if (c->>'kind') = 'licence' then
      perform public.fn_licence_ask_close_for_lead(v_lead, p_channel, v_id);
    end if;

    v_after := public.fn_supplier_mandatory_check(v_lead);
    -- THE RECEIPT SAYS WHAT IS STILL MISSING, the same as the WhatsApp path. A receipt that only
    -- confirms arrival leaves the supplier believing they are finished when they are not, which is
    -- how 81 invitations became 0 registrations.
    if coalesce((v_after->>'complete')::boolean, false) then
      v_reply := 'Got it -- your ' || replace(c->>'kind','_',' ') || ' is saved. Your file is now '
              || 'complete and goes for verification. I will let you know when it is approved.';
    else
      select string_agg(value #>> '{}', ', ') into v_missing
        from jsonb_array_elements(v_after->'missing');
      v_reply := 'Got it -- your ' || replace(c->>'kind','_',' ') || ' is saved. Still needed: '
              || coalesce(v_missing, '(nothing listed)') || '. You can send them the same way.';
    end if;
  end if;

  return jsonb_build_object('ok', true, 'intake_id', v_id, 'channel', p_channel,
    'lead_id', v_lead, 'classified_as', c->>'kind', 'confidence', c->>'confidence',
    'attached', v_lead is not null and (c->>'kind') <> 'unknown',
    'needs_identity_challenge', v_lead is null,
    'mandatory_before', v_before, 'mandatory_after', v_after, 'reply', v_reply);
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_record_supplier_contact(p_transaction_id uuid, p_lead_id bigint, p_channel text, p_notification_id bigint DEFAULT NULL::bigint, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id bigint; v_n int;
begin
  if p_channel is null or p_channel not in ('email','whatsapp','sms','phone') then
    raise exception 'channel must be one of email, whatsapp, sms, phone (got %)', coalesce(p_channel,'null');
  end if;

  insert into public.supplier_response_watch (transaction_id, lead_id, attempts)
  values (p_transaction_id, p_lead_id, '[]'::jsonb)
  on conflict (transaction_id) do nothing;

  update public.supplier_response_watch
     set attempts = attempts || jsonb_build_object(
           'at', now(), 'channel', p_channel,
           'notification_id', p_notification_id, 'note', p_note)
   where transaction_id = p_transaction_id
   returning id, jsonb_array_length(attempts) into v_id, v_n;

  return jsonb_build_object('ok', true, 'watch_id', v_id, 'attempts', v_n, 'channel', p_channel);
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_record_supplier_response(p_transaction_id uuid, p_channel text, p_ref text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row public.supplier_response_watch;
begin
  update public.supplier_response_watch
     set first_response_at = coalesce(first_response_at, now()),
         response_channel  = coalesce(response_channel, p_channel),
         response_ref      = coalesce(response_ref, p_ref)
   where transaction_id = p_transaction_id
   returning * into v_row;

  if v_row.id is null then
    return jsonb_build_object('ok', false, 'reason', 'no watch is open for this transaction');
  end if;
  return jsonb_build_object('ok', true, 'watch_id', v_row.id,
    'first_response_at', v_row.first_response_at,
    'note', 'This transaction can no longer produce a non-response refund. The supplier answered.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_reply_watch_tick()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_sla numeric := public.fn_seat_clock_policy('support_first_reply_sla_hours', 24);
  v_cut timestamptz; v_founder text[]; c text; v_n int; v_oldest timestamptz; v_ids jsonb; v_median numeric;
  v_out jsonb := '{}'::jsonb;
begin
  v_cut := now() - make_interval(secs => (v_sla * 3600)::double precision);
  select coalesce(array_agg(right(regexp_replace(value, '[^0-9]', '', 'g'), 9)), '{}') into v_founder
    from public.app_secrets where key in ('founder_mobile', 'founder_public_phone', 'admin_mfa_phone')
     and length(regexp_replace(coalesce(value, ''), '[^0-9]', '', 'g')) >= 9;

  foreach c in array array['email', 'whatsapp', 'chat'] loop
    if c = 'email' then
      select count(*), min(m.created_at), coalesce(jsonb_agg(m.id order by m.id), '[]'::jsonb)
        into v_n, v_oldest, v_ids
        from public.inbound_messages m
       where m.created_at > now() - interval '30 days' and m.created_at < v_cut and m.replied_at is null
         and coalesce(m.to_email, '') !~* '^expenses@' and coalesce(m.owner_role, '') <> 'accountant'
         and not public.fn_is_demo_email(m.from_email);
      select percentile_cont(0.5) within group (order by extract(epoch from m.replied_at - m.created_at) / 60) into v_median
        from public.inbound_messages m
       where m.replied_at is not null and m.created_at > now() - interval '7 days'
         and coalesce(m.to_email, '') !~* '^expenses@' and coalesce(m.owner_role, '') <> 'accountant';
    elsif c = 'whatsapp' then
      select count(*), min(w.created_at), coalesce(jsonb_agg(w.id order by w.id), '[]'::jsonb)
        into v_n, v_oldest, v_ids
        from public.wa_messages w
       where w.created_at > now() - interval '30 days' and w.created_at < v_cut
         and coalesce(btrim(w.inbound), '') <> '' and (w.reply is null or not coalesce(w.sent, false))
         and not (right(regexp_replace(coalesce(w.wa_from, ''), '[^0-9]', '', 'g'), 9) = any (v_founder));
      v_median := null;   -- the WhatsApp reply is written in the same row as the inbound: minutes are not recorded
    else
      select count(*), min(g.created_at), coalesce(jsonb_agg(g.id order by g.id), '[]'::jsonb)
        into v_n, v_oldest, v_ids
        from public.assistant_logs g
        left join public.org_tasks t on t.id = g.gap_task_id
       where g.answered = false and g.created_at > now() - interval '30 days' and g.created_at < v_cut
         and coalesce(t.status, 'open') not in ('done', 'cancelled');
      select percentile_cont(0.5) within group (order by extract(epoch from t.updated_at - g.created_at) / 60) into v_median
        from public.assistant_logs g join public.org_tasks t on t.id = g.gap_task_id
       where g.answered = false and t.status = 'done' and t.updated_at > g.created_at and g.created_at > now() - interval '7 days';
    end if;

    if v_n > 0 then
      perform public.fn_it_engineer_finding_upsert('support_reply_sla:' || c,
        v_n || ' ' || c || ' message(s) have waited more than ' || v_sla || ' h for a first reply (oldest '
          || to_char(v_oldest at time zone 'Asia/Dubai', 'YYYY-MM-DD HH24:MI') || ' Dubai)',
        'customer_support first-reply watch (fn_support_reply_watch_tick) -> ' || c, 'customer_facing', v_n,
        jsonb_build_object('channel', c, 'sla_hours', v_sla, 'waiting', v_n, 'oldest', v_oldest,
                           'ids', (select coalesce(jsonb_agg(x), '[]'::jsonb) from (select x from jsonb_array_elements(v_ids) x limit 20) z),
                           'median_first_reply_minutes_7d', round(v_median), 'owner_seat', 'customer_support', 'duty', 'reply_time'),
        '{}'::text[], array['whether the customer was answered on another channel'], 'customer_support');
    elsif exists (select 1 from public.it_engineer_finding where issue_key = 'support_reply_sla:' || c and closed_at is null) then
      perform public.fn_it_engineer_finding_close('support_reply_sla:' || c,
        'every ' || c || ' message older than ' || v_sla || ' h has a first reply');
    end if;
    v_out := v_out || jsonb_build_object(c, jsonb_build_object('over_sla', v_n, 'median_first_reply_minutes_7d', round(v_median)));
  end loop;
  return jsonb_build_object('ok', true, 'sla_hours', v_sla) || v_out;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_support_report_to_ceo(p_idempotency_key text, p_severity text, p_subject text, p_evidence jsonb, p_attempted jsonb, p_requested text, p_case_ref text DEFAULT NULL::text, p_task_ref text DEFAULT NULL::text, p_review_in interval DEFAULT '1 day'::interval, p_source_agent text DEFAULT 'customer_support'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_parent text;
  v_id     bigint;
  v_agent  text := lower(btrim(coalesce(p_source_agent, '')));
  v_existing public.support_ceo_report%rowtype;
begin
  -- WHO IS REPORTING IS AN ARGUMENT NOW, NOT A LITERAL. It defaults to customer_support so every
  -- existing caller behaves exactly as it did, and it is used in all three of the places the
  -- literal used to sit: the edge lookup, source_agent, and owner_role_id. Getting only two of the
  -- three would be worse than none -- a report filed under the accountant's name but gated on
  -- support's edge is a report that can be sent when support is reorganised and refused when the
  -- accountant is.
  if v_agent = '' then
    return jsonb_build_object('ok', false, 'reason',
      'source_agent is required. A report with no sender cannot be routed, because the reporting '
      || 'edge that decides where it goes is the SENDER''s edge, not a constant.');
  end if;

  -- THE MANAGER IS READ, NOT ASSUMED. If the edge is gone or the parent is not active, this
  -- refuses rather than picking someone.
  select e.parent_role_id into v_parent
    from public.org_reporting_edge e
    join public.org_role r on r.role_id = e.parent_role_id and r.status = 'active'
   where e.child_role_id = v_agent;

  if v_parent is null then
    return jsonb_build_object('ok', false, 'reason',
      format('No active reporting parent for %s. The report is NOT sent and NOT silently '
             || 'redirected: inventing a recipient is how work goes to nobody.', v_agent));
  end if;

  if coalesce(btrim(p_requested), '') = '' then
    return jsonb_build_object('ok', false, 'reason',
      'requested_outcome is required. A report that does not say what it wants is a notification, '
      || 'and the CEO cannot act on it.');
  end if;

  -- IDEMPOTENT BY THE BUSINESS EVENT. A webhook that fires twice, a retry after a timeout and a
  -- restart mid-flight must all produce ONE report. Returning the existing row is the correct
  -- answer, not an error: the caller's intent was satisfied the first time.
  select * into v_existing from public.support_ceo_report where idempotency_key = p_idempotency_key;
  if found then
    return jsonb_build_object('ok', true, 'duplicate', true, 'report_id', v_existing.id,
      'status', v_existing.status,
      'note', 'This matter was already reported. Returning the original rather than sending a second.');
  end if;

  insert into public.support_ceo_report
    (idempotency_key, source_agent, case_ref, task_ref, severity, subject,
     verified_evidence, attempted_actions, requested_outcome, owner_role_id, next_review_at)
  values
    (p_idempotency_key, v_agent, p_case_ref, p_task_ref, p_severity, p_subject,
     p_evidence, coalesce(p_attempted, '[]'::jsonb), p_requested,
     v_agent,                       -- the sender keeps it until the CEO accepts
     now() + coalesce(p_review_in, interval '1 day'))
  returning id into v_id;

  return jsonb_build_object('ok', true, 'report_id', v_id, 'reported_to', v_parent,
    'owner', v_agent,
    'note', format('Sent. Ownership stays with %s until the CEO accepts it with a receipt.', v_agent));
end $function$


CREATE OR REPLACE FUNCTION public.fn_support_request_ratings_due(p_limit integer DEFAULT 500)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_days     integer;
  v_site     text;
  v_founder  text;
  v_asked    integer := 0;
begin
  select nullif(regexp_replace(coalesce(value, ''), '[^0-9]', '', 'g'), '')::int
    into v_days from public.app_secrets where key = 'rating_request_days_after_reveal';
  v_days := coalesce(v_days, 21);

  select coalesce(value, 'https://quotesdone.com') into v_site
    from public.app_secrets where key = 'public_site_url';
  v_site := coalesce(v_site, 'https://quotesdone.com');

  -- The founder's own address, so a customer record that happens to carry it is never asked.
  -- fn_notifications_founder_mail_policy intercepts founder-directed mail whose kind is not
  -- allowed_to_email and returns NULL: the row is silently not inserted, the unique key stays free,
  -- and this sweep would re-ask that one transaction every 15 minutes forever.
  select lower(nullif(split_part(coalesce(value, ''), ',', 1), '')) into v_founder
    from public.app_secrets where key = 'admin_emails';

  with due as (
    select t.id as tx_id, t.quote_id, t.inquiry_id, t.supplier_id,
           c.email as cemail, l.company_name, i.summary
      from public.transactions t
      join public.customers c on c.id = t.customer_id
      left join public.leads l on l.id = t.supplier_id
      left join public.inquiries i on i.id = t.inquiry_id
     where t.revealed_at is not null
       and t.revealed_at <= now() - make_interval(days => v_days)
       and t.quote_id is not null
       -- 4. NEVER ASK ABOUT A REFUNDED OR REVERSED REVEAL.
       -- MEASURED, NOT ASSUMED: trg_reveal_window sets refund_status := 'window_open' on EVERY
       -- reveal, so "refund_status is null" describes no real transaction at all — a guard written
       -- as `coalesce(refund_status,'none') = 'none'` asks nobody, ever, and its zero would have
       -- looked exactly like "nothing was due". The live vocabulary is
       -- none / window_open / requested / approved / refunded / declined.
       -- This is an ALLOWLIST of the states where the money is still ours and undisputed, plus
       -- 'declined' (the customer complained and the complaint was refused — their opinion is then
       -- the most informative rating on the platform). An unrecognised future state falls out of the
       -- list and is simply not asked, which is the safe direction to fail.
       and coalesce(t.refund_status, 'none') in ('none', 'window_open', 'declined')
       and coalesce(c.email, '') like '%@%'
       and lower(coalesce(c.email, '')) is distinct from coalesce(v_founder, '~none~')
       -- 3. STOP ASKING WHEN IT IS ANSWERED. A review closes the ask permanently.
       and not exists (select 1 from public.reviews r where r.transaction_id = t.id)
       -- 2. ASKED ONCE, EVER — looked up in ANY state.
       and not exists (select 1 from public.notifications n
                        where n.type = 'rating_request' and n.quote_id = t.quote_id)
     -- A deterministic order shared by every session, so two concurrent runs take the same key in
     -- the same sequence. With one target table, one lock per key and ON CONFLICT DO NOTHING, there
     -- is no second resource to hold and therefore no cycle: this cannot deadlock.
     order by t.revealed_at, t.quote_id
     limit greatest(coalesce(p_limit, 500), 1)
  ), ins as (
    -- 1. SUPPORT SENDS IT. public.notifications is the estate's one channel queue; kind
    -- 'support_agent' is already registered in founder_mail_policy as customer_support's own
    -- customer-facing mail. The Sales Engineer is not involved and no new send path exists.
    insert into public.notifications
      (type, kind, to_email, to_role, lead_id, inquiry_id, quote_id, subject, body, channel, status)
    select 'rating_request', 'support_agent', d.cemail, 'customer',
           d.supplier_id, d.inquiry_id, d.quote_id,
           'How did ' || coalesce(d.company_name, 'your supplier') || ' do?',
           'It has been about ' || v_days || ' days since you unlocked '
             || coalesce(d.company_name, 'this supplier')
             || coalesce(' for: ' || left(d.summary, 80), '')
             || '. Now that you have had the chance to actually work with them, please rate them out '
             || 'of 5 — communication, quality, punctuality, documentation and after-sales. Open the '
             || 'job in your portal and choose Rate supplier: ' || v_site || '/portal'
             || '. Ratings on QuotesDone come only from customers who have paid to reveal a supplier '
             || 'and dealt with them, so yours is what gives this company a score at all.',
           'email', 'queued'
      from due d
    on conflict (quote_id) where type = 'rating_request' and coalesce(channel, 'email') = 'email'
    do nothing
    returning 1
  )
  select count(*)::int into v_asked from ins;

  return jsonb_build_object('ok', true, 'asked', v_asked, 'days_after_reveal', v_days,
    'note', 'Enqueued into public.notifications as customer_support. send_outbox delivers; a row in any state means the ask was already made.');
end $function$


CREATE OR REPLACE FUNCTION public.fn_suppression_stops(p_reason text, p_type text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select lower(btrim(coalesce(p_reason, ''))) <> 'unsubscribe' or coalesce(p_type, '') = any (public.fn_opt_out_types())
$function$


CREATE OR REPLACE FUNCTION public.fn_table_export_change_tracking(p_apply boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_min bigint := coalesce(public.fn_it_threshold('export_incremental_min_bytes'), 67108864)::bigint;
  v_added text[] := '{}'; v_removed text[] := '{}'; v_refreshed text[] := '{}'; v_reasons jsonb := '{}'::jsonb;
  r record; v_pk text; v_npk integer; v_bytes bigint; v_proj text; v_have text; v_want boolean;
begin
  for r in select x.table_name as t from public.fn_table_export_list() x
            where x.table_name <> 'table_export_change'
  loop
    if to_regclass(format('public.%I', r.t)) is null then continue; end if;
    v_bytes := pg_total_relation_size(format('public.%I', r.t)::regclass);
    select count(*), min(a.attname::text) into v_npk, v_pk
      from pg_index i
      cross join lateral unnest(i.indkey) with ordinality k(attnum, ord)
      join pg_attribute a on a.attrelid = i.indrelid and a.attnum = k.attnum
     where i.indrelid = format('public.%I', r.t)::regclass and i.indisprimary;

    if v_bytes >= v_min and coalesce(v_npk, 0) <> 1 then
      -- Named out loud rather than silently left full: this table is big and CANNOT report changes.
      v_reasons := v_reasons || jsonb_build_object(r.t,
        format('%s bytes, at or over the threshold, but its primary key has %s columns, so it stays a full copy every day',
               v_bytes, coalesce(v_npk, 0)));
    end if;

    -- The exported projection, as the update trigger compares it. A column added to a tracked table
    -- later changes this string, and the branch below rebuilds the triggers with the new list -- a
    -- stale list would make a change to the new column invisible.
    select coalesce(string_agg(quote_ident(a.attname), ',' order by a.attnum), '') into v_proj
      from pg_attribute a
     where a.attrelid = format('public.%I', r.t)::regclass and a.attnum > 0 and not a.attisdropped
       and format_type(a.atttypid, a.atttypmod) not like 'vector%';
    select x.projection into v_have from public.table_export_change_tracked x where x.table_name = r.t;
    v_want := v_bytes >= v_min and coalesce(v_npk, 0) = 1;

    if v_want and (v_have is null or v_have is distinct from v_proj) then
      if p_apply then
        execute format('drop trigger if exists %I on public.%I', 'z90_' || r.t || '_export_change_ins', r.t);
        execute format('create trigger %I after insert on public.%I referencing new table as new_rows
                        for each statement execute function public.trg_table_export_change(%L, %L)',
                       'z90_' || r.t || '_export_change_ins', r.t, v_pk, v_proj);
        execute format('drop trigger if exists %I on public.%I', 'z90_' || r.t || '_export_change_upd', r.t);
        execute format('create trigger %I after update on public.%I referencing old table as old_rows new table as new_rows
                        for each statement execute function public.trg_table_export_change(%L, %L)',
                       'z90_' || r.t || '_export_change_upd', r.t, v_pk, v_proj);
        execute format('drop trigger if exists %I on public.%I', 'z90_' || r.t || '_export_change_del', r.t);
        execute format('create trigger %I after delete on public.%I referencing old table as old_rows
                        for each statement execute function public.trg_table_export_change(%L, %L)',
                       'z90_' || r.t || '_export_change_del', r.t, v_pk, v_proj);
        execute format('drop trigger if exists %I on public.%I', 'z90_' || r.t || '_export_change_trunc', r.t);
        execute format('create trigger %I after truncate on public.%I
                        for each statement execute function public.trg_table_export_change(%L, %L)',
                       'z90_' || r.t || '_export_change_trunc', r.t, v_pk, v_proj);
        insert into public.table_export_change_tracked (table_name, pk_column, projection, bytes_at_registration)
        values (r.t, v_pk, v_proj, v_bytes)
        on conflict (table_name) do update set pk_column = excluded.pk_column, projection = excluded.projection,
                                               bytes_at_registration = excluded.bytes_at_registration;
      end if;
      if v_have is null then v_added := v_added || r.t; else v_refreshed := v_refreshed || r.t; end if;
    elsif not v_want and v_have is not null then
      if p_apply then
        execute format('drop trigger if exists %I on public.%I', 'z90_' || r.t || '_export_change_ins', r.t);
        execute format('drop trigger if exists %I on public.%I', 'z90_' || r.t || '_export_change_upd', r.t);
        execute format('drop trigger if exists %I on public.%I', 'z90_' || r.t || '_export_change_del', r.t);
        execute format('drop trigger if exists %I on public.%I', 'z90_' || r.t || '_export_change_trunc', r.t);
        delete from public.table_export_change_tracked x where x.table_name = r.t;
        delete from public.table_export_change c where c.table_name = r.t;
      end if;
      v_removed := v_removed || r.t;
    end if;
  end loop;
  return jsonb_build_object('threshold_bytes', v_min, 'added', to_jsonb(v_added), 'removed', to_jsonb(v_removed),
                            'triggers_refreshed', to_jsonb(v_refreshed),
                            'stays_full_and_why', v_reasons, 'applied', p_apply,
                            'tracked', (select coalesce(jsonb_object_agg(x.table_name, x.pk_column), '{}'::jsonb)
                                          from public.table_export_change_tracked x));
end $function$


CREATE OR REPLACE FUNCTION public.fn_table_export_demo_ids()
 RETURNS TABLE(dc text[], dl text[], di text[], dq text[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  select coalesce(array_agg(c.id::text), '{}') into dc from public.customers c
   where coalesce(c.is_demo, false) or coalesce(c.email, '') ~* 'example\.invalid' or coalesce(c.full_name, '') ~* 'zz[_ -]?demo';
  select coalesce(array_agg(l.id::text), '{}') into dl from public.leads l
   where coalesce(l.is_demo, false) or coalesce(l.email, '') ~* 'example\.invalid' or coalesce(l.company_name, '') ~* 'zz[_ -]?demo';
  select coalesce(array_agg(i.id::text), '{}') into di from public.inquiries i where i.customer_id::text = any(dc);
  select coalesce(array_agg(q.id::text), '{}') into dq from public.quotes q
   where q.supplier_id::text = any(dl) or q.inquiry_id::text = any(di);
  return next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_table_export_due()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_local timestamp := now() at time zone 'Asia/Dubai';
  v_stamp date := (now() at time zone 'Asia/Dubai')::date;
  v_run public.table_export_run;
  v_kind text; v_since timestamptz; v_full_at timestamptz;
  v_resume jsonb;
begin
  if v_local::time < time '03:00' then
    return jsonb_build_object('due', false, 'stamp', v_stamp, 'reason', 'before 03:00 Asia/Dubai');
  end if;
  select * into v_run from public.table_export_run r where r.stamp = v_stamp for update;
  if not found then
    perform public.fn_table_export_change_tracking(true);
    select r.started_at - interval '6 hours' into v_since
      from public.table_export_run r where r.status = 'done' and r.stamp < v_stamp order by r.stamp desc limit 1;
    select max(r.started_at) into v_full_at
      from public.table_export_run r where r.status = 'done' and r.kind = 'full' and r.stamp < v_stamp;
    v_kind := case when extract(isodow from v_local) = 5 or v_since is null
                     or not exists (select 1 from public.table_export_run r
                                     where r.status = 'done' and r.kind = 'full' and r.stamp >= v_stamp - 7 and r.stamp < v_stamp)
                     -- a table that became change-tracked after the last full copy has no base yet
                     or exists (select 1 from public.table_export_change_tracked x
                                 where v_full_at is null or x.tracking_since > v_full_at)
                   then 'full' else 'incremental' end;
    if v_kind = 'full' then v_since := null; end if;
    insert into public.table_export_run (stamp, kind, since) values (v_stamp, v_kind, v_since) on conflict (stamp) do nothing;
    if not found then return jsonb_build_object('due', false, 'stamp', v_stamp, 'reason', 'claimed concurrently'); end if;
    return jsonb_build_object('due', true, 'stamp', v_stamp, 'attempt', 1, 'resume', null, 'kind', v_kind, 'since', v_since);
  end if;
  if v_run.status = 'done' then
    return jsonb_build_object('due', false, 'stamp', v_stamp, 'status', 'done', 'kind', v_run.kind);
  end if;
  if v_run.heartbeat_at > now() - interval '10 minutes' then
    return jsonb_build_object('due', false, 'stamp', v_stamp, 'status', v_run.status, 'reason', 'in progress or waiting to retry');
  end if;
  if v_run.attempts >= 6 then
    return jsonb_build_object('due', false, 'stamp', v_stamp, 'status', v_run.status, 'attempts', v_run.attempts, 'reason', 'gave up after 6 attempts');
  end if;
  v_resume := case
    when v_run.status = 'running' then v_run.state
    when v_run.status = 'failed' and jsonb_typeof(v_run.state->'queue') = 'array'
         and jsonb_array_length(v_run.state->'queue') > 0
         and (v_run.state->'errors') ? (v_run.state->'queue'->0->>'t') then v_run.state
  end;
  update public.table_export_run r
     set attempts = r.attempts + case when r.status = 'failed' then 1 else 0 end,
         status = 'running', heartbeat_at = now(),
         state = v_resume
   where r.stamp = v_stamp;
  return jsonb_build_object('due', true, 'stamp', v_stamp,
    'attempt', v_run.attempts + case when v_run.status = 'failed' then 1 else 0 end,
    'resume', v_resume,
    'kind', v_run.kind, 'since', v_run.since);
end $function$


CREATE OR REPLACE FUNCTION public.fn_table_export_filter(p_table text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_rel regclass := to_regclass(format('public.%I', p_table));
  v_where text;
begin
  if v_rel is null then raise exception 'fn_table_export_filter: public.% does not exist', p_table; end if;
  select format('(to_jsonb(t) - %L::text[])::text !~* %L', public.fn_table_export_stripped(p_table), 'zz[_ -]?demo|example\.invalid')
         || coalesce(string_agg(case a.attname
              when 'is_demo'     then ' and not coalesce(t.is_demo, false)'
              when 'customer_id' then ' and not coalesce(t.customer_id::text = any($1), false)'
              when 'supplier_id' then ' and not coalesce(t.supplier_id::text = any($2), false)'
              when 'lead_id'     then ' and not coalesce(t.lead_id::text = any($2), false)'
              when 'inquiry_id'  then ' and not coalesce(t.inquiry_id::text = any($3), false)'
              when 'quote_id'    then ' and not coalesce(t.quote_id::text = any($4), false)' end, ''), '')
    into v_where
    from pg_attribute a
   where a.attrelid = v_rel and a.attnum > 0 and not a.attisdropped
     and a.attname in ('is_demo', 'customer_id', 'supplier_id', 'lead_id', 'inquiry_id', 'quote_id');
  return v_where;
end $function$


CREATE OR REPLACE FUNCTION public.fn_table_export_finish(p_stamp date, p_manifest jsonb, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_day text := to_char(p_stamp, 'YYYY-MM-DD');
  v_bad text; v_queued integer; v_pruned integer := 0; v_run public.table_export_run;
begin
  select * into v_run from public.table_export_run r where r.stamp = p_stamp;
  if not found then return jsonb_build_object('ok', false, 'stamp', p_stamp, 'error', 'no table_export_run row for this day'); end if;
  if p_error is null then
    select string_agg(x.table_name, ', ') into v_bad
      from public.fn_table_export_list() x
     where coalesce((p_manifest->'tables'->x.table_name->>'pages')::int, -1)
           <> (select count(*) from storage.objects o
                where o.bucket_id = 'backups' and o.name like v_day || '/' || x.table_name || '/page\_%.json');
    if v_bad is not null then p_error := 'pages in storage disagree with the manifest for: ' || v_bad; end if;
    if p_error is null and not exists (select 1 from storage.objects o where o.bucket_id = 'backups' and o.name = v_day || '/_manifest.json') then
      p_error := 'the manifest is not in storage';
    end if;
  end if;

  if p_error is not null then
    update public.table_export_run r set status = 'failed', error = left(p_error, 2000), heartbeat_at = now()
     where r.stamp = p_stamp;
    return jsonb_build_object('ok', false, 'stamp', p_stamp, 'error', left(p_error, 500));
  end if;

  update public.table_export_run r set status = 'done', finished_at = now(), heartbeat_at = now(), manifest = p_manifest, error = null
   where r.stamp = p_stamp;
  -- a full copy holds every row, so changes logged well before it started are no longer needed
  if v_run.kind = 'full' then
    delete from public.table_export_change cl where cl.changed_at < v_run.started_at - interval '1 day';
    get diagnostics v_pruned = row_count;
  end if;
  v_queued := public.fn_enqueue_doc_backups();
  return jsonb_build_object('ok', true, 'stamp', p_stamp, 'kind', v_run.kind, 'queued_for_dropbox', v_queued, 'change_log_pruned', v_pruned);
end $function$


CREATE OR REPLACE FUNCTION public.fn_table_export_list()
 RETURNS TABLE(table_name text, subject text, change_log text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select v.t, v.s,
         (select 'table_export_change' from public.table_export_change_tracked x where x.table_name = v.t)
  from (values
    ('customers','customer'), ('customer_preference','customer'), ('customer_calls','customer'), ('projects','customer'),
    ('leads','supplier'), ('lead_category','supplier'), ('lead_subcategory','supplier'), ('supplier_capabilities','supplier'),
    ('supplier_catalog','supplier'), ('supplier_product','supplier'), ('supplier_product_variant','supplier'),
    ('supplier_capability_confirmation','supplier'), ('supplier_collaboration','supplier'), ('supplier_collaboration_event','supplier'),
    ('supplier_negotiation_policy','supplier'), ('supplier_screening_hit','supplier'), ('supplier_lead_intake','supplier'),
    ('doc_reviews','supplier'), ('licence_renewal_ask','supplier'), ('outreach','supplier'), ('company_registration','company'),
    ('inquiries','inquiry'), ('inquiry_intake','inquiry'), ('inquiry_matches','inquiry'), ('inquiry_requirement','inquiry'),
    ('inquiry_cancellations','inquiry'), ('inquiry_supplier_brief','inquiry'), ('inquiry_state_audit','inquiry'),
    ('inquiry_gate','inquiry'), ('inquiry_answer','inquiry'), ('inquiry_answer_document','inquiry'), ('inquiry_answer_scope','inquiry'),
    ('inquiry_workstream','inquiry'), ('inquiry_workstream_group','inquiry'), ('inquiry_workstream_requirement','inquiry'),
    ('inquiry_trade_candidate','inquiry'), ('inquiry_trade_clarification','inquiry'), ('inquiry_scope_disposition','inquiry'),
    ('rfq_archives','inquiry'), ('rfq_clarification','inquiry'),
    ('quotes','quote'), ('quote_items','quote'), ('quote_reviews','quote'), ('quote_review_messages','quote'),
    ('quote_requirements','quote'), ('quote_committed_items','quote'), ('quote_comparisons','quote'), ('quote_spec_hold','quote'),
    ('spec_alternative_offer','quote'), ('po_orders','quote'), ('po_vendors','quote'), ('questions','quote'), ('reviews','quote'),
    ('category_specs','quote rules'), ('category_quote_specs','quote rules'),
    ('transactions','payment'), ('reveal_invoices','payment'), ('supplier_dues','payment'), ('refunds','payment'),
    ('refund_case','payment'), ('refund_incident','payment'), ('refund_ceo_review','payment'), ('refund_ceo_check','payment'),
    ('refund_ladder_evidence','payment'), ('refund_status_transition','payment'), ('stripe_events','payment'),
    ('stripe_payout','payment'), ('stripe_dispute','payment'), ('charge_audit','payment'), ('pricing_config','payment'),
    ('gl_journal','accounting'), ('gl_journal_lines','accounting'), ('gl_expense_map','accounting'), ('expenses','accounting'),
    ('expense_entries','accounting'), ('bank_statement_intake','accounting'), ('bank_statement_line','accounting'),
    ('accountant_month_close','accounting'), ('accountant_issued_document','accounting'),
    ('messages','conversation'), ('chat_threads','conversation'), ('conversation_archive','conversation'),
    ('inbound_messages','conversation'), ('contact_messages','conversation'), ('complaint_tickets','conversation'),
    ('support_case','conversation'), ('support_notification','conversation'), ('support_document_intake','conversation'),
    ('wa_messages','conversation'), ('wa_conversation','conversation'), ('wa_turn','conversation'),
    ('wa_document_intake','conversation'), ('notifications','conversation'), ('agent_chats','conversation'),
    ('legal_reviews','legal'), ('pdpl_requests','legal'), ('pdpl_erase_files','legal'), ('email_suppressions','legal'),
    ('founder_instruction','decision'), ('company_policy_decision','decision'),
    ('kb_chunks','knowledge'), ('dept_library','knowledge'), ('ops_knowledge','knowledge'), ('agent_knowledge','knowledge'),
    ('sales_knowledge','knowledge'), ('ceo_knowledge','knowledge'), ('support_knowledge','knowledge'),
    ('accountant_knowledge','knowledge'), ('it_engineer_knowledge','knowledge'), ('employee_knowledge','knowledge'),
    ('marketing_post','marketing'), ('marketing_connection_check','marketing'), ('marketing_insight_day','marketing'),
    ('marketing_ad_spend_day','marketing'), ('marketing_duty_run','marketing'), ('marketing_report','marketing'),
    ('marketing_article','marketing'), ('marketing_prospect','marketing'), ('marketing_outreach_message','marketing'),
    ('marketing_platform_spec','marketing'), ('marketing_platform_spec_source','marketing'),
    ('marketing_campaign','marketing'), ('marketing_post_variant','marketing'),
    ('marketing_post_platform','marketing'), ('marketing_post_metric','marketing'), ('marketing_first_touch','marketing'),
    ('marketing_goal','marketing'), ('marketing_scorecard_report','marketing'),
    ('marketing_asset_feature','marketing'), ('marketing_asset_perception','marketing'), ('marketing_asset_review','marketing'),
    ('marketing_insight_note','marketing'), ('marketing_month_plan','marketing'), ('marketing_plan_review_turn','marketing'),
    ('marketing_model_run','marketing'), ('market_intel','marketing'), ('competitor','marketing'),
    ('table_export_change','backup')
  ) v(t, s)
  -- The sibling PRs' tables may not exist yet when this applies; backup/index.ts fails the whole day on a
  -- missing table, so ONLY those nine are skipped until their own file creates them. Every other table in the
  -- list still fails loudly if it disappears.
  where v.t not in ('marketing_platform_spec','marketing_platform_spec_source','marketing_campaign','marketing_post_variant',
                    'marketing_post_platform','marketing_post_metric','marketing_first_touch','marketing_goal','marketing_scorecard_report')
     or to_regclass('public.' || v.t) is not null
$function$


CREATE OR REPLACE FUNCTION public.fn_table_export_page(p_table text, p_after jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 1000, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_rel regclass; v_cols text; v_keyvals text; v_after text := 'true'; v_where text; v_log text; v_pk text; v_pktype text;
  v_strip text[]; v_lim integer := greatest(1, least(coalesce(p_limit, 1000), 1000));
  v_rows jsonb; v_n integer; v_last jsonb;
  v_dc text[]; v_dl text[]; v_di text[]; v_dq text[];   -- $1..$4, the positions fn_table_export_filter names
begin
  select x.change_log into v_log from public.fn_table_export_list() x where x.table_name = p_table;
  if not found then raise exception 'fn_table_export_page: % is not in fn_table_export_list()', p_table; end if;
  v_rel := to_regclass(format('public.%I', p_table));
  if v_rel is null then raise exception 'fn_table_export_page: public.% does not exist', p_table; end if;

  select string_agg(format('t.%I', a.attname), ', ' order by k.ord),
         string_agg(format('(($5->>%s)::%s)', k.ord - 1, format_type(a.atttypid, a.atttypmod)), ', ' order by k.ord),
         min(a.attname::text), min(format_type(a.atttypid, a.atttypmod))
    into v_cols, v_keyvals, v_pk, v_pktype
    from pg_index i
    cross join lateral unnest(i.indkey) with ordinality k(attnum, ord)
    join pg_attribute a on a.attrelid = i.indrelid and a.attnum = k.attnum
   where i.indrelid = v_rel and i.indisprimary;
  if v_cols is null then raise exception 'fn_table_export_page: public.% has no primary key to page on', p_table; end if;
  if p_after is not null then v_after := format('(%s) > (%s)', v_cols, v_keyvals); end if;

  v_strip := public.fn_table_export_stripped(p_table);
  v_where := public.fn_table_export_filter(p_table);
  select d.dc, d.dl, d.di, d.dq into v_dc, v_dl, v_di, v_dq from public.fn_table_export_demo_ids() d;
  if p_since is not null and v_log is not null then
    -- THE CAST GOES ON THE LOG, NEVER ON THE TABLE. Measured 18 Sep 2026: with `t.id::text in (...)`
    -- this statement outlived the management API gateway (524) on kb_chunks -- casting the primary key
    -- makes the index on it unusable and turns an incremental page into a sequential scan of 2.69 M
    -- rows over 9 GB, every page, every night. row_key was written from this very column, so casting it
    -- back is exact.
    v_where := v_where || format(
      ' and t.%I in (select cl.row_key::%s from public.table_export_change cl
                      where cl.table_name = %L and cl.changed_at >= $7 and not cl.deleted)',
      v_pk, v_pktype, p_table);
  end if;

  execute format(
    'select coalesce(jsonb_agg(y.j order by y.ord), ''[]''::jsonb), count(*)::int, (array_agg(y.k order by y.ord desc))[1]
       from (select row_number() over () as ord, x.k, x.j
               from (select jsonb_build_array(%1$s) as k, to_jsonb(t) - $6 as j
                       from public.%2$I t where %3$s and %4$s order by %1$s limit %5$s) x) y',
    v_cols, p_table, v_after, v_where, v_lim)
    into v_rows, v_n, v_last
    using v_dc, v_dl, v_di, v_dq, p_after, v_strip, p_since;

  return jsonb_build_object('table', p_table, 'rows', v_rows, 'n', v_n, 'last', v_last, 'done', v_n < v_lim,
                            'mode', case when p_since is not null and v_log is not null then 'changes_since' else 'full' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_table_export_replay(p_table text, p_base jsonb, p_increments jsonb DEFAULT '[]'::jsonb, p_changes jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_pk text; v_pktype text; v_npk integer; v_strip text[]; v_where text; v_proj text;
  v_dc text[]; v_dl text[]; v_di text[]; v_dq text[];   -- $1..$4, the positions fn_table_export_filter names
  v_lo text; v_hi text; v_inc jsonb; v_n integer;
  n_base integer := 0; n_upserted integer := 0; n_deleted integer := 0; n_rebuilt integer := 0;
  n_match integer := 0; n_changed integer := 0; n_gone integer := 0; n_lost integer := 0;
  v_lost_keys jsonb;
begin
  if to_regclass(format('public.%I', p_table)) is null then
    raise exception 'fn_table_export_replay: public.% does not exist', p_table;
  end if;
  if not exists (select 1 from public.fn_table_export_list() x where x.table_name = p_table) then
    raise exception 'fn_table_export_replay: % is not in fn_table_export_list()', p_table;
  end if;
  select count(*), min(a.attname::text), min(format_type(a.atttypid, a.atttypmod))
    into v_npk, v_pk, v_pktype
    from pg_index i
    cross join lateral unnest(i.indkey) with ordinality k(attnum, ord)
    join pg_attribute a on a.attrelid = i.indrelid and a.attnum = k.attnum
   where i.indrelid = format('public.%I', p_table)::regclass and i.indisprimary;
  if coalesce(v_npk, 0) <> 1 then
    raise exception 'fn_table_export_replay: public.% has a %-column primary key; only a single-column key is rebuilt', p_table, coalesce(v_npk, 0);
  end if;
  v_strip := public.fn_table_export_stripped(p_table);
  v_where := public.fn_table_export_filter(p_table);
  select d.dc, d.dl, d.di, d.dq into v_dc, v_dl, v_di, v_dq from public.fn_table_export_demo_ids() d;
  -- The exported projection, named column by column, for the same reason the trigger names it: a
  -- to_jsonb() of the whole row would serialise a 768-dimension embedding on both sides of every
  -- comparison only to subtract it again.
  select coalesce(string_agg(quote_ident(a.attname), ',' order by a.attnum), '') into v_proj
    from pg_attribute a
   where a.attrelid = format('public.%I', p_table)::regclass and a.attnum > 0 and not a.attisdropped
     and format_type(a.atttypid, a.atttypmod) not like 'vector%';

  execute format('create temp table it_replay_scratch (like public.%I) on commit drop', p_table);
  execute format('insert into it_replay_scratch select * from jsonb_populate_recordset(null::public.%I, $1)', p_table)
    using coalesce(p_base, '[]'::jsonb);
  get diagnostics n_base = row_count;
  if n_base = 0 then
    execute 'drop table it_replay_scratch';
    return jsonb_build_object('table', p_table, 'rebuilt', 0, 'lost_rows', -1,
                              'error', 'the base page carried no rows, so there is nothing to rebuild from');
  end if;
  -- The window is the base page's own key range, IN THE KEY'S OWN TYPE. Comparing keys as text would
  -- sort bigint 10 before 9 and silently rebuild the wrong window.
  execute format('select min(s.%1$I)::text, max(s.%1$I)::text from it_replay_scratch s', v_pk) into v_lo, v_hi;

  -- every later day, in order: its rows replace the keys they carry (an update is that row again), and
  -- anything it carries outside the base page's window is dropped, so the comparison stays bounded.
  for v_inc in select value from jsonb_array_elements(coalesce(p_increments, '[]'::jsonb)) loop
    execute format('delete from it_replay_scratch s where s.%1$I in
                      (select (r->>%2$L)::%3$s from jsonb_array_elements($1) r)', v_pk, v_pk, v_pktype)
      using coalesce(v_inc, '[]'::jsonb);
    execute format('insert into it_replay_scratch select * from jsonb_populate_recordset(null::public.%I, $1)', p_table)
      using coalesce(v_inc, '[]'::jsonb);
    get diagnostics v_n = row_count;
    n_upserted := n_upserted + v_n;
    execute format('delete from it_replay_scratch s where s.%1$I < ($1)::%2$s or s.%1$I > ($2)::%2$s', v_pk, v_pktype)
      using v_lo, v_hi;
  end loop;

  -- then the deletions the change log recorded, newest wins: a key whose LAST entry is a delete is gone.
  -- A row_key that does not parse as the key's own type is skipped (21 Sep 2026): the TRUNCATE branch of
  -- trg_table_export_change writes a sentence there with deleted = true, and on bigint kb_chunks the cast
  -- raised 22P02 and failed the whole replay. Measured before the fix. The truncate itself forced the
  -- next export day FULL, so skipping its marker loses nothing.
  execute format(
    'delete from it_replay_scratch s where s.%1$I in (
       select d.row_key::%2$s from (
         select distinct on (c->>''row_key'') c->>''row_key'' as row_key, (c->>''deleted'')::boolean as deleted
           from jsonb_array_elements($1) c
          where c->>''table_name'' = $2
          order by c->>''row_key'', (c->>''changed_at'') desc) d
        where d.deleted and pg_input_is_valid(d.row_key, %2$L))', v_pk, v_pktype)
    using coalesce(p_changes, '[]'::jsonb), p_table;
  get diagnostics n_deleted = row_count;
  execute 'select count(*) from it_replay_scratch' into n_rebuilt;

  -- compared with live over the columns the export carries (the vector columns are stripped at export)
  execute format(
    'select count(*) filter (where l.%1$I is not null and not ((%3$s) is distinct from (%4$s))),
            count(*) filter (where l.%1$I is not null and ((%3$s) is distinct from (%4$s))),
            count(*) filter (where l.%1$I is null)
       from it_replay_scratch s left join public.%2$I l on l.%1$I = s.%1$I',
    v_pk, p_table, 'l.' || replace(v_proj, ',', ', l.'), 's.' || replace(v_proj, ',', ', s.'))
    into n_match, n_changed, n_gone;

  -- THE ONE THAT FAILS THE DRILL: live rows inside the window that the rebuild does not hold and that
  -- no change-log entry names either. A row created after the last export IS named (its insert is
  -- logged), so this counts only rows the backup genuinely cannot give back. The demo rule is the
  -- export's own (fn_table_export_filter), or every demo row would read as a row the rebuild lost.
-- The excuse is the LATEST log entry, not any entry. Review finding, 18 Sep 2026: "any entry names it"
-- also excused a key whose last entry is a DELETE and which is nonetheless live today -- exactly the
-- shape a trigger-bypassing write leaves (session_replication_role=replica, ALTER TABLE ... DISABLE
-- TRIGGER, a raw restore, the truncate-and-reload path). That row is in no backup file and no log entry
-- claims it is, so it must count as lost.
  execute format(
    'create temp table it_replay_lost on commit drop as
       with latest as (
         select distinct on (c->>''row_key'') c->>''row_key'' as row_key, (c->>''deleted'')::boolean as deleted
           from jsonb_array_elements($7) c
          where c->>''table_name'' = $8
          order by c->>''row_key'', (c->>''changed_at'') desc)
       select t.%1$I::text as key
         from public.%2$I t
        where %3$s
          and t.%1$I >= ($5)::%4$s and t.%1$I <= ($6)::%4$s
          and not exists (select 1 from it_replay_scratch s where s.%1$I = t.%1$I)
          and not exists (select 1 from latest l where l.row_key = t.%1$I::text and not l.deleted)',
    v_pk, p_table, v_where, v_pktype)
    using v_dc, v_dl, v_di, v_dq, v_lo, v_hi, coalesce(p_changes, '[]'::jsonb), p_table;
  -- EXECUTE, not static SQL: a plpgsql plan cached against a temp table created in this call would
  -- point at a dead OID on the next one.
  execute 'select count(*)::int from it_replay_lost' into n_lost;
  execute 'select coalesce(jsonb_agg(k.key), ''[]''::jsonb) from (select key from it_replay_lost order by key limit 10) k'
    into v_lost_keys;
  execute 'drop table it_replay_lost';

  execute 'drop table it_replay_scratch';
  return jsonb_build_object('table', p_table, 'key_column', v_pk, 'key_lo', v_lo, 'key_hi', v_hi,
    'base_rows', n_base, 'increment_rows', n_upserted, 'deletes_applied', n_deleted, 'rebuilt', n_rebuilt,
    'identical_to_live', n_match, 'changed_since_export', n_changed, 'gone_from_live', n_gone,
    'lost_rows', n_lost, 'lost_keys_first_10', v_lost_keys, 'not_compared', to_jsonb(v_strip));
end $function$


CREATE OR REPLACE FUNCTION public.fn_table_export_save(p_stamp date, p_state jsonb)
 RETURNS boolean
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  update public.table_export_run r set state = p_state, heartbeat_at = now()
   where r.stamp = p_stamp and r.status = 'running'
  returning true;
$function$


CREATE OR REPLACE FUNCTION public.fn_table_export_stripped(p_table text)
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(array_agg(a.attname::text), '{}')
    from pg_attribute a
   where a.attrelid = to_regclass(format('public.%I', p_table)) and a.attnum > 0 and not a.attisdropped
     and format_type(a.atttypid, a.atttypmod) like 'vector%';
$function$


CREATE OR REPLACE FUNCTION public.fn_target_baseline(p_contract_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c record;
  v_val numeric;
  v_state text;
  v_note text;
begin
  select * into c from public.target_contract where id = p_contract_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'No such contract.');
  end if;

  if coalesce(btrim(c.measure_sql), '') = '' then
    v_state := 'not_instrumented';
    v_note  := 'NO INSTRUMENT EXISTS. The contract names an authoritative source but carries no measure. '
            || 'This needs an instrument built before it needs a number, and that is not a SQL task.';
    v_val   := null;
  else
    begin
      execute c.measure_sql into v_val;
      if v_val is null then
        v_state := 'unknown';
        v_note  := 'The measure ran and returned NULL. That is an unknown, not a zero.';
      else
        v_state := 'measured';
        v_note  := 'Measured live from the contract''s own measure_sql.';
      end if;
    exception when others then
      -- An error is never a zero. This is the distinction the estate got wrong once already.
      v_state := 'unknown';
      v_val   := null;
      v_note  := 'The measure FAILED and the baseline is therefore unknown, not zero. Error: '
              || left(sqlerrm, 200);
    end;
  end if;

  update public.target_contract
     set baseline_value = v_val,
         baseline_state = v_state,
         baseline_at    = now(),
         baseline_note  = v_note
   where id = p_contract_id;

  return jsonb_build_object(
    'ok', true,
    'contract_id', p_contract_id,
    'baseline_value', v_val,
    'baseline_state', v_state,
    'baseline_at', now(),
    'note', v_note
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_target_feasibility(p_contract_id bigint, p_record boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  c            record;
  d            record;
  v_days       int;
  v_remaining  numeric;
  v_cum_rate   numeric := 1.0;
  v_down_rate  numeric := 1.0;
  v_up_rate    numeric := 1.0;
  v_total_lag  int := 0;
  v_measured   int := 0;
  v_assumed    int := 0;
  v_stages     int := 0;
  v_top        numeric;
  v_top_down   numeric;
  v_top_up     numeric;
  v_binding    text := null;
  v_binding_why text := null;
  v_cap_limit  numeric;
  v_cost       numeric := 0;
  v_headroom   numeric;
  v_verdict    text;
  v_reason     text;
  v_changes    text[] := '{}';
  v_run_rate   numeric;
  v_required   numeric;
  v_eta        date;
  v_chain      jsonb := '[]'::jsonb;
  -- Stages that declare NO capacity ceiling. Treating an undeclared capacity as an infinite one is
  -- how this function first blessed 16,129 invitations in 30 days from a list of 19,896 addresses on
  -- a domain already bouncing at 10%. Silence about a ceiling is not evidence of headroom.
  v_undeclared text[] := '{}';
  -- THE SAFETY ENVELOPE. A channel's safe throughput is a property of the channel, not of how badly
  -- we want the target. Budget and internal capacity are negotiable; sender reputation is not, because
  -- losing it costs every sign-in code and receipt that shares the domain. So this overrides.
  v_chan       jsonb;
  v_chan_block text := null;
  v_chan_why   text := null;
  v_chan_safe  numeric;
begin
  select * into c from public.target_contract where id = p_contract_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'No such contract.');
  end if;

  v_days := greatest(0, (c.deadline - (now() at time zone c.timezone)::date));

  -- Remaining outcome. For an incremental target the baseline does not subtract.
  if c.desired_basis = 'incremental' then
    v_remaining := c.desired_value;
  else
    v_remaining := c.desired_value - coalesce(c.baseline_value, 0);
  end if;

  -- Walk the chain. cum_rate is the product of every stage's conversion, so the top of funnel
  -- required is remaining / cum_rate.
  for d in
    select * from public.target_driver where contract_id = p_contract_id order by stage_order
  loop
    v_stages := v_stages + 1;
    v_cum_rate := v_cum_rate * d.rate;

    -- Downside and upside bracket an assumed rate by half and double, bounded at 1. A measured rate
    -- is bracketed far more tightly, because we actually know it.
    if d.rate_source = 'measured' then
      v_measured := v_measured + 1;
      v_down_rate := v_down_rate * greatest(d.rate * 0.75, 0.0001);
      v_up_rate   := v_up_rate   * least(d.rate * 1.25, 1.0);
    else
      v_assumed := v_assumed + 1;
      v_down_rate := v_down_rate * greatest(d.rate * 0.5, 0.0001);
      v_up_rate   := v_up_rate   * least(d.rate * 2.0, 1.0);
    end if;

    v_total_lag := v_total_lag + d.lag_days;

    v_chain := v_chain || jsonb_build_object(
      'stage', d.stage_key,
      'label', d.stage_label,
      'rate', d.rate,
      'rate_source', d.rate_source,
      'lag_days', d.lag_days,
      'capacity_per_day', d.capacity_per_day,
      'unit_cost', d.unit_cost
    );
  end loop;

  -- No chain means no model. Say so rather than inventing one.
  if v_stages = 0 then
    v_verdict := 'CANNOT_ASSESS';
    v_reason  := 'No driver model exists for this contract. Without a causal chain there is no way to '
              || 'say what volume of activity produces the outcome, and any number would be invented.';
    v_changes := array['Build the driver model: name each stage from controllable activity to outcome, with its rate and whether that rate was measured or assumed.'];
  elsif c.baseline_state <> 'measured' then
    v_verdict := 'CANNOT_ASSESS';
    v_reason  := 'The baseline is ' || c.baseline_state || '. A gap cannot be computed from an unknown '
              || 'starting point, and treating it as zero is the error this column exists to prevent.';
    v_changes := array['Instrument the baseline, or record explicitly that it is a measured zero.'];
  end if;

  v_top      := case when v_cum_rate  > 0 then v_remaining / v_cum_rate  else null end;
  v_top_down := case when v_down_rate > 0 then v_remaining / v_down_rate else null end;
  v_top_up   := case when v_up_rate   > 0 then v_remaining / v_up_rate   else null end;

  -- Cost: sum the unit cost of every stage against the volume that stage must carry.
  declare
    v_vol numeric := v_top;
  begin
    for d in select * from public.target_driver where contract_id = p_contract_id order by stage_order loop
      if d.unit_cost is not null and v_vol is not null then
        v_cost := v_cost + (v_vol * d.unit_cost);
      end if;
      if v_vol is not null then v_vol := v_vol * d.rate; end if;
    end loop;
  end;

  -- Capacity: the first stage whose per-day ceiling cannot carry its required volume in the time left
  -- is the binding constraint. Lag is subtracted, because a stage that takes 7 days to convert does
  -- not get all 30 days of runway.
  declare
    v_vol numeric := v_top;
    v_usable_days int;
  begin
    for d in select * from public.target_driver where contract_id = p_contract_id order by stage_order loop
      v_usable_days := greatest(1, v_days - v_total_lag);
      if d.capacity_per_day is not null and v_vol is not null then
        v_cap_limit := d.capacity_per_day * v_usable_days;
        if v_vol > v_cap_limit and v_binding is null then
          v_binding := d.stage_key;
          v_binding_why := format(
            'Stage %s must carry %s units but its ceiling is %s per day over %s usable days, which is %s.',
            d.stage_key, round(v_vol, 1), d.capacity_per_day, v_usable_days, round(v_cap_limit, 1));
        end if;
      elsif d.capacity_per_day is null and d.channel_key is null then
        v_undeclared := array_append(v_undeclared,
          format('%s (must carry %s over %s usable days)', d.stage_key, round(coalesce(v_vol,0),0), v_usable_days));
      end if;

      -- The channel check. A stage that names a channel is capped by that channel's policy no matter
      -- what the budget or the internal capacity allows.
      if d.channel_key is not null and v_vol is not null then
        v_chan := public.fn_channel_safe_volume(d.channel_key, v_vol, v_usable_days);
        if coalesce((v_chan->>'ok')::boolean, false) = false and v_chan_block is null then
          v_chan_block := d.stage_key;
          v_chan_safe  := (v_chan->>'safe_max')::numeric;
          v_chan_why   := v_chan->>'reason';
        end if;
      end if;
      if v_vol is not null then v_vol := v_vol * d.rate; end if;
    end loop;
  end;

  v_headroom := case when c.budget_amount is null then null else c.budget_amount - v_cost end;

  -- Run rate so far, and the pace required from here.
  v_run_rate := case when c.baseline_at is not null and c.activated_at is not null
                       and c.baseline_at > c.activated_at
                     then coalesce(c.baseline_value,0) / greatest(1, extract(day from c.baseline_at - c.activated_at))
                     else null end;
  v_required := case when v_days > 0 then v_remaining / v_days else null end;
  v_eta := case when v_run_rate is not null and v_run_rate > 0
                then (now() at time zone c.timezone)::date + ceil(v_remaining / v_run_rate)::int
                else null end;

  -- The verdict, if the two hard refusals above did not already set it.
  if v_verdict is null then
    -- THE SAFETY ENVELOPE IS CHECKED FIRST, because it is the only constraint that cannot be bought
    -- out of. A cheaper plan, a longer deadline or more staff do not restore a blacklisted domain.
    if v_chan_block is not null then
      v_verdict := 'NOT_ACHIEVABLE';
      v_reason  := 'The channel that carries this plan cannot carry it safely. ' || v_chan_why;
      v_changes := array_append(v_changes, format(
        'Cap stage %s at %s, which is what the channel can safely carry, and make up the difference on '
        || 'another channel or renegotiate the target. Raising the volume is not an option here: budget '
        || 'and capacity are negotiable, sender reputation is not.',
        v_chan_block, round(coalesce(v_chan_safe,0),0)));
      v_changes := array_append(v_changes,
        'Open a separate outreach domain and warm it, so cold volume never shares a reputation with sign-in codes and receipts.');
    elsif v_binding is not null then
      v_verdict := 'NOT_ACHIEVABLE';
      v_reason  := 'A capacity ceiling binds before the deadline. ' || v_binding_why;
      v_changes := array_append(v_changes, format('Raise capacity at stage %s, extend the deadline, or reduce the desired value.', v_binding));
    elsif c.budget_amount is not null and v_cost > c.budget_amount then
      v_verdict := 'NOT_ACHIEVABLE';
      v_reason  := format('The plan costs %s against a budget of %s, so it cannot be funded as designed.',
                          round(v_cost,2), c.budget_amount);
      v_changes := array_append(v_changes, format('Raise the budget to %s, improve a conversion rate, or reduce the desired value.', round(v_cost,2)));
    elsif array_length(v_undeclared, 1) > 0 then
      -- An undeclared ceiling is not headroom. Say the volume out loud and make someone declare it.
      v_verdict := 'AT_RISK';
      v_reason  := format('The arithmetic is fundable, but %s stage(s) declare no capacity ceiling: %s. '
                       || 'An undeclared ceiling is an unchecked assumption, not evidence of headroom, and it is '
                       || 'exactly how a plan that looks affordable turns out to be physically impossible.',
                          array_length(v_undeclared,1), array_to_string(v_undeclared, '; '));
      v_changes := array_append(v_changes,
        format('Declare a real capacity_per_day for: %s. If the true ceiling cannot carry the volume, the target changes, not the ceiling.',
               array_to_string(v_undeclared, ', ')));
    elsif v_measured = 0 then
      v_verdict := 'AT_RISK';
      v_reason  := format('The chain is arithmetically fundable and within capacity, but every one of its %s '
                       || 'rates is assumed rather than measured here. The plan is a hypothesis, not a forecast.', v_stages);
      v_changes := array_append(v_changes, 'Measure at least the first conversion rate on a small controlled batch before scaling.');
    elsif v_assumed > v_measured then
      v_verdict := 'AT_RISK';
      v_reason  := format('%s of %s rates are assumed rather than measured, so the downside case (%s at top of funnel) '
                       || 'is far from the base case (%s).', v_assumed, v_stages, round(coalesce(v_top_down,0),0), round(coalesce(v_top,0),0));
      v_changes := array_append(v_changes, 'Convert the largest assumed rate into a measured one before committing the full budget.');
    else
      v_verdict := 'ACHIEVABLE';
      v_reason  := format('Requires %s at the top of the funnel over %s days, within capacity and budget, '
                       || 'on %s measured rates of %s.', round(coalesce(v_top,0),0), v_days, v_measured, v_stages);
    end if;
  end if;

  if p_record then
    insert into public.target_verdict (
      contract_id, remaining_outcome, days_remaining, current_run_rate, required_run_rate,
      expected_completion, scenario_downside, scenario_base, scenario_upside,
      binding_stage, binding_reason, required_top_of_funnel, projected_cost, budget_headroom,
      verdict, verdict_reason, what_must_change, measured_rate_count, assumed_rate_count
    ) values (
      p_contract_id, v_remaining, v_days, v_run_rate, v_required,
      v_eta, v_top_down, v_top, v_top_up,
      v_binding, v_binding_why, v_top, nullif(v_cost,0), v_headroom,
      v_verdict, v_reason, v_changes, v_measured, v_assumed
    );
  end if;

  return jsonb_build_object(
    'ok', true,
    'contract', c.contract_key,
    'version', c.version,
    'objective', c.objective,
    'baseline', jsonb_build_object('value', c.baseline_value, 'state', c.baseline_state, 'at', c.baseline_at),
    'remaining_outcome', v_remaining,
    'days_remaining', v_days,
    'total_lag_days', v_total_lag,
    'required_run_rate_per_day', round(coalesce(v_required,0), 2),
    'chain', v_chain,
    'cumulative_rate', v_cum_rate,
    'required_top_of_funnel', jsonb_build_object(
       'downside', round(coalesce(v_top_down,0),0),
       'base',     round(coalesce(v_top,0),0),
       'upside',   round(coalesce(v_top_up,0),0)),
    'projected_cost', round(v_cost, 2),
    'budget_amount', c.budget_amount,
    'budget_headroom', round(coalesce(v_headroom,0), 2),
    'binding_stage', v_binding,
    'binding_reason', v_binding_why,
    'channel_blocked_stage', v_chan_block,
    'channel_safe_max', v_chan_safe,
    'channel_reason', v_chan_why,
    'rates_measured', v_measured,
    'rates_assumed', v_assumed,
    'verdict', v_verdict,
    'verdict_reason', v_reason,
    'what_must_change', to_jsonb(v_changes)
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_task_approve(p_dry_run boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  r            record;
  v_auth       jsonb;
  v_granted    text;
  v_ceiling    text;
  v_tier       text;
  v_final      text;
  v_why        text;
  v_reason     text;
  v_decision   text;
  v_authreason text;
  v_rep_key    text;
  v_rep_tier   text;
  v_promoted   int := 0;
  v_held       int := 0;
  v_lane       int := 0;
  v_sample     jsonb := '[]'::jsonb;
  -- Mirrors AUTONOMOUS_CEILING in supabase/functions/dept_plan/index.ts byte for byte.
  c_ceiling constant text[] := array['content_draft','knowledge_fill','recommend','invite',
                                     'analysis','research','seo','monitor','reconcile','outreach_draft'];
begin
  for r in
    select id, dept_key, action_class, tier, coalesce(needs_founder,false) needs_founder,
           coalesce(decided_by,'(unattributed)') decided_by, title, assigned_agent
      from org_tasks
     where status = 'proposed'
     order by id
  loop
    v_auth       := fn_dept_authority(r.dept_key, r.action_class);
    v_authreason := coalesce(v_auth->>'reason', 'no reason given');
    v_granted    := coalesce(nullif(v_auth->>'tier',''), 'gated');
    if v_granted not in ('advisory','gated','supervised','autonomous') then v_granted := 'gated'; end if;

    -- WHO WILL DO IT, AND HOW HAS THEIR WORK BEEN GRADED. The assignee when one exists, else the
    -- proposer; an employee on reputation probation does not get its task waved through.
    v_rep_key := coalesce(r.assigned_agent, nullif(r.decided_by, '(unattributed)'));
    select p.tier into v_rep_tier from public.agent_reputation p where p.agent_key = v_rep_key;

    v_ceiling := case when r.action_class = any(c_ceiling) then 'autonomous' else 'gated' end;
    v_tier    := case when fn_authority_rank(v_granted) > fn_authority_rank(v_ceiling)
                      then v_ceiling else v_granted end;
    v_final   := case when r.needs_founder and fn_authority_rank(v_tier) > fn_authority_rank('gated')
                      then 'gated' else v_tier end;
    if v_rep_tier = 'probation' and v_final <> 'gated' then v_final := 'gated'; end if;

    -- Name the ACTUAL cause. Four different things produce a hold and they need different fixes:
    -- a hard gate is permanent, a missing org_authority row is a configuration gap someone should
    -- close, a ceiling clamp is a deliberate refusal to widen autonomy from a file, and a probation
    -- tier is the employee's own record.
    if v_final <> 'gated' then
      v_decision := 'approve';
      v_reason := 'Approved by the authority model: ' || r.dept_key || '/' || r.action_class
        || ' resolves to tier "' || v_final || '" (' || v_authreason || '); '
        || coalesce(v_rep_key, 'nobody') || ' holds reputation tier '
        || coalesce(v_rep_tier, 'unmeasured') || '. '
        || 'No founder gate applies — decision_policy.founder_review_gates covers refunds outside '
        || 'policy, money moves above the limit, published marketing, legal action, strategy '
        || 'changes, partnerships and executive security incidents only.';
    else
      v_decision := 'hold';
      if v_rep_tier = 'probation' then
        v_why := coalesce(v_rep_key, 'the proposer') || ' is on reputation probation, and a task '
              || 'of theirs is reviewed before it runs';
      elsif v_granted = 'gated' then
        v_why := 'the authority model itself grants no more than "gated" — ' || v_authreason;
      elsif fn_authority_rank(v_granted) > fn_authority_rank(v_ceiling) then
        v_why := 'org_authority grants "' || v_granted || '" but "' || r.action_class
              || '" sits outside AUTONOMOUS_CEILING, so it is clamped to "gated". Widening that set '
              || 'is a change to this routine''s AUTONOMOUS_CEILING constant, not an edit to the task';
      else
        v_why := 'the task was written with needs_founder=true by ' || r.decided_by
              || ', and needs_founder can only tighten';
      end if;
      v_reason := 'Held for review: ' || r.dept_key || '/' || r.action_class || ' — ' || v_why || '.';
    end if;

    if not p_dry_run then
      -- Idempotent on the DECISION, not on the run. An hourly sweep must not restate the same
      -- verdict 24 times a day; it must speak the moment a verdict CHANGES.
      insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent,
                                stage, decision, reason, confidence)
      select 'org_task', r.id::text, r.dept_key, r.decided_by, 'approval_path',
             'approval', v_decision, v_reason, 1.0
      where not exists (
        select 1 from review_chain rc
         where rc.subject_type = 'org_task' and rc.subject_id = r.id::text
           and rc.stage = 'approval' and rc.decision = v_decision);

      if v_decision = 'hold' and not r.needs_founder then
        -- A HOLD HAS AN OWNER (5 Sep 2026). A gated proposal used to stay 'proposed' with nobody named,
        -- and the OS showed it to the founder as his decision. His standing rule: nothing reaches him
        -- except a Stripe refund — and the only class that may carry needs_founder is refund_decision
        -- (a00_org_tasks_founder_routing_refund_only). So a hold enters the org_task lane at tier
        -- 'gated': the department determines it from company knowledge, the accountable colleague
        -- reviews it, and the lane invokes no executor above low/advisory_safe/reversible at that tier.
        -- The review_chain 'hold' verdict above stays on record; the row also says why it was held.
        update org_tasks
           set status = 'assigned', tier = 'gated', needs_founder = false,
               decided_by = 'approval_path', updated_at = now(),
               result = coalesce(result, '{}'::jsonb) || jsonb_build_object(
                 'held', jsonb_build_object('at', now(), 'by', 'fn_task_approve', 'reason', v_reason,
                   'owner_basis', 'a hold is reviewed by the department in the org_task lane at tier gated, never by the founder'))
         where id = r.id;
        v_lane := v_lane + 1;
      end if;

      if v_decision = 'approve' then
        -- Write the RESOLVED tier, exactly as dept_plan does. Leaving the stale tier behind is the
        -- same "permission in the payload" defect audit 7.3 fixed in fn_event_dispatch, and
        -- cos_execute reads t.tier for its advisory_safe and review_pending decisions.
        update org_tasks
           set status = 'assigned', tier = v_final, needs_founder = false,
               decided_by = 'approval_path', updated_at = now()
         where id = r.id;
      end if;
    end if;

    if v_decision = 'approve' then v_promoted := v_promoted + 1; else v_held := v_held + 1; end if;
    if jsonb_array_length(v_sample) < 12 then
      v_sample := v_sample || jsonb_build_array(jsonb_build_object(
        'task', r.id, 'dept', r.dept_key, 'class', r.action_class,
        'granted', v_granted, 'final', v_final, 'decision', v_decision,
        'reputation', jsonb_build_object('agent', v_rep_key, 'tier', v_rep_tier)));
    end if;
  end loop;

  return jsonb_build_object(
    'dry_run', p_dry_run,
    'considered', v_promoted + v_held,
    'approved', v_promoted,
    -- 'held' counts every hold verdict; of those, only a needs_founder (refund) row stays 'proposed'.
    'held', v_held,
    'held_into_lane', v_lane,
    'held_for_founder', v_held - v_lane,
    'sample', v_sample);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_task_is_demand(p_action_class text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select coalesce(p_action_class,'') ~*
    -- the revenue path: someone outside the company is on the other end of it
    '(invite|quote|rfq|inquir|lead|customer|supplier|onboard|registration|approv|kyc|collection|payment|refund|dispute|contract|delivery|fulfil)'
$function$


CREATE OR REPLACE FUNCTION public.fn_task_lesson(p_task_id bigint, p_outcome text, p_review jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  t record; v_id bigint; v_kind text; v_conf numeric; v_detail text; v_what text;
  v_verdict text; v_result text; v_basis text;
begin
  select o.id, o.dept_key, o.title, o.action_class, o.tier, o.result, o.status from org_tasks o
    into t where o.id = p_task_id;
  if t.id is null then return null; end if;

  -- What the review actually found, in the review's own words. Violations first because a failure
  -- is the lesson; dissents next; otherwise the approval and who gave it.
  select string_agg(distinct (v->>'rule') || ' (' || (v->>'severity') || '): ' || coalesce(v->>'why',''), ' | ')
    into v_detail from jsonb_array_elements(coalesce(p_review->'violations','[]'::jsonb)) v;

  if v_detail is null or v_detail = '' then
    select string_agg((d->>'by') || ' ' || (d->>'stance') || ': ' || left(coalesce(d->>'reasoning',''), 300), ' | ')
      into v_detail from jsonb_array_elements(coalesce(p_review->'dissents','[]'::jsonb)) d;
  end if;

  if p_outcome = 'event_closed' then
    -- xos-10. The Knowledge OS captures what a DISPATCHED EVENT produced, GRADED against the row.
    select c.decision into v_verdict
      from review_chain c
     where c.subject_type = 'org_task' and c.subject_id = t.id::text
       and c.stage in ('published','cos_review','dept_review') and c.decision is not null
     order by c.created_at desc, c.id desc
     limit 1;

    v_result := coalesce(nullif(t.result->>'summary',''), '');
    v_kind   := 'lesson';

    if coalesce(v_verdict,'') in ('reject','request_revision','hold_for_human','escalate')
       or coalesce(t.result->'executed'->>'error','') <> ''
       or v_result ~* '^\s*executor error'
       or coalesce(t.status,'') not in ('done','closed') then
      v_kind  := 'lesson_learned';
      v_conf  := 0.85;   -- a failure is the most useful thing this loop can record
      v_what  := 'worse';
      v_basis := case when coalesce(v_verdict,'') <> '' then 'the review verdict "' || v_verdict || '"'
                      else 'the outcome the task itself recorded' end;
    elsif v_result = '' then
      v_conf  := 0.4;    -- below the 0.6 retrieval floor: nothing was recorded, so there is nothing to serve
      v_what  := 'no_change';
      v_basis := 'the absence of any recorded result';
    else
      v_conf  := 0.6;    -- the floor fn_agent_institutional_memory serves from
      v_what  := 'success';
      v_basis := case when coalesce(v_verdict,'') <> '' then 'the review verdict "' || v_verdict || '"'
                      else 'the result the task recorded on closing' end;
    end if;

    v_detail := 'Raised by ' || coalesce(p_review->>'event_type','a company event')
             || ' on the bus and closed by ' || t.dept_key || '. Result: '
             -- org_tasks.result is JSONB, not text: the OS writes {at, mode, brain, summary} and
             -- the summary is the part that is a lesson. `nullif(t.result,'')` casts '' to jsonb
             -- at CALL time — it survived a staging apply that had no closed tasks to iterate and
             -- failed on production's 58. ->> returns text and never has to cast.
             || left(coalesce(nullif(v_result,''), 'closed with no recorded result'), 600)
             || '. Correlation ' || coalesce(p_review->>'correlation_id','unknown')
             || '. Graded ' || v_what || ' on ' || v_basis || '.';
  elsif p_outcome = 'published' and (v_detail is null or v_detail = '') then
    v_kind   := 'lesson';
    v_conf   := 0.5;   -- recorded for the audit trail; below fn_agent_institutional_memory's 0.6 floor
    v_detail := 'Cleared the quality standard for a department deliverable on the first pass and was '
             || 'approved by ' || coalesce(p_review->>'reviewer','the department head') || ' and the Chief of Staff.';
    v_what   := 'success';
  elsif p_outcome = 'published' then
    v_kind   := 'lesson_learned';
    v_conf   := 0.85;  -- shipped OVER a recorded objection: the most useful thing to remember
    v_detail := 'Approved and published despite a recorded objection. ' || v_detail;
    v_what   := 'success_over_dissent';
  else
    v_kind   := 'lesson_learned';
    v_conf   := 0.85;
    v_detail := 'Returned by review (' || p_outcome || '). ' || coalesce(v_detail, 'see review_chain');
    v_what   := 'worse';
  end if;

  insert into institutional_memory
    (kind, subject_type, subject_id, headline, detail, outcome, learned_by, confidence,
     evidence_ref, visible_to, occurred_at)
  values (v_kind, 'org_task', t.id::text,
          left(t.dept_key || ': ' || coalesce(t.title,'(untitled task)'), 200),
          left(v_detail, 2000), v_what, t.dept_key, v_conf,
          case when p_outcome = 'event_closed'
               then 'event_delivery:org_task:' || t.id
               else 'review_chain:org_task:' || t.id end,
          array[t.dept_key], now())
  returning id into v_id;

  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_task_review(p_task_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  t             record;
  v_text        text;
  v_deliverable text;
  v_author      text;
  v_chain       jsonb;
  v_outcome     text;
  v_rule        record;
  v_ch          jsonb;
  v_dept        text;
  v_blocked     boolean := false;
  v_blocker     text;
  v_dissents    jsonb := '[]'::jsonb;
  v_involved    jsonb := '[]'::jsonb;
  v_rules_hit   int := 0;
  v_own_resp    text;
  v_own_os      text;
  v_own_agent   text;
begin
  select o.id, o.dept_key, o.title, o.detail, o.action_class, o.result, o.tier, o.assigned_agent
    into t from org_tasks o where o.id = p_task_id;
  if t.id is null then
    return jsonb_build_object('error', 'no such task', 'task_id', p_task_id);
  end if;

  v_deliverable := coalesce(t.result->>'deliverable', '');
  if v_deliverable = '' then
    return jsonb_build_object('task_id', p_task_id, 'outcome', 'no_deliverable',
      'reason', 'The task carries no deliverable to review.');
  end if;

  -- WHO ACTUALLY WROTE IT (4 Sep 2026). This was `coalesce(d.brain_agent, d.lead_agent, dept_key)` —
  -- the department head, whoever performed the work. fn_pick_reviewer then correctly refuses to let a
  -- head approve its own output, and for the Office of the CEO there is nobody above the ceo, so every
  -- exec task escalated on an authorship nobody claimed. The row records its worker; read it.
  select coalesce(nullif(t.result->>'employee',''), nullif(t.assigned_agent,''),
                  d.brain_agent, d.lead_agent, t.dept_key)
    into v_author
    from org_departments d where d.dept_key = t.dept_key;
  if v_author is null then
    v_author := coalesce(nullif(t.result->>'employee',''), nullif(t.assigned_agent,''), t.dept_key);
  end if;

  -- STAGE 1+2: department head, then Chief of Staff. This is fn_review_submit unchanged — the
  -- reviewer is resolved live through delegation_rule and seniority, so a head who is unavailable
  -- delegates rather than silently approving.
  v_chain   := fn_review_submit('org_task', p_task_id::text, t.dept_key, v_author, v_deliverable);
  v_outcome := v_chain->>'outcome';

  -- STAGE 3: the challenge. Deterministic, so it runs on every task rather than being rationed.
  v_text := coalesce(t.title,'') || ' ' || coalesce(t.detail,'') || ' ' || coalesce(t.action_class,'');

  -- STAGE 0 OF THE RECORD, WRITTEN HERE: WHO OWNS THIS PROCESS.
  -- The responsibility is matched on its own words, longest first, so 'business development' wins
  -- over 'sales' when both occur. position() and not LIKE: 35 of the 72 responsibility values carry
  -- an underscore, and on the pattern side of LIKE an underscore is a single-character wildcard.
  select r.responsibility, r.os_key into v_own_resp, v_own_os
    from os_responsibility r
   where position(replace(r.responsibility, '_', ' ') in lower(v_text)) > 0
   order by length(r.responsibility) desc, r.responsibility
   limit 1;
  if v_own_os is null then
    select d.os_key into v_own_os from os_department d
     where d.dept_key = t.dept_key order by d.os_key limit 1;
  end if;
  select o.owner_agent into v_own_agent from operating_system o
   where o.os_key = v_own_os and o.active
     and exists (select 1 from org_agents a where a.agent_key = o.owner_agent and a.active);
  if v_own_agent is not null and v_own_agent is distinct from v_author then   -- an owner who authored it is already accountable; a self-review row is refused by the chain guard
    insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent,
                              stage, decision, reason, confidence)
    select 'org_task', p_task_id::text, t.dept_key, v_author, v_own_agent, 'ownership', 'owned',
           'os_responsibility routes this work to the ' || v_own_os || ' OS'
             || case when v_own_resp is null
                     then ', taken from the owning OS of the ' || t.dept_key || ' department because '
                          || 'no declared responsibility matched the task'
                     else ', which is the declared owner of the responsibility "' || v_own_resp || '"'
                end
             || '. Accountable to the company for it: ' || v_own_agent || '.', 1.0
     where not exists (select 1 from review_chain rc
                        where rc.subject_type = 'org_task' and rc.subject_id = p_task_id::text
                          and rc.stage = 'ownership');
  end if;

  for v_rule in
    select c.*,
           -- ponytail: word-overlap matcher, deliberately conservative. A rule applies only when
           -- the task belongs to the rule's OWN department and at least two of the situation's
           -- distinctive words appear in the task. It under-matches rather than over-matches:
           -- "Publishing anything externally" will not fire on a task titled "Draft Q3 posts".
           -- Upgrade path when the founder wants precision is an action_class[] or match_pattern
           -- column on collaboration_rule, matched here instead of the word overlap.
           (select count(*) from unnest(string_to_array(
                    regexp_replace(lower(c.situation), '[^a-z ]', ' ', 'g'), ' ')) w
             where length(w) > 4 and position(w in lower(v_text)) > 0) hits
      from collaboration_rule c
     where c.owner_dept = t.dept_key
  loop
    if v_rule.hits < 2 then continue; end if;
    v_rules_hit := v_rules_hit + 1;

    -- Who the rule says must take part, recorded as its own reviewable stage so that "this needed
    -- legal and legal never saw it" is answerable after the fact.
    v_involved := v_involved || jsonb_build_object(
      'situation', v_rule.situation, 'must_involve', to_jsonb(v_rule.must_involve),
      'must_review', to_jsonb(v_rule.must_review), 'blocking', v_rule.blocking);

    insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent,
                              stage, decision, reason, confidence)
    values ('org_task', p_task_id::text, t.dept_key, v_author,
            coalesce((v_rule.must_review)[1], 'exec'), 'collaboration',
            case when v_rule.blocking then 'required' else 'advisory' end,
            'collaboration_rule #' || v_rule.id || ' applies ("' || v_rule.situation || '"): '
              || 'involve ' || coalesce(array_to_string(v_rule.must_involve, ', '), '(none)')
              || '; review by ' || coalesce(array_to_string(v_rule.must_review, ', '), '(none)')
              || '; may be challenged by ' || coalesce(array_to_string(v_rule.may_challenge, ', '), '(none)')
              || '. Why this rule exists: ' || v_rule.reason, 1.0);

    -- Each department the rule permits to challenge actually challenges.
    foreach v_dept in array coalesce(v_rule.may_challenge, array[]::text[]) loop
      v_ch := fn_challenge(v_text, t.dept_key, v_dept);
      if (v_ch->>'stance') <> 'support' then
        v_dissents := v_dissents || jsonb_build_object(
          'by', v_dept, 'stance', v_ch->>'stance', 'confidence', v_ch->>'confidence',
          'reasoning', v_ch->>'reasoning', 'blocking', v_rule.blocking);

        insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent,
                                  stage, decision, reason, violated_rule, confidence)
        values ('org_task', p_task_id::text, t.dept_key, v_author, v_dept, 'challenge',
                case when v_rule.blocking and (v_ch->>'stance') = 'recommend_against'
                     then 'reject' else 'dissent' end,
                upper(v_ch->>'stance') || ' from ' || v_dept || ': ' || coalesce(v_ch->>'reasoning','')
                  || case when v_ch->'alternatives' <> '[]'::jsonb
                          then ' Alternative offered: ' || (v_ch->'alternatives'->>0) else '' end,
                v_ch->>'conflicts_with', (v_ch->>'confidence')::numeric);

        -- THE FOUNDER'S RULE, 6 Aug 2026: the blocking flag decides whether a rejection stops the
        -- work or is recorded against it. The reason is written either way.
        if v_rule.blocking and (v_ch->>'stance') = 'recommend_against' then
          v_blocked := true;
          v_blocker := v_dept || ' — ' || left(coalesce(v_ch->>'reasoning',''), 200);
        end if;
      end if;
    end loop;
  end loop;

  if v_blocked and v_outcome in ('published', 'approve') then
    v_outcome := 'request_revision';
    insert into review_chain (subject_type, subject_id, dept_key, author_agent, reviewer_agent,
                              stage, decision, reason, confidence)
    values ('org_task', p_task_id::text, t.dept_key, v_author, 'brief', 'cos_review',
            'request_revision',
            'Returned for revision by the Chief of Staff: a BLOCKING collaboration rule was '
            || 'challenged and the challenge recommended against it. ' || v_blocker, 1.0);
  end if;

  -- "Every completed task should generate learning." Written here, by the reviewer, at the moment
  -- the verdict is known — the review already establishes what was wrong, so the lesson costs
  -- nothing. Never let recording the lesson fail the review itself.
  begin
    perform fn_task_lesson(p_task_id, v_outcome,
      jsonb_build_object('violations', coalesce(v_chain->'violations','[]'::jsonb),
                         'dissents',   v_dissents,
                         'reviewer',   v_chain->>'reviewer'));
  exception when others then null;
  end;

  return jsonb_build_object(
    'task_id',        p_task_id,
    'outcome',        v_outcome,
    'stopped_at',     v_chain->>'stopped_at',
    'author',         v_author,
    'reviewer',       v_chain->>'reviewer',
    'delegated_from', v_chain->>'delegated_from',
    'violations',     coalesce(v_chain->'violations', '[]'::jsonb),
    'unenforceable',  coalesce(v_chain->'unenforceable', '[]'::jsonb),
    'rules_applied',  v_rules_hit,
    'collaboration',  v_involved,
    'dissents',       v_dissents,
    'owned_by_os',    v_own_os,
    'owner_agent',    v_own_agent,
    'owns_responsibility', v_own_resp,
    'blocked',        v_blocked);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_taxonomy_trades_for(p_slugs text[])
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- Each name resolves to itself (normalised) and to the taxonomy code(s) of the same trade. Never to a
  -- neighbour. A retired taxonomy code is dropped, so it never gates a match.
  select coalesce(array_agg(distinct x.code order by x.code), '{}'::text[])
    from (
      select public.fn_trade_code(s) as code
        from unnest(coalesce(p_slugs, '{}'::text[])) s
      union
      select unnest(m.trade_codes)
        from unnest(coalesce(p_slugs, '{}'::text[])) s
        join public.intake_trade_taxonomy m on public.fn_trade_code(m.intake_slug) = public.fn_trade_code(s)
    ) x
   where x.code is not null
     and not exists (select 1 from public.taxonomy_trade t where t.code = x.code and not t.active);
$function$


CREATE OR REPLACE FUNCTION public.fn_text_did_not_survive_reply(p_lang text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case when lower(coalesce(p_lang, 'en')) = 'ar' then
      'وصلتني رسالتكم وقد تحوّلت حروفها إلى علامات استفهام، فتعذّرت عليّ قراءة سؤالكم. '
      || 'لا خطأ في سؤالكم، وإنما لم يصل النص سليمًا عبر الاتصال. يُرجى إعادة إرسال الرسالة. '
      || 'وإن تكرر ذلك، يمكنكم الاتصال أو المراسلة عبر واتساب:' || E'\n'
      || E'‎' || '+971 50 931 9355' || E'\n'
      || '(من الاثنين إلى الجمعة، من 9 صباحًا حتى 6 مساءً بتوقيت الإمارات)' || E'\n'
      || 'أو البريد الإلكتروني:' || E'\n' || 'management@quotesdone.com'
    else
      'Your message reached me with its characters replaced by question marks, so I cannot read '
      || 'what you asked. Nothing is wrong with your question — it did not survive the connection. '
      || 'Please send it again. If it keeps happening, call or WhatsApp +971 50 931 9355 '
      || '(Mon-Fri, 9am-6pm GST) or email management@quotesdone.com.'
  end;
$function$


CREATE OR REPLACE FUNCTION public.fn_text_lost_its_script(p_text text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce(
       p_text !~ '[^\x00-\x7F]'
   and (
         (    (select count(*) from regexp_matches(p_text, '[?][?]+', 'g')) >= 2
          and length(regexp_replace(p_text, '[^?]', '', 'g'))::numeric
                >= 0.30 * greatest(length(regexp_replace(p_text, '\s', '', 'g')), 1))
      or (select count(*) from regexp_matches(p_text, '[?]{4,}', 'g')) >= 3
      or p_text ~ '[?]{8,}'
       ),
  false);
$function$


CREATE OR REPLACE FUNCTION public.fn_trade_code(p_name text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select nullif(btrim(regexp_replace(lower(btrim(coalesce(p_name, ''))), '[^[:alnum:]]+', '_', 'g'), '_'), '');
$function$


CREATE OR REPLACE FUNCTION public.fn_trade_proposal_decide(p_id bigint, p_decision text, p_code text DEFAULT NULL::text, p_label_en text DEFAULT NULL::text, p_label_ar text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.taxonomy_trade_proposal; v_label text;
begin
  select * into r from public.taxonomy_trade_proposal where id = p_id for update;
  if r.id is null then raise exception 'fn_trade_proposal_decide: no proposal %', p_id; end if;
  if r.status not in ('pending', 'map_offered') then
    raise exception 'fn_trade_proposal_decide: proposal % is already %', p_id, r.status;
  end if;

  if p_decision = 'add' then
    -- Under the SUPPLIER'S code, never another: suppliers who confirmed this trade already hold it
    -- in supplier_capabilities.trades, and a different code would silently unmatch them.
    -- Siblings (other suppliers' PENDING proposals of the same code) are locked in id order first, so
    -- two concurrent 'add' decisions on one code queue instead of deadlocking.
    perform 1 from public.taxonomy_trade_proposal where code = r.code and status = 'pending' order by id for update;
    v_label := coalesce(nullif(btrim(p_label_en), ''), nullif(r.label_en, ''), r.label_ar);
    insert into public.taxonomy_trade (code, label, label_ar, aliases, sort, active)
    values (r.code, v_label, coalesce(nullif(btrim(p_label_ar), ''), r.label_ar),
            array_remove(array[lower(nullif(btrim(coalesce(p_label_en, r.label_en)), ''))], null), 900, true)
    on conflict (code) do nothing;
    update public.taxonomy_trade_proposal
       set status = 'added', mapped_to = null, decided_at = now(), decided_by = 'sales_engineer', note = coalesce(p_note, note)
     where id = r.id;
    -- Other suppliers' PENDING rows of the same code are now in the list too; they are marked as a
    -- consequence, with a system note naming the decision, never with this decision's note. A
    -- map_offered row is a separate decision for that supplier and is left alone.
    update public.taxonomy_trade_proposal
       set status = 'added', decided_at = now(), decided_by = 'sales_engineer',
           note = 'auto: code added to taxonomy_trade by proposal #' || r.id
     where code = r.code and status = 'pending' and id <> r.id;
  elsif p_decision = 'offer_map' then
    if not exists (select 1 from public.taxonomy_trade where code = p_code and active) then
      raise exception 'fn_trade_proposal_decide: % is not an active trade', p_code;
    end if;
    update public.taxonomy_trade_proposal
       set status = 'map_offered', mapped_to = p_code, decided_at = now(), decided_by = 'sales_engineer', note = coalesce(p_note, note)
     where id = r.id;
  elsif p_decision = 'reject' then
    update public.taxonomy_trade_proposal
       set status = 'rejected', mapped_to = null, decided_at = now(), decided_by = 'sales_engineer', note = coalesce(p_note, note)
     where id = r.id;
  else
    raise exception 'fn_trade_proposal_decide: decision must be add, offer_map or reject, not %', p_decision;
  end if;
  return (select to_jsonb(x) from public.taxonomy_trade_proposal x where x.id = r.id);
end $function$


CREATE OR REPLACE FUNCTION public.fn_transaction_attach_invoice(p_transaction_id uuid, p_invoice jsonb, p_doc_path text DEFAULT NULL::text, p_doc_name text DEFAULT NULL::text, p_doc_content_type text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_inv_id   text := nullif(btrim(coalesce(p_invoice->>'id','')), '');
  v_pdf      text := nullif(btrim(coalesce(p_invoice->>'invoice_pdf','')), '');
  v_hosted   text := nullif(btrim(coalesce(p_invoice->>'hosted_invoice_url','')), '');
  v_path     text := nullif(btrim(coalesce(p_doc_path,'')), '');
  v_existing public.transactions%rowtype;
  v_rows     integer;
begin
  if p_transaction_id is null then
    return jsonb_build_object('ok', false, 'reason', 'no transaction id');
  end if;
  if v_inv_id is null then
    return jsonb_build_object('ok', false, 'reason', 'the invoice object carries no id');
  end if;
  -- A Stripe Invoice id is in_...; anything else is not the object this column names, and a column
  -- the accountant reconciles against Stripe must not hold something Stripe cannot resolve.
  if v_inv_id !~ '^in_[A-Za-z0-9_]+$' then
    return jsonb_build_object('ok', false, 'reason', 'not a stripe invoice id',
                              'given', left(v_inv_id, 60));
  end if;

  -- Both links are opened as evidence by the founder and the CEO. A spoofed payload may not aim
  -- them anywhere but Stripe. Same pattern fn_refund_attach_receipt uses, and it refuses lookalikes
  -- such as stripe.com.evil.example because the host must END at stripe.com before the first slash.
  if v_pdf is not null and v_pdf !~ '^https://[a-z0-9.-]*\.?stripe\.com/' then
    return jsonb_build_object('ok', false, 'reason', 'invoice_pdf is not a stripe.com url',
                              'given', left(v_pdf, 120));
  end if;
  if v_hosted is not null and v_hosted !~ '^https://[a-z0-9.-]*\.?stripe\.com/' then
    return jsonb_build_object('ok', false, 'reason', 'hosted_invoice_url is not a stripe.com url',
                              'given', left(v_hosted, 120));
  end if;

  -- The stored object is named by its PREFIX, not by a free path. A caller that could name any path
  -- in finance-docs could make this row point at another record's document.
  if v_path is not null and v_path !~ '^invoices/' then
    return jsonb_build_object('ok', false, 'reason', 'a stored invoice must live under invoices/ in finance-docs',
                              'given', left(v_path, 120));
  end if;

  select * into v_existing from public.transactions where id = p_transaction_id;
  if not found then
    return jsonb_build_object('ok', false,
             'reason', format('no transaction %s', p_transaction_id));
  end if;

  -- WRITE-ONCE ON IDENTITY. The first invoice a sale was billed under is the one it stays billed
  -- under; a second, different invoice id is a fact about a different sale and is refused rather
  -- than allowed to overwrite the reference the books were reconciled against.
  if coalesce(v_existing.stripe_invoice_id, '') <> '' and v_existing.stripe_invoice_id <> v_inv_id then
    return jsonb_build_object('ok', false, 'reason', 'this transaction is already billed under another invoice',
                              'existing', v_existing.stripe_invoice_id, 'given', v_inv_id);
  end if;

  -- The FILE may arrive after the REFERENCE -- Stripe finalises the PDF moments after the session
  -- completes -- so the document columns fill in on a later call without disturbing what is set.
  update public.transactions t set
    stripe_invoice_id         = v_inv_id,
    stripe_invoice_number     = coalesce(nullif(btrim(coalesce(p_invoice->>'number','')),''), t.stripe_invoice_number),
    stripe_invoice_status     = coalesce(nullif(btrim(coalesce(p_invoice->>'status','')),''), t.stripe_invoice_status),
    stripe_invoice_total_fils = coalesce((p_invoice->>'total')::bigint, t.stripe_invoice_total_fils),
    stripe_invoice_currency   = coalesce(upper(nullif(btrim(coalesce(p_invoice->>'currency','')),'')), t.stripe_invoice_currency),
    stripe_invoice_pdf_url    = coalesce(v_pdf, t.stripe_invoice_pdf_url),
    stripe_invoice_hosted_url = coalesce(v_hosted, t.stripe_invoice_hosted_url),
    doc_path                  = coalesce(t.doc_path, v_path),
    doc_name                  = coalesce(t.doc_name, nullif(btrim(coalesce(p_doc_name,'')),'')),
    doc_content_type          = coalesce(t.doc_content_type, nullif(btrim(coalesce(p_doc_content_type,'')),'')),
    doc_kind                  = case when t.doc_path is null and v_path is not null then 'stripe_invoice'
                                     else t.doc_kind end
  where t.id = p_transaction_id;
  get diagnostics v_rows = row_count;

  return jsonb_build_object(
    'ok', v_rows > 0,
    'transaction_id', p_transaction_id,
    'invoice_id', v_inv_id,
    'stored', v_path is not null or coalesce(v_existing.doc_path,'') <> '',
    'state', (select document_state from public.v_revenue_documents where id = p_transaction_id));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_transaction_refund_outcome_follows_through()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if NEW.refund_status in ('succeeded', 'refunded') and NEW.refund_amount_aed is not null
     and (OLD.refund_status is distinct from NEW.refund_status or OLD.refund_amount_aed is distinct from NEW.refund_amount_aed) then
    begin
      perform public.fn_accountant_refund_settled(NEW.id);
    exception when others then
      insert into public.ceo_task (title, detail)
      values (left('Refund on reveal ' || left(NEW.id::text, 8) || ' settled but its follow-through failed', 200),
              'fn_accountant_refund_settled raised: ' || sqlerrm || '. The refund itself is recorded; the supplier charge, the customer''s message or the re-verification did not complete.');
    end;
  elsif NEW.refund_status = 'failed' and OLD.refund_status is distinct from 'failed' then
    perform public.fn_ceo_refund_verify(NEW.id);
  elsif NEW.refund_status = 'rejected' and OLD.refund_status is distinct from 'rejected' then
    perform public.fn_seat_handoff('accountant', 'sales_engineer', 'refund.declined', 'transactions', NEW.id::text,
      jsonb_build_object('transaction_id', NEW.id, 'customer_id', NEW.customer_id, 'inquiry_id', NEW.inquiry_id,
                         'quote_id', NEW.quote_id, 'note', NEW.refund_note));
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.fn_twilio_error_in_plain_words(p_code text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case nullif(btrim(coalesce(p_code, '')), '')
    when '63016' then 'outside the 24-hour window: the recipient has not messaged us in the last 24 hours, so WhatsApp accepts only an approved template, not free text'
    when '63024' then 'not a usable WhatsApp account: the number is not on WhatsApp, has not accepted WhatsApp''s terms, or runs an outdated app'
    when '63003' then 'the number could not be found on WhatsApp: wrong, inactive or not registered'
    when '63032' then 'WhatsApp will not deliver to this user because of a WhatsApp restriction on the recipient'
    when '63033' then 'the recipient has opted out of receiving these messages'
    when '63049' then 'Meta chose not to deliver it (its per-user limit on marketing messages)'
    when '63050' then 'the recipient has opted out of marketing messages on WhatsApp'
    when '63013' then 'WhatsApp refused it as a policy violation'
    when '63018' then 'our WhatsApp sender hit its rate limit, so the message was not delivered'
    when '63027' then 'the template does not exist at Meta in this language'
    when '63028' then 'the template was sent with the wrong number of variables'
    when '63040' then 'Meta rejected the template'
    when '63041' then 'Meta paused the template (low quality)'
    when '63042' then 'Meta disabled the template'
    when '63051' then 'Meta has locked our WhatsApp sender or account'
    when '63112' then 'Meta has disabled the WhatsApp Business Account behind our sender'
    when '30003' then 'the phone is unreachable (switched off or out of coverage)'
    when '30005' then 'the number does not exist or is not assigned to anyone'
    when '30006' then 'the number is a landline or cannot receive SMS'
    when '30007' then 'the carrier filtered it as unwanted'
    when '30008' then 'the carrier reported an unknown delivery error'
    else case when p_code is null or btrim(p_code) = '' then null
              else 'Twilio error ' || btrim(p_code) || ' (twilio.com/docs/api/errors/' || btrim(p_code) || ')' end
  end
$function$


CREATE OR REPLACE FUNCTION public.fn_twilio_status_arrived(p_sid text, p_status text, p_error_code text DEFAULT NULL::text, p_source text DEFAULT 'callback'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  n public.notifications; v_status text := lower(btrim(coalesce(p_status, ''))); v_code text := nullif(btrim(coalesce(p_error_code, '')), '');
  v_final_fail boolean;
begin
  if coalesce(btrim(p_sid), '') = '' then return jsonb_build_object('matched', false, 'applied', false, 'reason', 'no MessageSid'); end if;
  if public.fn_twilio_status_rank(v_status) = 0 then
    return jsonb_build_object('matched', null, 'applied', false, 'reason', 'not a status this estate records: ' || left(v_status, 40));
  end if;
  select * into n from public.notifications
   where provider_message_id = btrim(p_sid) and channel in ('whatsapp', 'sms')
   order by id limit 1 for update;
  if n.id is null then return jsonb_build_object('matched', false, 'applied', false); end if;
  if public.fn_twilio_status_rank(v_status) <= public.fn_twilio_status_rank(n.provider_status) then
    return jsonb_build_object('matched', true, 'applied', false, 'notification_id', n.id, 'kept', n.provider_status, 'ignored', v_status);
  end if;
  v_final_fail := v_status in ('failed', 'undelivered');
  update public.notifications
     set provider_status = v_status, provider_status_at = now(),
         provider_error_code = coalesce(v_code, provider_error_code),
         status = case when v_final_fail and status = 'sent' then 'failed' else status end,
         last_error = case when v_final_fail
                           then left('Twilio reported ' || v_status || coalesce(' (error ' || v_code || ')', '') || ': '
                                     || coalesce(public.fn_twilio_error_in_plain_words(v_code), 'no error code was given'), 500)
                           else last_error end
   where id = n.id;
  return jsonb_build_object('matched', true, 'applied', true, 'notification_id', n.id, 'from', n.provider_status, 'to', v_status,
                            'failed', v_final_fail, 'error_code', v_code, 'source', left(coalesce(p_source, ''), 20));
end $function$


CREATE OR REPLACE FUNCTION public.fn_twilio_status_poll_claim(p_limit integer DEFAULT 20)
 RETURNS TABLE(notification_id bigint, sid text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  return query
  update public.notifications u set provider_status_checked_at = now()
   where u.id in (select c.id from public.notifications c
                   where c.channel in ('whatsapp', 'sms') and coalesce(btrim(c.provider_message_id), '') <> ''
                     and c.sent_at < now() - interval '30 minutes'
                     and public.fn_twilio_status_rank(c.provider_status) < 4
                     and coalesce(c.provider_status, '') <> 'unreadable'
                     and (c.provider_status_checked_at is null or c.provider_status_checked_at < now() - interval '30 minutes')
                   order by coalesce(c.provider_status_checked_at, c.sent_at)
                   limit least(greatest(coalesce(p_limit, 20), 1), 50)
                   for update skip locked)
  returning u.id, u.provider_message_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_twilio_status_poll_failed(p_notification_id bigint, p_http integer DEFAULT NULL::integer, p_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  c_give_up constant int := 5;   -- 5 x 30 minutes: 2.5 hours of trying before we stop asking.
  n public.notifications; v_fails int; v_gave_up boolean;
begin
  select * into n from public.notifications where id = p_notification_id for update;
  if n.id is null then return jsonb_build_object('matched', false); end if;
  if public.fn_twilio_status_rank(n.provider_status) >= 4 then
    return jsonb_build_object('matched', true, 'applied', false, 'reason', 'already final: ' || n.provider_status);
  end if;
  v_fails := coalesce(n.provider_poll_failures, 0) + 1;
  v_gave_up := v_fails >= c_give_up;
  update public.notifications
     set provider_poll_failures = v_fails,
         provider_status = case when v_gave_up then 'unreadable' else provider_status end,
         provider_status_at = case when v_gave_up then now() else provider_status_at end,
         provider_error_code = coalesce(nullif(btrim(coalesce(p_code, '')), ''), provider_error_code),
         last_error = left('Twilio could not be read for this message: '
                           || coalesce('HTTP ' || p_http::text, 'no HTTP response')
                           || coalesce(', Twilio code ' || nullif(btrim(coalesce(p_code, '')), ''), '')
                           || ' (attempt ' || v_fails || ' of ' || c_give_up || ')'
                           || case when v_gave_up then ' — given up: the delivery of this message is unknown.' else '' end, 500)
   where id = n.id;
  return jsonb_build_object('matched', true, 'applied', true, 'failures', v_fails, 'gave_up', v_gave_up,
                            'give_up_after', c_give_up, 'http', p_http, 'code', nullif(btrim(coalesce(p_code, '')), ''));
end $function$


CREATE OR REPLACE FUNCTION public.fn_twilio_status_rank(p_status text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case lower(coalesce(p_status, ''))
    when 'accepted' then 1 when 'scheduled' then 1 when 'queued' then 1
    when 'sending' then 2 when 'sent' then 3
    when 'delivered' then 4 when 'undelivered' then 4 when 'failed' then 4
    when 'read' then 5 else 0 end
$function$


CREATE OR REPLACE FUNCTION public.fn_twin(p_kind text, p_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare res jsonb;
begin
  if p_kind='customer' then
    select jsonb_build_object('kind','customer','id',c.id,'name',c.full_name,'email',c.email,
      'industry',c.industry,
      'rfqs',(select count(*) from inquiries where customer_id=c.id),
      'deals',(select count(*) from transactions where customer_id=c.id),
      'spend_aed',(select coalesce(sum(reveal_fee),0) from transactions where customer_id=c.id and coalesce(fee_status,'')='paid'),
      'categories',(select coalesce(jsonb_agg(distinct category),'[]') from inquiries where customer_id=c.id),
      -- BUYING PATTERNS (§2) — categories ORDERED BY how often the customer actually buys them,
      -- with the count beside each. `categories` above is a set and a set is not a pattern.
      'preferred_categories',(select coalesce(jsonb_agg(jsonb_build_object('category',k.category,'rfqs',k.n) order by k.n desc),'[]')
         from (select category, count(*) n from inquiries where customer_id=c.id and category is not null
               group by category order by count(*) desc limit 8) k),
      'projects_active',(select count(*) from projects
         where customer_id=c.id and coalesce(status,'') not in ('closed','cancelled','completed','done')),
      'projects_total',(select count(*) from projects where customer_id=c.id),
      -- PREFERRED SUPPLIERS (§2) — the suppliers this customer has actually paid to reveal. A
      -- preference the customer demonstrated, not one they were asked to declare.
      'preferred_suppliers',(select count(distinct supplier_id) from transactions
         where customer_id=c.id and coalesce(fee_status,'')='paid' and supplier_id is not null),
      -- (No approval_chain key since 14 Sep 2026: the Approvals tab and the organisation/policy
      -- tables it read were removed — a company buys exactly like an individual. See
      -- a_company_buys_like_an_individual_so_the_approval_chain_is_dropped.sql.)
      'last_active',(select max(created_at) from inquiries where customer_id=c.id),
      -- AI UNDERSTANDING (§2) — the share of eight profile facts held, and ONLY once the customer
      -- has raised a request. Before that there is no buying behaviour to understand, and a tally of
      -- sign-up fields is not understanding (see the header of this file).
      'understanding_pct',(case when exists (select 1 from inquiries where customer_id=c.id) then
         (select round(100.0 * (
             (c.full_name is not null and c.full_name <> '')::int
           + (c.phone is not null and c.phone <> '')::int
           + coalesce(c.email_verified,false)::int
           + (c.tos_accepted_at is not null)::int
           + (c.locale is not null)::int
           + (c.industry is not null and c.industry <> '')::int
           + 1
           + (exists (select 1 from customer_preference cp where cp.customer_id=c.id))::int
         ) / 8.0)) end),
      'banned',c.banned) into res from customers c where c.id::text=p_id;

  elsif p_kind='rfq' then
    select jsonb_build_object('kind','rfq','id',i.id,'category',i.category,'emirate',i.emirate,'status',i.status,
      'completeness',i.completeness,'ready',i.rfq_ready,'budget',i.budget,
      'quotes',(select count(*) from quotes where inquiry_id=i.id),
      'avg_quote_quality',(select round(avg(nullif(quality->>'score','')::numeric),1) from quotes where inquiry_id=i.id),
      'matched_suppliers',(select count(*) from inquiry_matches where inquiry_id=i.id),
      'created',i.created_at,'completed',i.completed_at,'outcome',i.outcome) into res from inquiries i where i.id::text=p_id;

  elsif p_kind='category' then
    res := jsonb_build_object('kind','category','category',p_id,
      'demand_rfqs',(select count(*) from inquiries where category=p_id),
      'approved_suppliers',(select count(*) from leads where coalesce(approval_status,'')='approved' and (lower(coalesce(categories,''))||' '||lower(coalesce(sub_type,'')) like '%'||lower(p_id)||'%')),
      'supplier_pool_total',(select count(*) from leads where lower(coalesce(categories,''))||' '||lower(coalesce(sub_type,'')) like '%'||lower(p_id)||'%'),
      'avg_quote_quality',(select round(avg(nullif(q.quality->>'score','')::numeric),1) from quotes q join inquiries i on i.id=q.inquiry_id where i.category=p_id),
      'agent',public.fn_resolve_cat_agent(p_id));

  elsif p_kind='company' then
    res := jsonb_build_object('kind','company','name','QuotesDone',
      'health',public.fn_health_index(),
      'suppliers_total',(select count(*) from leads),'suppliers_approved',(select count(*) from leads where coalesce(approval_status,'')='approved'),
      'customers',(select count(*) from customers),'rfqs',(select count(*) from inquiries),'quotes',(select count(*) from quotes),
      'revenue_paid_aed',(select coalesce(sum(reveal_fee),0) from transactions where coalesce(fee_status,'')='paid'),
      'eval',public.fn_eval_snapshot(30));
  else
    res := jsonb_build_object('error','kind must be customer|rfq|category|company');
  end if;
  return coalesce(res, jsonb_build_object('error','not found','kind',p_kind,'id',p_id));
end $function$


CREATE OR REPLACE FUNCTION public.fn_ui_label(p_domain text, p_key text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select coalesce(
           (select l.label from public.ui_label l
             where l.domain = p_domain and l.key = p_key),
           -- No row: humanise rather than blank. 'supplier_risk_complaints' -> 'Supplier Risk
           -- Complaints'. Worse than a written label, better than showing the founder a key, and
           -- v_ui_label_missing reports that it happened.
           nullif(initcap(replace(coalesce(p_key, ''), '_', ' ')), ''),
           'Unlabelled');
$function$


CREATE OR REPLACE FUNCTION public.fn_usd_to_aed()
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
AS $function$ select 3.672450::numeric $function$


CREATE OR REPLACE FUNCTION public.fn_vat_threshold_fraction_reached(p_turnover_aed numeric)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select max(e::numeric)
    from public.decision_policy d, jsonb_array_elements_text(d.value) e
   where d.key = 'vat_threshold_report_fractions'
     and coalesce(p_turnover_aed, 0) >= e::numeric * (select num_value from public.gl_settings where key = 'vat_registration_threshold_aed');
$function$


CREATE OR REPLACE FUNCTION public.fn_vat_threshold_position(p_turnover_aed numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_thr numeric; v_frac numeric; v_band text;
begin
  select num_value into v_thr  from public.gl_settings where key = 'vat_registration_threshold_aed';
  select num_value into v_frac from public.gl_settings where key = 'vat_threshold_warn_fraction';
  if v_thr is null then
    raise exception 'gl_settings.vat_registration_threshold_aed is missing; refusing to decide a tax obligation against a threshold nobody set';
  end if;

  v_band := case
    when p_turnover_aed >= v_thr                       then 'crossed'
    when p_turnover_aed >= v_thr * coalesce(v_frac,0.8) then 'approaching'
    else 'below' end;

  return jsonb_build_object(
    'band', v_band,
    'turnover_aed', round(coalesce(p_turnover_aed,0), 2),
    'threshold_aed', v_thr,
    'headroom_aed', round(v_thr - coalesce(p_turnover_aed,0), 2),
    'pct_of_threshold', round(coalesce(p_turnover_aed,0) / v_thr * 100, 1),
    'obligation', case v_band
      when 'crossed'     then 'Taxable supplies in the preceding 12 months have passed the mandatory registration threshold. Registration is required.'
      when 'approaching' then 'Not yet required. Close enough that registration should be prepared rather than discovered.'
      else 'No registration obligation on the preceding-12-months test.' end);
end $function$


CREATE OR REPLACE FUNCTION public.fn_verified_mobile(p_role text, p_customer uuid DEFAULT NULL::uuid, p_lead bigint DEFAULT NULL::bigint, p_email text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
    when p_role = 'customer' then (select c.phone from public.customers c
                                    where coalesce(c.phone_verified, false) and nullif(btrim(c.phone), '') is not null
                                      and (c.id = p_customer or (p_customer is null and p_email is not null and lower(c.email) = lower(btrim(p_email))))
                                    limit 1)
    when p_role = 'supplier' then (select l.phone from public.leads l
                                    where coalesce(l.owner_phone_verified, false) and nullif(btrim(l.phone), '') is not null
                                      and (l.id = p_lead or (p_lead is null and p_email is not null and (lower(l.claimed_by) = lower(btrim(p_email)))))
                                    order by l.id limit 1)
  end
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_answer(p_from text, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_body     text := lower(btrim(coalesce(p_body, '')));
  i          record;
  v_intent   record := null;
  v_pat      text;
  v_reply    text;
  v_lead     record;
  v_lead_id  bigint;
  v_ident_k  text := 'unknown';
  v_ident_id text := null;
  v_id       bigint;
  v_missing  text;
  v_cfg      record;
  v_log      bigint;
begin
  if v_body = '' then
    return jsonb_build_object('ok', false, 'reason', 'Empty message.');
  end if;

  select standard_reveal_rate, supplier_free_count, supplier_reg_fee into v_cfg
    from public.pricing_config order by id limit 1;

  -- WHO IS ASKING. Identity gates every 'own_records' answer, so one supplier can never be told
  -- another supplier's business by sending a lucky message.
  v_lead_id := public.fn_wa_lead_id(p_from);
  if v_lead_id is not null then
    select * into v_lead from public.leads where id = v_lead_id;
    v_ident_k := 'lead'; v_ident_id := v_lead_id::text;
  end if;

  -- MATCH. First intent whose pattern appears in the body wins, in sort order, so a specific
  -- intent can be placed ahead of a general one.
  for i in select * from public.wa_reply_intent where active order by sort, intent_key loop
    foreach v_pat in array i.match_patterns loop
      -- WORD BOUNDARIES, NOT SUBSTRINGS. A plain substring test matched the greeting pattern 'hi'
      -- inside the word 'something', so 'i want to buy something' was answered with hello. Patterns that
      -- begin and end on a word character are matched on word boundaries; punctuation patterns such as
      -- '#' keep the substring test, because a boundary around a symbol never matches.
      -- Whole-token matching WITHOUT regex escapes. The transport between this file and the database
      -- strips backslashes, so a regex word boundary arrives as a literal letter and the statement
      -- will not even parse. Padding both sides with spaces and normalising punctuation to spaces
      -- gives the same result with no escape to lose.
      if (case
            when v_pat ~ '[a-z0-9]'
              then position(' ' || v_pat || ' '
                            in ' ' || regexp_replace(v_body, '[^a-z0-9 ]', ' ', 'g') || ' ') > 0
            else position(v_pat in v_body) > 0
          end)
         and (not i.requires_number or v_body ~ '[0-9]{2,}') then
        v_intent := i;
        exit;
      end if;
    end loop;
    exit when v_intent is not null;
  end loop;

  -- NO MATCH. An honest refusal that names what it would need. Never a guess, and never a claim
  -- that some service is unavailable.
  if v_intent is null then
    v_reply := public.fn_wa_unmatched_reply();
    insert into public.wa_answer_log (from_phone, body, identity_kind, identity_id, matched, reply, refusal_reason)
    values (p_from, p_body, v_ident_k, v_ident_id, false, v_reply,
            'No enumerated intent matched. This row is the backlog: a real question with no resolver.')
    returning id into v_log;
    return jsonb_build_object('ok', true, 'matched', false, 'reply', v_reply, 'log_id', v_log);
  end if;

  -- IDENTITY REQUIRED BUT UNKNOWN.
  if v_intent.requires_identity and v_lead_id is null then
    v_reply := 'I do not recognise this number yet, so I cannot look up your records. Reply with the '
            || 'email address you registered with, or REGISTER to start a new registration.';
    insert into public.wa_answer_log (from_phone, body, identity_kind, identity_id, intent_key, matched, reply, refusal_reason)
    values (p_from, p_body, v_ident_k, v_ident_id, v_intent.intent_key, true, v_reply,
            'Intent matched but the sender is not a known party.')
    returning id into v_log;
    return jsonb_build_object('ok', true, 'matched', true, 'intent', v_intent.intent_key, 'reply', v_reply, 'log_id', v_log);
  end if;

  v_reply := v_intent.answer_template;

  -- COMPANY SLOTS, the same for everyone.
  v_reply := replace(v_reply, '{{reveal_rate}}', coalesce(round(v_cfg.standard_reveal_rate * 100, 1)::text || '%', '3%'));
  v_reply := replace(v_reply, '{{free_count}}',  coalesce(v_cfg.supplier_free_count::text, '1000'));
  v_reply := replace(v_reply, '{{reg_fee}}',     coalesce(round(v_cfg.supplier_reg_fee)::text, '1000'));

  -- THE APPROVED PUBLIC CONTACT, filled the same way. It is read from the settings that say
  -- publication in their names -- never from founder_mobile, which is a private contact record that
  -- happens to hold the same digits. Two values matching is not permission to publish either.
  --
  -- When the setting is absent the slot renders a sentence that ADMITS it rather than an empty
  -- string. "You can contact  on  " is worse than saying the contact is not configured, and the
  -- build spec asks for a blocker reported to the CEO rather than a placeholder shown to a customer.
  v_reply := replace(v_reply, '{{founder_public_phone}}',
    coalesce((select value from public.app_secrets where key = 'founder_public_phone'),
             '(no approved public contact is configured yet)'));
  v_reply := replace(v_reply, '{{founder_public_name}}',
    coalesce((select value from public.app_secrets where key = 'founder_public_name'),
             'the owner'));

  -- OWN-RECORD SLOTS, read from this sender's row only.
  if v_lead_id is not null then
    v_reply := replace(v_reply, '{{company_name}}', coalesce(v_lead.company_name, 'your company'));
    v_reply := replace(v_reply, '{{reg_status}}',   coalesce(v_lead.registration_status, 'not started'));
    v_reply := replace(v_reply, '{{approval_status}}', coalesce(v_lead.approval_status, 'not yet reviewed'));

    -- The founder's mandatory six, not the ten the scoring view happens to list.
    select string_agg(m, ', ') into v_missing from (
      select 'a UAE mobile number' as m where coalesce(btrim(v_lead.phone_e164), '') = ''
      union all select 'an email address' where coalesce(btrim(v_lead.email), '') = ''
      union all select 'your trade licence' where coalesce(btrim(v_lead.license_doc_path), '') = ''
      union all select 'your company profile' where coalesce(btrim(v_lead.company_profile_doc_path), '') = ''
      union all select 'a signed copy of our terms' where coalesce(btrim(v_lead.signed_terms_path), '') = ''
    ) x;
    v_reply := replace(v_reply, '{{missing_list}}', coalesce(v_missing, 'nothing, your file is complete'));
    v_reply := replace(v_reply, '{{missing_line}}',
      case when v_missing is null then 'Your file is complete.'
           else 'We still need: ' || v_missing || '.' end);

    v_reply := replace(v_reply, '{{quote_count}}', '0');
    v_reply := replace(v_reply, '{{quote_detail}}',
      'No quotes yet. Once a buyer posts a request in your category you will be invited to quote.');
    v_reply := replace(v_reply, '{{awarded_count}}', '0');
    v_reply := replace(v_reply, '{{awarded_detail}}',
      'No jobs awarded yet. You will get a message here the moment one is.');
  end if;

  -- BY-ID LOOKUP. A number in the body is resolved against the real records, and returned ONLY to a
  -- party who appears on that record. An id is not a password.
  if v_intent.scope = 'by_id' then
    -- The first run of two or more digits. Stripping every digit from the whole sentence turns
    -- 'i have 2 questions about job 55' into 255, which is a different job belonging to someone else.
    v_id := nullif((regexp_match(v_body, '([0-9]{2,})'))[1], '')::bigint;
    if v_id is null then
      v_reply := 'Send me the number and I will look it up. For example: quote 1234, or job 5678.';
    else
      v_reply := replace(v_reply, '{{id_answer}}',
        'I could not find a record numbered ' || v_id || ' that you are a party to. Check the number, '
        || 'or reply HUMAN and the team will look into it.');
    end if;
  end if;

  insert into public.wa_answer_log (from_phone, body, identity_kind, identity_id, intent_key, matched, reply)
  values (p_from, p_body, v_ident_k, v_ident_id, v_intent.intent_key, true, v_reply)
  returning id into v_log;

  return jsonb_build_object(
    'ok', true, 'matched', true, 'intent', v_intent.intent_key,
    'identity_kind', v_ident_k, 'identity_id', v_ident_id,
    'reply', v_reply, 'log_id', v_log, 'answered_by', 'deterministic'
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_attach_document(p_phone text, p_storage_path text, p_caption text DEFAULT NULL::text, p_media_kind text DEFAULT NULL::text, p_turn_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_lead   bigint;
  v_cap    text := lower(coalesce(p_caption, '') || ' ' || coalesce(p_storage_path, ''));
  v_kind   text := 'unknown';
  v_by     text := 'caption';
  v_conf   text := 'low';
  v_intake bigint;
  v_before jsonb;
  v_after  jsonb;
  v_reply  text;
begin
  v_lead := public.fn_wa_lead_id(p_phone);

  -- Classify from the caption and the filename. Deliberately conservative: an unrecognised document
  -- is recorded as unknown and waits, rather than being filed as a trade licence on a guess.
  if v_cap ~ '(trade|licence|license|رخصة|رخصه)' then
    v_kind := 'licence'; v_conf := 'high';
  elsif v_cap ~ '(profile|company profile|brochure|ملف|بروفايل)' then
    v_kind := 'profile'; v_conf := 'high';
  elsif v_cap ~ '(terms|t&c|agreement|signed|شروط|اتفاقية)' then
    v_kind := 'signed_terms'; v_conf := 'high';
  end if;

  if v_lead is not null then
    v_before := public.fn_supplier_mandatory_check(v_lead);
  end if;

  insert into public.wa_document_intake
    (phone_e164, lead_id, turn_id, storage_path, media_kind, caption,
     classified_as, classified_by, confidence, attached, attach_note)
  values (regexp_replace(coalesce(p_phone,''), '[^0-9]', '', 'g'), v_lead, p_turn_id,
          p_storage_path, p_media_kind, p_caption, v_kind, v_by, v_conf, false, null)
  returning id into v_intake;

  -- Attach ONLY when we know whose file it is and what it is. Anything else waits for a person.
  if v_lead is null then
    v_reply := 'Thank you. I could not match this number to a registered company yet, so I have kept '
            || 'your file and someone will match it to your account. If you reply with the email '
            || 'address you registered with, I can do it straight away.';
    update public.wa_document_intake set attach_note = 'No lead matches this number.' where id = v_intake;

  elsif v_kind = 'unknown' then
    v_reply := 'Thank you, I have saved that to your file. I could not tell which document it is, so '
            || 'to file it correctly please tell me: is it your trade licence, your company profile, '
            || 'or the signed terms?';
    update public.wa_document_intake set attach_note = 'Received but unclassified; asked the sender.' where id = v_intake;

  else
    if v_kind = 'licence' then
      update public.leads set license_doc_path = p_storage_path where id = v_lead;
    elsif v_kind = 'profile' then
      update public.leads set company_profile_doc_path = p_storage_path where id = v_lead;
    elsif v_kind = 'signed_terms' then
      update public.leads set signed_terms_path = p_storage_path where id = v_lead;
    end if;

    update public.wa_document_intake
       set attached = true,
           attach_note = format('Attached as %s to lead %s.', v_kind, v_lead)
     where id = v_intake;

    v_after := public.fn_supplier_mandatory_check(v_lead);

    -- Tell them what changed and what is left. This is the difference between a receipt and a service.
    if coalesce((v_after->>'complete')::boolean, false) then
      v_reply := 'Got it, that is your ' || replace(v_kind,'_',' ') || ' saved. Your file is now '
              || 'complete and it goes to our team for verification. I will message you here when it '
              || 'is approved.';
    else
      v_reply := 'Got it, that is your ' || replace(v_kind,'_',' ') || ' saved. Still needed: '
              || (select string_agg(value #>> '{}', ', ') from jsonb_array_elements(v_after->'missing'))
              || '. You can send them here the same way.';
    end if;
  end if;

  return jsonb_build_object(
    'ok', true,
    'intake_id', v_intake,
    'lead_id', v_lead,
    'classified_as', v_kind,
    'confidence', v_conf,
    'attached', (v_lead is not null and v_kind <> 'unknown'),
    'mandatory_before', v_before,
    'mandatory_after', v_after,
    'reply', v_reply
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_context(p_audience text, p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_e164 text; v_email text; v_lead record; v_cust record;
        v_dc uuid[]; v_dl bigint[]; v_di uuid[]; v_refunds jsonb;
begin
  -- ONE IDENTIFIER, TWO SHAPES. wa_from arrives as 'whatsapp:+9715...'; a browser session arrives
  -- as an email address. An '@' is the discriminator: nothing that is a phone number contains one,
  -- and an address stripped of non-digits is meaningless, which is how a mis-shaped identifier used
  -- to fall through to "known: false" instead of an answer.
  v_email := nullif(lower(btrim(coalesce(p_phone, ''))), '');
  if v_email is not null and position('@' in v_email) = 0 then v_email := null; end if;
  v_e164 := regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g');
  if v_e164 = '' and v_email is null then return jsonb_build_object('scope','none'); end if;

  -- ---------------------------------------------------------------- FOUNDER: the company itself
  if p_audience = 'founder' then
    -- DEMO: left out of every business figure below.
    select coalesce(array_agg(id), '{}') into v_dc from customers where is_demo;
    select coalesce(array_agg(id), '{}') into v_dl from leads where is_demo;
    select coalesce(array_agg(id), '{}') into v_di from inquiries where public.fn_inquiry_is_demo(id);

    -- REFUNDS ARE THE CEO'S, NOT HIS. The old decision-queue reader (dropped 9 Sep) listed refunds as
    -- waiting on him; since 14 Sep the CEO decides every refund and the founder only receives the CEO's summary
    -- when a review loop escalates. This is what the CEO holds, stated as information.
    with open_r as (
      select r.id, r.requested_at, r.amount_fils, r.reason_code, rv.cycle, rv.outcome
        from refunds r
        left join lateral (select x.cycle, x.outcome from refund_ceo_review x where x.refund_id = r.id order by x.cycle desc limit 1) rv on true
       where r.status = 'requested'
         and (r.customer_id = any (v_dc)) is not true and (r.supplier_lead_id = any (v_dl)) is not true and (r.inquiry_id = any (v_di)) is not true)
    select jsonb_build_object(
      'who_decides', 'ceo',
      'note', 'Every refund is decided by the CEO. You receive his short summary only when a review loop escalates (three cycles or a missed deadline). Nothing here waits on you.',
      'open', (select count(*) from open_r),
      'escalated', (select count(*) from open_r where outcome = 'escalated'),
      'items', coalesce((select jsonb_agg(jsonb_build_object('refund_id', z.id, 'requested_at', z.requested_at,
                          'amount_aed', round(z.amount_fils / 100.0, 2), 'reason', z.reason_code,
                          'review_cycle', z.cycle, 'review_outcome', z.outcome) order by z.requested_at)
                           from (select * from open_r order by requested_at limit 12) z), '[]'::jsonb))
      into v_refunds;

    return jsonb_build_object(
      'scope','company',
      'suppliers', jsonb_build_object(
        'leads_total',      (select count(*) from leads where (id = any (v_dl)) is not true),
        'claimed',          (select count(*) from leads where coalesce(claimed,false) and (id = any (v_dl)) is not true),
        'claimed_real',     (select count(*) from leads where coalesce(claimed,false) and (id = any (v_dl)) is not true
                              and not (coalesce(company_name,'') ilike 'ZZ DEMO%' or coalesce(email,'') ilike '%@example.invalid')),
        'approved',         (select count(*) from leads where approval_status = 'approved' and (id = any (v_dl)) is not true),
        'licence_verified', (select count(*) from leads where coalesce(verified,false) and (id = any (v_dl)) is not true),
        'with_email',       (select count(*) from leads where coalesce(btrim(email),'') <> '' and (id = any (v_dl)) is not true)),
      'invites', jsonb_build_object(
        'enabled',      (select value from app_secrets where key='invite_enabled'),
        'daily_cap',    (select value from app_secrets where key='invite_daily_cap'),
        'sent_today',   (select count(*) from leads where invited_at >= date_trunc('day', now() at time zone 'utc') and (id = any (v_dl)) is not true),
        'sent_7d',      (select count(*) from leads where invited_at > now() - interval '7 days' and (id = any (v_dl)) is not true),
        'bounced_7d',   (select count(*) from leads where invite_status='bounced' and invited_at > now() - interval '7 days' and (id = any (v_dl)) is not true),
        'uncontacted',  (select count(*) from leads where invited_at is null and coalesce(btrim(email),'') <> '' and (id = any (v_dl)) is not true)),
      'demand', jsonb_build_object(
        'customers',        (select count(*) from customers where (id = any (v_dc)) is not true),
        'inquiries_total',  (select count(*) from inquiries where (id = any (v_di)) is not true),
        'inquiries_7d',     (select count(*) from inquiries where created_at > now() - interval '7 days' and (id = any (v_di)) is not true),
        'quotes_total',     (select count(*) from quotes where (inquiry_id = any (v_di)) is not true and (supplier_id = any (v_dl)) is not true),
        'quotes_7d',        (select count(*) from quotes where created_at > now() - interval '7 days'
                               and (inquiry_id = any (v_di)) is not true and (supplier_id = any (v_dl)) is not true)),
      'money', jsonb_build_object(
        'transactions',      (select count(*) from transactions where (customer_id = any (v_dc)) is not true
                                and (supplier_id = any (v_dl)) is not true and (inquiry_id = any (v_di)) is not true),
        'revealed',          (select count(*) from transactions where revealed_at is not null and (customer_id = any (v_dc)) is not true
                                and (supplier_id = any (v_dl)) is not true and (inquiry_id = any (v_di)) is not true),
        'ai_spend_today_aed',(select round(coalesce(sum(cost_aed),0)::numeric,2) from ai_cost_log where occurred_at >= current_date),
        'ai_spend_month_aed',(select round(coalesce(sum(cost_aed),0)::numeric,2) from ai_cost_log where occurred_at >= date_trunc('month', now()))),
      'health', jsonb_build_object(
        'agent_runs_failed_24h', (select count(*) from agent_runs where status in ('error','failed') and started_at > now() - interval '24 hours'),
        'actions_pending',       (select count(*) from agent_actions where status in ('pending','needs_review')),
        'escalations_open',      (select count(*) from agent_actions where coalesce(escalated,false) and status in ('pending','needs_review'))),
      'refunds_with_the_ceo', v_refunds);
  end if;

  -- ---------------------------------------------------------------- SUPPLIER: only their own row
  if p_audience = 'supplier' then
    select * into v_lead from leads l
     where (v_e164 <> '' and l.id = (select o.lead_id from public.fn_whatsapp_owner(p_phone) o where o.party_kind = 'supplier'))
        or (v_email is not null and (lower(coalesce(l.claimed_by,'')) = v_email or lower(coalesce(l.email,'')) = v_email))
     order by coalesce(l.claimed,false) desc, l.id limit 1;
    if not found then return jsonb_build_object('scope','supplier','known', false); end if;

    return jsonb_build_object(
      'scope','supplier', 'known', true,
      'company', v_lead.company_name,
      'account', jsonb_build_object('email', v_lead.claimed_by, 'phone', coalesce(v_lead.phone_e164, v_lead.phone)),
      'profile', jsonb_build_object(
        'claimed',          coalesce(v_lead.claimed,false),
        'approval_status',  coalesce(v_lead.approval_status,'not submitted'),
        'verified',         coalesce(v_lead.verified,false),
        'email_verified',   coalesce(v_lead.owner_email_verified,false),
        'phone_verified',   coalesce(v_lead.owner_phone_verified,false),
        'trade_licence_no', v_lead.trade_license_no,
        'licence_authority',v_lead.license_authority,
        'licence_expiry',   v_lead.license_expiry,
        'licence_on_file',  (v_lead.license_doc_path is not null),
        'blocked_because',  v_lead.licence_gate_reason),
      'work', jsonb_build_object(
        'inquiries_received',  (select count(*) from inquiry_matches m where m.supplier_id = v_lead.id),
        'inquiries_quoted',    (select count(distinct q.inquiry_id) from quotes q where q.supplier_id = v_lead.id),
        'inquiries_missed',    (select count(*) from inquiry_matches m where m.supplier_id = v_lead.id
                                  and not exists (select 1 from quotes q where q.inquiry_id = m.inquiry_id and q.supplier_id = v_lead.id)),
        'quotes_submitted',    (select count(*) from quotes q where q.supplier_id = v_lead.id),
        'last_quote',          (select jsonb_build_object('amount_aed', q.quote_amount, 'status', q.status, 'when', q.created_at)
                                  from quotes q where q.supplier_id = v_lead.id order by q.created_at desc limit 1),
        'jobs_won',            (select count(*) from quotes q where q.supplier_id = v_lead.id and q.status = 'accepted')));
  end if;

  -- ---------------------------------------------------------------- CUSTOMER: only their own rows
  if p_audience = 'customer' then
    select * into v_cust from customers c
     where (v_e164 <> '' and c.id = (select o.customer_id from public.fn_whatsapp_owner(p_phone) o where o.party_kind = 'customer'))
        or (v_email is not null and lower(coalesce(c.email,'')) = v_email)
     limit 1;
    if not found then return jsonb_build_object('scope','customer','known', false); end if;

    return jsonb_build_object(
      'scope','customer', 'known', true,
      'name', v_cust.full_name,
      -- WHAT WE HOLD FOR THEM. "what is my email registered" was one of the four questions the
      -- assistant could not answer, and the answer was one column away the whole time.
      'account', jsonb_build_object(
        'email', v_cust.email, 'phone', v_cust.phone,
        'language', v_cust.locale, 'industry', v_cust.industry,
        'customer_since', v_cust.created_at),
      'profile', jsonb_build_object(
        'phone_verified', coalesce(v_cust.phone_verified,false),
        'email_verified', coalesce(v_cust.email_verified,false),
        'terms_signed',   (v_cust.signed_terms_url is not null),
        -- create_inquiry's own gate, stated as the fact it is, so the assistant answers "can I post
        -- a request" with the truth rather than an encouragement.
        'can_post_request', (coalesce(v_cust.phone_verified,false) and coalesce(v_cust.email_verified,false)
                             and v_cust.signed_terms_url is not null)),
      'inquiries', coalesce((
        select jsonb_agg(x order by x->>'created_at' desc) from (
          select jsonb_build_object(
            'id', i.id, 'category', i.category, 'emirate', i.emirate, 'status', i.status,
            'created_at', i.created_at,
            'suppliers_received', (select count(*) from inquiry_matches m where m.inquiry_id = i.id),
            'quotes_received',    (select count(*) from quotes q where q.inquiry_id = i.id and q.status='submitted'),
            -- PRE-REVEAL: a band and a count, never the individual quotes and never a supplier name.
            'revealed', exists (select 1 from transactions t where t.inquiry_id = i.id and t.revealed_at is not null),
            'price_band', case
              when exists (select 1 from transactions t where t.inquiry_id = i.id and t.revealed_at is not null)
                then (select jsonb_build_object('low', min(q.quote_amount), 'high', max(q.quote_amount), 'average', round(avg(q.quote_amount)::numeric,0))
                        from quotes q where q.inquiry_id = i.id and q.status='submitted')
              else (select case when count(*) = 0 then null
                                else jsonb_build_object('average_rounded_to_nearest_1000',
                                        round(avg(q.quote_amount)::numeric / 1000) * 1000, 'note',
                                        'rounded band only - the exact quotes and the supplier names unlock when you reveal')
                           end from quotes q where q.inquiry_id = i.id and q.status='submitted') end) as x
          from inquiries i where i.customer_id = v_cust.id order by i.created_at desc limit 10) z), '[]'::jsonb));
  end if;

  return jsonb_build_object('scope','unknown');
end $function$


CREATE OR REPLACE FUNCTION public.fn_wa_fact_pack(p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_lead_id bigint;
  l         record;
  c         record;
  v_cfg     record;
  v_conv    record;
  v_hist    jsonb := '[]'::jsonb;
  v_mand    jsonb;
  v_digits  text;
  -- Built before the return, NOT inside a CASE. Postgres evaluates a record field reference even in
  -- an unreached CASE branch, so with an unknown sender 'record l is not assigned yet' aborts the
  -- whole function. An unknown caller is the most common case, so that bug would have fired first.
  v_ident   jsonb;
  v_found_c boolean := false;
  v_conv_j  jsonb;
begin
  v_digits := regexp_replace(coalesce(p_phone,''), '[^0-9]', '', 'g');
  select standard_reveal_rate, supplier_free_count, supplier_reg_fee, category_open_min_suppliers,
         refund_window_working_days, chase_after_working_days
    into v_cfg from public.pricing_config order by id limit 1;

  v_lead_id := public.fn_wa_lead_id(p_phone);
  if v_lead_id is not null then
    select * into l from public.leads where id = v_lead_id;
    v_mand  := public.fn_supplier_mandatory_check(v_lead_id);
    v_ident := jsonb_build_object(
      'kind','supplier','id',v_lead_id,'company',l.company_name,
      'approval_status', coalesce(l.approval_status,'not reviewed'),
      'registration_status', coalesce(l.registration_status,'not started'),
      'mandatory', v_mand);
  else
    select * into c from public.customers
      where regexp_replace(coalesce(phone,''), '[^0-9]', '', 'g') = v_digits limit 1;
    v_found_c := found;
    if v_found_c then
      v_mand  := public.fn_customer_mandatory_check(c.id);
      v_ident := jsonb_build_object(
        'kind','customer','id',c.id::text,'name',c.full_name,
        'email_verified', c.email_verified, 'phone_verified', c.phone_verified,
        'mandatory', v_mand);
    else
      v_ident := jsonb_build_object('kind','unknown',
        'note','This number matches no lead and no customer. Do not discuss anyone''s records.');
    end if;
  end if;

  v_conv_j := jsonb_build_object('state','new');
  select * into v_conv from public.wa_conversation where phone_e164 = v_digits;
  if found then
    v_conv_j := jsonb_build_object(
      'state', v_conv.thread_state, 'topic', v_conv.topic, 'language', v_conv.language,
      'messages_so_far', v_conv.message_count,
      'window_open', (v_conv.window_expires_at is not null and v_conv.window_expires_at > now()));
    select coalesce(jsonb_agg(jsonb_build_object('at', t.at, 'dir', t.direction,
             'text', coalesce(t.transcript, t.body)) order by t.at), '[]'::jsonb)
      into v_hist
      from (select * from public.wa_turn where conversation_id = v_conv.id order by at desc limit 12) t;
  end if;

  return jsonb_build_object(
    -- WHO. Identity is a fact, never an inference. An unknown sender stays unknown.
    'identity', v_ident,

    -- WHAT IS TRUE ABOUT THE COMPANY. Read live, never remembered.
    'company', jsonb_build_object(
      'reveal_rate_pct', round(coalesce(v_cfg.standard_reveal_rate,0.03) * 100, 1),
      'supplier_free_count', v_cfg.supplier_free_count,
      'supplier_reg_fee_aed', v_cfg.supplier_reg_fee,
      'category_opens_at_suppliers', v_cfg.category_open_min_suppliers,
      'refund_window_working_days', v_cfg.refund_window_working_days,
      'supplier_chase_after_working_days', v_cfg.chase_after_working_days,
      'founder_contact', (coalesce((select value from public.app_secrets where key = 'founder_public_phone'),
                   '(no approved public contact is configured — tell the CEO)')),
      'supplier_mandatory', jsonb_build_array('company name','UAE mobile','email','trade licence','company profile','signed terms'),
      'customer_mandatory', jsonb_build_array('name','mobile','email','signed terms')),

    -- THE THREAD.
    'conversation', v_conv_j,
    'history', v_hist,

    -- WHAT IS NOT KNOWN. Stating this is what stops a model filling the gap with something plausible.
    'unknown', jsonb_build_array(
      'There are no live requests, quotes or comparison reports in the system yet, so no job status can be given for any id.',
      'No category is open yet, so no supplier can currently be matched to a buyer request.',
      'Pricing beyond the reveal rate and registration fee is not set and must not be invented.'),

    -- WHAT MAY NOT BE SAID OR DONE. A boundary, not a suggestion.
    'must_not', jsonb_build_array(
      'Never state a fact that is not in this pack. If it is not here, say you will check and pass it to the team.',
      'Never quote a price, discount, delivery date or timescale that is not in this pack.',
      'Never reveal any other party''s identity, contact details or quote. Anonymity is the product.',
      'Never promise approval, a job, or a refund. Refunds are the founder''s decision alone.',
      'Never ask for a password, a card number or an OTP code.'),

    'generated_at', now()
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_fanout()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_dest text; v_opt text;
begin
  -- only fan out plain email rows; never recurse on whatsapp rows
  if coalesce(new.channel, 'email') <> 'email' or new.to_email is null or coalesce(new.to_role, '') not in ('customer', 'supplier') then return new; end if;
  v_dest := public.fn_whatsapp_destination(new.to_role, null, new.lead_id, new.to_email);
  if v_dest is null then
    if new.to_role = 'customer' then
      select c.whatsapp_opt into v_opt from public.customers c where lower(c.email) = lower(new.to_email) limit 1;
    else
      select l.whatsapp_opt into v_opt from public.leads l where l.id = new.lead_id or (new.lead_id is null and lower(l.claimed_by) = lower(new.to_email)) order by l.id limit 1;
    end if;
    -- 'none' is recorded (a03 marks the twin skipped with the reason); unanswered makes no twin.
    if v_opt is distinct from 'none' then return new; end if;
  end if;
  insert into public.notifications (type, to_email, to_role, to_phone, lead_id, inquiry_id, quote_id, subject, body, channel, status)
  values (new.type, new.to_email, new.to_role, v_dest, new.lead_id, new.inquiry_id, new.quote_id, new.subject, new.body, 'whatsapp', 'queued');
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.fn_wa_founder_alert_fallback(p_notification_id bigint, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  n public.notifications%rowtype;
  v_phone text; v_email text; v_kind text; v_twin integer; v_new bigint; v_outcome text; v_claim bigint;
begin
  select * into n from public.notifications where id = p_notification_id;
  if not found then return jsonb_build_object('ok', false, 'outcome', 'no_such_row'); end if;
  if coalesce(n.channel, 'email') <> 'whatsapp' then
    return jsonb_build_object('ok', false, 'outcome', 'not_whatsapp');
  end if;

  -- Same test as a10_notifications_founder_mail_policy, so one cannot admit what the other refuses.
  select regexp_replace(coalesce(value, ''), '[^0-9]', '', 'g') into v_phone
    from public.app_secrets where key = 'admin_mfa_phone';
  if not (coalesce(n.to_role, '') in ('founder', 'admin', 'owner')
          or (n.to_phone is not null and coalesce(v_phone, '') <> ''
              and regexp_replace(n.to_phone, '[^0-9]', '', 'g') = v_phone)) then
    return jsonb_build_object('ok', false, 'outcome', 'not_founder');
  end if;

  v_kind := coalesce(nullif(btrim(n.kind), ''), nullif(btrim(n.type), ''), 'unregistered');

  -- 1. CLAIM THE ROW BEFORE DOING ANYTHING ELSE. send_whatsapp runs every 15 minutes and a run can
  --    overlap its predecessor; without a claim two callers could both pass the twin check and both
  --    queue a fallback email, so the founder would get the same alert twice. The UPDATE takes the
  --    row lock and only one caller gets an id back. The outcome is not known yet, so last_error is
  --    written provisionally here and finished below — a row can never be left saying 'pending'
  --    because both writes are in the same transaction as the caller's rpc.
  update public.notifications
     set status = 'skipped',
         last_error = left('not delivered by WhatsApp: ' || coalesce(p_reason, 'unspecified')
                           || ' | founder fallback: in progress', 500)
   where id = n.id and status in ('queued', 'held')
   returning id into v_claim;
  if v_claim is null then
    -- another run already retired this row, or it was delivered in the meantime. Do NOT email again.
    return jsonb_build_object('ok', false, 'outcome', 'already_handled', 'notification_id', n.id);
  end if;

  -- 2. Did the email twin already carry this alert? fn_notify_founder inserts the email row and the
  --    WhatsApp row in the same call, so the twin shares created_at to the microsecond; ten minutes
  --    is a generous window that still cannot reach the next tick's alert, and the subject match
  --    pins it to THIS event rather than to any alert of the same kind.
  --    ponytail: the correlation is (kind, ±10 minutes, subject containment) because the two rows
  --    share no id today — fn_notify_founder writes the email subject as '[Attention] ' || event and
  --    the WhatsApp subject as the bare event, so one contains the other. Two alerts of the SAME
  --    kind inside ten minutes where one subject contains the other would mis-correlate. Give both
  --    rows a shared correlation id in fn_notify_founder if that ever becomes possible; the ceiling
  --    here is a one-hour-per-problem deduped IT digest, so it cannot happen with today's writers.
  --    The window is bounded by created_at, which notifications_status_idx covers.
  select count(*) into v_twin
    from public.notifications e
   where e.channel = 'email'
     and coalesce(e.to_role, '') in ('founder', 'admin', 'owner')
     and coalesce(nullif(btrim(e.kind), ''), nullif(btrim(e.type), ''), 'unregistered') = v_kind
     and e.status in ('queued', 'sent')
     and e.created_at between n.created_at - interval '10 minutes' and n.created_at + interval '10 minutes'
     and position(coalesce(n.subject, '~none~') in coalesce(e.subject, '')) > 0;

  if v_twin > 0 then
    v_outcome := 'email_twin_already_sent';
  else
    select coalesce(nullif(split_part(coalesce(value, ''), ',', 1), ''), 'management@quotesdone.com')
      into v_email from public.app_secrets where key = 'admin_emails';
    v_email := coalesce(v_email, 'management@quotesdone.com');

    -- The kind travels with the fallback on purpose. Queue it as 'founder_alert' with the row's own
    -- kind and a10 admits it exactly when founder_mail_policy says that kind is his to read.
    insert into public.notifications (type, kind, to_email, to_role, subject, body, status, channel)
    values ('founder_alert', v_kind, v_email, 'founder',
            '[Attention] ' || coalesce(n.subject, 'QuotesDone alert'), n.body, 'queued', 'email')
    returning id into v_new;

    if v_new is null then
      -- a10 returned NULL: founder_mail_policy says this kind is not his to read, so the alert was
      -- routed to its owning seat instead. That is a decision, not a delivery — record it where the
      -- OS can see it rather than let the WhatsApp row disappear claiming an email went.
      v_outcome := 'blocked_by_founder_mail_policy';
      insert into public.founder_alerts (level, event, detail, channel)
      values ('high', 'whatsapp_fallback:blocked_by_policy',
              left('notification ' || n.id || ' (kind ' || v_kind || ') could not be sent by WhatsApp ('
                   || coalesce(p_reason, 'unspecified') || ') and founder_mail_policy does not allow '
                   || 'that kind by email either: ' || coalesce(n.subject, ''), 1000), 'os');
    else
      v_outcome := 'emailed';
    end if;
  end if;

  -- 4. Finish the record the claim in step 1 opened. The row is already out of the queue; this only
  --    replaces 'in progress' with what actually happened, so the row explains itself for ever.
  update public.notifications
     set last_error = left('not delivered by WhatsApp: ' || coalesce(p_reason, 'unspecified')
                           || ' | founder fallback: ' || v_outcome, 500)
   where id = n.id;

  return jsonb_build_object('ok', true, 'outcome', v_outcome, 'kind', v_kind,
                            'email_notification_id', v_new, 'notification_id', n.id);
end $function$


CREATE OR REPLACE FUNCTION public.fn_wa_human_hold(p_phone text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select coalesce((select thread_state = 'handed_to_human' from public.wa_conversation
                    where phone_e164 = regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g')), false)
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_human_request(p_phone text, p_hold boolean, p_event text, p_detail text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_digits text := regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g'); v_h bigint; v_ok boolean := true; v_err text;
begin
  if length(v_digits) < 9 then return jsonb_build_object('ok', false, 'reason', 'no usable number'); end if;
  if p_hold then
    insert into public.wa_conversation (phone_e164, party_kind, message_count, thread_state, handed_to)
    values (v_digits, 'unknown', 0, 'handed_to_human', 'customer_support')
    on conflict (phone_e164) do update set thread_state = 'handed_to_human', handed_to = 'customer_support', last_seen_at = now();
  end if;
  select id into v_h from public.agent_actions
   where kind = 'handoff' and status = 'pending' and detail ->> 'type' = 'support.human_requested' and detail ->> 'phone_digits' = v_digits
   order by id desc limit 1;
  if v_h is null then
    v_h := public.fn_seat_handoff('customer_support', 'customer_support', 'support.human_requested', 'wa_conversation',
      v_digits || ':' || to_char(now() at time zone 'UTC', 'YYYYMMDDHH24MISS'),
      jsonb_build_object('phone_digits', v_digits, 'held', p_hold, 'event', p_event,
                         'waiting_for', 'a person to answer +' || v_digits || ' on WhatsApp'));
  end if;
  begin
    perform public.fn_notify_founder(p_event => p_event, p_detail => p_detail, p_level => 'high', p_kind => 'whatsapp_human_request',
                                     p_dedupe_key => 'wa_human:' || v_digits || ':' || to_char(now() at time zone 'Asia/Dubai', 'YYYY-MM-DD'),
                                     p_owner_agent => 'customer_support');
  exception when others then v_ok := false; v_err := left(sqlerrm, 300);
  end;
  return jsonb_build_object('ok', true, 'handoff_id', v_h, 'held', p_hold, 'notified', v_ok, 'notify_error', v_err);
end $function$


CREATE OR REPLACE FUNCTION public.fn_wa_human_request_close(p_phone text, p_by text, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_digits text := regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g'); r record; n int := 0;
begin
  -- The founder may type 050..., 50... or 971...: the last nine digits name the number.
  update public.wa_conversation set thread_state = 'open', handed_to = null
   where right(phone_e164, 9) = right(v_digits, 9) and thread_state = 'handed_to_human';
  for r in select id from public.agent_actions
            where kind = 'handoff' and status = 'pending' and detail ->> 'type' = 'support.human_requested'
              and right(detail ->> 'phone_digits', 9) = right(v_digits, 9) loop
    perform public.fn_seat_handoff_complete(r.id, jsonb_build_object('closed_by', coalesce(p_by, 'founder'), 'note', p_note, 'closed_at', now()));
    n := n + 1;
  end loop;
  return jsonb_build_object('closed', n);
end $function$


CREATE OR REPLACE FUNCTION public.fn_wa_human_request_tick()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; v_conv public.wa_conversation; v_ref text; v_secret text; v_req bigint; v_body text; v_lang text; n int := 0; v_sent int := 0;
begin
  select value into v_ref from public.app_secrets where key = 'project_ref';
  select value into v_secret from public.app_secrets where key = 'cred_fn_resilience_ping';
  for r in select a.* from public.agent_actions a
            where a.kind = 'handoff' and a.status = 'pending' and a.detail ->> 'type' = 'support.human_requested'
              and a.created_at < now() - interval '23 hours' and not (a.detail ? 'followed_up_at')
              and coalesce(a.detail ->> 'held', 'true') = 'true'
            order by a.id limit 20 loop
    n := n + 1; v_req := null;
    update public.wa_conversation set thread_state = 'open', handed_to = null
     where phone_e164 = r.detail ->> 'phone_digits' and thread_state = 'handed_to_human'
    returning * into v_conv;
    if v_conv.id is null then select * into v_conv from public.wa_conversation where phone_e164 = r.detail ->> 'phone_digits'; end if;
    v_lang := case when coalesce(v_conv.language, '') = 'ar' then 'ar' else 'en' end;
    v_body := case when v_lang = 'ar'
      then 'نعتذر عن تأخر ردنا عليكم. لم يتمكن أحد أعضاء الفريق من التواصل معكم بعد، وقد أبلغناه مجددًا بطلبكم. وإلى حين ذلك عادت إليكم خدمة الردود الفورية في هذه المحادثة، فتفضلوا بإرسال كلمة «قائمة» لعرض الخيارات أو كتابة استفساركم.' || E'\n\nفريق خدمة العملاء في QuotesDone'
      else 'We are sorry you have not heard from us yet. A member of the team has not been able to reach you, and we have reminded them of your request. Meanwhile, instant answers are back on in this chat: reply MENU for the options or type your question.' || E'\n\nQuotesDone Customer Support' end;
    if v_conv.window_expires_at > now() and v_ref is not null and v_secret is not null then
      select net.http_post(
        url := 'https://' || v_ref || '.supabase.co/functions/v1/send_whatsapp',
        headers := jsonb_build_object('Content-Type', 'application/json'),
        body := jsonb_build_object('__secret', v_secret, 'to', '+' || (r.detail ->> 'phone_digits'), 'body', v_body),
        timeout_milliseconds := 15000) into v_req;
      v_sent := v_sent + 1;
    end if;
    begin
      perform public.fn_notify_founder(p_event => 'WhatsApp: +' || (r.detail ->> 'phone_digits') || ' has waited 23 hours for a person',
        p_detail => 'Nobody closed the request from +' || (r.detail ->> 'phone_digits') || ' (' || coalesce(r.detail ->> 'event', 'Talk to a person') || ').'
        || case when v_req is not null then ' They were sent a polite follow-up and automatic replies are back on.'
                else ' Their WhatsApp window has closed, so no follow-up could be sent; call them or email them.' end
        || E'\nReply now: https://wa.me/' || (r.detail ->> 'phone_digits')
        || E'\nWhen handled, send DONE +' || (r.detail ->> 'phone_digits') || ' to the QuotesDone WhatsApp number.',
        p_level => 'high', p_kind => 'whatsapp_human_request', p_dedupe_key => 'wa_human_followup:' || r.id,
        p_owner_agent => 'customer_support');
    exception when others then null;   -- the follow-up is recorded below either way
    end;
    update public.agent_actions
       set detail = detail || jsonb_build_object('followed_up_at', now(), 'followup_request_id', v_req,
                                                 'followup_skipped', case when v_req is null then 'the 24-hour WhatsApp window had closed' end)
     where id = r.id;
  end loop;
  return jsonb_build_object('ok', true, 'due', n, 'followups_queued', v_sent);
end $function$


CREATE OR REPLACE FUNCTION public.fn_wa_lead_id(p_phone text)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  -- 14 Sep 2026 (#322): only a supplier's CONFIRMED WhatsApp number (fn_whatsapp_owner). fn_wa_answer
  -- and fn_wa_fact_pack identify suppliers through this function.
  select o.lead_id from public.fn_whatsapp_owner(p_phone) o where o.party_kind = 'supplier';
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_menu_context(p_phone text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id json; v_aud text; v_cust uuid; v_lead bigint; v_name text; v_company text; v_reqs jsonb := '[]'::jsonb;
begin
  v_id  := public.fn_identify_contact(p_phone);
  v_aud := coalesce(v_id ->> 'audience', 'unknown');
  if v_aud = 'founder' then
    select nullif(btrim(value), '') into v_name from public.app_secrets where key = 'founder_name';
  elsif v_aud in ('customer', 'supplier') then
    -- fn_identify_contact already confirmed the number; this reads the same owner row for its ids.
    select o.customer_id, o.lead_id into v_cust, v_lead from public.fn_whatsapp_owner(p_phone) o limit 1;
    if v_aud = 'supplier' then
      select nullif(btrim(contact_name), ''), nullif(btrim(company_name), '') into v_name, v_company
        from public.leads where id = v_lead;
    else
      select nullif(btrim(full_name), '') into v_name from public.customers where id = v_cust;
    end if;
  end if;
  -- A greeting never carries an address (22 Sep: "Good day management@quotesdone.com").
  if v_name ~ '@' then v_name := null; end if;
  if v_company ~ '@' then v_company := null; end if;
  if v_aud = 'customer' and v_cust is not null then
    select coalesce(jsonb_agg(jsonb_build_object('id', i.id, 'rfq_no', i.rfq_no, 'status', i.status, 'created_at', i.created_at)
                              order by i.created_at desc), '[]'::jsonb)
      into v_reqs
      from (select id, rfq_no, status, created_at from public.inquiries
             where customer_id = v_cust and completed_at is null
               and coalesce(status, '') not in ('closed', 'cancelled', 'completed', 'lost')
             order by created_at desc limit 5) i;
  end if;
  return jsonb_build_object('audience', v_aud, 'name', coalesce(v_name, v_company), 'company', v_company,
                            'approved', coalesce((v_id ->> 'approved')::boolean, false), 'requests', v_reqs);
end $function$


CREATE OR REPLACE FUNCTION public.fn_wa_model_brief()
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select
     'You are the QuotesDone WhatsApp agent, talking to UAE suppliers and buyers. '

  || 'ABSOLUTE RULE ON FACTS: every detail about any customer, supplier, quote, job or price comes '
  || 'from fact_pack and from nowhere else. You know nothing about this company or these people '
  || 'except what fact_pack contains, and you must never fill such a gap from memory or from what '
  || 'seems likely. '

  || 'THE OWNER''S NUMBER IS ' || (coalesce((select value from public.app_secrets where key = 'founder_public_phone'),
                   '(no approved public contact is configured — tell the CEO)')) || ' AND THERE ARE EXACTLY TWO REASONS TO GIVE IT. One: the '
  || 'sender asked to speak to a person, an agent or a human, or asked who owns or runs QuotesDone. '
  || 'Two: the message is a complaint, a dispute or an accusation, which needs a person whether they '
  || 'asked or not. In both cases give it plainly and without making them ask twice, because the '
  || 'owner is the only person in this company and an escalation that does not reach him reaches '
  || 'nobody. Give it for NOTHING ELSE: not for an off-topic question, not for small talk, not '
  || 'because you could not answer. '

  || 'ABSOLUTE RULE ON SUBJECT: if the message is not about QuotesDone, reply with EXACTLY this '
  || 'sentence and nothing else: "' || public.fn_wa_off_topic_reply() || '" '
  || 'Translate it into the sender''s language if they did not write in English, but do not reword '
  || 'it, do not add to it, do not apologise around it, and do not answer the question first. Never '
  || 'state a fact about the outside world as if you had checked it: you cannot see the weather, a '
  || 'score, a rate or the time. '

  || 'BUT PHRASING IS NOT SUBJECT. A QuotesDone question asked in unusual words is still a QuotesDone '
  || 'question. "any update on my file bro" is a registration-status question and must be understood '
  || 'and answered from the record. Judge what the message is ABOUT, never how it is worded. '

  || 'WHEN IT IS ABOUT US BUT THE PACK LACKS THE FACT: say you will check and that someone will come '
  || 'back to them. That gap is ours. '

  || 'The sender may write in any language: understand them and reply in their own. Follow the '
  || 'conversation history. Honour every entry in must_not. Match the courtesy you are given; a '
  || 'greeting gets a greeting, not a menu. Be brief, plain and useful, the way a competent person '
  || 'on a phone would be.'
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_off_topic_reply()
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select 'I am here to assist you with QuotesDone inquiries only. Please let me know how I can help you.'
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_problem_report(p_phone text, p_text text, p_lang text DEFAULT 'en'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  alphabet constant text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';   -- 32 symbols, no 0/O/1/I (as fn_complaint_open)
  v_digits text := regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g');
  v_days int := greatest(1, public.fn_seat_clock_policy('support_case_append_days', 7)::int);
  v_sla numeric := public.fn_seat_clock_policy('support_first_reply_sla_hours', 24);
  v_lang text := case when p_lang = 'ar' then 'ar' else 'en' end;
  v_kind text; v_cust uuid; v_lead bigint; v_party text; v_ref text; v_id bigint; v_inq text; v_bytes bytea;
  v_case public.support_case; v_report jsonb; i int; attempt int := 0;
begin
  if coalesce(btrim(p_text), '') = '' then raise exception 'fn_wa_problem_report: empty report'; end if;
  select o.party_kind, o.customer_id, o.lead_id into v_kind, v_cust, v_lead from public.fn_whatsapp_owner(p_phone) o limit 1;
  v_party  := coalesce(v_cust::text, v_lead::text, '+' || v_digits);
  v_report := jsonb_build_object('at', now(), 'text', left(btrim(p_text), 4000));

  -- The request the report names, when it is one of this customer's own.
  if v_cust is not null then
    select i.rfq_no::text into v_inq from public.inquiries i
     where i.customer_id = v_cust and i.rfq_no is not null and p_text ~ ('(^|[^0-9])' || i.rfq_no::text || '([^0-9]|$)')
     order by i.created_at desc limit 1;
  end if;

  -- An open case from this number or this account in the last v_days days takes the report.
  select c.* into v_case from public.support_case c
   where c.state <> 'closed' and c.opened_at > now() - make_interval(days => v_days)
     and c.party_id in (v_party, '+' || v_digits)
   order by c.opened_at desc limit 1;
  if found then
    update public.support_case set last_activity_at = now(), inquiry_ref = coalesce(inquiry_ref, v_inq)
     where case_id = v_case.case_id;
    update public.agent_actions
       set detail = jsonb_set(detail, '{reports}', coalesce(detail -> 'reports', '[]'::jsonb) || v_report)
     where kind = 'handoff' and target_id = 'support.case_open:' || v_case.case_id;
    return jsonb_build_object('case_ref', v_case.case_ref, 'case_id', v_case.case_id, 'appended', true,
                              'sla_hours', v_sla, 'party_kind', v_case.party_kind);
  end if;

  loop
    attempt := attempt + 1;
    v_bytes := decode(replace(gen_random_uuid()::text, '-', ''), 'hex');
    v_ref := 'QD-S-';
    for i in 0..5 loop v_ref := v_ref || substr(alphabet, (get_byte(v_bytes, i) % 32) + 1, 1); end loop;
    begin
      insert into public.support_case (case_ref, party_kind, party_id, inquiry_ref, subject, state, identity_verified, verified_how, owner_role_id)
      values (v_ref, coalesce(v_kind, 'unknown'), v_party, v_inq,
              'WhatsApp problem report (' || v_lang || '): ' || left(btrim(p_text), 4000),
              'open', v_kind is not null, case when v_kind is not null then 'confirmed WhatsApp number' end, 'customer_support')
      returning case_id into v_id;
      exit;
    exception when unique_violation then
      if attempt >= 5 then raise; end if;
    end;
  end loop;

  perform public.fn_seat_handoff('customer_support', 'customer_support', 'support.case_open', 'support_case', v_id::text,
    jsonb_build_object('case_ref', v_ref, 'phone_digits', v_digits, 'lang', v_lang, 'party_kind', coalesce(v_kind, 'unknown'),
                       'inquiry_ref', v_inq, 'reports', jsonb_build_array(v_report), 'sla_hours', v_sla,
                       'waiting_for', 'the first reply to case ' || v_ref || ' (reporter +' || v_digits || ')'));
  return jsonb_build_object('case_ref', v_ref, 'case_id', v_id, 'appended', false, 'sla_hours', v_sla,
                            'party_kind', coalesce(v_kind, 'unknown'), 'inquiry_ref', v_inq);
end $function$


CREATE OR REPLACE FUNCTION public.fn_wa_record_turn(p_phone text, p_direction text, p_body text DEFAULT NULL::text, p_media_url text DEFAULT NULL::text, p_media_kind text DEFAULT NULL::text, p_transcript text DEFAULT NULL::text, p_intent text DEFAULT NULL::text, p_answered_by text DEFAULT NULL::text, p_fact_pack jsonb DEFAULT NULL::jsonb, p_model text DEFAULT NULL::text, p_cost_aed numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_digits text := regexp_replace(coalesce(p_phone,''), '[^0-9]', '', 'g');
  v_conv   record;
  v_lead   bigint;
  v_cust   uuid;
  v_kind   text := 'unknown';
  v_pid    text;
  v_turn   bigint;
  v_dir    text;
begin
  -- THE DIRECTION IS NORMALISED HERE, WHERE THE CALLER'S VOCABULARY MEETS THE COLUMN'S.
  -- Every branch below compares p_direction to 'in', and wa_turn's CHECK allows only 'in' and
  -- 'out'. A caller writing 'INBOUND' -- the obvious word, and the one the edge function reached
  -- for -- hit the CHECK and the whole turn was lost. Worse would have been no CHECK: the row
  -- would have been stored and the 24-hour service window would never have opened, so the agent
  -- would have gone quiet a day later for a reason nothing recorded.
  v_dir := case lower(btrim(coalesce(p_direction, '')))
             when 'in' then 'in' when 'inbound' then 'in' when 'incoming' then 'in'
             when 'out' then 'out' when 'outbound' then 'out' when 'outgoing' then 'out'
             else null end;
  if v_dir is null then
    return jsonb_build_object('ok', false, 'reason',
      format('direction %L is neither inbound nor outbound; nothing was recorded', p_direction));
  end if;
  if v_digits = '' then
    return jsonb_build_object('ok', false, 'reason', 'No usable phone number on the message.');
  end if;

  v_lead := public.fn_wa_lead_id(p_phone);
  if v_lead is not null then
    v_kind := 'lead'; v_pid := v_lead::text;
  else
    select id into v_cust from public.customers
     where regexp_replace(coalesce(phone,''), '[^0-9]', '', 'g') = v_digits limit 1;
    if v_cust is not null then v_kind := 'customer'; v_pid := v_cust::text; end if;
  end if;

  insert into public.wa_conversation (phone_e164, party_kind, party_id, message_count,
                                      window_opened_at, window_expires_at)
  values (v_digits, v_kind, v_pid, 0,
          case when v_dir = 'in' then now() else null end,
          case when v_dir = 'in' then now() + interval '24 hours' else null end)
  on conflict (phone_e164) do update set
      last_seen_at   = now(),
      party_kind     = coalesce(excluded.party_kind, wa_conversation.party_kind),
      party_id       = coalesce(excluded.party_id,   wa_conversation.party_id),
      -- An INBOUND message opens or re-opens the 24-hour service window. An outbound one never does,
      -- which is the whole point of the rule: we cannot extend our own permission to keep talking.
      window_opened_at  = case when v_dir = 'in' then now() else wa_conversation.window_opened_at end,
      window_expires_at = case when v_dir = 'in' then now() + interval '24 hours'
                               else wa_conversation.window_expires_at end
  returning * into v_conv;

  update public.wa_conversation
     set message_count = message_count + 1,
         last_intent   = coalesce(p_intent, last_intent)
   where id = v_conv.id
  returning * into v_conv;

  insert into public.wa_turn (conversation_id, direction, body, media_url, media_kind, transcript,
                              transcript_source, intent_key, answered_by, fact_pack, model_id, cost_aed)
  values (v_conv.id, v_dir, p_body, p_media_url, p_media_kind, p_transcript,
          case when p_transcript is not null then 'model' else 'none' end,
          p_intent, p_answered_by, p_fact_pack, p_model, p_cost_aed)
  returning id into v_turn;

  return jsonb_build_object(
    'ok', true, 'conversation_id', v_conv.id, 'turn_id', v_turn,
    'party_kind', v_conv.party_kind, 'party_id', v_conv.party_id,
    'message_count', v_conv.message_count,
    'window_expires_at', v_conv.window_expires_at,
    'window_open', (v_conv.window_expires_at is not null and v_conv.window_expires_at > now())
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_route(p_phone text, p_body text, p_has_audio boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_digits text := regexp_replace(coalesce(p_phone,''), '[^0-9]', '', 'g');
  v_det    jsonb;
  v_pack   jsonb;
  v_conv   record;
  v_needs  boolean;
  v_why    text;
  v_held   boolean;
  v_latin  boolean;
  v_trouble boolean;
  v_asked  boolean;
  v_person boolean;
  v_reason text;
  v_chain  jsonb;
  v_intent text;
  v_reply  text;
begin
  select coalesce((select value = 'true' from public.app_secrets where key = 'paid_inference_enabled'), false)
    into v_held;
  v_held := not v_held;

  v_det  := public.fn_wa_answer(p_phone, coalesce(p_body, '(voice note)'));
  v_pack := public.fn_wa_fact_pack(p_phone);
  v_intent := v_det->>'intent';
  v_reply  := v_det->>'reply';
  select * into v_conv from public.wa_conversation where phone_e164 = v_digits;

  v_latin := coalesce(p_body, '') ~ '^[\s\x20-\x7E]*$';

  -- The two ways a message needs a person.
  v_asked   := coalesce(v_intent = 'contact_human', false);
  v_trouble := coalesce(p_body,'') ~* '(complain|refund|dispute|angry|lawyer|legal|scam|cheat|fraud|شكوى|احتيال|نصب)';

  -- One decision now, not two. Needing a person and getting his number are the same thing here.
  v_person := v_asked or v_trouble;
  v_reason := case
    when v_asked   then 'They asked for a person, or asked who runs the company.'
    when v_trouble then 'This is a complaint, a dispute or an accusation. It needs a person whether '
                     || 'they asked for one or not, and the founder is the only person there is.'
    else 'Nobody asked for a person and nothing here needs one. A number given out by a machine '
      || 'cannot be taken back.' end;

  -- A complaint gets the number appended, because the escalation and the contact are the same act.
  if v_trouble and not v_asked then
    v_reply := v_reply || ' If you would rather speak to someone directly, call or message '
            || '+971 50 931 9355, which is answered by the owner.';
  end if;

  v_needs := false; v_why := 'A deterministic answer matched and the message is simple, so this turn costs nothing.';
  if p_has_audio then
    v_needs := true; v_why := 'The message is a voice note and must be transcribed before it can be answered.';
  elsif not v_latin then
    v_needs := true; v_why := 'The message is not in Latin script and the fixed answers exist only in English.';
  elsif v_intent in ('small_talk','off_topic','greeting','contact_human') then
    v_needs := false;
    v_why := format('Matched %s, which is answered completely without a model.', v_intent);
  elsif coalesce((v_det->>'matched')::boolean, false) = false then
    v_needs := true; v_why := 'No fixed answer matched. Wording varies, so this is the normal case rather than an exception.';
  elsif coalesce(v_conv.message_count, 0) >= 2 then
    v_needs := true; v_why := 'This is a continuing conversation; a fixed answer would ignore what came before.';
  elsif length(coalesce(p_body,'')) > 160 then
    v_needs := true; v_why := 'The message is long enough to contain more than one question.';
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'rung', rung, 'model', model, 'kind', kind, 'rationale', rationale) order by rung), '[]'::jsonb)
    into v_chain
    from public.model_fallback_chain
   where purpose = 'whatsapp_conversation' and active;

  return jsonb_build_object(
    'ok', true,
    'needs_model', v_needs,
    'why', v_why,
    'inference_held', v_held,
    'model', case when v_needs then 'google/gemini-3-flash' else null end,
    'fallback_chain', case when v_needs then v_chain else null end,
    'on_model_failure',
      'Try each rung in order. Record model_wanted, model_used and fell_back on llm_calls for every '
   || 'attempt, so a fallback that becomes permanent is visible rather than quietly expensive. The '
   || 'final rung is the deterministic reply and it cannot fail.',
    'model_reason', case
      when not v_needs then 'No model needed. The database answered it.'
      else 'google/gemini-3-flash first, by founder ruling. On failure claude-sonnet-5. On failure the '
        || 'deterministic reply. Every rung gets the same fact pack and the same boundaries.' end,

    -- One decision. Handing to a person and giving the number are the same act.
    'needs_a_person', v_person,
    'founder_number', case when v_person then (coalesce((select value from public.app_secrets where key = 'founder_public_phone'),
                   '(no approved public contact is configured — tell the CEO)')) else null end,
    'person_reason', v_reason,
    'opened_by', case when v_asked then 'they asked'
                      when v_trouble then 'complaint or dispute'
                      else null end,

    'action', case
      when v_needs and v_held  then 'send_deterministic_and_log_shortfall'
      when v_needs             then 'walk_fallback_chain_with_fact_pack'
      else                          'send_deterministic' end,

    'transcription_gap', case when p_has_audio
      then 'Whether Gemini 3 Flash can take the Twilio media URL directly, or whether a speech model '
        || 'must be added to ai_model_register first, is NOT established and must be checked before '
        || 'audio is enabled.'
      else null end,

    'deterministic_reply', v_reply,
    'deterministic_intent', v_intent,
    'fact_pack', v_pack,
    'model_brief', public.fn_wa_model_brief()
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_wa_signature_watch()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n_rows int; n_senders int; v_last timestamptz;
begin
  if coalesce(new.meta ->> 'signature_valid', '') = 'false' then
    select count(*), count(distinct wa_from), max(created_at) into n_rows, n_senders, v_last
      from public.wa_messages
     where created_at > now() - interval '24 hours' and meta ->> 'signature_valid' = 'false';
    perform public.fn_it_engineer_finding_upsert(
      'wa_inbound:signature_refused',
      'Inbound WhatsApps are being refused at the door: ' || n_rows || ' failed X-Twilio-Signature in 24 hours, so nobody who wrote got an answer',
      'supabase/functions/wa_inbound (verifyTwilioSignature, signature.ts) and app_secrets.twilio_auth_token',
      'customer_facing', n_senders,
      jsonb_build_object('refused_24h', n_rows, 'senders_24h', n_senders, 'last_refused_at', v_last,
                         'last_reason', new.meta ->> 'signature_reason', 'urls_tried', new.meta -> 'signature_urls_tried',
                         'owner_seat', 'customer_support'),
      '{}'::text[],
      array['whether the refused request was a forgery or a genuine Twilio webhook signed over a URL or token we did not try'],
      'it_engineer.wa_signature_watch');
  elsif coalesce(new.meta ->> 'signature_valid', '') = 'true' or coalesce(new.meta ->> 'provenance_verified', '') = 'true' then
    if exists (select 1 from public.it_engineer_finding where issue_key = 'wa_inbound:signature_refused' and closed_at is null) then
      perform public.fn_it_engineer_finding_close('wa_inbound:signature_refused',
        'an inbound WhatsApp passed verification at ' || to_char(now() at time zone 'UTC', 'YYYY-MM-DD HH24:MI') || 'Z (wa_messages ' || new.id || ')');
    end if;
  end if;
  return null;
exception when others then
  -- The watch must never cost the message row it is watching.
  raise warning 'fn_wa_signature_watch: %', sqlerrm;
  return null;
end $function$


CREATE OR REPLACE FUNCTION public.fn_wa_unmatched_reply()
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select 'I can help with your registration, your documents, your quotes, and any job by its number. '
      || 'I am not sure about that one, so let me check and someone will come back to you.'
$function$


CREATE OR REPLACE FUNCTION public.fn_watch_failed_runs()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_stale record;
  v_stale_n int := 0;
  v_rehearsal int := 0;
  v_since    timestamptz;
  v_fail     record;
  v_alerts   int := 0;
  v_held     int := 0;
  v_real     int := 0;
  v_detail   text := '';
  v_models_answering boolean;
begin
  select coalesce(last_run_at, now() - interval '24 hours') into v_since
    from alert_watermark where watcher = 'failed_runs';
  if not found then
    insert into alert_watermark (watcher, last_run_at) values ('failed_runs', now() - interval '24 hours');
    v_since := now() - interval '24 hours';
  end if;

  -- IS A MODEL ANSWERING AT ALL? This one boolean is what separates "the AI is broken" from
  -- "the AI is switched off", and it is measured, not configured - nothing here reads a flag that
  -- someone could forget to clear. A single successful attempt in the last 24 hours is enough to
  -- put every model-unavailable error back on the failure side.
  select exists (select 1 from public.llm_attempt
                  where created_at > now() - interval '24 hours' and coalesce(ok, false))
    into v_models_answering;
  -- Rows inside a declared sandbox rehearsal window (demo_factory.withRun): counted, stated in the
  -- message if one goes out, never the reason one goes out. A rehearsal on the production database
  -- paged the founder twice on 3 Sep 2026 about the operator's own probes; this is the fix.
  select count(*) into v_rehearsal
    from agent_runs r
   where r.started_at > v_since and r.status = 'error'
     and public.fn_rehearsal_window_covers(r.started_at);

  for v_fail in
    select r.agent,
           count(*) as fails,
           max(r.started_at) as latest,
           left(coalesce(max(r.note), ''), 300) as sample_note,
           -- The signature is the agent plus the shape of the note, not the note itself: the same
           -- standing condition arrives with different numbers in it every pass ("3 step(s) are
           -- ready" one hour, "4" the next) and must still be recognised as the same condition.
           r.agent || ':' || left(regexp_replace(coalesce(max(r.note), ''), '[0-9]+', '#', 'g'), 120) as signature,
           bool_or(coalesce(r.note, '') ~* '(model returned nothing|returned no content|generation_failed|returned nothing for|model call failed|open-circuit|LLM call failed)') as model_shaped
      from agent_runs r
     where r.started_at > v_since and r.status = 'error'
       -- a row inside a DECLARED rehearsal window is counted below, not paged (3 Sep 2026)
       and not public.fn_rehearsal_window_covers(r.started_at)
     group by r.agent, left(regexp_replace(coalesce(r.note, ''), '[0-9]+', '#', 'g'), 120)
     order by count(*) desc
  loop
    -- HELD: a model did not answer, and no model has answered at all. Counted, recorded, not
    -- alerted. The moment v_models_answering flips true this branch stops being taken.
    if v_fail.model_shaped and not v_models_answering then
      v_held := v_held + v_fail.fails;
      insert into public.alert_signature (watcher, signature)
        values ('failed_runs', v_fail.signature)
        on conflict (watcher, signature) do update
          set last_seen_at = now(), seen_count = alert_signature.seen_count + 1, resolved_at = null;
      continue;
    end if;

    v_real := v_real + v_fail.fails;

    -- ONCE PER CONDITION. A signature alerted inside the last 24 hours is still recorded as seen,
    -- and does not interrupt him again.
    insert into public.alert_signature (watcher, signature)
      values ('failed_runs', v_fail.signature)
      on conflict (watcher, signature) do update
        set last_seen_at = now(), seen_count = alert_signature.seen_count + 1, resolved_at = null;

    if exists (select 1 from public.alert_signature s
                where s.watcher = 'failed_runs' and s.signature = v_fail.signature
                  and s.last_alerted_at > now() - interval '24 hours') then
      continue;
    end if;

    v_detail := v_detail || v_fail.agent || ': ' || v_fail.fails || ' failure(s). ' || v_fail.sample_note || E'\n';
    v_alerts := v_alerts + 1;
    update public.alert_signature set last_alerted_at = now()
      where watcher = 'failed_runs' and signature = v_fail.signature;
  end loop;

  -- The hold is stated once, in the same message, so it is never invisible: he should be able to
  -- see that the quiet is his own decision and not a working company.
  if v_held > 0 then
    v_detail := v_detail || E'\n' || v_held ||
      ' further run(s) could not reach a model. No model call has succeeded in 24 hours, so these ' ||
      'are counted as held by the paid-inference hold, not as failures. They will be reported as ' ||
      'failures again the moment a model answers.' || E'\n';
  end if;

  -- THE DEAD-GUARD BLIND SPOT (3 Sep 2026). A job that never fires produces no failure. v_cron_stale
  -- lists active jobs with no run of any status inside twice their schedule, measured from activation
  -- (scripts/sql/v_cron_stale_the_dead_guard_blind_spot.sql). Same ledger, same once-per-24h rule.
  for v_stale in select jobname, schedule, why from public.v_cron_stale order by jobname loop
    v_stale_n := v_stale_n + 1;
    insert into public.alert_signature (watcher, signature) values ('failed_runs', 'cron_stale:' || v_stale.jobname)
    on conflict (watcher, signature) do update set last_seen_at = now(), seen_count = alert_signature.seen_count + 1, resolved_at = null;
    if exists (select 1 from public.alert_signature s where s.watcher = 'failed_runs'
                 and s.signature = 'cron_stale:' || v_stale.jobname and s.last_alerted_at > now() - interval '24 hours') then
      continue;
    end if;
    v_detail := v_detail || 'cron ' || v_stale.jobname || ' has NOT FIRED: ' || v_stale.why || E'\n';
    v_alerts := v_alerts + 1;
    update public.alert_signature set last_alerted_at = now() where watcher = 'failed_runs' and signature = 'cron_stale:' || v_stale.jobname;
  end loop;

  -- A SIGNATURE RESOLVES ON MERIT, NOT ON THE CLOCK (5 Sep 2026). The red view carried a watcher
  -- episode for 24 h after the last sighting whatever the subject did next. kb_embed had run
  -- 'ok' 83 times after its last error and dr_drill 4 times, and both stayed red; monthly_report was
  -- listed stale every hour and paged every day because v_cron_stale read '0 7 1 * *' as daily.
  -- Two rules, both measured from the subject's own ledger:
  --   failed-run signature  -> resolved when the agent has a status='ok' run started AFTER the
  --                            watcher last saw the failure (last_seen_at). A later failure re-opens
  --                            it through the upsert above (resolved_at = null), which the red view
  --                            then treats as a NEW episode and pages again.
  --   cron_stale signature  -> resolved when the job is no longer listed by v_cron_stale on this
  --                            pass, i.e. a run of any status has been recorded since.
  update public.alert_signature s
     set resolved_at = now()
   where s.watcher = 'failed_runs' and s.resolved_at is null
     and s.signature not like 'cron_stale:%'
     and exists (select 1 from public.agent_runs ok
                  where ok.agent = split_part(s.signature, ':', 1)
                    and ok.status = 'ok' and ok.started_at > s.last_seen_at);
  update public.alert_signature s
     set resolved_at = now()
   where s.watcher = 'failed_runs' and s.resolved_at is null
     and s.signature like 'cron_stale:%'
     and not exists (select 1 from public.v_cron_stale c where 'cron_stale:' || c.jobname = s.signature);

  if v_rehearsal > 0 then
    v_detail := v_detail || E'\n' || v_rehearsal || ' further run(s) failed inside a declared sandbox rehearsal window and were not paged.' || E'\n';
  end if;

  if v_alerts > 0 then
    -- 6 SEP 2026: fn_notify_founder, not an HTTP hop to alert_founder. founder_mail_policy routes this kind
    -- (scheduled_runs_failed) to the IT operations engineer as ONE org_task per condition; it never emails him.
    perform public.fn_notify_founder(
      'Scheduled runs failed (' || v_alerts || ' new condition(s))', v_detail, 'error',
      p_kind => 'scheduled_runs_failed',
      -- Dedupe on the day, not the hour. The hour made the key change every pass, which is why
      -- a dedupe key existed for three weeks and never deduplicated anything.
      p_dedupe_key => 'failed_runs:' || to_char(now(),'YYYY-MM-DD'));
    update alert_watermark set last_alert_at = now() where watcher = 'failed_runs';
  end if;

  update alert_watermark set last_run_at = now() where watcher = 'failed_runs';
  return jsonb_build_object(
    'checked_since', v_since,
    'models_answering', v_models_answering,
    'runs_failed', v_real,
    'runs_held_by_ai_hold', v_held,
    'runs_in_declared_rehearsal', v_rehearsal,
    'crons_stale', v_stale_n,
    'new_conditions_alerted', v_alerts,
    'alerted', v_alerts > 0);
end;
$function$


CREATE OR REPLACE FUNCTION public.fn_what_if(p_question text, p_change jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_sup int; v_rev numeric; v_cost numeric; v_conv numeric; v_pool int;
  v_impact jsonb; v_conf numeric; v_id bigint;
  v_d_rev numeric; v_d_leads numeric; v_d_profit numeric;
begin
  select count(*) into v_sup from leads where approval_status='approved';
  select coalesce(sum(coalesce(reveal_fee,app_fee,0)),0) into v_rev from transactions where revealed_at>now()-interval '30 days';
  select coalesce(sum(cost_aed),0) into v_cost from ai_cost_log where occurred_at>now()-interval '30 days';
  select coalesce(sum(sendable),0) into v_pool from v_supply_gap;
  v_conv := 0.05;

  if p_question ~* 'reveal fee|reduce.*fee|lower.*fee' then
    v_impact := jsonb_build_object('revenue_per_reveal','down by the discount percentage',
      'reveal_volume','unknown - no reveals have occurred, so elasticity is unmeasured',
      'net_revenue','indeterminate',
      'honest_answer','This cannot be simulated. Zero reveals have happened, so there is no price-response curve to extrapolate from. Any number would be invented.');
    v_conf := 0.15;
    -- All three stay NULL on purpose. The branch's own text says the question cannot be simulated,
    -- and a projection of 0 would contradict it.
    v_d_rev := null; v_d_leads := null; v_d_profit := null;

  elsif p_question ~* 'model price|openrouter|ai cost.*double|llm cost' then
    v_impact := jsonb_build_object('current_monthly_ai_cost_aed',round(v_cost,2),'if_doubled_aed',round(v_cost*2,2),
      'share_of_total_budget', round(100.0*v_cost*2/nullif((select sum(monthly_aed) from department_budget),0),1)||'%',
      'mitigation','Model policy already routes by task class. Prompt-cache reads are '
        ||coalesce((select round(100.0*sum(cached_in_tokens)/nullif(sum(prompt_tokens),0),1)::text
                      from ai_cost_log where occurred_at > now() - interval '30 days'),'0')
        ||'% of prompt tokens over 30 days ('
        ||coalesce((select sum(cached_in_tokens)::text from ai_cost_log
                     where occurred_at > now() - interval '30 days'),'0')
        ||' read against '
        ||coalesce((select sum(cache_write_tokens)::text from ai_cost_log
                     where occurred_at > now() - interval '30 days'),'0')
        ||' written at a 1.25x premium), so caching pays only above roughly 22% and is measured here rather than assumed.');
    v_conf := 0.8;
    -- Doubling the AI bill moves cost, not sales: the extra spend lands on profit one-for-one and
    -- the top line is untouched, so revenue is NULL rather than 0 (unmodelled, not unchanged).
    v_d_rev := null; v_d_leads := null; v_d_profit := -round(v_cost,2);

  elsif p_question ~* 'invite|supplier.*onboard|scale.*supplier' then
    v_impact := jsonb_build_object('sendable_pool',v_pool,'expected_approved_at_5pct',round(v_pool*v_conv),
      'target',860,'shortfall',greatest(0,860-round(v_pool*v_conv)),
      'note','Assumes a 5% invite-to-approved conversion, which is an assumption not an observation - no invite has converted yet.');
    v_conf := 0.45;
    -- Supply-side leads are the only dimension this branch models, and it says out loud that the
    -- 5% is an assumption. Revenue would need a conversion rate nobody has observed.
    v_d_rev := null; v_d_leads := round(v_pool*v_conv); v_d_profit := null;

  elsif p_question ~* 'saudi|expand|new market' then
    v_impact := jsonb_build_object('home_market_readiness',(select count(*) from v_supply_gap where approved>=10)||' of 86 categories at target',
      'assessment','Expanding before the home market has any onboarded supply spreads a thin pool thinner and the category knowledge is UAE-specific.');
    v_conf := 0.7;
    v_d_rev := null; v_d_leads := null; v_d_profit := null;
  else
    v_impact := jsonb_build_object('assessment','No model exists for this question yet. Add a scenario to scenario_library so it can be simulated rather than guessed.');
    v_conf := 0.2;
    v_d_rev := null; v_d_leads := null; v_d_profit := null;
  end if;

  -- THE THREE DIMENSIONS THE FOUNDER ASKED FOR, ALWAYS NAMED. Branch-shaped keys like
  -- 'net_revenue' and 'if_doubled_aed' answer the question but cannot be read uniformly across
  -- simulations, so a reader had to know which branch ran before it knew what it was looking at.
  v_impact := v_impact || jsonb_build_object(
    'projected_revenue_delta_aed', v_d_rev,
    'projected_leads_delta',       v_d_leads,
    'projected_profit_delta_aed',  v_d_profit,
    'delta_note', 'A null delta means this scenario does not model that dimension. It does not mean the delta is zero.');

  insert into simulations (scenario, result)
  values (jsonb_build_object('question',p_question,'change',p_change,'confidence',v_conf),
          -- The confidence belongs in the projection the caller reads, not only beside the question
          -- it was asked. coalesce guards the branch that builds it by hand already.
          v_impact || jsonb_build_object('confidence', coalesce((v_impact->>'confidence')::numeric, v_conf)))
  returning id into v_id;

  -- THE SIMULATION LEAVES SOMETHING TO APPROVE. Only when it actually modelled the question:
  -- v_conf is the simulator's own score for the branch it took, and below 0.5 are exactly the
  -- branches whose text says they are guesses ("No model exists for this question yet",
  -- "an assumption not an observation"). Those produce a projection to read and no action to take.
  if v_conf >= 0.5 then
    insert into agent_actions(agent, kind, status, risk, title, recommendation, detail,
                              target_table, target_id, confidence, evidence)
    values ('strategy_director', 'simulation_apply', 'pending', 'medium',
            left('Act on the simulation: ' || p_question, 200),
            coalesce(v_impact->>'assessment',
                     'The simulation returned a projection; open it to see the modelled figures.')
              || ' Approving this accepts the modelled change; the projection and its basis are on '
              || 'simulation #' || v_id || '.',
            jsonb_build_object('simulation_id', v_id, 'question', p_question,
                               'change', p_change, 'projection', v_impact),
            'simulations', v_id::text, v_conf,
            -- The real basis, not the generic stamped one: this rests on the simulation and the
            -- figures it computed, which are the two things a reader would want to check.
            jsonb_build_object('basis', 'simulation #' || v_id || ' of "' || p_question || '"',
                               'simulation_id', v_id, 'confidence', v_conf, 'projection', v_impact));
  end if;

  return jsonb_build_object('id',v_id,'question',p_question,'projection',v_impact,'confidence',v_conf,
    'basis', jsonb_build_object('approved_suppliers',v_sup,'revenue_30d',v_rev,'ai_cost_30d',round(v_cost,2),'sendable_pool',v_pool));
end $function$


CREATE OR REPLACE FUNCTION public.fn_whatsapp_destination(p_role text, p_customer uuid DEFAULT NULL::uuid, p_lead bigint DEFAULT NULL::bigint, p_email text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_opt text; v_wa text; v_at timestamptz;
begin
  if p_role = 'customer' then
    select c.whatsapp_opt, c.whatsapp_phone, c.whatsapp_verified_at into v_opt, v_wa, v_at from public.customers c
     where c.id = p_customer or (p_customer is null and p_email is not null and lower(c.email) = lower(btrim(p_email))) limit 1;
  elsif p_role = 'supplier' then
    select l.whatsapp_opt, l.whatsapp_phone, l.whatsapp_verified_at into v_opt, v_wa, v_at from public.leads l
     where l.id = p_lead or (p_lead is null and p_email is not null and lower(l.claimed_by) = lower(btrim(p_email))) order by l.id limit 1;
  else
    return null;
  end if;
  if v_opt = 'other' and v_at is not null and nullif(btrim(v_wa), '') is not null then return v_wa; end if;
  if v_opt = 'same' then return public.fn_verified_mobile(p_role, p_customer, p_lead, p_email); end if;
  return null;   -- 'none', unanswered, or an 'other' number not yet verified
end $function$


CREATE OR REPLACE FUNCTION public.fn_whatsapp_owner(p_phone text, p_all boolean DEFAULT false)
 RETURNS TABLE(party_kind text, customer_id uuid, lead_id bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with t as (select right(regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g'), 9) as tail),
  hits as (
    select 'customer'::text as party_kind, c.id as customer_id, null::bigint as lead_id
      from public.customers c, t
     where length(t.tail) = 9
       and ((c.whatsapp_opt = 'other' and c.whatsapp_verified_at is not null
             and right(regexp_replace(coalesce(c.whatsapp_phone, ''), '[^0-9]', '', 'g'), 9) = t.tail)
         or (c.whatsapp_opt = 'same' and coalesce(c.phone_verified, false)
             and right(regexp_replace(coalesce(c.phone, ''), '[^0-9]', '', 'g'), 9) = t.tail))
    union
    select 'supplier', null, l.id
      from public.leads l, t
     where length(t.tail) = 9
       -- 18 Sep 2026, founder instruction 516: a confirmed sanctions ban means the handset names
       -- nobody. WhatsApp is the one channel with no session to refuse.
       and not exists (select 1 from public.sanctions_ban b where b.lead_id = l.id)
       and ((l.whatsapp_opt = 'other' and l.whatsapp_verified_at is not null
             and right(regexp_replace(coalesce(l.whatsapp_phone, ''), '[^0-9]', '', 'g'), 9) = t.tail)
         or (l.whatsapp_opt = 'same' and coalesce(l.owner_phone_verified, false)
             and right(regexp_replace(coalesce(l.phone, ''), '[^0-9]', '', 'g'), 9) = t.tail)))
  -- A PHONE MAY CONFIRM, NEVER SELECT: one party or nobody.
  select h.party_kind, h.customer_id, h.lead_id from hits h where p_all or (select count(*) from hits) = 1
$function$


CREATE OR REPLACE FUNCTION public.fn_workflow_actor_resolve(p_run uuid, p_actor text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_ctx jsonb; v_owner text; v_live text; v_tid bigint;
begin
  if p_actor is null or btrim(p_actor) = '' then return null; end if;

  if lower(btrim(p_actor)) not in ('owner', 'director', 'dept_head', 'department head') then
    return public.fn_org_agent_resolve(p_actor);
  end if;

  select r.context into v_ctx from public.workflow_run r where r.id = p_run;
  if v_ctx is null then return null; end if;

  -- The owner is the assignee of the task this run was raised for. employee_task runs carry
  -- context.task_id; the guard on the cast is there because context is free-form jsonb and a
  -- non-numeric task_id would abort the whole planning statement rather than skip one step.
  if coalesce(v_ctx->>'task_id','') ~ '^[0-9]+$' then
    v_tid := (v_ctx->>'task_id')::bigint;
    select t.assigned_agent into v_owner from public.org_tasks t where t.id = v_tid;
  end if;
  if v_owner is null then v_owner := nullif(v_ctx->>'agent',''); end if;
  if v_owner is null then v_owner := public.fn_org_agent_resolve(nullif(v_ctx->>'dept_key','')); end if;

  select o.agent_key into v_live from public.org_agents o where o.agent_key = v_owner and o.active;
  if v_live is null then return null; end if;

  if lower(btrim(p_actor)) = 'owner' then return v_live; end if;

  -- 'Director' on employee_task step 10 is "department head review" - the owner's own manager,
  -- which org_agents.manager_key already models for 93 of 94 employees, acyclically.
  -- The owner's active manager is the department head. If the owner has no active manager (only the
  -- ceo, the top of the org), the owner is its own department head, so 'Director' never resolves to
  -- no employee and never stalls a run at step 10.
  return coalesce(
    (select m.agent_key
       from public.org_agents o
       join public.org_agents m on m.agent_key = o.manager_key and m.active
      where o.agent_key = v_live),
    v_live);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_workflow_run_follow_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_run uuid; v_run_status text;
begin
  if new.status is not distinct from old.status then return new; end if;
  if new.status not in ('done','failed','escalated','cancelled') then return new; end if;

  v_run_status := case when new.status = 'done' then 'done'
                       when new.status = 'cancelled' then 'cancelled'
                       else 'failed' end;

  for v_run in
    select r.id from public.workflow_run r
     where r.workflow_key = 'employee_task'
       and r.status = 'running'
       and (r.context->>'task_id') = new.id::text
  loop
    update public.workflow_step_run
       set status = 'skipped', finished_at = now(),
           output = coalesce(output, '{}'::jsonb) || jsonb_build_object(
             'closed_by', 'owning_org_task', 'org_task_id', new.id,
             'org_task_status', new.status,
             'used_llm', case when (new.result->>'used_llm') in ('true','false') then (new.result->>'used_llm')::boolean else null end,
             'note', case when new.status = 'cancelled'
                          then 'the owning task was cancelled; this step was never separately observed, so it is skipped rather than claimed as done'
                          else 'the owning task was performed and reviewed as one act; this step was never '
                            || 'separately observed, so it is skipped rather than claimed as done' end)
     where workflow_run_id = v_run and finished_at is null;

    update public.workflow_run
       set status      = v_run_status,
           finished_at = now(),
           updated_at  = now(),
           context     = coalesce(context,'{}'::jsonb)
                         || jsonb_build_object('closed_by','owning_org_task',
                                               'org_task_status', new.status,
                                               'used_llm', case when (new.result->>'used_llm') in ('true','false') then (new.result->>'used_llm')::boolean else null end),
           error       = case when new.status = 'done' then null
                              else jsonb_build_object('owning_org_task', new.id,
                                                      'org_task_status', new.status,
                                                      'reason', case when new.status = 'cancelled' then 'the owning org_task was cancelled' else 'the owning org_task ended ' || new.status end) end
     where id = v_run;
  end loop;
  return new;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_workflow_start(p_workflow_key text, p_trigger_event_id bigint DEFAULT NULL::bigint, p_entity_type text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_context jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_run uuid; v_key text; v_corr uuid; v_first int;
begin
  if not exists (select 1 from workflow w where w.workflow_key = p_workflow_key and coalesce(w.active,true))
    then return null; end if;

  -- One run per (workflow, triggering event). Without the event there is nothing to be idempotent
  -- against, so a manual start gets its own key rather than silently colliding with the last one.
  v_key := p_workflow_key || ':' || coalesce(p_trigger_event_id::text, gen_random_uuid()::text);

  select e.correlation_id into v_corr from company_event e where e.id = p_trigger_event_id;
  -- 4 SEP 2026: a run started WITHOUT a triggering event begins its own correlation.
  -- The line above finds nothing when p_trigger_event_id is null, workflow_run.correlation_id is
  -- NOT NULL, and the insert below therefore raised 23502 on every eventless start. The line before
  -- it already anticipates exactly this case -- it mints a fresh idempotency key rather than
  -- colliding -- so the omission was in the next statement, not in the design.
  --
  -- It is the reason MASTER_PLAN 4.3's one-spine design never ran: fn_org_task_promote is the leg
  -- that lifts an org_task onto the workflow spine, it calls this with a null event because a
  -- backlog task has no event, every call raised, and the promoter's own
  -- `exception when others then null` swallowed it. Measured: 0 of 301 employee_task runs ever
  -- created carry promoted_by = fn_org_task_promote, and the raise reproduces on any backlog task.
  -- Correlation ties together work that shares a cause; a promoted task IS its own cause.
  v_corr := coalesce(v_corr, gen_random_uuid());

  insert into workflow_run (workflow_key, trigger_event_id, correlation_id, entity_type, entity_id,
                            idempotency_key, status, current_step, context, started_at)
  values (p_workflow_key, p_trigger_event_id, v_corr, p_entity_type, p_entity_id,
          v_key, 'running', 0, coalesce(p_context,'{}'::jsonb), now())
  on conflict (idempotency_key) do nothing
  returning id into v_run;

  if v_run is null then
    select id into v_run from workflow_run where idempotency_key = v_key;
    return v_run;                      -- already started; nothing to re-plan
  end if;

  -- Plan every step of the workflow up front. A run whose steps are only materialised as they are
  -- reached cannot be read as "where is this piece of work", which is the entire value of the table.
  --
  -- THE ACTOR IS RESOLVED HERE (11 Aug 2026). It used to copy workflow_step.actor_role verbatim,
  -- and actor_role is not one namespace - see the header. Resolving in the dispatcher instead
  -- would leave the stored row still addressed to nobody, which is the defect this codebase keeps
  -- reproducing. addressed_as keeps the original wording so no reassignment is silent.
  insert into workflow_step_run (workflow_run_id, step_no, actor, action_class, status,
                                 input, idempotency_key)
  select v_run, s.step_no, coalesce(x.resolved, s.actor_role), s.action_class, 'queued',
         jsonb_build_object('step', s.step, 'gate', s.gate)
           || case when x.resolved is not null and x.resolved is distinct from s.actor_role
                   then jsonb_build_object('addressed_as', s.actor_role)
                   else '{}'::jsonb end,
         v_key || '#' || s.step_no
    from workflow_step s
    cross join lateral (select public.fn_workflow_actor_resolve(v_run, s.actor_role) as resolved) x
   where s.workflow_key = p_workflow_key
   order by s.step_no
  on conflict (idempotency_key) do nothing;

  select min(step_no) into v_first from workflow_step_run where workflow_run_id = v_run;
  if v_first is null then
    -- A workflow with no steps cannot be in flight. Closing it here stops it sitting in the
    -- in-flight list forever pretending to be work.
    update workflow_run set status = 'done', finished_at = now(), updated_at = now()
     where id = v_run;
    return v_run;
  end if;

  update workflow_step_run set status = 'ready', started_at = now()
   where workflow_run_id = v_run and step_no = v_first;
  update workflow_run set current_step = v_first, updated_at = now() where id = v_run;
  return v_run;
end $function$


CREATE OR REPLACE FUNCTION public.fn_workflow_start_due(p_lookback_minutes integer DEFAULT 1440)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n int := 0;
begin
  for r in
    select w.workflow_key, e.id, e.event_type, e.payload
      from company_event e
      join workflow w on w.trigger_event = e.event_type and coalesce(w.active,true)
     where p_lookback_minutes = 0
        or e.occurred_at > now() - make_interval(mins => p_lookback_minutes)
     order by e.id
     limit 200
  loop
    if not exists (select 1 from workflow_run x
                    where x.idempotency_key = r.workflow_key || ':' || r.id::text) then
      perform public.fn_workflow_start(r.workflow_key, r.id, 'company_event', r.id::text,
                                       coalesce(r.payload,'{}'::jsonb));
      n := n + 1;
    end if;
  end loop;
  return n;
end $function$


CREATE OR REPLACE FUNCTION public.fn_workflow_step_claim(p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_out jsonb; v_today int; v_cap int; v_demand_ready int; v_held boolean;
begin
  v_held := coalesce((public.fn_kernel_paid_provider_gate('anthropic/claude-sonnet-5')->>'allowed')::boolean, false) = false;

  update public.workflow_step_run sr
     set status = 'ready'
   where sr.status = 'running'
     and sr.finished_at is null
     and sr.started_at < now() - interval '15 minutes'
     and not exists (select 1 from public.action_execution x
                      where x.workflow_step_run_id = sr.id
                        and x.status in ('queued','running','succeeded'));

  select coalesce((value #>> '{}')::int, 6) into v_cap
    from public.decision_policy where key = 'workflow_reflection_steps_per_day';
  v_cap := coalesce(v_cap, 6);

  -- NON-DEMAND ONLY, and MODEL WORK ONLY: the ceiling exists to bound paid reasoning. A deterministic
  -- determination costs nothing and is not counted against it.
  select count(*) into v_today
    from public.workflow_step_run sr
   where sr.output->>'worked_by' = 'workflow_dispatch'
     and coalesce(sr.output->>'used_llm', 'true') <> 'false'
     and sr.finished_at >= date_trunc('day', now() at time zone 'utc') at time zone 'utc'
     and not public.fn_task_is_demand(sr.action_class);

  select count(*) into v_demand_ready
    from public.workflow_step_run sr
    join public.workflow_run r on r.id = sr.workflow_run_id
   where sr.status = 'ready'
     and sr.finished_at is null
     and r.status = 'running'
     and r.workflow_key <> 'employee_task'
     and coalesce(sr.input->>'gate','') <> 'founder'
     and public.fn_task_is_demand(sr.action_class)
     and public.fn_workflow_actor_resolve(sr.workflow_run_id, sr.actor) is not null
     and not exists (
           select 1 from public.org_action_executor e
            where e.action_class = sr.action_class and e.active and e.kind in ('edge','rpc')
              and e.risk_tier = 'low' and e.advisory_safe and e.reversible
              and not e.notifies_human
              and coalesce(e.required_authority,'') <> 'founder');

  if not v_held and v_today >= v_cap and v_demand_ready = 0 then
    return jsonb_build_object('capped', true, 'worked_today', v_today, 'cap', v_cap,
             'demand_ready', 0,
             'note', 'the daily reflection ceiling is spent and no revenue-path step is waiting; see '
                     || 'scripts/sql/the_dispatchers_ceiling_counted_revenue_work_against_reflection.sql');
  end if;

  with pick as (
    select sr.id
      from public.workflow_step_run sr
      join public.workflow_run r on r.id = sr.workflow_run_id
     where sr.status = 'ready'
       and sr.finished_at is null
       and r.status = 'running'
       -- THE ORG_TASK LANE (§4.3). An employee_task run is the promotion of one org_task into the
       -- spine; the dispatcher works it while the task is still open, and the follow trigger owns it
       -- once the task has closed or parked. A run whose task is gone is nobody's work.
       and (r.workflow_key <> 'employee_task'
            or exists (select 1 from public.org_tasks t
                        where t.id::text = r.context->>'task_id'
                          and t.status in ('assigned','in_progress')))
       and coalesce(sr.input->>'gate','') <> 'founder'
       -- the reflection ceiling is untouched: it bounds PAID reasoning, and while the model is held
       -- (v_held) nothing here can reach a paid provider. When the hold lifts the lane obeys it.
       and (public.fn_task_is_demand(sr.action_class) or v_today < v_cap or v_held)
       and public.fn_workflow_actor_resolve(sr.workflow_run_id, sr.actor) is not null
       -- parked awaiting the model: not claimed again until the hold lifts
       and not (v_held and coalesce(sr.error->>'disposition','') = 'awaiting_model')
       and (
         -- the org_task lane is always the dispatcher's: its executor (cos_execute on coordinate) was
         -- retired on 3 Sep and the sweep's low-risk predicate never accepted it
         r.workflow_key = 'employee_task'
         -- (a) no safe executor owns it: the dispatcher's row, as before
         or not exists (
             select 1 from public.org_action_executor e
              where e.action_class = sr.action_class and e.active and e.kind in ('edge','rpc')
                and e.risk_tier = 'low' and e.advisory_safe and e.reversible
                and not e.notifies_human
                and coalesce(e.required_authority,'') <> 'founder')
         -- (b) the model is held and the safe executor cannot finish it: it runs on the model, or it
         --     already left only terminal (held/cancelled/stalled) executions behind
         or (v_held and (
               exists (select 1 from public.org_action_executor e
                        where e.action_class = sr.action_class and e.active
                          and public.fn_executor_needs_model(e.target))
            -- stranded: parked held/stalled, or cancelled on a REFUSAL or a missing decision record.
            -- (A never-dispatched cancel is the sweep's to re-queue, not the dispatcher's.)
            or (exists (select 1 from public.action_execution x
                         where x.workflow_step_run_id = sr.id
                           and (x.status in ('held','stalled')
                                or (x.status = 'cancelled'
                                    and (x.response->>'invoker' = 'refused' or (x.request ? 'decision_record_id')))))
                and not exists (select 1 from public.action_execution x
                                 where x.workflow_step_run_id = sr.id
                                   and x.status in ('queued','running','succeeded')))))
       )
     -- fresh steps before retries: 24 change_deployment step-1 retries (3 attempts each before they
     -- park) must not starve a step that has never been looked at
     order by coalesce(sr.attempts, 0), sr.id
     limit greatest(least(coalesce(p_limit, 5),
                          case when v_held then coalesce(p_limit, 5)
                               else greatest(v_cap - v_today, 0) + v_demand_ready end), 1)
     for update of sr skip locked
  ), claimed as (
    update public.workflow_step_run sr
       set status = 'running', started_at = now()
      from pick
     where sr.id = pick.id
    returning sr.id, sr.workflow_run_id, sr.step_no, sr.actor, sr.action_class, sr.input, sr.attempts, sr.error
  )
  select coalesce(jsonb_agg(jsonb_build_object(
           'step_run_id',  c.id,
           'run_id',       c.workflow_run_id,
           'step_no',      c.step_no,
           'employee',     public.fn_workflow_actor_resolve(c.workflow_run_id, c.actor),
           'addressed_as', coalesce(c.input->>'addressed_as', c.actor),
           'action_class', c.action_class,
           'step',         c.input->>'step',
           'gate',         c.input->>'gate',
           'workflow_key', r.workflow_key,
           'workflow',     w.name,
           'context',      r.context,
           'attempts',     coalesce(c.attempts, 0),
           'model_held',   v_held,
           'deterministic_only', v_held,
           -- THE ORG_TASK LANE: the work is the task, not the loop step it is recorded under.
           'lane',                 case when r.workflow_key = 'employee_task' and t.id is not null then 'org_task' else 'workflow_step' end,
           'org_task_id',           t.id,
           'org_task_title',        t.title,
           'org_task_detail',       left(coalesce(t.detail, ''), 2000),
           'org_task_dept',         t.dept_key,
           'org_task_action_class', t.action_class,
           'org_task_subject',      case when t.id is null then null
                                         else public.fn_org_task_subject(t.title, t.action_class, t.dept_key) end,
           'stranded_reason', case
              when exists (select 1 from public.org_action_executor e
                            where e.action_class = c.action_class and e.active and e.kind in ('edge','rpc')
                              and e.risk_tier = 'low' and e.advisory_safe and e.reversible
                              and not e.notifies_human)
               then coalesce((select 'executor ' || coalesce(x.executor, e2.target) || ' left status=' || x.status
                                     || coalesce(' (' || (x.response->>'reason') || ')', '')
                                from public.action_execution x
                                join public.org_action_executor e2 on e2.action_class = c.action_class and e2.active
                               where x.workflow_step_run_id = c.id
                               order by x.created_at desc limit 1),
                             'executor runs on the held paid model; not queued')
              else null end,
           'prior_steps', (select coalesce(jsonb_agg(jsonb_build_object(
                                    'step_no', p.step_no,
                                    'step',    p.input->>'step',
                                    'by',      coalesce(p.output->>'employee', p.actor),
                                    'outcome', left(coalesce(p.output->>'outcome',
                                                             p.output->>'note', ''), 600))
                                  order by p.step_no), '[]'::jsonb)
                             from (select p2.* from public.workflow_step_run p2
                                    where p2.workflow_run_id = c.workflow_run_id
                                      and p2.step_no < c.step_no
                                      and p2.status = 'done'
                                      and coalesce(p2.output->>'outcome', p2.output->>'note','') <> ''
                                    order by p2.step_no desc
                                    limit 3) p)
         ) order by c.id), '[]'::jsonb)
    into v_out
    from claimed c
    join public.workflow_run r on r.id = c.workflow_run_id
    left join public.workflow w on w.workflow_key = r.workflow_key
    left join public.org_tasks t on r.workflow_key = 'employee_task'
                                and t.id::text = r.context->>'task_id';

  return v_out;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_workflow_step_deterministic_done(p_step_run_id bigint, p_output jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  sr           record;
  v_sim        numeric;
  v_floor      numeric := 0.85;
  v_terms      int;
  v_employee   text;
  v_dept       text;
  v_trace      uuid;
  v_review     bigint;
  v_superseded int := 0;
  v_res        text;
  v_out        jsonb;
  -- the record applied
  v_pb_id text; v_pb_title text; v_pb_type text; v_pb_content text; v_pb_sd jsonb;
  -- facts + rendering
  v_facts jsonb; v_bound int; v_deliv text; v_outcome text;
  -- executor
  ex record; v_has_ex boolean := false; v_needs_model boolean := false; v_exec_status text; v_exec_id uuid;
  v_exec_result jsonb; v_req_args int; v_kind text := null; v_source text := 'playbook_rendered';
  v_queued boolean := false; v_refused text; v_err text; v_target text;
  -- measurement
  v_llm int := 0; v_cost int := 0; v_used_llm boolean;
  v_disp text; v_mode text;
begin
  select s.id, s.workflow_run_id, s.step_no, s.actor, s.action_class, s.input, s.attempts, s.started_at, s.output as prev_output,
         r.workflow_key, r.context, r.correlation_id, r.trigger_event_id
    into sr
    from public.workflow_step_run s
    join public.workflow_run r on r.id = s.workflow_run_id
   where s.id = p_step_run_id and s.status = 'running' and s.finished_at is null;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'step is not held running by a dispatcher');
  end if;

  v_sim      := nullif(p_output->>'similarity', '')::numeric;
  v_terms    := nullif(p_output->>'terms_matched', '')::int;
  v_employee := coalesce(nullif(p_output->>'employee',''), sr.actor);

  -- FALSE-SUCCESS GUARDS. Nothing below runs unless the determination has substance. The floors are the
  -- applier's own (0.85 cosine AND keyword corroboration), so a caller cannot pass on cosine alone.
  if coalesce(p_output->>'playbook_record_id','') = '' then
    return jsonb_build_object('ok', false, 'reason', 'no playbook_record_id: a determination must cite the company knowledge it applied');
  end if;
  if v_sim is null or v_sim < v_floor then
    return jsonb_build_object('ok', false, 'reason', 'similarity ' || coalesce(v_sim::text,'null') || ' is below the apply floor ' || v_floor);
  end if;
  if v_terms is null or v_terms < 2 then
    return jsonb_build_object('ok', false, 'reason', 'terms_matched ' || coalesce(v_terms::text,'null') || ' is below the corroboration floor of 2 step terms');
  end if;
  select k.record_id, k.title, k.record_type, k.content, k.structured_data
    into v_pb_id, v_pb_title, v_pb_type, v_pb_content, v_pb_sd
    from public.ops_knowledge k
   where k.record_id = p_output->>'playbook_record_id' and k.runtime_eligible;
  if v_pb_id is null then
    return jsonb_build_object('ok', false, 'reason', 'playbook ' || (p_output->>'playbook_record_id') || ' is not a runtime-eligible ops_knowledge record');
  end if;
  if v_pb_type not in ('decision_playbook','decision_rule','standard_operating_procedure','exception_playbook') then
    return jsonb_build_object('ok', false, 'reason', 'record ' || v_pb_id || ' is a ' || v_pb_type || ', not an actionable kind');
  end if;

  -- THE FACTS, then the deliverable AS A FUNCTION OF THEM.
  v_facts := public.fn_workflow_step_facts(sr.id);
  v_bound := coalesce((v_facts->>'facts_bound')::int, 0);

  -- THE EXECUTOR. Read the registry row and decide from it, in words.
  select e.action_class, e.kind, e.target, e.active, e.risk_tier, e.advisory_safe, e.reversible,
         e.notifies_human, e.unattended_ok, e.required_authority, e.compensation_action_class
    into ex
    from public.org_action_executor e
   where e.action_class = sr.action_class and e.active
   order by e.kind limit 1;
  v_has_ex := found;
  if v_has_ex then v_target := ex.target; end if;
  if not v_has_ex then
    v_exec_status := 'none: no active executor is mapped to action_class ' || coalesce(sr.action_class, '(null)');
  else
    v_kind := ex.kind;
    v_needs_model := public.fn_executor_needs_model(ex.target);
    if v_needs_model then
      v_exec_status := 'held: ' || ex.target || ' is routed to a model task class by fn_task_class and the paid provider is held; not invoked';
    elsif coalesce(ex.required_authority, '') = 'founder' then
      v_exec_status := 'withheld: ' || ex.target || ' is reserved to the founder';
    elsif ex.notifies_human then
      v_exec_status := 'withheld: ' || ex.target || ' notifies a human (org_action_executor.notifies_human); the deterministic close never sends';
    elsif not (ex.risk_tier = 'low' and ex.advisory_safe and ex.reversible) then
      v_exec_status := format('withheld: %s is risk_tier=%s advisory_safe=%s reversible=%s; the close invokes low/advisory_safe/reversible only',
                              ex.target, ex.risk_tier, ex.advisory_safe, ex.reversible);
    elsif ex.kind not in ('rpc', 'edge') then
      v_exec_status := 'withheld: ' || ex.target || ' is a ' || ex.kind || ' executor and no invoker handles that kind';
    elsif exists (select 1 from public.action_execution x where x.workflow_step_run_id = sr.id and x.status in ('queued','running')) then
      return jsonb_build_object('ok', false, 'reason', 'executor ' || ex.target || ' is already queued or running for this step; the sweep settles it');
    elsif ex.kind = 'rpc' then
      select coalesce(p.pronargs - p.pronargdefaults, -1) into v_req_args
        from pg_proc p where p.proname = ex.target and p.pronamespace = 'public'::regnamespace
       order by p.pronargs limit 1;
      if v_req_args is null then
        v_exec_status := 'failed: public.' || ex.target || '() does not exist';
      elsif v_req_args > 0 then
        v_exec_status := 'withheld: public.' || ex.target || '() requires ' || v_req_args || ' argument(s) a workflow step cannot supply';
      else
        v_exec_id := gen_random_uuid();
        begin
          execute format('select coalesce(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) from public.%I() t', ex.target) into v_exec_result;
          insert into public.action_execution(id, correlation_id, workflow_step_run_id, action_class, executor, idempotency_key,
                                              risk_tier, reversible, request, response, status, attempts, started_at, finished_at)
          values (v_exec_id, coalesce(sr.correlation_id, gen_random_uuid()), sr.id, sr.action_class, ex.target,
                  'workflow_step:' || sr.id || ':det:' || to_char(now(), 'YYYYMMDDHH24MISSMS'),
                  ex.risk_tier, ex.reversible,
                  jsonb_build_object('workflow_step_run_id', sr.id, 'workflow_run_id', sr.workflow_run_id, 'step_no', sr.step_no,
                                     'actor', sr.actor, 'source', 'fn_workflow_step_deterministic_done', 'kind', 'rpc'),
                  jsonb_build_object('invoker', 'succeeded', 'at', now(), 'kind', 'rpc', 'inline', true,
                                     'result_rows', coalesce(jsonb_array_length(v_exec_result), 0),
                                     'result', case when pg_column_size(v_exec_result) > 20000 then to_jsonb(left(v_exec_result::text, 20000)) else v_exec_result end),
                  'succeeded', 1, now(), now());
          v_exec_status := 'ran: public.' || ex.target || '() inline, ' || coalesce(jsonb_array_length(v_exec_result), 0)
                           || ' row(s), action_execution ' || v_exec_id;
          v_source := 'executor:' || ex.target;
        exception when others then
          v_err := sqlstate || ' ' || left(sqlerrm, 400);
          -- the failure is a fact: record it and refuse the close, so the step is released with the reason
          insert into public.action_execution(id, correlation_id, workflow_step_run_id, action_class, executor, idempotency_key,
                                              risk_tier, reversible, request, response, status, attempts, started_at, finished_at)
          values (v_exec_id, coalesce(sr.correlation_id, gen_random_uuid()), sr.id, sr.action_class, ex.target,
                  'workflow_step:' || sr.id || ':det:' || to_char(now(), 'YYYYMMDDHH24MISSMS'),
                  ex.risk_tier, ex.reversible,
                  jsonb_build_object('workflow_step_run_id', sr.id, 'workflow_run_id', sr.workflow_run_id, 'step_no', sr.step_no,
                                     'actor', sr.actor, 'source', 'fn_workflow_step_deterministic_done', 'kind', 'rpc'),
                  jsonb_build_object('invoker', 'failed', 'at', now(), 'kind', 'rpc', 'inline', true, 'error', v_err),
                  'failed', 1, now(), now());
          return jsonb_build_object('ok', false, 'reason', 'executor public.' || ex.target || '() failed: ' || v_err,
                                    'action_execution_id', v_exec_id);
        end;
      end if;
    else -- edge, deterministic
      select x.response->>'reason' into v_refused
        from public.action_execution x
       where x.workflow_step_run_id = sr.id and x.response->>'invoker' = 'refused'
       order by x.created_at desc limit 1;
      if v_refused is not null then
        v_exec_status := 'withheld: the invoker refused ' || ex.target || ' for this step earlier (' || left(v_refused, 200) || '); not re-queued';
      elsif exists (select 1 from public.action_execution x
                     where x.workflow_step_run_id = sr.id and x.request->>'source' = 'fn_workflow_step_deterministic_done') then
        select 'withheld: an earlier re-queue of ' || ex.target || ' for this step ended ' || x.status into v_exec_status
          from public.action_execution x
         where x.workflow_step_run_id = sr.id and x.request->>'source' = 'fn_workflow_step_deterministic_done'
         order by x.created_at desc limit 1;
      else
        v_exec_id := gen_random_uuid();
        insert into public.action_execution(id, correlation_id, workflow_step_run_id, action_class, executor, idempotency_key,
                                            risk_tier, reversible, request, status, attempts)
        values (v_exec_id, coalesce(sr.correlation_id, gen_random_uuid()), sr.id, sr.action_class, ex.target,
                'workflow_step:' || sr.id || ':det:' || to_char(now(), 'YYYYMMDDHH24MISSMS'),
                ex.risk_tier, ex.reversible,
                jsonb_build_object('workflow_step_run_id', sr.id, 'workflow_run_id', sr.workflow_run_id, 'step_no', sr.step_no,
                                   'actor', sr.actor, 'input', coalesce(sr.input, '{}'::jsonb),
                                   'source', 'fn_workflow_step_deterministic_done', 'kind', 'edge'),
                'queued', 0);
        v_queued := true;
        v_exec_status := 'queued: ' || ex.target || ' as action_execution ' || v_exec_id || ' for the HTTP invoker; the step closes when the sweep settles it';
        v_source := 'executor:' || ex.target;
      end if;
    end if;
  end if;

  -- THE DELIVERABLE, rendered from the facts, with the executor line.
  v_deliv := public.fn_workflow_step_render(v_facts, v_pb_title, v_pb_type, v_pb_content, v_pb_sd);
  v_deliv := regexp_replace(v_deliv, E'\nAPPLIED RECORD: ',
               E'- executor: ' || coalesce(v_exec_status, '?') || E'\n\nAPPLIED RECORD: ');

  -- THE DISPOSITION, earned.
  -- 5 SEP 2026, from the skeptic that audited this routine: 'determined' used to mean "not routed
  -- to a model", and both rows that carried it had executed nothing (executor withheld). A label
  -- that reads as 'executed' must be EARNED by an execution: an action_execution this close created
  -- and which succeeded. Facts bound and rendered, but no executor ran (none mapped, withheld,
  -- queued for the HTTP invoker, refused) is 'rendered' -- true, and not the same word as done.
  v_disp := case when v_bound = 0 then 'needs_narrative'
                 when v_needs_model then 'advisory_held_model'
                 when v_exec_id is not null and exists (select 1 from public.action_execution x
                        where x.id = v_exec_id and x.status = 'succeeded') then 'determined'
                 else 'rendered' end;
  v_mode := case when v_disp = 'determined' then 'determined' else 'advisory' end;
  v_outcome := case when v_disp = 'needs_narrative'
                    then 'No fact was bound for this step (no metric, goal, event payload or prior conclusion); the record "'
                         || v_pb_title || '" applies as written and the step needs narrative from a reviewer or the model path.'
                    else coalesce(nullif(v_facts#>>'{derived,band}', '') || ' ' || coalesce(v_facts#>>'{metric,label}', '') || ': ', '')
                         || 'applied ' || v_pb_type || ' "' || v_pb_title || '" to ' || v_bound || ' bound fact(s)'
                         || case when v_facts#>>'{derived,cause}' is not null then '; cause ' || (v_facts#>>'{derived,cause}') else '' end
                         || '; executor ' || split_part(coalesce(v_exec_status, 'none'), ':', 1) end;

  -- used_llm IS A MEASUREMENT: the provider ledgers since the dispatcher claimed this step.
  select count(*) into v_llm  from public.llm_attempt a where a.fn = 'workflow_dispatch' and a.created_at >= sr.started_at;
  select count(*) into v_cost from public.ai_cost_log c where c.fn = 'workflow_dispatch' and c.occurred_at >= sr.started_at;
  v_used_llm := (v_llm + v_cost) > 0;

  select o.department into v_dept from public.org_agents o where o.agent_key = v_employee;

  -- The sealed record of what was decided, on what, by which rule, with what confidence.
  insert into public.decision_trace(
      correlation_id, causation_event_id, entity_type, entity_id, decision_type,
      proposed_by, decided_by, policy_keys, knowledge_refs, evidence_refs, alternatives,
      assumptions, risk, confidence, authority_result,
      decision, outcome_status, agent_key, department_id, task_class,
      knowledge_versions, source_freshness, tools_requested, tools_executed, tool_result_refs,
      uncertainty, escalation_decision, proposed_action, expected_outcome,
      model, provider, input_tokens, output_tokens, estimated_cost_aed, final_status, sealed_at)
  values (
      coalesce(sr.correlation_id, gen_random_uuid()), sr.trigger_event_id,
      'workflow_step_run', sr.id::text, 'deterministic_playbook_application',
      v_employee, 'fn_workflow_step_deterministic_done', array['deterministic_first']::text[],
      jsonb_build_array(jsonb_build_object('record_id', v_pb_id, 'title', v_pb_title, 'record_type', v_pb_type,
                                           'similarity', v_sim, 'terms_matched', v_terms)),
      jsonb_build_array(jsonb_build_object('workflow_run_id', sr.workflow_run_id, 'workflow_key', sr.workflow_key,
                                           'step_no', sr.step_no, 'step', sr.input->>'step',
                                           'facts', v_facts)),
      coalesce(p_output->'candidates', '[]'::jsonb),
      jsonb_build_array('the corroborated nearest actionable company record is the applicable one for this step',
                        'the facts read at close time are the facts the step is about'),
      jsonb_build_object('level', 'low', 'note', case when v_source like 'executor:%'
                                                      then 'a low-risk, advisory-safe, reversible executor was invoked; moves no money, sends nothing, approves nobody'
                                                      else 'determination only; moves no money, sends nothing, approves nobody' end),
      v_sim,
      jsonb_build_object('mode', v_mode, 'gate', coalesce(sr.input->>'gate', 'none'), 'paid_provider', 'held', 'executor', v_exec_status),
      jsonb_build_object('determination', left(v_deliv, 8000), 'outcome', v_outcome, 'disposition', v_disp,
                         'determination_source', v_source, 'basis', 'facts of the step rendered against the corroborated record; no model call'),
      'pending', v_employee, v_dept, 'workflow_step',
      '{}'::jsonb, jsonb_build_object('ops_knowledge', 'live at decision time', 'facts_read_at', v_facts->>'read_at'),
      case when v_target is not null then array[v_target] else '{}'::text[] end,
      case when v_source like 'executor:%' then array[v_target] else '{}'::text[] end,
      case when v_exec_id is null then '[]'::jsonb else jsonb_build_array(jsonb_build_object('action_execution_id', v_exec_id)) end,
      case v_disp when 'determined' then 'determined from ' || v_bound || ' bound fact(s); queued for review'
                  when 'advisory_held_model' then 'determined from ' || v_bound || ' bound fact(s), but the step''s executor needs the held model; advisory until the hold lifts'
                  else 'no fact bound: the record applies as written; narrative is needed' end,
      'review_queued', 'close the workflow step with disposition ' || v_disp,
      'the run advances; a reviewer can overturn the determination',
      'none', 'deterministic', 0, 0, 0, 'auto_done', now())
  returning id into v_trace;

  -- Never a silent pass: the determination is queued for review, with everything needed to overturn it.
  insert into public.review_queue(kind, dept_key, title, summary, payload, status)
  values ('deterministic_step', v_dept,
          left(initcap(replace(v_disp, '_', ' ')) || ': ' || sr.workflow_key || ' step ' || sr.step_no || ' — ' || coalesce(sr.input->>'step',''), 240),
          left(v_outcome, 600),
          jsonb_build_object('workflow_run_id', sr.workflow_run_id, 'step_run_id', sr.id, 'step_no', sr.step_no,
                             'employee', v_employee, 'playbook_record_id', v_pb_id,
                             'playbook_title', v_pb_title, 'similarity', v_sim, 'terms_matched', v_terms,
                             'decision_trace_id', v_trace, 'disposition', v_disp,
                             'determination_source', v_source, 'executor_status', v_exec_status,
                             'facts_bound', v_bound, 'used_llm', v_used_llm),
          'pending')
  returning id into v_review;

  -- The executor's parked/stranded attempt is superseded: fn_action_release_held must not re-run it at
  -- launch over a step that is already closed.
  update public.action_execution
     set status = 'cancelled', finished_at = coalesce(finished_at, now()),
         response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
           'superseded_at', now(), 'superseded_by', 'deterministic determination',
           'decision_trace_id', v_trace, 'prior_status', status)
   where workflow_step_run_id = sr.id and status in ('held','stalled');
  get diagnostics v_superseded = row_count;

  v_out := coalesce(p_output, '{}'::jsonb) || jsonb_build_object(
             'mode', v_mode,
             'deliverable', left(v_deliv, 20000),
             'outcome', left(v_outcome, 400),
             'disposition', v_disp,
             'determination_source', v_source,
             'executor_status', v_exec_status,
             'executor_kind', v_kind,
             'action_execution_id', v_exec_id,
             'facts_bound', v_bound,
             'facts', v_facts,
             'used_llm', v_used_llm,
             'used_llm_basis', 'measured at close: ' || v_llm || ' llm_attempt + ' || v_cost
                               || ' ai_cost_log row(s) by workflow_dispatch since the step was claimed at ' || sr.started_at,
             'decision_trace_id', v_trace,
             'review_queue_id', v_review,
             'review_status', 'pending',
             'superseded_executions', v_superseded);

  if v_queued then
    -- the step stays running with a queued execution; fn_workflow_step_sweep settles it when the
    -- executor answers, merging the response over this determination
    update public.workflow_step_run set output = v_out where id = sr.id;
    return jsonb_build_object('ok', true, 'advanced', 'awaiting executor ' || v_target, 'decision_trace_id', v_trace,
                              'review_queue_id', v_review, 'superseded_executions', v_superseded,
                              'disposition', v_disp, 'determination_source', v_source,
                              'executor_status', v_exec_status, 'action_execution_id', v_exec_id,
                              'facts_bound', v_bound, 'used_llm', v_used_llm);
  end if;

  v_res := public.fn_workflow_step_done(sr.workflow_run_id, sr.step_no, v_out, 'done');

  return jsonb_build_object('ok', true, 'advanced', v_res, 'decision_trace_id', v_trace,
                            'review_queue_id', v_review, 'superseded_executions', v_superseded,
                            'disposition', v_disp, 'determination_source', v_source,
                            'executor_status', v_exec_status, 'action_execution_id', v_exec_id,
                            'facts_bound', v_bound, 'used_llm', v_used_llm);
end
$function$


CREATE OR REPLACE FUNCTION public.fn_workflow_step_done(p_run uuid, p_step_no integer, p_output jsonb DEFAULT '{}'::jsonb, p_status text DEFAULT 'done'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_next int;
begin
  update workflow_step_run
     set status = p_status, output = coalesce(p_output,'{}'::jsonb), finished_at = now(),
         attempts = coalesce(attempts,0) + 1
   where workflow_run_id = p_run and step_no = p_step_no;
  if not found then return 'no such step'; end if;

  if p_status <> 'done' then
    update workflow_run set status = 'failed', finished_at = now(), updated_at = now(),
           error = jsonb_build_object('failed_step', p_step_no, 'status', p_status)
     where id = p_run;
    return 'failed at step ' || p_step_no;
  end if;

  select min(step_no) into v_next from workflow_step_run
   where workflow_run_id = p_run and step_no > p_step_no and status = 'queued';

  if v_next is null then
    update workflow_run set status = 'done', finished_at = now(), updated_at = now(),
           current_step = p_step_no
     where id = p_run;
    return 'run complete';
  end if;

  update workflow_step_run set status = 'ready', started_at = now()
   where workflow_run_id = p_run and step_no = v_next;
  update workflow_run set current_step = v_next, updated_at = now() where id = p_run;
  return 'advanced to step ' || v_next;
end $function$


CREATE OR REPLACE FUNCTION public.fn_workflow_step_facts(p_step_run_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  -- step + run
  v_step_no int; v_actor text; v_action_class text; v_input jsonb; v_started timestamptz; v_run uuid;
  v_wf text; v_ctx jsonb; v_trigger bigint; v_r_entity_type text; v_r_entity_id text;
  -- event
  v_ev_type text; v_ev_entity_type text; v_ev_entity_id text; v_ev_payload jsonb; v_ev_at timestamptz; v_ev_actor text;
  -- metric
  v_mk text; v_label text; v_owner text; v_val numeric; v_tgt numeric; v_dir text; v_state text; v_err text;
  v_taken timestamptz; v_definition text; v_in_scorecard boolean := false;
  v_hist jsonb; v_consec int := 0; v_ever_met boolean := false; v_n_snap int := 0; snap record; v_off boolean;
  v_metric jsonb := null; v_band text; v_gap numeric; v_att numeric; v_cause text; v_cause_why text;
  -- goals
  v_goals jsonb := null; v_failing jsonb := null; v_prior jsonb := '[]'::jsonb;
  v_bound int := 0; v_derived jsonb := '{}'::jsonb;
begin
  select s.step_no, s.actor, s.action_class, s.input, s.started_at, s.workflow_run_id,
         r.workflow_key, coalesce(r.context, '{}'::jsonb), r.trigger_event_id, r.entity_type, r.entity_id
    into v_step_no, v_actor, v_action_class, v_input, v_started, v_run,
         v_wf, v_ctx, v_trigger, v_r_entity_type, v_r_entity_id
    from public.workflow_step_run s
    join public.workflow_run r on r.id = s.workflow_run_id
   where s.id = p_step_run_id;
  if v_run is null then return null; end if;

  select e.event_type, e.entity_type, e.entity_id, e.payload, e.occurred_at, e.actor
    into v_ev_type, v_ev_entity_type, v_ev_entity_id, v_ev_payload, v_ev_at, v_ev_actor
    from public.company_event e where e.id = v_trigger;
  v_ev_payload := coalesce(v_ev_payload, '{}'::jsonb);

  -- THE METRIC THIS RUN IS ABOUT. Keyed by the event's entity (kpi.missed carries metric_key as
  -- entity_id), else by the context's metric_key, else by the label the emitter wrote.
  v_mk := case when v_ev_entity_type = 'metric' then v_ev_entity_id
               when v_ctx ? 'metric_key' then v_ctx->>'metric_key'
               when v_r_entity_type = 'metric' then v_r_entity_id
               else (select d.metric_key from public.metric_definition d
                      where d.label = coalesce(v_ctx->>'label', v_ev_payload->>'label') limit 1) end;
  -- the emitter's numbers are facts even when the metric is a fixture with no definition row
  v_label := coalesce(v_ctx->>'label', v_ev_payload->>'label');
  v_val   := coalesce(nullif(v_ev_payload->>'value','')::numeric, nullif(v_ctx->>'value','')::numeric);
  v_tgt   := coalesce(nullif(v_ev_payload->>'target','')::numeric, nullif(v_ctx->>'target','')::numeric);
  v_state := coalesce(v_ev_payload->>'state', v_ctx->>'state');
  v_dir   := coalesce(v_ev_payload->>'direction', v_ctx->>'direction');

  if v_mk is not null then
    select sc.label, sc.owner_dept, sc.value, sc.target, sc.direction, sc.state, sc.error, sc.taken_at, sc.definition, true
      into v_label, v_owner, v_val, v_tgt, v_dir, v_state, v_err, v_taken, v_definition, v_in_scorecard
      from public.v_bi_scorecard sc where sc.metric_key = v_mk;
    v_in_scorecard := coalesce(v_in_scorecard, false);
    if not v_in_scorecard then
      -- the scorecard select found nothing and nulled the targets: restore the emitter's numbers
      v_label := coalesce(v_ctx->>'label', v_ev_payload->>'label');
      v_val   := coalesce(nullif(v_ev_payload->>'value','')::numeric, nullif(v_ctx->>'value','')::numeric);
      v_tgt   := coalesce(nullif(v_ev_payload->>'target','')::numeric, nullif(v_ctx->>'target','')::numeric);
      v_state := coalesce(v_ev_payload->>'state', v_ctx->>'state');
      v_dir   := coalesce(v_ev_payload->>'direction', v_ctx->>'direction');
    end if;

    -- snapshot history, newest first, and the leading run of misses — the metric_lifecycle playbooks'
    -- TARGET_MIS_SET test reads ">= 3 consecutive measured periods, never met since the target was set"
    v_hist := '[]'::jsonb;
    for snap in
      select s.value, s.error, s.taken_at from public.metric_snapshot s
       where s.metric_key = v_mk order by s.taken_at desc limit 12
    loop
      v_n_snap := v_n_snap + 1;
      if v_n_snap <= 6 then
        v_hist := v_hist || jsonb_build_object('value', snap.value, 'error', snap.error, 'taken_at', snap.taken_at);
      end if;
      v_off := snap.error is null and snap.value is not null and v_tgt is not null
               and ((v_dir = 'up' and snap.value < v_tgt * 0.7) or (v_dir = 'down' and snap.value > v_tgt * 1.3));
      if v_off and v_consec = v_n_snap - 1 then v_consec := v_consec + 1; end if;
      if snap.error is null and snap.value is not null and v_tgt is not null
         and ((v_dir = 'up' and snap.value >= v_tgt) or (v_dir = 'down' and snap.value <= v_tgt)) then
        v_ever_met := true;
      end if;
    end loop;
  end if;

  if v_label is not null or v_val is not null or v_mk is not null then
    -- band by the scorecard's own rule when the scorecard did not already say
    v_band := coalesce(v_state,
                case when v_err is not null then 'ERROR'
                     when v_val is null or v_tgt is null then 'UNMEASURED'
                     when v_dir = 'up'   and v_val >= v_tgt then 'ON_TARGET'
                     when v_dir = 'down' and v_val <= v_tgt then 'ON_TARGET'
                     when v_dir = 'up'   and v_val >= v_tgt * 0.7 then 'BEHIND'
                     when v_dir = 'down' and v_val <= v_tgt * 1.3 then 'BEHIND'
                     when v_val is not null and v_tgt is not null then 'OFF_TARGET' end);
    v_gap := case when v_val is not null and v_tgt is not null then v_val - v_tgt end;
    v_att := case when v_val is null or v_tgt is null then null
                  when coalesce(v_dir,'up') = 'up' then
                       case when v_tgt > 0 then round(100 * v_val / v_tgt, 1)
                            when v_val <= 0 then 100 else null end
                  else case when v_val > 0 then least(100, round(100 * v_tgt / v_val, 1)) else 100 end end;
    -- cause class, by the "root cause" playbook's own definitions, from what is measurable here
    if v_band = 'ERROR' or v_err is not null then
      v_cause := 'INSTRUMENT'; v_cause_why := 'the latest snapshot carries an error: ' || coalesce(v_err, '(null)');
    elsif v_band = 'UNMEASURED' then
      v_cause := 'INSTRUMENT'; v_cause_why := 'value or target is null; the metric is UNMEASURED, not failing';
    elsif v_band in ('ON_TARGET', 'BEHIND') then
      v_cause := 'NONE'; v_cause_why := 'band ' || v_band || ': no miss to attribute';
    elsif v_consec >= 3 and not v_ever_met and coalesce(btrim(v_definition), '') = '' then
      v_cause := 'TARGET_MIS_SET';
      v_cause_why := v_consec || ' consecutive OFF_TARGET snapshots, never met in ' || v_n_snap
                     || ' recorded, and metric_definition.definition is empty (no documented basis)';
    else
      v_cause := 'EXECUTION';
      v_cause_why := 'default per the playbook: input existed and the instrument is sound. TARGET_MIS_SET test: '
                     || v_consec || ' consecutive OFF_TARGET snapshot(s) (needs >= 3), ever met = ' || v_ever_met
                     || ', documented basis = ' || (coalesce(btrim(v_definition), '') <> '')
                     || case when v_n_snap = 0 then '; no snapshot history for this key' else '' end;
    end if;
    v_metric := jsonb_strip_nulls(jsonb_build_object(
      'metric_key', v_mk, 'label', v_label, 'owner_dept', v_owner, 'in_scorecard', v_in_scorecard,
      'value', v_val, 'target', v_tgt, 'direction', v_dir, 'state', v_state, 'error', v_err,
      'taken_at', v_taken, 'snapshots_newest_first', v_hist, 'snapshots_read', v_n_snap,
      'consecutive_off_target', v_consec, 'ever_met', v_ever_met));
    v_bound := v_bound + (v_val is not null)::int + (v_tgt is not null)::int + (v_band is not null)::int
               + (v_n_snap > 0)::int;
    v_derived := jsonb_strip_nulls(jsonb_build_object(
      'band', v_band, 'gap', v_gap, 'attainment_pct', v_att, 'cause', v_cause, 'cause_evidence', v_cause_why,
      'direction', v_dir));
  end if;

  -- GOALS AT RISK and FAILING METRICS (goal.at_risk carries both as arrays of keys / labels)
  if jsonb_typeof(v_ctx->'goals_at_risk') = 'array' or jsonb_typeof(v_ev_payload->'goals_at_risk') = 'array' then
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
             'key', g.key, 'goal', g.goal, 'metric', g.metric, 'target_value', g.target_value, 'unit', g.unit,
             'direction', g.direction, 'owner_dept', g.owner_dept, 'horizon', g.horizon, 'deadline', g.deadline,
             'active', g.active,
             'latest_period', (select jsonb_build_object('period', p.period_label, 'actual', p.actual_value,
                                                         'target', p.target_value, 'status', p.status)
                                 from public.goal_period p where p.goal_key = g.key
                                order by p.updated_at desc limit 1))) order by g.key), '[]'::jsonb)
      into v_goals
      from public.company_goals g
     where g.key in (select jsonb_array_elements_text(coalesce(v_ctx->'goals_at_risk', v_ev_payload->'goals_at_risk')));
    -- a fixture goal with no company_goals row is still a named fact of the trigger
    select coalesce(v_goals, '[]'::jsonb) || coalesce(jsonb_agg(jsonb_build_object('key', k, 'in_company_goals', false)), '[]'::jsonb)
      into v_goals
      from jsonb_array_elements_text(coalesce(v_ctx->'goals_at_risk', v_ev_payload->'goals_at_risk')) k
     where not exists (select 1 from public.company_goals g where g.key = k);
    v_bound := v_bound + coalesce(jsonb_array_length(v_goals), 0);
  end if;
  if jsonb_typeof(v_ctx->'failing_metrics') = 'array' or jsonb_typeof(v_ev_payload->'failing_metrics') = 'array' then
    select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
             'label', lbl, 'metric_key', sc.metric_key, 'value', sc.value, 'target', sc.target,
             'direction', sc.direction, 'state', sc.state, 'error', sc.error, 'taken_at', sc.taken_at,
             'owner_dept', sc.owner_dept, 'in_scorecard', (sc.metric_key is not null))) order by lbl), '[]'::jsonb)
      into v_failing
      from jsonb_array_elements_text(coalesce(v_ctx->'failing_metrics', v_ev_payload->'failing_metrics')) lbl
      left join public.v_bi_scorecard sc on sc.label = lbl;
    v_bound := v_bound + coalesce(jsonb_array_length(v_failing), 0);
  end if;

  -- WHAT THIS RUN ALREADY CONCLUDED (outcome lines only, in order)
  select coalesce(jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
           'step_no', p.step_no, 'step', p.input->>'step', 'by', coalesce(p.output->>'employee', p.actor),
           'outcome', left(coalesce(p.output->>'outcome', p.output->>'note', ''), 600),
           'disposition', p.output->>'disposition', 'determination_source', p.output->>'determination_source',
           'executor_status', p.output->>'executor_status')) order by p.step_no), '[]'::jsonb)
    into v_prior
    from public.workflow_step_run p
   where p.workflow_run_id = v_run and p.step_no < v_step_no and p.status = 'done';
  v_bound := v_bound + (select count(*) from jsonb_array_elements(v_prior) x where coalesce(x->>'outcome','') <> '')::int;

  -- the trigger payload's own scalar facts, beyond the ones already read above
  v_bound := v_bound + (select count(*) from jsonb_each(v_ev_payload) e
                         where jsonb_typeof(e.value) in ('string','number','boolean')
                           and e.key not in ('label','value','target','state','direction'))::int;

  return jsonb_strip_nulls(jsonb_build_object(
    'step', jsonb_build_object('workflow_key', v_wf, 'step_no', v_step_no, 'step', v_input->>'step',
                               'gate', v_input->>'gate', 'actor', v_actor, 'action_class', v_action_class,
                               'claimed_at', v_started),
    'trigger', case when v_ev_type is null then null else
                 jsonb_build_object('event_id', v_trigger, 'event_type', v_ev_type, 'entity_type', v_ev_entity_type,
                                    'entity_id', v_ev_entity_id, 'actor', v_ev_actor, 'occurred_at', v_ev_at,
                                    'payload', v_ev_payload) end,
    'context', v_ctx,
    'metric', v_metric,
    'goals_at_risk', v_goals,
    'failing_metrics', v_failing,
    'prior_steps', v_prior,
    'derived', v_derived,
    'facts_bound', v_bound,
    'read_at', now()));
end
$function$


CREATE OR REPLACE FUNCTION public.fn_workflow_step_render(p_facts jsonb, p_title text, p_record_type text, p_content text, p_structured jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  f jsonb := coalesce(p_facts, '{}'::jsonb);
  d jsonb := coalesce(p_facts->'derived', '{}'::jsonb);
  m jsonb := p_facts->'metric';
  t text := '';
  sel text[]; k text; v jsonb; s text; x jsonb; n int := 0; lines text := '';
begin
  t := 'DETERMINATION — ' || coalesce(f#>>'{step,workflow_key}', '?') || ' step ' || coalesce(f#>>'{step,step_no}', '?')
       || ': ' || coalesce(f#>>'{step,step}', '') || E'\n'
       || 'Decided by ' || coalesce(f#>>'{step,actor}', '?') || ' at ' || coalesce(f->>'read_at', '') || ' from '
       || coalesce(f->>'facts_bound', '0') || ' bound fact(s); no model call.' || E'\n\n';

  t := t || E'FACTS THIS STEP DECIDED FROM\n';
  if f ? 'trigger' then
    t := t || '- trigger: ' || coalesce(f#>>'{trigger,event_type}', '?') || ' on ' || coalesce(f#>>'{trigger,entity_type}', '?')
         || ' ' || coalesce(f#>>'{trigger,entity_id}', '?') || ' at ' || coalesce(f#>>'{trigger,occurred_at}', '?')
         || ' (event ' || coalesce(f#>>'{trigger,event_id}', '?') || ') payload ' || coalesce((f#>'{trigger,payload}')::text, '{}') || E'\n';
  else
    t := t || E'- trigger: none recorded on this run\n';
  end if;
  if m is not null then
    t := t || '- metric: ' || coalesce(m->>'label', m->>'metric_key', '?')
         || case when (m->>'metric_key') is not null then ' [' || (m->>'metric_key') || ']' else '' end
         || ' value=' || coalesce(m->>'value', 'null') || ' target=' || coalesce(m->>'target', 'null')
         || ' direction=' || coalesce(m->>'direction', 'unknown') || ' state=' || coalesce(m->>'state', d->>'band', 'unknown')
         || case when (m->>'error') is not null then ' ERROR=' || (m->>'error') else '' end
         || case when (m->>'taken_at') is not null then ' taken_at=' || (m->>'taken_at') else '' end
         || ' owner=' || coalesce(m->>'owner_dept', 'unknown')
         || ' in_scorecard=' || coalesce(m->>'in_scorecard', 'false') || E'\n'
         || '- snapshots (newest first, ' || coalesce(m->>'snapshots_read', '0') || ' read): ' || coalesce((m->'snapshots_newest_first')::text, '[]')
         || '; consecutive_off_target=' || coalesce(m->>'consecutive_off_target', '0') || ' ever_met=' || coalesce(m->>'ever_met', 'false') || E'\n';
  end if;
  if jsonb_typeof(f->'goals_at_risk') = 'array' then
    for x in select * from jsonb_array_elements(f->'goals_at_risk') loop
      t := t || '- goal at risk: ' || coalesce(x->>'key', '?')
           || case when coalesce(x->>'in_company_goals', 'true') = 'false' then ' (no company_goals row)'
                   else ' "' || coalesce(x->>'goal', '') || '" target ' || coalesce(x->>'target_value', 'null') || ' ' || coalesce(x->>'unit', '')
                        || ' dir=' || coalesce(x->>'direction', '?') || ' owner=' || coalesce(x->>'owner_dept', '?')
                        || ' deadline=' || coalesce(x->>'deadline', 'none')
                        || case when x ? 'latest_period' then ' latest period ' || (x->'latest_period')::text else ' (no goal_period yet)' end end
           || E'\n';
    end loop;
  end if;
  if jsonb_typeof(f->'failing_metrics') = 'array' then
    for x in select * from jsonb_array_elements(f->'failing_metrics') loop
      t := t || '- failing metric: ' || coalesce(x->>'label', '?')
           || case when coalesce(x->>'in_scorecard', 'false') = 'true'
                   then ' [' || (x->>'metric_key') || '] value=' || coalesce(x->>'value', 'null') || ' target=' || coalesce(x->>'target', 'null')
                        || ' state=' || coalesce(x->>'state', '?') || ' owner=' || coalesce(x->>'owner_dept', '?')
                        || case when (x->>'error') is not null then ' ERROR=' || (x->>'error') else '' end
                   else ' (not on v_bi_scorecard: the emitter''s label only)' end
           || E'\n';
    end loop;
  end if;
  if jsonb_typeof(f->'prior_steps') = 'array' and jsonb_array_length(f->'prior_steps') > 0 then
    for x in select * from jsonb_array_elements(f->'prior_steps') loop
      t := t || '- prior step ' || coalesce(x->>'step_no', '?') || ' (' || coalesce(x->>'by', '?') || ', '
           || coalesce(x->>'disposition', 'no disposition') || '): ' || coalesce(x->>'outcome', '') || E'\n';
    end loop;
  else
    t := t || E'- prior steps: none concluded yet; this is the first step of the run to decide anything\n';
  end if;
  if f ? 'context' and (f->'context') <> '{}'::jsonb then
    t := t || '- run context: ' || (f->'context')::text || E'\n';
  end if;

  t := t || E'\nDETERMINED\n';
  if m is not null then
    t := t || '- variance: ' || coalesce(m->>'label', '?') || ' is ' || coalesce(d->>'band', 'unknown')
         || case when d ? 'gap' then ' — gap ' || (d->>'gap') || ' against target ' || coalesce(m->>'target', 'null')
                                   || ' (direction ' || coalesce(d->>'direction', 'unknown') || ')' else '' end
         || case when d ? 'attainment_pct' then ', attainment ' || (d->>'attainment_pct') || '%' else '' end || E'\n'
         || '- cause class: ' || coalesce(d->>'cause', 'not established') || ' — ' || coalesce(d->>'cause_evidence', '') || E'\n';
  end if;

  -- resolve keyed maps in structured_data at the facts
  sel := array_remove(array[d->>'band', d->>'cause', d->>'direction', f#>>'{trigger,event_type}', f#>>'{step,gate}',
                            lower(d->>'band'), lower(d->>'cause')], null);
  if p_structured is not null and jsonb_typeof(p_structured) = 'object' then
    for k, v in select * from jsonb_each(p_structured) loop
      if jsonb_typeof(v) = 'object' then
        foreach s in array coalesce(sel, '{}'::text[]) loop
          if v ? s then
            n := n + 1;
            lines := lines || '- ' || k || '[' || s || '] → ' || case when jsonb_typeof(v->s) = 'string' then v->>s else (v->s)::text end || E'\n';
          end if;
        end loop;
      end if;
    end loop;
  end if;
  if n > 0 then
    t := t || 'Selected from "' || coalesce(p_title, '?') || '" at the facts above (' || n || ' rule(s)):' || E'\n' || lines;
  else
    t := t || 'No keyed rule in "' || coalesce(p_title, '?') || '" resolves at these facts; the record applies as written below.' || E'\n';
  end if;

  t := t || E'\nAPPLIED RECORD: ' || coalesce(p_record_type, '?') || ' "' || coalesce(p_title, '?') || E'"\n'
       || coalesce(p_content, '');
  if p_structured is not null and p_structured <> '{}'::jsonb then
    t := t || E'\n\nSTRUCTURED DATA OF THE RECORD:\n' || jsonb_pretty(p_structured);
  end if;
  return t;
end
$function$


CREATE OR REPLACE FUNCTION public.fn_workflow_step_sweep(p_limit integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s record; v_settled int := 0; v_q int := 0; v_key text; v_res text; v_out jsonb; v_parked int; v_noclass int;
        v_cap int; v_reflection_today int; v_throttled int; v_true_stall int; v_status text; v_note text;
        v_ineligible int; v_why text; v_held boolean;
begin
  v_held := coalesce((public.fn_kernel_paid_provider_gate('anthropic/claude-sonnet-5')->>'allowed')::boolean, false) = false;

  -- 1. SETTLE what the invoker has already finished. A determination stored on the step before its
  --    executor ran (fn_workflow_step_deterministic_done's queued-edge path) is kept under the response.
  for s in
    select x.status, x.response, x.executor, r.id sid, r.workflow_run_id, r.step_no, r.output prev_output
      from public.action_execution x
      join public.workflow_step_run r on r.id = x.workflow_step_run_id
     where x.workflow_step_run_id is not null
       and x.status in ('succeeded','failed')
       and r.finished_at is null
     order by r.id
     limit 50
  loop
    v_res := public.fn_workflow_step_done(
      s.workflow_run_id, s.step_no,
      coalesce(s.prev_output, '{}'::jsonb)
        || coalesce(s.response, '{}'::jsonb)
        || jsonb_build_object('worked_by', 'executor:' || coalesce(s.executor, '?'),
                              'executor_status', case when s.status = 'succeeded' then 'ran: ' else 'failed: ' end || coalesce(s.executor, '?'))
        || case when v_held then jsonb_build_object('used_llm', false, 'used_llm_basis', 'paid provider held (kernel K12) at settle time') else '{}'::jsonb end,
      case when s.status = 'succeeded' then 'done' else 'failed' end);
    v_settled := v_settled + 1;
  end loop;

  -- 1b. RE-QUEUE the executions the old fn_execution_sweep cancelled before the invoker ever ran them
  --     (observed=cancelled, never dispatched, no decision record, not superseded). A deterministic
  --     executor such as uptime_check or ai_health is simply run, late; a model-backed one stays for the
  --     dispatcher while the model is held. The idempotency key is the same row, so this is an UPDATE.
  for s in
    select x.id xid, r.id sid
      from public.action_execution x
      join public.workflow_step_run r on r.id = x.workflow_step_run_id
      join public.org_action_executor e on e.action_class = r.action_class and e.active
     where x.status = 'cancelled'
       and r.status = 'ready' and r.finished_at is null
       and x.response->>'invoker' is null
       and x.response->>'observed' = 'cancelled'
       and not (x.request ? 'decision_record_id')
       and not (x.response ? 'superseded_by')
       and e.kind in ('edge','rpc') and e.risk_tier = 'low' and e.advisory_safe and e.reversible
       and not e.notifies_human and coalesce(e.required_authority,'') <> 'founder'
       and not (v_held and public.fn_executor_needs_model(e.target))
     order by r.id
     limit greatest(coalesce(p_limit, 5), 1)
  loop
    update public.action_execution
       set status = 'queued', finished_at = null,
           response = coalesce(response,'{}'::jsonb) || jsonb_build_object(
             'requeued_at', now(),
             'requeue_reason', 'cancelled by fn_execution_sweep before the invoker ran it (no decision record was ever expected); re-queued 4 Sep 2026')
     where id = s.xid;
    update public.workflow_step_run set status = 'running' where id = s.sid and status = 'ready';
    v_q := v_q + 1;
  end loop;

  -- 2. QUEUE the ready steps a registered, low-risk, reversible edge executor can run WITHOUT
  --    delivering a message to a person — and, while the model is held, without needing the model.
  for s in
    select r.id, r.workflow_run_id, r.step_no, r.actor, r.action_class, r.input,
           e.target, e.risk_tier, e.reversible
      from public.workflow_step_run r
      join public.org_action_executor e on e.action_class = r.action_class
     where r.status = 'ready' and r.finished_at is null
       and e.kind in ('edge','rpc') and e.active
       and e.risk_tier = 'low' and e.advisory_safe and e.reversible
       and not e.notifies_human
       and coalesce(e.required_authority,'') <> 'founder'
       and not (v_held and public.fn_executor_needs_model(e.target))
       and not exists (select 1 from public.action_execution x
                        where x.idempotency_key = 'workflow_step:' || r.id)
     order by r.id
     limit greatest(coalesce(p_limit, 5), 1)
  loop
    v_key := 'workflow_step:' || s.id;
    insert into public.action_execution(id, correlation_id, action_class, executor, idempotency_key,
                                        risk_tier, reversible, request, status, attempts,
                                        workflow_step_run_id)
    values (gen_random_uuid(), gen_random_uuid(), s.action_class, s.target, v_key,
            s.risk_tier, s.reversible,
            jsonb_build_object('workflow_step_run_id', s.id,
                               'workflow_run_id', s.workflow_run_id,
                               'step_no', s.step_no,
                               'actor', s.actor,
                               'input', coalesce(s.input, '{}'::jsonb),
                               'source', 'fn_workflow_step_sweep'),
            'queued', 0, s.id)
    on conflict (idempotency_key) do nothing;

    update public.workflow_step_run set status = 'running' where id = s.id and status = 'ready';
    v_q := v_q + 1;
  end loop;

  select count(*), count(*) filter (where action_class is null)
    into v_parked, v_noclass
    from public.workflow_step_run where status = 'ready' and finished_at is null;

  select coalesce((value #>> '{}')::int, 6) into v_cap
    from public.decision_policy where key = 'workflow_reflection_steps_per_day';
  v_cap := coalesce(v_cap, 6);

  select count(*) into v_reflection_today
    from public.action_execution x
   where x.workflow_step_run_id is not null
     and x.created_at >= date_trunc('day', now() at time zone 'utc') at time zone 'utc'
     and not public.fn_task_is_demand(x.action_class);

  select count(*) into v_throttled
    from public.workflow_step_run sr
    join public.workflow_run r on r.id = sr.workflow_run_id
   where sr.status = 'ready' and sr.finished_at is null
     and sr.action_class is not null
     and r.status = 'running'
     and r.workflow_key <> 'employee_task'
     and coalesce(sr.input->>'gate','') <> 'founder'
     and not public.fn_task_is_demand(sr.action_class)
     and v_reflection_today >= v_cap;

  select count(*), string_agg(distinct why, '; ') into v_ineligible, v_why from (
    select sr.id,
           case when e.action_class is null then 'no executor is mapped to ' || sr.action_class
                when e.kind not in ('edge','rpc') then sr.action_class || ' is a ' || e.kind || ' executor and no invoker handles that kind'
                when not e.active then sr.action_class || ' executor is inactive'
                when e.risk_tier <> 'low' then sr.action_class || ' is risk_tier ' || e.risk_tier
                when not e.advisory_safe then sr.action_class || ' is not advisory_safe'
                when not e.reversible then sr.action_class || ' is not reversible'
                when e.notifies_human then sr.action_class || ' notifies a human'
                when v_held and public.fn_executor_needs_model(e.target) then
                     sr.action_class || ' runs on the paid model, which is held; the dispatcher works it deterministically'
                when exists(select 1 from public.action_execution x where x.workflow_step_run_id = sr.id)
                     and not exists(select 1 from public.action_execution x
                                     where x.workflow_step_run_id = sr.id
                                       and x.status in ('queued','running','succeeded')) then
                     sr.action_class || ' has only a terminal (cancelled/failed/held) action_execution; while the model is held the dispatcher works it deterministically'
           end as why
      from public.workflow_step_run sr
      left join public.org_action_executor e on e.action_class = sr.action_class
     where sr.status = 'ready' and sr.finished_at is null and sr.action_class is not null
  ) q where why is not null;
  v_ineligible := coalesce(v_ineligible, 0);
  v_true_stall := greatest(v_parked - v_noclass - v_throttled - v_ineligible, 0);

  v_out := jsonb_build_object(
    'settled', v_settled, 'queued', v_q, 'ran_at', now(), 'model_held', v_held,
    'parked', v_parked, 'parked_without_action_class', v_noclass,
    'parked_throttled_by_reflection_ceiling', v_throttled,
    'reflection_worked_today', v_reflection_today, 'reflection_cap', v_cap,
    'parked_ineligible_by_policy', v_ineligible,
    'parked_ineligible_because', coalesce(v_why, ''),
    'parked_unexplained', v_true_stall,
    'ready_runnable', (select count(*) from public.workflow_step_run r
                         join public.org_action_executor e on e.action_class = r.action_class
                        where r.status = 'ready' and e.kind in ('edge','rpc') and e.active
                          and e.risk_tier='low' and e.advisory_safe and e.reversible
                          and not e.notifies_human),
    'ready_held_notifies_human', (select count(*) from public.workflow_step_run r
                                    join public.org_action_executor e on e.action_class = r.action_class
                                   where r.status = 'ready' and e.notifies_human),
    'never_finished', (select count(*) from public.workflow_step_run where finished_at is null));

  v_status := case when v_true_stall > 0 and v_q = 0 and v_settled = 0 then 'error' else 'ok' end;
  v_note := 'settled ' || v_settled || ', queued ' || v_q || ', parked ' || v_parked
         || ' (' || v_noclass || ' awaiting an action_class, ' || v_throttled
         || ' held by the reflection ceiling at ' || v_reflection_today || '/' || v_cap || ' today, '
         || v_ineligible || ' ineligible by policy'
         || case when v_why is null or v_why = '' then '' else ' (' || left(v_why, 300) || ')' end
         || ', ' || v_true_stall || ' unexplained)';
  if v_status = 'error' then
    v_note := 'STALLED: ' || v_true_stall || ' workflow step(s) are ready, carry an action_class, '
           || 'and are not explained by the reflection ceiling. ' || v_note;
  end if;

  insert into public.agent_runs(agent, status, counts, note, started_at, finished_at)
  values ('workflow_step_sweep', v_status, v_out, v_note, now(), now());

  if v_noclass > 0 then
    begin
      insert into public.org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
      select 'exec', 'Classify the workflow steps no executor can run',
             v_noclass || ' workflow_step_run row(s) are ready with no action_class, so nothing can '
             || 'ever pick them up and their runs never complete. The gap is in the DEFINITIONS: '
             || 'employee_task, rfq_handling, payment, refund, complaint, supplier_onboarding, '
             || 'customer_registration, invoice_approval, campaign_publishing and '
             || 'supplier_suspension carry no action_class on any step. Classifying them will make '
             || 'the queued backlog FIRE, so check org_action_executor.notifies_human, risk_tier '
             || 'and reversible per class first - refund reaches Stripe and needs the founder.',
             'proposed', 'gated', false, 'incident_fix'
      where not exists (select 1 from public.org_tasks
                         where title = 'Classify the workflow steps no executor can run'
                           and status <> 'done');
    exception when others then null; end;
  end if;

  -- Stranded steps are the dispatcher's while the model is held (fn_workflow_step_claim). The dedup
  -- backlog task is raised only when the hold is NOT in force, i.e. when nothing else will take them.
  if not v_held and (select count(*) from public.workflow_step_run sr
               where sr.status='ready' and sr.finished_at is null and sr.action_class is not null
                 and exists(select 1 from public.action_execution x where x.workflow_step_run_id=sr.id)
                 and not exists(select 1 from public.action_execution x
                                 where x.workflow_step_run_id=sr.id and x.status in ('queued','running','succeeded'))) > 0 then
    begin
      insert into public.org_tasks (dept_key, title, detail, status, tier, needs_founder, action_class)
      select 'exec', 'Re-open workflow steps stranded by a cancelled action',
             (select count(*) from public.workflow_step_run sr
               where sr.status='ready' and sr.finished_at is null and sr.action_class is not null
                 and exists(select 1 from public.action_execution x where x.workflow_step_run_id=sr.id)
                 and not exists(select 1 from public.action_execution x
                                 where x.workflow_step_run_id=sr.id and x.status in ('queued','running','succeeded')))
             || ' workflow step(s) are ready but each has only a terminal (cancelled/failed) '
             || 'action_execution, so the sweep will not re-queue over it. Re-open them for a fresh '
             || 'attempt or drive the review-decision loop they await; a cancelled action must also settle its step.',
             'proposed', 'gated', false, 'incident_fix'
      where not exists (select 1 from public.org_tasks
                         where title = 'Re-open workflow steps stranded by a cancelled action'
                           and status <> 'done');
    exception when others then null; end;
  end if;

  return v_out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_working_days_between(p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare d date; n int := 0; last date;
begin
  if p_from is null or p_to is null or p_to <= p_from then return 0; end if;
  d := (p_from at time zone 'Asia/Dubai')::date + 1;
  last := (p_to at time zone 'Asia/Dubai')::date;
  while d <= last loop
    if public.fn_is_working_day(d) then n := n + 1; end if;
    d := d + 1;
  end loop;
  return n;
end $function$


CREATE OR REPLACE FUNCTION public.fn_write_decision_trace(p jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id       uuid;
  v_agent    text := nullif(p->>'agent_key','');
  v_role     text;
  v_dept     text;
  v_mgr      text;
  v_dobj     text;
  v_corr     uuid := coalesce(nullif(p->>'correlation_id','')::uuid, gen_random_uuid());
begin
  if v_agent is null then
    raise exception 'fn_write_decision_trace: agent_key is required. A trace that cannot name who decided is not evidence.';
  end if;

  -- Identity is resolved SERVER-SIDE from the roster. A model cannot label its own trace with
  -- someone else's role, which is the whole point of separating role_id from agent_key.
  select a.department, a.manager_key, d.north_star
    into v_dept, v_mgr, v_dobj
    from org_agents a left join org_departments d on d.dept_key = a.department
   where a.agent_key = v_agent;

  v_role := coalesce(nullif(p->>'role_id',''),
                     (select i.packaged_role_id from org_role_identity i
                       where i.agent_key = v_agent order by i.packaged_role_id limit 1));

  insert into decision_trace (
    correlation_id, entity_type, entity_id, decision_type, proposed_by, decided_by,
    policy_keys, knowledge_refs, evidence_refs, alternatives, assumptions, risk,
    confidence, authority_result, decision, outcome_status,
    task_id, agent_key, role_id, department_id, manager_id, task_class,
    company_objective, department_objective, relevant_kpi,
    knowledge_versions, source_freshness, tools_requested, tools_executed, tool_result_refs,
    uncertainty, escalation_decision, proposed_action, expected_outcome, review_date,
    model, provider, input_tokens, output_tokens, estimated_cost_aed, final_status
  ) values (
    v_corr,
    coalesce(nullif(p->>'entity_type',''),'agent_task'),
    nullif(p->>'entity_id',''),
    coalesce(nullif(p->>'decision_type',''),'agent_decision'),
    v_agent,
    coalesce(nullif(p->>'decided_by',''), v_agent),
    coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(p->'policy_keys','[]'::jsonb)) x), '{}'),
    coalesce(p->'knowledge_refs','[]'::jsonb),
    coalesce(p->'evidence_refs','[]'::jsonb),
    coalesce(p->'alternatives','[]'::jsonb),
    coalesce(p->'assumptions','[]'::jsonb),
    coalesce(p->'risk','{}'::jsonb),
    nullif(p->>'confidence','')::numeric,
    coalesce(p->'authority_result','{}'::jsonb),
    coalesce(p->'decision','{}'::jsonb),
    coalesce(nullif(p->>'outcome_status',''),'pending'),
    nullif(p->>'task_id',''), v_agent, v_role, v_dept, v_mgr, nullif(p->>'task_class',''),
    -- The canonical company objective, read from the row that owns it rather than restated here:
    -- company_goals.revenue_annual = "Reach AED 1,000,000 annual revenue", target 1000000 AED.
    coalesce(nullif(p->>'company_objective',''),
             (select g.goal || ' (' || g.target_value::text || ' ' || coalesce(g.unit,'') || ')'
                from company_goals g where g.key = 'revenue_annual' and g.active limit 1)),
    coalesce(nullif(p->>'department_objective',''), v_dobj),
    nullif(p->>'relevant_kpi',''),
    coalesce(p->'knowledge_versions','{}'::jsonb),
    coalesce(p->'source_freshness','{}'::jsonb),
    coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(p->'tools_requested','[]'::jsonb)) x), '{}'),
    coalesce((select array_agg(x) from jsonb_array_elements_text(coalesce(p->'tools_executed','[]'::jsonb)) x), '{}'),
    coalesce(p->'tool_result_refs','[]'::jsonb),
    nullif(p->>'uncertainty',''), nullif(p->>'escalation_decision',''),
    nullif(p->>'proposed_action',''), nullif(p->>'expected_outcome',''),
    nullif(p->>'review_date','')::date,
    nullif(p->>'model',''), nullif(p->>'provider',''),
    nullif(p->>'input_tokens','')::integer, nullif(p->>'output_tokens','')::integer,
    nullif(p->>'estimated_cost_aed','')::numeric, nullif(p->>'final_status','')
  ) returning id into v_id;

  return v_id;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ws_agent_ops(p_agent text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare ca public.category_agents%rowtype; pr public.prompts%rowtype;
  runs_total int; runs_24h int; runs_7d int; ok_runs int; last_run timestamptz; last_status text;
  avg_ms numeric; kn_updated timestamptz; kn_count int; mem_count int; health text;
  v_dept text; v_cap int; v_open int; v_queue int; v_goal jsonb; v_rep public.agent_reputation%rowtype;
begin
  select * into ca from public.category_agents where slug=p_agent;
  select * into pr from public.prompts where key=p_agent;

  -- RESOLVE HERE, NOT AT THE TOP. PLACEMENT IS LOAD-BEARING (15 Aug 2026).
  --
  -- Everything below this line reads org_agents, agent_runs, agent_knowledge, agent_memory,
  -- agent_actions, decision_log, employee_kpi_history, knowledge_exam_results and skills_matrix by
  -- agent_key, and every one of those missed for an employee addressed by an alias - so the whole
  -- workspace drawer came back empty for them: no runs, no knowledge, no KPIs, no learning curve.
  --
  -- But the TWO lookups above are keyed differently. category_agents.slug and prompts.key are
  -- alias-shaped: 14 alias values are also category_agents slugs, and none of the 132 slugs equals
  -- any org_agents.agent_key. Resolving before them would blank the name, emoji and persona for
  -- exactly the employees this repairs - trading an empty drawer for an anonymous one.
  p_agent := coalesce(public.fn_org_agent_resolve(p_agent), p_agent);
  select count(*), count(*) filter (where started_at>now()-interval '24 hours'),
         count(*) filter (where started_at>now()-interval '7 days'),
         count(*) filter (where status='ok'),
         max(started_at),
         coalesce(round(avg(extract(epoch from (finished_at-started_at))*1000) filter (where finished_at is not null),0),0)
    into runs_total, runs_24h, runs_7d, ok_runs, last_run, avg_ms
    from public.agent_runs where agent=p_agent;
  select status into last_status from public.agent_runs where agent=p_agent order by started_at desc limit 1;
  select count(*), max(updated_at) into kn_count, kn_updated from public.agent_knowledge where agent_key=p_agent;
  select count(*) into mem_count from public.agent_memory where agent_key=p_agent;
  health := case
    when last_status is null then 'idle'
    when last_status in ('error','failed') then 'degraded'
    when last_run < now()-interval '3 days' then 'stale'
    else 'healthy' end;

  select a.department, a.max_open_tasks into v_dept, v_cap
    from public.org_agents a where a.agent_key = p_agent;
  select * into v_rep from public.agent_reputation where agent_key = p_agent;

  -- The employee's own open items, and the open work sitting in their department.
  select count(*) into v_queue from public.agent_actions
   where agent = p_agent and status in ('pending','held_for_review','proposed','open');
  select count(*) into v_open from public.org_tasks
   where dept_key = v_dept and coalesce(status,'') <> 'done';

  -- CURRENT GOAL, resolved down the chain until something real answers.
  select case
    when o.objective is not null then jsonb_build_object(
      'objective', o.objective, 'horizon', o.horizon, 'status', o.status,
      'goal_source', 'department_objective', 'dept', v_dept)
    when cg.goal is not null then jsonb_build_object(
      'objective', cg.goal, 'horizon', cg.horizon, 'metric', cg.metric,
      'target_value', cg.target_value, 'unit', cg.unit,
      'goal_source', 'company_goals', 'dept', v_dept)
    when d.north_star is not null then jsonb_build_object(
      'objective', d.north_star, 'horizon', 'standing',
      'goal_source', 'department_north_star', 'dept', v_dept)
    else jsonb_build_object('objective', null, 'goal_source', 'none', 'dept', v_dept)
  end into v_goal
  from (select 1) _
  left join lateral (select * from public.department_objective x
                      where x.dept_key = v_dept and x.active
                      order by x.sort nulls last, x.updated_at desc limit 1) o on true
  left join lateral (select * from public.company_goals c
                      where c.owner_dept = v_dept and c.active
                      order by c.sort nulls last limit 1) cg on true
  left join public.org_departments d on d.dept_key = v_dept;

  return jsonb_build_object(
    'identity', jsonb_build_object('key',p_agent,'name',coalesce(ca.name,pr.description,p_agent),
       'emoji',ca.emoji,'active',coalesce(ca.active,true),'persona',ca.persona,
       'department', v_dept,
       'prompt_version',pr.active_version,'prompt_desc',pr.description,'prompt_owner',pr.owner,'prompt_updated',pr.updated_at,
       'knowledge_updated',kn_updated),
    'health', jsonb_build_object('status',health,'last_run',last_run,'last_status',last_status),
    'performance', jsonb_build_object('runs_total',runs_total,'runs_24h',runs_24h,'runs_7d',runs_7d,
       'ok_rate', case when runs_total>0 then round(100.0*ok_runs/runs_total,1) else null end,
       'avg_duration_ms',avg_ms),

    -- PERFORMANCE AS A TREND, NOT A POINT (11 Aug 2026). Every number above is a single current
    -- value, so the drawer could show how this employee is doing and never whether it is getting
    -- better or worse. employee_kpi_history writes one row per KPI per UTC day with a unique index
    -- that makes a fabricated trend impossible; this is its first reader. Attainment is averaged
    -- across the employee's KPIs for the day, so the series is "how this person performed", not
    -- one arbitrary KPI of theirs. Oldest-first because that is the order a line is drawn in.
    'kpi_trend', (select coalesce(jsonb_agg(jsonb_build_object(
                        'label', to_char(t.measured_on, 'DD Mon'),
                        'v', t.attainment,
                        'kpis', t.n) order by t.measured_on), '[]'::jsonb)
                    from (select h.measured_on,
                                 round(avg(h.attainment)::numeric, 1) attainment,
                                 count(*) n
                            from public.employee_kpi_history h
                           where h.agent_key = p_agent
                             and h.measured_on > (now() at time zone 'utc')::date - 90
                           group by h.measured_on
                           order by h.measured_on desc
                           limit 30) t),

    -- ── THE SIX THAT WERE COMPUTED AND NEVER DELIVERED ─────────────────────────────────────────
    'goal', v_goal,

    'tasks', jsonb_build_object(
      'mine_open', v_queue,
      'department', v_dept,
      'department_open', v_open,
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
                 'id',t.id,'title',t.title,'status',t.status,'tier',t.tier,
                 'needs_founder',t.needs_founder,'created_at',t.created_at,'last_run_at',t.last_run_at)
               order by (coalesce(t.status,'')='done'), t.created_at desc)
             from (select * from public.org_tasks where dept_key = v_dept
                    and coalesce(status,'') <> 'done' order by created_at desc limit 12) t), '[]'::jsonb)),

    'decisions', coalesce((select jsonb_agg(jsonb_build_object(
                 'id',l.id,'kind',l.kind,'decision',l.decision,'confidence',l.confidence,
                 'route_to',l.route_to,'reasons',l.reasons,'sources',l.sources,'at',l.created_at)
               order by l.created_at desc)
             from (select * from public.decision_log where actor = p_agent
                    order by created_at desc limit 10) l), '[]'::jsonb),

    'confidence', jsonb_build_object(
      'reputation_score', v_rep.score, 'tier', v_rep.tier,
      'correctness', v_rep.correctness, 'reliability', v_rep.reliability,
      'learning_speed', v_rep.learning_speed, 'computed_at', v_rep.computed_at,
      'avg_decided', (select round(avg(confidence)::numeric, 2) from public.decision_log
                       where actor = p_agent and confidence is not null),
      'decided_with_confidence', (select count(*) from public.decision_log
                                   where actor = p_agent and confidence is not null)),

    'workload', jsonb_build_object(
      'open_tasks', v_open, 'queue_depth', v_queue, 'capacity', v_cap,
      'workload_pct', case when coalesce(v_cap,0) > 0
                           then round(100.0 * (v_open + v_queue) / v_cap, 1) else null end,
      'state', case when coalesce(v_cap,0) = 0 then 'unset'
                    when (v_open + v_queue) > v_cap then 'over'
                    when (v_open + v_queue) > v_cap * 0.8 then 'tight' else 'ok' end),

    'plans', coalesce((select jsonb_agg(jsonb_build_object(
                 'objective',p.objective,'horizon',p.horizon,'status',p.status,'scope','department')
               order by p.sort nulls last)
             from public.department_objective p where p.dept_key = v_dept and p.active), '[]'::jsonb)
      || coalesce((select jsonb_agg(jsonb_build_object(
                 'objective',o.objective,'horizon',o.horizon,'measure',o.measure,'scope','operating_system')
               order by o.id)
             from public.os_objective o
             where o.active and o.os_key = (select r.os_key from public.os_responsibility r
                                             where r.responsibility = v_dept limit 1)), '[]'::jsonb),

    -- WHAT THIS EMPLOYEE IS SUPPOSED TO KNOW (13 Aug 2026). employee_knowledge holds 900 rows over
    -- 66 employees - the domains each one is expected to cover and at what depth - and had NO
    -- browser-reachable reader at all. The `knowledge` block below is a different table:
    -- agent_knowledge is what has been WRITTEN for them, this is the curriculum they are measured
    -- against. Showing only the first without the second means a drawer can look full while the
    -- employee covers one of twelve domains they are meant to hold.
    'curriculum', jsonb_build_object(
       'domains', (select count(*) from public.employee_knowledge ek where ek.agent_key = p_agent),
       'rows', coalesce((select jsonb_agg(jsonb_build_object('domain',ek.domain_key,'depth',ek.depth,'layer',ek.layer_no)
                                order by ek.layer_no nulls last, ek.domain_key)
                           from public.employee_knowledge ek where ek.agent_key = p_agent),'[]'::jsonb),
       'by_depth', coalesce((select jsonb_object_agg(d.depth, d.n)
                               from (select coalesce(ek.depth,'unspecified') depth, count(*) n
                                       from public.employee_knowledge ek where ek.agent_key = p_agent
                                      group by 1) d),'{}'::jsonb)),
    'knowledge', jsonb_build_object('count',kn_count,'updated',kn_updated,

       'topics', coalesce((select jsonb_agg(distinct topic) from public.agent_knowledge where agent_key=p_agent and topic is not null),'[]'::jsonb),
       'recent', coalesce((select jsonb_agg(jsonb_build_object('topic',topic,'priority',priority,'updated',updated_at) order by updated_at desc)
                    from (select * from public.agent_knowledge where agent_key=p_agent order by updated_at desc limit 6) x),'[]'::jsonb)),
    'memory', jsonb_build_object('count',mem_count,
       'recent', coalesce((select jsonb_agg(jsonb_build_object('kind',kind,'content',left(content,140),'importance',importance,'at',created_at) order by created_at desc)
                    from (select * from public.agent_memory where agent_key=p_agent order by created_at desc limit 6) x),'[]'::jsonb)),
    'queue', coalesce((select jsonb_agg(jsonb_build_object('id',id,'kind',kind,'title',title,'risk',risk,'status',status,'recommendation',recommendation,'created_at',created_at,
                   -- NOT HIS unless the kind's policy is 'founder' (a refund). The holder is the role that decides it.
                   'holder', public.fn_action_holder(x.kind, x.agent),
                   'yours', exists (select 1 from public.agent_action_kind_policy kp where kp.kind = x.kind and kp.policy = 'founder')) order by created_at desc)
                 from (select * from public.agent_actions where agent=p_agent and status in ('pending','held_for_review','proposed','open') order by created_at desc limit 12) x),'[]'::jsonb),
    'conversations', coalesce((select jsonb_agg(jsonb_build_object('role',role,'content',left(content,160),'at',created_at) order by created_at desc)
                 from (select * from public.agent_chats where agent_key=p_agent order by created_at desc limit 8) x),'[]'::jsonb),
    -- LEARNING PROGRESS. The employee workspace showed goal, tasks, decisions, confidence,
    -- workload, plans, knowledge, health, performance, queue, runs, memory, conversations and
    -- recommendations - everything except whether this employee is getting BETTER. The founder's
    -- operating model asks each employee to "learn from performance, failures, outcomes and new
    -- information" and to "improve its decisions and methods over time", and the drawer had no key
    -- for it, so knowledge_exam_results (576 rows over 98 employees) and skills_matrix (695 rows)
    -- were written and never read by any browser-reachable surface.
    --
    -- exam_trend is one point PER DAY, oldest first, because a curve is the only form in which
    -- "improving" is visible. A single aggregate score cannot say whether it went up.
    'learning', jsonb_build_object(
      'exam_results_total', (select count(*) from public.knowledge_exam_results where agent_key = p_agent),
      'exam_days',          (select count(distinct created_at::date) from public.knowledge_exam_results where agent_key = p_agent),
      'exam_score_pct',     (select round(100.0 * count(*) filter (where verdict = 'correct') / nullif(count(*),0), 1)
                               from public.knowledge_exam_results where agent_key = p_agent),
      'last_exam_at',       (select max(created_at) from public.knowledge_exam_results where agent_key = p_agent),
      'exam_trend', coalesce((select jsonb_agg(jsonb_build_object('day', d, 'asked', n, 'score_pct', pct) order by d)
                     from (select created_at::date d, count(*) n,
                                  round(100.0 * count(*) filter (where verdict = 'correct') / nullif(count(*),0), 1) pct
                             from public.knowledge_exam_results where agent_key = p_agent
                            group by 1 order by 1 desc limit 14) t), '[]'::jsonb),
      'knowledge_gaps_found', (select count(*) from public.knowledge_exam_results
                                where agent_key = p_agent and gap_fact is not null),
      'knowledge_gaps_filled', (select count(*) from public.knowledge_exam_results
                                 where agent_key = p_agent and filled),
      'skills', coalesce((select jsonb_agg(jsonb_build_object('skill', skill, 'rating', rating) order by skill)
                 from public.skills_matrix where agent_key = p_agent), '[]'::jsonb)),
    'recommendations', coalesce((select jsonb_agg(jsonb_build_object('title',title,'recommendation',left(recommendation,180),'risk',risk,'at',created_at) order by created_at desc)
                 from (select * from public.agent_actions where agent=p_agent and recommendation is not null order by created_at desc limit 6) x),'[]'::jsonb),
    'audit', coalesce((select jsonb_agg(jsonb_build_object('title',title,'kind',kind,'status',status,'decided_by',decided_by,'decided_at',decided_at,'at',created_at) order by created_at desc)
                 from (select * from public.agent_actions where agent=p_agent order by created_at desc limit 12) x),'[]'::jsonb),
    'recent_runs', coalesce((select jsonb_agg(jsonb_build_object('id',id,'status',status,'note',note,'started_at',started_at,'finished_at',finished_at) order by started_at desc)
                 from (select * from public.agent_runs where agent=p_agent order by started_at desc limit 8) x),'[]'::jsonb)
  );
end $function$


CREATE OR REPLACE FUNCTION public.fn_ws_agents()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare v_out jsonb;
begin
  create temp table if not exists _minds (k text primary key) on commit drop;
  insert into _minds
    select agent_key from public.org_agents where active
    union select 'cat:'||slug from public.category_agents where active
    union select slug from public.category_agents where active
    union select distinct agent_key from public.agent_knowledge where agent_key <> '_global'
  on conflict do nothing;

  with keys as (
    select distinct k from (
      select agent k from public.agent_runs where agent is not null and agent <> ''
      union select agent from public.agent_actions where agent is not null
      union select key from public.prompts where key is not null
      union select slug from public.category_agents where slug is not null
      union select agent_key from public.org_agents where active
    ) u
  ),
  -- ONE PASS PER SOURCE. Previously each of these was a subquery re-evaluated for all 356 keys.
  runs as (
    select agent k, count(*) runs_total,
           count(*) filter (where started_at > now() - interval '24 hours') runs_24h,
           max(started_at) last_run
      from public.agent_runs where agent is not null and agent <> '' group by agent
  ),
  -- The newest run's status, taken with a window rather than a per-key ORDER BY ... LIMIT 1.
  last_status as (
    select k, status from (
      select agent k, status, row_number() over (partition by agent order by started_at desc) rn
        from public.agent_runs where agent is not null and agent <> ''
    ) z where rn = 1
  ),
  acts as (
    select agent k, count(*) filter (where status in ('pending','held_for_review','proposed','open')) actions_pending
      from public.agent_actions where agent is not null group by agent
  ),
  mem as (select agent_key k, count(*) n from public.agent_memory group by agent_key),
  kn  as (select agent_key k, count(*) n from public.agent_knowledge group by agent_key)
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      -- THE WORKFORCE, and nothing else. Was a distinct count over a union of org_agents,
      -- category brains under two spellings, and every agent_key that ever had a knowledge row.
      'agents', (select count(*) from public.org_agents where active),
      -- The category brains still counted, under their own name, because they are real and useful
      -- - they are simply not employees.
      'category_brains', (select count(*) from public.category_agents where active),
      'automations', (select count(distinct ar.agent) from public.agent_runs ar
                      where ar.agent is not null and ar.agent <> ''
                        and not exists (select 1 from _minds m where m.k=ar.agent)),
      'runs_24h', (select count(*) from public.agent_runs where started_at > now()-interval '24 hours'),
      'actions_total', (select count(*) from public.agent_actions),
      'actions_pending', (select count(*) from public.agent_actions where status in ('pending','held_for_review','proposed','open')),
      'memory_items', (select count(*) from public.agent_memory),
      'knowledge_items', (select count(*) from public.agent_knowledge)
    ),
    'rows', coalesce((
      select jsonb_agg(r order by (r->>'runs_total')::int desc nulls last, r->>'name')
      from (
        select jsonb_build_object(
          'key', k.k,
          'name', coalesce(ca.name, pr.description, k.k),
          'emoji', ca.emoji,
          'kind', case when exists (select 1 from _minds m where m.k=k.k) then 'agent' else 'automation' end,
          'active', coalesce(ca.active, true),
          'prompt_version', pr.active_version,
          'runs_total', coalesce(ru.runs_total, 0),
          'runs_24h', coalesce(ru.runs_24h, 0),
          'last_run', ru.last_run,
          'last_status', ls.status,
          'actions_pending', coalesce(ac.actions_pending, 0),
          'memory', coalesce(me.n, 0),
          -- Both the bare key and its 'cat:' twin, exactly as the IN (k, 'cat:'||k) did.
          'knowledge', coalesce(kb.n, 0) + coalesce(kc.n, 0)
        ) r
        from keys k
        left join public.category_agents ca on ca.slug = k.k
        left join public.prompts pr on pr.key = k.k
        left join runs ru on ru.k = k.k
        left join last_status ls on ls.k = k.k
        left join acts ac on ac.k = k.k
        left join mem me on me.k = k.k
        left join kn kb on kb.k = k.k
        left join kn kc on kc.k = 'cat:' || k.k
      ) s), '[]'::jsonb)
  ) into v_out;

  return v_out;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ws_ai()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      'agents',(select count(*) from category_agents),
      'agents_active',(select count(*) from category_agents where active is true),
      'actions_total',(select count(*) from agent_actions),
      'actions_pending',(select count(*) from agent_actions where status='pending'),
      'runs_24h',(select count(*) from agent_runs where started_at > now()-interval '24 hours'),
      'avg_confidence',(select round(avg(confidence)::numeric,2) from decision_log where confidence is not null)
    ),
    'trainer', jsonb_build_object(
      'ai_health', (select (kpis->>'ai_health')::numeric from ai_trainer_snapshots order by snapshot_date desc limit 1),
      'metrics', (select kpis from ai_trainer_snapshots order by snapshot_date desc limit 1),
      'weak_agents', coalesce((select jsonb_agg(jsonb_build_object('agent',agent,'run_success_pct',run_success_pct,'rejection_rate_pct',rejection_rate_pct,'errors',errors) order by run_success_pct nulls last)
          from ai_agent_quality where runs_30d>=20 and (coalesce(run_success_pct,100)<95 or coalesce(rejection_rate_pct,0)>20)),'[]'::jsonb),
      'proposals', coalesce((select jsonb_agg(jsonb_build_object('title',title,'risk',risk,'reco',recommendation))
          from agent_actions where agent='ai_trainer' and status in ('pending','needs_review')),'[]'::jsonb)
    ),
    'prompt_reviews', coalesce((select jsonb_agg(jsonb_build_object(
        'id', id, 'key', detail->>'key', 'version', (detail->>'version')::int,
        'reason', detail->>'reason',
        'active_version', (select active_version from prompts p where p.key = a.detail->>'key'),
        'active_score', (a.detail->'eval'->>'active_score'),
        'candidate_score', (a.detail->'eval'->>'candidate_score'),
        'delta', (a.detail->'eval'->>'delta'),
        'decision', a.detail->'eval'->>'decision',
        'sensitive', (a.detail->'eval'->>'sensitive'),
        'scored', (a.detail ? 'eval')
      ) order by created_at desc)
      from agent_actions a where kind='prompt_approval' and status in ('pending','needs_review')),'[]'::jsonb),
    'agents', coalesce((select jsonb_agg(jsonb_build_object('slug',ca.slug,'name',ca.name,'emoji',ca.emoji,'active',ca.active,
        'actions',(select count(*) from agent_actions a where a.agent=ca.slug),
        'pending',(select count(*) from agent_actions a where a.agent=ca.slug and a.status='pending')) order by ca.name) from category_agents ca),'[]'::jsonb),
    'kinds', coalesce((select jsonb_agg(jsonb_build_object('key',k,'count',c) order by c desc) from (
        select coalesce(nullif(kind,''),'other') k, count(*) c from agent_actions group by 1 order by 2 desc limit 12) kk),'[]'::jsonb),
    'runs', coalesce((select jsonb_agg(jsonb_build_object('id',id,'agent',agent,'status',status,'started_at',started_at,'finished_at',finished_at,'note',note)) from (select * from agent_runs order by started_at desc limit 12) r),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_analytics()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'marketplace', fn_marketplace_analytics(),
    'supplier_funnel', jsonb_build_object(
      'directory',(select count(*) from leads),
      'claimed',(select count(*) from leads where claimed is true),
      'registered',(select count(*) from leads where registration_paid_at is not null),
      'submitted',(select count(*) from leads where coalesce(approval_status,'') in ('submitted','under_review','pending','pending_review')),
      'approved',(select count(*) from leads where approval_status='approved')
    ),
    'top_sectors', coalesce((select jsonb_agg(jsonb_build_object('key',s,'count',c) order by c desc) from (
        select coalesce(nullif(sector,''),'other') s, count(*) c from leads group by 1 order by 2 desc limit 12) x),'[]'::jsonb),
    'top_emirates', coalesce((select jsonb_agg(jsonb_build_object('key',e,'count',c) order by c desc) from (
        select coalesce(nullif(emirate,''),'—') e, count(*) c from leads group by 1 order by 2 desc limit 8) x),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_company()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'legal', jsonb_build_object(
      'health', (select (kpis->>'legal_health')::numeric from legal_kpi_snapshots order by snapshot_date desc limit 1),
      'kpis', (select to_jsonb(k) from legal_kpis k),
      'missing_docs', coalesce((select jsonb_agg(jsonb_build_object('requirement',requirement,'priority',priority,'applies_to',applies_to) order by priority) from legal_checklist where not present),'[]'::jsonb),
      'flags', coalesce((select jsonb_agg(jsonb_build_object('title',title,'risk',risk)) from agent_actions where agent='legal_ai' and status in ('pending','needs_review')),'[]'::jsonb),
      'reviews', coalesce((select jsonb_agg(jsonb_build_object('title',title,'kind',doc_kind,'risk',risk_level,'at',reviewed_at) order by reviewed_at desc) from (select * from legal_reviews order by reviewed_at desc limit 10) r),'[]'::jsonb)
    ),
    'departments', coalesce((select jsonb_agg(jsonb_build_object('agent',agent,'actions',c,'pending',pend,'last_active',la) order by c desc) from (
        select coalesce(agent,'—') agent, count(*) c,
               count(*) filter (where status='pending') pend, max(created_at) la
        from agent_actions where created_at >= public.fn_os_fresh_start_at() group by 1 order by 2 desc limit 20) d),'[]'::jsonb),
    'runs', coalesce((select jsonb_agg(jsonb_build_object('agent',agent,'status',status,'started_at',started_at,'note',note)) from (select * from agent_runs where started_at >= public.fn_os_fresh_start_at() order by started_at desc limit 12) r),'[]'::jsonb),
    'evals', coalesce((select jsonb_agg(jsonb_build_object('snapshot_at',snapshot_at,'window_days',window_days,'kpis',kpis)) from (select * from agent_evals where snapshot_at >= public.fn_os_fresh_start_at() order by snapshot_at desc limit 4) e),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_company_os()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(

    -- ── THE TEN OPERATING SYSTEMS ────────────────────────────────────────────────────────────
    'operating_systems', coalesce((select jsonb_agg(jsonb_build_object(
        'os_key', o.os_key, 'num', o.num, 'name', o.name, 'mission', o.mission,
        'charter', o.charter, 'mandate', o.mandate, 'owner_agent', o.owner_agent,
        'health_score', o.health_score, 'last_health_at', o.last_health_at, 'active', o.active,
        'responsibilities', (select coalesce(jsonb_agg(r.responsibility order by r.responsibility), '[]'::jsonb)
                               from public.os_responsibility r where r.os_key = o.os_key),
        'objectives', (select coalesce(jsonb_agg(jsonb_build_object(
                          'objective', j.objective, 'horizon', j.horizon, 'measure', j.measure,
                          'actual_value', j.actual_value) order by j.id), '[]'::jsonb)
                         from public.os_objective j where j.os_key = o.os_key and j.active),
        -- Only 4 of the 72 os_responsibility rows name a department; the rest name capabilities.
        -- So this reports the departments the OS demonstrably owns and the headcount inside THEM,
        -- rather than a company-wide headcount that would read as 0 for Leadership and be wrong.
        'owned_departments', (select coalesce(jsonb_agg(d.dept_key order by d.dept_key), '[]'::jsonb)
                                from public.org_departments d
                               where exists (select 1 from public.os_responsibility r2
                                              where r2.os_key = o.os_key and r2.responsibility = d.dept_key)),
        'staff_in_owned_departments', (select count(*) from public.org_agents a where a.active
                    and a.department in (select r2.responsibility from public.os_responsibility r2 where r2.os_key = o.os_key)))
      order by o.num) from public.operating_system o where o.active), '[]'::jsonb),

    -- ── THE COMPANY BRAIN, AS ONE GRAPH ──────────────────────────────────────────────────────
    'graph', jsonb_build_object(
      'node_count', (select count(*) from public.graph_nodes),
      'edge_count', (select count(*) from public.graph_edges),
      'rebuilt_at', (select max(updated_at) from public.graph_nodes),
      'node_kinds', coalesce((select jsonb_agg(jsonb_build_object('kind', k.kind, 'n', k.n) order by k.n desc)
                     from (select kind, count(*) n from public.graph_nodes group by 1) k), '[]'::jsonb),
      'edge_kinds', coalesce((select jsonb_agg(jsonb_build_object('rel', e.rel, 'src_kind', e.src_kind, 'dst_kind', e.dst_kind, 'n', e.n) order by e.n desc)
                     from (select rel, src_kind, dst_kind, count(*) n from public.graph_edges group by 1,2,3) e), '[]'::jsonb),
      'nodes', coalesce((select jsonb_agg(jsonb_build_object('kind', n.kind, 'ref_id', n.ref_id, 'label', n.label) order by n.kind, n.label)
                 from (select * from public.graph_nodes order by kind, label limit 200) n), '[]'::jsonb),
      'edges', coalesce((select jsonb_agg(jsonb_build_object('src_kind', g.src_kind, 'src_ref', g.src_ref, 'rel', g.rel, 'dst_kind', g.dst_kind, 'dst_ref', g.dst_ref) order by g.src_kind, g.rel)
                 from (select * from public.graph_edges order by src_kind, rel limit 300) g), '[]'::jsonb)),

    -- ── THE AI BOARD ─────────────────────────────────────────────────────────────────────────
    'board', jsonb_build_object(
      'advisors', coalesce((select jsonb_agg(jsonb_build_object(
          'advisor_key', b.advisor_key, 'name', b.name, 'lens', b.lens, 'asks', b.asks, 'weight', b.weight)
        order by b.advisor_key) from public.board_advisor b where coalesce(b.active, true)), '[]'::jsonb),
      'opinion_count', (select count(*) from public.board_opinion),
      'opinions', coalesce((select jsonb_agg(jsonb_build_object(
          'subject', p.subject, 'advisor_key', p.advisor_key, 'recommendation', p.recommendation,
          'rationale', left(p.rationale, 300), 'confidence', p.confidence, 'at', p.created_at)
        order by p.created_at desc)
        from (select * from public.board_opinion order by created_at desc limit 12) p), '[]'::jsonb)),

    -- ── THE INDICES: MATURITY, MARKETPLACE HEALTH, ORGANISATIONAL ENERGY ─────────────────────
    -- THE ENGINE ITSELF HAD NO SCREEN (12 Aug 2026). 238 workflow runs and the only thing any
    -- surface showed was a count tile: "Workflows run today". Which processes are in flight, where
    -- each one is parked and WHO it is waiting on were not on any screen in the company, so the
    -- engine going from 5 completed runs to 131 was invisible except in the database.
    -- waiting_on is the resolved employee, not the raw actor_role - the whole point of the
    -- resolver work is that a step now names somebody the company can actually reach.
    'workflow_state', jsonb_build_object(
      'by_status', coalesce((select jsonb_object_agg(s.status, s.n)
          from (select status, count(*) n from public.workflow_run group by 1) s), '{}'::jsonb),
      'steps_delivered', (select count(*) from public.workflow_step_run
                             where output->>'worked_by' = 'workflow_dispatch'),
      'ready_now', (select count(*) from public.workflow_step_run sr
                      join public.workflow_run r on r.id = sr.workflow_run_id
                     where sr.status = 'ready' and r.status = 'running'),
      'in_flight', coalesce((select jsonb_agg(jsonb_build_object(
            'run_id', r.id,
            'workflow', coalesce(w.name, r.workflow_key),
            'step_no', sr.step_no,
            'step', sr.input->>'step',
            'gate', nullif(sr.input->>'gate', 'none'),
            'waiting_on', public.fn_workflow_actor_resolve(r.id, sr.actor),
            'addressed_as', coalesce(sr.input->>'addressed_as', sr.actor),
            'waiting_since', sr.started_at,
            'hours_waiting', round(extract(epoch from (now() - sr.started_at))/3600.0)
          ) order by sr.started_at)
        from (select r2.id, r2.workflow_key, sr2.step_no, sr2.input, sr2.actor, sr2.started_at
                from public.workflow_run r2
                join public.workflow_step_run sr2
                  on sr2.workflow_run_id = r2.id and sr2.status = 'ready'
               where r2.status = 'running'
               order by sr2.started_at
               limit 25) q
        join public.workflow_run r on r.id = q.id
        join public.workflow_step_run sr on sr.workflow_run_id = q.id and sr.step_no = q.step_no
        left join public.workflow w on w.workflow_key = r.workflow_key), '[]'::jsonb)),

    -- WHAT THE COMPANY'S PROCESSES ACTUALLY PRODUCED (11 Aug 2026).
    -- workflow_step_run.output holds 3,700-4,700 characters of real analysis per step, written by
    -- the named employee who owns that step. Before this key, the ONLY readers of that column were
    -- the two functions that write it; this surface counted rows per day and showed none of the
    -- work. A deliverable nobody reads is the defect this estate keeps reproducing.
    -- The outcome line is surfaced, not the body: the founder wants to see what his company decided,
    -- and the full text stays one query away for anything that needs it.
    'process_work', coalesce((select jsonb_agg(jsonb_build_object(
        'at', sr.finished_at,
        'workflow', coalesce(w.name, r.workflow_key),
        'step_no', sr.step_no,
        'step', sr.input->>'step',
        'employee', coalesce(sr.output->>'employee', sr.actor),
        'outcome', left(coalesce(sr.output->>'outcome',''), 400),
        'chars', length(coalesce(sr.output->>'deliverable','')),
        'confidence', sr.output->>'self_confidence',
        'mode', sr.output->>'mode') order by sr.finished_at desc)
      from public.workflow_step_run sr
      join public.workflow_run r on r.id = sr.workflow_run_id
      left join public.workflow w on w.workflow_key = r.workflow_key
     where sr.status = 'done'
       and coalesce(sr.output->>'deliverable','') <> ''
       and sr.finished_at > now() - interval '14 days'
     limit 40), '[]'::jsonb),

    'indices', coalesce((select jsonb_agg(jsonb_build_object(
        'index_name', c.index_name, 'score', c.score, 'band', c.band,
        'measured_on', c.measured_on, 'dimensions', c.dimensions) order by c.index_name)
      from public.company_index c
      where c.measured_on = (select max(measured_on) from public.company_index c2 where c2.index_name = c.index_name)), '[]'::jsonb),
    'marketplace_health', (select jsonb_build_object('score', c.score, 'band', c.band, 'measured_on', c.measured_on, 'dimensions', c.dimensions)
        from public.company_index c where c.index_name = 'marketplace_health'
        order by c.measured_on desc, c.id desc limit 1),

    -- ── EXECUTIVE REPLAY ─────────────────────────────────────────────────────────────────────
    'replay', jsonb_build_object(
      -- THE SIX TRACKS OF THE CHOSEN DAY, in one place for the first time. The day is the newest
      -- company_snapshot day, which is the chip the Replay card is already showing, so these
      -- counts describe what the founder is looking at rather than a different day's activity.
      'tracks', (select jsonb_build_object(
          'day', dd.day,
          'decisions',     (select count(*) from public.decision_log      x where x.created_at::date = dd.day),
          'conversations', (select count(*) from public.agent_chats       x where x.created_at::date = dd.day),
          'approvals',     (select count(*) from public.agent_actions     x where coalesce(x.decided_at, x.created_at)::date = dd.day),
          'workflows',     (select count(*) from public.workflow_step_run x where coalesce(x.started_at, x.finished_at)::date = dd.day),
          'kpis',          (select count(*) from public.metric_snapshot   x where x.taken_at::date = dd.day),
          'outcomes',      (select count(*) from public.outcome_record    x where coalesce(x.observed_at, x.created_at)::date = dd.day))
        from (select coalesce(max(snapshot_on), current_date - 1) as day from public.company_snapshot) dd),
      'days_on_file', (select count(*) from public.company_snapshot),
      'newest', (select max(snapshot_on) from public.company_snapshot),
      'company_snapshot', coalesce((select jsonb_agg(jsonb_build_object('snapshot_on', s.snapshot_on, 'state', s.state) order by s.snapshot_on desc)
        from (select * from public.company_snapshot order by snapshot_on desc limit 8) s), '[]'::jsonb)),

    -- ── REPUTATION ───────────────────────────────────────────────────────────────────────────
    'reputation', jsonb_build_object(
      'graded', (select count(*) from public.agent_reputation),
      'by_tier', coalesce((select jsonb_agg(jsonb_build_object('tier', t.tier, 'n', t.n) order by t.n desc)
                   from (select coalesce(tier, 'ungraded') tier, count(*) n from public.agent_reputation group by 1) t), '[]'::jsonb),
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
          'agent_key', r.agent_key, 'score', r.score, 'tier', r.tier, 'correctness', r.correctness,
          'reliability', r.reliability, 'cost_efficiency', r.cost_efficiency,
          'learning_speed', r.learning_speed, 'collaboration', r.collaboration)
        order by r.score desc nulls last)
        from (select * from public.agent_reputation order by score desc nulls last limit 20) r), '[]'::jsonb)),

    -- ── STRUCTURAL PROPOSALS AND THE LESSON LEDGER ───────────────────────────────────────────
    'evolution_proposals', coalesce((select jsonb_agg(jsonb_build_object(
        'id', e.id, 'trigger_kind', e.trigger_kind, 'subject', e.subject,
        'observation', left(e.observation, 240), 'proposal', left(e.proposal, 240),
        'change_class', e.change_class, 'status', e.status, 'decided_by', e.decided_by, 'at', e.created_at)
      order by e.created_at desc)
      from (select * from public.evolution_proposal order by created_at desc limit 12) e), '[]'::jsonb),
    -- THE FOUR STRATEGIC QUEUES, named by their own tables so the screen and the store cannot drift
    -- apart: evolution_proposal, challenge_record, opportunity and board_opinion. The spec's
    -- "strategic decisions rather than operational tasks" is exactly this set against the pending
    -- agent_actions queue the founder was being shown instead.
    'strategic_queues', jsonb_build_object(
      'evolution_proposal', (select count(*) from public.evolution_proposal where status = 'proposed'),
      'challenge_record', (select count(*) from public.challenge_record where responded_at is null),
      'opportunity', (select count(*) from public.opportunity where status = 'open'),
      'board_opinion', (select count(*) from public.board_opinion),
      'operational_pending', (select count(*) from public.agent_actions where status in ('pending','needs_review'))),
    'opportunity', coalesce((select jsonb_agg(jsonb_build_object(
        'id', o.id, 'kind', o.kind, 'title', o.title, 'detail', left(o.detail, 240),
        'value_score', o.value_score, 'effort', o.effort, 'confidence', o.confidence, 'at', o.created_at)
      order by o.value_score desc nulls last)
      from (select * from public.opportunity where status = 'open'
             order by value_score desc nulls last limit 10) o), '[]'::jsonb),

    -- The AI disagreeing with the founder, and what it offered instead. 47 challenges on file, 31
    -- carrying alternatives, and no surface has ever shown one.
    'challenge_record', coalesce((select jsonb_agg(jsonb_build_object(
        'id', h.id, 'proposal', h.proposal, 'proposed_by', h.proposed_by, 'challenged_by', h.challenged_by,
        'stance', h.stance, 'confidence', h.confidence, 'reasoning', left(h.reasoning, 320),
        'alternatives', h.alternatives, 'violates_principle', h.violates_principle,
        'violates_rank', h.violates_rank, 'founder_response', h.founder_response,
        'responded_at', h.responded_at, 'at', h.created_at)
      order by h.created_at desc)
      from (select * from public.challenge_record order by created_at desc limit 12) h), '[]'::jsonb),

    'institutional_memory', jsonb_build_object(
      'lessons', (select count(*) from public.institutional_memory),
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
          'kind', m.kind, 'headline', m.headline, 'outcome', m.outcome, 'lesson', left(m.detail, 240),
          'os_key', m.os_key, 'confidence', m.confidence, 'occurred_at', m.occurred_at)
        order by m.occurred_at desc nulls last)
        from (select * from public.institutional_memory order by occurred_at desc nulls last limit 12) m), '[]'::jsonb)),

    -- ── RESILIENCE ───────────────────────────────────────────────────────────────────────────
    'resilience', jsonb_build_object(
      'critical_capability', coalesce((select jsonb_agg(jsonb_build_object(
          'capability_key', c.capability_key, 'capability', c.capability, 'owner_dept', c.owner_dept,
          'test_kind', c.test_kind, 'last_verdict', c.last_verdict, 'last_checked', c.last_checked)
        order by c.capability_key) from public.critical_capability c), '[]'::jsonb),
      'continuity_plan', coalesce((select jsonb_agg(jsonb_build_object(
          'service', p.service, 'criticality', p.criticality, 'failure_mode', p.failure_mode,
          'fallback', p.fallback, 'recovery', p.recovery, 'rto_minutes', p.rto_minutes,
          'owner_agent', p.owner_agent, 'last_tested', p.last_tested)
        order by p.criticality, p.service) from public.continuity_plan p), '[]'::jsonb)),

    -- ── THE OPERATING MANUAL ─────────────────────────────────────────────────────────────────
    'operating_manual', jsonb_build_object(
      'runbooks', (select count(*) from public.os_runbooks),
      'by_category', coalesce((select jsonb_agg(jsonb_build_object('category', k.category, 'n', k.n) order by k.n desc)
                      from (select coalesce(category, 'uncategorised') category, count(*) n from public.os_runbooks group by 1) k), '[]'::jsonb),
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
          'slug', r.slug, 'title', r.title, 'category', r.category, 'when_to_use', left(r.when_to_use, 200), 'os_key', r.os_key)
        order by r.sort nulls last, r.slug)
        from (select * from public.os_runbooks order by sort nulls last, slug limit 24) r), '[]'::jsonb)),

    -- ── RESOURCE MOVEMENT, AUTONOMY, SUPPLY AND THE EVENT BUS ────────────────────────────────
    'allocation_change', coalesce((select jsonb_agg(jsonb_build_object(
        'resource', a.resource, 'subject', a.subject, 'from_value', a.from_value, 'to_value', a.to_value,
        'reason', left(a.reason, 200), 'policy', a.policy, 'reverted', a.reverted, 'at', a.created_at)
      order by a.created_at desc)
      from (select * from public.allocation_change order by created_at desc limit 12) a), '[]'::jsonb),
    'autonomy', jsonb_build_object(
      'changes', (select count(*) from public.autonomy_control_audit),
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
          'object', u.object, 'op', u.op, 'direction', u.direction, 'old_value', u.old_value,
          'new_value', u.new_value, 'reason', left(u.reason, 160), 'at', u.at)
        order by u.at desc)
        from (select * from public.autonomy_control_audit order by at desc limit 10) u), '[]'::jsonb)),
    'supply_health', jsonb_build_object(
      'snapshots', (select count(*) from public.supply_health_snapshots),
      'latest_period_end', (select max(period_end) from public.supply_health_snapshots),
      'coverage_gaps', coalesce((select jsonb_agg(to_jsonb(s) order by s.period_end desc)
        from (select * from public.supply_health_snapshots order by period_end desc limit 6) s), '[]'::jsonb)),
    'invite_schedule', coalesce((select jsonb_agg(jsonb_build_object(
        'day', i.day, 'planned', i.planned, 'sent', i.sent, 'status', i.status) order by i.day desc)
      from (select * from public.invite_schedule order by day desc limit 10) i), '[]'::jsonb),
    'events', jsonb_build_object(
      'total', (select count(*) from public.company_event),
      'last_7d', (select count(*) from public.company_event where occurred_at > now() - interval '7 days'),
      'by_class', coalesce((select jsonb_agg(jsonb_build_object('event_type', c.event_type, 'n', c.n) order by c.n desc)
                   from (select event_type, count(*) n from public.company_event
                          where occurred_at > now() - interval '30 days' group by 1) c), '[]'::jsonb)),

    -- ── MODEL MIX ────────────────────────────────────────────────────────────────────────────
    'model_mix', coalesce((select jsonb_agg(jsonb_build_object(
        'model_used', m.model_used, 'calls', m.calls, 'aed', m.aed, 'latency_ms', m.latency_ms,
        'cache_hits', m.cache_hits) order by m.aed desc)
      from (select coalesce(nullif(model_used,''),'unknown') model_used, count(*) calls,
                   round(coalesce(sum(cost_aed),0),4) aed,
                   round(avg(latency_ms)) latency_ms,
                   count(*) filter (where cached) cache_hits
              from public.ai_cost_log where occurred_at > now() - interval '30 days' group by 1) m), '[]'::jsonb),

    -- ── INFORMATION FLOWING BETWEEN THE TEN SYSTEMS ─────────────────────────────────────────
    -- Derived from what was actually DELIVERED, not from what os_interface declares: the declared
    -- outputs and inputs are disjoint sets and join to zero cross-OS edges. The consumer is
    -- event_delivery.os_key; the producer is company_event.actor resolved through its department,
    -- or the actor itself when the actor IS a department. Deliveries whose actor is machinery
    -- (system, a cron, the brief) are counted as unattributed rather than assigned to a system.
    'flow', (with res as (
        select d.os_key as to_os, d.event_type, d.delivered_at,
               coalesce((select od.os_key from public.org_agents a
                          join public.os_department od on od.dept_key = a.department
                         where a.agent_key = e.actor limit 1),
                        (select od2.os_key from public.os_department od2
                          where od2.dept_key = e.actor limit 1)) as from_os
          from public.event_delivery d
          join public.company_event e on e.id = d.event_id
         where d.os_key is not null and d.delivered_at > now() - interval '7 days')
      select jsonb_build_object(
        'window_days', 7,
        'deliveries', (select count(*) from res),
        'attributed', (select count(*) from res where from_os is not null),
        'unattributed', (select count(*) from res where from_os is null),
        'unroutable', (select count(*) from public.event_delivery
                        where unroutable_reason is not null
                          and delivered_at > now() - interval '7 days'),
        'nodes', coalesce((select jsonb_agg(jsonb_build_object(
            'os_key', o.os_key, 'num', o.num, 'name', o.name,
            'received', (select count(*) from res where res.to_os = o.os_key),
            'sent', (select count(*) from res where res.from_os = o.os_key)) order by o.num)
          from public.operating_system o where o.active), '[]'::jsonb),
        'edges', coalesce((select jsonb_agg(x) from (
            select from_os, to_os, count(*) as n,
                   count(distinct event_type) as event_types,
                   max(delivered_at) as newest,
                   (array_agg(distinct event_type))[1:3] as kinds
              from res where from_os is not null
             group by from_os, to_os order by count(*) desc limit 40) x), '[]'::jsonb))),

    'generated_at', now()
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_customer_360(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare c public.customers%rowtype; j jsonb;
  ltv numeric(18,2); deal_value numeric(18,2); reveals int;
  rfqs_total int; rfqs_active int; rfqs_done int; avg_budget numeric(18,2);
  last_act timestamptz; score int; cats text; docs jsonb := '[]'::jsonb; summary text;
begin
  select * into c from public.customers where id=p_id;
  if c.id is null then return jsonb_build_object('error','customer not found'); end if;

  select coalesce(sum(reveal_fee) filter (where fee_status='paid'),0), coalesce(sum(quote_amount),0), count(*)
    into ltv, deal_value, reveals from public.transactions where customer_id=p_id;
  select count(*), count(*) filter (where status not in ('completed','cancelled','closed','lost')),
         count(*) filter (where status in ('completed','closed') or outcome='completed'),
         coalesce(round(avg(nullif(expected_value,0)),2),0)
    into rfqs_total, rfqs_active, rfqs_done, avg_budget from public.inquiries where customer_id=p_id;
  select string_agg(distinct category, ', ') into cats from public.inquiries where customer_id=p_id and category is not null;

  select greatest(coalesce(max(i.created_at), c.created_at),
                  coalesce((select max(revealed_at) from public.transactions where customer_id=p_id), c.created_at),
                  c.created_at)
    into last_act from public.inquiries i where i.customer_id=p_id;
  last_act := coalesce(last_act, c.created_at);

  score := least(100, greatest(0,
      coalesce(rfqs_total,0)*12 + coalesce(reveals,0)*25 + round(coalesce(ltv,0)/20)::int
      + (case when last_act > now() - interval '30 days' then 15 else 0 end)));

  docs := coalesce((select jsonb_agg(jsonb_build_object('type','Drawing','name',coalesce(drawing_file_name,'drawing'),'path',drawing_file_path))
                    from public.inquiries where customer_id=p_id and drawing_file_path is not null),'[]'::jsonb);
  if c.signed_terms_path is not null then docs := docs || jsonb_build_object('type','Signed terms','name','terms','path',c.signed_terms_path); end if;

  summary := c.full_name||' joined '||to_char(c.created_at,'Mon YYYY')||'. '
    ||coalesce(rfqs_total,0)||' RFQ(s)'||coalesce(' across '||cats,'')||'. '
    ||coalesce(reveals,0)||' reveal(s), AED '||to_char(coalesce(ltv,0),'FM999999990.00')||' paid to date.'
    ||(case when avg_budget>0 then ' Avg project budget AED '||to_char(avg_budget,'FM999999990') else '' end)
    ||(case when c.banned then ' [BANNED]' when not coalesce(c.email_verified,false) then ' Email unverified.' else '' end);

  j := jsonb_build_object(
    'profile', jsonb_build_object('id',c.id,'full_name',c.full_name,'email',c.email,'phone',c.phone,
       'created_at',c.created_at,'phone_verified',c.phone_verified,'email_verified',c.email_verified,
       'banned',c.banned,'banned_reason',c.banned_reason,'whatsapp',jsonb_build_object('opt',c.whatsapp_opt,'confirmed',public.fn_whatsapp_destination('customer',c.id) is not null),'tos_accepted_at',c.tos_accepted_at,
       'chat_strikes',c.chat_strikes),
    'metrics', jsonb_build_object('ltv',ltv,'total_deal_value',deal_value,'reveals',reveals,
       'rfqs_total',rfqs_total,'rfqs_active',rfqs_active,'rfqs_completed',rfqs_done,
       'avg_project_budget',avg_budget,'relationship_score',score),
    'ai_summary', summary,
    'preferences', (
       with pref as (select p.preferences pj from public.customer_preference p
                       join public.customers cc on cc.id = p.customer_id
                      where p.customer_id = p_id and cc.tos_accepted_at is not null)
       select jsonb_build_object(
         'categories', coalesce((select pj->'stated'->'categories' from pref),
                                (select pj->'inferred'->'categories' from pref),
                                coalesce((select jsonb_agg(distinct category) from public.inquiries where customer_id=p_id and category is not null),'[]'::jsonb)),
         'emirates',   coalesce((select pj->'stated'->'emirates' from pref),
                                (select pj->'inferred'->'emirates' from pref),
                                coalesce((select jsonb_agg(distinct emirate) from public.inquiries where customer_id=p_id and emirate is not null),'[]'::jsonb)),
         'scope_type', (select pj->'inferred'->>'scope_type' from pref),
         'budget_aed_avg', (select pj->'inferred'->'budget_aed_avg' from pref),
         'remembered', exists(select 1 from pref))),
    'rfqs', coalesce((select jsonb_agg(jsonb_build_object('id',i.id,'category',i.category,'emirate',i.emirate,
       'status',i.status,'pipeline_stage',i.pipeline_stage,'budget',i.expected_value,
       'outcome',i.outcome,'created_at',i.created_at) order by i.created_at desc)
       from (select * from public.inquiries where customer_id=p_id order by created_at desc limit 15) i),'[]'::jsonb),
    'quotes', coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'amount',q.quote_amount,'status',q.status,'created_at',q.created_at) order by q.created_at desc)
       from public.quotes q join public.inquiries i on i.id=q.inquiry_id where i.customer_id=p_id),'[]'::jsonb),
    'transactions', coalesce((select jsonb_agg(jsonb_build_object('quote_amount',t.quote_amount,'reveal_fee',t.reveal_fee,'fee_status',t.fee_status,'revealed_at',t.revealed_at) order by t.revealed_at desc)
       from public.transactions t where t.customer_id=p_id),'[]'::jsonb),
    'documents', docs,
    'timeline', (select jsonb_agg(e order by e->>'at' desc) from (
        select jsonb_build_object('at',c.created_at,'event','Signed up') e
        union all select jsonb_build_object('at',i.created_at,'event','RFQ: '||coalesce(i.category,'inquiry')) from public.inquiries i where i.customer_id=p_id
        union all select jsonb_build_object('at',t.revealed_at,'event','Revealed supplier · AED '||coalesce(t.reveal_fee::text,'0')||' fee') from public.transactions t where t.customer_id=p_id and t.revealed_at is not null
      ) tl)
  );
  return j;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ws_customer_behavior()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'customers',        (select count(*) from customer_health),
    -- Averages over the real book. NULL when there is nobody to average, never 0.
    'avg_health',       (select round(avg(health)::numeric, 1)       from customer_health),
    'avg_engagement',   (select round(avg(engagement)::numeric, 1)   from customer_health),
    'avg_satisfaction', (select round(avg(satisfaction)::numeric, 1) from customer_health),
    'dormant',          (select count(*) from customer_health where coalesce(dormant, false)),
    'at_risk',          (select count(*) from customer_health where lower(coalesce(risk_tier,'')) in ('high','elevated','at_risk')),
    'with_rfqs',        (select count(*) from customer_health where coalesce(total_inq, 0) > 0),
    -- CHURN IS NOT MEASURED, AND SAYS SO RATHER THAN RETURNING A NUMBER. Every customer on this
    -- platform was created inside the last 30 days and none has completed a transaction, so there
    -- is no lapse to observe. A churn rate here would be arithmetic on an empty set.
    'churn_rate_pct',   null,
    'churn_note',       'Not measured: no customer is old enough to have lapsed and no transaction has completed, so there is nothing to compute a churn rate from.',
    'rows', coalesce((select jsonb_agg(jsonb_build_object(
              'customer_id', c.customer_id, 'name', c.full_name, 'email', c.email,
              'health', c.health, 'engagement', c.engagement, 'satisfaction', c.satisfaction,
              'progress', c.progress, 'service', c.service, 'risk_tier', c.risk_tier,
              'dormant', c.dormant, 'total_inq', c.total_inq, 'active_inq', c.active_inq,
              'stalled_inq', c.stalled_inq, 'last_activity', c.last_activity)
            order by c.health nulls last)
            from customer_health c), '[]'::jsonb),
    'generated_at', now()
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_customers()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      'total',(select count(*) from customers),
      'verified',(select count(*) from customers where phone_verified is true or email_verified is true),
      'banned',(select count(*) from customers where banned is true),
      'with_rfqs',(select count(distinct customer_id) from inquiries where customer_id is not null)
    ),
    'success', jsonb_build_object(
      'kpis', coalesce((select to_jsonb(k) from customer_kpis k),'{}'::jsonb),
      'open_escalations', (select count(*) from agent_actions where kind='customer_escalation' and status in ('pending','needs_review')),
      'attention', coalesce((select jsonb_agg(a) from (
          select jsonb_build_object('id',customer_id,'name',coalesce(full_name,email),'health',health,
            'engagement',engagement,'satisfaction',satisfaction,'progress',progress,'service',service,
            'risk_tier',risk_tier,'stalled',stalled_inq,'disputes',disputes,'dormant',dormant) a
          from customer_health where risk_tier in ('high','medium') order by health asc limit 10) t),'[]'::jsonb),
      'trend', coalesce((select jsonb_agg(jsonb_build_object('d',snapshot_date,'health',(kpis->>'avg_health')) order by snapshot_date)
          from (select snapshot_date, kpis from customer_kpi_snapshots order by snapshot_date desc limit 14) s),'[]'::jsonb)
    ),
    'rows', coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'full_name',c.full_name,'email',c.email,'phone',c.phone,
        'phone_verified',c.phone_verified,'email_verified',c.email_verified,'banned',c.banned,'created_at',c.created_at,
        'rfqs',(select count(*) from inquiries i where i.customer_id=c.id),
        'projects',(select count(*) from projects p where p.customer_id=c.id))) from (select * from customers order by created_at desc limit 100) c),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_documents()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      'documents',(select count(*) from documents),
      'inventory_total',(select count(*) from document_inventory),
      'dropbox_files',(select count(*) from dropbox_files where not is_folder),
      'indexed',(select count(*) from documents where indexed is true),
      -- a review a department owns is not pending for the founder (6 Sep 2026)
      'reviews_pending',(select count(*) from doc_reviews where coalesce(status,'')='pending' and owner_role is null),
      'versions',(select count(*) from doc_versions)
    ),
    'controller', jsonb_build_object(
      'health', (select (kpis->>'doc_health')::numeric from document_kpi_snapshots order by snapshot_date desc limit 1),
      'kpis', (select to_jsonb(k) from document_kpis k),
      'by_bucket', coalesce((select jsonb_agg(jsonb_build_object('bucket',bucket,'docs',c,'bytes',b,'past_retention',pr,'class',cls) order by c desc)
          from (select bucket, count(*) c, sum(bytes) b, count(*) filter (where past_retention) pr, max(retention_class) cls from document_inventory group by bucket) t),'[]'::jsonb),
      'dropbox', jsonb_build_object(
        'connected', (select (max(synced_at) is not null) from dropbox_files),
        'files', (select count(*) from dropbox_files where not is_folder),
        'folders', (select count(*) from dropbox_files where is_folder),
        'bytes', (select coalesce(sum(size),0) from dropbox_files),
        'last_sync', (select max(synced_at) from dropbox_files),
        'top_folders', coalesce((select jsonb_agg(jsonb_build_object('path',path,'items',n) order by n desc)
            from (select split_part(path,'/',2) path, count(*) n from dropbox_files where path like '/%/%' group by 1 order by 2 desc limit 8) t),'[]'::jsonb)
      ),
      'retention', coalesce((select jsonb_agg(jsonb_build_object('bucket',bucket,'class',class,'retention_days',retention_days) order by bucket) from retention_policy),'[]'::jsonb),
      'tasks', coalesce((select jsonb_agg(jsonb_build_object('title',title,'risk',risk,'reco',recommendation)) from agent_actions where agent='document_controller' and status in ('pending','needs_review')),'[]'::jsonb)
    ),
    -- bucket + path: what os_api `file` signs so the shell can open the row (6 Sep 2026)
    'documents', coalesce((select jsonb_agg(jsonb_build_object('id',id,'file_name',file_name,'kind',kind,'ref_table',ref_table,'ref_id',ref_id,'status',status,'indexed',indexed,'created_at',created_at,'bucket',bucket,'path',path)) from (select * from documents order by created_at desc limit 40) d),'[]'::jsonb),
    -- the section is titled "Reviews pending" and carries Approve/Reject: it lists pending, unowned rows only
    'reviews', coalesce((select jsonb_agg(jsonb_build_object('id',id,'file_name',file_name,'ai_category',ai_category,'ai_summary',ai_summary,'ai_confidence',ai_confidence,'status',status,'created_at',created_at)) from (select * from doc_reviews where coalesce(status,'')='pending' and owner_role is null order by created_at desc limit 20) r),'[]'::jsonb),
    'kinds', coalesce((select jsonb_agg(jsonb_build_object('key',k,'count',c) order by c desc) from (select coalesce(nullif(kind,''),'other') k, count(*) c from documents group by 1) kk),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_ea()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'today_events', a->'today'->'events',
    'reminders_due', a->'today'->'reminders_due',
    'upcoming_events', a->'upcoming_events',
    'open_tasks', a->'open_tasks',
    'overdue_tasks', (a->>'overdue_tasks')::int,
    'approvals_total', (a->'approvals_to_clear'->>'total')::int,
    'approvals_high_risk', (a->'approvals_to_clear'->>'high_risk')::int,
    'approvals_top', a->'approvals_to_clear'->'top',
    'recent_meetings', a->'recent_meetings'
  )
  from (select fn_ea_agenda(7) a) x;
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_exec()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'command', fn_os_command(),
    'tasks', coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'status',status,'priority',priority,'due',due_date,'entity',entity)) from (select * from crm_tasks where coalesce(status,'') not in ('done','cancelled') and created_at >= fn_os_fresh_start_at() order by created_at desc limit 8) t),'[]'::jsonb),
    'approvals', public.fn_founder_queue(6)->'waiting_on_you',
    'held', coalesce((select jsonb_agg(jsonb_build_object('id',id,'agent',agent,'title',title,'kind',kind,'kind_label',fn_ui_label('action_kind',kind),'holder',public.fn_action_holder(kind, agent),'risk',risk,'status',status,'created_at',created_at,'yours',false))
                from (select a.* from agent_actions a left join agent_action_kind_policy p on p.kind = a.kind
                       where a.status in ('pending','needs_review') and coalesce(p.policy,'') <> 'founder'
                         and a.created_at >= fn_os_fresh_start_at() order by a.created_at desc limit 6) a),'[]'::jsonb),
    'activity', coalesce((select jsonb_agg(jsonb_build_object('actor',actor,'kind',kind,'kind_label',fn_ui_label('action_kind',kind),'decision',decision,'confidence',confidence,'route_to',route_to,'created_at',created_at)) from (select * from decision_log where created_at >= fn_os_fresh_start_at() order by created_at desc limit 10) d),'[]'::jsonb),
    'notifications', coalesce((select jsonb_agg(jsonb_build_object('type',type,'type_label',fn_ui_label('notification_type',type),'subject',subject,'status',status,'created_at',created_at)) from (select * from notifications where created_at >= fn_os_fresh_start_at() order by created_at desc limit 6) n),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_exec_home()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with h as (select to_jsonb(public.fn_health_index()) j),
  gh as (
    select coalesce(
      (select 'monthly' where exists (select 1 from public.goal_period where horizon = 'monthly')),
      (select 'quarterly' where exists (select 1 from public.goal_period where horizon = 'quarterly')),
      'annual') hz
  ),
  g as (
    -- fn_goal_attainment handles the four ways the inline version was wrong (least() ignoring
    -- nulls, direction, period, row-count-as-goal-count). One copy, not two.
    select (a.j->>'pct')::numeric        pct,
           (a.j->>'goals_total')::int    n,
           (a.j->>'goals_measured')::int measured
      from gh, lateral (select public.fn_goal_attainment(gh.hz) j) a
  ),
  bott as (
    select coalesce(jsonb_agg(jsonb_build_object(
             'department', r.owner_dept, 'resource', r.resource, 'used_pct', r.used_pct,
             'state', r.state, 'committed', r.committed, 'capacity', r.capacity, 'unit', r.unit)
           order by r.used_pct desc nulls last), '[]'::jsonb) j
      from public.v_resource_pressure r where r.state in ('HALT', 'DEGRADE')
  ),
  dept as (
    select coalesce(jsonb_agg(jsonb_build_object(
             'department', coalesce(dh.department, e->>'label', e->>'key'),
             'dept_key', e->>'key',
             'runs', (e->'runs'),
             'busy', coalesce((e->>'runs')::int, 0) > 0,
             'health', dh.score, 'status', dh.status)
           order by coalesce((e->>'runs')::int, 0) desc), '[]'::jsonb) j
      from jsonb_array_elements(public.fn_agents_board()->'departments') e
      left join public.v_department_health dh on dh.dept_key = e->>'key'
  ),
  -- fn_founder_queue and fn_founder_refund_approvals_open were dropped earlier today with the rest
  -- of the founder-approval machinery: "all approvals are from CEO. nothing goes to me". The apply
  -- guard refused this file until these two calls came out, which is the guard doing its job -- a
  -- plpgsql body resolves its callees at RUN time, so without it this would have applied cleanly and
  -- thrown the first time the tile was rendered.
  fq as (select null::jsonb j),
  home as (select jsonb_build_object(
    'health_index',     (select (j->>'index')::numeric from h),
    'mood',             (select j->>'band' from h),
    'health_note',      (select j->>'note' from h),
    'revenue_today',    (select coalesce(sum(coalesce(reveal_fee, app_fee, 0)), 0)
                           from public.transactions where revealed_at::date = current_date),
    'revenue_30d',      (select coalesce(sum(coalesce(reveal_fee, app_fee, 0)), 0)
                           from public.transactions where revealed_at > now() - interval '30 days'),
    'goal_progress_pct', (select pct from g),
    'goal_horizon',     (select hz from gh),
    'goal_count',       (select n from g),
    'goal_measured',    (select measured from g),
    'customers_active', (select count(*) from public.customers where coalesce(banned, false) = false),
    'suppliers_active', coalesce((public.fn_marketplace_analytics()->>'active_suppliers_30d')::int, 0),
    'employees',        (select count(*) from public.org_agents where active),
    'employees_working', (select count(*) from public.org_agents o where o.active and (
                             exists (select 1 from public.agent_runs r
                                      where r.agent = o.agent_key and r.started_at > now() - interval '24 hours')
                          or exists (select 1 from public.agent_memory m
                                      where m.agent_key = o.agent_key and m.created_at > now() - interval '24 hours')
                          or exists (select 1 from public.agent_chats c
                                      where c.agent_key = o.agent_key and c.created_at > now() - interval '24 hours'))),
    'bottlenecks',      (select j from bott),
    'departments',      (select j from dept),
    'workflow_runs_24h', (select count(*) from public.workflow_run
                           where coalesce(started_at, created_at) > now() - interval '24 hours'),
    -- 9 SEP 2026 -- PHASE MACHINERY REMOVED. A 'handoffs_24h' key stood here counting
    -- the kernel handoff-run table over 24 hours. That table is deleted in this sweep, so the key is
    -- gone rather than pinned to a hard-coded zero: an absent number and a measured zero are
    -- different statements, and the OS must not be told "no handoffs" by a routine that can no
    -- longer count them. Any surface reading home.handoffs_24h now reads undefined; the founder
    -- has accepted that the website may break in the meantime and be rebuilt correctly.
    'events_delivered_24h', (select count(*) from public.event_delivery
                              where delivered_at > now() - interval '24 hours'),
    'knowledge_revisions_7d', (select count(*) from public.kb_revisions
                                where created_at > now() - interval '7 days'),
    'uptime_pct_24h', (select round(100.0 * count(*) filter (where verdict = 'ALIVE')
                                    / nullif(count(*), 0), 1)
                         from public.edge_health_probe where checked_at > now() - interval '24 hours'),
    'leads_total',      (select count(*) from public.leads),
    'agent_runs_24h',   (select count(*) from public.agent_runs where started_at > now() - interval '24 hours'),
    'events_24h',       (select count(*) from public.company_event where occurred_at > now() - interval '24 hours'),
    -- HIS decisions: refund approvals and nothing else. The 14 open agent_actions this used to
    -- count are held with their roles and reported under that name.
    -- HIS decision queue is empty by ruling, not by measurement: nothing is routed to him at all.
    'decisions_open',   0,
    'held_with_roles',  (select (j->>'held_with_roles_total')::int from fq),
    'held_with',        (select j->'held_with_roles' from fq),
    -- ONE definition of an open task: public.v_org_open_tasks (see one_definition_of_an_open_task.sql).
    'tasks_open',       (select count(*) from public.v_org_open_tasks),
    'generated_at',     now()
  ) j)
  -- THE OVERNIGHT BRIEF, AS ONE SENTENCE. Written here so the Console's "speak the overnight brief"
  -- button and the founder command channel ("status", "brief", "how are we doing") read the SAME
  -- text from the SAME figures, instead of one composing it in the browser and the other having no
  -- answer at all (6 Sep 2026: "status" came back as "clarification required").
  select h.j || jsonb_build_object('brief_text',
       'Company health ' || coalesce(h.j->>'health_index', 'unknown') || ', mood ' || coalesce(h.j->>'mood', 'unknown') || '. '
    || 'Revenue today ' || coalesce(h.j->>'revenue_today', '0') || ' dirhams, ' || coalesce(h.j->>'revenue_30d', '0') || ' over thirty days. '
    || coalesce(h.j->>'suppliers_active', '0') || ' active suppliers, ' || coalesce(h.j->>'customers_active', '0') || ' active customers. '
    || coalesce(h.j->>'employees_working', '0') || ' of ' || coalesce(h.j->>'employees', '0') || ' AI employees worked overnight. '
    || 'Goal progress ' || coalesce(h.j->>'goal_progress_pct', '0') || ' percent. '
    || coalesce(h.j->>'tasks_open', '0') || ' open tasks across every department. '
    || case when jsonb_array_length(coalesce(h.j->'bottlenecks', '[]'::jsonb)) > 0
            then jsonb_array_length(h.j->'bottlenecks')::text || ' departments are over capacity.'
            else 'No department is over capacity.' end)
  from home h;
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_finance()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  cash_total numeric(18,2); rev_total numeric(18,2); exp_total numeric(18,2);
  rev30 numeric(18,2); exp30 numeric(18,2); monthly_burn numeric(18,2); runway numeric(18,1);
  j jsonb;
begin
  select coalesce(sum(balance),0) into cash_total from public.gl_account_balances where code in ('1000','1050');
  select coalesce(sum(balance),0) into rev_total from public.gl_account_balances where type='revenue';
  select coalesce(sum(balance),0) into exp_total from public.gl_account_balances where type='expense';

  -- 30-day run-rate (posted activity)
  select
    coalesce(sum(case when ga.type='revenue' then l.credit-l.debit else 0 end),0),
    coalesce(sum(case when ga.type='expense' then l.debit-l.credit else 0 end),0)
    into rev30, exp30
  from public.gl_journal_lines l
  join public.gl_journal j2 on j2.id=l.journal_id and j2.status='posted'
  join public.gl_accounts ga on ga.code=l.account_code
  where j2.entry_date >= current_date - 30;

  monthly_burn := exp30 - rev30;                       -- net cash burn (positive = burning)
  runway := case when monthly_burn > 0 and cash_total > 0 then round(cash_total/monthly_burn,1) else null end;

  j := jsonb_build_object(
    'as_of', now(),
    'cash', jsonb_build_object(
      'total', cash_total,
      'accounts', coalesce((select jsonb_agg(jsonb_build_object('code',code,'name',name,'balance',balance) order by code)
                   from public.gl_account_balances where code in ('1000','1050','1100','1110','1150','1500','1600')),'[]'::jsonb)
    ),
    'pnl', jsonb_build_object(
      'revenue', rev_total, 'expenses', exp_total, 'net_income', rev_total-exp_total,
      'margin_pct', case when rev_total>0 then round(100.0*(rev_total-exp_total)/rev_total,1) else null end
    ),
    'run_rate', jsonb_build_object(
      'revenue_30d', rev30, 'expense_30d', exp30, 'net_30d', rev30-exp30,
      'arr_estimate', round(rev30*12,2), 'monthly_burn', monthly_burn,
      'runway_months', runway
    ),
    'monetization', jsonb_build_object(
      'reveal_fees', (select coalesce(balance,0) from public.gl_account_balances where code='4000'),
      'commissions', (select coalesce(balance,0) from public.gl_account_balances where code='4100'),
      'registration', (select coalesce(balance,0) from public.gl_account_balances where code='4200'),
      'stripe_fees', (select coalesce(balance,0) from public.gl_account_balances where code='6100')
    ),
    'revenue_breakdown', coalesce((select jsonb_agg(jsonb_build_object('code',code,'name',name,'amount',balance) order by balance desc)
        from public.gl_account_balances where type='revenue' and balance<>0),'[]'::jsonb),
    'expense_breakdown', coalesce((select jsonb_agg(jsonb_build_object('code',code,'name',name,'amount',balance) order by balance desc)
        from public.gl_account_balances where type='expense' and balance<>0),'[]'::jsonb),
    'receivables', jsonb_build_object(
      'commission_receivable', (select coalesce(balance,0) from public.gl_account_balances where code='1110'),
      'trade_receivable', (select coalesce(balance,0) from public.gl_account_balances where code='1100'),
      'overdue_commissions', (select coalesce(sum(amount_due),0) from public.supplier_dues
                              where public.fn_supplier_due_is_owed(status, paid_at) and coalesce(due_date,reveal_date) < current_date)
    ),
    'payables', jsonb_build_object(
      'ap_open', (select coalesce(sum(total-amount_paid),0) from public.ap_bills where status in ('open','partial')),
      'aging', coalesce((select jsonb_agg(to_jsonb(a)) from public.ap_aging a),'[]'::jsonb)
    ),
    'cashflow', coalesce((
      select jsonb_agg(x order by x->>'month')
      from (
        select jsonb_build_object(
          'month', to_char(date_trunc('month',j3.entry_date),'YYYY-MM'),
          'inflow', sum(l.debit), 'outflow', sum(l.credit), 'net', sum(l.debit-l.credit)
        ) x
        from public.gl_journal_lines l
        join public.gl_journal j3 on j3.id=l.journal_id and j3.status='posted'
        where l.account_code in ('1000','1050')
          and j3.entry_date >= (date_trunc('month',current_date) - interval '5 months')
        group by date_trunc('month',j3.entry_date)
      ) s
    ),'[]'::jsonb),
    'budgets', coalesce((select jsonb_agg(to_jsonb(b)) from public.budget_vs_actual_summary b),'[]'::jsonb)
  );
  j := j || jsonb_build_object('ai', jsonb_build_object(
    'kpis', (select to_jsonb(k) from public.finance_kpis k),
    'forecast', public.fn_finance_forecast(),
    'health', (select (kpis->>'health')::numeric from public.finance_kpi_snapshots order by snapshot_date desc limit 1),
    'open_alerts', (select count(*) from public.agent_actions where agent='finance_ai' and status in ('pending','needs_review')),
    'alerts', coalesce((select jsonb_agg(jsonb_build_object('signal',detail->>'signal','risk',risk,'title',title,'reco',recommendation))
        from public.agent_actions where agent='finance_ai' and status in ('pending','needs_review')),'[]'::jsonb),
    'trend', coalesce((select jsonb_agg(jsonb_build_object('d',snapshot_date,'health',(kpis->>'health'),'cash',(kpis->>'cash')) order by snapshot_date)
        from (select snapshot_date,kpis from public.finance_kpi_snapshots order by snapshot_date desc limit 14) s),'[]'::jsonb)
  ));
  return j;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ws_fraud()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      'open_flags', (select count(*) from fraud_flags where coalesce(status,'open') not in ('dismissed','resolved','closed')),
      'high_severity', (select count(*) from fraud_flags where lower(coalesce(severity,'')) in ('high','critical') and coalesce(status,'open') not in ('dismissed','resolved','closed')),
      'flags_7d', (select count(*) from fraud_flags where created_at > now() - interval '7 days'),
      'banned_actors', (select (select count(*) from customers where banned) + (select count(*) from leads where banned))
    ),
    'open_flags', (select coalesce(jsonb_agg(f order by f.created desc),'[]'::jsonb) from (
        select kind, subject_type, subject_id, coalesce(severity,'—') severity, coalesce(status,'open') status,
               to_char(created_at,'YYYY-MM-DD HH24:MI') created, detail
        from fraud_flags where coalesce(status,'open') not in ('dismissed','resolved','closed')
        order by created_at desc limit 100) f),
    'banned', (select coalesce(jsonb_agg(b),'[]'::jsonb) from (
        select 'customer' kind, id::text subject_id, full_name name, banned_reason reason from customers where banned
        union all
        select 'supplier', id::text, company_name, banned_reason from leads where banned limit 100) b)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_governance()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    -- governance_kpis.open_for_review counts every open agent_action; overridden here with the
    -- founder's real number and the held count published beside it under its own name.
    'kpis', (select to_jsonb(k) from public.governance_kpis k)
            || jsonb_build_object('open_for_review', public.fn_founder_refund_approvals_open(),
                                  'held_with_roles', (public.fn_founder_queue(1)->>'held_with_roles_total')::int),
    'universal_rules', (select universal_rules from public.agent_governance where active order by version desc limit 1),
    'response_structure', (select response_structure from public.agent_governance where active order by version desc limit 1),
    'recent_escalations', (select coalesce(jsonb_agg(e),'[]'::jsonb) from (
        select id, agent, title, coalesce(escalation_reason,'—') as reason, confidence,
               public.fn_action_policies(kind, confidence) as policies,
               public.fn_owning_os(agent) as os,
               public.fn_action_holder(kind, agent) as holder,
               false as yours,
               (select d.alternatives from public.decision_log d where d.id = decision_log_id) as alternatives,
               case when decided_at is not null
        then coalesce(status,'decided') || ' by ' || coalesce(decided_by,'the system') || ' on ' || decided_at::date
        else 'held with ' || public.fn_action_holder(kind, agent) || ' since ' || created_at::date end as outcome,
               to_char(created_at,'YYYY-MM-DD') as created
        from public.agent_actions
        where escalated
          and status in ('pending','needs_review')
          and created_at >= public.fn_os_fresh_start_at()
        order by created_at desc limit 15) e),
    'agent_coverage', (select coalesce(jsonb_agg(c),'[]'::jsonb) from (
        select ca.name as agent, (ca.persona is not null) as has_persona,
               exists(select 1 from public.agent_knowledge k where k.agent_key='cat:'||ca.slug or k.agent_key=ca.slug) as has_knowledge,
               (select count(*) from public.agent_actions a where a.agent=ca.slug) as audit_items
        from public.category_agents ca where ca.active order by ca.name limit 60) c),
    'fresh_start_at', public.fn_os_fresh_start_at()
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_intelligence()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with mat as (
    -- The company maturity index, in measurement order. This is the only series in the estate long
    -- enough to carry a trajectory, and it is rebuilt nightly.
    select measured_on, score from public.company_index
     where index_name = 'company_maturity'
     order by measured_on
  ), steps as (
    select (score - lag(score) over (order by measured_on))::double precision dx from mat
  ), moments as (
    select count(*)::int n,
           avg(dx) mu,
           coalesce(stddev_samp(dx), 0) sd
      from steps where dx is not null
  )
  select jsonb_build_object(

    -- ── OPPORTUNITIES ────────────────────────────────────────────────────────────────────────
    'opportunities', jsonb_build_object(
      'open', (select count(*) from public.opportunity where status = 'open'),
      'total', (select count(*) from public.opportunity),
      'newest', (select max(created_at) from public.opportunity),
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
                 'id', o.id, 'kind', o.kind, 'title', o.title, 'detail', o.detail,
                 'value_score', o.value_score, 'effort', o.effort, 'confidence', o.confidence,
                 'detected_by', o.detected_by, 'created_at', o.created_at)
               order by o.value_score desc nulls last, o.created_at desc)
             from public.opportunity o where o.status = 'open'), '[]'::jsonb)
    ),

    -- ── COMPETITORS ──────────────────────────────────────────────────────────────────────────
    'competitors', jsonb_build_object(
      'total', (select count(*) from public.competitor),
      'by_threat', coalesce((select jsonb_agg(jsonb_build_object('level', t.threat_level, 'n', t.n)
                     order by case t.threat_level when 'high' then 1 when 'medium' then 2 else 3 end)
                   from (select coalesce(nullif(threat_level, ''), 'unrated') threat_level, count(*) n
                           from public.competitor group by 1) t), '[]'::jsonb),
      'anonymity_rivals', (select count(*) from public.competitor where offers_anonymity is true),
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
                 'id', c.id, 'name', c.name, 'url', c.url, 'kind', c.kind,
                 'threat_level', c.threat_level, 'overlap', c.overlap, 'strength', c.strength,
                 'weakness', c.weakness, 'offers_anonymity', c.offers_anonymity,
                 'verified_at', c.verified_at)
               order by case coalesce(c.threat_level, '') when 'high' then 1 when 'medium' then 2 else 3 end, c.name)
             from public.competitor c), '[]'::jsonb),
      'positions', coalesce((select jsonb_agg(jsonb_build_object(
                 'dimension', p.dimension, 'quotesdone', p.quotesdone,
                 'market_norm', p.market_norm, 'verdict', p.verdict) order by p.id)
             from public.competitive_position p), '[]'::jsonb)
    ),

    -- ── AI SPENDING ──────────────────────────────────────────────────────────────────────────
    -- Every model call the company has paid for, in the window the spec's own cost row (#8) uses.
    'ai_spending', jsonb_build_object(
      'window_days', 30,
      'calls_30d', (select count(*) from public.ai_cost_log where occurred_at > now() - interval '30 days'),
      'total_aed', (select round(coalesce(sum(cost_aed), 0), 4) from public.ai_cost_log where occurred_at > now() - interval '30 days'),
      'failed_30d', (select count(*) from public.ai_cost_log where occurred_at > now() - interval '30 days' and ok is false),
      'cache_hits_30d', (select count(*) from public.ai_cost_log where occurred_at > now() - interval '30 days' and cached is true),
      'cheaper_available_30d', (select count(*) from public.ai_cost_log where occurred_at > now() - interval '30 days' and could_be_cheaper is true),
      'by_model', coalesce((select jsonb_agg(jsonb_build_object('model', m.model_used, 'calls', m.calls, 'aed', m.aed)
                    order by m.aed desc)
                  from (select coalesce(nullif(model_used, ''), 'unknown') model_used, count(*) calls,
                               round(coalesce(sum(cost_aed), 0), 4) aed
                          from public.ai_cost_log where occurred_at > now() - interval '30 days'
                         group by 1) m), '[]'::jsonb),
      'by_dept', coalesce((select jsonb_agg(jsonb_build_object('dept', d.dept_key, 'calls', d.calls, 'aed', d.aed)
                    order by d.aed desc)
                  from (select coalesce(nullif(dept_key, ''), 'unattributed') dept_key, count(*) calls,
                               round(coalesce(sum(cost_aed), 0), 4) aed
                          from public.ai_cost_log where occurred_at > now() - interval '30 days'
                         group by 1) d), '[]'::jsonb),
      'daily', coalesce((select jsonb_agg(jsonb_build_object('d', x.d, 'aed', x.aed, 'calls', x.calls) order by x.d)
                  from (select occurred_at::date d, round(coalesce(sum(cost_aed), 0), 4) aed, count(*) calls
                          from public.ai_cost_log where occurred_at > now() - interval '30 days'
                         group by 1) x), '[]'::jsonb)
    ),

    -- ── GROWTH PROBABILITY ───────────────────────────────────────────────────────────────────
    -- Not a point estimate dressed up as a forecast. The company maturity index is measured
    -- nightly; its daily changes give a drift and a volatility, and those give the probability the
    -- index is higher in 30 days than it is today under a random-walk-with-drift model. The
    -- logistic form is the standard approximation to the normal CDF (max error ~0.01), which is far
    -- below the uncertainty in a 13-point sample — and the sample size travels with the number so
    -- nobody can read it as more than it is.
    'growth_probability', (select jsonb_build_object(
        'horizon_days', 30,
        'observations', m.n,
        'index_name', 'company_maturity',
        'index_now', (select score from mat order by measured_on desc limit 1),
        'index_first', (select score from mat order by measured_on limit 1),
        'window_from', (select min(measured_on) from mat),
        'window_to', (select max(measured_on) from mat),
        'drift_per_day', round(m.mu::numeric, 4),
        'volatility_per_day', round(m.sd::numeric, 4),
        'growth_probability_pct', case when m.n < 3 or m.sd = 0 then null
            else round((100.0 / (1 + exp(-1.702 * (m.mu * sqrt(30.0) / m.sd))))::numeric, 1) end,
        'method', 'P(index in 30d > index today), from the measured daily drift and volatility of the company maturity index; random walk with drift, logistic approximation to the normal CDF'
      ) from moments m),

    'generated_at', now()
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_knowledge()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      'chunks',(select coalesce(sum(chunks),0) from kb_category_stats),
      'document_chunks',(select coalesce(sum(chunks),0) from kb_category_stats where source_kind='document'),
      'categories',(select count(distinct category) from kb_category_stats),
      'category_specs',(select count(*) from catalog_supplier_categories),
      'stats_as_of',(select max(refreshed_at) from kb_category_stats)
    ),
    'curator', jsonb_build_object(
      'health', (select (kpis->>'health')::numeric from knowledge_kpi_snapshots order by snapshot_date desc limit 1),
      'coverage_pct', k.coverage_pct, 'knowledge_coverage_pct', k.knowledge_coverage_pct, 'playbook_coverage_pct', k.playbook_coverage_pct,
      'accuracy_pct', k.accuracy_pct, 'freshness_pct', k.freshness_pct, 'usage_reach_pct', k.usage_reach_pct,
      'regulations', k.regulations, 'regulations_pending', k.regulations_pending, 'standards', k.standards, 'manufacturers', k.manufacturers, 'brands', k.brands, 'materials', k.materials, 'playbooks', k.playbooks,
      'open_items', (select count(*) from agent_actions where agent='knowledge_curator' and status in ('pending','needs_review')),
      'tasks', coalesce((select jsonb_agg(jsonb_build_object('title',title,'risk',risk,'reco',recommendation))
          from agent_actions where agent='knowledge_curator' and status in ('pending','needs_review')),'[]'::jsonb)
    ),
    'reg_library', jsonb_build_object(
      'coverage', (select to_jsonb(rc) from reg_coverage rc),
      'indexed', coalesce((select jsonb_agg(jsonb_build_object('authority',authority,'code',code_name,'domain',domain) order by authority) from reg_catalog where status='indexed'),'[]'::jsonb),
      'missing', coalesce((select jsonb_agg(jsonb_build_object('authority',authority,'code',code_name,'domain',domain,'priority',priority,'status',status) order by priority, authority) from reg_catalog where copyright='free' and status<>'indexed'),'[]'::jsonb),
      'reference_only', coalesce((select jsonb_agg(jsonb_build_object('authority',authority,'code',code_name) order by authority) from reg_catalog where copyright='copyrighted'),'[]'::jsonb)
    ),
    'regulations', coalesce((select jsonb_agg(jsonb_build_object('title',title,'status',authority||coalesce(' · '||status,''),'source_url',source_url) order by coalesce(effective_date, created_at) desc)
        from (select * from regulations order by coalesce(effective_date, created_at) desc limit 20) rg),'[]'::jsonb),
    -- 6 SEP 2026: category counts come from kb_category_stats (refreshed every 30 min), not from a
    -- GROUP BY over 2.7M rows per click.
    'categories', coalesce((select jsonb_agg(jsonb_build_object('key',cat,'count',c) order by c desc) from (
        select coalesce(nullif(regexp_replace(category,'^cat:',''),''),'general') cat, sum(chunks) c from kb_category_stats group by 1 order by 2 desc limit 16) kk),'[]'::jsonb),
    'coverage', coalesce((select jsonb_agg(jsonb_build_object('category',v.category,'label',v.label,'chunks',v.chunks,'status',v.status) order by v.chunks asc, v.num)
        from v_kb_coverage v),'[]'::jsonb),
    'coverage_kpis', jsonb_build_object(
        'gaps',(select count(*) from v_kb_coverage where status='gap'),
        'thin',(select count(*) from v_kb_coverage where status='thin'),
        'covered',(select count(*) from v_kb_coverage where status='covered'),
        'total',(select count(*) from v_kb_coverage)
    ),
    -- WHICH KNOWLEDGE WAS ACTUALLY USED, and by whom. agent_brain writes a row here on every
    -- retrieval; until now nothing read them back, so "the knowledge is being used" was an
    -- assertion rather than something the founder could check.
    'used', coalesce((select jsonb_agg(jsonb_build_object(
        'agent', u.agent, 'query', left(coalesce(u.query,''), 90),
        'category', u.category, 'at', u.created_at) order by u.created_at desc)
      from (select * from kb_usage_log order by created_at desc limit 25) u),'[]'::jsonb),
    'used_kpis', jsonb_build_object(
      'lookups_7d', (select count(*) from kb_usage_log where created_at > now() - interval '7 days'),
      'agents_7d', (select count(distinct agent) from kb_usage_log where created_at > now() - interval '7 days'),
      'categories_7d', (select count(distinct category) from kb_usage_log
                         where created_at > now() - interval '7 days' and category is not null)
    ),
    'recent', coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'category',category,'citation',citation)) from (select * from kb_chunks order by created_at desc limit 20) c),'[]'::jsonb)
  )
  from knowledge_kpis k;
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_live_company()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(

    -- ── THE PATH: milestone by milestone, with the steps inside each ─────────────────────────
    'goal_path', coalesce((select jsonb_agg(jsonb_build_object(
        'milestone', v.label, 'year_no', v.year_no, 'statement', v.statement,
        'steps', (select coalesce(jsonb_agg(jsonb_build_object(
                     'step', g.goal, 'metric', g.metric, 'target', g.target_value,
                     'unit', g.unit, 'owner_dept', g.owner_dept,
                     'actual', (select p.actual_value from public.goal_period p
                                 where p.goal_key = g.key order by p.updated_at desc limit 1))
                   order by g.sort nulls last), '[]'::jsonb)
                   from public.company_goals g
                  where g.active and coalesce(g.horizon, 'year_' || v.year_no::text) ~* ('year_?' || v.year_no::text)))
      order by v.year_no)
      from public.vision_horizon v where v.active), '[]'::jsonb),
    'roadmap_summary', (select count(*) from public.vision_horizon where active),

    -- ── THE HANDOFF CHAIN: work passing from department to department ────────────────────────
    'handoff_chain', coalesce((select jsonb_agg(jsonb_build_object(
        'id', c.id, 'subject_type', c.subject_type, 'subject_id', c.subject_id,
        'from_dept', c.dept_key, 'hop', c.stage, 'author_agent', c.author_agent,
        'to_dept', (select g.department from public.org_agents g where g.agent_key = c.reviewer_agent limit 1),
        'reviewer_agent', c.reviewer_agent, 'decision', c.decision,
        'reason', left(coalesce(c.reason, ''), 200), 'confidence', c.confidence,
        'delegated_from', c.delegated_from, 'at', c.created_at)
      order by c.created_at desc)
      from (select * from public.review_chain order by created_at desc limit 25) c), '[]'::jsonb),
    'handoffs_total', (select count(*) from public.review_chain),
    'handoff_stages', coalesce((select jsonb_agg(jsonb_build_object('hop', s.stage, 'n', s.n) order by s.n desc)
      from (select stage, count(*) n from public.review_chain group by 1) s), '[]'::jsonb),

    -- Where an event actually landed, which is the other half of the same sequence.
    'event_delivery', coalesce((select jsonb_agg(jsonb_build_object(
        'event_type', e.event_type, 'to_dept', (select g.department from public.org_agents g where g.agent_key = e.agent_key limit 1),
        'agent_key', e.agent_key, 'os_key', e.os_key, 'delivered_at', e.delivered_at,
        'unroutable_reason', e.unroutable_reason) order by e.delivered_at desc)
      from (select * from public.event_delivery order by delivered_at desc limit 15) e), '[]'::jsonb),

    -- ── THE RISK REGISTER ────────────────────────────────────────────────────────────────────
    'risk_register', coalesce((select jsonb_agg(jsonb_build_object(
        'id', r.id, 'risk', r.risk, 'category', r.category, 'dept_key', r.dept_key,
        'probability', r.probability, 'impact', r.impact, 'owner_agent', r.owner_agent,
        'mitigation', left(coalesce(r.mitigation, ''), 240), 'status', r.status,
        'review_due', r.review_due)
      -- probability and impact are TEXT on this table, not numbers, so they cannot be multiplied
      -- into a score here. Ordered by review urgency instead, and both values travel to the screen.
      order by r.review_due nulls last, r.updated_at desc nulls last)
      from public.risk_register r where coalesce(r.status, '') <> 'closed'), '[]'::jsonb),

    -- ── INFRASTRUCTURE, the last twin class with no reader ───────────────────────────────────
    -- edge_health_probe is the thirteenth twin object class and the only one nothing the browser
    -- can reach had ever read, so the founder's twin was complete except for the machine it runs on.
    'infrastructure', jsonb_build_object(
      'probes', (select count(*) from public.edge_health_probe),
      'rows', coalesce((select jsonb_agg(to_jsonb(p) order by p.id desc)
        from (select * from public.edge_health_probe order by id desc limit 12) p), '[]'::jsonb)),

    -- ── DEPARTMENT HEALTH, for the twin ──────────────────────────────────────────────────────
    'department_health', coalesce((select jsonb_agg(jsonb_build_object(
        'dept_key', h.dept_key, 'department', h.department, 'score', h.score,
        'status', h.status, 'basis', h.basis) order by h.score nulls first)
      from public.v_department_health h), '[]'::jsonb),

    'generated_at', now()
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_marketing()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'health', (select (kpis->>'health')::numeric from marketing_snapshots order by snapshot_date desc limit 1),
    'inquiries_30d', k.inquiries_30d, 'quoted_30d', k.quoted_30d, 'revealed_30d', k.revealed_30d,
    'revenue_30d', k.revenue_30d, 'inq_to_quote_pct', k.inq_to_quote_pct, 'quote_to_reveal_pct', k.quote_to_reveal_pct,
    'blog_published', k.blog_published, 'drafts_pending', k.drafts_pending,
    'social_staged', k.social_staged, 'social_published', k.social_published,
    'seo_pages', k.seo_pages, 'seo_gaps', k.seo_gaps, 'supply_gaps', k.supply_gaps,
    'leads_total', k.leads_total, 'outreach_sent', k.outreach_sent,
    'meta', jsonb_build_object(
      'spend_30d', k.meta_spend_30d, 'clicks_30d', k.meta_clicks_30d, 'results_30d', k.meta_results_30d,
      'impressions_30d', k.meta_impressions_30d, 'active_campaigns', k.meta_active_campaigns,
      'cpl', k.meta_cpl, 'roi', k.meta_roi,
      'sync', (select case when (select value from app_secrets where key='meta_access_token') is not null then 'connected' else 'awaiting_token' end),
      'campaigns', coalesce((select jsonb_agg(jsonb_build_object('name',campaign_name,'status',effective_status,'spend',spend,'clicks',clicks,'results',results))
          from meta_insights where time_window='last_30d' and campaign_name ilike '%quotesdone%'),'[]'::jsonb)
    ),
    'priorities', coalesce((select plan->'priorities' from marketing_snapshots order by snapshot_date desc limit 1),'[]'::jsonb),
    'push_supply', coalesce((select jsonb_agg(jsonb_build_object('category',category,'inquiries_90d',inquiries_90d,'suppliers',suppliers) order by inquiries_90d desc)
        from (select * from marketing_category_demand where inquiries_90d>0 and suppliers=0 order by inquiries_90d desc limit 10) t),'[]'::jsonb),
    'recommendations', coalesce((select jsonb_agg(jsonb_build_object('title',title,'risk',risk,'reco',recommendation))
        from agent_actions where agent='marketing_ai' and status in ('pending','needs_review')),'[]'::jsonb)
  )
  from marketing_kpis k;
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_marketplace()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      'rfqs',(select count(*) from inquiries),
      'active',(select count(*) from inquiries where coalesce(status,'') not in ('completed','cancelled','closed')),
      'quotes',(select count(*) from quotes),
      'avg_value',(select round(avg(expected_value)) from inquiries where expected_value is not null),
      'hired',(select count(*) from inquiries where hired_supplier_id is not null),
      'transactions',(select count(*) from transactions)
    ),
    'kanban', coalesce((select jsonb_agg(jsonb_build_object('key',stg,'count',c) order by c desc) from (
        select coalesce(nullif(pipeline_stage,''),coalesce(nullif(status,''),'new')) stg, count(*) c from inquiries group by 1) k),'[]'::jsonb),
    'rows', coalesce((select jsonb_agg(jsonb_build_object('id',id,'category',category,'emirate',emirate,'summary',summary,
        'status',status,'pipeline_stage',pipeline_stage,'deal_owner',deal_owner,'expected_value',expected_value,
        'budget',budget,'rfq_ready',rfq_ready,'created_at',created_at) ) from (select * from inquiries order by created_at desc limit 50) i),'[]'::jsonb),
    'quotes', coalesce((select jsonb_agg(jsonb_build_object('id',id,'inquiry_id',inquiry_id,'supplier_id',supplier_id,
        'quote_amount',quote_amount,'customer_price',customer_price,'status',status,'created_at',created_at)) from (select * from quotes order by created_at desc limit 30) q),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_notifications()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with fq as (select public.fn_founder_queue(8) j)
  select jsonb_build_object(
    -- CRITICAL — a founder alert raised at critical/high. An open agent_action at risk 'critical'
    -- used to be added here; it belongs to its role and is listed under 'held' instead.
    'critical', jsonb_build_object(
      'tier', 'critical',
      'count', (select count(*) from public.founder_alerts
                 where lower(coalesce(level,'')) in ('critical','high')
                   and created_at > now() - interval '7 days'
                   and created_at >= public.fn_os_fresh_start_at()),
      'rows', coalesce((select jsonb_agg(jsonb_build_object('title', a.event, 'detail', left(a.detail::text, 200),
                          'level', a.level, 'at', a.created_at) order by a.created_at desc)
                from (select * from public.founder_alerts
                       where lower(coalesce(level,'')) in ('critical','high')
                         and created_at > now() - interval '7 days'
                         and created_at >= public.fn_os_fresh_start_at()
                       order by created_at desc limit 8) a), '[]'::jsonb)),

    -- IMPORTANT — waiting on the founder. That is a refund approval and nothing else.
    'important', jsonb_build_object(
      'tier', 'important',
      'count', public.fn_founder_refund_approvals_open(),
      'rows', coalesce((select jsonb_agg(jsonb_build_object('title', x->>'title', 'detail', 'from ' || (x->>'from') || ' · ' || (x->>'kind_label'),
                          'kind', x->>'kind', 'agent', x->>'from', 'at', x->>'raised', 'id', x->>'id', 'source', x->>'source'))
                from fq, jsonb_array_elements(fq.j->'waiting_on_you') x), '[]'::jsonb)),

    -- HELD — open work that belongs to a named role. Informational: he is not asked to decide it.
    'held', jsonb_build_object(
      'tier', 'held',
      'count', (select (j->>'held_with_roles_total')::int from fq),
      'rows', coalesce((select jsonb_agg(jsonb_build_object(
                          'title', 'held with ' || (x->>'holder') || ': ' || (x->>'count'),
                          'detail', (select string_agg(k, ', ') from jsonb_array_elements_text(x->'kinds') k),
                          'holder', x->>'holder', 'count', x->>'count'))
                from fq, jsonb_array_elements(fq.j->'held_with_roles') x), '[]'::jsonb)),

    -- SUGGESTED — nothing is blocked, but the company thinks the founder should look.
    'suggested', jsonb_build_object(
      'tier', 'suggested',
      'count', (select count(*) from public.opportunity where status = 'open'
                 and created_at >= public.fn_os_fresh_start_at())
             + (select count(*) from public.evolution_proposal where status = 'proposed'
                 and created_at >= public.fn_os_fresh_start_at()),
      'rows', coalesce((select jsonb_agg(jsonb_build_object('title', o.title, 'detail', left(coalesce(o.detail,''), 200),
                          'kind', o.kind, 'at', o.created_at) order by o.value_score desc nulls last)
                from (select * from public.opportunity where status = 'open'
                       and created_at >= public.fn_os_fresh_start_at()
                       order by value_score desc nulls last limit 6) o), '[]'::jsonb)),

    -- COMPLETED TODAY — closed since midnight, whoever closed it.
    'completed_today', jsonb_build_object(
      'tier', 'completed_today',
      'count', (select count(*) from public.agent_actions where decided_at::date = current_date),
      'rows', coalesce((select jsonb_agg(jsonb_build_object('title', a.title, 'status', a.status,
                          'decided_by', a.decided_by, 'at', a.decided_at) order by a.decided_at desc)
                from (select * from public.agent_actions where decided_at::date = current_date
                       order by decided_at desc limit 8) a), '[]'::jsonb)),

    'auto_cleared_24h', (select round(100.0 * count(*) filter (where coalesce(escalated, false) = false)
                                 / greatest(count(*), 1))
                           from public.agent_actions where created_at > now() - interval '24 hours'),
    'auto_handled_30d', (select round(100.0 * count(*) filter (where coalesce(escalated, false) = false)
                                 / greatest(count(*), 1))
                           from public.agent_actions where created_at > now() - interval '30 days'),
    'actions_24h', (select count(*) from public.agent_actions where created_at > now() - interval '24 hours'),
    'actions_30d', (select count(*) from public.agent_actions where created_at > now() - interval '30 days'),
    'outbound_queue', (select count(*) from public.notifications where coalesce(status,'') not in ('sent','delivered')),
    'fresh_start_at', public.fn_os_fresh_start_at(),
    'generated_at', now()
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_operations()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  with fq as (select public.fn_founder_queue(30) j)
  select jsonb_build_object(
    'ops', jsonb_build_object(
      'health', (select (kpis->>'ops_health')::numeric from ops_kpi_snapshots order by snapshot_date desc limit 1),
      'kpis', (select to_jsonb(k) from ops_kpis k),
      'recommendations', coalesce((select jsonb_agg(jsonb_build_object('title',title,'risk',risk,'reco',recommendation)) from agent_actions where agent='operations_ai' and status in ('pending','needs_review')),'[]'::jsonb)
    ),
    'security', jsonb_build_object(
      'score', (select (kpis->>'security_score')::numeric from security_kpi_snapshots order by snapshot_date desc limit 1),
      'kpis', (select to_jsonb(k) from security_kpis k),
      'incidents', coalesce((select jsonb_agg(jsonb_build_object('title',title,'risk',risk)) from agent_actions where agent='security_ai' and status in ('pending','needs_review')),'[]'::jsonb),
      'events', coalesce((select jsonb_agg(jsonb_build_object('kind',kind,'severity',severity,'source',source,'at',created_at) order by created_at desc) from (select * from security_events where created_at >= public.fn_os_fresh_start_at() order by created_at desc limit 10) e),'[]'::jsonb)
    ),
    'kpis', jsonb_build_object(
      'approvals_pending', public.fn_founder_refund_approvals_open(),
      'held_with_roles', (select (j->>'held_with_roles_total')::int from fq),
      'high_risk',(select count(*) from agent_actions where status='pending' and coalesce(risk,'') in ('high','critical')),
      -- ONE definition of an open task (was: crm_tasks, the founder's own to-do list, which is 0).
      'tasks_open',(select count(*) from public.v_org_open_tasks),
      'decisions_24h',(select count(*) from decision_log where created_at > now()-interval '24 hours' and created_at >= public.fn_os_fresh_start_at()),
      'disputes',(select count(*) from transactions where coalesce(refund_status,'') in ('requested','pending'))
    ),
    -- HIS: the refund queue, verbatim from fn_founder_queue.
    'approvals', (select j->'waiting_on_you' from fq),
    -- NOT HIS: open agent_actions with the role that holds each. No approve/reject for him.
    'held', coalesce((select jsonb_agg(jsonb_build_object('id',id,'agent',agent,'kind',kind,
        'kind_label', public.fn_ui_label('action_kind', kind),
        'holder', public.fn_action_holder(kind, agent),
        'risk',risk,'title',title,
        'policies', public.fn_action_policies(kind, confidence),
        'recommendation',recommendation,'status',status,'target_table',target_table,'created_at',created_at,
        'os', public.fn_owning_os(agent), 'confidence', confidence, 'yours', false,
        'alternatives', (select d.alternatives from public.decision_log d where d.id = decision_log_id),
        'outcome', 'held with ' || public.fn_action_holder(kind, agent) || ' since ' || created_at::date)) from (
        select a.* from agent_actions a
          left join agent_action_kind_policy p on p.kind = a.kind
         where a.status in ('pending','needs_review') and coalesce(p.policy,'') <> 'founder'
           and a.created_at >= public.fn_os_fresh_start_at()
         order by (coalesce(a.risk,'')='critical') desc, a.created_at desc limit 30) a),'[]'::jsonb),
    'decisions', coalesce((select jsonb_agg(jsonb_build_object('id',id,'actor',actor,'kind',kind,'decision',decision,
        'confidence',confidence,'route_to',route_to,'created_at',created_at)) from (select * from decision_log where created_at >= public.fn_os_fresh_start_at() order by created_at desc limit 20) d),'[]'::jsonb),
    -- The company's open org_tasks, owned by their departments' agents (not his to close: no Done button).
    'tasks', coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'status',status,'priority',priority,'due',null,
        'source', coalesce(dept_key,'—') || case when assigned_agent is not null then ' · ' || assigned_agent else '' end,
        'entity','org_task','created_at',created_at)) from (select * from public.v_org_open_tasks order by created_at desc limit 20) t),'[]'::jsonb)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_refunds()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', jsonb_build_object(
      'pending', (select count(*) from transactions where refund_status in ('requested','pending')),
      'within_window', (select count(*) from transactions where refund_status in ('requested','pending') and refund_deadline > now()),
      'resolved_30d', (select count(*) from transactions where refund_resolved_at > now() - interval '30 days')
    ),
    'pending', (select coalesce(jsonb_agg(r order by r.requested desc),'[]'::jsonb) from (
        select t.id as transaction_id, t.quote_id, t.reveal_fee, coalesce(t.refund_status,'—') refund_status, coalesce(t.refund_reason,'—') reason,
               to_char(t.refund_requested_at,'YYYY-MM-DD') requested, to_char(t.refund_deadline,'YYYY-MM-DD') deadline,
               (t.refund_deadline > now()) in_window, coalesce(c.full_name,'—') customer, coalesce(l.company_name,'—') supplier
        from transactions t left join customers c on c.id=t.customer_id left join leads l on l.id=t.supplier_id
        where t.refund_status in ('requested','pending') order by t.refund_requested_at desc limit 100) r),
    'recent_resolved', (select coalesce(jsonb_agg(r order by r.resolved desc),'[]'::jsonb) from (
        select t.id as transaction_id, t.quote_id, coalesce(t.refund_status,'—') refund_status, coalesce(t.refund_note,'—') note,
               to_char(t.refund_resolved_at,'YYYY-MM-DD') resolved
        from transactions t where t.refund_resolved_at is not null order by t.refund_resolved_at desc limit 25) r)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_reports()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', (select to_jsonb(k) from public.report_kpis k),
    -- THE LATEST EXECUTIVE MEETING, IN SEQUENCE. exec_reports.findings is the ordered transcript of
    -- what each of the ten officers said; report_registry projects only title/period/id, so until
    -- now the body reached nothing the browser could run. `contributions` keeps the array order
    -- the meeting wrote it in — that order IS the replay.
    'meeting', (select jsonb_build_object(
        'id', r.id, 'period', r.period, 'officer', r.officer, 'summary', r.summary,
        'at', to_char(r.created_at,'YYYY-MM-DD HH24:MI'),
        'contributions', coalesce(r.findings, '[]'::jsonb),
        'priorities', coalesce(r.recommendations, '[]'::jsonb),
        'challenges', (select coalesce(jsonb_agg(jsonb_build_object(
              'proposal', c.proposal, 'by', c.challenged_by, 'of', c.proposed_by,
              'stance', c.stance, 'confidence', c.confidence, 'reasoning', c.reasoning,
              'alternatives', c.alternatives) order by c.id), '[]'::jsonb)
            from public.challenge_record c
           where c.created_at between r.created_at - interval '30 minutes'
                                  and r.created_at + interval '6 hours'))
      from public.exec_reports r where r.officer='ceo' and r.created_at >= public.fn_os_fresh_start_at() order by r.created_at desc limit 1),
    'freshness', (select jsonb_build_object(
        'daily', daily_fresh, 'weekly', weekly_fresh, 'monthly', monthly_fresh, 'quarterly', quarterly_fresh,
        'department', department_fresh, 'supplier', supplier_fresh, 'customer', customer_fresh, 'ai', ai_fresh
      ) from public.report_kpis),
    'recent', (select coalesce(jsonb_agg(r), '[]'::jsonb) from (
        select id, source, report_type, title, period,
               case source when 'exec' then 'exec' when 'narrative' then 'board' else source end as src,
               to_char(created_at,'YYYY-MM-DD HH24:MI') as created
        from public.report_registry where created_at >= public.fn_os_fresh_start_at() order by created_at desc limit 25) r),
    'by_type', (select coalesce(jsonb_agg(t), '[]'::jsonb) from (
        select report_type, id, title,
               case source when 'exec' then 'exec' when 'narrative' then 'board' else source end as src,
               to_char(created_at,'YYYY-MM-DD HH24:MI') as created
        from (
          select distinct on (report_type) report_type, id, source, title, created_at
          from public.report_registry where created_at >= public.fn_os_fresh_start_at() order by report_type, created_at desc
        ) x order by report_type) t),
    -- WHO PRODUCES EACH TYPE, AND WHETHER IT IS RUNNING. A tile that shows only a last date reads
    -- as live; this says "paused" out loud when the cron behind a type is off. Keyed by report_type.
    'producers', (select coalesce(jsonb_object_agg(p.report_type, jsonb_build_object(
        'job', p.jobname, 'active', coalesce(j.active, false),
        'last_run', (select to_char(max(d.start_time),'YYYY-MM-DD HH24:MI') from cron.job_run_details d where d.jobid = j.jobid),
        'paused_reason', case when coalesce(j.active, false) then null
                              when j.jobid is null then 'no cron job named ' || p.jobname
                              else 'cron ' || p.jobname || ' is paused' end)), '{}'::jsonb)
      from (values ('daily','founder_brief_daily'), ('department','reporting_ai_daily'), ('supplier','reporting_ai_daily'),
                   ('customer','reporting_ai_daily'), ('ai','reporting_ai_daily'), ('weekly','board_report_weekly'),
                   ('monthly','monthly_report'), ('quarterly','quarterly_report'), ('finance','finance_ai_daily')) as p(report_type, jobname)
      left join cron.job j on j.jobname = p.jobname),
    'flags', (select coalesce(jsonb_agg(f), '[]'::jsonb) from (
        select title, risk, status, to_char(created_at,'YYYY-MM-DD') as created
        from public.agent_actions
        where agent='reporting_ai' and kind='report_task' and status in ('pending','needs_review')
        order by created_at desc) f)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_rfq_360(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare i public.inquiries%rowtype; j jsonb; docs jsonb := '[]'::jsonb; hired text;
begin
  select * into i from public.inquiries where id=p_id;
  if i.id is null then return jsonb_build_object('error','RFQ not found'); end if;
  if i.drawing_file_path is not null then docs := docs || jsonb_build_object('type','Drawing','name',coalesce(i.drawing_file_name,'drawing'),'path',i.drawing_file_path); end if;
  if i.drawing_redacted_paths is not null then
    docs := docs || coalesce((select jsonb_agg(jsonb_build_object('type','Drawing (redacted)','name','redacted','path',x)) from unnest(i.drawing_redacted_paths) x),'[]'::jsonb);
  end if;
  select company_name into hired from public.leads where id=i.hired_supplier_id;
  j := jsonb_build_object(
    'requirements', jsonb_build_object('category',i.category,'emirate',i.emirate,'role_needed',i.role_needed,
       'summary',i.summary,'spec',i.spec,'boq',i.boq,'boq_confidence',i.boq_confidence,'budget',i.budget,
       'scope_type',i.scope_type,'trades',i.trades,'keywords',i.keywords),
    'status', jsonb_build_object('status',i.status,'pipeline_stage',i.pipeline_stage,'deal_owner',i.deal_owner,
       'expected_value',i.expected_value,'outcome',i.outcome,'lost_reason',i.lost_reason,'completed_at',i.completed_at,
       'project_id',i.project_id,'created_at',i.created_at),
    'ai_qualification', jsonb_build_object('completeness',i.completeness,'rfq_ready',i.rfq_ready,'routing',i.routing,'brief_source',i.brief_source),
    'selected_supplier', case when i.hired_supplier_id is not null then jsonb_build_object('id',i.hired_supplier_id,'company_name',hired) else null end,
    'documents', docs,
    'matching', coalesce((select jsonb_agg(jsonb_build_object('supplier_id',m.supplier_id,'company_name',l.company_name,
       'similarity',m.similarity,'match_reason',m.match_reason,'sent_at',m.sent_at) order by m.similarity desc nulls last)
       from public.inquiry_matches m left join public.leads l on l.id=m.supplier_id where m.inquiry_id=p_id),'[]'::jsonb),
    'quotes', coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'supplier_id',q.supplier_id,'company_name',l.company_name,
       'amount',q.quote_amount,'status',q.status,'lead_time',q.lead_time,'validity',q.validity,'quality',q.quality,
       'created_at',q.created_at) order by q.quote_amount asc nulls last)
       from public.quotes q left join public.leads l on l.id=q.supplier_id where q.inquiry_id=p_id),'[]'::jsonb),
    'procurement', public.fn_procurement_analysis(p_id),
    'clarifications', coalesce((select jsonb_agg(jsonb_build_object('question',qn.question,'answer',qn.answer,
       'supplier_id',qn.supplier_id,'asked_at',qn.asked_at,'answered_at',qn.answered_at) order by qn.asked_at desc)
       from public.questions qn where qn.inquiry_id=p_id),'[]'::jsonb),
    'timeline', (select jsonb_agg(e order by e->>'at' desc) from (
        select jsonb_build_object('at',i.created_at,'event','RFQ created') e
        union all select jsonb_build_object('at',m.sent_at,'event','Matched supplier') from public.inquiry_matches m where m.inquiry_id=p_id and m.sent_at is not null
        union all select jsonb_build_object('at',q.created_at,'event','Quote received: AED '||coalesce(q.quote_amount::text,'?')) from public.quotes q where q.inquiry_id=p_id
        union all select jsonb_build_object('at',i.completed_at,'event','Completed'||coalesce(' ('||i.outcome||')','')) where i.completed_at is not null
      ) tl)
  );
  return j;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ws_strategy()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select jsonb_build_object(
    'kpis', (select to_jsonb(k) from public.strategy_kpis k),
    'risks', (select coalesce(jsonb_agg(r),'[]'::jsonb) from (
        select title, category, score, likelihood, impact, status
        from public.strategy_risks where status<>'closed' order by score desc limit 20) r),
    'recommendations', (select coalesce(jsonb_agg(x),'[]'::jsonb) from (
        select title, risk, to_char(created_at,'YYYY-MM-DD') as created
        from public.agent_actions where agent='strategy_ai' and kind='strategy_rec'
          and status in ('pending','needs_review') order by array_position(array['high','medium','low']::text[],risk)) x),
    'under_supplied', coalesce(fn_strategy_metrics()->'under_supplied','[]'::jsonb),
    'market_intel', (select coalesce(jsonb_agg(m),'[]'::jsonb) from (
        select kind, title, impact, status, coalesce(source,'—') as source
        from public.market_intel where status<>'dismissed' order by created_at desc limit 20) m),
    'recent_simulations', (select coalesce(jsonb_agg(s),'[]'::jsonb) from (
        select coalesce(nullif(scenario->>'question',''), nullif(scenario->>'title',''), nullif(scenario->>'type',''), 'Scenario #' || id) as title,
               (scenario->>'confidence')::numeric as confidence,
               to_char(created_at,'YYYY-MM-DD HH24:MI') as created
        from public.simulations order by created_at desc limit 8) s)
  );
$function$


CREATE OR REPLACE FUNCTION public.fn_ws_supplier_360(p_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare l public.leads%rowtype; j jsonb; docs jsonb := '[]'::jsonb;
begin
  select * into l from public.leads where id=p_id;
  if l.id is null then return jsonb_build_object('error','supplier not found'); end if;

  -- documents from path fields
  if l.license_doc_path is not null then docs:=docs||jsonb_build_object('type','Trade licence','name',coalesce(l.license_doc_name,'licence'),'path',l.license_doc_path); end if;
  if l.egr_doc_path is not null then docs:=docs||jsonb_build_object('type','Establishment card','name',coalesce(l.egr_doc_name,'egr'),'path',l.egr_doc_path); end if;
  if l.insurance_doc_path is not null then docs:=docs||jsonb_build_object('type','Insurance','name','insurance','path',l.insurance_doc_path); end if;
  if l.vat_doc_path is not null then docs:=docs||jsonb_build_object('type','VAT certificate','name','vat','path',l.vat_doc_path); end if;
  if l.company_profile_doc_path is not null then docs:=docs||jsonb_build_object('type','Company profile','name','profile','path',l.company_profile_doc_path); end if;
  if l.signed_terms_path is not null then docs:=docs||jsonb_build_object('type','Signed terms','name','terms','path',l.signed_terms_path); end if;
  if l.catalog_doc_paths is not null then
    docs := docs || coalesce((select jsonb_agg(jsonb_build_object('type','Catalogue','name','catalogue','path',x))
                              from unnest(l.catalog_doc_paths) x),'[]'::jsonb);
  end if;

  j := jsonb_build_object(
    'profile', jsonb_build_object(
      'id', l.id, 'company_name', l.company_name, 'sector', l.sector, 'sub_type', l.sub_type,
      'emirate', l.emirate, 'city', l.city, 'phone', coalesce(l.phone_e164,l.phone), 'email', l.email,
      'website', l.website, 'contact_name', l.contact_name, 'founded_year', l.founded_year,
      'company_size', l.company_size, 'employee_count', l.employee_count, 'business_role', l.business_role,
      'lifecycle_stage', l.lifecycle_stage, 'claimed', l.claimed
    ),
    'status', jsonb_build_object(
      'approval_status', l.approval_status, 'verified', l.verified, 'verification_status', l.verification_status,
      'registration_status', l.registration_status, 'matching_blocked', l.matching_blocked,
      'matching_block_reason', l.matching_block_reason, 'banned', l.banned, 'banned_reason', l.banned_reason,
      'chat_strikes', l.chat_strikes
    ),
    'ai', jsonb_build_object(
      'capability_summary', l.capability_summary, 'capability_score', l.capability_score,
      'review_notes', l.ai_review_notes, 'review_flags', l.ai_review_flags, 'reviewed_at', l.ai_reviewed_at,
      'twin', coalesce((select to_jsonb(tw) from public.supplier_twin tw where tw.supplier_id=p_id),'{}'::jsonb)
    ),
    'compliance', jsonb_build_object(
      'trade_license_no', l.trade_license_no, 'license_authority', l.license_authority,
      'license_expiry', l.license_expiry, 'trn', l.trn, 'vat_number', l.vat_number,
      'insurance_expiry', l.insurance_expiry, 'iso_certifications', l.iso_certifications,
      'certifications', l.certifications, 'accepted_terms_at', l.accepted_terms_at,
      'registration_expires_at', l.registration_expires_at,
      'license_expiring', (l.license_expiry is not null and l.license_expiry < current_date + 30),
      'insurance_expiring', (l.insurance_expiry is not null and l.insurance_expiry < current_date + 30)
    ),
    'capabilities', jsonb_build_object(
      'brands_carried', l.brands_carried, 'machinery', l.machinery, 'engineers_count', l.engineers_count,
      'team_size', l.team_size, 'warehouse_area', l.warehouse_area, 'service_emirates', l.service_emirates,
      'manufacturer_authorizations', l.manufacturer_authorizations, 'client_references', l.client_references,
      'products', l.products, 'services', l.services,
      'detail', coalesce((select to_jsonb(c) from public.supplier_capabilities c where c.supplier_id=p_id),'{}'::jsonb)
    ),
    'performance', coalesce((select jsonb_build_object(
        'matched',pf.matched,'quoted',pf.quoted,'won',pf.won,'quote_rate',pf.quote_rate,
        'win_rate',pf.win_rate,'perf_score',pf.perf_score,'rating',pf.rating,'review_count',pf.review_count)
        from public.supplier_perf pf where pf.supplier_id=p_id),'{}'::jsonb)
      || jsonb_build_object('rv_reveals',l.rv_reveals,'rv_responded',l.rv_responded,'rv_response_rate',l.rv_response_rate,
                            'app_rating',l.app_rating,'app_reviews',l.app_reviews),
    'reputation', coalesce((select to_jsonb(rp) - 'supplier_id' - 'company_name' from public.supplier_reputation rp where rp.supplier_id=p_id),'{}'::jsonb),
    'financials', (
      select jsonb_build_object(
        'deals_count', count(*) filter (where t.id is not null),
        'deal_value_total', coalesce(sum(t.quote_amount),0),
        'reveal_fees_generated', coalesce(sum(t.reveal_fee) filter (where t.fee_status='paid'),0)
      ) from public.transactions t where t.supplier_id=p_id
    ) || (
      select jsonb_build_object(
        'commission_total', coalesce(sum(amount_due),0),
        'commission_paid', coalesce(sum(amount_due) filter (where status in ('paid','settled')),0),
        'commission_owed', coalesce(sum(amount_due) filter (where public.fn_supplier_due_is_owed(status, paid_at)),0)
      ) from public.supplier_dues where supplier_id=p_id
    ),
    'documents', docs,
    'quotes', coalesce((select jsonb_agg(jsonb_build_object('id',q.id,'amount',q.quote_amount,'status',q.status,'created_at',q.created_at) order by q.created_at desc)
                        from (select * from public.quotes where supplier_id=p_id order by created_at desc limit 10) q),'[]'::jsonb),
    'reviews', coalesce((select jsonb_agg(jsonb_build_object('rating',r.rating,'comment',r.comment,'created_at',r.created_at) order by r.created_at desc)
                        from (select * from public.reviews where supplier_id=p_id order by created_at desc limit 8) r),'[]'::jsonb),
    'timeline', (select jsonb_agg(e order by e->>'at' desc) from (
        select jsonb_build_object('at',l.created_at,'event','Added to directory') e where l.created_at is not null
        union all select jsonb_build_object('at',l.registration_submitted_at,'event','Registration submitted') where l.registration_submitted_at is not null
        union all select jsonb_build_object('at',l.approved_at,'event','Approved'||coalesce(' by '||l.approval_decided_by,'')) where l.approved_at is not null
        union all select jsonb_build_object('at',l.accepted_terms_at,'event','Accepted terms') where l.accepted_terms_at is not null
      ) tl),
    -- WHY WE DECIDED WHAT WE DECIDED about this supplier. decision_record holds the reasoning behind
    -- past decisions and decision_trace the policies that were applied; neither reached the supplier
    -- view, so "why did we reject Supplier X?" had no answer on the screen that shows X.
    'rejection_reason', coalesce((select jsonb_agg(jsonb_build_object(
        'id', dr.id, 'problem', dr.problem, 'recommendation', dr.recommendation,
        'risks', dr.risks, 'status', dr.status, 'decided_by', dr.decided_by,
        'actual_outcome', dr.actual_outcome, 'at', dr.created_at) order by dr.created_at desc)
      from public.decision_record dr
      where coalesce(l.company_name,'') <> ''
        and (dr.problem ilike '%'||l.company_name||'%' or dr.context ilike '%'||l.company_name||'%')), '[]'::jsonb),
    'decision_trace', coalesce((select jsonb_agg(jsonb_build_object(
        'entity_id', dt.entity_id, 'policy_keys', dt.policy_keys) order by dt.entity_id)
      from public.decision_trace dt where dt.entity_id = p_id::text), '[]'::jsonb)
  );
  return j;
end $function$


CREATE OR REPLACE FUNCTION public.fn_ws_suppliers(p jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
declare
  v_q text := nullif(trim(coalesce(p->>'q','')),'');
  v_emirate text := nullif(p->>'emirate','');
  v_sector text := nullif(p->>'sector','');
  v_approval text := nullif(p->>'approval','');
  v_limit int := least(coalesce((p->>'limit')::int,50),100);
  v_offset int := greatest(coalesce((p->>'offset')::int,0),0);
  v_rows jsonb; v_total bigint;
begin
  select count(*) into v_total from leads
   where coalesce(source,'') <> 'canary'
     and (v_q is null or company_name ilike '%'||v_q||'%' or categories ilike '%'||v_q||'%')
     and (v_emirate is null or emirate=v_emirate)
     and (v_sector is null or sector=v_sector)
     and (v_approval is null or approval_status=v_approval);

  select coalesce(jsonb_agg(r),'[]'::jsonb) into v_rows from (
    select jsonb_build_object('id',id,'company_name',company_name,'sector',sector,'sub_type',sub_type,
      'emirate',emirate,'city',city,'rating',app_rating,'reviews',app_reviews,'categories',categories,
      'approval_status',approval_status,'lifecycle_stage',lifecycle_stage,'verified',verified,
      'verification_status',verification_status,'capability_score',capability_score,'invite_status',invite_status,
      'registration_status',registration_status,'license_expiry',license_expiry,'banned',banned,
      'matching_blocked',matching_blocked,'phone',phone,'website',website,'created_at',created_at) as r
    from leads
    where coalesce(source,'') <> 'canary'
      and (v_q is null or company_name ilike '%'||v_q||'%' or categories ilike '%'||v_q||'%')
      and (v_emirate is null or emirate=v_emirate)
      and (v_sector is null or sector=v_sector)
      and (v_approval is null or approval_status=v_approval)
    order by capability_score desc nulls last, app_reviews desc nulls last
    limit v_limit offset v_offset
  ) x;

  return jsonb_build_object(
    'kpis', jsonb_build_object(
      'total',(select count(*) from leads where coalesce(source,'') <> 'canary'),
      'approved',(select count(*) from leads where approval_status='approved'),
      'pending_review',(select count(*) from leads where coalesce(approval_status,'') in ('submitted','pending','under_review','pending_review')),
      'verified',(select count(*) from leads where verified is true),
      'registered',(select count(*) from leads where registration_paid_at is not null),
      'licenses_expiring',(select count(*) from leads where license_expiry is not null and license_expiry < (now()+interval '30 days')::date and license_expiry >= now()::date),
      'banned',(select count(*) from leads where banned is true),
      'matching_blocked',(select count(*) from leads where matching_blocked is true)
    ),
    'success', jsonb_build_object(
      'kpis', coalesce((select to_jsonb(k) from supplier_kpis k), '{}'::jsonb),
      'open_risk', (select count(*) from agent_actions where kind='supplier_risk' and status in ('pending','needs_review')),
      'attention', coalesce((select jsonb_agg(a) from (
          select jsonb_build_object('id',supplier_id,'company_name',company_name,'health',health,
            'quality',quality,'compliance',compliance,'response',response,'retention',retention,
            'risk_tier',risk_tier,'dormant',dormant) a
          from supplier_health where risk_tier in ('high','medium') order by health asc limit 10) t),'[]'::jsonb),
      'trend', coalesce((select jsonb_agg(jsonb_build_object('d',snapshot_date,'health',(kpis->>'avg_health')) order by snapshot_date)
          from (select snapshot_date, kpis from supplier_kpi_snapshots order by snapshot_date desc limit 14) s),'[]'::jsonb)
    ),
    'kanban', coalesce((select jsonb_agg(jsonb_build_object('key',stg,'count',c) order by c desc) from (
        select coalesce(nullif(lifecycle_stage,''),'directory') stg, count(*) c from leads where coalesce(source,'') <> 'canary' group by 1 order by 2 desc limit 8) k),'[]'::jsonb),
    'sectors', coalesce((select jsonb_agg(jsonb_build_object('key',s,'count',c) order by c desc) from (
        select coalesce(nullif(sector,''),'other') s, count(*) c from leads where coalesce(source,'') <> 'canary' group by 1 order by 2 desc limit 10) s),'[]'::jsonb),
    'emirates', coalesce((select jsonb_agg(jsonb_build_object('key',e,'count',c) order by c desc) from (
        select coalesce(nullif(emirate,''),'—') e, count(*) c from leads where coalesce(source,'') <> 'canary' group by 1 order by 2 desc limit 10) e),'[]'::jsonb),
    'total', v_total, 'limit', v_limit, 'offset', v_offset, 'rows', v_rows
  );
end;
$function$


CREATE OR REPLACE FUNCTION public.funnel_metrics(days integer DEFAULT 30)
 RETURNS json
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with w as (select (now() - make_interval(days => days)) as since)
  select json_build_object(
    'days', days,
    'inquiries', (select count(*) from public.inquiries i, w where i.created_at>=w.since),
    'matched', (select count(distinct m.inquiry_id) from public.inquiry_matches m join public.inquiries i on i.id=m.inquiry_id, w where i.created_at>=w.since),
    'quoted', (select count(distinct q.inquiry_id) from public.quotes q join public.inquiries i on i.id=q.inquiry_id, w where i.created_at>=w.since),
    'revealed', (select count(*) from public.transactions t join public.inquiries i on i.id=t.inquiry_id, w where t.revealed_at is not null and i.created_at>=w.since),
    'completed', (select count(*) from public.inquiries i, w where i.status='completed' and i.created_at>=w.since),
    'cancelled', (select count(*) from public.inquiries i, w where i.status='cancelled' and i.created_at>=w.since),
    'reveal_fees', (select coalesce(sum(t.reveal_fee),0) from public.transactions t join public.inquiries i on i.id=t.inquiry_id, w where t.revealed_at is not null and i.created_at>=w.since)
  );
$function$


CREATE OR REPLACE FUNCTION public.is_disposable_email(p_email text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select exists (
    select 1 from app_blocked_domains d
    where d.domain = lower(split_part(p_email,'@',2))
  );
$function$


CREATE OR REPLACE FUNCTION public.kb_match(query_embedding vector, match_count integer DEFAULT 8, p_category text DEFAULT NULL::text)
 RETURNS TABLE(id bigint, category text, title text, citation text, content text, similarity double precision)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with want as (
    select nullif(regexp_replace(lower(p_category),'^cat:',''),'') as c
  ), cats as (
    select c as cat from want where c is not null
    union
    select a.maps_to from kb_category_aliases a, want w where a.category = w.c
  ), src as materialized (
    select k.id, k.category, k.title, k.citation, k.content, k.embedding_gte
    from public.kb_chunks k
    where k.embedding_gte is not null
      and ((select c from want) is null or k.category_norm in (select cat from cats))
  )
  select s.id, s.category, s.title, s.citation, s.content,
         1 - (s.embedding_gte <=> query_embedding) as similarity
  from src s
  order by s.embedding_gte <=> query_embedding
  limit match_count;
$function$


CREATE OR REPLACE FUNCTION public.kb_norm(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  select nullif(
    btrim(regexp_replace(
      translate(
        regexp_replace(lower(normalize(coalesce(p,''), NFKC)), '[ً-ْٰـ]', '', 'g'),
        'أإآةىؤئ', 'اااهيوي'
      ),
      '[^[:alnum:]؀-ۿ]+', ' ', 'g')),
    '');
$function$


CREATE OR REPLACE FUNCTION public.kb_query(p_query text, p_category text DEFAULT NULL::text, p_limit integer DEFAULT 8)
 RETURNS TABLE(source_kind text, category text, title text, snippet text, citation text, effective_date date, rank real)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_lim int := greatest(1, least(coalesce(p_limit, 8), 25));
  v_tsq tsquery;
begin
  v_tsq := websearch_to_tsquery('english', coalesce(p_query, ''));

  -- A query of nothing, or of nothing but stop words, has no lexemes to match: websearch_to_tsquery
  -- returns an empty tsquery, which matches no row. Ranking is meaningless either way, so both land here.
  if coalesce(btrim(p_query), '') = '' or v_tsq::text = '' then
    return query
      select r.source_kind, r.category, r.title, r.snippet, r.citation, r.effective_date, r.rnk
        from (
          select c.source_kind, c.category, c.title, left(c.content, 700) as snippet, c.citation, c.effective_date,
                 0::real as rnk, c.id
            from public.kb_chunks c
           where p_category is null or c.category = p_category
           order by c.id desc
           limit v_lim
        ) r
       order by r.id desc;
    return;
  end if;

  return query
    select r.source_kind, r.category, r.title, r.snippet, r.citation, r.effective_date, r.rnk
      from (
        select c.source_kind, c.category, c.title, left(c.content, 700) as snippet, c.citation, c.effective_date,
               (ts_rank(c.fts, v_tsq)
                + case when p_category is not null and c.category = p_category then 0.4 else 0 end)::real as rnk
          from public.kb_chunks c
         where c.fts @@ v_tsq
      ) r
     order by r.rnk desc nulls last, r.effective_date desc nulls last
     limit v_lim;
end
$function$


CREATE OR REPLACE FUNCTION public.kb_sync()
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n int;
begin
  delete from kb_chunks where source_kind in ('regulation','trade','material');
  insert into kb_chunks(source_kind,source_id,category,title,content,citation,effective_date)
  select 'regulation', r.id::text, cat, r.title,
    coalesce(r.summary,'') || case when jsonb_array_length(coalesce(r.key_requirements,'[]'::jsonb))>0
      then E'\nKey requirements: ' || (select string_agg(x, '; ') from jsonb_array_elements_text(r.key_requirements) x) else '' end,
    r.authority || ' — ' || r.title || coalesce(' [' || r.source_url || ']','') || coalesce(' (effective ' || r.effective_date::text || ')',''),
    r.effective_date
  from regulations r
  left join lateral unnest(case when array_length(r.categories,1) is null then array[null::text] else r.categories end) as cat on true
  where r.status = 'active' and r.approved_at is not null;
  insert into kb_chunks(source_kind,source_id,category,title,content,citation,effective_date)
  select 'trade', ak.id::text, ak.agent_key, ak.topic, ak.content,
    'QuotesDone trade knowledge: ' || coalesce(ak.agent_key,'') || ' / ' || coalesce(ak.topic,''), null
  from agent_knowledge ak;
  insert into kb_chunks(source_kind,source_id,category,title,content,citation,effective_date)
  select 'material', m.id::text, m.category, m.item,
    m.item || ' — ' || coalesce(m.properties::text,'') ||
      case when array_length(m.standards,1) is not null then E'\nStandards: ' || array_to_string(m.standards,', ') else '' end ||
      case when m.price_band is not null then E'\nPrice band: ' || m.price_band else '' end,
    'QuotesDone material library: ' || m.item, null
  from materials m;
  select count(*) into n from kb_chunks;
  return jsonb_build_object('chunks', n);
end $function$


CREATE OR REPLACE FUNCTION public.kn_task(p_sig text, p_cond boolean, p_risk text, p_title text, p_reco text, p_assumptions jsonb DEFAULT NULL::jsonb, p_impact text DEFAULT NULL::text, p_cost text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if p_cond then
    if not exists (select 1 from agent_actions where kind='knowledge_task' and detail->>'signal'=p_sig and status in ('pending','needs_review')) then
      insert into agent_actions(agent,kind,status,risk,title,recommendation,detail,target_table,target_id,assumptions,expected_impact,cost)
      values ('knowledge_curator','knowledge_task','pending',p_risk,p_title,p_reco,jsonb_build_object('signal',p_sig),'knowledge',p_sig,p_assumptions,p_impact,p_cost);
    end if;
  else
    update agent_actions
       set status='resolved', decided_at=now(), decided_by='knowledge_curator (auto-resolved)'
     where kind='knowledge_task' and detail->>'signal'=p_sig and status in ('pending','needs_review');
  end if;
end $function$


CREATE OR REPLACE FUNCTION public.margin_rate(amount numeric)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select case
    when amount < 2000  then 0.10
    when amount < 5000  then 0.08
    when amount < 10000 then 0.06
    when amount < 20000 then 0.05
    when amount < 50000 then 0.04
    else 0.03 end
$function$


CREATE OR REPLACE FUNCTION public.mask_contacts(t text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s text := t;
begin
  if s is null or s = '' then return s; end if;
  -- emails
  s := regexp_replace(s, '[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}', '[hidden]', 'gi');
  -- explicit URLs
  s := regexp_replace(s, '(https?://|www\.)[^[:space:]]+', '[hidden]', 'gi');
  -- bare social / messenger short links (no scheme)
  s := regexp_replace(s, '(wa\.me|t\.me|bit\.ly|instagram\.com|facebook\.com|fb\.com|linkedin\.com|twitter\.com|x\.com)/[^[:space:]]*', '[hidden]', 'gi');
  -- international UAE numbers (+971 ...)
  s := regexp_replace(s, '\+?971[ \-]?[0-9][0-9 \-]{6,}[0-9]', '[hidden]', 'g');
  -- local UAE mobile  05x xxx xxxx  (9 digits starting 5, optional separators) — bounded so prices/qtys are safe
  s := regexp_replace(s, '\y0?5[0-9][ \-]?[0-9]{3}[ \-]?[0-9]{4}\y', '[hidden]', 'g');
  return s;
end;
$function$


CREATE OR REPLACE FUNCTION public.mask_contacts_jsonb(j jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r jsonb; k text; v jsonb; e jsonb;
begin
  if j is null then return j; end if;
  case jsonb_typeof(j)
    when 'string' then
      return to_jsonb(public.mask_contacts(j #>> '{}'));
    when 'object' then
      r := '{}'::jsonb;
      for k, v in select key, value from jsonb_each(j) loop
        r := r || jsonb_build_object(k, public.mask_contacts_jsonb(v));
      end loop;
      return r;
    when 'array' then
      r := '[]'::jsonb;
      for e in select value from jsonb_array_elements(j) loop
        r := r || jsonb_build_array(public.mask_contacts_jsonb(e));
      end loop;
      return r;
    else
      return j;
  end case;
end;
$function$


CREATE OR REPLACE FUNCTION public.mask_name(t text, nm text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s text := t; part text;
begin
  if s is null or s = '' or nm is null or btrim(nm) = '' then return s; end if;
  s := regexp_replace(s, '\y' || regexp_replace(btrim(nm), '([.^$*+?()\[\]{}|\\-])', '\\\1', 'g') || '\y', '[hidden]', 'gi');
  for part in select unnest(regexp_split_to_array(btrim(nm), '\s+')) loop
    if length(part) >= 3 then
      s := regexp_replace(s, '\y' || regexp_replace(part, '([.^$*+?()\[\]{}|\\-])', '\\\1', 'g') || '\y', '[hidden]', 'gi');
    end if;
  end loop;
  return s;
end;
$function$


CREATE OR REPLACE FUNCTION public.mask_project_identity(t text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare s text := t;
begin
  if s is null or s = '' then return s; end if;

  -- 1. LABELLED FIELDS. A title block labels its own secrets, in every format and every CAD
  --    template: "PROJECT:", "CLIENT:", "CONSULTANT:", "LOCATION:". The label is the reliable
  --    signal — far more reliable than trying to recognise the value — so the value after it is
  --    removed to end of line. This is what makes the rule format-independent, which is the
  --    founder's own requirement ("no matter what format it is").
  s := regexp_replace(s,
    '(?in)^[[:space:]]*(project|client|employer|owner|developer|consultant|architect|engineer|'
    || 'main[[:space:]]+contractor|contractor|sub[- ]?contractor|designer|surveyor|site|location|'
    || 'address|plot|building|tower|villa|community|district|drawing[[:space:]]*(no|number)?|'
    || 'dwg[[:space:]]*(no|number)?|sheet|makani|title|prepared[[:space:]]+by|issued[[:space:]]+to|'
    || 'checked[[:space:]]+by|approved[[:space:]]+by|drawn[[:space:]]+by)[[:space:]]*[:#][^\n]*',
    '[hidden]', 'g');

  -- Same labels appearing mid-line ("... | DRAWING No: AH-2024-A-102 | REV: C"), bounded to the
  -- segment so the rest of a sentence survives.
  --
  -- THE PEOPLE LABELS ARE IN THIS LIST BECAUSE THE FIRST VERSION MISSED THEM. Run over the real
  -- drawing, everything above was correctly hidden and this line came through untouched:
  --     DATE: 12/03/2024 | DRAWN BY: R. Fernandes | APPROVED: Eng. S. Malik
  -- The line-start rule did not fire because the line starts with DATE:, and the mid-line rule did
  -- not carry "drawn by" or "approved". Two named individuals — the draughtsman and the approving
  -- engineer — survived into the supplier-facing copy. A person's name is identity as surely as the
  -- consultant firm's is, and it is the kind of thing that identifies a project to anyone in the
  -- trade. Every label that can be followed by a person or a firm now appears in BOTH rules.
  s := regexp_replace(s,
    '(?i)(project|client|employer|consultant|architect|engineer|developer|owner|contractor|'
    || 'designer|surveyor|location|address|plot|building|tower|villa|community|makani|'
    || 'drawing[[:space:]]*no|dwg[[:space:]]*no|sheet[[:space:]]*no|'
    || 'drawn[[:space:]]+by|checked[[:space:]]+by|approved[[:space:]]+by|prepared[[:space:]]+by|'
    || 'reviewed[[:space:]]+by|issued[[:space:]]+to|approved|verified[[:space:]]+by)'
    || '[[:space:]]*[:#][[:space:]]*[^|\n]{1,80}', '[hidden]', 'g');

  -- 2. IDENTIFIERS WITH A SHAPE.
  --    Makani is Dubai's 10-digit address code, written 1234-56789 or as ten digits.
  s := regexp_replace(s, '(?i)\ymakani[[:space:]]*[:#]?[[:space:]]*[0-9]{4}[[:space:]-]?[0-9]{5,6}\y', '[hidden]', 'g');
  --    Plot / parcel numbers: "Plot 234-11", "Parcel 345-6789".
  s := regexp_replace(s, '(?i)\y(plot|parcel|land)[[:space:]]*(no\.?|number|#)?[[:space:]]*[0-9]{1,6}(-[0-9]{1,6})*\y', '[hidden]', 'g');
  --    Drawing / sheet numbers: "AH-2024-A-102", "DWG-01-A-203". Two or more hyphen-joined groups
  --    with at least one letter group, so a plain measurement or a date is not caught.
  s := regexp_replace(s, '\y[A-Z]{1,4}-[A-Z0-9]{1,6}-[A-Z0-9]{1,6}(-[A-Z0-9]{1,6})*\y', '[hidden]', 'g');

  -- 3. COMPANY NAMES BY THEIR SUFFIX. A UAE entity almost always announces itself: L.L.C, LLC,
  --    FZE, FZ-LLC, DMCC, Est., Trading, Contracting, Consultants, Consulting Engineers. Capture
  --    the run of capitalised words immediately before the suffix, which is the name itself.
  s := regexp_replace(s,
    '(?i)\y([A-Z][A-Za-z&''.\-]*[[:space:]]+){1,6}'
    || '(l\.?l\.?c\.?|llc|fz[- ]?llc|fze|fzco|dmcc|est\.?|establishment|trading|general[[:space:]]+trading|'
    || 'contracting|contractors?|consultants?|consulting[[:space:]]+engineers?|engineering[[:space:]]+consultants?|'
    || 'architects?|technical[[:space:]]+services|building[[:space:]]+materials)\y',
    '[hidden]', 'g');

  return s;
end $function$


CREATE OR REPLACE FUNCTION public.mask_project_identity_jsonb(j jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if j is null then return j; end if;
  case jsonb_typeof(j)
    when 'string' then return to_jsonb(public.mask_project_identity(j #>> '{}'));
    when 'array'  then return (select coalesce(jsonb_agg(public.mask_project_identity_jsonb(e)), '[]'::jsonb)
                                 from jsonb_array_elements(j) e);
    when 'object' then return (select coalesce(jsonb_object_agg(k, public.mask_project_identity_jsonb(v)), '{}'::jsonb)
                                 from jsonb_each(j) as t(k, v));
    else return j;
  end case;
end $function$


CREATE OR REPLACE FUNCTION public.qd_norm_customer_ver()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if TG_OP = 'UPDATE' then
    if NEW.tos_accepted_at is not distinct from OLD.tos_accepted_at then
      -- Not a new acceptance: the recorded version is evidence and is never rewritten -- except
      -- (6 Sep 2026) by the acceptance's own trigger chain re-aligning the row to the version the
      -- registry publishes now, which is the version fn_customer_terms_accept just recorded in the
      -- kernel. Depth > 1 means we are inside z56's chain, not a later hand call or a profile edit.
      if pg_trigger_depth() > 1
         and NEW.tos_version is distinct from OLD.tos_version
         and NEW.tos_version = public.fn_terms_version('customer') then
        return NEW;
      end if;
      NEW.tos_version := OLD.tos_version;
      return NEW;
    end if;
    if NEW.tos_version is not distinct from OLD.tos_version then
      NEW.tos_version := public.fn_terms_version('customer');
      return NEW;
    end if;
  end if;
  if NEW.tos_accepted_at is not null and coalesce(NEW.tos_version,'') = '' then
    NEW.tos_version := public.fn_terms_version('customer');
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.qd_notify_refund_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_company text; v_window int; v_chase int;
begin
  select company_name into v_company from leads where id = NEW.supplier_id;
  select refund_window_working_days, chase_after_working_days into v_window, v_chase
    from pricing_config order by id limit 1;
  -- 6 Sep 2026: the complaint is the Customer Success Director's to work (founder_mail_policy
  -- refund_complaint, allowed_to_email = false). The founder hears about a refund exactly twice: the
  -- day-5 final call (refund_final_call) and the approval itself.
  perform public.fn_notify_founder(
    p_event => 'Refund requested — supplier not responding: ' || coalesce(v_company, '(id ' || NEW.supplier_id::text || ')'),
    p_detail => 'A customer has asked for the reveal fee back because a revealed supplier is not responding.' || chr(10) ||
    'Supplier: ' || coalesce(v_company, '(id ' || NEW.supplier_id::text || ')') || chr(10) ||
    'Inquiry: ' || coalesce(NEW.inquiry_id::text, '') || ' · Transaction: ' || NEW.id::text ||
      ' · Reveal fee: AED ' || coalesce(NEW.reveal_fee::text, '0') || ' · paid ' ||
      coalesce(to_char(NEW.revealed_at at time zone 'Asia/Dubai', 'DD Mon YYYY'), '?') || chr(10) || chr(10) ||
    'Ladder: the supplier has ' || coalesce(v_window, 5)::text || ' working days from payment. The sweep chases at day ' ||
      coalesce(v_chase, 3)::text || ' and files the refund for the founder''s final call at day ' || coalesce(v_window, 5)::text ||
      '. Reach the supplier now; if they respond, record it (supplier_ack_at or a portal message) so the case closes. ' ||
      'Read fn_refund_state(''' || NEW.id::text || ''') for where it stands.',
    p_level => 'high', p_kind => 'refund_complaint', p_dedupe_key => 'refund_complaint:' || NEW.id::text, p_owner_agent => null);
  -- 9 SEP 2026 -- PHASE MACHINERY REMOVED. A guarded emit into the kernel source table stood here that
  -- opened a W17 kernel run once the refunds row existed. The kernel is deleted; nothing consumed
  -- it. The fn_notify_founder call above -- the notification a person actually reads, routed
  -- through founder_mail_policy as refund_complaint -- is unchanged.
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.qd_project_ref()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_ref text;
begin
  select value into v_ref from app_secrets where key = 'project_ref';
  if v_ref is null then
    select substring(command from 'https://([a-z]+)[.]supabase[.]co') into v_ref
      from cron.job where command like '%supabase.co/functions/v1/%' limit 1;
  end if;
  if v_ref is null then
    raise exception 'qd_project_ref: cannot determine the Supabase project ref. Set app_secrets.project_ref.';
  end if;
  return v_ref;
end $function$


CREATE OR REPLACE FUNCTION public.qd_sign_customer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_secret text; v_ref text;
begin
  select value into v_secret from app_secrets where key='cred_db_internal';
  -- Resolved defensively: a trigger on the Terms-acceptance path must never refuse the signature.
  begin
    v_ref := public.qd_project_ref();
  exception when others then
    v_ref := null;
  end;
  if v_ref is not null then
    perform net.http_post(
      'https://' || v_ref || '.supabase.co/functions/v1/compliance_archive',
      jsonb_build_object('__secret', v_secret, 'action','sign','kind','customer','email', NEW.email),
      '{}'::jsonb, '{"Content-Type":"application/json"}'::jsonb, 60000);
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.qd_sign_supplier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_secret text; v_ref text;
begin
  select value into v_secret from app_secrets where key='cred_db_internal';
  -- Resolved defensively: a trigger on the Terms-acceptance path must never refuse the signature.
  begin
    v_ref := public.qd_project_ref();
  exception when others then
    v_ref := null;
  end;
  if v_ref is not null then
    perform net.http_post(
      'https://' || v_ref || '.supabase.co/functions/v1/compliance_archive',
      jsonb_build_object('__secret', v_secret, 'action','sign','kind','supplier','email', NEW.claimed_by),
      '{}'::jsonb, '{"Content-Type":"application/json"}'::jsonb, 60000);
  end if;
  return NEW;
end $function$


CREATE OR REPLACE FUNCTION public.recompute_supplier_rating(p_supplier bigint)
 RETURNS void
 LANGUAGE sql
 SET search_path TO 'public'
AS $function$
  update public.leads l set
    app_rating  = (select round(avg(rating)::numeric, 2) from public.reviews r where r.supplier_id = p_supplier),
    app_reviews = (select count(*)::int from public.reviews r where r.supplier_id = p_supplier)
  where l.id = p_supplier;
$function$


CREATE OR REPLACE FUNCTION public.registered_supplier_count()
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(max(founding_rank), 0)::int from public.leads
$function$


CREATE OR REPLACE FUNCTION public.reveal_fee(amount numeric, at_time timestamp with time zone DEFAULT now())
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  -- 6 Sep 2026: no discount, no promo, no cap (founder). at_time is kept so callers need no change;
  -- it no longer selects a rate because there is only one rate.
  select case when amount is null or amount <= 0 then 0
              else round(amount * (select c.standard_reveal_rate from public.pricing_config c where c.id = 1), 2)
         end
$function$


CREATE OR REPLACE FUNCTION public.rl_check(p_key text, p_limit integer, p_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n int;
begin
  delete from rl_hits where at < now() - (p_seconds || ' seconds')::interval and k = p_key;
  select count(*) into n from rl_hits where k = p_key and at > now() - (p_seconds || ' seconds')::interval;
  if n >= p_limit then return false; end if;
  insert into rl_hits(k) values (p_key);
  return true;
end $function$


CREATE OR REPLACE FUNCTION public.scrub_inquiry_contacts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare changed boolean := false; v_name text;
begin
  new.summary_masked      := public.mask_project_identity(public.mask_contacts(new.summary));
  new.raw_input_masked    := public.mask_project_identity(public.mask_contacts(new.raw_input));
  new.budget_masked       := public.mask_project_identity(public.mask_contacts(new.budget));
  new.spec_masked         := public.mask_project_identity_jsonb(public.mask_contacts_jsonb(new.spec));
  new.boq_masked          := public.mask_project_identity_jsonb(public.mask_contacts_jsonb(new.boq));
  new.completeness_masked := public.mask_project_identity_jsonb(public.mask_contacts_jsonb(new.completeness));

  if new.customer_id is not null then
    begin
      select nullif(btrim(c.full_name), '') into v_name from public.customers c where c.id = new.customer_id;
    exception when others then v_name := null; end;
    if v_name is not null then
      new.summary_masked   := public.mask_name(new.summary_masked, v_name);
      new.raw_input_masked := public.mask_name(new.raw_input_masked, v_name);
      new.budget_masked    := public.mask_name(new.budget_masked, v_name);
    end if;
  end if;

  changed := (new.summary_masked is distinct from new.summary)
          or (new.raw_input_masked is distinct from new.raw_input)
          or (new.budget_masked is distinct from new.budget)
          or (new.spec_masked is distinct from new.spec)
          or (new.boq_masked is distinct from new.boq)
          or (new.completeness_masked is distinct from new.completeness);
  if changed then
    begin
      insert into public.founder_alerts(level, event, detail, channel)
      values ('warn', 'inquiry_contact_masked',
        'Masked customer contact details and/or project identity (consultant, client, building, '
        || 'location, plot, drawing numbers) in the supplier-facing copy of inquiry '
        || coalesce(new.id::text, '?') || ' from customer ' || coalesce(new.customer_id::text, '?') || '.',
        'system');
    exception when others then null; end;
  end if;
  return new;
end $function$


CREATE OR REPLACE FUNCTION public.scrub_quote_contacts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare changed boolean := false;
begin
  if new.notes         is distinct from public.mask_contacts(new.notes)         then new.notes         := public.mask_contacts(new.notes);         changed := true; end if;
  if new.scope         is distinct from public.mask_contacts(new.scope)         then new.scope         := public.mask_contacts(new.scope);         changed := true; end if;
  if new.conditions    is distinct from public.mask_contacts(new.conditions)    then new.conditions    := public.mask_contacts(new.conditions);    changed := true; end if;
  if new.exclusions    is distinct from public.mask_contacts(new.exclusions)    then new.exclusions    := public.mask_contacts(new.exclusions);    changed := true; end if;
  if new.payment_terms is distinct from public.mask_contacts(new.payment_terms) then new.payment_terms := public.mask_contacts(new.payment_terms); changed := true; end if;
  if new.warranty      is distinct from public.mask_contacts(new.warranty)      then new.warranty      := public.mask_contacts(new.warranty);      changed := true; end if;
  if new.lead_time     is distinct from public.mask_contacts(new.lead_time)     then new.lead_time     := public.mask_contacts(new.lead_time);     changed := true; end if;
  if new.validity      is distinct from public.mask_contacts(new.validity)      then new.validity      := public.mask_contacts(new.validity);      changed := true; end if;
  if changed then
    begin
      insert into public.founder_alerts(level, event, detail, channel)
      values ('warn', 'quote_contact_masked',
              'Masked off-platform contact details in quote for inquiry '||coalesce(new.inquiry_id::text,'?')||' from supplier '||coalesce(new.supplier_id::text,'?')||'.',
              'system');
    exception when others then null; end;
  end if;
  return new;
end;
$function$


